    [4463] = {
        title = "Трактат роздумів",
        description = "Подай складники, смертний.\n\nЩе я вимагатиму плати — тридцять золотих за цей виріб.",
    },
    [4464] = {
        title = "Зіпсована піснецвітка",
        description = "Ти натрапив на хворобливий, зіпсований кущ, що скидається на рослину «пісенна квітка». Від нього йде різкий, нездоровий сморід. Аби повернути її до нормального стану, потрібен негайний догляд.",
    },
    [4465] = {
        title = "Зіпсована піснецвітка",
        description = "Ти натрапив на хворобливий, зіпсований кущ, що скидається на рослину «пісенна квітка». Від нього йде різкий, нездоровий сморід. Аби повернути її до нормального стану, потрібен негайний догляд.",
