    [8747] = {
        title = "Шлях Захисника",
        progress = "Вражає, малече. Тобі довелося чимало пройти, щоб здобути прихильність Бронзової Зграї. Твою відданість помічено.\n\nПерстень-печатка захисника забезпечить надійний захист від сил зла.\n\nАле затям: щойно обереш свій шлях — вороття не буде, навіть якщо передумаєш.",
        completion = "Вражає, малече. Тобі довелося чимало пройти, щоб здобути прихильність Бронзової Зграї. Твою відданість помічено.\n\nПерстень-печатка захисника забезпечить надійний захист від сил зла.\n\nАле затям: щойно обереш свій шлях — вороття не буде, навіть якщо передумаєш.",
    },
    [8748] = {
        title = "Шлях Захисника",
        description = "Твою невпинну оборону дітей Калімдору відзначено. Передай мені свій перстень-печатку, щоб я міг посилити його могуть.",
    },
    [8749] = {
        title = "Шлях Захисника",
        description = "Ти робиш честь моєму роду, {name}. Скрушуй ворогів Калімдору! Покажи їм, що означає опоганити край вічного зоряного сяйва.\n\nТи заслужив ще одне посилення. Передай мені свій перстень-печатку, щоб я зміцнив його могуть.",
    },
    [8750] = {
        title = "Шлях Захисника",
        description = "Відданість такого розмаху — велика рідкість. Ти довів, що твоя воля незламна, {name}. За невсипущу варту над нашим світом тебе щедро винагородять.\n\nПередай мені свій перстень-печатку, щоб я посилив його чари.",
    },
    [8751] = {
        title = "Захисник Калімдору",
        description = "Ніколи я не бачив такої завзятості! Бронзовий рій дарує тобі останнє чарування. Цього забажав сам Позачасовий!\n\nДай мені свій перстень-печатку, щоб я зробив потрібні зміни.",
    },
    [8752] = {
        title = "Шлях завойовника",
        progress = "Вражає, малече. Тобі довелося чимало пройти, щоб здобути прихильність Бронзової Зграї. Твою відданість помічено.\n\nПерстень-печатка завойовника значно посилить твої фізичні атаки.\n\nАле затям: щойно обереш свій шлях — вороття не буде, навіть якщо передумаєш.",
        completion = "Вражає, малече. Тобі довелося чимало пройти, щоб здобути прихильність Бронзової Зграї. Твою відданість помічено.\n\nПерстень-печатка завойовника значно посилить твої фізичні атаки.\n\nАле затям: щойно обереш свій шлях — вороття не буде, навіть якщо передумаєш.",
    },
    [8753] = {
        title = "Шлях завойовника",
        description = "Твою невпинну оборону дітей Калімдору помічено. Дай мені свій перстень-печатку, щоб я підсилив його могуть.",
    },
    [8754] = {
        title = "Шлях завойовника",
        description = "Ти робиш честь моєму роду, {name}. Скрушуй ворогів Калімдору! Покажи їм, що означає сплюндрувати землю вічного зоряного сяйва.\n\nТи заслужив ще одне підсилення. Дай мені свій перстень-печатку, щоб я зміцнив його силу.",
    },
    [8755] = {
        title = "Шлях завойовника",
        description = "Відданість такого розмаху — велика рідкість. Ти довів, що воля твоя непохитна, {name}. Тебе щедро винагородять за невсипущу варту над нашим світом.\n\nДай мені свій перстень-печатку, щоб я зміцнив його чарування.",
    },
