    [24822] = {
        title = "Зміна серця",
        description = "Ти прагнеш змінити шлях, яким ідеш, {name}?",
    },
    [24823] = {
        title = "Шлях руйнування",
        description = "Ти прагнеш і далі йти шляхом руйнування?",
    },
    [24824] = {
        title = "Розтривожена земля",
        description = "Ми тут, щоб наглядати за шрамами цієї землі й виглядати нових ознак нестабільності. Поки що ми жодної не помітили, але повторний поштовх Катаклізму міг би спустошити Степи ще дужче.\n\nНа північному сході, біля провалля, шаленіють некеровані земляні елементалі. Щоб утишити землю, їх час від часу треба знищувати, а їхню сутність повертати їй у обряді. Якщо допоможеш нам у цьому, {class}, я радо тебе винагороджу.",
    },
    [24825] = {
        title = "Шлях мудрості",
        description = "Ти прагнеш і далі йти шляхом мудрості?",
    },
    [24826] = {
