    [35869] = {
        title = "ЦІЛА ГОРА уламків артефактів",
        description = "Стільки, скільки зможеш унести.",
    },
    [35870] = {
        title = "Винищувач базилісків",
        description = "Базиліск — одна з улюблених страв Ніші. Тут вона полює, і саме так ці виродки із Залізної Орди, мабуть, зуміли її схопити.\n\nНавіщо їм було завдавати собі стільки клопоту, щоб приборкати її в такий спосіб? Можливо, разом ми з тобою знайдемо відповідь, караючи їх за їхні злодіяння.\n\nА поки що Ніші потрібна їжа. Поки я доглядаю за нею, чи не пополюєш ти замість неї?",
    },
    [35871] = {
        title = "Кілька уламків артефактів",
        description = "Кожна дрібниця має значення.",
    },
    [35872] = {
        title = "Жменя уламків артефактів",
        description = "Що більше, то краще!",
    },
    [35873] = {
        title = "ЦІЛА ГОРА уламків артефактів",
        description = "Стільки, скільки зможеш унести.",
    },
    [35876] = {
        title = "Гарнізонна кампанія: гніздо Темного Припливу",
        description = "Нам надходять звістки, що бойові кораблі Залізної Орди стають на якір біля маленького острова на південь від долини Тіньового Місяця.\n\nМи відправили розвідників, але вони ще не повернулися. Треба все розвідати.\n\nБрон Скайгорн тримає для тебе ріклака напоготові, коли будеш готовий, командире.",
        objectives = "Вирушай до Гнізда Темного Прибою.",
        completion = "Ці дикуни не мають честі. Час розібратися з присутністю Залізної Орди на цьому острові.",
    },
    [35878] = {
        title = "Заходи безпеки",
        description = "Як виявилося, резонансна частота батарей добряче розлютила тутешню звірину. Я... здається, один із вепрів щойно глянув на мене й облизнувся.\n\nЯ щедро тобі віддячу, якщо ти просто... позбудешся всього, що там унизу трапиться на шляху. Байдуже, що це, просто вбий його, гаразд?",
    },
    [35879] = {
        title = "Заходи безпеки",
        description = "Батареї, які я загубив у болоті, добряче розлютили диких створінь. Забрати їх звідти, не пробившись крізь хтозна-що, буде неможливо.\n\nЯкщо ти не проти, чому б тобі не «подбати» про всіх тварюк, що трапляться на шляху? Не хочу, щоб якась велетенська бестія вистежила мене аж до місця розкопок.\n\nТи про це не пошкодуєш.",
    },
    [35880] = {
        title = "Лють і мудрість",
        description = "Звірі західної пустки ведуть нескінченну війну зі створіннями східних нетрів.\n\nЯкщо один бік здолає інший, увесь Дренор буде приречений під рукою переможця.\n\nЛеґіон Реготливого Черепа прагне помсти за своє знищене селище. Я скерував їхню лють на тутешніх створінь, щоб уберегти наш аванпост.\n\nЯкщо твоя ласка, командире, нагляньте за їхніми діями. Я ще не навчився довіряти Реготливому Черепу.",
    },
    [35881] = {
        title = "Руїни Першого Бастіону",
    },
    [35882] = {
        title = "Намір Бруто",
        description = "Ти зробив мені велику послугу. Цей клинок твій так само, як і мій.\n\nЯ даю тобі цю криваву клятву: я служитиму твоїй справі й віддам твоїм військам своє знання клинків і гірничої справи.\n\nЧи приймаєш ти її?",
    },
    [35883] = {
        title = "Кулаки Ваандаама",
        description = "Ти зробив мені велику послугу. Цей клинок твій так само, як і мій.\n\nЯ даю тобі цю криваву клятву: я служитиму твоїй справі й віддам твоїм військам своє знання клинків і гірничої справи.\n\nЧи приймаєш ти її?",
    },
    [35884] = {
        title = "Останній ривок",
        description = "Якщо раніше вони не лютували, то тепер лютують напевно. Ми й хвилини не протримаємося тут, нагорі цього танка!\n\nПриєднаймося до решти й тікаймо звідси!!",
        objectives = "Утечи до доків.",
        completion = "Попри все, ми тут. Досі живі, а на п'ятах ціле військо.\n\nНаш корабель чекає. Вирушаймо?",
    },
