    [36502] = {
        title = "Трофей слави: Біоланта",
        description = "Перемога над Біолантою принесла тобі трофей, гідний того, щоб виставити його напоказ на твоєму форпості. \n\nПовернися з ним до Мараада, щоб примножити свою славу!",
    },
    [36503] = {
        title = "Трофей слави: Біоланта",
        description = "Перемога над Біолантою принесла тобі трофей, гідний визнання.\n\nВіднеси його до Дуротана у Звіриній Варті.",
