    [43635] = {
        title = "Заради багатьох",
        description = "[ЦЕ ТИМЧАСОВЕ ЗАВДАННЯ, ЩОБ ПЕРЕНЕСТИ ТЕБЕ ДО ДАЛАРАНА НА РОЗБИТИХ ОСТРОВАХ.]\n\nБудь ласка, скористайся цим порталом до Даларана на Розбитих островах і розпочни своє завдання з артефактом!",
    },
    [43637] = {
        title = "Аркавія: Засмічений Стік",
