    [43723] = {
        title = "Чемпіонка: Таоші",
        completion = "Це честь понад усякі слова, {NAME}. Я радо служитиму твоєю чемпіонкою.\n\nПросто вкажи напрямок. Я проберуся будь-куди. Вивідаю будь-що.",
    },
    [43724] = {
        title = "Чемпіон: Майстер Матіас Шоу",
        completion = "Може, укладемо союз — ти і я? Звісно, офіційно я не наважуся пристати до Некоронованих, а тим паче до Ради Тіней.\n\nЯ ж усе-таки очільник SI:7.\n\nАле коли знадобиться моя допомога чи порада — досить лише попросити. Я буду поруч. Працюватимемо разом таємними каналами, щоб Палаючий Легіон було знищено.",
    },
    [43726] = {
        title = "Оповіді Розбитих островів",
        description = "Гей, $p(друже:подруго), що це? Книга?",
