    [43786] = {
        title = "Набридливі гнізда",
    },
    [43797] = {
        title = "Допомога Конклаву",
        description = "Жерці Конклаву — грізні союзники. Спільними силами ми, можливо, таки матимемо шанс убити жахолорда назавжди.\n\nПередай Алонсу Фаолу, що ми будемо поруч і готові битися, коли ти нас потребуватимеш.",
    },
    [43798] = {
        title = "НЕБЕЗПЕКА: Косумот Голодний",
    },
    [43801] = {
        title = "Дай їм прочухана",
    },
    [43802] = {
