    [43916] = {
        title = "Нічна Цитадель: Головний ботанік Тел'арн",
        description = "Нічнонароджені вправні не в одному виді магії, і всередині стін Нічної Фортеці нас, найпевніше, чекають грізні вороги. Їхні наймогутніші маги й воїни мають полягти, перш ніж ми зможемо стати проти Ґул'дана.",
    },
    [43917] = {
        title = "Нічна Цитадель: Елісанда",
        description = "Колись давно Велика магістрикс Елісанда виступила проти Легіону й кинула виклик самій королеві Азшарі. Тисячоліття, що минули, змінили думку Елісанди й перетворили її на союзницю демонів. Настав час стати проти неї.",
    },
    [43918] = {
