    [44581] = {
        title = "Додамо вогника",
        objectives = "Зустрінься з Номі в Даларані.",
        completion = "Агов, {NAME}, це я, Номі. Ну, з Пандарії, пам'ятаєш?\n\nНічого, якщо не пригадуєш — ми ж бачилися хтозна-коли.\n\nЯ тепер повноправний кухар і вигадую власні страви.\n\nОсь, скуштуй дещо з рецептів і наїдків, над якими я працював.",
    },
    [44582] = {
        title = "Опоганьте це вогнище!",
        completion = "Опоганьте вогнище Альянсу в долині Тіньового Місяця!",
    },
    [44583] = {
        title = "Опоганьте це вогнище!",
        completion = "Опоганьте вогнище Орди на Хребті Морозного Вогню!",
