    [45007] = {
        title = "Дружба з гострокогтем",
        description = "<Твоє пташеня гострокогтя інстинктивно вбігає на кухню будь-якої корчми, куди ти заходиш, і влаштовує безлад серед каструль і сковорідок. Воно любить залазити в будь-який посуд, що трапляється під лапу, особливо в брудний. Можливо, ти стримаєш цю поведінку, якщо знайдеш для нього власний посуд.>",
        objectives = "Купи Брудну Ложку в Мел Лінхен у Даларані для свого пташеняти гострокогтя.",
        progress = "<Твоє пташеня гострокогтя допитливо дивиться на тебе.>",
        completion = "<Ти відчуваєш, як між тобою і пташеням зароджується особливий зв'язок. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45008] = {
        title = "Дружба з кривавозором",
        description = "<Твоє пташеня кривавозора, схоже, обожнює качатися в квітах. Ти припускаєш, що любов до квітучих рослин колись допомагала зграї знаходити плоди для харчування. Воно неабияк зрадіє, якщо матиме власну особливу квітку!>",
        objectives = "Купи Пурпурову Квітку в Ееріт Примроуз у Даларані для свого пташеняти кривавозора.",
        progress = "<Твоє пташеня кривавозора допитливо дивиться на тебе.>",
        completion = "<Ти відчуваєш, як між тобою і пташеням зароджується особливий зв'язок. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45009] = {
        title = "Урок полювання: рудий кільцехвіст",
        description = "<Твоє пташеня гострокогтя потоваришувало з кількома іншими летючими улюбленцями. Зграя, схоже, прагне пополювати на єнотів Вал'шари.>",
        objectives = "Здолай 3 рудих кільцехвости у Вал'шарі зі своїм пташеням гострокогтя і 2 летючими улюбленцями.",
        completion = "<Пташеня смикає за кіготь, що сходить, — скоро він знову буде гострим. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45010] = {
        title = "Урок полювання: юний шкряботрус",
        description = "<Твоє пташеня кривавозора потоваришувало з кількома іншими летючими улюбленцями. Зграя, схоже, прагне пополювати на крабів Азсуни.>",
        objectives = "Здолай 3 юних шкряботруси в Азсуні зі своїм пташеням кривавозора і 2 летючими улюбленцями.",
        completion = "<Пташеня зализує рани — поранене, але задоволене. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45011] = {
        title = "Урок співпраці: Дресарон",
        description = "<Твоє пташеня гострокогтя, схоже, не надто цікавиться твоїми іншими улюбленцями і здебільшого ігнорує їх під час бою. Можливо, допоможе добрий приклад командної роботи.>",
        objectives = "Здолай Дресарона в Гущавині Темносердя у Вал'шарі зі своїм пташеням гострокогтя.",
        completion = "<Пташеня має виснажений вигляд і одразу засинає. Схоже, йому сниться якийсь жах. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45012] = {
        title = "Урок співпраці: Серпентрікс",
        description = "<Хоч ви й перемогли, твоє пташеня кривавозора відволікало інших твоїх улюбленців у вирішальні моменти бою. Можливо, допоможе добрий приклад командної роботи.>",
        objectives = "Здолай Серпентрікс в Оці Азшари в Азсуні зі своїм пташеням кривавозора.",
        completion = "<Пташеня ледь помітно світиться магічною енергією — у що це воно вплуталося? Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45013] = {
        title = "Урок полювання: долинний пурхун",
        description = "<Твоє пташеня гострокогтя вперто відмовляється підходити до будь-якої водойми, скрегочучи й шкрябаючи землю щоразу, коли ти $p(сам:сама) заходиш у воду. Можливо, спільна робота з водяними улюбленцями допоможе йому подолати цей страх. А спільне полювання на нову здобич, яку воно почало вистежувати, може дати раду цій справі.>",
        objectives = "Здолай 3 долинних пурхунів у Вал'шарі зі своїм пташеням гострокогтя і 2 водяними улюбленцями.",
        completion = "<Пташеня тепер почувається значно спокійніше біля води. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45014] = {
        title = "Урок полювання: павук Скверни",
        description = "<Щоразу, коли ти зупиняєшся в корчмі, твоє пташеня видирається на меблі й відмовляється торкатися підлоги. Воно непевно стрибає з предмета на предмет, часто влаштовуючи неабиякий безлад. Ти пригадуєш, що причиною може бути неприємний досвід із блохами. Спільне полювання на нову здобич разом із кількома улюбленцями-звірятками може допомогти йому подолати цей страх.>",
        objectives = "Здолай 3 павуків Скверни в Азсуні зі своїм пташеням кривавозора і 2 улюбленцями-звірятками.",
        completion = "<Пташеня тепер почувається значно спокійніше біля комах. Йому знадобиться час, щоб оговтатися після цієї пригоди.>",
    },
    [45015] = {
        title = "Урок співпраці: Ксавій",
        description = "<Твоє пташеня гострокогтя взяло за звичку ховатися в твоїй торбі, коли ти наближаєшся до дуже могутніх істот цього світу. Воно мусить навчитися зберігати спокій під тиском, навіть стикаючись із найтемнішими з кошмарів. Можливо, допоможе епічний приклад командної роботи проти грізного ворога.>",
        objectives = "Здолай Ксавія у Смарагдовому Кошмарі, маючи при собі Гостропазуре Пташеня.",
        completion = "<Пташеня несміливо на тебе дивиться. Схоже, воно трохи боїться твоєї сили. Йому знадобиться час, щоб оговтатися від цієї пригоди.>",
    },
    [45016] = {
        title = "Урок командної гри: Скорпірон",
        description = "<Твоє кровозорче пташеня гарчить і сичить на великих звірів, неначе зовсім не дбаючи про власну безпеку. Йому треба навчитися покладатися на силу числа, щоб уберегтися. Можливо, допоможе, якщо показати йому епічний приклад командної гри проти величезного звіра.>",
        objectives = "Здолай Скорпірона в Нічній Цитаделі, маючи при собі Кровозоре Пташеня.",
        completion = "<Пташеня замислено жує уламок велетенського скорпіона. Йому знадобиться час, щоб оговтатися від цієї пригоди.>",
    },
    [45017] = {
        title = "Бойова злагода з гостролапом",
        description = "<Здається, твоє гостролапе пташеня готове об'єднатися з тобою для ще одного раунду боїв і показати все, чого навчилося про командну гру. Командувати ним поряд із новими союзниками було б чудовою перевіркою його вмінь.>",
        objectives = "Виконай 3 світові завдання з боями улюбленців, маючи Гостропазуре Пташеня і 2 магічних улюбленців.",
        completion = "<Пташеня має виснажений вигляд і кілька хвилин п'є після перемоги. Йому знадобиться час, щоб оговтатися від цієї пригоди.>",
    },
    [45018] = {
        title = "Бойова злагода з кровозорцем",
        description = "<Здається, твоє кровозорче пташеня готове об'єднатися з тобою для ще одного раунду боїв і показати все, чого навчилося про командну гру. Командувати ним поряд із новими союзниками було б чудовою перевіркою його вмінь.>",
        objectives = "Виконай 3 світові завдання з боями улюбленців, маючи Кровозоре Пташеня і 2 улюбленців-звірів.",
        completion = "<Пташеня має доволі ситий вигляд. Що воно з'їло? Йому знадобиться час, щоб оговтатися від цієї пригоди.>",
    },
    [45019] = {
        title = "Возз'єднання гостролапа",
        description = "<Твоє гостролапе пташеня останнім часом не їсть. Воно немовби пригнічене. Можливо, настав час повернути його туди, де воно народилося?>",
        objectives = "Поверни Гостропазуре Пташеня на Зелені Кручі у Вал'шарі.",
        completion = "<Матріарх гостропазурих вдячно видає могутнє кряктання. Як її дитя приєдналося до твоєї зграї, так і вона піде за тобою як за новим ватажком, тепер, коли ти здобув її довіру.>",
    },
    [45020] = {
        title = "Возз'єднання кровозорця",
        description = "<Твоє кровозорче пташеня відмовляється пити. Воно немовби пригнічене. Можливо, настав час повернути його туди, де воно народилося?>",
        objectives = "Поверни Кровозоре Пташеня в Дельту Аллуванона в Азсуні.",
        completion = "<Матріарх кровозорих знову з'єднується зі своїм пташеням, ховаючи його під крилом. Як її дитя приєдналося до твоєї зграї, так і вона піде за тобою як за новим ватажком, тепер, коли ти здобув її довіру.>",
    },
    [45021] = {
        title = "Невідомі відповіді",
        description = "Ти помітив зміну в поведінці Джубеки? Знаю, вона не найтепліша з чорнокнижниць, але боюся, останнім часом вона замкнулася в собі ще більше, ніж зазвичай.\n\nГадаю, її думки крутяться навколо Канретада, колишнього очільника ради. Джубека твердо стояла на тому, щоб тримати його у вигнанні, аж доки Палаючий Легіон не взяв її в полон.\n\nЙого доля невідома, і це вочевидь непокоїть нашу подругу. Останнє, що вона мені сказала, — що відчуває його присутність в Азсуні. Не дай їй пройти цей шлях самотужки.",
    },
    [45024] = {
        title = "Винищення культу",
        description = "Принада Канретада сильна. Навіть коли його немає в цьому світі, є ті, хто будь-якою ціною прагне бути поруч із ним, сподіваючись долучитися до його сили.\n\nГурт цих фанатиків отут, у Фаронаарі, невтомно працює над тим, щоб повернути Канретада, — я дізнався про це від свого бранця.\n\nМи не можемо дозволити їм досягти успіху, {name}. Знайди їхнє лігво й убий якомога більше з них.\n\nЯ лишуся тут і подивлюся, що ще зможу дізнатися про їхні наміри.",
    },
    [45025] = {
        title = "Викрадення джерела сили",
        description = "Мій бранець доволі балакучий, {name}. Він каже, що культ Зеленого Полум'я використовує енергію Скверни, щоб живити свої спроби повернути Канретада з вигнання.\n\nУ своєму лігві вони заряджають кристали Скверни, здатні вмістити велику кількість магії Скверни. Без належної сили для свого ритуалу окультистам буде непросто впоратися зі своїм завданням.\n\nВикради їхні кристали Скверни, але не знищуй їх. Для чогось такого потужного ми завжди знайдемо застосування.",
    },
    [45026] = {
        title = "Витрата енергії Скверни",
        description = "Невдовзі вигнання Канретада спаде, і він повернеться до нашого світу.\n\nМи повинні будь-якою ціною вберегти його й його силу від рук Легіону.\n\nЯкщо мій давній друг ще десь там, усередині, можливо, ми зможемо його повернути.\n\nКристали, які ти здобу$p(в:ла), живляться енергією Скверни. Ми можемо використати ці ненаситні кристали, щоб висмоктати магію, що пожирає Канретада.\n\nАле спершу їхню силу треба вичерпати. Для цього тобі доведеться скористатися силою кристалів і вбити їхньою енергією демонів.",
    },
    [45027] = {
        title = "До Зламаного берега",
        description = "Схоже, спотворені послідовники Канретада почали свій ритуал на Розбитому узбережжі.\n\nМи мусимо діяти швидко. Не можна дозволити Палаючому Легіону використати Канретада як свою зброю.\n\nУ нас напоготові аколіти, готові провести ритуал виклику на Розбитому узбережжі, щойно ти будеш готовий.",
    },
    [45028] = {
        title = "Доля Канретада",
        description = "Я відчуваю його присутність, повелителю Нижнього світу! Канретад тут! Його послідовники розбили табір у сусідньому перевалі й просто зараз проводять ритуал, щоб повернути його.\n\nШвидше, візьми кристали Скверни. Розстав їх колом навколо Канретада.\n\nЯкщо розмістити правильно, кристали з'єднаються між собою й почнуть висмоктувати енергію Скверни.\n\nА тепер іди, доки не пізно!",
    },
    [45030] = {
        title = "Кістка, гравірована Скверною",
        description = "<Кістка вкрита складними рунами, врізаними просто в поверхню тим, що може бути лише потужною магією Скверни.>\n\n<Безперечно, когось із Кірін-Тор у Даларані це зацікавило б.>",
    },
    [45032] = {
        title = "Як вітер",
    },
    [45033] = {
        title = "Камінь Пекла",
        description = "<Для недосвідченого ока це лише ще один уламок Скверни, але ти впізнаєш у цьому камені один із каталізаторів, якими пришвидшують відновлення найсильніших воїнів Легіону в Нижньому світі.>\n\n<Що він робить на Азероті, незрозуміло. Можливо, Кірін-Тор у Даларані допоможе тобі дізнатися більше?>",
    },
    [45034] = {
        title = "Вогонь з гармат!",
        description = "Знадобиться щось більше за нещасну корабельну аварію, щоб мене здолати. Ці перерослі, смердючі від блювотиння демонські лантухи Скверни ще здивуються, якщо думають, що цього досить, аби мене спинити.  \n\n<Кішан випльовує морську воду й витирає рота рукавом.>\n\nЕх... Хоча невеличкий перепочинок мені б не завадив. Ось, візьми цю сигнальну ракетницю й виклич артилерійські удари по пляжу. Спусти пекло на цих нікчемних виплодків з козлячими ногами, а я зустріну тебе на базі, коли місію буде виконано!",
    },
    [45035] = {
        title = "Поклик битви",
    },
    [45036] = {
        title = "Асґрім Згуба Жаху",
        description = "Дух одного з наших найшанованіших воїнів зник із Залів Доблесті.\n\nАсґрім Згуба Жаху був великим воєначальником і королем. Століттями його дух перебував на належному місці в Залах Доблесті... аж до недавнього часу.\n\nНезліченні роки тому кістки Згуби Жаху поховала його бойова ватага неподалік звідси. Там ми й шукатимемо відповіді.\n\nЗатруби в Ріг Одіна над місцем поховання й виклич його дух перед нами.",
    },
    [45037] = {
        title = "Медальйон Елдре'Таласа",
        description = "<Обережно відкривши медальйон, ти знаходиш портрет королеви Азшари, цілком викладений із коштовного каміння.>\n\n<Такі речі високорідних трапляються рідко, і знайти одну з них у такому бездоганному стані в руках Легіону вкрай тривожно.>\n\n<Ти знаєш, що Кірін-Тор у Даларані, можливо, розповість тобі більше.>",
    },
    [45043] = {
        title = "Сяйлива пелюстка кривавого будяка",
        description = "<Знайти кривавий будяк за межами земель ельфів крові надзвичайно рідко, а тим паче таку свіжу пелюстку, як ця.>\n\n<Можливо, Легіон просто забрав її в загиблого бійця, але таке пояснення видається аж надто зручним.>\n\n<Ти гадаєш, що Кірін-Тор у Даларані, ймовірно, зацікавиться цим.>",
    },
    [45044] = {
        title = "Більше не зброя",
        description = "Спис, який ти знайш$p(ов:ла), безперечно має ознаки тролського ремесла, що трапляються в інших ковальських виробах.\n\nМожливо, хтось в одному з таборів тут, в Ун'Ґоро, знатиме про нього більше.",
    },
    [45045] = {
        title = "Фіал прадавньої мани",
        description = "<Придивившись уважніше, ти бачиш, що цей фіал наповнений водою з місячного колодязя, добре відомою своїми потужними арканними властивостями.>\n\n<Цікаво, що її, схоже, не осквернив попередній власник. Хоча це мало б заспокоювати, натомість лише викликає підозри щодо її походження.>\n\n<Хтось серед Кірін-Тор у Даларані напевно зацікавиться цим.>",
    },
    [45046] = {
        title = "Як вітер",
    },
    [45047] = {
        title = "Як вітер",
    },
    [45048] = {
        title = "Як вітер",
    },
    [45049] = {
        title = "Як вітер",
    },
    [45050] = {
        title = "Плани проникнення",
        description = "Хоч текст важко розібрати і він укритий демонічними рунами, схоже, це плани проникнення в Даларан. Рада Шести захоче це побачити.",
    },
    [45051] = {
        title = "Зворотне ковальство",
        description = "А я ж думав, що ніколи більше не побачу цю штукенцію!\n\nЩоправда, вона вже не така, як була. Ох, мон, матиму великі неприємності, якщо з'явлюся з нею в руках.\n\nГадаєш, ти зміг би допомогти мені її полагодити? Планів на неї в мене нема, бо, бачиш, першої ж ночі тут наскочили створіння й покрали всі мої речі.\n\nТо що скажеш? Виручиш брата?\n\nДумаю, якщо ти зможеш з'ясувати, з чого вона зроблена, то полагодиш її, а я запишу подробиці, як її роблять.",
    },
    [45052] = {
        title = "Виснажений кристал Нижнього світу",
        description = "Цей кристал схожий на щось, що використовують у ритуалах темної магії. Зважаючи на те, що його енергія вичерпана, той, кому він належить, мабуть, досяг успіху в тому ритуалі, який проводив.\n\nМаги Кірін-Тор, найпевніше, зацікавляться його вивченням.",
    },
    [45053] = {
        title = "Вказівки злодія",
        description = "Поспіхом надряпана записка свідчить:\n\n«Мені потрібна Райдужна Лінза для одного з моїх заклять. Доведи, що ти справді найкращий з-поміж моїх учнів, і принеси її мені.\n\nО, і пильнуй, щоб ця записка ніде не валялася, аби якийсь шукач пригод її не знайшов!»\n\nЯкщо хтось хоче викрасти Райдужну Лінзу, Кірін-Тор, найпевніше, захоче про це знати.",
    },
    [45054] = {
        title = "«Прадавні» ельфійські воєнні накази",
        description = "Ці накази мають офіційний вигляд і несуть на собі печатку Ворона, але вони надто нові. До того ж по краях ледь помітно мерехтить магія Скверни.\n\nРада Шести зацікавилася б цим.",
    },
    [45055] = {
        title = "Скуштувати власних ліків",
        description = "Я вже якийсь час сиджу в цьому таборі й точно знаю, що всі ті матеріали можна знайти просто тут, в Ун'Горо.\n\nНастав час відплатити тутешнім тварюкам. Забери в них те саме, що вони забрали в мене! Зробиш для мене хоч це, га, $p(друже:подруго)?\n\nА я просто почекаю тут, поки ти повернешся з усім добром.",
    },
    [45056] = {
        title = "Норесса",
        description = "Вона досі там, {name}. Норесса, моя дружина.\n\nВона на Променаді, поки ми чекаємо тут, готуючись до удару. Хтозна, що з нею сталося?\n\nПрошу тебе, $p(друже:подруго), я боюся найгіршого. Скажи їй, що назовні ще є надія.\n\nУ нас був маленький будинок на півдні Великої Променади, біля водних садів. Вона, мабуть, переховується там посеред цього божевілля.",
    },
    [45057] = {
        title = "Врятувати свою голову",
        description = "Бачу, що ти коваль, тож подумав: краще буде, якщо спис зробиш ти. Можеш скористатися цією кузнею, щоб зробити все потрібне.\n\nА я почну записувати те, що ти робиш, і тоді в нас буде і спис, і рецепт!",
    },
    [45058] = {
        title = "Звільніть вартових!",
    },
    [45059] = {
        title = "Уламок тотема, насичений Скверною",
        description = "Схоже, це уламок реліквії або тотема з Високогір'я. Він моторошно сяє силою Скверни. Це треба негайно віднести Раді Шести в Даларані!",
    },
    [45060] = {
        title = "Пошкоджений знак Кірін-Тор",
        description = "Хоч би його загубили, хоч би вкрали, дивно, що демон володіє знаком Кірін-Тор.\n\nРаду Шести, без сумніву, зацікавить ця знахідка.",
    },
    [45061] = {
        title = "Сувої Фалдроттін",
        description = "Хоч украй дивно вже те, що демон носив сувій врайкульських письмен, ще цікавіший його зміст.\n\nЗаписи, схоже, посилаються на врайкульське пророцтво про того, хто об'єднає Тайдскорнів проти Палаючого Легіону. Цю звістку слід негайно передати Раді Шести.",
    },
    [45062] = {
        title = "Опір під час арешту",
        description = "Твої знахідки не розчаровують, {name}.\n\nПрямуй до двигуна душ і скористайся нашою щойно здобутою зброєю, щоб розібрати джерело живлення.",
    },
    [45063] = {
        title = "Досліди над Сквернодушими",
        description = "Влада Андаріса над Згаслими — справжня загроза. Якщо ми хочемо посилити опірність Згаслих до цих впливів, робити це треба в середовищі, створеному з тієї самої магії.\n\nНегайно вирушай до Твердині Сквернодуших. Коли прибудеш, я надішлю Згаслих на допомогу. Украй важливо, щоб ти не йш$p(ов:ла) звідти, доки не впевнишся, що досліди дають належні результати.",
    },
    [45064] = {
        title = "Кінець Сквернонародженим",
        description = "Сквернонароджені почали поширювати свій вплив за межі міста. Особливо нас цікавить табір на сході, у Багряних Хащах. Ватажок цього застави, Валтіс Ама'ран, підпорядковується безпосередньо Андарісу.\n\nНастав час випробувати вишкіл наших Згаслих і пристрій Окулета на ділі. Ми не можемо дозволити їм просунутися далі, {name}.\n\nПрямуй до табору й скористайся сферою, щоб відтяти голову звіра. Час починати наш наступ.",
    },
    [45065] = {
        title = "Розвідати місто",
        description = "Ніколи не нудно! Хоча... мабуть, це не зовсім так.\n\nБоюся, мушу знову попросити тебе повернутися до міста й зібрати відомості. Але це не будь-які відомості — це видобуток відомостей!\n\nМені потрібні точні координати, щоб я міг навести свої телепортації з надзвичайною точністю. На жаль, коли дані будуть здобуті, доведеться витратити трохи часу, щоб їх опрацювати, та байдуже. Тим часом у нас і так багато справ.",
    },
    [45066] = {
        title = "Експериментальна нестабільність",
        description = "Щоб просунути наші дослідження, мушу попросити тебе дістати кілька особливих речей з моїх давно покинутих покоїв.\n\nЗапевняю тебе, там... здебільшого безпечно, якщо не зважати на кілька нестабільних елементів.\n\nПрямуй до моєї майстерні й знайди телепортер. Я вимкну його маскувальний пристрій, щойно ти прибудеш.",
    },
    [45067] = {
        title = "Телемантичний простір",
        description = "Самого лише розуміння магії Скверни може бути замало, {name}.\n\nПоговори з Окулетом про те, як розширити наші зусилля. Я чув, він приготував для нас щось... особливе.",
    },
    [45068] = {
        title = "Діжки розваг",
    },
    [45069] = {
        title = "Діжки розваг",
    },
    [45070] = {
        title = "Діжки розваг",
    },
    [45071] = {
        title = "Діжки розваг",
    },
    [45072] = {
        title = "Діжки розваг",
    },
    [45073] = {
        title = "Грабуй і палій!",
        description = "Скажу тобі чесно, $p(друже:подруго), я тут не просто так — маю свої власні причини. Минулого разу вийшла невелика халепа. Трохи випивки, трохи азартних ігор і забагато рому, якщо ти розумієш, про що я. Слово за слово, замаячили кулаки і... чесно кажучи, усе як у тумані. Після того мене тут не надто радо вітають.\n\nАле ж вони забрали моє добро! Ці брехливі, брудні старі... кхм. Не міг би ти взяти цей смолоскип і... спалити їхнє манаття? Я був би вдячний.",
    },
    [45079] = {
        title = "Селище Ґленбрук",
        description = "<Ця книга — список мешканців Ґленбрука.\n\nУсі імена, крім кількох, закреслені.>",
    },
    [45083] = {
        title = "Птахи Крайси",
        description = "Я роздобув одних із найекзотичніших падложерних птахів, що їх будь-коли бачили в Азероті. Гадаєш, ти зможеш проти них устояти?",
    },
    [45088] = {
        title = "Випробування Доблесті: Втрачене військо",
        description = "Хоч поразка Гельї і є твоєю головною ціллю, мені потрібна ще більша твоя допомога. Гелья здобула здатність викрадати й опоганювати душі моїх валар'ярів. Її поплічники тримають ці душі в полоні, спотворюючи їх. Я певен, що найвеличніші душі валар'ярів Гелья прибирає собі. Ти мусиш визволити ці втрачені душі й повернути їх мені.\n\nЗроби це, і я винагороджу тебе благословенним захистом зі збройні залу.",
    },
    [45098] = {
        title = "Розмах замовлень",
        description = "За останні кілька днів ми натрапили на тривожну кількість несанкціонованих замовлень на воєнне спорядження, зокрема на сучасний далекобійний прилад наведення й велику кількість вибухівки військового зразка.\n\nСаме прилад наведення замовили в Мукса Манашифрувальника — він свого роду майстер технологій стеження.\n\nВирушай до його крамниці в Ґаджетзані й спробуй з'ясувати, хто покупець. Ми маємо докопатися до суті, перш ніж той товар пустять у хід.",
    },
    [45099] = {
        title = "Гарячий слід",
        description = "Прилад наведення, кажеш?\n\n<Мукс якусь мить сторожко тебе розглядає.>\n\nАга, продав я один такий. Але обличчя покупця так і не побачив. Дуже потайний тип.\n\nХоча, коли він виходив, у нього з кишені випала перфокарта. Я послав одного зі своїх посіпак услід за ним на одному з моїх ракетних візків, щоб повернути її.\n\nОбслуговування клієнтів, сам розумієш?\n\nАле той пройдисвіт так і не повернувся! Та гей, якщо ти шукаєш пригод, вони подалися на захід. Це все, що я можу тобі сказати.",
    },
    [45101] = {
        title = "Запуск ось-ось",
        description = "Це кепсько.\n\nПо всьому Ґномреґані ми поставили сигналізацію, щоб виявляти будь-яких сторонніх, поки завершуємо очищати його від радіації.\n\nЗа останні кілька годин спрацювала чи не кожна з них.\n\nЗважаючи на твою розвідку, можна сміливо припустити, що Термаплаґ десь там унизу, і вогневої міці в нього досить, щоб винищити будь-що на власний розсуд!\n\nОсь тут і потрібен ти. Я переправлю тебе до Ґномреґана. Щойно будеш там, поговори з Високим Майстровим і зроби все, що знадобиться.\n\nЗа Азерот!",
    },
    [45102] = {
        title = "Розпочати штурм",
        description = "Битва за наш світ була запеклою, та завдяки силі твоєї зброї й об'єднаним силам Азерота ми щоразу відкидали загарбників-демонів назад.\n\nТепер ми знову стоїмо на Розбитому Узбережжі, готові звершити те, чого раніше не змогли досягти. Не забуваймо тих, хто пожертвував усім, щоб дати нам цей шанс.\n\nНаша перша ціль — захопити пагорб перед нами, щоб звести фортецю. Зберися з духом, {name}. Штурм Розбитого Узбережжя починається зараз.",
    },
    [45103] = {
        title = "У похід!",
        description = "Час настав, Повелителю смерті! Наші розвідники помітили велике скупчення демонів неподалік звідси. Веди нас до перемоги й покажи цим демонам силу нежиті!",
    },
    [45105] = {
        title = "Лорд Раз'ґор",
        description = "Володар ями Раз'ґор наглядає за цим бастіоном. Якщо хочеш зламати Розбите Узбережжя, Раз'ґора треба здолати.\n\nПробийся крізь демонічну заставу й знайди лорда Раз'ґора. Убий демона — і завдаси нищівного удару планам Палаючого Легіону на Розбитому Узбережжі.",
    },
    [45111] = {
        title = "Усі люблять добру бійку",
        description = "У записці сказано:\n\n«Не варто було тобі патякати про бійцівський клуб, надто вже цим чемпіонам. Та коли вже так сталося, гадаю, нехай вони час від часу тут б'ються. Але спершу ти краще доведи, що ти справжній боєць!»",
    },
    [45112] = {
        title = "Ознаки безумства",
        description = "<Хто б не був цей покупець, схоже, він пішов поспіхом. Навколо тебе важко висне їдкий чад, а багаття посеред цього місця ще тліє.>\n\n<Можливо, щось тут укаже тобі правильний напрямок?>",
    },
    [45118] = {
        title = "Ріг Гельї",
        description = "{name}, нам треба зміцнювати наше військо будь-якими засобами. Квалдири прокляті без надії на спасіння, але вони запеклі воїни, і це ресурс, яким не варто нехтувати.\n\nВони навіки зобов'язані коритися Гельї — навіть після її смерті. Якщо ми зможемо прикликати їх її голосом, вони підуть за нами!\n\nМи здобули Ріг Гельї з її трупа. Наповни його силою, щоб ти міг прикликати квалдирів, коли вони нам знадобляться.",
    },
    [45123] = {
        title = "Елементаль: Безумство Левії Лоренс",
        description = "Левія Лоренс колись була членом Кірін-Тору. Захоплення тіньовою магією призвело до її вигнання з міста, але вона надто добре знає тутешні вулиці, щоб триматися осторонь назавжди.\n\nЛевія зникла, і я вкрай стурбований. Її праця могла привернути увагу Легіону. Таке вже бувало. Було б дуже небезпечно, якби її знання потрапили до їхніх рук.\n\nОстанній раз її бачили біля Сацелуму Писаря. Розпитай там і спробуй натрапити на її слід.\n\nСпеціалізація: Шаман стихій",
    },
    [45125] = {
        title = "Гра з демонічним",
        description = "Левія, певно, використала ці руни, щоб допомогти своєму ритуалу. Навіть якщо вона така могутня, як каже Модера, у демонічній магії вона була новачком, тож руни мали допомогти стабілізувати портал.\n\nМені потрібно, щоб ти з'ясував, які руни треба активувати, аби відтворити її ритуал. У цій кімнаті є кілька книг про рунічну магію, які вона, без сумніву, вивчала для свого ритуалу.\n\nЩойно ти активуєш руни, я завершу закляття.",
    },
    [45126] = {
        title = "Неймовірна спокуса",
        description = "Мо... Модера тебе прислала?\n\nНі... ти мусиш... тікати! Аґата от-от повернеться!\n\nРятуйся...",
    },
    [45127] = {
        title = "Кохані під знаком Скверни",
        description = "Ця мерзенна матір бісенят! Якби я не була така ослаблена, я б пірнула в цю водойму й висловила б їй усе, що про неї думаю!\n\n<Левія глибоко вдихає, щоб опанувати себе.>\n\nЛише питання часу, коли Аґата зможе скористатися силою, яку вкрала в мене. Краще нам не бути тут, коли це станеться.",
    },
    [45128] = {
        title = "Славетне возз'єднання",
        description = "Ти добре впорався, бойовий володарю {name}. Повернімося до Небесної Тверджі. Одін захоче почути про твій тутешній успіх.",
    },
    [45132] = {
        title = "Поки не пізно",
        description = "<Якщо за цим стоїть сумнозвісний Сікко Термаплаґ, наслідки справді жахливі.>\n\n<Ще гірше — схоже, він уклав союз із Легіоном. Хтозна, які «дарунки» вони піднесли цьому божевільному мехінженеру.>\n\n<Мукс у Ґаджетзані, сподіваюся, допоможе тобі вистежити Термаплаґа, поки не пізно.>",
    },
    [45133] = {
        title = "Ознаки безумства",
        description = "Та кажу ж тобі, я вже розповів усе, що знаю!\n\nЯкщо хочеш дізнатися щось про того типа, що купив систему наведення, доведеться піти за моєю помічницею на захід.\n\nТабір покупця десь там...\n\nЯк на мене.",
    },
    [45134] = {
        title = "Жниварі душ",
    },
    [45143] = {
        title = "Суд чекає",
        description = "Наш безперервний наступ на Розбитому узбережжі привернув увагу багатьох паладинів, які бажають битися під твоїм проводом. Одні гідніші за інших, але судити про це можеш лише ти.\n\nНові рекрути чекають у таборі одразу за каплицею, очікуючи на твій суд.",
    },
    [45145] = {
        title = "Родинні реліквії Мондфанґів",
        description = "Як і обіцяла, ось ключ-півмісяць, що відмикає скрині моєї родини, хоча нічого цінного в них уже не лишилося.\n\nСподіваюся, усе, що знайдеш, ти передаси Делас? Речі наших предків, хоч би яка їхня цінність, мають лишитися в нашій родині.",
    },
    [45146] = {
        title = "Рунічне читання",
        description = "Із цим сувоєм коїться щось дивне. Для недосвідченого ока це порожня сторінка, але коли я підношу його до світла, на мить проступає мерехтіння рун.\n\nЯк і з більшістю демонічних рун, мені знадобиться кров Скверни, щоб зруйнувати магію, якою приховано послання всередині цього сувою.",
    },
    [45147] = {
        title = "Знищення каменя Скверни",
        description = "<Делас роззявляє рота, і сувій вислизає з її рук на підлогу.>\n\nЦього не може бути... ці руни... вони описують пакт між Палаючим Легіоном і моїми предками. Темна угода, що мала дарувати моїм предкам захист від демонів у цьому житті, але натомість їхні душі належали б Легіону.\n\nЦей кулон Скверни — втілення цього пакту, і його неможливо зняти, щойно надягнеш.\n\nШвидше, {name}. Ти мусиш скористатися своїм артефактом, щоб знищити цю прокляту прикрасу!",
    },
    [45148] = {
        title = "Клятвопорушник",
        description = "Багато років тому я уклав угоду з чоловіком, якого вважав схожим на себе. Його обіцянка захисту здавалася надто гарною, щоб бути правдою, але я був у відчаї й погодився на цю оборудку.\n\nЛише після того, як я підписав її кров'ю, повелитель жаху Зорак показав своє справжнє обличчя.\n\nДоки він живий, мої предки лишатимуться прив'язаними до Палаючого Легіону, а наші вороги збиратимуть армію з підневільних солдатів.\n\nВирушай до Розбитого берега і вбий Зорака В'язня Клятв. Його смерть розірве владу, яку він має над моїми предками.",
    },
    [45149] = {
        title = "Кінець прокляттю Півмісяця",
        description = "Ми мусимо зробити все можливе, щоб зняти прокляття, яке спіткало моїх предків.\n\nПалаючий Легіон отаборився серед руїн, де спочивають наші мертві, готовий виконати жахливу угоду, укладену так давно.\n\nКожен з моїх предків обтяжений підвіскою, що прив'язує його до демонічних володарів. Її не можна зняти, але, як ти вже дові$p(в:ла), маючи достатньо сили, її можна знищити.\n\nПоклади край прокляттю, що мучить моїх предків, і звільни їхні душі!",
    },
    [45159] = {
        title = "Кубічна загадка",
        description = "<Ти знаходиш загадковий куб. Його будова незнайома, але безсумнівно стародавня.\n\nПоверхня куба викладена магічними рунами. Хоч він і бездіяльний, його властивості, можливо, варто дослідити.\n\nМабуть, якщо показати його Дарінесс Ученій у Даларані, вона зможе розповісти про нього більше.>",
    },
    [45160] = {
        title = "Кубічні потоки",
        description = "Щоб визначити призначення цього куба, нам треба наповнити його енергією. Гм, я маю ідею...\n\nНічнонароджені цінують речовину, яка тобі, поза сумнівом, знайома, — стародавню ману. Вона має чудово підійти для такої давньої реліквії. Збери достатню кількість, і ми спробуємо привести його в дію.\n\nБудь обережний у Сурамарі! Було б шкода, якби цей дивовижний куб загубився і знову став лише спогадом.",
    },
    [45162] = {
        title = "Ми принесли молот",
        description = "Твої чемпіони здобули перемогу в бійці проти Ради Бойових Молотів. Принеси цей «жетон» до Гільдії бійців як доказ.",
    },
    [45163] = {
        title = "Очищення",
        description = "Твої чемпіони повертаються з перемогою. Вони розповідають величну історію про те, як добряче прибрали за прибиральником Біллом.",
    },
    [45167] = {
        title = "REUSE ME",
        description = "{name}, нам доведеться зміцнювати нашу армію будь-якими можливими засобами, щоб мати бодай надію відкинути Легіон. Квалдири прокляті без надії на спасіння, але вони люті воїни і ресурс, яким не варто нехтувати. Вони мусять коритися тому, хто володіє Рогом Гелі. Ти маєш здобути його.\n\nЇї так званим геларджарам доручили його охороняти. Тобі доведеться відібрати його в них.",
    },
    [45172] = {
        title = "У бій!",
        description = "Твої чемпіони повернулися з розвідки поля бою зі звітом, що описує шалені пригоди та зухвалі подвиги сили й честі. У цих мінливих битвах за завоювання завжди потрібна додаткова допомога.\n\nЧи відгукнешся ти на поклик?",
    },
    [45173] = {
        title = "Відчайдушні часи",
        description = "Конфлікт триває. Як завжди, на великих полях бою потрібна твоя допомога. Долучайся до сутички, перемагай ворогів і здобувай славу для своєї фракції.",
    },
    [45174] = {
        title = "Полювання на Іллідана Стормрейджа",
        description = "Алларі Душожерка, оракул іллідарі, вже чималий час полює на душу Іллідана. Тепер вона вважає, що знайшла її місцеперебування, і потребує твоєї допомоги, щоб її повернути.\n\nЗнайди Алларі на Заставі іллідарі в Азсуні й допоможи їй усім, чим можеш.\n\nЯкщо Саргерас справді планує використати тіло Іллідана як посудину для власного повернення, то повернення душі Іллідана до його тіла — запорука того, що темний титан не повернеться у наш світ!",
    },
    [45175] = {
        title = "Призма душі іллідарі",
        description = "На жаль, я поки що не обтяжуватиму тебе знанням про місцеперебування душі володаря, {name}. Спершу ми маємо створити призму душі, достатньо потужну, щоб втримати безмежні хаотичні енергії володаря.\n\nДля цього мені потрібні залишкові фрагменти душ могутніх істот, розкиданих по всьому світу. Принеси мені достатньо, і я створю призму душі, здатну втримати душу володаря — принаймні достатньо довго, щоб перенести її в наару.",
    },
    [45176] = {
        title = "Випробування Доблесті: Володар Тіней, що був і буде",
        description = "Хоча вистежити фізичне тіло володаря виявилося непросто, нам вдалося знайти його в Нічній Цитаделі Сурамару. За даними нашої розвідки, Ґул'дан робить останні приготування до Нічного Колодязя, щоб використати його силу і ввести душу Саргераса в тіло Іллідана.\n\nЄдиний спосіб цьому завадити — повернути на місце безсмертну душу самого Іллідана.\n\nВізьми Призму душі іллідарі й вирушай до Гельгейму. Здолай Гелю і застосуй призму на душі Іллідана! Поверни її до Серця Світла.",
    },
    [45177] = {
        title = "Нічна Цитадель",
        description = "Душа Іллідана надійно спочиває в Серці Світла. Візьми цю посудину й передай її Хадґару з такими настановами:\n\nКоли Ґул'дан спробує розірвати небеса й привести темного титана в наш світ, виклич силу цієї посудини й випусти душу Іллідана в його тіло.\n\nІди ж, {name}. У нас обмаль часу. Темний ритуал скоро почнеться.",
    },
    [45178] = {
        title = "Стримування зарази",
    },
    [45179] = {
        title = "Підкори натовп",
        description = "Цей лист запрошує тебе битися на одній із найбільших подій в історії Азероту. Величні битви на арені, де бійці здобувають славу й шану, і кожен запам'ятає їхні імена. Принаймні до наступного сезону.",
    },
    [45182] = {
        title = "Лід: Викривлений близнюк",
        description = "До мене звернувся давній друг, Карам Магсписа, з проханням допомогти знайти його брата, Рейста. Карам боїться, що Рейст зв'язався з темними силами, і прагне його спинити.\n\nСпершу Рейст навчався в Кірін-Тор, але жага влади була в ньому така сильна, що він звернувся до забороненого мистецтва некромантії. Це викрилося, і його вигнали з нашого ордену.\n\nЗнайди Карама в Залі Спритноруких і поглянь, чи зможеш йому допомогти.\n\nСпеціалізація: Маг Льоду",
    },
    [45185] = {
        title = "Послання з тіней",
        description = "Я знаю, що мій брат і в минулому збивався на манівці, та боюся, що тепер він потрапив до тенет немислимого зла. Нещодавно він почав потайки зустрічатися з темним культом, що ховається серед мешканців Даларану.\n\nЯ прибув сюди, щоб переконати його змінити свій шлях, але він не схотів зійти з обраної дороги. А тепер він зник.\n\nКоли я бачив його востаннє, Рейст мешкав у кімнаті нагорі. Я не зміг знайти там жодних слідів, але тобі, можливо, поталанить більше.",
    },
    [45187] = {
        title = "Таємниці Черева",
        description = "Отже, мій брат подався чинити якийсь ритуал із цими культистами? Це пояснює, чому він пішов, але не куди...\n\nСтривай! У цьому листі згадуються культисти «Нетерзаприсяжних», що шукають реагенти в Череві. Якщо поквапимося, ми ще зможемо їх знайти!",
    },
    [45188] = {
        title = "Мудрість Ради",
        description = "Вибач, {name}, але я нічого тут не второпаю. Загадки ніколи не були моєю сильною стороною.\n\nНам варто віднести ці записи культиста до архімага. Можливо, він пролиє на це світло.",
    },
    [45190] = {
        title = "Там, де найтонше",
        description = "Хоч я ніколи й не чув про культ «Нетерзаприсяжних», те, про що йдеться в цьому маніфесті, не віщує нічого доброго.\n\nПроте маю одну здогадку. У записах ідеться про «місце, де його шкіра найтонша». Гадаю, вони можуть мати на увазі місце, де завіса між Азеротом і Круговертю Нетеру найслабша, — Гробницю Саргераса.\n\nТепер, коли наші сили закріпилися на Розбитому березі, для Рейста та його союзників-культистів це слушна нагода дістатися гробниці. Раджу тобі їх спинити.",
    },
    [45192] = {
        title = "Руни роздирання",
        description = "Мій брат і його культисти чинять якийсь ритуал у дальньому кінці печери. Я намагався втрутитися, та брат залишив магічні обереги, що перекривають шлях.\n\nЯкщо ти знайдеш спосіб їх оминути, ми ще зможемо спинити його вчасно!",
    },
    [45193] = {
        title = "На крок позаду",
        description = "Схоже, Рейст вислизнув від нас, але принаймні його культисти вже не становитимуть такої загрози.\n\nНам слід повернутися до Кірін-Тор. Вони допоможуть нам спланувати наступний крок.",
    },
    [45203] = {
        title = "Битва за руїни",
    },
    [45207] = {
        title = "Нічнонароджена учениця",
        description = "Я залюбки познайомлю тебе зі своєю новою ученицею, якщо ти не проти трохи помандрувати. Зараз вона на завданні — пильнує осередок сквернонароджених бійців опору, що присягнули на вірність Легіону.\n\nЯк перша нічнонароджена, що приєдналася до Тирісгарди, вона напевно прагне довести свою майстерність!",
    },
    [45209] = {
        title = "Ці видющі очі",
        description = "Донедавна Лай'лет регулярно надсилала нам магічні послання з Нічної Цитаделі. Вона ретельно приховувала ці послання — лише найпильніші провидці могли б їх виявити.\n\nВони не могли бути в палаці... надто багато завад від Нічного Колодязя...\n\nАвжеж! Тераса Просвітлення! Сутінкова варта мала там влаштувати пост підслуховування.\n\nОглянь кулі провидіння на сліди послань Лай'лет. Ми мусимо дізнатися, що вона намагалася нам сказати!",
    },
    [45238] = {
        title = "Повернення до Каражана: Кубічний осередок",
        description = "Дідько! Прадавня мана, схоже, не діє. Треба обміркувати цю проблему, зосередитися і...\n\nСтривай, ось воно! Зосередитися! Нам треба зосередити енергію прадавньої мани, щоб активувати куб.\n\nЯ чув, що в Каражані є манавирм, здатний фокусувати свою силу. Можливо, це саме те, що нам потрібно!\n\nБудь обережний, утім. Мої джерела кажуть, що цей вирм велетенський!",
    },
    [45239] = {
        title = "Кубічне злиття",
        description = "Вийшло! Магію куба відновлено! Не терпиться побачити, на що він здатен!\n\nОскільки всю чорнову роботу зробив ти, тобі й належить честь активувати його. Хочеш спробувати?",
    },
    [45240] = {
        title = "Готування до справи",
        description = "Володарю смерті, ми відшукали реліквію величезної ваги й могутності. Збруя Паморозного Ікла з'явилася в Цитаделі Крижаної Корони. Ми мусимо здобути її, а не дати їй потрапити до чужих рук.\n\nГадаю, ти захочеш забрати збрую особисто? Ми вислали наперед одну з наших, Мінерву Воронгорю, на розвідку. Ти ж уже зустрічав її, так? Вона справила на нас неабияке враження, і ми віримо, що під твоїм наставництвом вона стане досить могутньою.\n\nЯ відчиню для тебе браму смерті. Найкраще зустрітися з нею там.",
    },
    [45243] = {
        title = "На крилах Даумира",
        description = "Час настав, {name}. З цими новими драконами в нашій армії ми готові до штурму Розбитого Берега. Великий загін демонів з'явився поблизу одного з наших таборів, і їх надто багато, щоб хтось із наших союзників міг із ними впоратися.\n\nХто ж краще здолає цих демонів, як не ті, хто не боїться смерті? Ті, хто має чималеньку таємну зброю?\n\nБери Даумира. Ми зустрінемо тебе там.",
    },
    [45251] = {
        title = "Подвійний захист",
        description = "Прабатько-конструкт? Яке винахідливе рішення нашої проблеми!\n\nМабуть, ми вже могли б скеровувати силу Катра'натіра, не звільняючи його, та про всяк випадок я хочу додати ще один шар захисту, перш ніж пробувати. Я не дозволю нікому звинуватити мене в підступності!\n\nЗустрінься зі мною на Розбитому Березі, коли будеш готов$p(ий:а).",
    },
    [45260] = {
        title = "Крок за кроком",
        description = "Дякую, що прийшов, $p(чужинцю:чужинко). Рада знову тебе бачити.\n\nУ місті виникла справа, яка потребує твоєї уваги, але спершу...\n\nПоговорімо про надію.\n\n<Талісра вказує на аркан'дор.>\n\nПлід аркан'дора справді може звільнити мій народ від Нічного Колодязя. Однак росте він не так уже й швидко. Знадобиться час, щоб роздати ці ліки.\n\nГадаю, буде справедливо, якщо ти допоможеш мені роздавати плоди, щойно вони достигнуть. Прошу, візьми це й дай комусь.",
    },
    [45261] = {
        title = "Продовження зцілення",
        description = "Після подій біля Спадної Півмісяця тутешні біженці прагнуть як ніколи отримати дар аркан'дора й назавжди звільнитися від Нічного Колодязя.\n\nНа щастя, дерево дало нові плоди. Знову прошу тебе вшанувати нас і роздати ці плоди всім тут, у Шал'Арані.\n\nКоли впораєшся, ми обговоримо подальші справи в місті. Сілґрин повідомляє, що Арлуель виявилася гарною ученицею, і вони вдвох успішно евакуюють містян.",
    },
    [45262] = {
        title = "Звістка від Лі'лет",
        description = "Аркан'дор знову плодоносить. І саме вчасно — Лі'лет надіслала нам звістку, і, схоже, вона напала на слід Вантіра. Йому давно вже час отримати цей дар, якщо тільки нам пощастить його знайти.\n\nДай плід ще одному мешканцеві тут, у Шал'Арані, поки я завершу розшифровувати звістку Лі'лет.",
    },
    [45263] = {
        title = "Трапеза перед зборами",
        description = "Поява Вантіра неабияк підняла настрій тутешньому люду. Смію сказати, дехто навіть почав смакувати новонабутою свободою, хоч і сумує за коханим містом.\n\nЯ не спочину, доки не зможу повернути його їм.\n\nНа нас із тобою чекає важлива зустріч. Та перш ніж піти, роздаймо ще плодів аркан'дора.\n\nЯ хочу, щоб люди знали: хоч мені й треба зараз піти, я їх не покинула.",
    },
    [45265] = {
        title = "Живлення повстання",
        description = "Щодня дедалі більше нічнонароджених тікають із Сурамара, щоб приєднатися до нашої справи.\n\nНаші лави зростають, і з допомогою великих героїв на кшталт тебе та армій Орди й Альянсу наші шанси ще ніколи не були такими високими.\n\nДопоможи мені роздати ще плодів аркан'дора — кожен із них означає життя, вільне від рабської залежності від Нічного Колодязя!\n\nОпісля ми поговоримо, як найкраще підтримати наших нових союзників у їхній облозі.",
    },
    [45266] = {
        title = "Єдиний фронт",
        description = "Наші повстанці озброєні, і бойовий дух високий — навіть ельфи Альянсу й Орди припинили чвари.\n\nМи майже готові виступити на місто.\n\nРоздай цьоготижневі плоди, і тоді ми зможемо почати готування.",
    },
    [45267] = {
        title = "Перед облогою",
        description = "Стільки років мого життя минуло за навчанням у Нічній Твердині...\n\nНіколи я не думала, що одного дня доведеться пробиватися назад із боєм.\n\nЧасу обмаль. Битва незабаром нагряне.\n\nПрошу, продовж нашу традицію й нагодуй ще одного біженця плодом аркан'дора.",
    },
    [45268] = {
        title = "Радниця й арканістка",
        description = "Ця нова Перша арканістка, призначена Елісандою. Ця... Андаріс. Якщо вона така небезпечна, як я чула, то Лі'лет, цілком можливо, втрачено.\n\nВибач, не варто мені плекати такі думки. Просто ми отримали тривожну звістку.\n\nДопоможи мені роздати останню партію плодів аркан'дора, а потім ми обговоримо ту звістку.",
    },
    [45269] = {
        title = "Смак свободи",
        description = "Ми готові настільки, наскільки взагалі можемо бути. Щойно ми втілимо план Валтруа в життя, ми зможемо атакувати Святилище Ордену й покласти край Андаріс. Вона нізащо не сподівається, що ми загартували наших Згаслих проти магії Скверни, і її пиха стане її погибеллю.\n\nХодімо, нагодуймо народ востаннє.",
    },
    [45271] = {
        title = "Повстання",
        description = "Перша арканістка Талісра отримала зловісні звістки щодо повстання Згаслих і потребує твоєї допомоги.\n\nВирушай до Шал'Арану в Сурамарі та зустрінься з нею.",
    },
    [45272] = {
        title = "Повстання: Зниклі безвісти",
        description = "Перша арканістка Талісра попросила твоєї допомоги в пошуках своїх зниклих людей.\n\nУ неї є зачіпка від вельми несподіваного союзника.\n\nЗустрінься з нею в Шал'Арані в Сурамарі.",
    },
    [45277] = {
        title = "Повстання: Молодий місяць",
        description = "Перша арканістка Талісра передала звістку: надійшло повідомлення від Лі'лет. Потрібна твоя допомога.\n\nВирушай до Шал'Арану в Сурамарі та допоможи чим зможеш.",
    },
    [45278] = {
        title = "Повстання: Ельфійська проблема",
        description = "Альянс і Орда прибули до Сурамару. Перша арканістка Талісра потребує твоєї допомоги, щоб їх представити.\n\nЗустрінься з Талісрою в Шал'Арані.",
    },
    [45280] = {
        title = "Повстання: Куючи зброю війни",
        description = "Біженці потоком стікаються до Шал'Арану, і багато хто готовий битися за повстанську армію Талісри.\n\nЇм потрібна зброя, вишкіл і допомога від кожного, хто здатен її надати.\n\nВирушай до Шал'Арану й запропонуй свою підтримку.",
    },
    [45281] = {
        title = "Повстання: Похід на Сурамар",
        description = "Перша арканістка Талісра передала звістку: настав час почати наш штурм Сурамару. Ельфійські армії Орди, Альянсу, Кірін Тор і Згаслих зібрані.\n\nВони чекають лише на твоє прибуття, щоб розпочати штурм.\n\nЯвись до Шал'Арану, зустрінься з Першою арканісткою Талісрою та готуйся до бою.",
    },
    [45282] = {
        title = "Повстання: Відповідь Елісанди",
        description = "Об'єднані сили ельфів готові розпочати облогу брам Нічної Фортеці.\n\nЯвись до Першої арканістки Талісри в Шал'Арані, щоб почати облогу.",
    },
    [45285] = {
        title = "Повстання: Сильні, як наша воля",
        description = "Після нападу Елісанди потреба поповнити лави повстання Згаслих сильніша, ніж будь-коли.\n\nУ дію втілюються плани, які можуть допомогти в цьому нестандартним чином.\n\nЯвись до Першої арканістки Талісри в Шал'Арані по докладніші відомості.",
    },
    [45287] = {
        title = "Повстання: Падіння Нічної Фортеці",
        description = "Перша арканістка Талісра передає звістку, що її сили готові. Настав час тобі очолити напад на Нічну Фортецю.\n\nЯвись до Шал'Арану в Сурамарі по подробиці.",
    },
    [45291] = {
        title = "Повернення до Каражану: Книжкові вирми",
        description = "Мій безтілесний стан уперше дозволив мені безпечно ввійти до вежі. Маю сказати, там панує справжній безлад!\n\nМені б знадобилася допомога з моїм списком прибирання. Почнімо з бібліотеки. Усі ці затхлі фоліанти неодмінно приваблять манавирмів!\n\nБудь ласка, постав на полиці всі книжки, що попадали на підлогу або, ще гірше, знялися в повітря. А якщо знайдеш манавирмів, що гризуть сторінки... розчави їх!",
    },
    [45292] = {
        title = "Повернення до Каражану: Перезапуск Прибиральника",
        description = "Вартовий Медів створив Куратора, щоб той наглядав за Каражаном, але боюся, що цей пристрій поводиться химерно. Тривала робота, можливо, спричинила збій.\n\nБудь ласка, піднімися до Звіринця й вимкни Куратора. Також обшукай довкола в пошуках ящика із запасними кристалами-мотиваторами та повернися до мене.\n\nНавіть із моїми базовими знаннями я маю зуміти замінити його мотиватор, і тоді ми залучимо Куратора до прибирання вежі.",
    },
    [45293] = {
        title = "Повернення до Каражана: Нові підкови",
        description = "Поки що мій проєкт з прибирання Каражана не назвеш гучним успіхом. Час спробувати щось нове.\n\nНове — як-от нові черевики... тобто підкови! Біля вежі лишили ящик підков. Проблема в тому, щоб знайти кур'єра, готового ступити всередину... зважаючи на тутешню смертність.\n\nЯкщо твоя ласка, візьми ящик і віднеси його Корену до стайні. Тільки обережно проходь повз Аттумена. Мисливець недолюблює чужинців.",
    },
    [45294] = {
        title = "Повернення до Каражана: Нервова перерва",
        description = "Нові вистави в оперному театрі припали до душі всім... крім акторів зі старіших постановок. Самолюбство зачеплене, а напруга зростає!\n\nРомуло і Джуліанна готові отруїти одне одного.\n\nБляшаноголовий аж іржавіє від сліз через брак захоплення.\n\nУ Червоної Шапочки накидку вкрала ображена дублерка, що втекла грати в шахи, уявляєш.\n\nАктори, що з них візьмеш? Нам треба, щоб вони були готові виступати, якщо публіка вимагатиме повернення вистав. Прошу, допоможи мені заспокоїти їхні нерви!",
    },
    [45295] = {
        title = "Повернення до Каражана: Геть павутиння",
        description = "Зізнаюся... навіть бувши духом, я смертельно боюся павуків. Усі ці лапи! Краплі отрути з ікол! Липке павутиння, що лізе з їхніх...\n\n<Даріус звивається в якомусь корчі, на який неприємно дивитися.>\n\nАле ж такий рятівник світу, як ти, певно, їх не боїться. І це добре, бо цілий виводок павуків захопив помешкання слуг.\n\nТи ж із цим розберешся, так? Якщо не винищиш їх усіх, вони й далі плодитимуться.",
    },
    [45296] = {
        title = "Це вам не дрібнички",
        description = "Обвуглені кісткові уламки досі жевріють прадавньою силою. Даріусу було б надзвичайно цікаво оглянути їх і почути про твою перемогу над Нічним Жахом.",
    },
    [45301] = {
        title = "Узяти все під контроль",
        description = "У Мардумі вже кілька місяців тихо. Цікаво, чому Легіон нападає на нас саме зараз? Можливо, це помста за те, що ми знищили їхній бойовий корабель на Зламаному березі...\n\nКраще нам самим спуститися туди й урятувати становище, чи не так?",
    },
    [45304] = {
        title = "Атака на темряву",
        description = "Твої чемпіони повернулися дещо приголомшені сутичкою з Володарем тіней.",
    },
    [45307] = {
        title = "Привід для тривоги... з кігтями!",
    },
    [45312] = {
        title = "Ти подолав М'ясну Кулю",
        description = "Твої чемпіони повертаються з жмутом закривавленого, сплутаного й вельми смердючого волосся.",
    },
    [45316] = {
        title = "Стабілізація Сурамару",
        description = "План Елісанди обернувся проти неї самої. Вона думала придушити наше повстання, покаравши Тонкий Місяць для прикладу.\n\nНатомість вона роздмухала полум'я шал'дорай дужче, ніж я будь-коли зміг би.\n\nМи маємо вести злагоджену кампанію проти Елісанди та Легіону, б'ючись із ними в кожному закутку Сурамару.\n\nПокажи людям, що надія ще є — що ще є герої, готові за них боротися!",
    },
    [45317] = {
        title = "Боротьба на всіх фронтах",
        description = "Ми майже готові взяти ворота в облогу. Твої зусилля тут були грандіозні, {name}.\n\nАле не забуваймо, що ти ще й {class}t. Твоє військо покладається на твоє командування. Жодна людина не встоїть проти Легіону наодинці.\n\nПродовжуй виконувати свій обов'язок. Веди {class}s Азероту, і перемога буде забезпечена.",
    },
    [45329] = {
        title = "Операція: Портали",
        description = "Це серйозне вторгнення, але немає нічого, з чим не впорався б такий Згубник, як ти. Час пустити цю зброю в діло!",
    },
    [45330] = {
        title = "Загін розвідників",
        description = "Нам буде непросто розшукати зниклих розвідників і леді С'тено. Підозрюю, що декому з них зовсім не хочеться, аби його знайшли.\n\nЗроби все, що можеш, {name}!",
    },
    [45331] = {
        title = "Повернення до Ахерусу",
        description = "Ти дуже зросла відтоді, як ми бачилися востаннє, {name}. Тепер, коли в нас є збруя, погляньмо, чи має Мограйн план, як її використати.",
    },
    [45339] = {
        title = "Оборона Молота Скверни",
        description = "Нам треба якнайшвидше повернутися до Молота Скверни!",
    },
    [45342] = {
        title = "Надання допомоги",
        description = "На жаль, схоже, що багато твоїх союзників уже б'ються на цих уражених Скверною берегах. \n\nВони ніколи не зможуть здобути перевагу в бою, доки стільки з них потерпає від зарази. \n\nВізьми протиотруту й використай її, щоб надати допомогу своїм союзникам. \n\nМи з Роландом подбаємо про поранених тут.",
    },
    [45343] = {
        title = "Дивна зараза",
        description = "Мені доповіли, що доволі дивна зараза поширюється невеликою прибережною місцевістю у Високогір'ї.\n\nМісцеві племена покинули цей край, боячись підхопити недугу, від якої наразі немає відомих ліків.\n\nОдна з наших мандрувала тими краями, коли її супутник занедужав. Вона попросила Конклав про допомогу. Розшукай її, верховний жерче, і зроби все можливе, щоб спинити поширення цієї хвороби.",
    },
    [45344] = {
        title = "Зразки з джерела",
        description = "Як бачиш, мій супутник тяжко занедужав. \n\nВін, певно, підхопив те саме, що було в цих тавренів. Увесь їхній табір вимер!\n\nСхоже, це породження Скверни, і воно не піддається жодному відомому лікуванню. \n\nЯ невтомно шукаю ліки, але, боюся, Роландові лишилося небагато часу. \n\nМені б згодилася зайва пара рук. Кілька зразків із джерела пришвидшили б справу. \n\nТільки неодмінно уникай прямого контакту із заразою. Левітація стане в пригоді.",
    },
    [45345] = {
        title = "Капосні спрайти",
        description = "Мало кому відомо, що пилок, який спрайти використовують для своїх витівок, має цілющі властивості.\n\nДехто в алхімічній спільноті відмахується від цього твердження, але заперечують вони лише тому, що їм ніколи не вдавалося роздобути цей рідкісний інгредієнт.\n\nСпрайти часто огортають себе ілюзіями, щоб уникнути викриття.\n\nКози поблизу мають дивне мерехтіння, що наводить на думку: можливо, це переодягнені спрайти.\n\nРозвій магію, що їх оточує, аби виявити їхню справжню подобу.",
    },
    [45346] = {
        title = "Хисткі особини",
        description = "Схоже, ця зараза Скверни має три стадії.\n\nПерша позначається стійким мокротним кашлем.\n\nНа другій шкіра набуває хворобливого зеленкуватого відтінку.\n\nТретя ж означає цілковите перетворення, коли жертва обертається на безтямний труп. Гадаю, саме на цій стадії можна зібрати найбільше відомостей про хворобу.\n\nУ мене є пристрій, що дозволяє безпечно зберігати особини, але перш ніж їх зібрати, їх треба скувати.",
    },
    [45347] = {
        title = "Виготовлення ліків",
        description = "Я використав те, що ти для мене зібрав, аби виготовити ліки, які, маю надію, виявляться надійними. Бракує лише дещиці потужної магії, яку, сподіваюся, ти зможеш надати.\n\nЗілля он там, на моєму алхімічному столі.\n\nПоквапся, будь ласка, {name}. Роланд слабшає щохвилини.",
    },
    [45348] = {
        title = "Надійне зберігання",
        description = "Схоже, що тонка рівновага між святою магією та магією тіні і є ключем до лікування цієї зарази. Звісно, над засобом доведеться ще попрацювати, щоб зменшити небажані побічні ефекти, як-от смерть.\n\nА поки що віднеси протиотруту до Храму Світла Порожнечі й тримай її в безпеці. Я ж старанно працюватиму над пошуком джерела цієї зарази.",
    },
    [45349] = {
        title = "До Зламаного берега",
        description = "Ми отримали звістку від тих, хто б'ється на Розбитому березі. Схоже, джерело зарази вдалося визначити — це певний острів біля західного узбережжя.\n\nБагато наших союзників уже заражені. Ми мусимо діяти швидко, щоб зараза не поширювалася далі.",
    },
    [45350] = {
        title = "Протидія заразі",
        description = "Я простежив джерело зарази аж до цих берегів. Палаючий Легіон використовує розпорошувачі Скверни, щоб поширювати заразний наліт Скверни, через який кожен, хто з ним стикається, занедужує.\n\nЗнищ Оззука Опоганювача та його розпорошувачі Скверни, щоб заразу вдалося стримати.",
    },
    [45354] = {
        title = "Розосередження дисків",
        description = "Ці диски випромінюють силу! Це, певно, через їхню близькість один до одного. Ми мусимо забрати їх звідси, поки вони не зарезонували ще сильніше й не спричинили катастрофу в цих священних залах.\n\nЯ надішлю їх до єдиного відомого мені місця, де ми зможемо приборкати їхні енергії, запобігши будь-якому вибуху. Я кажу про Око Вічності.\n\nТам ми зможемо безпечно завершити те, що не вдалося довести до кінця Антонідасу. Звернися до мене знову, коли будеш готовий вирушати.",
    },
    [45358] = {
        title = "Стримування зарази",
    },
    [45372] = {
        title = "Доля нічнонароджених",
        description = "Невдовзі після твого звитяжного повернення з Нічної Фортеці нагальна справа покликала Таліссру назад до палацу.\n\nВона просила, щоб ти зустрі$p(в:ла) її там.\n\nЗвернися до мене, коли будеш готовий приєднатися до неї.",
    },
    [45379] = {
        title = "Скарбничий Ікс'рігед",
        objectives = "Вбий 1 пожирача Крил Скверни.",
    },
    [45381] = {
        title = "Нічна Твердиня: Талісман шал'дорай",
        description = "Коли будували Нічну Твердиню, мій народ викував талісман, що давав доступ до цих залів. Із силою талісмана можна було вільно пройти палацом і завдати удару просто по магістриксі. Використавши уламки сили Нічного Колодязя, ми могли б знайти талісман і покласти край цій дурній війні...",
    },
    [45382] = {
        title = "Нічна Твердиня: Талісман шал'дорай",
        description = "Коли будували Нічну Твердиню, мій народ викував талісман, що давав доступ до цих залів. Із силою талісмана можна було вільно пройти палацом і завдати удару просто по магістриксі. Використавши уламки сили Нічного Колодязя, ми могли б знайти талісман і покласти край цій дурній війні...",
    },
    [45383] = {
        title = "Нічна Твердиня: Талісман шал'дорай",
        description = "Коли будували Нічну Твердиню, мій народ викував талісман, що давав доступ до цих залів. Із силою талісмана можна було вільно пройти палацом і завдати удару просто по магістриксі. Використавши уламки сили Нічного Колодязя, ми могли б знайти талісман і покласти край цій дурній війні...",
    },
    [45385] = {
        title = "Ми маємо бути готові!",
        description = "Кораблі Легіону відступили, поки що. Та це лише питання часу, доки вони знову нападуть, і ми маємо бути готові.\n\nТреба негайно братися за ремонт! Леді С'тено очолила пошук деталей. Та зробить що завгодно, аби лишатися на твердій землі, ха!\n\nВона чекає на тебе на Розбитому Березі.",
    },
    [45386] = {
        title = "Запуск ось-ось",
        description = "Тінь {name}, яке полегшення!\n\nПо всьому Ґномреґану ми встановили сигналізацію, щоб виявляти будь-кого стороннього, поки завершуємо очищення міста від радіації.\n\nЗа останні кілька годин спрацювала майже кожна з них.\n\nЗа твоєю розвідкою можна сміливо припустити, що Термаплаґ десь там унизу, і в нього досить вогневої потуги, щоб винищити все, що йому заманеться!\n\nНе хвилюйся, я можу доправити тебе до Ґномреґану. Поговори з Великим Майстровитом, щойно будеш там, і зроби все, що знадобиться.\n\nЗа Азерот!",
    },
    [45390] = {
        title = "Душі врайкулів",
    },
    [45391] = {
        title = "Чемпіонка: леді С'тено",
        completion = "Ти шануєш нашу угоду понад усі с-сподівання, Вбивс-сце {NAME}. Знаєш-ш, я не майс-стриня солодких промов, але запевняю: я вдячна.\n\nЯ стану поруч із тобою, якщо приймеш мене.",
    },
    [45392] = {
        title = "Темний дарунок",
        description = "Ті квіти були... приємним жестом.\n\n<Велонара вдихає аромат однієї з чорних троянд.>\n\nУ мене є зайвий каптур. Нічого особливого, але, може, Моорґот захоче його взяти.\n\nТільки хай не плекає зайвих надій абощо. Я лише віддячую за доброту.\n\nБуду вдячна, якщо ти збережеш усе це між нами. Дарувати подарунки шанувальникам трохи виходить за межі правил поведінки темних рейнджерок.",
    },
    [45397] = {
        title = "Вогонь з гармат!",
        description = "Знадобиться щось більше за бісову корабельну аварію, щоб мене звалити. Ці перерослі, блювотно-смердючі демонські лантухи Скверни ще пошкодують, якщо думають, що цього досить, аби мене спинити.\n\n<Кішан випльовує морську воду й витирає рота рукавом.>\n\nУф... Хоча, мабуть, мені треба трохи перепочити. Ось, візьми цей сигнальний пістолет і виклич ним артилерійські удари по пляжу. Влаштуй пекло цим нікчемним покручам, напівкозлам, а я зустріну тебе на базі, коли місію буде виконано!",
    },
    [45398] = {
        title = "Приборкання сили",
        description = "Ці дурні використовують силу збруї Раймфанґа, щоб поневолити крижаних вірмів. Їхній ватажок, Андйор, сидить усередині на спині матки виводку й глузує з нас.\n\nХай більше не дихає.",
    },
    [45399] = {
        title = "Покінчити зі свелдреками",
        description = "Отже, як мені розповіли, порядок речей такий. $p(Смертний:Смертна) заходить у Крижану Корону. $p(Смертного:Смертна) жорстоко вбивають. $p(Смертного:Смертна) піднімають як Погибель.\n\nЦі дурні хай не сподіваються, що зможуть тут безчинствувати, робити що заманеться й піти без жодних наслідків. Час зробити їх такими ж безмозкими, як їхня поведінка.",
    },
    [45404] = {
        title = "Паніка в броварні",
        description = "Ми не були готові до раптового нападу. Боюся, бровароварку Бланш захопили, або й гірше...\n\nПрошу, допоможи мені, Великий Майстре!",
    },
    [45405] = {
        title = "Пролом у Святилище",
        description = "Час настав. Валтруа готова знищити бар'єр, що охороняє пролом у Святилищі. Я телепортую тебе до пролому, а далі тобі належить убезпечити цю місцину.\n\nВізьми ці кулі телемантії. Якщо знадобиться підтримка, виклич ними Згаслих.\n\nМи маємо вдарити, перш ніж ворог встигне підготувати новий захист. Дай знати, коли будеш готовий, і ми почнемо.",
    },
    [45406] = {
        title = "Лють бурі",
        description = "Більше немає часу готуватися, мить дії настала!\n\nХодімо зі мною, малий. Ти спрямуєш мою ціль, і ми очистимо цей острів громом та блискавкою!",
    },
    [45412] = {
        title = "Захист: допомога Іллідарі",
        description = "На щастя, ми не самі викриваємо плани Легіону проникнути в місто.\n\nКор'вас Бладторн з іллідарі почала сама патрулювати вулиці міста, щоб знайти джерело недавніх нападів.\n\nЯ не цілком довіряю цим «мисливцям на демонів», та принаймні вони довели, що гідні свого імені. Раджу тобі знайти її й дізнатися, що вона викрила, перш ніж Легіон завдасть нового удару.\n\nСпеціалізація: Воїн захисту",
    },
    [45413] = {
        title = "Збір інформації",
        description = "Легіон засилав одного демона за одним, щоб удертися до сховищ Кірін-Тор у місті, але ми не знаємо, чого вони шукають.\n\nСхоже, нарешті вони таки прорвалися всередину.\n\nНам треба швидко з'ясувати, що було викрадено, перш ніж вони встигнуть пустити це в хід.\n\nРозпитай тих, хто вцілів, про все, що знають, — а я своїм примарним зором перевірю, чи не зачаїлися десь поблизу останні демони.",
    },
    [45414] = {
        title = "Підтвердження підозр",
        description = "Це серце — остання вціліла частина верховного лорда Круула, колись одного з найкращих воєначальників Легіону.\n\nБагато років тому армії Круула мало не ринули на Темний портал, щоб розчавити напад Азерота на Позамежжя. Ми, іллідарі, перехопили його, перш ніж він устиг ударити.\n\nБоюся, що Легіон хоче використати серце, щоб пришвидшити воскресіння Круула в Нижньому світі. Ми мусимо негайно знайти пророка Велена — лише він може сказати напевне.",
    },
    [45415] = {
        title = "Між світами",
        description = "Круул несе прокляття, але його сила ще не явила себе вповні. Його прислужники викрали серце, щоб пришвидшити його переродження в Нижньому світі.\n\nУ нас обмаль часу.\n\nВирушай туди, де загинув Круул, до Сходів Долі в спустошеному Позамежжі, де зв'язок з його душею найміцніший. Там ти маєш розкрити шлях до його царства.\n\nЯ мушу підготуватися до прийдешньої битви. Щасти тобі, чемпіоне.",
    },
    [45416] = {
        title = "Повернення верховного лорда",
        description = "У мене є для тебе послання від Кор'вас, а також настанови, як дістатися туди.\n\nЯ можу телепортувати тебе до них, щоб почати бій, але тобі знадобиться кілька осколків Нижнього світу, щоб пробити собі шлях у Викривлена Порожнеча.\n\nКоли матимеш достатньо, поговори зі мною — і можеш починати.",
    },
    [45417] = {
        title = "Нічна Цитадель: володар Ради Тіней",
        description = "Просто зараз Ґул'дан використовує силу Нічного Колодязя, щоб затягнути Саргераса у наш світ.\n\nЗбери своїх соратників і проклади собі шлях на вершину Нічної Цитаделі.\n\nЯ підготую Серце Світла й приєднаюся до тебе, коли настане час.\n\nРазом ми покладемо край Ґул'данові раз і назавжди.",
    },
    [45420] = {
        title = "Нічна Цитадель: Око Аман'Тула",
        description = "Битву виграно, але до кінця війни ще далеко.\n\nЩоб спинити навалу демонів, що ринула в Азерот, ми мусимо використати Стовпи Творіння, аби запечатати Гробницю Саргераса.\n\n<Хадґар вдивляється в Око Аман'Тула.>\n\nЦе... мабуть, важко буде нести.\n\nМожливо, я зможу скористатися силою самого Ока, щоб телепортувати його до Даларана. Що ж, є лише один спосіб дізнатися!",
    },
    [45423] = {
        title = "Скиглячі тваринки",
        description = "Я радий, що ти тут, {name}.\n\nВідколи пробудили Наралекса, у печерах час від часу чути тихе скиглення. Спершу ми гадали, що якісь мутовані тваринки вціліли. Та подальші пошуки показали, що вони ростуть і розмножуються понад наші найсміливіші уявлення. Можливо, до цього причетне тіло Вердана Вічноживого, ми не певні. Тому ми й посилаємо тебе.\n\nНещодавно я також бачив підозрілі сліди, що вели в печери. Можливо, ми тут не самі, тож будь обережний.",
        objectives = "Переможи молоду вічноживу спору в Печерах Лементу.",
        completion = "Так, мені теж трапилася на очі та тіниста постать — вона промчала просто повз мене. Мабуть, таурен, але напевно сказати не можна. Пильнуй за ним: щось мені підказує, що ми лише починаємо розплутувати цю таємницю.",
    },
    [45425] = {
        title = "Назад до гаю",
        description = "Оце ОТ був чудовий вчинок. Тепер, коли ми прибрали командира, друїди й прадавні якийсь час будуть у безпеці. А помста стала приємним додатком.\n\nНам слід повернутися до Рензара й розповісти йому, чого ми досягли.",
    },
    [45426] = {
        title = "Поступ природи",
        description = "{name}, ти мусиш повернутися до Гаю Снів і принести звістку про напад на мене. Скажи іншим друїдам, що такі напади на нас триватимуть, поки ми не знайдемо способу спинити Легіон.\n\nДякую тобі за допомогу. Я відчуваю, як енергія Скверни покидає мої жили, хоча на це й піде якийсь час.",
    },
    [45437] = {
        title = "Нагальна справа",
        description = "Архімаг {name}! У нас важливий гість. Прошу, завітай до моїх покоїв, коли матимеш хвильку.",
    },
    [45439] = {
        title = "Вторгнення... мурлоків?",
    },
    [45440] = {
        title = "Назріває заварушка",
        description = "Вітаю, Грандмайстре. Я майстер у виготовленні мудрованих варив, і ми з Алмай разом із броварнею Штормового Гладуна виготовляємо Штормове вариво для ордену.\n\nВласне, ми вже почали виробництво!\n\nЦе ж привід для свята, чи не так? Ми принесли вдосталь мого преміального Святкового вариво для всіх!",
    },
    [45441] = {
        title = "Ненажерливі личинки",
        description = "Твоє прохання нарубати деревини здається цілком розумним, {name}. Та і для мене знайдеться справа.\n\nІснує вид метеликів, чиї личинки живляться деревами. Зазвичай їх замало, щоб завдати шкоди, але раз на століття вони розмножуються в неймовірній кількості.\n\nЇхнє масове вилуплення щойно почалося. Усі мої доглядачі б'ються з Жахіттям, і відпустити їх я не можу. Боюся, мені не вберегти лісових велетнів самотужки.\n\nЧи розчавиш цих личинок?",
    },
    [45442] = {
        title = "Кепські справи",
        description = "Погляньмо... Насіння ісераліни для зцілення, синцезілля проти отрути і стихійна земля для опору хворобам. О, і дрібка перемеленого скверноцвіту для злагодження.\n\nТак, гадаю, це нейтралізує отруту Легіону. Смакуватиме воно, певно, жахливо, та які ліки бувають інакші?\n\nПоспіши, грандмайстре {name}. Нашим найтяжче ураженим друзям лишилося небагато часу.",
    },
    [45449] = {
        title = "Алхіміня Корлія",
        description = "Фанатиків у Гарнізоні Скверни очолює алхіміня Корлія. Схоже, саме її пивоварка Бланш заскочила за отруюванням нашого варива.\n\nПрошу, вбий її.",
    },
    [45459] = {
        title = "Штурм Легіону",
        description = "Я зробив усе можливе, щоб відбити демонів, але навіть для моєї майстерності їх було забагато...\n\nКоли я лежав при смерті, то почув, як жахолорд наказував алхіміку скверноскорнів отруїти мій напій, а тоді повернутися на Розбитий берег.\n\nЯкби ти роздобу$p(в:ла) трохи тієї отрути, ми б напевне змогли зварити протиотруту!",
    },
    [45472] = {
        title = "Яйця кракена",
    },
    [45473] = {
        title = "Гігантська проблема",
        objectives = "Знищ Корабель.",
    },
    [45482] = {
        title = "Аркана: доля Хвилескорнів",
        description = "Учора зі Штормгейму прибув розвідник із важливою знахідкою — цими стародавніми сувоями. У них міститься пророцтво валькір про нову правительку врайкулів — таку, що могла б повернути Хвилескорнів проти Легіону.\n\nСправу ускладнює те, що ця врайкулка, можливо, і є спадкоємицею Сковальда.\n\nВізьми сувої, знайди спадкоємицю і приведи її до валькір. Гадаю, вигнанці, про яких вони згадують, — це врайкули Яндвіка, тож почати варто звідти.\n\nСпеціалізація: маг Аркани",
    },
    [45486] = {
        title = "Неохоча королева",
        description = "Стривай, звідки ти знаєш про моє походження? Будь обережний зі словами тут — є ті, хто полював би на мене, якби дізнався про мій родовід.\n\nЯ не знаю, хто ти, і не вірю, що я частина якогось пророцтва. Та якщо ти прагнеш виправити шкоду, якої мій батько завдав Хвилескорнам, то я почуваюся зобов'язаною тобі допомогти.\n\nЗустріньмося у Вальдісдаллі, {class}. Звідти ми зможемо дістатися Скольд-Ашілу і попросити аудієнції в Ейїр. Можливо, вона проллє світло на це пророцтво.",
    },
    [45498] = {
        title = "Не буди лиха, поки спить тихо",
        description = "Бачиш отих здоровезних ередарів? Ось у тому кургані тримають Ґолдринна! Не знаю, що Легіон із ним там робить, але я певен — їм не можна дати в цьому досягти успіху.\n\nПробираймося туди і рятуймо Ґолдринна!",
    },
    [45520] = {
        title = "За ворожими порталами",
    },
    [45522] = {
        title = "Змусити Кісткомовців замовкнути",
        description = "Право Сіґрін на трон оскаржать двоє суперників — рунопровидець Фальяр з Кісткомовців і ярл Вельбранд із Дрекір'ярів.\n\nЯ почав би в Гауствальді з рунопровидця. Він був близьким союзником Сковальда і могутній містик. З Кісткомовцями під рукою він стане затятим супротивником, якщо його не вдасться змусити скоритися.\n\nІди ж і здобудь своє призначення в ім'я валькір!",
    },
    [45523] = {
        title = "Приборкати Дрекір'ярів",
        description = "Слова Кісткомовця непокоять мене, $p(чужинцю:чужинко). Темрява, про яку він каже, скверняне прокляття Сковальда, — невже він якось передав його мені?\n\nНі, цього не може бути. Рунопровидець, певно, помиляється...\n\nХодімо, наступний претендент чекає. Без сумніву, мені знадобиться твоя допомога, щоб і його упокорити.",
    },
    [45524] = {
        title = "Забутий спадкоємець",
        description = "Мій брат... живий?\n\nКоли я бачила його востаннє, убивці брали його в кільце. Я й уявити не можу, як він їх здолав...\n\nНам слід вирушити до Вректа. Я хочу побачити брата на власні очі.",
    },
    [45525] = {
        title = "Питання без відповідей",
        description = "Що зроблено, те зроблено. Більше немає нікого, хто оскаржив би трон Хвилескорнів.\n\nПроте слова мого брата досі переслідують мене. Якщо Ейїр знає, хто наказав убити мою родину, я заслуговую це знати.\n\nХодімо, повертаймося.",
    },
    [45526] = {
        title = "Лють Богині-Королеви",
        description = "{class}, Кірін-Тор знайшли спосіб провести тебе в Зали Доблесті, щоб ти наздогна$p(в:ла) спадкоємицю Бога-Короля. Архімаг Хадґар просив мене наголосити, наскільки важливо спинити Сіґрін, адже пророцтва натякають, що вона досі може бути ключем до об'єднання Хвилескорнів проти Легіону.\n\nЩоб телепортувати тебе просто до Залів, знадобиться неймовірно багато енергії, тож переконайся, що ти готов$p(ий:а). Може минути чимало часу, перш ніж ми зможемо відправити тебе знову.\n\nЗвернися до мене, коли будеш готовий вирушати.",
    },
    [45527] = {
        title = "Прощення Ейїр",
        description = "Вибач за все, через що я змусила тебе пройти, $p(чужинцю:чужинко). Після того, що я тут накоїла, боюся, усе це могло бути марно.\n\nХодімо зі мною назад до Скольд-Ашіл. Там я прийму будь-який вирок, який Ейїр вважатиме справедливим для мене.",
    },
    [45528] = {
        title = "Осквернені кургани",
        description = "Ти барився надто довго, тож я взяла на себе сміливість розвідати кургани заздалегідь. Легіон установив портали й щомиті протягує крізь них усе більше й більше демонів. Ми мусимо їх позакривати, щоб урятувати Ґолдринна!\n\nНе певна, що мої звичні методи зарадять із їхнім знищенням, але я думаю, ти впораєшся! Гадаю, тут згодиться добряча робота з лозами.",
    },
    [45531] = {
        title = "Повзуча Скверна",
    },
    [45532] = {
        title = "Накази Матері",
        description = "Та велика потвора, схоже, очолює тутешній напад. Ану завалимо її!",
    },
    [45534] = {
        title = "Спільний ворог",
        description = "Маю до тебе ще одне прохання, $p(чужинцю:чужинко).\n\nПовернися до своїх очільників і розкажи їм про те, що тут сталося. Хоч твій народ, можливо, ніколи й не стане справжнім союзником Тайдескорнів, знай: у нас є спільний ворог — і з ним мій народ боротиметься до останнього врайкула.\n\nКоли настане час, сподіваюся побачити тебе на полі бою.",
    },
    [45536] = {
        title = "Інтерфейс щотижневого завдання 2 на 2",
    },
    [45537] = {
        title = "Інтерфейс щотижневого завдання 3 на 3",
    },
    [45538] = {
        title = "Інтерфейс щотижневого завдання 10 на 10",
    },
    [45539] = {
        title = "Виклик на бій улюбленців: Печери Лементу",
        description = "Здичавілі звірята Печер Лементу й далі плодяться у вологій темряві, та я роблю все можливе, щоб тримати їхню кількість під контролем.\n\nПрочищаючи печери, я знайшов кількох улюбленців і трохи припасів. Я, мабуть, ладен розлучитися з мішком припасів, якщо ти перевершиш мій найкращий прохід.\n\nЩоб мене побороти, тобі доведеться зачистити печеру, не зцілюючи й не воскрешаючи жодного зі своїх улюбленців. Щасти!",
        objectives = "Переможи молоду вічноживу спору в Печерах Лементу.",
        completion = "Ого, оце так! Ось торба з припасами — ти чесно її заслуговуєш! Вибач за вогкість.",
    },
    [45540] = {
        title = "Поклик із печер",
        description = "О, добре, я радий, що ти завіта$p(в:ла). До нас дійшли тривожні чутки, що в Печерах Лементу й далі шириться скверна. Ти, схоже, саме та людина, що зможе це розслідувати.\n\nВідколи Наралекс пробудився, одна з його учениць наглядає за цими краями, щоб тримати здичавілих створінь під контролем. Саме вона надсилає нам ці страшні застороги.\n\nЗустрінься з нею в оці схожої на череп скелі над Печерами Лементу й поглянь, чи зможеш допомогти їй із цією ситуацією.",
        objectives = "Знайди Муяні в схожій на череп скелі над Печерами Лементу.",
        completion = "Дякую, що ти тут. Маю цікаві новини про те, що коїться в Печерах Лементу, відколи Наралекс прокинувся.",
    },
    [45541] = {
        title = "Як ТОБІ таке?!",
    },
    [45542] = {
        title = "За ворожими порталами",
    },
    [45545] = {
        title = "Метання бочок",
        description = "Легіон захищає лігво Фелскорнів випромінювачами скверни. На щастя, у нас є вдосталь Штормового вариву, тож має стачити, щоб їх знищити.\n\nВізьми цю бочку, кинь її в розпилювачі й дивись, як вони злетять у повітря з гучним БУМ!",
    },
    [45549] = {
        title = "Зцілення скверни",
    },
    [45550] = {
        title = "Зцілення скверни",
    },
    [45551] = {
        title = "Згубні наслідки",
        description = "Палаючий Легіон не вгамується, доки не знищить геть усе й усіх. Його присутність тут уже згубно вплинула на наші землі, а тепер, схоже, і на нашу звірину.\n\nЯ чув численні звістки про хворих тварин у хащах, що оточують захоплене демонами місто Сурамар.\n\nВирушай туди й перевір, чи правдиві ці чутки.",
    },
    [45552] = {
        title = "Загоєння ран",
        description = "<Рани Д'Бінна не дають йому рухатися.>\n\nМабуть, ти зможеш знайти десь поблизу щось, що загоїть рани манашаблезуба?",
    },
    [45553] = {
        title = "Нічна Мисливиця кличе",
        description = "<Д'Бінн нашорошується, зачувши голос своєї господині. Мордою він наполегливо штовхає твою руку, запрошуючи скочити йому на спину.>",
    },
    [45554] = {
        title = "Перебрати владу",
        description = "Я марнію в цій клітці, бранка негідника на ім'я Рейлн.\n\nВін очолює гурт нічнонароджених, які вдаються до магії скверни, щоб опоганювати й підкоряти тутешню звірину.\n\nВплив Палаючого Легіону вже поширився надто далеко, як на мене.\n\nУбий його й забери його кулю контролю, щоб мене звільнили з цієї арканної в'язниці!",
    },
    [45555] = {
        title = "Скверноскуті звірі",
        description = "То Рейлн виконує накази Лексери? І чого я не дивуюся. Вона почувалася аж надто спокійно поряд із демонами, що захопили наше місто.\n\nМи не можемо дозволити їй опоганити звірину Сурамару. Я присяглася захищати місто Сурамар від усіх ворогів, навіть тих, що в його мурах.\n\nЯкщо ти впораєшся з її звіроловами, я зроблю все можливе, щоб вистежити Нічну Мисливицю Лексеру.",
    },
    [45556] = {
        title = "Готовність до удару",
        description = "Я вистежив одного з ловців, який, сам того не відаючи, привів мене до Розбитого узбережжя. \n\nТам була Лексера, оточена армією демонів і відданих нічнонароджених.\n\nПідібратися ближче я не зміг, але, наскільки можу судити, вона зі своєю армією ловців приборкує спотворених Скверною звірів.\n\nЦе наруга над природою, і її треба зупинити!\n\nЗустрінь мене на Розбитому узбережжі й будь готовий до удару. Я назбираю ще манакореня. Маю передчуття, що він нам знадобиться.",
    },
    [45557] = {
        title = "Неприродні наслідки",
        description = "Лексера та її ловці захопили долину.\n\nВона сильніша, ніж здається, {name}, і б'ється з міццю жахолорда. Не йди туди непідготовленим. \n\nЯ впораюся з цими демонами. Іди, знайди Лексеру й дай їй відчути наслідки її неприродних діянь.",
    },
    [45559] = {
        title = "За ворожими порталами",
    },
    [45560] = {
        title = "Руйнування: Гуркіт біля Скверн-тотемів",
        description = "Високогірні передали грізне попередження від своїх союзників-дроґбарів. Скверн-тотеми поширюють свою демонічну скверну на дику природу довкола, заражаючи саму землю. Ми вважаємо, що цим варто зайнятися радше раніше, ніж пізніше.\n\nВождь дроґбарів, Наварроґґ, особисто займається цією справою, і ми хотіли б, щоб ти зустрі$p(вся:лася) з ним біля селища Скверн-тотемів.\n\nСпеціалізація: Чорнокнижник Руйнування",
    },
    [45561] = {
        title = "Знайди мене",
        description = "Лист від Максиміліана написаний на чомусь, що скидається на клапоть, відірваний від корабельного вітрила. До нього додано вказівки до пляжу на півночі Високогір'я.",
    },
    [45562] = {
        title = "На коліна, зброєносцю!",
        description = "Ти маєш стати переді мною на коліна, якщо ми знову вирушимо в дорогу разом. На коліна, зброєносцю, і прийми це звання!",
    },
    [45563] = {
        title = "Оповита монета",
        description = "Клубочиться туман огортає монету, і вона починає ширяти над твоєю долонею. Туман на мить розступається, відкриваючи блискучу нову монету, та наступної ж миті монета здається стертою за роки обігу. Коли монета знову лягає тобі в долоню, у твоєму розумі зринають видіння джунглів і оповитих туманом вершин, і крізь видіння ти впізнаєш чотирьох Небожителів, що зібралися у дворі острова.",
    },
    [45564] = {
        title = "Палаючі птахи",
        description = "Скверн-тотеми ставлять досліди на цих фалькозаврах! Вони не досягли бажаних результатів і недбало покинули свої піддослідні матеріали валятися, ще більше отруюючи тварин.\n\nНам слід зібрати їхні покинуті тотеми, щоб запобігти подальшій скверні й дізнатися, що вони робили.",
    },
    [45565] = {
        title = "Подальше навчання",
        description = "Дорога сюди була небезпечна, зброєносцю. Вона була сповнена загроз. Шторми, демони, штормові демони... Здригаюся від самого спогаду. Звісно, я подолав усі ці небезпеки ціною великих втрат для себе. Ось тут мені й потрібна твоя допомога.\n\nТи маєш вирушити — ба ні, відважно ринути — і повернути мою броню, мою зброю і, звісно ж, мого величного скакуна. Щойно ти успішно виконаєш ці три завдання, тебе підвищать до зброєносця першого класу!",
    },
    [45566] = {
        title = "Лицарські пожитки",
        description = "Серед шквалів і навальних хвиль мій могутній корабель хитало й кидало. Лицарі меншого штибу тремтіли б від жаху, заклякнувши на місці. Тільки не я! Аж ніяк! Героїчно я зняв із себе броню й надійно сховав її у свій мішок. \n\nЧому я роздягся до цієї простої білизни, питаєш? Так спитав би лише невіглас-зброєносець. Я остерігався піти на дно, якби мій корабель зазнав лиха, авжеж! Ха-ха! \n\nНа жаль, мішки з бронею змило за борт хвилями.",
    },
    [45567] = {
        title = "Королівство за коня",
        description = "Ох, горе мені! Невдовзі після висадки на берег я почав досліджувати околиці, в'їхавши на своєму вірному скакуні Піменто в самісіньке серце захопленого демонами селища на півночі. Поки я провадив свої розшуки, я прив'язав Піменто, щоб іти далі пішки, та повернувшись, виявив, що могутній демон захопив її! Ось він, верхи на ній, наче вона його власна. Прошу, знайди її та поверни до мене.",
    },
    [45568] = {
        title = "Вони вкрали Екскаліберто!",
        description = "Я вів розвідку в найближчому селищі демонів, коли на мене напали. Вони забрали мій артефакт! Звісно, якщо я піду звідси, узбережжя лишиться без захисту. Артефакт у демонів поблизу. Іди, убий їх і поверни його мені!",
    },
    [45570] = {
        title = "У надійніших руках",
        description = "Лишається ще справа з Іриссю Зосередження. Прошу, поверни її твоїм друзям із Кірін-Тор разом із моїми вибаченнями.\n\nЩо ж до мене, гадаю, я на якийсь час досить погнався за артефактами. Однієї одержимості безсмертним тіньовим злом мені цілком вистачить, красно дякую.",
    },
    [45571] = {
        title = "Трохи шпигунства",
        description = "Порох уже з нами, тож час переходити до наступного плану. Зустрінемося на Розбитому березі. \n\nЗ Посадкового майданчика Красуса можна вилетіти просто до нашого наступного місця. Там ми тебе й чекатимемо, {class}t.",
    },
    [45572] = {
        title = "Тримаємо позиції",
        description = "Ми хоч і очікували сильної присутності Легіону, та наші напади на їхні табори розлютили їхні війська ще дужче, ніж ми передбачали. Наші сили збираються і на землі, і в небі над Громовим Тотемом, аби повернути собі опору.\n\nЗроби все можливе, щоб зменшити їхні лави. Щойно ми втримаємо Громовий Тотем, почнемо готувати остаточний удар.",
    },
    [45573] = {
        title = "Підіймайся",
        description = "Ось ми й на місці, {class}t. На цьому острові є печера, повна надзвичайно могутніх демонів та їхніх ватажків. Якщо наш план удасться, цих демонів... «рознесе на друзки», як гарно висловився Тетіс.\n\nЗараз немає часу пояснювати план повністю, але Тесс погодилася провести тебе крок за кроком. Спершу тобі треба піднятися на верх цього схилу. Дорогою поклади кількох ворогів.",
    },
    [45574] = {
        title = "Інгредієнти Скверни",
        description = "Наші розвідники виявили табір Скверноскорнів у Гарнізоні Скверни. Нам знадобиться якомога більше зразків отрути Скверни, якщо ми хочемо зварити ліки для наших уражених монахів.\n\nБери зразки всього, що бодай трохи виглядає корисним!",
    },
    [45575] = {
        title = "Селище спотворювачів",
        description = "Скверно-Тотеми й далі створюють ці тотеми для нових «експериментів». Розберімося з цими вливальниками за давнім звичаєм.\n\nЇхня смерть виправить велике зло й дасть підказки про їхню кінцеву мету.",
    },
    [45576] = {
        title = "Підіймайся",
        description = "Ось ми й на місці, {class}t. На цьому острові є печера, повна надзвичайно могутніх демонів та їхніх ватажків. Якщо наш план удасться, цих демонів... «рознесе на друзки», як гарно висловився Тетіс.\n\nЗараз немає часу пояснювати план повністю, але Ліліан погодилася провести тебе крок за кроком. Спершу тобі треба піднятися на верх цього схилу. Дорогою поклади кількох ворогів.",
    },
    [45586] = {
        title = "Підсилення щита",
        description = "Не завадить ще трохи зміцнити щит Каменя Душі Нічнонароджених, а для цього ми маємо наповнити його енергією.\n\nРіанна запевнила мене, що есенція Скверни чудово згодиться для наших потреб. Так, цей метод і справді доволі огидний. Але, як добре знають сін'дорей, відчайдушні часи вимагають відчайдушних заходів.\n\nУсе просто: нам конче потрібна магічна енергія, а наші вороги мають її вдосталь.\n\nЗроби те, що мусиш.",
    },
    [45587] = {
        title = "Загроза Скверно-Тотемів",
        description = "Якби я знав, що Туґар живий і стоїть за всім цим, то попередив би тебе раніше! Це сповнене ненависті створіння, легка здобич для справи Легіону.\n\nЯкщо він і справді досягне успіху зі своїми дослідами Скверни, ми мусимо спинити його зараз. Він глузує з нас отам, нагорі. Ходімо!",
    },
    [45614] = {
        title = "Леді Ремор'за",
        description = "Наші союзники доповіли про ковен надзвичайно могутніх відкличників Скверни, що засіли на Терасі Сліз.\n\nЇхня очільниця, леді Ремор'за, та її послідовники — знавці прадавньої магії нічнонароджених і можуть ставати майже невразливими до атак.\n\nПроте нам, магам, до снаги здолати їх за допомогою Крадіжки заклять. Покажімо їм міць Тирісгарди!",
    },
    [45615] = {
        title = "Хто знайшов, того й здобич",
        description = "Ти лиш поглянь на це місце? Суцільний безлад! Куди не глянь — самі купи арканного пилу!\n\n<Аказамзарак широко всміхається.>\n\nЦі бідолахи й не уявляють, чого варта ця штука!\n\nОсь що я тобі скажу: якщо допоможеш мені прикликати кілька мітел, щоб позмітати це золото в порошку, я поділю прибуток із тобою — 80 на 20.",
    },
    [45626] = {
        title = "Зладнай собі бомбу!",
    },
    [45627] = {
        title = "Падіння Скверно-Тотемів",
        description = "Наш зв'язковий у Високогір'ї, Наваррогґ, повідомляє, що Туґар Кривавий Тотем нарешті знову об'явився.\n\nВін надіслав мені кристал-повідомлення разом із деякими настановами.\n\nЯ можу телепортувати тебе до Наваррогґа, і він проведе тебе до місця, де перебуває Туґар, але є одна проблема.\n\nНаваррогґу потрібна додаткова магічна сила, щоб відбити магію Скверни Туґара. Перед відходом тобі знадобиться кілька Уламків Нижнечестя.",
    },
    [45628] = {
        title = "Цього разу залиш слід",
        description = "Ти готовий, {class}t? Я проведу тебе через кожен крок плану. Тобі нічого не загрожуватиме! Найперше: бачиш отой спусковий пункт позаду мене? Це твій шлях униз, у печеру. Щасти!",
    },
    [45629] = {
        title = "Цього разу залиш слід",
        description = "Ну, була не була, {class}t. Якщо хтось і впорається з цим, то це ти! ...Напевно. Просто скористайся точкою спуску позаду мене, щоб потрапити в печеру.\n\nЩо? Не роби такого обличчя. Дам тобі решту вказівок, коли будеш у печері.",
    },
    [45630] = {
        title = "Нічий слуга",
        description = "Мені подобається працювати з тобою, {name}. Як щодо того, щоб і далі заробляти золото разом?\n\nВерховний маг Хадґар витрачає неймовірно багато часу, відсилаючи своїх слуг робити невідомо що. А що, як заповзятлива парочка на кшталт нас знайде дешевшу заміну?\n\n<Аказамзарак простягає тобі невеличкий кристал.>\n\nЦей красень створить слугу буквально з повітря - і кількох фунтів пилу, який ти позаміта$p(в:ла).\n\nЧому б не взяти його в місто й не випробувати? Сам побачиш!",
    },
    [45632] = {
        title = "Зник безвісти: Ейтріґґ",
        description = "Ти знаєш Ейтріґґа? Це гідний воїн-орк, який вів наші сили проти наг Скверногніву неподалік.\n\nНа жаль, під час нещодавньої сутички наги захопили багатьох наших солдатів. Ейтріґґ кинувся за ними й не повернувся. Боюся, з ним сталося щось жахливе.\n\nБудь ласка, спробуй його знайти!",
    },
    [45633] = {
        title = "Операція \"Скверногнів\"",
        description = "Мені не до вподоби, що наги стали на бік Палаючого Легіону. Це щось нове, і цього не можна ігнорувати.\n\nВоєначальник наг Каз'джатар і його прислужник-скрог, Скверноборід, відповідальні за напади Скверногніву на наші сили.\n\nМи маємо навчити їх, що злигатися з демонами - собі дорожче!",
    },
    [45634] = {
        title = "Квалдири напоготові",
        description = "Ти наповнив силою Ріг Гел'ї в Гельгеймі, і тепер настав час ним скористатися. Я виявив три портали Легіону, які нам слід знищити.\n\nВідшукай уламок врайкульського корабля на узбережжі Скверногніву. Поклич квалдирів і доручи їм робити те, що вони вміють найкраще: руйнувати!",
    },
    [45637] = {
        title = "М'ясо піщаного черв'яка",
        description = "Щоб розбудити колосів, треба ціла купа м'яса. На щастя для тебе, Силітус аж кишить піщаними черв'яками, а колосам, схоже, їхній смак до вподоби.",
    },
    [45638] = {
        title = "Хрусткі павучі лапи",
        description = "Нам потрібне м'ясо - будь-яке м'ясо - щоб годувати колосів. А немає дешевшого м'яса за павуче. Його повно в Позамежжі.",
    },
    [45639] = {
        title = "Охолоджене м'ясо",
        description = "Звірі Нордськолу великі, важкі й повні м'яса. Іди й знайди щось, чим ми зможемо нагодувати колосів.",
    },
    [45640] = {
        title = "Хвости крокаліска",
        description = "Крокаліски Ульдуму відомі тим, що більші за всіх інших. Коли тобі терміново потрібно багато м'яса, вони завжди гарний вибір.",
    },
    [45641] = {
        title = "Сирі тигрячі стейки",
        description = "Далеко на півдні, у Пандарії, тигри жиріють, полюючи на дрібнішу звірину. Принеси мені трохи їхнього м'яса.",
    },
    [45642] = {
        title = "Сире м'ясо рохокопита",
        description = "Ґорчук каже мені, що давні орочі клани Дренору цінували рохокопита за його розміри - однієї здобичі вистачало, щоб нагодувати ціле село на ніч.",
    },
    [45643] = {
        title = "Пісні гомілки",
        description = "Нам потрібне м'ясо, і багато. Ти виглядаєш доволі міцним - може, вполюєш кількох звірів на Розбитих островах?",
    },
    [45644] = {
        title = "О Долоріє, моя люба Долоріє",
        description = "Чудово! Ми ж бо доволі хвацька пара шукачів пригод, чи не так?\n\nТепер, коли мої речі в безпеці, перед нами відкривається новий шлях. Я ж прибув сюди не лише для того, щоб дати відсіч вторгненню демонів, ні! Я прийшов у пошуках моєї коханої, моєї любої Долорії. Спочиваючи між полюваннями на драконів, я бачив сон, ні, видіння. Воно повідало мені, що Долорію викрали й забрали до міста, що ширяє в небі!\n\nЦе має бути Даларан. Хутчіш, зброєносцю! Сідай у сідло й зустрінь мене в славетній корчмі Даларана. Поспішай!",
    },
    [45645] = {
        title = "Марна справа",
        description = "Ну так, авжеж, мене, гм, тримають тут проти моєї, ну, волі, чи якось так.\n\nСлухай, $p(друже:подруго), між нами кажучи, старий Макс не має жодних шансів, але серце в нього на місці. Я весь час намагаюся втекти й сховатися, а він усе одно мене знаходить! Просто не можу зважитися засмутити його правдою.\n\nУ мене є ідея. Чому б тобі не вбити кілька отих здоровенних двоголових \"Пагорбових бандитів\"? Скажімо, вони вкрали в мене коштовності, а ти зможеш викупити нею мою свободу.\n\nНе квапся, бережи себе. Хоч трохи.",
    },
    [45647] = {
        title = "Місія: пошук і порятунок",
        description = "Я змушу цих наг заплатити за їхнє зухвальство. \n\nВони та їхні прислужники-скроги захопили наших воїнів, поки ми билися з Легіоном. Немає в них честі!\n\nМи мусимо врятувати наших полеглих солдатів, перш ніж їх продадуть у рабство, або щось гірше...",
    },
    [45648] = {
        title = "Зник безвісти: лорд Даріус Кровлі",
        description = "Чи знайомий ти з лордом Даріусом Кровлі? Це достойний гілнеаський воїн, який вів наші сили проти наг Скверногніву неподалік. \n\nНа жаль, нещодавно в сутичці наги захопили багатьох наших солдатів. Лорд Даріус кинувся навздогін і не повернувся. Боюся, з ним сталося щось жахливе.\n\nБудь ласка, спробуй знайти його!",
    },
    [45649] = {
        title = "Місія: пошук і порятунок",
        description = "Я змушу цих наг заплатити за їхнє зухвальство. \n\nВони та їхні прислужники-скроги захопили наших воїнів, поки ми билися з Легіоном. Немає в них честі!\n\nМи мусимо врятувати наших полеглих солдатів, перш ніж їх продадуть у рабство, або щось гірше...",
    },
    [45650] = {
        title = "Операція \"Скверногнів\"",
        description = "Мене дуже непокоїть звістка про те, що наги об'єдналися з Палаючим Легіоном. Це щось нове, і цього не можна ігнорувати.\n\nВоєначальник наг Каз'джатар та його прихвостень-скрог Сквернобородий відповідальні за напади Скверногніву на наші сили.\n\nМи мусимо навчити їх, що злигатися з демонами не варто!",
    },
    [45651] = {
        title = "Руїни Ан'Кіражу: Оссиріан",
    },
    [45652] = {
        title = "\"Скромне\" прохання",
        description = "{class}е, до нас завітала... гостя. Вона вимагає впустити її, але варта не пропустить її без дозволу.\n\nБудь ласка, піднімися на оглядовий майданчик, щойно зможеш.",
    },
    [45653] = {
        title = "Спали його вогнем!",
    },
    [45654] = {
        title = "Ан'Кіраж: Ктун",
    },
    [45655] = {
        title = "Колос Аші",
    },
    [45656] = {
        title = "Слабкі вітрові камені",
    },
    [45657] = {
        title = "Силітист",
    },
    [45674] = {
        title = "Колос Реґала",
    },
    [45675] = {
        title = "Колос Зори",
    },
    [45694] = {
        title = "Арахноцид",
    },
    [45706] = {
        title = "Сила тисяч",
        description = "Я знаю, що мене тут не надто люблять, і ні мене, ні моїх Грозототемів не запрошували приєднатися до тебе й твоїх шаманів. Та все ж я приходжу до тебе з пропозицією.\n\nЛегіон нападає на мою домівку. Я втратила деякі речі, що... дорогі мені, і мені більше нема до кого звернутися. Мені боляче просити... але я прошу твоєї допомоги. Якщо допоможеш, я віддам свій народ на службу проти Легіону.",
    },
    [45723] = {
        title = "Гнів старої",
        description = "Ці демони приходять у мою домівку, забирають мої речі й полонять мій народ? Вони зазнають мого гніву. Знищ їх, дитино. Бодай на це ти ж здатна.",
    },
    [45724] = {
        title = "Змії та камені",
        description = "Коли напали демони, вони захопили дві мої вельми могутні цінності: мого супутника Арікару та Камінь Загибелі.\n\nХоч смерть для Арікари нічого не значить, Легіон напевно має на нього лихі плани. А Камінь Загибелі... такий могутній артефакт належить у моїх руках, а не в їхніх. Ми мусимо розділитися, щоб знайти їх.\n\nЗаради світу, будь обережна. Не хочу, щоб ти незграбно знищила геть усе.",
    },
    [45725] = {
        title = "Розбиваючи кайдани",
        description = "Легіон не пошиє Грозототемів у дурні. Звільни мій народ, і ми вшануємо тебе своєю допомогою в прийдешній битві.",
    },
    [45726] = {
        title = "Зіпсоване болото",
        description = "Я ще не зміг розвідати, що в селищі, проте на півдні відбуваються небезпечніші досліди. Вони опоганювали неспокійних духів боліт іще більшою магією Скверни!\n\nЯ переробив цей тотем Скверни, щоб він витягнув із тих духів енергію Скверни, якою їх просякли.\n\nБудь ласка, зціли стільки духів, скільки зможеш, можливо, це навіть дарує їм трохи спокою.\n\nЯкщо хочеш, я навіть можу відправити тебе туди!",
    },
    [45727] = {
        title = "Об'єднання островів",
        description = "Тут, на Розбитих островах, є безліч фракцій. Ми мусимо об'єднати їх, якщо хочемо мати бодай шанс проти Легіону. Доведи їм свою цінність і повертайся до мене зі звітом.",
        objectives = "Поговори з Архімагом Хадґаром у Даларані.",
        completion = "Чудова робота, {name}. Нам ще довгий шлях попереду, щоб очистити цей світ від Легіону, але це наближає нас на крок.",
    },
    [45729] = {
        title = "М'ясо піщаного черв'яка",
        description = "Щоб переконати велетенських колосів Силітуса прокинутися, потрібна ціла гора м'яса. На щастя для тебе, Силітус аж кишить піщаними червами, а колосам їхній смак, схоже, цілком до вподоби!",
    },
    [45730] = {
        title = "Хрусткі павучі лапи",
        description = "Нам потрібне м'ясо — будь-яке м'ясо — щоб годувати колосів... а немає дешевшого м'яса за павуче. Його ти знайдеш удосталь у Позамежжі.",
