    [45793] = {
        title = "Навала окультистів",
    },
    [45794] = {
        title = "Повідомити Раду",
        description = "Я подбаю про цього бранця, а ти маєш повернутися до Розлому Жахошраму.\n\nРозкажи іншим про те, що ми виявили. Нам знадобиться їхня допомога, щоб упоратися з Канретадом на Розбитому березі.",
    },
    [45795] = {
        title = "Присутність сили",
        description = "Демони, схоже, черпають давню силу всередині самого Храму. Їм удалося спотворити й осквернити цю священну землю магією Скверни.\n\nМи мусимо знищити демонічну присутність, перш ніж розпочати наш останній наступ.",
    },
    [45796] = {
        title = "Знищення гнізда",
        description = "Ми мусимо покласти край задуму Туґара. Ці потвори мають бути знищені, як і їхнє джерело!\n\nГадаю, я знаю, де воно. Неподалік мав поселення загін нейтральних дроґбарів, але об'єднана атака демонів і тавренів Скверни вигнала їх звідти. Це напевно те саме місце.\n\nВирушай туди й зупини виробництво їхніх чудовиськ Скверни просто біля джерела!",
    },
    [45797] = {
        title = "Гра із зеленим вогнем",
    },
    [45798] = {
        title = "Вар'зуул Підбурювач",
        description = "Там нагорі сстирчить якийсь огидний володар демонів, що репетує вже багато годин.\n\nЧи не міг би ти нарешті стулити йому пельку? У мене від нього страшенно болить голова!",
    },
    [45804] = {
        title = "Бісенашестя!",
