    [46173] = {
        title = "Тактичне планування",
        description = "Полководче битви {name}! Нам слід обговорити наші подальші кроки!",
    },
    [46175] = {
        title = "Гуркітливий грім",
    },
    [46176] = {
        title = "Зачеплений верховний маг",
        description = "Тепер, коли бар'єр розвіяно, верховний маг Ксайлем нарешті в межах досяжності!\n\nСподіваймося, він охоче поверне Іриду...",
    },
    [46177] = {
        title = "На відстані порталу",
        description = "Ксилем, може, і втік, але слід його порталу лишився.\n\nТепер, коли ти звільни$p(в:ла) його учнів від темного впливу, я поставлю їх до праці — нехай шукають спосіб дістатися до нього. Щойно щось знайду — сповіщу Кірін-Тор.\n\nПрошу лише про одне: коли зійдешся з архімагом віч-на-віч, спробуй зберегти йому життя. Я вірю, що добра людина, якою він колись був, досі живе під тінню, що ним заволоділа.\n\nПрощавай, {name}.",
    },
    [46178] = {
        title = "Сховатися на видноті",
        description = "Вітаю, Тіньовий клинку.\n\nСподіваюся, ти не надто гніваєшся, що я почала без тебе, — мені трохи важко стримуватися поряд із безмозкою нежиттю.\n\nТак, ти все правильно почув. Таерір, той самий Таерір, що ось уже багато місяців стояв у Залі Тіней, був нежиттю-пішаком жахолорда.\n\nІ таких, як він, ще більше — у наших містах, вони підіймаються в лавах аристократії, набираються сили й впливу, і їх майже неможливо викрити.",
    },
    [46179] = {
        title = "Знищити Легіон",
