    [46777] = {
        title = "Щедроти Легіонопаду",
        completion = "Верховний лорде, завдяки твоїм зусиллям наші сили змогли здобути додаткові ресурси з поля бою.\n\nЧим більше ти пануватимеш на полі бою, тим більше ресурсів зможуть виділити наші сили.",
    },
    [46778] = {
        title = "Подальший розвиток",
        description = "Що далі триває війна проти наших ворогів, то більше мусимо рости й ми.\n\nТепер ми можемо проводити нові дослідження. Знайди Ейнара Рунотворця, щоб і далі розвивати Залу ордену.",
    },
