    [46791] = {
        title = "Принесений вітром",
        description = "Далекозорче {name}, консул Целестос просить тебе повернутися до Вирому. Прийди до нього якнайшвидше.",
    },
    [46792] = {
        title = "Збір бур",
        description = "Тандераан попросив мене відправити тебе до Престолу Чотирьох Вітрів, щоб допомогти йому в одній справі.\n\nЗвернися до мене знову, коли будеш готовий вирушати, Далекозорче.",
    },
    [46794] = {
        title = "Взірець Двору",
        description = "Вдячний Двір Фарондіса просить тебе прийти. Вони хочуть нагородити тебе за твою виняткову допомогу.",
    },
    [46796] = {
        title = "Взірець Високогір'я",
        description = "Вдячні племена Високогір'я просять тебе прийти. Вони хочуть нагородити тебе за твою виняткову допомогу.",
    },
    [46797] = {
