    [47119] = {
        title = "Гробниця Саргераса: Звільнити змучених",
        description = "Душі всередині Гробниці спотворює Машина Жаху. Знищ її та звільни їх від цих страждань.",
    },
    [47120] = {
        title = "Гробниця Саргераса: Звільнити змучених",
        description = "Душі всередині Гробниці спотворює Машина Жаху. Знищ її та звільни їх від цих страждань.",
    },
    [47121] = {
        title = "Гробниця Саргераса: Звільнити змучених",
        description = "Душі всередині Гробниці спотворює Машина Жаху. Знищ її та звільни їх від цих страждань.",
    },
    [47122] = {
        title = "Гробниця Саргераса: Полеглий Аватара",
        description = "Лише Полеглий Аватара стоїть на нашому шляху до останньої битви. Убий його — і покінчимо з цим.",
    },
    [47123] = {
        title = "Гробниця Саргераса: Полеглий Аватара",
        description = "Лише Полеглий Аватара стоїть на нашому шляху до останньої битви. Убий його — і покінчимо з цим.",
    },
    [47124] = {
        title = "Гробниця Саргераса: Полеглий Аватара",
        description = "Лише Полеглий Аватара стоїть на нашому шляху до останньої битви. Убий його — і покінчимо з цим.",
    },
    [47125] = {
        title = "Гробниця Саргераса: Полеглий Аватара",
        description = "Лише Полеглий Аватара стоїть на нашому шляху до останньої битви. Убий його — і покінчимо з цим.",
    },
    [47126] = {
        title = "Гробниця Саргераса: Дурисвіт",
        description = "Печатку носять лише найпотужніші з його слуг, і вона свідчить про присутність Дурисвіта, Кіл'джедена. Його треба здолати.",
    },
    [47127] = {
        title = "Гробниця Саргераса: Дурисвіт",
        description = "Печатку носять лише найпотужніші з його слуг, і вона свідчить про присутність Дурисвіта, Кіл'джедена. Його треба здолати.",
    },
    [47128] = {
        title = "Гробниця Саргераса: Дурисвіт",
        description = "Печатку носять лише найпотужніші з його слуг, і вона свідчить про присутність Дурисвіта, Кіл'джедена. Його треба здолати.",
    },
    [47129] = {
        title = "Гробниця Саргераса: Дурисвіт",
        description = "Печатку носять лише найпотужніші з його слуг, і вона свідчить про присутність Дурисвіта, Кіл'джедена. Його треба здолати.",
    },
    [47130] = {
        title = "Неналежне поховання",
        description = "Криваві тролі збирають тіла мого народу для своєї кривавої магії. Сьогодні цьому кінець.\n\nПро тіла тут подбаю я. Візьми цей смолоскип. Його полум'я освятили жерці Бвонсамді, лоа смерті.\n\nСпалюй усі тіла мого народу, які побачиш. Кожне спалене тіло — це менше сили для кривавої магії цих чудовиськ.",
        objectives = "Скористайся Церемоніальним Смолоскипом на тілах зандаларі.",
        completion = "Мій народ заслуговує на краще. Коли це скінчиться, ми маємо належно вшанувати їх у Зулдазарі.",
    },
    [47132] = {
        title = "Вогонь Скверни і Лід",
    },
    [47134] = {
        title = "Зірвати втечу Легіону з в'язниці",
        description = "Великий інквізитор Раалґар має тут, на Аргусі, певний зв'язок зі Скверною, що робить його невразливим. Колись давно наару ув'язнили його в Аркатразі.\n\nКоли війська Кель'таса Сонстрайдера напали на цитадель, нам довелося рятуватися втечею на «Екзодарі».\n\nКілька в'язнів Легіону втекли з Аркатразу під час останнього вторгнення Легіону на Азерот, але Раалґар серед них не був. Завадь їм звільнити його, а я тим часом вивчу джерело його безсмертя, щоб його можна було зруйнувати.\n\nЯ підкину тебе ближче. Решта — за тобою.",
    },
    [47135] = {
        title = "Задля їхнього ж блага",
    },
    [47137] = {
        title = "Захисники Легіонфолу",
        description = "Битва за повернення Розколотого берега виснажує наші ресурси. Ми не можемо дозволити собі послабити натиск, інакше Легіон зведе нанівець усе, чого ми досягли.\n\nЧлени твого ордену віддали багато, але потрібно ще більше.\n\nЗгуртуй своїх захисників і зроби все необхідне, щоб зміцнити їхні лави. У цій землі може ховатися нерозкрита сила, яка переломить хід війни на нашу користь.",
    },
    [47139] = {
        title = "Знак Сентінакса",
        description = "Сентінакс сіє жах над Розколотим берегом, насилаючи орди демонів, що загрожують нашим військам. Ці нелюди прагнуть завадити нам захопити Гробницю.\n\nУ них нічого не вийде.\n\nВимани найсильніших із їхніх ницих лав. Убий їх і забери знаки, які вони носять. Нехай Легіон боїться нашої сили!",
    },
    [47148] = {
        title = "Щось інакше",
        description = "Навіть найкровожерливіші бійці врешті стомлюються й відвертаються від нескінченної боротьби війни. Вони шукають нового способу випробувати свою мужність і знищити ворогів.\n\nДолучися до бою, що вже триває, і змагайся з суперниками в обмеженій у часі події, де традиційні правила відкинуто.",
        objectives = "Переможи в PvP-сутичці.",
    },
    [47180] = {
        title = "Пульсівне божевілля",
        description = "Цей Розбитий ще зберіг частину свого здорового глузду, хоч і не повністю.\n\nЯ відчуваю поблизу вплив Порожнечі, але він зосереджений у невеликих осередках. Якщо розвіяти ці прояви, це має допомогти нашому другові прояснити розум.\n\nМабуть, ми зможемо скористатися уламками молитов, які ти знайш$p(ов:ла), адже в них досі лишається трохи енергії Світла.\n\nЯ тим часом спробую второпати його белькотіння. Можливо, ми дізнаємося щось про те, що тут відбувається.",
    },
    [47181] = {
        title = "Незаперечний доказ",
        description = "Компанія «Ешвейн» поки що цього не знає, але кинути тебе до Тол-Дагору було найбільшою помилкою в їхньому житті.\n\nТой новий порох, що ми поцупили, може стати ключем до їхнього падіння.\n\nДля початку, чом би нам не влаштувати всім невеличку демонстрацію того, наскільки потужна ця штука?\n\n<Флінн засипає дрібку блискучого пороху у свій пістоль.>\n\nДавай, стрельни ось у ту діжку.",
    },
    [47182] = {
        title = "Давно на часі",
        description = "Я багато чого дізнався. Великий інквізитор Раалґар перебрався на базу поблизу цитаделі Легіону за горами. Саме там він тримає Серце Скверни Аргуса — джерело свого безсмертя, — і його живлять колодязі, що ведуть прямо до ядра Аргуса.\n\nВін готується до нападу, тож ти вдариш першим. Познач розташування колодязів, а я обрушу на них священний вогонь із гармат «Віндікаара». Коли цей зв'язок зі Скверною Аргуса буде розірвано, Раалґара можна буде вбити, а Серце Скверни — здобути.",
    },
    [47183] = {
        title = "План Аркаана",
        description = "Аркаан пам'ятає. Він пам'ятає дещо, що... так... що нас врятує.\n\nІди за Аркааном. Ізолон кличе! Ми звернемося до Світла лагідними словами. Світло прожене темряву.\n\n<Аркаан сторожко поглядає на Аллерію.>\n\nАркаан пильно за нею наглядатиме.",
    },
    [47184] = {
        title = "Небезпека для Аркаана",
        description = "Хай що його покликало, добрих намірів воно мати не може. Нам треба піти за ним.\n\nПерш ніж ступити в цей портал, {name}... переконайся, що готовий до бою. Вплив Порожнечі рідко буває мирним.",
    },
    [47186] = {
        title = "Святилище Мудреців",
        description = "Схоже, ти попрацюєш з нами якийсь час.\n\nСайрус налагодить морський транспорт між цим місцем і Стормвіндом, але, гадаю, для щоденних потреб тобі захочеться чогось трохи швидшого.\n\nПіднімися назад нагору й, вийшовши надвір, поверни ліворуч. Там ти знайдеш старий кабінет, де колись Припливні мудреці проводили свої магічні ритуали.\n\nМаги твого Альянсу напевно вже відчули його силу.\n\nПовідом їм, що там вони можуть відкривати свої портали. Вартові гавані охоронятимуть кімнату.",
    },
    [47188] = {
        title = "Поміч лоа",
        description = "Криваві тролі сильні як ніколи — завдяки цьому Ґ'гууну... а тепер вони ще й наповнюють силою велетенський конструкт!\n\nНам потрібен план, як знищити той конструкт, Ґ'гууна й кривавих тролів. Легко не буде.\n\nАле в мене є ідея.",
        objectives = "Порадься з Таланджі й Роканом, щоб вирішити наступні кроки.",
        completion = "Допомога лоа може бути нашим єдиним шансом спинити кривавих тролів. \n\nРушаймо.",
    },
    [47189] = {
        title = "Розділена нація",
        description = "Кул-Тірас має об'єднатися, перш ніж зможе бодай чимось зарадити Альянсу.\n\nДозволь увести тебе в курс нинішньої ситуації в кожній з наших основних територій.\n\nА тоді ти зможеш глянути на мапу за моєю спиною й вирішити, куди хочеш вирушити першим.",
    },
    [47198] = {
        title = "Вони хочуть нас живими",
        description = "Отрути кривавих тролів зроблені так, щоб паралізувати, а не вбивати. Бачиш, вони хочуть нас живими.\n\nМені аж недобре, коли думаю, навіщо їм це.\n\nЯ роблю протиотрути так швидко, як можу, але мені потрібен хтось такий, як ти, щоб вийти туди й випробувати їх. Візьми те, що я вже наготував, і подивися, чи зможемо ми поставити тих солдатів на ноги.",
    },
    [47199] = {
        title = "Кривава брама",
        description = "Ми щойно отримали звістку, що північний кордон зазнає потужного нападу армії кривавих тролів.\n\nКороль Растахан закликав підкріплення.\n\nТи знаєш цю загрозу краще за будь-кого з нас. Іди й зроби все, що можеш, щоб їм допомогти.",
    },
    [47200] = {
        title = "Кліщі",
        description = "Убий тих кровопузів, перш ніж вони здіймуться в небо з усіма моїми солдатами! А я підготую свої війська до флангового удару.",
    },
    [47201] = {
        title = "Рокан",
        description = "Мої розвідники доповіли, що твій тіньовий мисливець Темного Списа, Рокан, повернувся з Назміру. Його притиснули по той бік брами.\n\nНам треба прорвати цей натиск фланговим маневром.\n\nСтара Ротана вже на позиції. Сідай верхи й проламай збоку лави кривавих тролів.\n\nЯк опинишся там, спробуй знайти Рокана.\n\nА, і ще, {name}, будь обережний. Там унизу літає чимало темної магії.",
    },
    [47202] = {
        title = "Особисте послання",
        description = "Настав час мені вирушити на Розбитий берег і на власні очі побачити місце, де загинув мій батько.\n\nЯкщо я маю стати королем, яким був мій батько... королем, на якого заслуговує Стормвінд, я мушу на власному досвіді пізнати загрозу, з якою стикається мій народ.\n\nПрошу, перекажи моїм радникам, що я вирушив на Розбитий берег. Якби я сказав їм сам, вони б лише спробували мене зупинити.\n\nЯ чекатиму на тебе біля Точки Спасіння. Прощавай.",
    },
    [47203] = {
        title = "Кидаючи тінь",
        description = "Це був Локус-Вокер. Він навчив мене всього, що я знаю про Порожнечу, і йому ще є чого мене навчити.\n\nЯкщо він тут, то присутність ефіріалів інтригує мене ще більше. Я думала, він єдиний свого роду, та тепер, коли я побачила іншого, хто має справу з Порожнечею...\n\nХодімо, ми мусимо зіграти в його гру, якщо хочемо дізнатися те, що знає він. Схоже, він подався до Тіньових Лощин на півночі.",
        objectives = "Дослідь Тіньові Улоговини разом з Аллерією і Локус-Вокером.",
        completion = "<Аллерія на мить наче втрачає мову.>",
    },
    [47204] = {
        title = "Нова лінія фронту",
        description = "Убивай усе, що бачиш, окрім зандаларів!",
    },
    [47205] = {
        title = "Матір війни",
        description = "Стару Ротану прокляла матір війни, яку привели з собою ці підлі криваві тролі. Нам треба здолати її, щоб повернути цього старого жахорога в бій.",
    },
    [47217] = {
        title = "Джерела темряви",
        description = "Гадаю, я розумію, що він намагався нам показати, {name}.\n\nЯ відчуваю, як попереду наростає сплеск сили. Вони, певно, плекають Порожнечу, прикликаючи її сюди.\n\nНам треба зупинити їх, перш ніж вони занурять усе це місто в морок. Знайди джерело й перекрий його будь-якою ціною.\n\nУ нас із Локус-Вокером ще лишилася незавершена справа.",
        objectives = "Вимкни 5 Жниварів Порожнечі.",
        progress = "У нас із Локус-Вокером лишилися незакінчені справи.",
        completion = "Ми виграємо час, і не більше.",
    },
    [47218] = {
        title = "Вторгнення Тіньової варти",
        description = "Як ти вже, безперечно, зрозумів, певна частина мого народу трагічно піддалася поклику Порожнечі.\n\nЯ сподівався знайти більше тих, хто має потрібну силу духу. Я розчарований таким цілковитим браком опору.\n\nНічого не вдієш. Щоб просунути твою справу і мою, нам доведеться винищити цих слабких духом істот.",
        objectives = "Убий 15 Ефіріалів Тіньової варти.",
        progress = "Ходити по лезу бритви таки ризиковано, {NAME}.",
        completion = "Приємно знати, що в нас може бути спільна мета. Може, я ще знайду користь із твого роду.",
    },
    [47219] = {
        title = "Готовий посуд",
        description = "Поміркувавши, я вирішив дати Аллерії ще одну можливість здійснити свою долю.\n\nГадаю, ти хочеш знати, що це означає, смертний.\n\n<Локус-Вокер сміється.>\n\nЗустрінь нас у глибині табору Тіньової варти, що попереду, — мої побратими готують прикликання, яке дасть достатньо енергії, щоб Віндраннер почала спочатку.\n\nПобач, що стається, коли опановуєш силу Порожнечі.",
        objectives = "Здолай Нал'атота і забери його серце.",
        progress = "Я чітко бачу шлях, {NAME}.",
        completion = "<Аллерія бере серце в руки.>\n\nЦе наступний крок, {NAME}. Дякую, що привів мене до цієї миті.",
    },
    [47220] = {
        title = "Маяк у темряві",
        description = "Це було... напружене переживання.\n\n<Аллерія тре чоло.>\n\nВажко зосередитися. Мені треба, щоб ти поверну$p(вся:лася) до Велена. Передай йому це.\n\n<Вона кладе тобі в долоню щось холодне й важке.>\n\nЯ відчуваю, що це має належати йому, хоч і не певна чому.\n\nРозкажи йому все, що ми дізналися. Я впевнена, Ромуул стежив за нашим поступом. Якщо пощастить, маяк уже прямує до нас.",
    },
    [47221] = {
        title = "Рука долі",
        description = "{name},\n\nМи виграли багато битв проти Палаючого Легіону, але настав час покінчити з цією війною раз і назавжди.\n\nРозпочалися останні приготування до відправлення на Аргус.\n\nПоспіши до гавані Стормвінда. Там на тебе чекає корабель, що доправить тебе й твоїх союзників на Азурмист.",
    },
    [47222] = {
        title = "Двома шляхами морем",
        description = "Гробниця Саргераса була лише початком. Якщо ми не знищимо Легіон дощенту, він повернеться ще сильнішим.\n\nМи вирушимо на Азурмист морем, щоб не привертати зайвої уваги. Чим менше часу матиме Легіон, аби відреагувати на наш напад, тим краще.\n\nПросто скажи слово, коли будеш готовий вирушати.",
    },
    [47223] = {
        title = "Вихід Світла",
        description = "Пророк Велен та інші зібралися внизу, у Сховищі Світла. Вхід просто далі цією стежкою.\n\nНам слід негайно відшукати Пророка, щоб не затримувати вторгнення.",
    },
    [47224] = {
        title = "Віндікаар",
        description = "Усе готово до нашого штурму. Лишилося тільки встановити маяк, який перенесе нас на корабель.\n\nЩойно маяк прибуде, поклади руку на його поверхню, щоб піднятися на борт «Віндікаара» — знаряддя нашої відплати.",
    },
    [47226] = {
        title = "Осиротіле пташеня",
        description = "<Уціліле пташеня жалібно пищить, дивлячись на труп своєї матері.\n\nВоно з надією розглядає тебе й, здається, хоче піти за тобою.\n\nМожливо, ти знайдеш когось у Загоні Бойових Звірів, хто зміг би про нього подбати?>",
        objectives = "Знайди в Загоні Бойових Звірів того, хто дбає про юних жахорогів.",
        completion = "Ти той ординець, про якого я стільки чув? Я гадав, ти будеш трохи більший. Ха!\n\nГей! Що це в тебе там?",
    },
    [47228] = {
        title = "Екологія Шибали",
        description = "Я справді сподівався, що ця місцина буде гостиннішою.\n\nЗандалари геть ніяк не допомогли розчистити цей простір для археологічних досліджень. Перш ніж ми взагалі зможемо почати розкривати таємниці Шибали, нам треба зробити її безпечною для тих, хто не такий вправний у бою, аби вони могли працювати.\n\nРуїни попереду кишать усілякими хижими звірами. Ті кілька відважних дослідників, що наважилися зайти всередину, так і не повернулися.\n\nМісцева природа не стоятиме на шляху прогресу, {name}. Зрозуміло?",
        objectives = "Убий 8 шибальських хижаків.",
        completion = "Я чув, цей край дуже сприятливий для такого життя. Їхня чисельність відновиться... деінде.",
    },
    [47229] = {
        title = "Бастіон Торкалі",
        description = "Ми знову поставили стару Ротану на ноги. Залазь і бери віжки.\n\nПрикрий нас, щоб Таланджі змогла пробитися зі свого боку.",
    },
    [47235] = {
        title = "Провидіння Ока",
        description = "Від імені Орди ми шукаємо реліквію під назвою Око Шибали.\n\nМісцеві геть ніяк не допомогли, а панна Тае'шара наполягає, щоб ми скористалися її дослідним обладнанням.\n\nЯ ненавиджу здогади. Натомість ми застосуємо прямішій спосіб: провидіння.\n\nЯ позначу три місця на твоїй карті. Хочу, щоб ти встанови$p(в:ла) на кожному з них пристрій провидіння. За їхніми вимірами я визначу місцезнаходження реліквії, і ми вирушимо в путь.",
        objectives = "Постав 3 Ворожбитські Посудини в Шибалі.",
        completion = "Чудова робота. Дай мені переглянути результати, і ми рушимо.",
    },
    [47238] = {
        title = "Престол Тріумвірату",
        description = "Навіть із Сигілом Пробудження в руках Корона не врятує нас, доки не стане цілою.\n\nСаме тому ми мусимо ввійти до Престолу Тріумвірату, навіть знаючи, що Л'ура чекає там на нас.\n\nЦе тяжке завдання, якого я не просив би, якби воно не було цілком необхідним.\n\nМи зійдемо туди разом. Ходімо.",
    },
    [47241] = {
        title = "Тінь смерті",
        description = "Лоа в нас четверо, але ми знаємо, де лише один із них: Бвонсамді.\n\nХай як мені це неприємно, я готова на все, аби спинити кривавих тролів... навіть якщо доведеться мати справу з лоа смерті.\n\nБагато віків тому Бвонсамді мав тут, у Назмірі, храм. Ворожіння відкрило мені кілька місць на півночі, де я відчуваю магічну присутність. Обшукай їх — може, знайдуться підказки.\n\nПоспішай, {name}. Якщо ми не заручимося допомогою Бвонсамді, Зулдазар упаде!",
        objectives = "Пошукай підказки, де шукати лоа на ім'я Бвонсамді.",
        completion = "Ти шукаєш храм Бвонсамді? Ти, мабуть, у відчаї, якщо туди йдеш.\n\nНа твоє щастя, я і сам туди прямую.",
    },
    [47244] = {
        title = "Жнива душ",
        description = "Нині до храму Бвонсамді навідуються лише два типи гостей: ті, хто шукає угоди зі смертю, і мертві. Від тебе не тхне, тож, гадаю, ти з перших.\n\nЯ й сам прямую до храму, тож пропоную обмін.\n\nБачиш землю за мостом? Там є відьма на ім'я Наджіма, за якою я давно полюю. Криваві тролі прогнилі до самого нутра, але їхні душі згодяться як підношення Бвонсамді. Вона занадто сильна, щоб я впорався сам, але якщо ти її вб'єш — я відведу тебе до храму.\n\nДаю тобі слово.",
        objectives = "Здолай Кривавицю Наджіму.",
        completion = "Це має спрацювати. Її душа ідеальна для підношення.\n\nА тепер, перш ніж іти до храму, лишилося ще одне...",
    },
    [47245] = {
        title = "Послання отримано",
        description = "Лоа могутні, та нам потрібні солдати, якщо ми хочемо мати бодай шанс не дати кривавим тролям добудувати їхнього велетня. Не знищимо ту штуку, поки її не скінчили, — і Зулдазару, і всьому нашому народові кінець!\n\nНам потрібна поміч Орди!\n\nЗвістку про становище вже надіслано вождю. Щойно дістанемо її відповідь, зможемо вируша—\n\nСтривай... що це за гамір?",
        objectives = "Дослідь заворушення.",
        completion = "Гобліни... з усіх гідних загонів Орди, чому вождь має слати нам саме гоблінів?",
    },
    [47246] = {
        title = "Рештки проклятих",
        description = "Відколи духи почали взивати до цього «Ґ'гууна», мій храм укрила нестерпна скверна нежиті.\n\nНежить — то гидота, але кровокамені, які її породжують, мають велику силу. Вони ще можуть стати Бвонсамді в пригоді.\n\nХочеш показати мені свій запал — очисти мій храм від цього бруду й принеси мені їхні кровокамені.",
    },
    [47247] = {
        title = "Те, що переслідує мертвих",
        description = "Бвонсамді знає, чого ти тут. Ти шукаєш моєї прихильності.\n\n<Бвонсамді мовчки міряє тебе поглядом.>\n\nВипробування — щоб побачити, чи $p(вартий:варта) ти часу Бвонсамді.\n\nЄ духи, чиї молитви оспівують щось на ім'я «Ґ'гуун». Мені вони більше не віддають шани. Я не дозволю оскверняти мій власний храм!\n\nІди й приборкай найсильніших із прадавніх духів.\n\nЯкщо зробиш це для мене — може, ти й справді $p(вартий:варта) мого клопоту.",
        objectives = "Здолай верховну жрицю вроків Тізеджу і воєначальницю Малажу.",
        completion = "А, я відчуваю, як їхні душі зміцнюють мою силу. Я знав, що ти вартий часу Бвонсамді.",
    },
    [47248] = {
        title = "Поки смерть не розлучить нас",
        description = "Я не знаю, хто ти, але мені потрібна твоя допомога.\n\nМій любий Валджабу завжди казав, що йому байдуже до даних ним обітниць жерця... ми будемо разом навіки.\n\nЩо ж, настав мій час відійти, і я знала, що не зможу жити без нього. Я повернулася й чекала на цьому місці... здавалося, цілу вічність, а Валджабу так і не з'явився!\n\nЯ блукаю цим світом уже надто довго.\n\nПрошу, благаю тебе, принеси мені пам'ятку про мого Валджабу!",
    },
    [47249] = {
        title = "Узи душі",
        description = "Ти добре впора$p(вся:лася) з моїми завданнями. Гадаю, ти подаєш надії. Може, ти й $p(вартий:варта) угоди.\n\nЩо ж, гаразд: присягаюся позичити тобі свої сили проти твоїх ворогів. А натомість ти відправиш Бвонсамді мільйон душ! Нічого так дивуватися — тобі це цілком до снаги.\n\nПриходь до мене у Двір Духів. Там ми й скріпимо нашу угоду.",
        objectives = "Поговори з Бвонсамді у Дворі Духів і заверши обряд.",
        completion = "Ці криваві тролі та їхній «бог» Ґ'гуун — вони значно більша загроза, ніж я гадав. Обряд, що скріплює пакт між нами, не завершено, але зважаючи на обставини, гадаю, формальності можна пропустити.\n\nПоки ціну сплачено, можеш розраховувати на поміч Бвонсамді.",
    },
    [47250] = {
        title = "Ми ще зустрінемося",
        description = "Ну, а тепер час тобі рушати.\n\nНа тебе чекає ще багато душ кривавих тролів, які треба відправити на Той Бік для Бвонсамді, — а тут ти більше жодної не знайдеш.",
        objectives = "Вирушай до Руїн Зо'бала і поговори з Ганзабу.",
        completion = "То ти теж уклав пакт із Бвонсамді? Добре: що більше душ для Бвонсамді, то він сильніший, а це на краще для нас обох. Тільки лиши трохи полювання Ганзабу. Мені теж є за що платити!",
    },
    [47251] = {
        title = "Цікаві часи",
        description = "{name}, не хочу тебе тривожити, але ми, можливо, переживаємо деякі... часові збурення.\n\nЧи чув ти колись вислів «сподіваюся, минуле не повернеться, щоб тебе переслідувати»?\n\nЗавітай до мене в Долину духів, і ми поговоримо детальніше.",
    },
    [47252] = {
        title = "Цікаві часи",
        description = "{name}, не хочу тебе тривожити, але ми, можливо, переживаємо деякі... часові збурення.\n\nЧи чув ти колись вислів «сподіваюся, минуле не повернеться, щоб тебе переслідувати»?\n\nЗавітай до мене в Королівську бібліотеку Стормвінда, і ми поговоримо детальніше.",
    },
    [47254] = {
        title = "Першопочатки",
        description = "Давним-давно нашими землями ходили великі жахіття й спонукали навіть найменших до подвигів героїзму.\n\nЯ кажу, звісно ж, про лорда Каззака, Азурегоса й Драконів Жахіття.\n\nЛегенди оповідають, що їхні скарби були настільки жаданими, що цілі армії ставали табором на ніч, аби вполювати їх.\n\nДракони відчули збурення в часоплинах, що випадково розташовані там, де колись блукали ці велети.\n\nВони доручили мені знайти чемпіонів, які б усе розслідували.",
    },
    [47257] = {
        title = "Кістки Ксібали",
        description = "Далеко на півдні ти знайдеш кістки прадавнього створіння. Це Ксібала, прародителька, перша з-поміж дияволозаврів. Вона була матір'ю Резана, матір'ю всіх, хто з'явився опісля. Зандалари там не живуть, бо тепер ці землі належать звірам.\n\nЯ чула чутки, що дехто з твоєї Орди прибув туди, шукаючи чогось серед її кісток.\n\nЦе нерозважливо. Розберися з цим, гаразд?",
        objectives = "Вирушай до Шибали і поговори з дослідницею Тей'шарою Бладвотчер.",
        completion = "Я чекала такої знахідки все життя. Я змушу батька пишатися.",
    },
    [47258] = {
        title = "Підготовка до облоги",
        description = "Схоже, ми мусимо готуватися до облоги. Наразі ж повертайся до своєї Орди в Дазар'алор. Готуйся до прийдешнього протистояння.\n\nЯкщо сили Назміру рушать у наступ, я надішлю звістку.",
    },
    [47259] = {
        title = "Ясла для жахорога",
        description = "Доглядач Базкоджі мав справжній хист до малечі. Якщо це маля йде за тобою, це означає, що Базкоджі мертвий.\n\nУ мене немає часу шукати іншого доглядача. Ти впораєшся із цим завданням?\n\nЦе чимало роботи, і малі прив'язуються дуже швидко. Якщо ти візьмешся його доглядати, це буде зобов'язання. Це маля залежатиме від тебе. Сподіваюся, ти впораєшся із завданням годувати й захищати його.\n\nНасамперед найголовніше: їжа. У загонах і в річці внизу вдосталь корму.",
        objectives = "Нагодуй своє дитинча.",
        completion = "Непогано. Це маля вже виглядає міцнішим.",
    },
    [47260] = {
        title = "Можливі побічні дії...",
        description = "<Твій супутник-жахоріг безперестанку гикає. Щоразу він або помітно зменшується, або більшає. Він скиглить до тебе в розпачі.\n\nТобі б не завадила допомога.>",
    },
    [47261] = {
        title = "Як приручити свого жахорога",
        description = "Мушу роздобути хоч трохи того, чим ти годуєш своє маля! Оце так!\n\nТепер, коли воно підросло, час навчити його бути надійним бойовим товаришем.\n\nПогляньмо, як воно впорається з серйознішим випробуванням, га?\n\nПоговори з наглядачем кралю Б'хором, коли будеш готовий почати.",
        objectives = "Поговори з майстром краалю Б'хором і обери навчання свого жахорога.",
        completion = "Ой. Принаймні на це було доволі цікаво дивитися! Ха-ха-ха!\n\nГадаю, ви двоє точно заслужили тут своє місце!",
    },
    [47262] = {
        title = "Кінець кривавим тролям",
        description = "Лоа сьогодні всміхаються до нас. «Матріарх» цих кривавих тролів, хвора потвора на ім'я Атіна, чекає попереду.\n\nУ нас зміна планів, {name}. Ми покладемо край цій загрозі просто зараз. Уб'ємо Атіну — і кривавих тролів охопить хаос.\n\nВона могутня врочниця. Розпочни бій, а я вдарю із засідки й заскочу її зненацька.\n\nРушаймо. Ми повернемося до Зулдазару ще до кінця дня.",
        objectives = "Убий Атіну, Матріарх кривавих тролів.",
        completion = "Атіна від нас не втече, треба рухатися далі.",
    },
    [47263] = {
        title = "Час одкровення",
        description = "Я відчуваю попереду темне вуду Атіни. Хай що вона замислила з цим «Ґ'гууном», ми мусимо це зупинити.\n\nБудь готов$p(ий:а) до всього, {name}. Ми не знаємо, якою силою насправді володіє Атіна.\n\nАле одне я знаю напевно. Якщо Ґ'гуун загрожує моєму народу — він загине, так само як Атіна.",
        objectives = "Допоможи Таланджі наздогнати Атіну.",
        completion = "Загроза кривавих тролів більша, ніж я могла уявити. Того конструкта досить, щоб знищити весь Зулдазар\n\nЩоб це спинити, потрібно більше, ніж Орда.",
    },
    [47264] = {
        title = "Не лишай нікого живим",
        description = "Тепер ти бачиш те, що мій батько відмовляється визнавати. Криваві тролі винищують нас, і їх треба зупинити.\n\nНаш план простий, {name}. Ми підемо туди й уб'ємо стільки кривавих тролів, скільки зможемо. Ти йди на схід, а я піду на північ.\n\nПотім зустрінемося й подивимося, що лишилося зробити. Ми навчимо цих кривавих тролів боятися зандаларі!",
        objectives = "Убий 6 кривавих тролів.",
        completion = "Ти скінчив? Добре, бо ми вже близько до кінця цієї загрози.",
    },
    [47272] = {
        title = "Гормон росту для жахорога",
        description = "Гарненьке створіннячко в тебе тут. Хоча на вигляд трохи замале, щоб бути чимось більшим за докуку.\n\nХочеш допомогти другові заробити? Тут безліч можливостей, та ці тролі мене й слухати не хочуть!\n\nОсь що я тобі скажу: я можу зготувати такий собі додаток, від якого аж волосся на грудях виросте! Е-е, на грудях твого малюка!\n\nЗнаю, жахороги — вегетаріанці й усе таке, але ж недарма всі найбільші хижаки їдять м'ясо!\n\nДля швидкого росту потрібен протеїн. БАГАТО протеїну.\n\nЗацікавився?",
        objectives = "Збери 10 Паруючої Свіжої Падалі.",
        progress = "То що? Дістав усе, що мені треба?",
        completion = "М'ясо — доволі дивовижна річ, знаєш!\n\nЕ-е, деталі про це, мабуть, поки що краще лиши при собі.",
    },
    [47283] = {
        title = "Рубай, рубай!",
        description = "Throm-ka, {name}.\n\nЯ завжди шукаю того, хто гадає, що вміє махати сокирою незгірш за найкращих.\n\nЯкщо зможеш прибрати отой пагінець без особливих клопотів, я певен, ми знайдемо твоїм умінням краще застосування.",
    },
    [47287] = {
        title = "Ядро матриці Віндікаара",
        description = "На Аргусі сталося чимало такого, що мене непокоїть, та найдужче — доля Ксе'ри. Часом я замислююся: чи правильно ми чинимо?\n\nАле ми мусимо рухатися далі. Я можу налаштувати Ядро матриці, що живить Віндікаар, щоб ти міг закликати міць наших гармат, коли вона знадобиться тобі на планеті.\n\nІди до Ядра матриці в залі в самому серці нашого корабля. Щойно встановиться зв'язок, у твоєму розпорядженні буде вся сила, яку ядро має тепер і матиме в майбутньому.",
    },
    [47289] = {
        title = "Ведмедики й чаювання",
        description = "Тут більше нема з ким гратися. Але ти ж погратимешся зі мною, правда, пане?\n\nЧас пити чай! Допоможи мені, будь ласка, знайти інших гостей!",
        objectives = "Збери пана Хрумчика, Хоботка і мера Стріґґса на чаювання.",
        progress = "Це буде найкраще чаювання в світі!",
        completion = "Ура! Лишилося знайти ще одного гостя.",
    },
    [47290] = {
        title = "Світова подія: підземелля — Гуммель",
    },
    [47310] = {
        title = "Час подрімати",
        description = "Твій уже не такий і маленький друзяка має трохи виснажений вигляд після такого захопливого дня. Закладаюся, вам обом потрібен відпочинок, га?\n\nПовертайся пізніше, коли трохи зміцнієш.",
        objectives = "Постав свого жахорога в Загоні Звірів.",
        completion = "Я поки що догляну за твоїм малям. Іди у свої пригоди. Вивчай звичаї зандаларі. Коли ви обидва будете готові, я матиму для вас пропозицію.",
    },
    [47311] = {
        title = "Удар головою для початківців",
        description = "Твоя звірюка має добре нагодований вигляд. Гаразд. Намагайся й далі тримати її в такій формі.\n\nТепер тобі треба навчити своє маля захищатися. У дикій природі жахороги — здобич для значно більших створінь, а молодняк — легка пожива для саврідів і подібних до них.\n\nВирушай у Дикі землі й покажи своєму малюкові, як давати їм відсіч.\n\nУся справа в розі, {name}.",
        objectives = "Допоможи своєму дитинчаті побороти 12 істот.",
        completion = "Я бачу в очах твого дитинчати проблиск упевненості. Добре. Вона йому знадобиться.",
    },
    [47312] = {
        title = "Пернатоцариця",
        description = "А, то це ти успадкува$p(в:ла) стадо Базкоджі. Принаймні те, що від нього лишилося.\n\nЯ знаю, що його вбило, і я намагався його застерегти. Пернатоцариця — люта равазавра, більша за решту й до того ж розумніша. Більшість яєць тут довкола — її.\n\nЗазвичай я вихваляю силу такої звірини, але вона стала справжнім лихом.\n\nТи знайдеш її в годівельних угіддях, де вона стереже свої гнізда. Убий її й принеси одну з пір'їн з її голови як доказ, що справу зроблено.",
        objectives = "Убий Пернатоцарицю і забери одну з її пір'їн.",
        progress = "Пернатоцариця досі нас переслідує?",
        completion = "Добре. Тепер, коли кровожерної матріарх немає, може, ми зможемо підсадити у виводок когось зі своїх на заміну... Гммм.",
    },
    [47313] = {
        title = "Розмови без зайвих вух",
        description = "Генералові Джакра'зету не можна довіряти.\n\nВін щось замислив, але я не знаю, що саме.\n\nКожного, хто ставить під сумнів його дії, чекає дорога в піски.\n\nДоки він при владі, моє місто ніколи не буде в безпеці.\n\nПоговори з його вартовими. Дізнайся, що зможеш, але дій обережно. Не треба, щоб Джакра'зет здогадався про наші наміри.",
        objectives = "Розпитай Наглядачів у Дазар'алорі.",
        completion = "Такими питаннями ти наживеш тут більше ворогів, ніж союзників.",
    },
    [47314] = {
        title = "Чутки про вигнання",
        description = "Тебе прислала Таланджі, чи не так?\n\nПринцесі варто знати, що відкрито ставити такі питання вже небезпечно.\n\nБойова варта Ракера наважилася заговорити — і відтоді про неї ніхто нічого не чув.\n\nКажуть, її вигнали до Вол'дуна.",
        objectives = "Іди за Каєю з клинкової варти.",
        completion = "Ми не дамо пісками поглинути Ракеру і те, що вона знає.",
    },
    [47315] = {
        title = "У дюни",
        description = "Хоч би що там Ракера розкопала, воно виявилося досить важливим, щоб заробити їй смертний вирок у пісках.\n\nМусимо вирушити до Вол'дуна й знайти її.\n\nНе можна допустити, щоб усе, що вона знає про Джакра'зета, загинуло разом із нею серед дюн.",
        objectives = "Лети в пустелі Вол'дуну і шукай воєварту Ракеру.",
        completion = "Ці змієлюди заплатять за те, що зробили з моїм домом.",
    },
    [47316] = {
        title = "Таємниці в піску",
        description = "Я знайшла цей щоденник закопаним у піску.\n\nКіро хотів кинути його у вогонь.\n\n«У нашому возі немає місця для щоденника, Міро. Яка з нього практична користь?»\n\nТільки не кажи йому, що я таке говорила, але, як на мене, це захопливо! Уявляєш, які таємниці він зберігає?\n\nБракує чимало сторінок, але закладаюся: ти зможеш відшукати їх у дюнах!",
        objectives = "Знайди відсутні сторінки щоденника.",
        progress = "Що ти знайшов?",
        completion = "Це почерк Ракери. Я впізнаю його будь-де.",
    },
    [47317] = {
        title = "Пошук уцілілих",
        description = "Рада бачити, що ти в безпеці, але що з рештою? Невже їх поглинули піски?\n\nПовернися до місця аварії й перевір, чи вижив ще хтось.\n\nА я порозпитую тут — може, ці лисолюди щось знають про Ракеру.",
        objectives = "Пошукай уцілілих біля місця падіння.",
        completion = "Джорана знала ризики, коли погодилася зайти в піски, але я все одно почуваюся винним за її смерть.\n\nЛишається сподіватися, що Таркадж якось дістався безпечного місця.",
    },
    [47319] = {
        title = "Цілюща отрута",
        description = "Міра ось знайшла твою подругу в дюнах. Удар блискавки мало її не вбив. І ще може вбити, якщо не лікувати.\n\nОси в цьому гаю жалять дуже болісно, але їхня отрута має й цілющі властивості.\n\nЯ можу видобути з їхніх залоз те, що мені потрібно.\n\nЯкщо отрути буде вдосталь, ми зможемо вгамувати біль від ран твоєї подруги.",
        objectives = "Збери 15 Отруйних Залоз Піскожала.",
        progress = "Ти приніс залози? Без них ми не зцілимо твого друга.",
        completion = "<Кіро швидко оглядає залози.>\n\nЦе має спрацювати.",
    },
    [47320] = {
        title = "Бальзам, що заспокоює",
        description = "Як і обіцяв, ось бальзам, що має загоїти рани твоєї супутниці.\n\nЩедро змаж ним усі вражені місця.\n\nДія має відчутися одразу.",
        objectives = "Скористайся Відновлювальним Бальзамом на Каї з клинкової варти.",
        completion = "Ці створіння прийшли нам на поміч?\n\nОстаннє, що пам'ятаю, — ми летіли над імперією сетраків. Був сліпучий спалах світла, а тоді все потемніло...",
    },
    [47321] = {
        title = "Повернення дрібничок",
        description = "Ніша сказала мені, що ти прибу$p(в:ла) сюди в пошуках вигнанки. На ім'я Ракера?\n\nМи її не знаємо, але, можливо, допоможемо тобі її знайти.\n\nТи допомагаєш нам — ми допомагаємо тобі. Згода?\n\nМи виживаємо збиральництвом: вимінюємо те, що знайдемо. Але сетраки, які напали на наші нори, забрали з собою чимало наших дрібничок.\n\nЯ завжди знав, що вони безжальні, та й уявити не міг, що вони такі жадібні.\n\nПоверни те, що забрали сетраки, і я подбаю, щоб тебе безпечно провели через дюни.",
        objectives = "Збери 6 Дрібничок із сетраків у Зміїній Пащі.",
        progress = "Ти допомагаєш нам, ми допомагаємо тобі. Домовились?",
        completion = "Ти винахідливіший, ніж на вигляд.",
    },
    [47322] = {
        title = "Втеча з підмогою",
        description = "Сетраки, може, й сильні, але ми спритні. Ну, принаймні ми з Мекару.\n\nМи ледве дісталися назад до воза, не втративши хвостів.\n\nРешті, схоже, пощастило менше. Ми чекаємо вже довгенько, а їх усе немає.\n\nЯкщо вирушаєш у саме пекло, то чи не пошукаєш наших друзів?",
        objectives = "Звільни Гакасі й Кіппа зі Зміїної Пащі.",
        completion = "Дякую, {NAME}. Ми завдячуємо тобі життям.",
    },
    [47324] = {
        title = "Несподівані союзники",
        description = "Гадаю, це один із ключів Хранителів! Напевно знатиме лише Воррік.\n\nНам треба негайно вирушати до храму.\n\nМій птеродакс віднесе нас туди, щойно ти будеш готовий, але треба поспішати.",
        objectives = "Лети до Святилища Відданих.",
        completion = "Ми не можемо дозволити Зневіреним захопити цей храм!",
    },
    [47327] = {
        title = "Відповідь на їхні напади",
        description = "Напади сетраків на наші нори не можуть лишитися без відповіді.\n\nНехай затямлять: не всі в пустелі здаються так легко.\n\nЄдина мова, яку розуміють сетраки, — це кров, тож саме нею ми й дамо їм урок.\n\n<Ніша замовкає й скептично дивиться на тебе, ніби сумнівається, що ти її зрозумі$p(в:ла).>\n\nЯ кажу, що сетраків тут треба перебити. Усіх до одного.",
        objectives = "Убий сетраків у Покинутих Норах.",
        completion = "Їхня кров стікає дюнами назад до їхньої фортеці. Сетраки двічі подумають, перш ніж знову нападати на наші нори.",
    },
    [47329] = {
        title = "Спадок Кровоглядів",
        description = "Вітаю, {name}.\n\nМене прислав мій батько, Верховний Дослідник Тае'телан Кровогляд, щоб наглядати за видобуванням усіх скам'янілостей, реліквій та артефактів у цій місцині.\n\nМої джерела повідомляють, що під цим самим місцем може бути закопано річ, яка прислужиться справі Орди.\n\nМені знадобиться твоя допомога, щоб її дістати. Бачиш, ці нічнороджені не надто вправні руками. Та й бруднитися не люблять.\n\nЧи не будеш ти такий ласкавий показати їм добрий приклад?",
        objectives = "Допоможи дослідниці Тей'шарі Бладвотчер здобути шибальську скам'янілість.",
        completion = "Ти працював руками! Як мило. Нічнонароджені винайшли чимало способів уникати такої дріб'язкової праці.",
    },
    [47330] = {
        title = "Шепіт переляканого світу",
        description = "$p(Воїне:Воячко), Маґні потребує твоєї допомоги!\n\nУ Речника є послання для тебе, можливо, від самої Азерот. Схоже, йому важко її зрозуміти, але я певен, він усе пояснить краще.\n\nВін казав, що був у Шолазарській улоговині, у Нортренді. Невдовзі він має з тобою зв'язатися.",
        objectives = "Зустрінься з Маґні в Шолазарській улоговині й вислухай застереження.",
    },
    [47332] = {
        title = "Твій наступний крок",
        description = "Принцеса Таланджі планує вирушити на північ, до Назміру. Тамтешні криваві тролі — це загроза, яку, на її переконання, її батько відмовляється визнавати.\n\nГенерал Джакра'зет зневажає Орду, тож йому не можна довіряти. Доки він при владі, місто ніколи не буде в безпеці.\n\nТобі також доведеться завоювати прихильність короля Растахана тут, у Зулдазарі. Це місто величезне й приховує безліч таємниць.",
    },
    [47416] = {
        title = "Тінь Тріумвірату",
        description = "Слова Талгата важать більше, ніж він, гадаю, сам розумів. Намагаючись завдати мені останнього удару, він дав нам відповідь.\n\nГерб Знання заховано в Престолі Тріумвірату, і він не без охорони.\n\nЯкщо мої підозри слушні, ми можемо зіткнутися із загрозою, страшнішою за все, що хтось із нас наважувався уявити.\n\nТемний наару.\n\nПовертаймося на Віндікаар. Там ми сплануємо наші подальші дії.",
    },
    [47418] = {
        title = "Біль зростання",
        description = "Ці тролі втрачають тут справжню нагоду! Вони скаржаться, що звірів на всіх не вистачає, але хіба вони справді пробували розводити їх масово? Аж ніяк!\n\nЗ моїм гормоном росту жахорога вони зможуть заповнити ці загони по самі вінця! Звісно, перенаселення може призвести до хвороб і проблем із надлишком нечистот, але я певен, що це можна вирішити.\n\nХа-ха-ха, це буде чудово!",
        objectives = "Дай своєму дитинчаті Гормон Росту Жахорога.",
        completion = "Овва! Спрацювало навіть краще, ніж я думав! Я зароблю статок!",
    },
    [47422] = {
        title = "Жахливе становище",
        description = "Гарна новина: ми знайшли джерело осквернення.\n\nПогана новина: це ритуал на вершині Занчулу.\n\nЄретики, що орудують кривавою магією, підсилюють там, нагорі, якогось жахливого троля.\n\nЯк він дістався аж до вершини повз нас — про це ми з Раалом, певно, сперечатимемося ще цілий рік.\n\nХодімо, спинімо цю єресь.",
        objectives = "Убий Дреґаду.",
        completion = "Я не потерплю тієї крові у своєму храмі!",
    },
    [47423] = {
        title = "Заборонені практики",
        description = "Ти прийш$p(ов:ла) саме вчасно, {name}. Мені якраз потрібна така зброя, як ти.\n\nШпигуни Язми кажуть, що в наших лавах завелися культисти крові. Король Растахан доручив мені вистежити всіх тролів, винних у кривавій магії, і винищити їх.\n\nВізьми цей тотем, викрий тих, від кого тхне кривавою магією, і очисти від них це святе місце.\n\nА коли впораєшся, скажи тому ледачому Володареві вроків Раалу, щоб злазив зі свого сідала й допомагав пильнувати це місце.",
        objectives = "Знайди й убий 9 Багряних Сектантів на Терасі Обраних.",
        completion = "Що? Той глузливий, мерзенний раптор-фанатик дорікає мені, що я не роблю своєї частки? Пхе!",
    },
    [47428] = {
        title = "Котик?",
        description = "Ти маєш знайти нашого останнього гостя, доки не настав час чаювання!\n\nЦьомчик дуже любить ліс, певна, ми знайдемо його там!",
        objectives = "Знайди Цьомчика в Лісі Ґленбрук.",
        completion = "Мрря?\n\n<Ти знаходиш Цьомчика, але Еббі ніде не видно.>",
    },
    [47430] = {
        title = "Спостереження за лунокрилами",
        description = "<Маккав жестом показує тобі поспостерігати за іншими лунокрилами поблизу.>",
    },
    [47431] = {
        title = "Збирання Світла",
        description = "Аллерія і я прагнемо більше часу провести з нашим сином, але ми не можемо дозволити собі чекати далі, {name}. Ми мусимо вдарити зараз.\n\nАрмія Світла розпорошена, але не переможена. Ті, хто вижив, мали б триматися поблизу місця падіння Ксенедара. Якщо є бодай надія на перемогу, ми мусимо згуртувати їх і врятувати Ксе'ру.\n\nКоли з повелителями ям покінчено, шлях до Ксенедара має бути безпечнішим. Зустрінь мене в халупі крокулів, щойно зможеш.",
    },
    [47432] = {
        title = "Угоду укладено",
        description = "Тепер, коли ти обра$p(в:ла) собі лоа-покровителя на час перебування тут, у Зулдазарі, тобі варто сповістити короля про своє рішення.\n\nЙому буде приємно, що ти обра$p(в:ла) слідувати за великою Па'ку.",
        objectives = "Поговори з королем Растаханом.",
        completion = "Отже, ти обрав шлях Па'ку. Хай вітри війни завжди будуть тобі попутні.\n\nЩо ж до мене, я йду за Резаном, дияволозавром-лоа королів. Утім, ми з ним не говорили багато років.\n\nМожливо, одного дня я його навідаю.",
    },
    [47433] = {
        title = "Наступальна оборона",
        description = "Дай-но вгадаю: Лоті загадала тобі вбивати всіх тролів, від яких тхне кривавою магією, так? Що ж, це заледве півзаходу.\n\nБачиш, кривава магія походить із давніх звичаїв, і наш народ почав піддаватися її спокусі лише відтоді, як упали мури на нашому північному кордоні.\n\nХодімо, трохи проїдемося й попатрулюємо кордон із Назміром. Саме звідти лізуть усі ці лихі ідеї.",
        objectives = "Патрулюй небо разом із Володарем вроків Раалом.",
        completion = "О, то цей кривоіклий сопун намагається завоювати тебе невеличким польотом і дрібкою чарівності, еге ж?",
    },
    [47434] = {
        title = "Наведення ладу",
        description = "«Щось відчувається інакше»? І це все, що сказав Раал?\n\nЙого зграя птеродаксів заполонила двір Занчулу. Щось зводить їх із розуму.\n\nПрожени їх, доки вони не покалічили себе чи інших.",
        objectives = "Прожени 20 Пташенят Птеродакса.",
        completion = "Чому ти лякаєш мою зграю?",
    },
    [47435] = {
        title = "Птериторіальна суперечка",
        description = "Двір Занчулу захопили птеродакси, яких звів із розуму якийсь темний ритуал. Тут згущується сила, і важко сказати, хто чи що її породжує.\n\nЯ мушу вистежити джерело. А ти тим часом візьми ось це — силу Ґонка — і клич його союзників на поміч у бою. Перебий цих знавіснілих птеродаксів.\n\nКоли впораєшся, скажи Раалові, щоб тримав свою зграю під контролем.",
        objectives = "Убий 6 Кровожерних Птеродаксів.",
        completion = "Обов'язково було вбивати аж стількох?",
    },
    [47437] = {
        title = "Змагання у відданості",
        description = "Гаразд, я розумію, становище серйозне... але вона віддала тобі силу свого лоа? Як на мене, Лоті більше переймається вербуванням, ніж загрозою від кривавих тролів.\n\nУ храмі за моєю спиною — троє вартових. Коли я туди зайшов, ці почвари спробували мене вбити. Мене!\n\nХтось осквернив наших власних вартових.\n\nОсь, я позичу тобі голос мого власного лоа — Па'ку, птеродакса. Скористайся ним, щоб викорінити це осквернення.",
        objectives = "Убий 3 Осквернених Охоронців Занчулі.",
        completion = "Це гірше, ніж ми думали.",
    },
    [47438] = {
        title = "Вибір сторони",
        description = "Слухай, {name}, це вже затягнулося. Я не з тих, хто плекає образи, але хай мене грім поб'є, якщо я дозволю тобі черпати силу і від лоа Раала, і від мого водночас.\n\nЧас обрати собі лоа. Лоа — не з тих, хто ділиться.",
        objectives = "Обери лоа.",
        completion = "Твій вибір зроблено.",
    },
    [47439] = {
        title = "Ґонк, Володар Зграї",
        description = "Ґонка знайдеш у його лігві на захід звідси, у Саду Лоа.\n\nТи одразу помітиш його тотеми. Пробігай біля них — вони додадуть тобі швидкості.\n\nА я тим часом далі очищатиму цей храм від єретиків.\n\nПоводься чемно перед лоа, а то він може й горлянку тобі вирвати.",
        objectives = "Домовся з Ґонком.",
        completion = "О, добре. Він не вирвав тобі горлянку. Це добрий знак. Ходімо, покажемо людям твій вибір.",
    },
    [47440] = {
        title = "Па'ку, Володарка Вітрів",
        description = "Ходімо, сідай зі мною на Ату Крилоповелителя — він донесе нас до Па'ку.\n\nА, і поводься чемно перед цим лоа. Кажуть, Па'ку скидала послідовників, які були їй не до вподоби, з дуже великої висоти на дуже тверде каміння.",
        objectives = "Домовся з Па'ку.",
        completion = "О, добре. Вона не скинула тебе вниз. Це добрий знак. Ходімо, покажемо людям твій вибір.",
    },
    [47441] = {
        title = "Шкідники",
        description = "Дай-но вгадаю, саурид і в тебе щось поцупив, еге ж? Слухай, я не маю часу ганятися за кожною дрібничкою, яку ці гризуни поцупили.\n\nХочеш трохи грошей? Допоможи мені перебити цих кусак.\n\nА як ні — то дай мені спокій.",
        objectives = "Убий 8 Злодійкуватих Хапунів у Зокало.",
        completion = "Злодій прийшов красти в злодіїв?",
    },
    [47442] = {
        title = "Прокляття Джані",
        description = "Злодію і вбивце, знай, що ти стоїш перед Покровителем Сміттярів, Володарем Злодіїв, Богом Покидьків, Повелителем Поплічників і Хранителем Таємниць.\n\nТи стоїш переді мною у вбранні, вартому цілих королівств золота, з такою зброєю, що коштує більше, ніж зароблять навіть мої найвідданіші й найславетніші послідовники.\n\nГадаю, зараз слушна нагода провчити тебе. Може, показати твоїй гордовитій величі, що то воно — нишпорити по канавах.",
        objectives = "Виживи у Випробуванні Джані.",
        completion = "Ха-ха! Гарна робота, багатий незнайомцю. Коли будеш у цих землях, тримай очі відкритими. Ніколи не знаєш, коли хтось із дітей укаже тобі на корисне місце.",
    },
    [47445] = {
        title = "Рада Занчулі",
        description = "Гей, ти, Речнику Орди.\n\nМої шпигуни доповіли мені про темні єресі, що кояться в нашому священному храмі Занчул.\n\nКороль послав Лоті й Раала владнати справу, але ці двоє членів ради вічно гризуться між собою, а до власних послідовників надто м'які.\n\nНам потрібен хтось більш... безжально безсторонній.\n\nЗустрінься з Бойовою друїдкою Лоті внизу, на Зокало, — решту вона розкаже сама.",
        objectives = "Поговори з бойовою друїдкою Лоті в Зокало.",
        completion = "Ласкаво просимо на сходи Занчулі, {NAME}. Скоро ти ступиш на священну землю.",
    },
    [47456] = {
        title = "Утихомирення Порожнечі",
    },
    [47473] = {
        title = "Оцінка супротивника",
        description = "Тураліон, поза сумнівом, сподівався на кращі новини, але, боюся, я не можу їх дати. Спроба прорватися в саме серце Легіону зараз коштувала б нам усього.\n\nМає бути інший шлях. Я не знаю, який саме, але вірю, що ми його знайдемо.\n\nКраще не змушувати Тураліона чекати. Ми мусимо рухатися далі.",
    },
    [47485] = {
        title = "Торгова компанія Ешвейн",
        description = "Отже, посіпаки Ешвейн розгулюють із новим порохом, що може розколоти галеон навпіл, а військові й гадки не мають.\n\nНам треба з'ясувати, скільки в них цього пороху і куди він прямує.\n\nМій давній приятель працює на поромі біля Ливарні Ешвейн. Можливо, він щось про це знає.\n\nТи можеш сісти на пором із Ринку Торгових Вітрів до Станції Східної Точки. Коли дістанешся туди, шукай чоловіка на ім'я Кеґні. Скажи, що тебе прислав я. Він мені винен послугу.",
    },
    [47486] = {
        title = "Підозрілі вантажі",
        description = "Зазвичай я б тобі нічого не сказав... але заради Сайруса розповім.\n\nЕшвейн затіяла щось велике.\n\nУ них там люди гарують цілодобово. Навіть привезли кількох здорованів, щоб усіх... \"підбадьорювати\".\n\nЯ не знаю, що саме вони роблять, але знаю, що сюди, до Бораля, воно не проходить.\n\nЯкби я був досить дурний, щоб піти туди винюхувати, я б оглянув самі товари. Подивився б, чи є на них транспортні наклейки.\n\nАле я не такий дурний, тож зробити це доведеться тобі.",
    },
    [47487] = {
        title = "Трудовий конфлікт",
        description = "Компанія Ешвейн так виснажувала своїх людей, що ті навіть спробували влаштувати страйк! \n\nКомпанія привезла купу посіпак, щоб придушити його й загнати всіх назад на роботу. \n\nЧув, вони навіть застрелили кількох хлопців, які спробували покинути роботу.\n\nЩо скажеш, як даси їм скуштувати їхньої ж жорстокості, поки ти там?",
    },
    [47488] = {
        title = "Маленькі носії",
        description = "<шморгає носом>\n\nВони казали, що годуватимуть нас. Казали, що ми будемо в теплі.\n\n<Олів витирає носа рукавом свого пальта.>\n\nАле вони були злі! І робота була справді важка. А коли ми намагалися відпочити, вони кричали на нас!\n\n<шморгає носом>\n\nЯ втекла, але мої друзі досі там.",
    },
    [47489] = {
        title = "Заховайся та пливи",
        description = "<Флінн піднімає комір, ховаючи обличчя, і говорить до тебе пошепки.>\n\nБачиш отой корабель? Я його знаю.\n\nСкажімо так: у нас із його капітанкою є невеличка спільна історія.\n\nЦе контрабандистське судно. На ньому точно наша незаконна зброя. Готовий закласти свій плащ... а я цей плащ люблю.\n\nНам треба з'ясувати, куди воно прямує...\n\nЯк ти почуваєшся в тісних місцях?",
    },
    [47491] = {
        title = "Рештки проклятих",
        description = "Відколи духи почали взивати до цього «Ґ'гууна», мій храм укрила нестерпна скверна нежиті.\n\nНежить — то гидота, але кровокамені, які її породжують, мають велику силу. Вони ще можуть стати Бвонсамді в пригоді.\n\nХочеш показати мені свій запал — очисти мій храм від цього бруду й принеси мені їхні кровокамені.",
        objectives = "Збери 6 Зотлілих Кровокаменів для Бвонсамді.",
        progress = "Дістав мені ті кровокамені?",
        completion = "Ммм, ці якраз підійдуть.",
    },
    [47493] = {
        title = "Самотній дух",
        description = "Землями мого храму блукає дух дитини на ім'я Кеула. Її мамця колись давно віддала мені своє дитя: думала, що така велика жертва вбереже її саму від мого поклику — від переходу на Той Бік.\n\nЩо ж, вона мала рацію: я її ще не забрав. Але вона й помилялася. Це її дитя вирішує, коли їм із мамцею бути разом знову, — і здається мені, що дитині вже несила чекати.\n\nЇм обом місце в моєму царстві.\n\nІди й приведи малу до її мамці.",
        objectives = "Розшукай Кеулу в Некрополі.",
        completion = "Хто ти? Ти бачив ма'ду?",
    },
    [47496] = {
        title = "Трощитель бункерів",
    },
    [47497] = {
        title = "Знайомство з бандою Золотого Ікла",
        description = "Вітаю, $p(мандрівнику:мандрівнице), і ласкаво просимо до корчми \"Золоте Ікло\"!\n\nХіба що ти прийш$p(ов:ла) нас повбивати... Тоді — геть звідси.\n\nА як ні — сідай і насолоджуйся розгардіяшем!\n\nТобто не зважай на розгардіяш. ЇЖ РОЗГАРДІЯШ! Ні, не їж розгардіяш. Не зважай на нього!\n\n<Ран'ка повертається до черепа з пов'язкою на оці й люто кричить щось зандаларською.>\n\nХа, не зважай на нього. Усі вигнанці можуть відпочити в корчмі \"Золоте Ікло\" — єдиному розкішному притулку серед цих суворих дюн.\n\nХодімо, познайомлю тебе з персоналом.",
    },
    [47498] = {
        title = "Загублений друг Ран'ки",
        description = "Коли підіймешся до Перевалу Мерця, неодмінно передай вітання Зулсану.\n\nВін мій найкращий друг, навіть якщо більшість часу не хоче бути поруч зі мною. Ха!\n\nА якщо серйозно — він уже кілька днів сидить там, на скелях. Якщо знайдеш його, переконай повернутися до корчми. Він нам потрібен, щоб поповнити наш сніданковий буфет.\n\nА, і зовсім стороннє питання, яке геть ніяк не пов'язане з тим, що ти можеш не знайти Зулсана й мені доведеться шукати йому заміну: яка завширшки в тебе голова?",
    },
    [47499] = {
        title = "Вишкірені ідоли",
        description = "До прокляття ми були вірною командою при доброму капітані. Та прокляття зіпсувало піратського короля Зем'лана, зробило його жорстоким і владним.\n\nТепер він ставиться до нас радше як до рабів, ніж до товаришів по команді. Змушує битися й гинути заради його зиску, а нам — ніяких скарбів. І слова не скажи без покарання.\n\nЩо ж, ми четверо більше не будемо його рабами.\n\nУ декого з команди лишилися ідоли, якими Зем'лан нас проклинав. Убий їх і забери ідолів. Хочу глянути, чи можна їх розбити. Просто заради втіхи.",
    },
    [47501] = {
        title = "Брудна робота за брудне питво",
        description = "Гості в корчмі \"Золоте Ікло\" мусять відробляти своє утримання. Що скажеш, як допоможеш мені перебити кількох скорпідів на одному з наших виїзних місць для прогулянок? На чарівному Перевалі Мерця!\n\nЗазвичай, щоб тебе туди пустили, треба придбати наш пакет \"Воєначальник\", але цього разу я зроблю виняток.\n\nЯ навіть докину наш пакет \"Король скорпідів\". Необмежено напоїв із крові скорпідів цілий день, щодня!\n\nОдна заковика: у нас закінчилася кров скорпідів. Принеси трохи, і я приготую нам порцію напоїв.",
    },
    [47502] = {
        title = "Велика черепна оборудка",
        description = "Щойно ти піш$p(ов:ла), головорізи Піщаної Люті напали на корчму й викрали всю банду Золотого Ікла!\n\nМи мусимо їх повернути.\n\nЗазвичай мізками наших крадіжок ще в Зулдазарі був Ман'зул, але я спробую вигадати план, як витягти їх із цієї халепи.\n\n<Ран'ка якийсь час думає.>\n\nПридумав! ТИ всіх їх врятуєш!",
    },
    [47503] = {
        title = "Ґозда'кун Работорговець",
        description = "Усе. Піщаній Люті офіційно заборонено вхід до корчми \"Золоте Ікло\"!\n\nНе можна просто так розгромити заклад, викрасти його персонал, поглумитися з власника всілякими фруктами й овочами — і думати, що тобі це минеться!\n\nМи покажемо цим головорізам, що буває, коли зачіпаєш банду Золотого Ікла!\n\nҐозда'кун Работорговець командував рештою Піщаної Люті під час нападу.\n\nЗнищ його, але залиш кількох із Піщаної Люті живими, щоб рознесли звістку.",
    },
    [47507] = {
        title = "Казадуум",
    },
    [47508] = {
        title = "Вогонь за готовністю",
        description = "Глянь туди — небо вкрите крилами кажанів. Ми мусимо надати яку зможемо підтримку дальнім боєм, але тут у нас і так клопоту по горло.\n\nСхоже, Легіон ще не знищив усі артилерійські батареї. Якщо доберешся до однієї з них, то зможеш показати цим крилатим нечистям Світло.",
    },
    [47509] = {
        title = "Тераса Обраних",
        description = "Ця зрада глибоко поранила саме серце Зандалара. Половина ради Занчулі та їхні прибічники стали на бік Зула і його... бога крові.\n\nНа щастя для нас, не весь Зандалар підтримує цю зраду.\n\nМи мусимо повалити культистів Зула, перш ніж вони згуртують надто багато люду до своєї справи. Почати варто із Занчулу.\n\nІди й глянь, чи зможеш зібрати тих зандаларі, що досі вірні своєму королю.",
        objectives = "Зустрінься з Каза'джином В'язальником Хвиль біля Тераси Обраних.",
        completion = "{NAME}, радий бачити, що ти ще не мертвий.",
    },
    [47512] = {
        title = "Назмір",
        description = "Криваві тролі з проклятого болота Назмір загрожують знищити весь Зулдазар.\n\nПринцеса Таланджі просить в Орди допомоги в експедиції, щоб ударити в саме серце кривавих тролів і покласти край їхній загрозі Зулдазару.",
        objectives = "Поговори з принцесою Таланджі.",
        completion = "Болото Назміру — найбільша загроза для мого народу. Я рада, що ти обрав допомогти мені в цьому.",
    },
    [47513] = {
        title = "Вол'дун",
        description = "Генерал Джакра'зет ненавидить Орду, і довіряти йому не можна. Доки він при владі, місто ніколи не буде в безпеці.\n\nНе лише ми маємо такі підозри. Поговори з принцесою Таланджі, щоб дізнатися більше.",
        objectives = "Поговори з принцесою Таланджі.",
        completion = "Джакра'зет — серйозна загроза для мого королівства і твоєї Орди. Тобі варто дослідити його діяльність.",
    },
    [47514] = {
        title = "Зулдазар",
        description = "Король Растахан — прадавній володар, що не квапиться довіряти новим союзникам. Мусимо заслужити його довіру, якщо хочемо здобути його флот.\n\nЗулдазар — осердя влади Зандаларської імперії й добре місце, щоб почати прихиляти цих можливих союзників на свій бік.",
        objectives = "Поговори з принцесою Таланджі.",
        completion = "Довіру мого батька заслужити нелегко.\n\nПовір мені.",
    },
    [47518] = {
        title = "Раал",
        description = "Кразак — це зрадник у жрецькому вбранні, який гадає, що коли катуватиме досить багато наших, то цим зашкодить нашим лоа.\n\nВони навіть затягли мого чоловіка Раала на верхівку Занчула. Зазвичай я б сказала, що хай би й забирали його собі, та вони використовують його зв'язок із Па'ку, щоб послабити лоа.\n\nА цього допустити не можна. Тож піднімімося на верхівку Занчула й врятуймо мого нікчемного чоловіка.",
        objectives = "Убий Кразака і звільни Володаря вроків Раала.",
        completion = "Ая... обов'язково було приводити Лоті? Вона мені цього ніколи не забуде.",
    },
    [47520] = {
        title = "І стіни мають вуха",
        description = "Язма, володарка шпигунів.\n\nТьху! Зрадниця, яка кохається в усякій повзучій гидоті. Вона стала на бік Зула й використовує дітей своєї лоа, Шадри, щоб стежити за кожним нашим кроком.\n\nМи мусимо вбивати всіх павуків, яких побачимо, інакше та зрадниця Язма знатиме про кожен наш рух.",
        objectives = "Убий 8 павуків у Занчулі.",
        completion = "Гарна робота. Це має засліпити Язму.",
    },
    [47521] = {
        title = "Опівночі в саду лоа",
        description = "Язма та її поплічник-троль Вол'каал відтягли більшість своїх сил назад до Саду лоа.\n\nКоїться щось лихе, я відчуваю це душею. Па'ку в небезпеці, а разом із нею і всі лоа, що мають там послідовників.\n\nХодімо, полетімо туди й покладімо край цим єресям.",
        objectives = "Лети з Володарем вроків Раалом до Саду Лоа.",
        completion = "Звідси ми зможемо вдарити у відповідь по наших ворогах.",
    },
    [47522] = {
        title = "Мисливець",
        description = "Гонк у небезпеці. Я чую його поклик.\n\nМоя лоа стільки разів рятувала мені життя, що тепер саме час відплатити за послугу.\n\nХодімо зі мною до Лігва Гонка на західному боці Саду лоа — і ми врятуємо бога.",
        objectives = "Урятуй Ґонка.",
        completion = "Вони прагнуть нас убити. Вони прагнуть нас зламати.\n\nУсе, чого вони досягли, — об'єднали нас для найбільшого полювання, яке коли-небудь знали зандаларі.",
    },
    [47523] = {
        title = "Виявлено збурення: Чорний храм",
        description = "{name}, точно вчасно, як завжди.\n\nСпершу добра новина, бо для мене вони все одно відбуваються водночас. Завдяки різноманітним викривленим у часі об'єктам з минулого й майбутнього, які ти знайш$p(ов:ла), ми збагнули, як виявляти появу нового такого об'єкта.\n\nА погана новина в тому, що ми знаємо, що наш метод працює, бо щось змінилося в Чорному храмі, і це сіє хаос по всьому часоплину! Нам потрібно, щоб ти подба$p(в:ла), аби той доленосний рейд минув точнісінько так, як і раніше, та усунув джерело цього збурення.",
        objectives = "Переживи наново штурм Чорного храму.",
        progress = "Будь особливо обережним, щоб напад на Храм минув точно так, як і минув.  Один зайвий помах крил бабки — і ти можеш убити Іллідана по-справжньому!  А тоді уяви, у яку халепу ми втрапимо!",
        completion = "Що це, {NAME}?\n\n<Ворму переглядає плани, спантеличено насупивши брови, поки слова совгаються туди-сюди>\n\nЦе плани нападу на Мардум. Невже ми запізнилися?\n\nДивно те, що новий план здається кращим за початковий!  Навряд чи це справа Легіону, бо Іллідан напевно виявив би будь-яку маніпуляцію скверною. То якщо не Легіон, хто за цим стоїть?",
    },
    [47525] = {
        title = "Лишатися непоміченими",
        description = "Назріває халепа, $p(друже:подруго). Криваві тролі заворушилися! Розбили неподалік великий табір і шлють невеликий загін на острів на південь звідси.\n\nЯкщо вони винюхають нашу позицію, поки ми без захисту, — нам кінець! Треба з'ясувати, що вони замислили, і здихатися їх.\n\nНайкраще почати з того острова на півдні. Підеш зі мною? Я готова вирушати.",
        objectives = "Дослідь Жаб'яче Багно.",
        completion = "Я більше не можу битися. Криваві тролі — вони серйозно взялися за Краґ'ву. Вони збираються згодувати його своєму кривавому богові!",
    },
    [47526] = {
        title = "Підкотити важку артилерію",
        description = "Присуд Світла має захисний механізм, щоб не потрапити до ворожих рук. Ми можемо запустити його механізм повернення, який телепортує його назад на судно.\n\nОскільки «Ксенедар» вийшов з ладу, гармата має повернутися натомість на твій корабель. Ти зможеш добре скористатися її вогневою міццю.\n\nОднак цей процес потребує часу й, найпевніше, приверне увагу Легіону. Будь насторожі.",
    },
    [47527] = {
        title = "Ритуали єресі",
    },
    [47528] = {
        title = "Володарка брехні",
        description = "Якщо ти вже впора$p(вся:лася) з цими селянськими лоа, то, можливо, допоможеш із моєю власною лоа — Шадрою.\n\nЗа всім цим стоїть моя «верховна» жриця Язма. Якщо вона підбурює своїх посіпак убивати інших лоа, то можу лише здогадуватися, що вона намагається принести в жертву й мою власну лоа.\n\nСвятилище Шадри — на північно-західному боці Саду лоа. Ти мусиш завадити їй убити Володарку шпигунів.",
        objectives = "Здолай Язму і Вол'каала в Саду Лоа.",
        completion = "Шадру... поглинули? Я чув про такі єресі в Зул'Драку, але щоб у Зулдазарі...",
    },
    [47529] = {
        title = "Надприродна підтримка",
        description = "Лоа можуть дарувати своїм послідовникам могутні благословення — допомогу, яка може стати різницею між перемогою чи поразкою в наших тутешніх зусиллях.\n\nДобре поміркуй, у кого з цих двох ти хоті$p(в:ла) би попросити благословення. Лоа не нададуть допомоги тим, хто наразі присягнув іншому лоа.",
    },
    [47540] = {
        title = "Тотемне відновлення",
        description = "Мене нагодовано, і тіло моє готове. Тепер я можу знову сповнитися давньою силою — і на якийсь час стану несприйнятливим до їхніх кривавих прокльонів і чарів висмоктування.\n\nСкористайся магією світляків, щоб перелити мою силу з тотемів у мене.\nСкоро ти побачиш мене відновленим. Тоді ми знищимо військо, що готується за рікою забрати силоміць усе, що належить мені.",
        objectives = "Активуй силу тотемів і віднови Краґ'ву.",
        completion = "Я знову почуваюся собою — як тоді, коли сотні послідовників вливали в мене свою віру. Моя сила згасне, але тролі знову навчаться боятися Краґ'ви!",
    },
    [47541] = {
        title = "Найкращий захист",
        description = "Якщо ти поверну$p(в:ла) нам Верховного екзарха, то ти справді бажаний союзник.\n\nАле нам потрібно більше. Бачиш наших солдатів, що б'ються попри всі негаразди? Захисти їх. Знищ ворога.\n\nГорді слова як для жерця, можливо, та кожен мертвий ман'арі — це на один клинок менше біля наших горлянок.\n\nПокажи їм, що Світло береже своїх обранців і так само палить невірних.\n\nКоли впораєшся, знайди Й'меру. У неї менше воїнів, а отже, більша потреба у твоїх уміннях.",
    },
    [47542] = {
        title = "Майстер облоги Вораан",
    },
    [47543] = {
        title = "День, коли Хромі помре",
        description = "О, {name}! Я саме про тебе думала! Ось що значить опинитися в потрібний час у потрібному місці!\n\nЯ якраз переглядала деякі аномалії на часових шляхах, коли виявила щось... несподіване. Щось не дуже приємне.\n\nУ недалекому майбутньому я загину. Кепські справи.\n\nЯ вже зібралася стрибнути вперед і з'ясувати, чому, як, хто... але мені було б спокійніше, якби поруч був {race} на кшталт тебе. Складеш мені компанію?",
    },
    [47545] = {
        title = "Перемотка",
        description = "Тепер ми знаємо, коли станеться напад і приблизно звідки він прийде. Поступ! Лишилося тільки дізнатися більше подробиць і зупинити той напад!\n\nДай знати, коли будеш готовий спробувати ще раз.",
    },
    [47550] = {
        title = "Численні переваги буття драконом часу",
        description = "Що ж, на лихо для... того, хто так прагне розвіяти мене в небуття, я доволі вправна володарка часових шляхів! У нас є перевага: спробувати ще раз, і ще, і ще, доки я знову не буду живою.\n\nНам знадобиться трохи більше, ніж кілька секунд, аби зупинити цей напад. Як щодо чотирьох годин?",
