    [47552] = {
        title = "Володарка Іл'тендра",
    },
    [47554] = {
        title = "Перехоплення планів Легіону",
        description = "Наша розвідниця Скара пише в посланні, що дізналася про велику операцію Легіону. Вона полювала на два зашифровані накази, які тримали війська Легіону неподалік, щоб роздобути подробиці, — і, певно, саме тоді її вбили. Легіон розбиває свої повідомлення на зашифровані частини, щоб ми не могли їх прочитати.\n\nСкара також пише, що її напарниця Бре, дешифрувальниця, загинула, намагаючись дістатися до наших позицій із книгою кодів, яка потрібна нам, щоб розшифрувати накази Легіону. Конче важливо, щоб ти знайш$p(ов:ла) і ті накази, і ту книгу кодів!",
    },
    [47557] = {
        title = "Тліючий хроноскалок",
        description = "Цей кристалічний скалок гарячий на дотик. Істота Порожнечі, яка його носила, аж ніяк не була володаркою полум'я, тож, можливо, хроноскалок пов'язаний з вогнем якось інакше.",
    },
    [47558] = {
        title = "Хроноскалок, торкнутий Скверною",
        description = "Цей кристалічний скалок пописаний глибокими борознами зеленої злостивої енергії. Ось що буває, коли тебе тримає в руках жахолорд.",
    },
    [47559] = {
        title = "Осяйний хроноскалок",
        description = "Цей кристалічний скалок мерехтить металевим полиском. Судячи з реакції Хромі, його можна використати, щоб з'єднати тебе з іншим часом і місцем.",
    },
    [47560] = {
        title = "Замерзлий хроноскалок",
        description = "Цей кристалічний скалок вкритий тонким крижаним шаром вічної мерзлоти. Від нього досі віє тим характерним запахом ліча.",
    },
    [47561] = {
        title = "Пухиропаща",
