    [50987] = {
        title = "Замовлення: моелітова руда",
        progress = "Ти тут, щоб доставити припаси?\nМонелітова Руда (20)",
        completion = "Дякую за допомогу, шахтарю. Нам дуже потрібна була ця монелітова руда.",
    },
    [50988] = {
        title = "Економічна нагода",
        description = "На вигляд ти достатньо кмітливий, щоб ухопитися за нагоду, коли вона трапляється, і, $p(друже:подруго), у мене якраз є одна для тебе.\n\nБачиш ту бухту внизу? Нею керують підприємці, які пильнують, аби залатати ті логістичні прогалини, що виникають у будь-якому звичайному місті чи містечку. Тобто зазвичай керують саме вони.\n\nАле в нас тут трохи завелися люди радше найманського штибу, якщо ти розумієш, про що я.\n\nДопоможи мені повернути контроль над бухтою, і я подбаю, щоб до тебе тут добре ставилися. Згода?",
    },
    [50989] = {
        title = "Замовлення: штормосрібна руда",
        progress = "Ти тут, щоб доставити припаси?\nШтормове срібло (10)",
        completion = "Дякую за допомогу, шахтарю. Нам дуже потрібне було це грозове срібло.",
    },
    [50990] = {
        title = "Передова наука про птахів",
        description = "<Перед тобою смачнюща курка... І все ж, попри все, у цьому створінні є щось трохи... жвавеньке.\n\nЗ розумним підходом і дрібкою науки для цього бідолашного птаха ще можна щось зробити.\n\nТи вирішуєш якнайшвидше віднести курку до д-ра Оґлторпа в Бухту Здобичі.>",
    },
