    [51794] = {
        title = "Випробування вивергального тотема",
    },
    [51795] = {
        title = "Битва за Лордерон",
        description = "Король Рінн зібрав наші сили, {name}. Ми маємо намір розпочати повномасштабний наступ на Лордерон.\n\nМи виженемо Орду з фортеці й повернемо її Альянсу. Минуло надто багато часу відтоді, як наш прапор майорів над Тірісфалем.\n\nГотов$p(ий:а) вирушати? Капітанка Анжеліка подбає про твоє перевезення.",
    },
    [51796] = {
        title = "Битва за Лордерон",
        description = "Альянс скликав свої знамена й рушає на Андерсіті.\n\nТепер війна почалася по-справжньому.\n\nНаша чарівниця відправить тебе. Іди.\n\nПодбай про нашу оборону й виведи цивільних у безпеку. Я скоро приєднаюся до тебе.\n\nЛок-тар огар, {name}.",
    },
    [51797] = {
        title = "Вистежити приливомудрого",
        description = "Рекссар вистежує могутнього приливомудрого, який допоможе нам знайти тіло маршала Валентайна. Він повідомив, що стався прорив.\n\nВирушай до Штормоспіву. Допоможи напіворку й Ліліан знайти цього приливомудрого і схилити його до волі Орди.\n\nНе повертайся без способу відшукати маршала Валентайна.",
    },
    [51798] = {
        title = "Жодна ціна не зависока",
        description = "Я вистежив приливомудрого до табору неподалік. Він мешкає там зі своєю родиною.\n\nАле стережися: приливомудрі — могутні вороги. Вони володіють усіма стихіями, а дехто навіть керує Порожнечею.\n\nЯкщо цей чоловік разом із родиною, то, можливо, він не здасться так легко.\n\nСподіваймося, у нього стане розуму не вплутувати їх у це.\n\nХодімо.",
    },
    [51800] = {
        title = "Опорний пункт: Тірагардська затока",
        description = "На узбережжі Тірагардської затоки повно піратів.\n\nЯ зв'язався з першою помічницею однієї команди, і вона гадає, що ми зможемо здолати капітана й заразом здобути гарний форпост.\n\n          - Мисливець тіні Тай'джин",
        objectives = "Допоможи тіньовому мисливцеві Тай'джину в Тірагардській Затоці.",
        completion = "<Ти обрав вирушити до Тірагардської Затоки.>",
    },
    [51801] = {
        title = "Опорний пункт: Друствар",
        description = "Схоже, під Друстваром залягає велика жила азериту.\n\nЛюбиш зиск? А я ОБОЖНЮЮ зиск. Скидається на золоту нагоду, якщо розумієш, про що я. Час — це гроші!\n\n          - Торговий принц Ґаллівікс",
        objectives = "Допоможи Ґаллівіксу й Ейтріґґу в Друстварі.",
        completion = "Ти обрав пливти до Друствару.",
    },
    [51802] = {
        title = "Опорний пункт: долина Штормоспіву",
        description = "Ми збудували й укріпили в долині Штормоспіву форпост під назвою Твердиня Бойового Ікла.\n\nВійська Кул-Тіраса оточили його, і напад неминучий. Нам потрібне підкріплення. Не зволікай.\n\n                                 - Рекссар",
        objectives = "Допоможи Рекссару в Долині Штормоспіву.",
        completion = "Ти обрав пливти до Долини Штормоспіву.",
    },
    [51803] = {
        title = "Кампанія в Кул-Тірасі",
        description = "Наш ворог поширює свій вплив по всьому Кул-Тірасу, вербуючи нових союзників для боротьби проти Орди.\n\nМи мусимо закріпитися на цих ворожих землях, якщо хочемо перемогти в цій війні.\n\nВождь потребує твоєї допомоги, щоб захопити форпости в долині Штормоспіву, у Друстварі та Тірагардській затоці.\n\nЯке місце захопимо першим?",
        objectives = "Скористайся Мапою Кампанії Кул-Тіраса, щоб обрати опорний пункт.",
        completion = "Ти маєш довіру Королеви. Поки що.",
    },
    [51804] = {
        title = "Безперервні перешкоди",
    },
    [51805] = {
        title = "Вони пізнають страх",
        description = "Нарешті нагода вдарити по Альянсу І по кул-тіранцях!\n\nМудрецький Вал кишить учнями-приливомудрими, які вивчають магію, та кул-тіранцями, що намагаються укріпити це місце проти Орди.\n\nВсіймо в них страх. Хай двічі подумають, перш ніж допомагати Альянсу в боротьбі проти Орди.\n\nВізьми цей ріг. У моїх руках він прикликає вал'кір. У твоїх — він посіє жах серед наших ворогів.\n\nЯ довіряю цей ріг тобі більше, ніж будь-кому. Не підведи мене.",
    },
    [51806] = {
        title = "Винищувач шкідників, мод. II",
    },
    [51810] = {
        title = "Капітан Гартфорд",
        description = "Я майже готовий покинути Вол'дун раз і назавжди. Лишилося зробити тільки одне...\n\nНам треба вбити капітана корабля.\n\nЯкщо капітан Гартфорд дізнається, що я дезертирував, я не буду в безпеці ні в Боралусі, ні деінде. Він гнатиметься за мною аж до Східних Королівств і назад, якщо доведеться!\n\nЦе буде небезпечно. Тож тобі варто перевдягтися, перш ніж зійти на борт «Поклику Сирени».\n\nЦе буде наша остання спільна справа. Зроби це — і я дам тобі код від скрині капітана. Піратський скарб!",
    },
    [51811] = {
        title = "Тортолани в пастці",
    },
    [51813] = {
        title = "Глибини Блекрока",
        description = "Ти чув, як двергари Темного Заліза приєдналися до Альянсу? Це був вельми незвичайний поворот подій.\n\nХоробрі герої Альянсу роками воювали з двергарами Темного Заліза, аж доки в їхніх лавах не стався розкол.\n\nМойра Тауріссан, відчужена донька колишнього короля двергарів Маґні Бронзбірд, очолювала одну з фракцій двергарів Темного Заліза.\n\nМойра прагнула допомогти Альянсу. Усе почалося з пропозиції допомогти дослідити азерит і його можливе застосування в Глибинах Блекрок...",
    },
    [51814] = {
        title = "Рапторожерливість",
    },
    [51815] = {
        title = "Яйцезнищення",
    },
    [51816] = {
        title = "Птерасні інгредієнти",
    },
    [51817] = {
        title = "Тортолани в пастці",
    },
    [51818] = {
        title = "Командир і капітан",
        description = "Мені це не приносить радості, {name}, але я зроблю те, що мушу, аби моя родина була щаслива й у безпеці.\n\nЯ волів би уникнути насильства, але якщо доведеться... є дві цілі. Їхні очільники. Капітан Малія та командир Авґустин.\n\nЇхня загибель має змусити обидві групи відступити з цих місць.\n\nКрім того, Авґустин конфіскував мою книгу. Поверни її — і моя сила буде твоєю, скільки б мені не лишилося.",
    },
    [51819] = {
        title = "Розсіяти наших ворогів",
        description = "Ми вже певний час розвідуємо околиці Мудрецького Валу. Нещодавно його відбили великі сили Альянсу та кул-тіранців.\n\nМи чекали нагоди вдарити, коли їхній захист ослабне. Тепер така мить настала.\n\nСпустися до Мудрецького Валу й покажи тим, хто там лишився, що чекає на тих, хто підіймає зброю проти Орди.",
    },
    [51820] = {
        title = "Масна халепа",
    },
    [51821] = {
        title = "Лад у бухті",
