    },
    [52472] = {
        title = "Уперед, Ло!",
        description = "Вітаю, {name}! Ми, тортоллани, змалечку слухаємо історії про Лога — тортоллана, що пережив безліч пригод. Ці оповіді гартують розум юного тортоллана, який намагається збагнути, як саме Лог здолав би ту чи іншу пригоду.\n\nХочеш спробувати?",
        objectives = "Навчися вести Ло.",
        completion = "Гарна робота, {NAME}!",
