    [53120] = {
        title = "Екзотичні прянощі",
        description = "О, вітаю! Маєш щось для мене?",
    },
    [53121] = {
        title = "Облога Боралуса",
        completion = "Шкода, що ти це пропустив, {NAME}. Дворфи-вершники на грифонах заскочили нас зненацька, та навряд чи вони очікували, що ми напхаємо на один човен стільки навчених убивць.\n\nНавіть Зеллінг устряв у розвагу!\n\nНа одному з дворфських трупів я знайшов цього листа. Схоже, між керівництвом Кул Тіраса й одним із їхніх домів, домом Ешвейн, назріває напруга. Це може дати нам гарну нагоду посіяти хаос у Боралусі.",
    },
    [53122] = {
        title = "Час для святкування",
        description = "Доброго дня, {class:v}.\n\nЗатінкова ніч — це час святкувань і роздумів, хоча декотрі й гадки не мають чому. Спалення Плетеного чоловіка зокрема лишається загадкою для багатьох, хто не належить до Відступників.\n\nВирушай до руїн Лордерона і поговори з Темнокличкою Янкою. Вона розповість тобі більше про церемонію Плетеного чоловіка.",
    },
    [53125] = {
        title = "Звіт про місію: У плетіння",
        description = "Твої прибічники надіслали звіт про місію в бухті Мулорибів.\n\nУ ньому йдеться, що місія завершилася успіхом, і тамтешні друїди завдяки цьому поглибили свої друїдські знання.\n\nДостав цей звіт Натаносу Лиховісникові на борту \"Плачу Банші\".",
    },
    [53126] = {
        title = "Лозовий тотем",
        description = "Оборону бухти Грязерибів відбито успішно. Молодець, {name}.\n\nПісля бою серед уламків знайшли загадковий тотем, який може стати тобі в пригоді під час пригод у Друстварі.\n\nВирушай до бухти Грязерибів у Друстварі й дізнайся, яку силу приховує цей тотем.",
    },
    [53127] = {
        title = "Плач лорда-адмірала",
        description = "У скрині лежить кілька особистих речей лорда-адмірала Деліна Праудмура. Серед них — згорнутий лист, запечатаний морсько-зеленим воском із відбитком герба Праудмурів. Пергамент легко рветься й потребує обережного поводження, а чорнило здебільшого змили час і морський приплив.\n\nМожливо, хтось зуміє відновити лист і розкрити його зміст.",
    },
    [53128] = {
        title = "Плач лорда-адмірала",
        description = "У скрині лежить кілька особистих речей лорда-адмірала Деліна Праудмура. Серед них — згорнутий лист, запечатаний морсько-зеленим воском із відбитком герба Праудмурів. Пергамент легко рветься й потребує обережного поводження, а чорнило здебільшого змили час і морський приплив.\n\nМожливо, хтось зуміє відновити лист і розкрити його зміст.",
    },
    [53129] = {
        title = "Закривавлена глефа вартової",
        description = "Глефа лежить за кілька сантиметрів від простягнутих пальців вартової. Її незрячі очі застигло дивляться на попелясту оболонку Тельдрассилу на обрії.\n\nМожливо, хтось в Оґриммарі розповість тобі, що тут сталося.",
    },
    [53130] = {
        title = "Закривавлена глефа вартової",
        description = "Глефа лежить за кілька сантиметрів від простягнутих пальців вартової. Її незрячі очі застигло дивляться на попелясту оболонку Тельдрассилу на обрії.\n\nМожливо, хтось у Стормвінді розповість тобі, що тут сталося.",
    },
    [53131] = {
        title = "Спочинок Королів",
        completion = "Орда прибула сюди не лише заради перевезення сан'лейнів. Тут повно високопосадовців Орди. Щось коїться.\n\nОдна з переваг полювання на важливих цілей Орди в тому, що вони зазвичай носять із собою важливі відомості. Поглянь на цю карту, яку я знайшов на одному з тіл. Бачиш велике червоне коло довкола «Спочинку Королів»? Що таке Спочинок Королів? Чому Альянс про це не знає?\n\nТреба з'ясувати це, щойно повернемося на суходіл.",
    },
    [53146] = {
        title = "Прочуханка Каменюкам",
        description = "Оґри Каменюки дошкуляють Араті ще з часів Другої війни, і досі нікуди не поділися.\n\nТи знаєш, що треба зробити.",
    },
    [53148] = {
        title = "Прочуханка Каменюкам",
        description = "Якщо оґри Каменюки не бажають приєднатися до Орди, то немає їм місця в Араті.\n\nТи знаєш, що треба зробити.",
    },
    [53149] = {
        title = "Винищення Візербарків",
        description = "У племені Візербарків довга й кривава історія на узгір'ях Араті.\n\nПокажи їм, наскільки кривавішою вона може стати.",
    },
    [53150] = {
        title = "Винищення Візербарків",
        description = "Кровожерливе плем'я Візербарків завжди відмовлялося приєднатися до Орди... і тепер, коли Орда тримає Араті, ми досягнемо того, що не вдалося Альянсу.\n\nЖени лісових тролів геть з узгір'їв.",
    },
    [53151] = {
        title = "Звіт про місію: Вовки для лігва",
        description = "Твої прибічники надіслали звіт про місію у Вовчому лігві.\n\nУ ньому йдеться, що місія завершилася успіхом і тепер зграя люто вовків охороняє форпост.\n\nДоправ звіт Натаносу Лиховісникові на борт «Зойку Банші».",
    },
    [53152] = {
        title = "Вовки для лігва",
        description = "Місія у Вовчому лігві в затоці Тірагарде завершилася успіхом. Молодець, {name}.\n\nТепер зграя люто вовків патрулює околиці форпосту.\n\nВирушай до Вовчого лігва й перевір, чи навчання вовків відповідає нашим стандартам.",
    },
    [53153] = {
        title = "Смерть Осквернителям",
        description = "Навіть після руйнування Андерсіті Осквернителі й далі змагаються з нами за владу над узгір'ями Араті.\n\nФермерські землі Ґо'Шека знову належатимуть Альянсу. Іди й розбий Відступників.",
    },
    [53154] = {
        title = "Ліга програє",
        description = "Навіть після падіння Стромґарда Ліга Араторі продовжує діяти на нагір'ї.\n\nПівнічні угіддя належатимуть Орді. Іди й розбий цих людей.",
    },
    [53155] = {
        title = "Карбована монета",
        description = "<Ця стара, потерта монета вочевидь побувала в багатьох руках. Краї поіржавіли за роки на солоному повітрі Великого моря, а сама вона має незвичне карбування.\n\nТи бачив чимало таких монет, розкиданих по всьому острову, — здається, ними тут користуються досить часто.>",
    },
    [53160] = {
        title = "Стародавній ключ від крипти",
        description = "<Магічний пристрій, знайдений у моґу, що вдерлися на острів; сили в ньому вже не лишилося.\n\nТи знаєш про схожі пристрої, якими активували стародавні машини титанів у сховищах моґу в Пандарії.\n\nСаме цей аж пашить лиховісною присутністю.\n\nМожливо, Мандрівники Історіями знають про нього більше.>",
    },
    [53161] = {
        title = "Перстень рифів",
        description = "<Легкий серпанок звивається й клубочиться навколо цього персня, наче пестить його.\n\nКоли ти тримаєш цю річ, глибоко в душі стає тривожно. Здається, ніби невидимі крижані руки з краю мертвих тягнуть тебе до себе.\n\nУ цьому годі помилитися — це сила Гельї.\n\nВаларджари захочуть про це почути.>",
    },
    [53162] = {
        title = "Гріхи Синдикату",
        description = "Наче Осквернителів було замало, з гір Альтерака досі сповзають агенти Синдикату, щоб виганяти чесних фермерів Альянсу.\n\nПокарай їх.",
    },
    [53163] = {
        title = "Ріг для пиття Кривавої Гущі",
        description = "<Великий ріг для пиття, відібраний в одного з вриколів Кривавої Гущі.\n\nМіцна робота дала йому пережити багато років важких мандрів Великим морем.\n\nТримаючи ріг, ти пригадуєш, як завзято ті вриколи, яких ти зустрі$p(в:ла), рвалися до азериту, — але задля чого?\n\nІнші племена вриколів можуть знати більше про Криваву Гущу та її наміри.>",
    },
    [53164] = {
        title = "Звуковий камінь",
        description = "<Камінь вібрує від твого дотику. Частота відлунює по всьому тілу, і ти почуваєшся посвіжілим.\n\nМабуть, мантиди використовують ці камені, щоб долати великі відстані над морем.\n\nДивно було бачити їх на острові: мантиди зазнали тяжкого удару, коли загинула Шек'зір, — тепер вони не мали б роїтися.\n\nМешканці Пандарії можуть знати більше.>",
    },
    [53165] = {
        title = "Спинити крадіжку старожитностей",
    },
    [53167] = {
        title = "Хутряний плащ Льодоіклів",
        description = "<Хутро на цьому плащі витерте й подерте, але досі гріє. Воно пережило багато років у суворих, нещадних завірюхах півночі.\n\nПлемені Льодоіклів досі не бачили в Азероті — можливо, хтось у Нортренді знає про них більше.>",
    },
    [53168] = {
        title = "Магічна підзорна труба",
        description = "<Ця підзорна труба дає змогу бачити далеко вдалину, але якщо дивитися в неї надто довго, починає боліти голова.\n\nСкло, схоже, виготовлене саме під чиїсь чужі очі.\n\nЗважаючи на тонке оздоблення труби, за її повернення, певно, дадуть чималу винагороду.>",
    },
    [53169] = {
        title = "Ядро елементаля",
        description = "<Вигоріле ядро від елементалів, яких ти зустрі$p(в:ла).\n\nКоли зосередишся, відчуваєш, що десь глибоко в ядрі ще лишилася елементальна енергія.\n\nВони вочевидь полювали за азеритом, але навіщо?\n\nМожливо, настав час нагадати про давню послугу.>",
    },
    [53170] = {
        title = "Незаймана чорна луска",
        description = "<Бездоганно чиста луска чорного дракона, взята від драконів, яких ти нещодавно зустрів.\n\nЧорна зграя драконів був майже повністю винищений після загибелі Дезвінга й піднесення Вратіона до влади.\n\nА проте розмір вказує на молодшого дракона.\n\nЄ одна особа, один дракон, який, ти знаєш, захоче про це почути, — але ДЕ Вратіон?\n\nТи здогадуєшся, що він може бути в якомусь знайомому, укріпленому й покинутому місці.>",
    },
    [53171] = {
        title = "Пошарпана луска Сутінків",
        description = "<Потерта луска сутінкового дракона, що пережила багато років битв.\n\nВважалося, що сутінкових драконів здолали з падінням Сінестри, — як їх стільки опинилося на острові?\n\nІ хто веде цей рій?>",
    },
    [53172] = {
        title = "Бізнес-план Venture Co.",
        description = "<Величезний том, надрукований дуже дрібним шрифтом. Ти не встигаєш прочитати й кількох речень, як літери починають розпливатися перед очима.\n\nДовгостроковий план компанії Venture Co. видається доволі заплутаним і майже незбагненним.\n\nОдне ясно напевно: конкурентне підприємство, певно, добре заплатило б, щоб заволодіти цим томом.>",
    },
    [53173] = {
        title = "Гріхи Синдикату",
        description = "Наче Ліги Араторі було замало, агенти Синдикату досі сповзають із гір Альтерака, щоб виганяти чесних робітників Орди.\n\nПокарай їх.",
    },
    [53174] = {
        title = "Око мурлока",
        description = "<Око мурлока, схоже, не має жодних магічних властивостей, але все ще доволі вологе на дотик.\n\nТи бачив, як чаклуни нага використовують подібні предмети у своїх ритуалах, але вони рідко калічать своїх рабів-мурлоків заради цього.\n\nЦе бентежить, навіть як для нага.>",
    },
    [53175] = {
        title = "Насувається фронт війни",
        description = "Ми не можемо короткозоро зосередити всі сили лише на Зандаларі. Підступність Орди жевріє по всьому світу.\n\nОдне особливо гаряче місце — у Нагір'ї Араторі, біля легендарної цитаделі Стромґард. Орда влаштувала поблизу табір і прагне захопити нашу територію.\n\nПоговори з Ралстоном Карном, офіцером із вербування дивізії, що відповідає за цей фронт. Йому згодиться гарний {class}, як-от ти.",
    },
    [53176] = {
        title = "Мерехтливий скарабей",
        description = "<Магічна дрібничка, знайдена в заклинача тол'вірів. Схоже, вона підсилює його здатність творити закляття.\n\nВона видається дуже давньою, але майже бездоганно збереглася.\n\nТол'віри Ульдуму, можливо, знають більше про раптову появу Аматет.>",
    },
    [53177] = {
        title = "Зламаний компас",
        description = "<Компас, знайдений у викинутого на берег пірата, більше не працює.\n\nМетал і робота вказують на те, що його зроблено в Стормвінді.>",
    },
    [53178] = {
        title = "Мисливський спис Кинджалоплавців",
        description = "<Цей спис гострий як бритва, хоча й видно, що він прослужив на полюванні у відкритому морі багато років.\n\nДревко ламалося в кількох місцях, і його лагодили тим, що було під рукою. З розмаїття матеріалів для ремонту ти робиш висновок, що плем'я джінью, з яким ти нещодавно зіткнувся, мабуть, багато мандрує.\n\nДоброзичливі джінью Пандарії можуть знати більше про це дивне плем'я.>",
    },
    [53179] = {
        title = "Вигнання духів",
        description = "Навіть по смерті Орда нерозумно чіпляється за територію Альянсу.\n\nВижени їхніх мстивих привидів із руїн Ар'ґорока, доки їхня скверна не поширилася.",
    },
    [53180] = {
        title = "Панцир Воруз'арака",
        description = "<Панцир нерубіанського володаря Воруз'арака. Він видається стародавнім.\n\nСхоже, Воруз'арак не хотів скидати свій панцир і натомість дуже довго носив той самий укритий шрамами панцир.\n\nПо всьому панцирі вирізьблено дивні позначки. Схоже, це якась мова.>",
    },
    [53181] = {
        title = "Друїдське хутро",
        description = "<Це хутро аж кипить природною магією. Звірі, з якими ти би$p(вся:лася) на острові, насправді були зовсім не звірями, а друїдами.\n\nПринаймні були ними раніше.\n\nЩо могло перетворити їх на здичавілих?\n\nТи не хотів убивати їх, але вони не лишили тобі вибору, чи не так?>",
    },
    [53182] = {
        title = "Душильний корінь",
        description = "<Корінь звивається й борсається у твоїй руці, намагаючись обвитися навколо твого передпліччя.\n\nЗберігачі, яких ти зустрі$p(в:ла), мабуть, мають надзвичайно глибокий зв'язок із природою, якщо їхні творіння наділені такою довговічністю.\n\nЗгадка про лють, з якою вони билися проти тебе, раптом викликає тривогу.\n\nЧому ці охоронці природи поводилися так?\n\nХтось напевно має відповіді.>",
    },
    [53183] = {
        title = "Звивиста маса",
        description = "<Щупальце звивається й пульсує у твоїй руці, а твій розум атакують найрізноманітніші лихі думки.\n\nОдне видіння зокрема знову й знову зринає у твоїй свідомості.\n\nПеред внутрішнім зором ти бачиш багатооку козу, що лежить у калюжі чорної води. Коли ти наближаєшся, її очі різко розплющуються, і за мить ти вже дивишся на козу знизу, з глибини калюжі.\n\nТи занурюєшся в крижану темряву, і все довкола чорніє.\n\nТи ховаєш масу в кишеню й струшуєш ці думки з голови.>",
    },
    [53184] = {
        title = "Вицвілий листок",
        description = "<Цей листок схожий на масово надрукований рекламний папірець, що пропонує послугу зі скуповування азериту.\n\nТи можеш розібрати кілька бляклих, але барвистих фраз на кшталт «Твоє багатство чекає у Великому морі!» та «Усі багатіють, чи не настав твій час?»\n\nПро жодні пов'язані з цим небезпеки не згадано.\n\nЗате внизу є трохи інформації про те, до кого звертатися.>",
    },
    [53185] = {
        title = "Внесок на воєнний фронт",
        description = "Добре навчена армія сама собою далеко нас не заведе, {name}. Нам потрібні також гроші, харчі й припаси, щоб армія була забезпечена, нагодована й готова до бою.\n\nСкарбниця Альянсу фінансує більшу частину воєнних зусиль, але решту оплачує тяжка праця таких громадян, як ти і я. Розв'яжи гаманець і зроби, що можеш. За Альянс!",
    },
    [53186] = {
        title = "Звіт про місію: засідка біля Урвища Грімватта",
        description = "Твої прибічники надіслали звіт про місію біля Урвища Грімватта.\n\nУ ньому йдеться, що місія завершилася успіхом, а кровотролі, які нападали, були переможені.\n\nДостав звіт верховному командувачу Вірмбейну на борту «Спокути Вітру».",
    },
    [53187] = {
        title = "Несподіваний гість",
        description = "Місія із захисту Урвища Грімватта завершилася успіхом. Молодець, {name}.\n\nТроє з Урвища Грімватта не лише втримали заставу, а й захопили кровокрога. Ноелла Девенпорт відповідає за приборкання звіра.\n\nВирушай до Урвища Грімватта в Назмірі й розпитай Ноеллу про приборкання крога.",
    },
    [53188] = {
        title = "Морозний фристайл",
    },
    [53189] = {
        title = "Слизькі схили",
    },
    [53190] = {
        title = "Вигнання духів",
        description = "Навіть по смерті Альянс безглуздо чіпляється за територію Орди.\n\nВижени їхніх мстивих привидів із руїн Стромґарда, поки їхня скверна не поширилася.",
    },
    [53192] = {
        title = "Двічі вигнані",
        description = "По всьому нагір'ї елементалі всіх ґатунків розривають свої пута.\n\nПовернь їх до первісного хаосу, з якого вони прийшли.",
    },
    [53193] = {
        title = "Двічі вигнані",
        description = "По всьому нагір'ї елементалі всіх ґатунків розривають свої пута.\n\nПовернь їх до первісного хаосу, з якого вони прийшли.",
    },
    [53194] = {
        title = "На фронт",
        description = "Мені потрібно, щоб ти подба$p(в:ла) про Аратійське нагір'я. Битва наразі вщухла, але коли вона спалахне знову, ти будеш нам потрібен на фронті.\n\nІвера Світанкокрила тримає портал просто до Стромґарда. Вона тобі допоможе.",
    },
    [53196] = {
        title = "Видраїти оце!",
    },
    [53197] = {
        title = "Огляд фронту",
        description = "Орда вже якийсь час не нападає. Та й ми, чесно кажучи, теж. Зараз має бути досить безпечно, щоб вирушити в розвідку.\n\nЗазирни до наших наглядачів на копальні та на лісопилці. Добре було б знати, що вони не накивали п'ятами й не наразилися на смерть, а заразом дорогою ти трохи познайомишся з місцевістю.\n\nДо речі, можеш також поговорити з Ґрейсоном Беллом, розпорядником польотів, — він дасть тобі швидкий огляд ворожої бази. «Ар'ґорок» чи якась інша орчача нісенітниця.",
    },
    [53198] = {
        title = "Назад до Боралуса",
        description = "Що ж, на цьому поки що, мабуть, усе. Ми зв'яжемося з тобою, якщо бої знову розгоряться. Безсумнівно, це станеться з дня на день.",
    },
    [53199] = {
        title = "Торканата",
    },
    [53200] = {
        title = "Завдання відстеження",
    },
    [53201] = {
        title = "Завдання відстеження",
    },
    [53202] = {
        title = "Завдання відстеження",
    },
    [53203] = {
        title = "Завдання відстеження",
    },
    [53204] = {
        title = "Завдання відстеження",
    },
    [53207] = {
        title = "Насувається фронт війни",
        description = "Наша увага має сягати далі за Кул-Тірас. Альянс і досі тисне на наші сили в інших куточках світу.\n\nНайбільше нас цікавить Аратійське нагір'я, поблизу Стромґарда. Ми розбили в тих краях табір, маючи намір захопити Стромґард.\n\nПоговори з Троком, вербувальником загону, відповідального за цей воєнний фронт. Йому згодиться добрий {class}, як ти.",
    },
    [53208] = {
        title = "На фронт",
        description = "Ми ведемо війну на Аратійському нагір'ї. Битва наразі вщухла, але коли вона спалахне знову, ти будеш нам потрібен на фронті.\n\nДруза Нетерфанг тримає портал просто до Ар'ґорока. Вона тобі допоможе.",
    },
    [53209] = {
        title = "Внесок на воєнний фронт",
        description = "Добре вишколена армія — це лише півсправи, {name}. Нам також потрібні гроші, харчі та припаси, щоб армія була забезпечена, нагодована й готова до бою.\n\nПокажи свою гордість і дай, що можеш. За Орду!",
    },
    [53210] = {
        title = "Огляд фронту",
        description = "Альянс уже певний час не нападає. Та й ми, чесно кажучи, теж. Тепер має бути досить безпечно, щоб вирушити в розвідку.\n\nНавідайся до наших наглядачів на копальні та лісопилці. Добре було б знати, що вони не дали себе вбити, та й сама поїздка дасть тобі трохи роздивитися околиці.\n\nДо речі, можеш також поговорити з льотоінженером Краззлом. Він покаже тобі Стромґард з висоти, щоб ти бачи$p(в:ла), з чим ми маємо справу.",
    },
    [53212] = {
        title = "Назад до Зулдазару",
        description = "Що ж, наразі цього має вистачити. Ми зв'яжемося з тобою, якщо бої знову розгоряться. Чесно кажучи, це може статися будь-якого дня.",
    },
    [53214] = {
        title = "Завдання відстеження",
    },
    [53215] = {
        title = "Завдання відстеження",
