    [53221] = {
        title = "Звіт про місію: зниклі припаси",
        description = "Твої прибічники надіслали звіт щодо місії в Гнізді Стерв'ятників.\n\nУ ньому йдеться, що місія завершилася успіхом, а втрачену партію припасів вдалося повернути.\n\nДостав звіт верховному командувачу Вірмбейну на борту «Спокути Вітру».",
    },
    [53222] = {
        title = "Необхідні припаси",
        description = "Місія з повернення припасів завершилася успіхом. Молодець, {name}.\n\nЦю партію припасів замовив Базз Кранкчаґ у Гнізді Стерв'ятників. Тобі варто навідатися до застави у Вол'дуні й переконатися, що всі зниклі припаси на місці.\n\nВирушай до Гнізда Стерв'ятників у Вол'дуні й поговори з Баззом Кранкчаґом.",
    },
    [53266] = {
        title = "Буйні морські стебла",
    },
    [53267] = {
        title = "Звіт про місію: дослідження динозаврів",
        description = "Твої прибічники надіслали звіт щодо місії в Зеленій Лощині.\n\nУ ньому йдеться, що місія завершилася успіхом, а різноманітні зразки динозаврів вдалося здобути.\n\nДостав звіт верховному командувачу Вірмбейну на борту «Спокути Вітру».",
    },
    [53268] = {
        title = "Дослідження динозаврів",
        description = "Місія зі збору зразків для дослідження завершилася успіхом. Молодець, {name}.\n\nТобі варто навідатися до командира застави й оглянути зразки власноруч.\n\nВирушай до Зеленої Лощини в Зулдазарі й поговори з Арґрімом Каменеглибом.",
    },
