    [55319] = {
        title = "Тонк Жахливий",
        description = "<Цей ТК виглядає так, ніби з нього вийшов би добрий гонщик на Шаленому Перегоні.\n\nОстаннє слово щодо того, що дозволено, за Крашем Вілером на гоночній трасі Шаленого Перегону.>",
    },
    [55339] = {
        title = "Наводимо лад",
        description = "Іонізовані гольяни — справжнє лихо цих вод. Вони обдирають морське дно від будь-якої їжі, через що іншим видам важко вижити.\n\nЦя риба мало на що годиться, хіба що править за поживу для більших риб. Я хочу побачити цих більших риб, тож маю план, як очистити води від гольянів і виманити велику рибу з її схованки.\n\nПочнімо з того, що мій рибосмок наловить мені іонізованих гольянів.",
        objectives = "Злови 200 Іонізованих Мальків.",
        progress = "Наловив риби?",
        completion = "З цими мальками ми зможемо збудувати пастку.",
    },
    [55340] = {
        title = "Каліграфія",
