    [56955] = {
        title = "Бунтівники на дорозі",
        description = "Це неприпустимо. Каменероджені бунтівники влаштували засідку на обоз, що прямував до Десятинного владаря. Він — тутешній Жнець, що править цим округом.\n\nНам треба прорватися крізь цей безлад. Міст на дальньому боці цієї сутички веде до Темної Гавані. Господар зазвичай тримає там частину своїх сил Кам'яного легіону.\n\nПрокладай нам шлях, Ходоче Пащі. Знищуй кожного, хто нас затримає. Ми не повинні змушувати сіра Денатрія чекати.",
        objectives = "Убий 5 Каменероджених Бунтівників.",
        completion = "Твої бойові таланти подають надії. Може, ще кілька століть і трохи смирення — і з тебе щось вийде.",
    },
    [56969] = {
        title = "Кора стародавнього рифоходу",
        description = "Так? Що таке?",
