    },
    [58080] = {
        title = "Послуга: Блискуче намисто примули",
        description = "Цей предмет неабияк зацікавить посередників.\n\nЗа твоєю попередньою угодою з Нічним Ринком, тобі слід віднести його просто до Та'ксери.\n\nТебе щедро винагородять.",
    },
    [58081] = {
        title = "Послуга: Любов і жах",
        description = "Цей предмет неабияк зацікавить посередників.\n\nЗа твоєю попередньою угодою з Нічним Ринком, тобі слід віднести його просто до Та'ксери.\n\nТебе щедро винагородять.",
    },
    [58084] = {
        title = "Пастки для душ",
