    [60727] = {
        title = "Послання з Крижаної Корони",
        description = "Наші війська в Нортренді надіслали звістку. Юстиціарка Трусерце просить негайної допомоги.\n\nМи мусимо відгукнутися на цей заклик невідкладно, хоч би які жахи чекали на нас у Крижаній Короні.\n\n{class:v}, як ти, чимало додасть нам шансів на полі бою.\n\nДаю тобі слово, що за твоєї відсутності Оґриммар буде під захистом.\n\nБитва кличе, {name}. Сподіваюся, ти готов$p(ий:а).",
        objectives = "Доповіси юстиціарці Маріель Трусерце на турнірному майданчику в Крижаній Короні.",
        completion = "Ти прибуваєш саме вчасно. Командир Трогг дуже добре про тебе відгукувався.",
    },
    [60732] = {
        title = "Перервати потік",
        description = "<Змучене втілення душі перед тобою палає магматичним вогнем. Хоч би для чого воно тут, у казані, призначалося, цю мету вже виконано.\n\nЦілковита зневага до решток цієї душі бентежить. Якщо нічого не вдіяти, ці діяння триватимуть.\n\nНадішли мешканцям Казана Зоваала послання.>",
        objectives = "Зірви зусилля Пащеприсяжних у Казані Зоваала.",
        completion = "Радій зі свого звершення, але не забувай про вагу своїх учинків.\n\nВін завжди спостерігає.",
    },
    [60733] = {
        title = "Попереду, в самому центрі",
        description = "Руни на тому клинку... вони такі самі, як ті, що викарбувані на дверях до Престолу Примуса. \n\nІ одна з них щойно засяяла...\n\nЦе те, що я думаю, {name}? Чи маєш ти спосіб відпечатати Престол? \n\nЯкщо так, то, можливо, ризик Вираза був недаремним. Це могло б змінити хід усієї війни!",
        objectives = "Наснаж руну Могутності біля Престолу Примуса.",
        completion = "Кров'ю й громом ми розчавимо наших ворогів.",
    },
    [60735] = {
        title = "Біда в раю",
        description = "Я добряче поміркував над твоєю присутністю тут, {name}.\n\nМені очевидно, що ти не звичайний прибулець з Орибоса. Я не знаю, чому ти тут і чого прагнеш досягти. Уже саме це — небачена річ.\n\nТи мусиш зрозуміти... до Бастіону не приходять просто за примхою. Цю долю треба заслужити, і ті, кого для неї обирають, винятково пасують до такого існування.\n\nОтож... я питаю тебе... чому ти тут насправді?",
        objectives = "Дай відповідь на запитання Клеї.",
        progress = "<Калістена дивиться на тебе згори вниз.>\n\nЩо таке, смертна душе?",
        completion = "<Калістена дивиться на тебе згори вниз.>\n\nМи почули тебе, смертна душе.",
    },
    [60736] = {
        title = "Завдання 02",
        objectives = "Відчини двері до Престолу Примуса.",
