    [60916] = {
        title = "Відповідь на запрошення: Камінноголовий",
        description = "Привіт, найкращ$p(ий:а) $p(друже:подруго)!\n\nМені не йти на свято.\n\n<Камінноголовий завзято хитає головою.>\n\nТреба лишитися на роботу!",
        objectives = "Підроби документ, що дасть Камінноголовому дозвіл покинути свій пост заради Двору Жарин.",
        progress = "Привіт, найкращ$p(ий:а) $p(друже:подруго)!",
