    [60972] = {
        title = "Полювання на барона",
        description = "<Амулет, який дав тобі Болвар, спалахує слабким червоним сяйвом, а тоді тьмяніє.\n\nЩоб він став у пригоді в пошуках Даріона Мограйна, тобі треба знайти спосіб відновити його силу.\n\nТи пригадуєш місцину під назвою Казан Зоваала, що аж кишіла темною магією.\n\nМабуть, саме там можна відновити силу амулета.>",
        objectives = "Заряди Амулет Вершників.",
        completion = "<Амулет спалахує червоним.>",
    },
    [60973] = {
        title = "Креслення: Фіал спокою",
        description = "<Ти знайшов креслення фіала, який може дати твоїм душевним побратимам перевагу на Шляху Сходження.\n\nДактиліс має допомогти тобі виготовити цей предмет спорядження.>",
        objectives = "Віднеси Креслення: Фіал спокою Дактилісу.",
        completion = "Бачу, тобі вдалося роздобути нове креслення. Радо допоможу тобі у виготовленні.",
    },
    [60974] = {
        title = "Фіал спокою",
        description = "<Твій друг-управитель дав тобі ще одну пляшечку, щоб зберігати в ній це зілля.\n\nЦе допоможе твоїм душевним побратимам триматися в бою на Шляху Сходження, як це робить твій фіал.>",
        objectives = "Віднеси Фіал спокою до Паолоне.",
        completion = "Фіал? Дуже гарний! Точнісінько як у друга! Я потримаю на збереження.",
    },
    [60975] = {
        title = "Креслення: Духокована егіда",
        description = "<Ти знайшов креслення щита, який може дати твоїм душевним побратимам перевагу на Шляху Сходження.\n\nДактиліс має допомогти тобі виготовити цей предмет спорядження.>",
