    [61135] = {
        title = "Серце герба",
        description = "З цим найбільшим даром Арденвельду ми отримали останню частину, щоб відновити Герб Піднесення.\n\nПодбаймо, щоб жертва Вербоцвіт не була марною.",
        objectives = "Установи Посудину Арденвельду на Гербі Піднесення.",
        progress = "<Здається, посудину так і тягне до цього місця.>",
        completion = "<Есенція Вербоцвіт просякне герб і довершить його — і Бастіон знову зможе висвячувати нових Піднесених.>",
    },
    [61136] = {
        title = "Аґонікс",
