    [61156] = {
        title = "Там, де є пера...",
        description = "У давні часи претенденти вправлялися в бою проти звірини Бастіону. Зі створенням центуріонів така безладна підготовка стала непотрібною.\n\nБагато крилатих мешканців цього краю славляться своїм пір'ям. Воно легке й міцне - саме те, що нам треба.\n\nЗбери все, що зможеш, будь ласка. Згодиться будь-яке крилате створіння.",
        objectives = "Збери 30 Мерехтокрилих пер із летючих звірів.",
        progress = "Пера в тебе?",
        completion = "Отримано прийнятну частку. Прийми мою подяку.",
    },
    [61157] = {
        title = "Просто в лоб",
        description = "Рогаті звірі Бастіону колись часто слугували для тренування претендентів, але тепер їх здебільшого замінили бойові підрозділи центуріонів. За останні кілька еонів їхнє поголів'я розрослося, і його час проріджувати.\n\nЇхні роги — найважливіша складова нашої роботи. Багато зразків поламані в боях — такі не годяться. Збирай їх обережно.\n\nКинь їм виклик, здолай їх і принеси їхні роги.",
        objectives = "Збери 12 Елізійських рогів із рогатих звірів.",
        progress = "Нам потрібно стільки рогів, скільки ти зможеш роздобути.",
        completion = "Прийнятний рівень якості та кількості. Дякую.",
    },
    [61159] = {
        title = "Знаки загибелі",
        description = "Усі зреченці завжди носять при собі особливий знак. Підозрюємо, що ці знаки наповнені силою Храму Вірності, яка зміцнює їх у боротьбі проти нас.\n\nЗбери ці знаки з їхніх загиблих тіл. Позбав їх цієї сили, а ми обернемо її на користь наших задумів.\n\nТака воля Архонта, як і наша.",
        objectives = "Збери 20 Знаків зреченців із зреченців-кіріанів.",
        progress = "Кожен знак — це зміщення сили на нашу користь.",
        completion = "Вони стануть у великій пригоді. Чудова робота.",
