    [61166] = {
        title = "Зменшуй, використовуй повторно, переробляй",
        description = "Центуріонам потрібно багато деталей. Але й нам теж!\n\nКофі потрібен їхній метал. Хоч із центуріонів, хоч із землі. Тобі вирішувати!\n\nНе надто пошкоджений, гаразд? Важко чистити!",
        objectives = "Збери 20 Резонансного сплаву із зреченців-центуріонів або деталей центуріонів.",
        progress = "Маєш метал?",
        completion = "Оце ВАЖКИЙ метал! Як улюблена музика Кофі!",
    },
    [61171] = {
        title = "Непорушні узи",
        description = "Друсти заплатять за це мерзенне прокляття, яке вони наслали на нас.\n\nМи втратили забагато союзників... забагато друзів, щоб тепер здаватися. Хай ми не можемо врятувати тих, хто впав у полон одержимості, та можемо покласти край їхнім мукам. Я накажу мисливцям добивати всіх одержимих, яких вони зустрінуть.\n\nБудь ласка, віднеси цей звіт Королеві Зими. Вона має дізнатися про те, що ми з'ясували.\n\nДякую за службу, {name}. Ти справжній друг і захисник Арденвельду.",
        objectives = "Віднеси звіт лорда Герна Королеві Зими.",
        progress = "Які вісті ти несеш?",
        completion = "Якщо тернослівники не знають способу зняти прокляття, то, можливо, для одержимих і справді немає надії. Це вкрай лихі вісті.",
    },
    [61173] = {
        title = "Відповідь: Міканікос",
        description = "Двір Жарин звучить цікаво... але зараз дуже багато роботи! Зреченці залізли в мої запаси. Тепер усе переплутане й безладне. Не можу працювати в таких умовах. У майстерні все не так!\n\nДопоможи мені! Дістань деталі. Більшість будуть пошкоджені, а ти ж не вмієш розпізнавати вади. Принеси мені багато на огляд. Я знайду ідеальну деталь.",
        objectives = "Допоможи Міканікосу, зібравши потенційно ідеальні деталі, щоб він завершив свій конструкт і відвідав Двір Жарин.",
        progress = "Маєш мої деталі?",
        completion = "Ось ідеальна! Бачиш? Решта погані для моєї конструкції. Забирай собі.",
