    [61252] = {
        title = "Попросити про послугу",
        description = "Ми вчинимо саме так, як наказує моя баронеса. Прикличмо стерничого перед собою... хай як це її засмутить.\n\nАктивуй маяк і готуйся до бою. Лічі вважають усі Очі своїми ворогами, і я певен, твоя репутація серед них тобі точно не на користь.",
        objectives = "Приклич стерну Каліру та здолай її.",
        completion = "Довіра моєї баронеси до тебе цілком виправдана.",
    },
    [61255] = {
        title = "Відповідь: Александрос Морґрейн",
        description = "Для мене буде честю представляти Малдраксус при Дворі Жарин принца Ренатала.\n\nАле перш ніж покинути свій пост, я маю переконатися, що мої побратими будуть у безпеці за моєї відсутності.\n\nПробийся до Ливарні Осеїну й забери зброю в наших суперників там.\n\nЯ розподілю її поміж військом, поки готуватимуся до від'їзду.",
        objectives = "Збери 9 Осеїнових посохів і 3 Осеїнові бойові сокири в Ливарні Осеїну.",
        progress = "Ти вже здобу$p(в:ла) зброю?",
        completion = "Вагома перевага. Ми здобуваємо додаткову зброю й водночас позбавляємо її наших ворогів.",
    },
    [61256] = {
        title = "Відповідь: Клея і Пелагос",
        description = "О, як чудово! Дякую за запрошення до Двору Жарин.\n\nМи якраз збиралися очиститися медитацією. Це буде ще потрібніше, якщо незабаром вирушаємо в дорогу. Хочеш приєднатися до нас?",
        objectives = "Приєднайся до Клеї та Пелагоса в кімнаті Медитації й постань перед спогадами свого минулого.",
        progress = "Ти вже заверши$p(в:ла) свою медитацію?",
        completion = "Медитація завжди так заспокоює і збагачує, правда ж? Тепер ми краще готові до подорожі!",
    },
