    [61371] = {
        title = "Атанос",
        description = "Для останнього випробування на Шляху ти маєш зустрітися зі старим другом із перших своїх миттєвостей у цьому царстві — Атаносом.\n\nМинули тисячоліття, відколи цей могутній голіаф востаннє ступав на арену зі своїм легендарним списом, Вартою Смирення. Коли він пішов, зброю розібрали, як велить традиція.\n\nЯкщо Атанос знову побачить Варту Смирення, гадаю, його можна буде переконати повернутися на арену. Розбитий спис у нас є, але потрібні матеріали, щоб його перекувати.",
        progress = "Для останнього випробування на Шляху ти маєш зустрітися зі старим другом із перших своїх миттєвостей у цьому царстві — Атаносом.\n\nМинули тисячоліття, відколи цей могутній голіаф востаннє ступав на арену зі своїм легендарним списом, Вартою Смирення. Коли він пішов, зброю розібрали, як велить традиція.\n\nЯкщо Атанос знову побачить Варту Смирення, гадаю, його можна буде переконати повернутися на арену. Розбитий спис у нас є, але потрібні матеріали, щоб його перекувати.\nВарта Смирення (1)\nДзеркало Душ (1)",
        completion = "Нехай нарешті настане повернення Атаноса.",
    },
    [61372] = {
        title = "Назад до нього",
        description = "Навіть із Вартою Смирення в руках, якщо ти хочеш переконати Атаноса знову стати на Шлях Сходження, ти мусиш довести, що ти гідний супротивник.\n\nВийди на арену й оберни спис проти нього. Навіть із його силою тобі годі сподіватися перемогти його, та спис має зуміти відбити його могутнє тупання.\n\nВідбивай його напади достатньо довго, і він неодмінно дозволить тобі захопити його пам'ять.",
        completion = "<На обличчі Дактиліса проступає щось схоже на подив.>\n\nТобі справді вдалося? Дуже добре! Воістину гідний супротивник.",
    },
    [61373] = {
        title = "Азаруукс, Згубник Царства",
        description = "Ти мусиш діяти негайно!\n\nПожирач неймовірної сили відкрив розлом у колізеї й уже зараз погрожує поглинути його! Ті кілька бійців, що були тут у цю мить, ледве стримують істоту.\n\nЯкщо цей жах не спинити, він рушить далі, до решти шпилів. Збери стільки аніми, скільки зможеш у цій місцині, і приборкай його.\n\nЩойно загрозу буде усунуто, візьми це запасне дзеркало й захопи його пам'ять, щоб ми могли більше дізнатися про його рід для майбутніх зустрічей.",
        objectives = "Поглинай аніму, щоб активувати злиття аніми й приборкати Азаруукса, а тоді захопи його спогад.",
        progress = "Не можна зволікати!",
        completion = "Героїчне звершення! Битви з його родом багато чого нас навчать.",
    },
    [61388] = {
        title = "Спільна подорож",
        description = "Поєднання душ — лише перший крок.\n\nЗ часом сила нашого зв'язку зростатиме й проявлятиметься у вигляді дивовижних нових здібностей!\n\nЩоб скористатися цією новопосталою силою, тобі досить покласти руку на Кузню Зв'язків. Жодної ціни платити не треба — єдине обмеження це твій зв'язок із Некролордами.",
        objectives = "Активуй силу зв'язку душ за допомогою Кузні Зв'язків.",
        progress = "Цей пристрій — лише провідник до сили, що криється в нас обох.",
        completion = "Нехай ми виявимося гідними союзниками в прийдешніх битвах.",
