    [61872] = {
        title = "До нагальних справ",
        description = "Ти добре тут попрацював, чемпіоне. МАТИ і я поміркуємо, що робити далі.\n\nТобі краще повернутися до нагальних справ і зробити все, що зможеш, аби посилити те своє намисто.\n\nУ мене є способи зв'язатися з тобою, щойно ми з МАТІР'Ю тут усе налагодимо.",
        objectives = "Повернися до Голфорда Вірмбейна на «Спокуті Вітру» в Боралусі.",
        completion = "{NAME}, як добре знову тебе бачити. Роботи тут не бракує.",
    },
    [61874] = {
        title = "Shadowlands: Холодний виклик",
        description = "Час настав, {class:v}.\n\nВеликий лорд Болвар Фордрагон просить тебе з'явитися на вершині цитаделі Крижаної Корони. Зустрінь мене в Оґриммарі, і я відведу тебе до нього.\n\nЯ не змушував би його чекати.",
        objectives = "Зустрінься з Даріоном Моґрейном біля Фортеці Ґроммаш в Оґриммарі.",
    },
    [61875] = {
        title = "По росу",
        description = "Будякокрапля — дивовижне створіння. Її коріння сягає глибоко в землю, де п'є найдавніші води. Цими водами вона збирає саму есенцію землі в краплину роси, що дає нашим майстрам змогу кувати потужну зброю.\n\nДопоможи нам зібрати росу — і будеш щедро винагороджений.\n\nПоквапся, поки вона не випарувалася!",
        objectives = "Збери 30 роси Будякокраплі в лісах Арденвельду.",
        progress = "Роса швидко випаровується, тож поквапся!",
        completion = "Ця роса неабияк допоможе нашим майстрам!\n\nДякую тобі, малече.",
    },
    [61876] = {
        title = "Зберись із духом",
        description = "Коли Мограйн відвідав Бастіон, ми з ним довго говорили. Він припустив, що якщо нам вдасться вбити Гармала, його серце можна буде використати, щоб посилити Герб Піднесення.\n\nМаркграф володіє силою формувати плоть так, як мало кому під силу. Хоча його витвори жахливі, якби ми приборкали цю силу, наші Піднесені стали б могутнішими, ніж будь-коли.\n\nЦе не наш шлях, але, гадаю, наш шлях змінюється. Можливо, це крок на нашій новій дорозі.",
        objectives = "Здобудь Серце Формувача Плоті.",
        progress = "Це мусить бути зроблено.",
        completion = "Мені аж відлягло, що не мені нести цю штуку назад до Бастіону.",
    },
    [61877] = {
        title = "Повернення до Фортеці",
        description = "Доправмо серце до Елізійської Фортеці якомога швидше.\n\nУ Тінокраї багато тих, хто напав би на нас, щоб забрати його силу собі. Будь насторожі, Ходоче Пащі.\n\nСьогодні ми повертаємося до своїх із перемогою.",
        objectives = "Зустрінься з Ксандрією біля Герба Піднесення в Елізійській Твердині в Бастіоні.",
        completion = "Як добре знову бути серед своїх. Малдраксус мені не до смаку.",
    },
    [61878] = {
        title = "Герб величі",
        description = "Щойно будеш готовий, тобі лишиться тільки вкласти серце у сферу тут, на Гербі Піднесення.\n\nПраця Міканікоса забезпечить, що його енергія належно спрямується на допомогу нашим ритуалам піднесення, а його сила має захистити Герб від будь-яких подальших нападів.\n\nХай Дім Конструктів більше ніколи не ступить у наше царство.",
        objectives = "Вклади Серце Формувача Плоті в Герб Піднесення.",
        progress = "<Схоже, це і є та сфера, у яку Ксандрія веліла тобі вкласти серце.>",
        completion = "<Серце Плототворця легко лягає в сяйливу сферу. Щойно воно опиняється всередині, ти чуєш тихеньке клацання в Гербі — наче його було створено, щоб охоче приймати таку силу.\n\nТак починається нова доба кіріан.>",
    },
    [61879] = {
