    [62052] = {
        title = "Вигнана через параною",
        description = "Лихи Дому Ритуалів відіграли вирішальну роль у нападі мальдраксійців на Бастіон. Зараз вони нам не союзники, тож було б важко переконати когось із них дозволити нам зберегти його спогад для наших навчальних цілей.\n\nМи зв'язалися з некроманткою, яка має давні порахунки з однією з ліхів. Знайди її, і вона допоможе тобі захопити цей спогад.",
        objectives = "Знайди Каракси Перебіжчицю на Променаді Претендента в Малдраксусі.",
        progress = "<Караксі дуже уважно гортає книгу.>",
        completion = "Мій задум справді втілюється в життя. Чужинець — і прийшов допомогти мені звершити помсту!",
    },
    [62053] = {
        title = "Некромантська сила",
        description = "Моя стара наставниця, Тран'тіок, — це втілення параної. Вона вірить, що всі її зрадять, і через це я була вигнана не лише з її служби, а й з усього Дому Ритуалів.\n\nЯ не мала наміру виступати проти неї... та це змінилося.\n\nВізьми кристалічну оболонку, яку ти змайструва$p(в:ла), і вбий моїх колишніх колег, щоб наповнити її некромантською енергією. Вона приведе тебе до філактерії Тран'тіок — саме того, що ми обоє шукаємо.",
        objectives = "Заряди Кристал-шукач душ, здолавши ворогів у Домі Ритуалів, тоді використай його, щоб знайти філактерію Тран'тіок.",
        progress = "Тран'тіок вважає мене загрозою...\n\nЯ покажу їй, що це слово означає насправді.",
        completion = "Часу в нас обмаль. Скоро Тран'тіок з'явиться власною персоною.",
