    [62216] = {
        title = "Програма підготовки",
        description = "Сержант Крашдж — непоганий інструктор, але цим новобранцям потрібне справжнє вишколення зі справжнім воїном. З тим, хто проливав кров на полі бою. З кимось на кшталт мене!\n\nІ я знаю саме той бій, який зробить із цих солдатів справжніх вояків.\n\nХодімо навчимо їх дечого.",
        objectives = "Убий Декадіуса.",
        progress = "Ну що, воно мертве?",
        completion = "З вас двох чудова команда. Добре мати надійних побратимів по зброї.",
    },
    [62217] = {
        title = "Польова підготовка",
        description = "Хоч і не нашою рукою, та Малдракс завдав великої кривди кіріанам Бастіону. Ми мусимо зробити все можливе, щоб усе виправити.\n\nЗагроза від Зреченців і досі є для них скалкою в боці. Звучить як чудова нагода і виявити нашу підтримку, і дати нашим новобранцям трохи бойового досвіду.",
        objectives = "Знищ 15 бійців Зреченців біля Вічної Кузні в Бастіоні.",
        completion = "Ви з Марзом добре спрацювалися. Він прийме удар на себе щоразу, коли буде треба.",
    },
    [62218] = {
        title = "Фонтан для фей",
        description = "Нуумінууру проводить дні, оберігаючи й пильнуючи багатьох фей по всьому Арденвельду. Вона висловила тривогу за деяких підопічних фей, яких давно не бачила.\n\nЗвернися до Нуумінууру й поглянь, чи зможеш допомогти їй знайти розгублених духів.",
        objectives = "Прибудь до Нуумінууру в Мерехтливій улоговині в Арденвельді.",
        progress = "Вітання тобі, вірна опоро душеносців.",
        completion = "Фонтан для фей задля рідкісного перепочинку... і справді спокуслива принада.",
    },
    [62219] = {
        title = "Примхливі забави",
        description = "Вічно ганяючись за своїми вигадками, мої подруги-феї рідко трапляються на очі.\n\nЇхня мінлива вдача часто збиває їх із пуття, ведучи стежками до розсіяності й смутку.\n\nВідшукай моїх подруг, наполягай, щоб вони повернулися до мого коріння, — і нагороду дістанеш і ти, і вони.",
        objectives = "Знайди Річкоцвіт, Місячний Вітер і Пурхокрилку та переконай їх повернутися до Нуумінууру.",
        progress = "Мої підопічні знають, що мають вертатися до мого коріння — плести оповіді про свої походеньки й міцнити дух.\n\nЩо довше вони пурхають десь далеко, то глибшають зморшки моєї тривоги.",
        completion = "Води твого світу відживляють моїх підопічних так, як не можуть води нашої домівки.\n\nІ ось вони знову вертаються на спочинок.",
    },
    [62221] = {
