    [62403] = {
        title = "Кабаняча смерть",
        description = "Кабани довкола Малдраксусу мають одну особливість. Їхні ікла вбирають рідину. Залежно від того, де побував звір, ці кістки можуть містити потужну суміш отрут чи інші алхімічні рідкості.\n\nЩоб розпізнати, з чого зроблена кістка, потрібне досвідчене око, тож просто принеси мені їх якомога більше. А вже я подивлюся, чи є серед них щось цінне.",
        objectives = "Збери 25 кривавих іклів з кабанів у Малдраксусі.",
        progress = "Пильнуй, щоб кістки не торкалися твоєї шкіри надто довго. Вони можуть викликати подразнення.",
        completion = "Добірна кількість. У цьому зібранні напевно знайдеться щось корисне.",
    },
    [62406] = {
        title = "Жезл Примуса",
        description = "Жезл Примуса. Остання частина регалій нашого володаря.\n\nНе приховуватиму гордості, яку відчуваю, відновлюючи цю залу. Ти маєш відчувати те саме почуття звершення.\n\nСтатуя чекає на тебе, {name}. Принеси славу цьому королівству.",
        objectives = "Установи Жезл Примуса на Статую Примуса.",
        completion = "Відчуваю силу. Силу — і полегкість.",
    },
    [62407] = {
        title = "Гербіцидні нахили",
        description = "Мій газ найпотужніший у всьому Малдраксусі, та я чув, як дехто каже, ніби він не найсильніший у Тінесвітті.\n\nВони стверджують, що в Арденвельді ростуть якісь рослини, цвіт яких куди їдкіший за мій газ. Дурниці!\n\nХодімо погляньмо на ці рослини. Якщо їхній сморід справді такий сильний, як кажуть, я, може, навіть зумію домішати його до власного газу!",
        objectives = "Допоможи Газовому Міху зібрати Пелюстки гнилоцвіту.",
        progress = "Ну як, весело рвати квіточки?",
        completion = "Як йому взагалі вдається смердіти ще гірше, ніж раніше?\n\nФу. Та принаймні результат він дає.",
    },
    [62411] = {
        title = "Завдання відстеження",
    },
    [62414] = {
        title = "Поховати підозри",
        description = "Нам не буде жодної користі з твого перевтілення на Нелесіс, якщо до Кел'Тузада дійде звістка, що її вбито.\n\nТи мусиш подбати, щоб ніхто з тих, хто бачив, як ти входиш до печери, не вижив.",
        objectives = "Убий 10 бійців лічеприсяжних біля Дому Ритуалів.",
        completion = "Нікого не лишилося, щоб зчинити тривогу? Добре.\n\nМожемо переходити до плану.",
    },
    [62417] = {
        title = "За межі!",
        description = "А, ти якраз вчасно. Я зробив неабияке відкриття.\n\nМені вдалося встановити зв'язок навіть далі, ніж будь-коли раніше.\n\nЯк я це зробив, питаєш? Тяжкою працею, ось як! Та ти й сам це знав. Ти працюєш майже так само завзято, як і я. Саме для цього ти тут!\n\nГотов$p(ий:а) до ще захопливішої пригоди?",
        objectives = "Дослідь невідому місцевість.",
        progress = "Я відчуваю легіт з того боку. Отже, це, мабуть, не під землею.",
        completion = "Нічого поганого в тому, щоб заробляти на життя збиранням квітів. Це добра, чесна праця.\n\nТа й надавати копняків тим клятим сприганам — справа теж варта. Гарна робота.",
    },
