    [62569] = {
        title = "Хватка Тюремника",
        description = "Зазирнувши в Пащу, Болвар привернув увагу Тюремника.\n\nЙого найгірші страхи справдилися.\n\nТи маєш допомогти мені розірвати зв'язок, {name}! Уламок Шолома — ось ключ!",
        objectives = "Допоможи Джайні Праудмур розірвати зв'язок Тюремника з Болваром.",
        completion = "Тюремник... зник... з моєї свідомості.\n\nДякую, {NAME}. Завдяки тобі я уник темнішої долі, ніж ти можеш собі уявити.\n\nЗа це я довіку буду тобі вдячний.",
    },
    [62584] = {
        title = "Постачання на передову",
        description = "Цей передовий табір сильно залежить від нашої лінії постачання з турнірного поля. Нещодавно один вантаж атакували дорогою через долину під нами.\n\nЗабери все, що зможеш, і, якщо вдасться, усунь загрозу, щоб таке більше не повторилося.",
        objectives = "Забери 6 Уцілілих товарів та вбий 3 Зблюваних вартових у Долині Полеглих Героїв.",
        progress = "Опинитися в крижаній пустці, у холоді й самоті... Сподіваюся лише, що наші союзники дали відсіч.\n\n<Хрестоносиця Ренн хитає головою.>\n\nЧи вдалося тобі врятувати хоч щось із вантажу?",
        completion = "Дякую за швидкі дії, {NAME}.\n\nЦих запасів має вистачити нам до наступного вантажу.\n\nЯ подбаю, щоб тіла наших полеглих було знайдено й віддано їм останню шану.",
    },
    [62587] = {
        title = "У пошуках внутрішнього спокою",
        description = "Мені завжди снилися сни.\n\nОсобливі сни, можна сказати.\n\nБудь-яке місце тиші чи спокою може явитися мені вві сні.\n\nНавіть ті, де поряд чигає небезпека, адже спокій можна знайти будь-де, якщо знаєш як.\n\nЗараз мені сниться твій світ, твій Азерот.\n\nЯ не можу мандрувати до твого царства. Допоможи мені доторкнутися до мого останнього сну твоїми очима.\n\nМені наснилося високе місце. Дуже високе місце. Чи знаєш ти його?",
        objectives = "Вирушай до Високогір'я в пошуках спокою.",
        completion = "Це був такий приємний сон. Я радий, що тобі випало пережити його наяву.",
    },
    [62588] = {
        title = "У пошуках внутрішнього спокою",
        description = "Ти повернувся.\n\nЦе мене тішить.\n\nБільше місць тиші явилося мені вві сні.\n\nЯ бачу піщаний пляж, заходи сонця.\n\nЯ не можу мандрувати до твого царства. Допоможи мені доторкнутися до мого останнього сну твоїми очима.",
        objectives = "Вирушай до Зулдазару, щоб помедитувати.",
        completion = "Це був такий приємний сон. Я радий, що тобі випало пережити його наяву.",
    },
    [62589] = {
        title = "У пошуках внутрішнього спокою",
        description = "Я радий, що ти бажаєш продовжити свої медитації.\n\nЦе допоможе тобі віднайти рівновагу.\n\nМені знову наснився сон. Теплий сон про холодне місце.\n\nВоно вкрите білим. Чи знаєш ти про нього?\n\nВирушай туди й побач на власні очі краєвид, який я бачив уві сні.",
        objectives = "Помедитуй у Вічнозим'ї.",
        completion = "Це був такий приємний сон. Я радий, що тобі випало пережити його наяву.",
    },
    [62590] = {
        title = "У пошуках внутрішнього спокою",
        description = "Дякую, що повернувся.\n\nМені наснився ще один сон. Ще одне видіння твого світу.\n\nУ цьому сні наді мною танцювало небо.\n\nНа краю урвища, у північному краю.\n\nЯке ж видовище.\n\nТи маєш пережити це сам.",
        objectives = "Помедитуй у Виючому Фіорді.",
        completion = "Це був такий приємний сон. Я радий, що тобі випало пережити його наяву.",
    },
    [62591] = {
        title = "У пошуках внутрішнього спокою",
        description = "Ми вже стільки пережили разом.\n\nЯ вдячний, що маю супутника в цій подорожі відкриттів.\n\nТи ступаєш там, де я можу лише з'явитися думкою.\n\nТи торкаєшся того, що я можу лише бачити.\n\nМені наснився ще один сон.\n\nЩе одне узбережжя. Статуя.\n\nВелика статуя маленької істоти.\n\nІди, відшукай той краєвид із мого сну.",
        objectives = "Помедитуй у Буті-Беї.",
        completion = "Це був такий приємний сон. Я радий, що тобі випало пережити його наяву.",
    },
    [62592] = {
        title = "Володар внутрішнього спокою",
        description = "Ти пройшов довгий шлях.\n\nТи майже готовий віднаходити внутрішній спокій будь-де.\n\nЛишилася ще одна подорож під моїм проводом.\n\nВона коротка. Спокій увесь цей час був тут, у цьому саду.\n\nЩе одне місце спокою, яке варто пережити.\n\nА тоді ти скинеш свої духовні кайдани.\n\nЯ пишатимуся тобою.",
        objectives = "Знайди нове місце для медитації в Оранжереї Королеви.",
        completion = "Це був такий приємний сон, я радий, що тобі випало пережити його наяву.",
    },
