    [62729] = {
        title = "Повернення до Орибоса",
        description = "Ти показав себе гідним союзником Бастіону, поки був тут, {name}. Хоч я й хотіла б, щоб ти лиши$p(вся:лася), є інші краї в Тіньокраї, які потребують допомоги дужче.\n\nПовертайся до Орибоса, щойно зможеш, і знайди Тал-Інару. Вона допоможе тобі вирішити, куди найкраще спрямувати свої зусилля далі.\n\nХай Архонт оберігає тебе.",
        objectives = "Поговори з Тал-Інарою в Орибосі.",
        completion = "Твоє призначення виконано. Чудова робота.",
    },
    [62730] = {
        title = "Плід богів",
        description = "Любиш солодкі плоди?\n\nПровости вирощують найсоковитіший пуріан. Це особливий плід! Знайдеш його в багатьох місцях Бастіону. Його використовують для всякого.\n\nЇж для поживи.\n\nДавай дзвонам заради благословень.\n\nДавай провостам заради скарбів.\n\nТи знайди, а я покажу тобі як!",
        objectives = "Принеси Еліосу 1 стиглий пуріан.",
        progress = "Знайшовся солодкий пуріан?",
        completion = "Так, цей дуже солодкий і стиглий. Треба скоріше використати, поки не зіпсувався!",
    },
    [62732] = {
        title = "Зосередження на Анклаві",
    },
    [62733] = {
        title = "Найсолодша данина",
        description = "Пуріан добре їсти, так, але краще давати.\n\nЗнайдеш замкнену срібну скриню біля статуї провоста. Поклади стиглий пуріан як данину.\n\nТоді отримаєш гарну несподіванку!\n\nСпробуєш?",
        objectives = "Поклади стиглий пуріан на тацю данини статуї провоста.",
        progress = "Пуріан уже віддано?",
        completion = "Сподіваюся, несподіванка припала до смаку! \n\nЗнайдеш ще срібні скрині — клади Стиглий Пуріан як данину!\n\nОго-го! Хочеш ключ від моєї Золотої Скрині? Спитай мене про Стюарда Дня!",
    },
    [62735] = {
        title = "Ворожі спогади",
