    [62865] = {
        title = "Повернути загублені душі",
        description = "Ходоку Пащі, певен, ти на власні очі бачив душі, що й далі ллються в Пащу.\n\nМи маємо діяти зараз, щоб підірвати могутність Тюремника, відібравши в нього якомога більше душ. Ця сила належить некролордам.\n\nЯ скеровуватиму твої зусилля з порятунку цих душ і допоможу знайти їм місце серед військ Малдраксуса.\n\nПовернися до Пащі й визволи тих, кого зможеш.",
        objectives = "Врятуй душі в Пащі.",
        completion = "Чудово, Ходоку Пащі. Наші армії міцнішатимуть із кожною душею, яку ти повернеш.",
    },
    [62866] = {
        title = "Повернути загублені душі",
        description = "Ходоку Пащі, певен, ти на власні очі бачив душі, що й далі ллються в Пащу.\n\nМи маємо діяти зараз, щоб підірвати могутність Тюремника, відібравши в нього якомога більше душ. Ця сила належить некролордам.\n\nЯ скеровуватиму твої зусилля з порятунку цих душ і допоможу знайти їм місце серед військ Малдраксуса.\n\nПовернися до Пащі й визволи тих, кого зможеш.",
        objectives = "Врятуй душі в Пащі.",
        progress = "Немає долі, гіршої за Пащу.",
        completion = "Чудово, Ходоку Пащі. Наші армії міцнішатимуть із кожною душею, яку ти повернеш.",
    },
    [62867] = {
        title = "Повернути загублені душі",
        description = "Душі й далі потоком ллються в Пащу.\n\nЇхня аніма, життєдайна кров усього Тіньокраю, відходить разом із цими душами, живлячи Тюремника. Ти врятував мене з Пащі. Не бачу причини, чому б тобі не вирвати з тієї безодні ще більше душ.\n\nПриводь до мене душі, які визволиш з Пащі, і я подбаю, щоб їм знайшлося краще застосування. Принаймні в Ревендреті вони матимуть шанс на спокуту.",
        objectives = "Врятуй душі в Пащі.",
        completion = "Дуже добірна колекція душ. Не надто зламані, не надто виснажені й не надто безвинні.\n\nНе бійся: у наших руках їхня доля буде кращою, ніж у Тюремника.",
    },
    [62868] = {
        title = "Повернути загублені душі",
        description = "Душі й далі потоком ллються в Пащу.\n\nЇхня аніма, життєдайна кров усього Тіньокраю, відходить разом із цими душами, живлячи Тюремника. Ти врятував мене з Пащі. Не бачу причини, чому б тобі не вирвати з тієї безодні ще більше душ.\n\nПриводь до мене душі, які визволиш з Пащі, і я подбаю, щоб їм знайшлося краще застосування. Принаймні в Ревендреті вони матимуть шанс на спокуту.",
        objectives = "Врятуй душі в Пащі.",
        completion = "Дуже добірна колекція душ. Не надто зламані, не надто виснажені й не надто безвинні.\n\nНе бійся: у наших руках їхня доля буде кращою, ніж у Тюремника.",
    },
    [62869] = {
        title = "Повернути загублені душі",
        description = "Душі й далі потоком ллються в Пащу.\n\nЇхня аніма, життєдайна кров усього Тіньокраю, відходить разом із цими душами, живлячи Тюремника. Ти врятував мене з Пащі. Не бачу причини, чому б тобі не вирвати з тієї безодні ще більше душ.\n\nПриводь до мене душі, які визволиш з Пащі, і я подбаю, щоб їм знайшлося краще застосування. Принаймні в Ревендреті вони матимуть шанс на спокуту.",
        objectives = "Врятуй душі в Пащі.",
        completion = "Дуже добірна колекція душ. Не надто зламані, не надто виснажені й не надто безвинні.\n\nНе бійся. У наших руках їхня доля буде кращою, ніж у Тюремника.",
    },
    [62870] = {
        title = "Душі для Гріхопаду",
        description = "Бейн страждає в Торгасті, та принаймні ми знаємо, що він іще живий.\n\nКидатися йому на порятунок без плану нападу було б згубно. Я подбаю про те, щоб його скласти.\n\nА тим часом раджу тобі привести врятовані душі назад до Гріхопаду.\n\nПідступи Денатрія залишили вентирів зі скупими запасами, і принцу Ренаталу знадобляться всі душі, які він зможе зібрати.",
        objectives = "Поверни душі, врятовані з Пащі, Тенавалу в Гріхопаді, що в Ревендреті.",
        completion = "А, отже, тобі все вдалося. Я й не сумнівався.\n\nА тепер знайдімо цим душам застосування.",
    },
    [62882] = {
        title = "Встановлюємо правила",
        description = "Знову прийшов рятувати душі? Яка відвага.\n\nХоча мушу зізнатися: твоя попередня вилазка привернула увагу Тюремника... і його гнів. Зрештою, досі ніхто не зміг від нього вислизнути.\n\nОкрім мене.\n\nТепер його сили насторожі й полюють на кожну заблукану душу, яку легендарний Ходок Пащі може спробувати в нього вкрасти.\n\nЦе зробило все вельми... незручним для мене. Якщо ми з тобою збираємося працювати разом, нам треба встановити кілька основних правил.\n\nІ ти маєш бути належно споряджений.",
        objectives = "Установи основні правила співпраці з Ве'нарі.",
        progress = "Обговорімо умови нашої угоди.",
        completion = "Бережи того Хранителя Душ. Я не маю ані найменшого бажання морочитися з добуванням нового.\n\nА тепер — до справи.",
    },
    [62883] = {
        title = "Хранителька великої слави",
        description = "Що більшу славу ти здобуваєш по всьому Тіньокраю, то дужче з тобою зростатиме й Серце Лісу.\n\nРозшукай Лорел, нашу хранительку слави. Вона ознайомить тебе з магією, якою ми наділяємо наших мисливців і мисливиць.",
        objectives = "Розшукай Лорел у Серці Лісу.",
        completion = "<Лорел бренькає на арфі короткий туш, коли ти підходиш.>\n\nО, наш новий чемпіон і добрий товариш! Радо вітаю, {NAME}.",
    },
    [62884] = {
        title = "Ліс співатиме твоє ім'я",
        description = "<Лорел спритними пальцями виводить вигадливу мелодію й співає.>\n\nЯ — хранителька слова і діла,\nткаля пісень і переказів давніх.\nЩо більшу славу здобудеш, то більше дарів,\nтак ми вшановуємо клятви заповітні.\n\nКожен учинок твій — то насінина сили,\nщо проросте небаченою міццю.\nЗаговори зі мною й поглянь, що чекає, —\nнаша магія готова тобі відкритися!",
        progress = "Не можу дочекатися, коли складу пісню про тебе!",
        completion = "<Лорел грає переможний пасаж.>\n\nХай твоя історія росте, як віття, що тягнеться до небес! Як наше коріння, що вростає глибоко в землю!",
    },
    [62890] = {
        title = "Та, що формує ліс",
        description = "Ти виконав своє покликання, Ходоку Пащі, і приніс спокій нашому лісу.\n\nЛишайся пильним, бо з часом і інші так само звернуться до тебе по допомогу.\n\nАніма, яку ти зібра$p(в:ла), стане в великій пригоді Серцю Лісу. Віднеси її до Зейгад. Вона збереже її в безпеці, доки в ній не виникне потреба. Ти знайдеш її глибоко в коренях Серця Лісу.",
        completion = "Коріння в'яне без аніми. З твоїм даром ми всі зможемо рости.",
    },
    [62891] = {
        title = "У Водойму",
        description = "Гаї в'януть, і наша Королева плаче на безплідній землі. Аніма, дорогоцінна, як вода, нині рідкісна, як сніг. Наша Королева ділиться власним, прихищає всіх під своїм гіллям... але одне дерево ще не ліс.\n\nТвій дар цінуватимуть і берегтимуть. Аніма живить наше коріння, як надія живить наші серця. Можливо, Арденвельд ще колись розквітне знову.",
        progress = "Марнувати нічого — і ніщо не буде змарноване. Вона буде в безпеці, доки не знадобиться.",
        completion = "Крізь голод і посуху ліс вистоїть. Наша вдячність не піддається опису.",
    },
    [62892] = {
        title = "Поверни загублених",
        description = "Аніма й душі. Вітер і дощ. Арденвельду потрібне і те, і те, щоб квітнути.\n\nДуші, призначені для нашого гілля, страждають у темряві. Ніхто не втікає з Пащі... але ти ходиш її тінями й повертаєшся. Ти — їхнє спасіння.\n\nПурхавка опікується зграйкою з турботою і співчуттям. Поговори з нею. Поверни наші загублені душі додому.",
        completion = "Я така рада, що ти тут! У нас стільки душ, які треба врятувати!",
    },
    [62893] = {
        title = "Зроби те, що нам не до снаги",
        description = "Подейкують, що ти побува$p(в:ла) в Пащі й повернувся... і що ти навіть заприятелював там із посередницею!\n\nСтільки душ, призначених для Арденвельду, ув'язнені в тому темному царстві. Їм потрібна наша допомога... а нам — їхня! Без них ми не зможемо плекати магію Серця Лісу.\n\nЗнаю, я прошу багато... але ти, можливо, наша єдина надія їх врятувати. Прошу, вирушай в Пащу й зроби те, що нам не до снаги. Від цього залежить майбутнє Арденвельду!",
        completion = "Так скоро знову тут, Ходаче Пащі?",
    },
    [62894] = {
        title = "Пурхни назад",
        description = "Бейн страждає в Торгасті, але принаймні ми знаємо, що він іще живий.\n\nКинутися йому на порятунок без плану нападу було б згубно. Я подбаю про те, щоб його скласти.\n\nА тим часом раджу тобі повернути врятовані душі до Арденвельду.\n\nВони заслуговують на перепочинок після свого жахливого випробування в Пащі, і вони, безперечно, виявляться вкрай важливими для зусиль Нічних Фей.",
        completion = "З поверненням! Я така рада, що ти не лиши$p(вся:лася) там у пастці! Це означає, що вся наша тяжка праця не піде намарне!\n\n<Пурхавка хихотить.>\n\nМи тут не байдикували!",
    },
    [62895] = {
        title = "Вибір шляху",
    },
    [62896] = {
        title = "Вибір шляху",
    },
    [62897] = {
        title = "Врятовані душі",
        description = "О, цікаво, яких подоб наберуть ці душі!\n\nСловами не передати, які ми вдячні, що ти їх врятував. Ти не лише поклав край їхнім мукам, але вони, можливо, навіть захочуть нам допомогти.\n\nІди поговори з Зейгад. Вона вже давно не мала змоги доглядати ліс, але це може незабаром змінитися. Усе це так захопливо!",
        completion = "Листя на буремному вітрі знаходить безпечний прихисток.",
    },
    [62898] = {
        title = "Перший новий паросток",
        description = "Довго ми спали. З душами, з анимою ми ростемо знову.\n\nТепер на нас чекає вибір. Як нам рости? Ти можеш вирішити, яка квітка розквітне першою.\n\nЗ часом, із більшою кількістю аними й готових допомогти душ, увесь сад розквітне. А поки що єдина квітка звістує надію на майбутнє.\n\nЛеді Місячноягода захоче знати про твій вибір. Знайди її, коли зробиш його.",
        objectives = "Розпочни вдосконалення санктуму.",
        completion = "Ну й попрацюва$p(в:ла) ж ти! Здається, ми знову перед тобою в боргу.\n\nНа щастя, гадаю, я маю саме той дарунок, яким можна віддячити.",
    },
    [62899] = {
        title = "Безкраїй ліс",
        description = "Що ж, оце і все, що я маю для тебе! Уф! Ти промчав вихором крізь усі тутешні справи, чи не так? Угору, вниз, навскоси й навіть в Пащу! У тебе, мабуть, аж голова обертом іде.\n\n<Пурхавка хихотить.>\n\nТобі варто навідатися до леді Місячноягоди й повідомити їй, що твоє навчання завершене!\n\nВона, напевно, не влаштує тобі іспит із того, що ти вивчи$p(в:ла).\n\nНапевно.",
        objectives = "Повернися до леді Мунберрі.",
        completion = "Ласкаво просимо до Двору Ночі, {NAME}. Я просто впевнена: ми врятуємо Арденвельд! О, і решту Тіньокраю теж!\n\nА якщо не зможемо, і ліс зів'яне, і Тюремник вирветься з Пащі та ввергне всі вічні царства в нищівний відчай, з якого немає вороття... \n\nТо принаймні зможемо сказати, що спробували — і нам було весело!",
    },
    [62900] = {
        title = "Провідник росту",
        description = "Хоча наш зв'язок і сам собою могутній, ти можеш посилити його за допомогою провідників.\n\nПровідники спрямовують аниму між душезв'язками безліччю різних способів, примножуючи при цьому потенціал нас обох. Вони дають нам змогу налаштуватися на унікальні сильні сторони одне одного.\n\nВикористаймо кілька зараз. Якщо вони здатні ще більше зміцнити наш зв'язок, то вони допоможуть нам захищати ліс.",
        objectives = "Додай провідників до Кузні Зв'язків, тоді встав одного в комірку Нії.",
        progress = "Разом ми звершимо великі справи.",
        completion = "Ви з Нією з часом зростатимете разом. Але наразі твій вишкіл завершено.",
    },
    [62902] = {
        title = "Аніма — це сила",
        description = "Ти добре впорався, босе. Тримай так і далі, і ми, може, ще й матимемо шанс пережити цю халепу.\n\nАле не втрачай пильності. Чутки про такий успіх розходяться, і це лиш питання часу, доки інші почнуть кликати тебе на поміч.\n\nОтож уся та аніма, яку ти зібра$p(в:ла), тут стане в пригоді. Віднеси її до старшини Плескопалого. Він подбає, щоб її зберегли надійно й безпечно.",
        objectives = "Поговори зі старшиною Плескопалим.",
        completion = "Бос вертається переможцем! Маєш аніму при собі, га?",
    },
    [62903] = {
        title = "У Водойму",
        description = "Аніма нині в дефіциті, тож мені доручили завідувати запасами, доки вони не знадобляться.\n\nСміливо складай будь-яку аниму, яку зібрав, у цю водойму.\nБудь певен, під моїм наглядом вона буде в цілості й безпеці.",
        objectives = "Склади аніму до резервуару свого святилища.",
        progress = "Запевняю тебе, ця водойма — найбезпечніше місце для зберігання аніми в усьому Ревендреті.",
        completion = "Ось так. Тепер аніма в цілості й безпеці.",
    },
    [62904] = {
        title = "Біда душ",
        description = "Аніма дає нам змогу робити чимало всякого, але цей санктум не може діяти на самій лише анимі. Для цього знадобляться спільні зусилля багатьох душ, що працюватимуть разом, аби розкрити його повний потенціал.\n\nВартовий душ прагне прислужитися, відколи ти врятува$p(в:ла) його з Пащі. Твоя унікальна здатність виводити звідти душі стане йому в пригоді.\n\nЧому б тобі не навідатися до нього?",
        objectives = "Поговори з Тенавалом.",
        completion = "Радий знову розмовляти з тобою, Ходаче Пащі.",
    },
    [62905] = {
        title = "Назад у темряву",
        description = "Душі й далі течуть в Пащу, а з ними й анима, що могла б нам допомогти.\n\nТи зміг врятувати мене з того місця. Чи можу я розраховувати на твою силу, щоб повторити те саме?\nПрошу, приведи нам більше готових допомогти душ, аби ми могли зміцнити силу цього санктуму.\n\nШукай будь-яку допомогу, яку зможеш знайти, і зроби те, що нам не до снаги, Той, що ходить Пащею. Ти — наша остання й найкраща надія.",
        objectives = "Знайди Ве'нарі в Пащі.",
        completion = "Так скоро знову тут, Ходаче Пащі?",
    },
    [62914] = {
        title = "Коаліція добровольців",
        description = "Добрі люди Ревендрета й далі страждають під гнітом прибічників Денатрія. Перш ніж відкрито виступити проти нашого колишнього Володаря, ми мусимо зміцнити свої сили.\n\nДоброхітні душі, які ти врятува$p(в:ла) із Пащі, стануть благом у ці тяжкі часи.\n\nІди до десятника Плоскопала. Він шукає помічників, щоб зводити вдосконалення для нашого святилища. Разом ми розкриємо весь потенціал Гріхопаду.",
        objectives = "Поговори зі старшиною Плескопалим.",
        completion = "Гей! А це шо таке? Нові душі, ге? \n\nАга, є в них трохи потенціалу, є. Багацько всякого я тут зможу зробити з їхньою поміччю.",
    },
    [62915] = {
        title = "Облаштування домівки",
        description = "Я тут надумав кілька способів, як можна покращити це місце, та позаяк саме ти приніс усю аніму й душі для цього, гадаю, тобі й вирішувати, з якого вдосконалення почати першим.\n\nТільки не лякайся обсягу. Що більше аніми ти принесеш і що більше доброхітних душ знайдеш, то більше можливостей ми тут створимо. А поки що вистачить і одного вдосконалення.",
        objectives = "Розпочни вдосконалення санктуму.",
        progress = "Не квапся. Перший крок завше найважчий.",
        completion = "Гарний вибір. \n\nБудівництво трохи потриває, але ж добрі речі часу потребують, еге ж?",
    },
    [62916] = {
        title = "Твій новий найкращий друг",
        description = "Шукаєш нового друга? Гу-гу!\n\nБагато стюардів радо стануть друзями. А ще теперішній друг зможе перепочити! Може, піде до Скель Спочинку, дасть ногам відпочити, поїсть тістечок...\n\n<Сіка поринає в марення.>\n\nГу! Точно!\n\nЯ покличу стюардів. А ти знайдеш нового друга!",
        objectives = "Обери нового стюарда-супутника, тоді повернися до Сіки.",
        progress = "Нові друзі, нові друзі! Стюарди люблять заводити нових друзів!",
    },
    [62917] = {
        title = "Спільні душі",
        description = "Сила Женців тече твоїм смертним тілом. Та ти можеш здобути ще більшу могуть, зв'язавши свою душу з іншою.\n\nЦе не несе жодних відомих недоліків, зате дає чимало переваг для обох сторін.\n\nЗа цим процесом наглядатиме Викривачка. Зустрінься з нею біля Кузні Зв'язків, коли будеш готовий.",
        objectives = "Зустрінься з Викривачкою біля Кузні Зв'язків.",
    },
    [62918] = {
        title = "Сила єднання",
        description = "Сила Женців тече твоїм смертним тілом. Та ти можеш здобути ще більшу могуть, зв'язавши свою душу з іншою.\n\nДушевний зв'язок з іншим не є нерозривним. Та все ж не варто легковажно на нього зважуватися.\nВи переживете минуле одне одного. Ваші сподівання, страхи, мрії, самі ваші спогади — якщо вони ще лишилися. Ви станете спорідненими душами в найправдивішому сенсі.\n\nКоли все звершиться, ваш зв'язок переступить межі фізичного простору й зробить тебе сильнішим не лише тілом.",
        objectives = "Заверши ритуал душевного зв'язку.",
        completion = "Твоє життя досі було... цікавим. Я подбаю, щоб воно стало ще цікавішим.",
    },
    [62919] = {
        title = "Зміцнення зв'язку",
        description = "Ти теж це відчуваєш? Наш зв'язок міцніший, ніж я могла собі уявити.\n\nМені казали, що зв'язок і далі зростатиме з часом, проте ми маємо змогу пришвидшити цей процес.\n\nГріхопаду потрібна наша сила. Можливо, найкраще буде вдатися до цього способу вже зараз.",
        progress = "Це піде на користь нам обом.",
        completion = "Разом ми багато чого досягнемо.",
    },
    [62920] = {
        title = "Провідник змін",
        description = "Хоч сили від вашого зв'язку вже значні, ти можеш зміцнити зв'язок іще дужче за допомогою провідників.\n\nПровідники спрямовують енергію твого душевного зв'язку безпосередньо в тебе, збільшуючи твій потенціал на безліч ладів.\n\nВикористай ті, що я тобі дала, щоб випробувати цю силу, та не бійся — інші ти знайдеш у своїх мандрах.",
        objectives = "Додай провідників до Кузні Зв'язків, тоді встав одного в комірку Наджії Туманного Клинка.",
        progress = "Цей крок — вирішальний для твого поступу.",
        completion = "Твій душевний зв'язок міцнішатиме з часом, але наразі твій вишкіл завершено.",
    },
    [62921] = {
        title = "Наше справжнє призначення",
        description = "Ми вдячні за цей союз, $p(Подорожній:Подорожня) Пащі.\n\nЗа твоєю допомогою Ренатал поведе нас у нову епоху — таку, що поверне Ревендрету його справжнє призначення.\n\nПовернися до нього зараз, щоб могла початися справжня робота.",
        objectives = "Повернися до принца Ренатала.",
        completion = "Сподіваюся, тобі все припало до вподоби.",
    },
    [62928] = {
        title = "Креслення: Перстень оберегу",
        description = "<Ти знайшов креслення захисного оберега, що може дати твоїм душевним побратимам перевагу на Шляху Піднесення.\n\nДактиліс має допомогти тобі виготовити це спорядження.>",
        objectives = "Віднеси Креслення: Перстень оберегу до Дактиліса.",
        completion = "Бачу, ти здобу$p(в:ла) нове креслення. З нетерпінням чекаю нагоди допомогти тобі у виготовленні.",
    },
    [62932] = {
        title = "Дослідити Торгаст",
        description = "Бейн у безпеці, та інші наші союзники досі бранці Тюремника. Вони лишаються в смертельній небезпеці.\n\nТоргаст — місце, що постійно змінюється, перетворюючись за волею свого володаря. Можливо, вистежити їх звичайними способами годі.\n\nЗайди до його тюремних блоків і подивися, які відомості зможеш знайти. Шукай будь-яку зачіпку, що могла б привести нас до наших зниклих друзів, і принеси її мені.",
        objectives = "Дослідь Торгаст у пошуках зачіпок, що допоможуть відшукати твоїх союзників.",
        progress = "Що тобі вдалося знайти?",
        completion = "<Болвар пильно вивчає предмет.>\n\nЯ відчуваю знайому есенцію. Власник цього ключа, можливо, причетний до полону Джайни Праудмур.\n\nМені потрібен час на подальші дослідження. Я зв'яжуся з тобою, щойно визначу наш подальший курс.",
    },
    [62935] = {
        title = "Рештки надії",
        description = "Я дослідив ключ, який ти приніс із Торгаста, {name}.\n\nВін підтверджує, що Джайна Праудмур досі утримується десь у вежі. Проте ми не знаємо, де саме.\n\nУ цьому жалюгідному місці ув'язнено незліченні душі. Дехто з них, можливо, ще цілий, та багато хто розбитий і зламаний.\n\nЗглянься над цими рештками й звільни тих, кого зможеш. Можливо, вони зуміють допомогти в наших пошуках.",
        objectives = "Дізнайся, чи зможеш почерпнути нові відомості від ув'язнених решток душ у Торгасті.",
        completion = "Добре, що ти врятува$p(в:ла) ті замучені душі, {NAME}. Шкода, що жодна не змогла допомогти нашій справі. \n\nМушу обміркувати подальший шлях. Я знову озвуся, коли знатиму, як діяти найкраще.",
    },
    [62938] = {
        title = "Відомості за плату",
        description = "Ми мусимо продовжити пошуки Джайни Праудмур. Маю запропонувати нову стратегію.\n\nВідколи я прибув до Орибоса, до мене зверталося багато посередників. Одні ставлять запитання, інші пропонують поміч — за плату.\n\nТи зустрічав інших із їхнього роду в Торгасті. Вони можуть володіти відомостями, які нам стануть у пригоді, хоч я сумніваюся, що вони поділяться ними задарма.\n\nРозшукай їх і зіграй на їхній зажерливості. Запропонуй заплатити за будь-які відомості, які вони мають.",
        objectives = "Розпитай Посередників, ув'язнених у Торгасті.",
        progress = "Багатонадійна зачіпка.",
        completion = "Схоже, зажерливість посередників стала нам у пригоді.\n\nМожливо, ти здобу$p(в:ла) саме те, що нам потрібно.",
    },
    [62951] = {
        title = "Шлях Сходження: Клея",
        description = "Артемеда особисто тренувала Клею, проводячи її через бойові медитації та вправи.\n\nВона зайшла далеко й готова пройти ще одне випробування на Шляху Сходження.\n\nПовернися до колізею і веди її як тактик, щоб вона здобула перемогу.",
        objectives = "Здобудь перемогу в будь-якому випробуванні Шляху Сходження за Клею.",
        completion = "Як ми й сподівалися. Сила Клеї продовжує зростати.",
    },
    [62952] = {
        title = "Шлях Сходження: Пелагос",
        description = "Хоча бій не його сильна сторона, Пелагос читав, медитував і тренувався, щоб удосконалитися на Шляху.\n\nМи віримо, що він готовий здобути перемогу.\n\nВін просить, щоб ти бу$p(в:ла) поруч і допоміг йому з тактикою. З допомогою друзів він стає сильнішим.",
        objectives = "Здобудь перемогу в будь-якому випробуванні Шляху Сходження за Пелагоса.",
        completion = "Одного дня Пелагосу доведеться долати випробування самотужки, щоб зростати.\n\nА поки що затишок і підтримка його душевних побратимів — саме те, чого він потребує.",
    },
    [62953] = {
        title = "Шлях Сходження: Міканікос",
        description = "Міканікос наполегливо працював у Вічній Кузні, налаштовуючи Брона та вдосконалюючи його бойові процедури.\n\nВін упевнений у своїх останніх змінах і просить дозволу пройти ще одне випробування.\n\nСтупи на Шлях разом із Міканікосом, щоб він зміг оцінити сильні й слабкі сторони свого голіафа.",
        objectives = "Здобудь перемогу в будь-якому випробуванні Шляху Сходження за Міканікоса.",
        completion = "Схоже, Брон і справді зміцнів!\n\nЦікаво буде побачити, як Міканікос застосує ці нові знання, щоб удосконалити центуріонів загалом.",
    },
    [62954] = {
        title = "Шлях Сходження: Калісфена",
        description = "Твої душевні узи потребують твого стратегічного розуму в новому випробуванні.\n\nЦього тижня вони зосередилися на Калісфені, щоб засвоїти уроки, яких навчає її пам'ять.\n\nКоли зможеш, з'явися до Артемеди, щоб повернутися на Шлях Сходження. Допоможи своїм душевним узам перемогти Калісфену, щоб довести своє зростання.",
        objectives = "Здолай Калісфену на Шляху Сходження будь-якими душевними узами.",
        completion = "Вітаю з перемогою. З нетерпінням чекаю почути, чого навчилися твої душевні узи.",
    },
    [62966] = {
        title = "Пошук свідка",
        description = "Ти врятував двох наших союзників із Торгаста, але Андуїна й Тралла досі не знайдено.\n\nКоридори тієї вежі величезні... здавалося б, нескінченні. Можна цілу вічність блукати тими нечестивими залами.\n\nУ своїх вилазках ти зустріча$p(в:ла) чимало нещасних в'язнів. Можливо, хтось із них бачив чи чув щось, що могло б скерувати наші пошуки.\n\nЗнайди будь-яких полонених, які можуть мати потрібні нам відомості, {name}.",
        objectives = "Знайди в Торгасті в'язня, який може знати, де тримають Андуїна чи Тралла.",
        completion = "Мене втішає, що Тралл досі живий. Присягаюся Світлом, ми його знайдемо.\n\nЯ боюся за Андуїна. Темрява жадає його душі.\n\nМи мусимо готуватися. Я озвуся, коли настане час діяти.",
    },
    [62967] = {
        title = "В'язниця забутих",
        description = "Я знайшов цікаву річ у Наглядача, якого ти вби$p(в:ла) у вежі.\n\nКраще не питай, звідки я знаю, що ти робиш і де ти це робиш у вежі. Скажімо так: у мене свої методи.\n\nАле цей ключ може привести до чогось цікавого в Торгасті. Або до чогось жахливого. Найімовірніше, жахливого.\n\nТобі варто трохи поблукати й подивитися, що він відмикає.",
        objectives = "З'ясуй, де скористатися Ключем забутих.",
        completion = "<Щойно ти вставляєш ключ у пристрій, той на мить здригається й починає відмикатися.>",
    },
    [62969] = {
        title = "Поки слід не охолов",
        description = "Із того, що розповів тобі полонений копач, схоже, що Тралла забрали глибоко в надра Торгаста. Муки, які він терпить, мабуть, неуявні.\n\nМи маємо дізнатися, де його тримають, поки слід не охолов.\n\nВежа величезна й небезпечна. Шукай там, де зможеш. Принось будь-які знахідки, які знайдеш.\n\nБудь обережний, {name}. Око Тюремника стежить за тобою.",
        objectives = "Увійди до Торгаста й знайди щось, що допоможе відшукати Тралла.",
        progress = "Чи вдалося знайти щось, що допоможе відшукати Тралла?",
        completion = "<Болвар вивчає тотем.>\n\nТак, це може вказати нам на місце, де тримають Тралла.",
    },
    [62970] = {
        title = "Креслення: Поштова сумка провоста",
        description = "<Ти знайшов креслення сумки на розмір провоста, ідеальної для перенесення пошти.\n\nДактиліс має змогти допомогти тобі це виготовити.>",
        objectives = "Віднеси Креслення: Поштова сумка провоста до Дактиліса.",
        completion = "Бачу, ти здобу$p(в:ла) нове креслення. З нетерпінням чекаю нагоди допомогти тобі у виготовленні.",
    },
    [62971] = {
        title = "Креслення: Позолочений абак",
        description = "<Ти знайшов креслення абака на розмір провоста, здатного обчислювати внески та зняття на будь-якій відстані.\n\nДактиліс має змогти допомогти тобі це виготовити.>",
        objectives = "Віднеси Креслення: Позолочений абак до Дактиліса.",
        completion = "Бачу, ти здобу$p(в:ла) нове креслення. З нетерпінням чекаю нагоди допомогти тобі у виготовленні.",
    },
    [62976] = {
        title = "Пояс із інструментами ремісника",
        description = "<Пояс із інструментами має багато кишень та петель і споряджений безліччю інструментів і матеріалів.\n\nВін дозволить твоєму провосту не лише допомагати тобі з ремеслом, а й переносити звичайні ремісничі товари.>",
        objectives = "Приклич свого супутника-управителя за допомогою «Прикликати управителя», а тоді віддай йому Поштову сумку управителя.",
    },
    [62981] = {
        title = "Креслення: Пояс із інструментами ремісника",
        description = "<Ти знайшов креслення добротно зробленого пояса з інструментами — ідеального подарунка для твого улюбленого провоста.\n\nДактиліс має змогти допомогти тобі це виготовити.>",
        objectives = "Віднеси Креслення: Пояс із інструментами ремісника до Дактиліса.",
        completion = "Бачу, ти здобу$p(в:ла) нове креслення. З нетерпінням чекаю нагоди допомогти тобі у виготовленні.",
    },
    [62984] = {
        title = "Креслення: Медальйон служіння",
        description = "<Ти знайшов креслення для пожертв, що дозволяє заробляти Медальйони служіння — шанований кіріанський символ відзнаки. Жертвуючи матеріали своєму святилищу, ти можеш отримувати Медальйони, щоб ступати на Шлях.\n\nДактиліс має змогти допомогти тобі в цьому.>",
        objectives = "Віднеси Креслення: Медальйон служіння до Дактиліса.",
        completion = "Бачу, пропорції пожертв для Медальйонів служіння знайдено. Радо винагороджу тебе, щойно ти внесеш матеріали.",
    },
    [62985] = {
        title = "Викопати новий вигляд",
        description = "Якщо пошукаєш біля брудної калюжі, певен, знайдеш фарбу для броні. Було б непогано мати змогу пофарбувати мій пояс в інший колір.",
        objectives = "Обшукай ворогів або викинуті пляшки в Дреджвуді, щоб знайти фарбу для броні.",
