    [63142] = {
        title = "Креслення душокузні",
        description = "<Переглядаючи документи, які маєш при собі, ти усвідомлюєш, що в них описано жахливі способи, якими душі можна перековувати на зброю.\n\nВе'нарі це заінтригувало б.>",
        objectives = "Віднеси Креслення Душокузні Ве'нарі в Притулок Ве'нарі.",
        completion = "Сировину в Пащі, певно, дістати нелегко. Не дивно, що зброярам Тюремника доводиться бути... винахідливими.\n\nМабуть, знання, записані в цих кресленнях, краще лишити в таємниці.",
    },
    [63145] = {
        title = "Свідчення тінепов'язаного",
        description = "<Схоже, це викликане болем безладне маячіння змученого в'язня Торгаста.\n\nВе'нарі знайде в цьому цінність.>",
        objectives = "Віднеси Свідчення Тінепов'язаного Ве'нарі в Притулок Ве'нарі.",
        completion = "Оце так знахідка, Ходаче Пащі. Відомості з перших рук зсередини Торгаста — рідкісні й цінні. Ніхто з тих, хто ступав до вежі, не повернувся, щоб про це розповісти.\n\nЗа винятком присутніх, звісно.",
    },
    [63152] = {
        title = "Угода вентирів",
        description = "<Схоже, це зашифроване листування між вельможею-вентиром і лейтенантом Поріддя Пащі.\n\nМожливо, Ве'нарі зможе його розшифрувати.>",
        completion = "<Ве'нарі ковзає поглядом по сувою, обертаючи його то так, то сяк.>\n\nДавненько я не бачила такого хитромудрого способу шифрування. Але вентири, гадаю, якщо чимось і славляться, то показною пишнотою.\n\nХоч би що містило це послання, ясно одне: його автор прагнув зберегти все в таємниці.",
    },
