    [63845] = {
        title = "Гнів Одіна",
        description = "Ріг викуто, а гідних обрано.\n\nТепер, {name}, нам лишилося тільки прив'язати моїх обраних валькір до рога й наповнити їх моєю силою, аби вони разили з моєю люттю.\n\nХодімо, будь свідком.",
        objectives = "Стань свідком наснаження обраних валькір і прив'язання Ілскагорна.",
        progress = "Так? Є питання?",
        completion = "Зроблено. Даніка та її сестри сповнені моєї сили й несуть мій гнів.",
    },
    [63846] = {
        title = "Жариночний збір",
        description = "Геній Теотара незаперечний, але надто багато хто не помічає винахідливості його помічників-копачів, Габбінса й Таббінса.\n\nГлянь на той гребінь удалині. Кузні Тюремника там вивергають Жарини сталі душ.\n\nЗ дзеркала, зробленого з них, ми могли б досягти багато чого...\n\nГаббінс уже змайстрував особливу парасолю, здатну вберегти власника від будь-яких падаючих жарин.\n\nЗустрінься з ним біля кузень і роздобудь трохи тих Жарин сталі душ!",
        objectives = "Здолай 4 Розлючені уламки кузні та збери 4 Жарини сталі душ.",
    },
    [63848] = {
        title = "Прояв вдячності",
        description = "Твоя присутність тут справджує давнє пророцтво, Ходоче Пащі. Я певен, що ти і твої союзники врятуєте нас.\n\nМабуть, я надто суворо судив про твою подругу-посередницю. Зрештою, саме вона провела тебе до Кортії.\n\nПередай, будь ласка, нашу подяку Ве'нарі й перекажи їй, що ми радо відповімо на її запитання.\n\nА їх у неї, схоже, є чимало.",
        objectives = "Поговори з Ве'нарі в Притулку Хранителя в Кортії.",
        completion = "Подяка — це ввічливо.\n\nПослуга — краще.",
    },
    [63849] = {
        title = "Слуховий пристрій",
        description = "Яка вдала нагода! Так сталося, що тебе перенесли саме туди, де я маю певний... інтерес. Розстав слухові секвенсори, які я тобі дала, і я спробую налагодити робочий сигнал.\n\nТаке небезпечне місце вимагатиме якнайбільшої обережності. Тобі варто скористатися своїм ефірним плащем, щоб лишитися непоміченим.",
        objectives = "Розстав слухові секвенсори в Десмотаероні, щоб допомогти Ве'нарі підслуховувати мешканців.",
        completion = "Чудово. Їхні таємниці скоро будуть моїми.\n\nПерепрошую. Я хотіла сказати \"нашими\".",
    },
    [63850] = {
        title = "Відстеження — малі консолі",
    },
    [63853] = {
        title = "Згаси полум'я",
        description = "Ти його бачиш?\n\nКрай ока, увесь час, воно завжди там... сяє так яскраво!\n\nЯк можна розслабитися й насолодитися чашкою чаю, коли довкола ця нагадка про вогонь і попіл.\n\nБудь ласка, Ходоче Пащі, зроби мені послугу... прибери його, щоб ми всі могли натішитися чашкою мого улюбленого чаю!",
        objectives = "Убий Інфернуса Нескінченного для Теотара.",
        progress = "Чи вбито те жахливе створіння?",
        completion = "Солодкий перепочинок від жаского погляду того створіння.",
    },
    [63855] = {
        title = "Легкість переходу",
        description = "Кортія сповнена можливостей. Поглянь лишень на всі ці захопливі речі.\n\nПередчуваючи такі дива, я прийшла підготованою. Знайдімо відповідне місце й налагодимо тривкіший зв'язок між цим місцем і моїм притулком.\n\nНаша спільна робота ще не завершена.",
        objectives = "Налагодь зв'язок між Кортією та Прихистком Ве'нарі.",
        progress = "Я заберу свою торбу, якщо вона в тебе.",
        completion = "Подорож була того варта — стільки нових можливостей відкрилося.\n\n<Ве'нарі порпається у важкій торбі й дістає кілька незвичних предметів.>",
    },
    [63856] = {
        title = "Зібрання Ковенантів",
        description = "Хоч Тюремник і лишається ув'язненим у Пащі, його жорстокість сягає далеко за межі його в'язниці.\n\nНа щастя, Архонт одужує після нападу. Хоча, як мені кажуть, її рана має... тривожну властивість.\n\nВічні та їхні союзники чекають на тебе й верховного лорда Фордрагона в палаті Судді. Я відкрию шлях.\n\nЇї голосом я мовив.",
        objectives = "Поговори з Тал-Інарою, щоб увійти до палати Судді.",
        completion = "<Болвар зачудовано дивиться на видовище перед собою.>",
    },
    [63857] = {
        title = "Голоси Вічних",
        description = "<Болвар вдивляється у величні постаті перед собою, у незліченні брами, що простягаються в ефір.>\n\nЦя палата... воістину дивовижна.\n\nПроте немає часу завмирати з благоговіння. Шанований Голос мусить негайно розпочати цю зустріч.",
        objectives = "Вислухай план.",
        completion = "Наступною ціллю Тюремника має бути Королева Зими.\n\nМи мусимо зробити все можливе, щоб захистити її.\n\nІ я маю кілька ідей, як саме...",
    },
    [63858] = {
        title = "Мужність душі",
        description = "У цей час чвар усі ми проходимо випробування, Ходоче Пащі. Потрібні велика відвага й сила духу, щоб без страху зустріти наших ворогів.\n\nВдерися в їхні лави й покажи їм силу своєї мужності.",
        objectives = "Знищ 15 вояків Сил Тюремника в Кокірусі та Казані Зоваала.",
    },
    [63859] = {
        title = "Врятовані дзвонами",
        description = "Наші провости готують дзвони підкріплення, щоб прикликати додаткових кіріанців на допомогу в нашому штурмі. Однак Присяжні Пащі нападають на провостів, аби зірвати їхні зусилля.\n\nНам потрібно, щоб ти захисти$p(в:ла) наших провостів, поки вони завершують роботу, а тоді задзвонив у кожен дзвін, щоб прикликати підкріплення.",
        objectives = "Захисти й задзвони в західний, східний і південний дзвони підкріплення.",
        completion = "Звуки цих дзвонів зміцнюють наші серця й дають нам силу здобути перемогу в цій битві.",
    },
    [63860] = {
        title = "Талісман вічного вченого",
        description = "<Талісман пом'ятий і заляпаний брудом. Хоч би хто сховав його тут, поводився з ним грубо.\n\nАрхіваріус Ро-Суір має місце для цього талісмана в Реліквіарії спогадів.>",
        objectives = "Віднеси пошкоджений талісман Архіваріусу Ро-Суїру в Реліквіарій спогадів.",
        completion = "Де... де це знайшлося?\n\n<Архіваріус підносить талісман ближче, щоб роздивитися.>\n\nЯ не бачив його цілі еони. Я гадав, що він утрачений.",
    },
    [63861] = {
        title = "Початок збірки",
        description = "Продовжмо нашу роботу, здобувши найважливіший предмет будь-якого наукового дослідження -- загублений кодекс.\n\nЦе забере трохи часу, але поки ми працюємо далі, сторінки цього твору зростатимуть і розквітатимуть, як і сама Кортія впродовж еонів.\n\nЩодо його місцеперебування: раніше він спочивав глибоко в надрах самої Кортії, у Печері Споглядання на півдні.\n\nЛишається тільки сподіватися, що сили Тюремника ще не знайшли його.",
        objectives = "Поверни Кодекс Спогадів Архіваріусу Ро-Суїру в Реліквіарій спогадів.",
        progress = "Чи знайшовся кодекс? Сподіваюся, ми не запізнилися.",
        completion = "Так, так. Це він. Прекрасний, чи не так?\n\n<Вогкість кодексу заскочує архіваріуса зненацька. Він обережно проводить рукою по палітурці, бурмочучи заклинання м'яким, загадковим тоном.>\n\nПоки що це допоможе його зберегти, але заклинання довго не протримається. Мусимо братися до роботи.",
    },
    [63862] = {
        title = "NavTest",
        description = "Follow the path before you.",
    },
    [63863] = {
        title = "Єдині в гордості",
        description = "Попри наше суперництво, Немея і я діємо як одна команда перед лицем більших загроз. І прайд, і фалинкси — люті бійці на полі бою.\n\nДля нас обох буде честю допомогти тобі в битві, що чекає попереду.\n\nДозволь Андірі чи Ґатаматосу допомогти тобі здолати чемпіонів Тюремника, які загрожують нашим військам.",
        objectives = "Здолай Малфестуса, Домонуса та Фуріса.",
        progress = "Тепер, коли тих чемпіонів здолано, наші сили можуть просуватися вперед.",
        completion = "Ти виявляєш найвищу мужність.",
    },
    [63864] = {
        title = "Жахливе вариво",
        description = "Могильний пил і плямиста трава — жахливе поєднання смаків, а Таббінс наварив із цих складників цілу величезну партію чаю.\n\nВін був такий огидний, що я вилив увесь чайник у вогонь. Виявилося, що чай геть мокрий і чудово гасить полум'я!\n\nТаббінс тягтиме всю партію разом із тобою. Знайди їй гідне застосування — лий її на нестійкі жаринки-іскри довкола Казана Зоваала.",
        objectives = "Загаси 30 нестійких жаринок-іскор.",
        progress = "Благаю, сподіваюся, те вариво не пішло тобі до рота.",
        completion = "Прошу, скажи мені, що те жахливе вариво не потрапило тобі до рота. За всі наші старання тут ми заслуговуємо лише на найдобірніші купажі.",
    },
    [63867] = {
        title = "Боротьба з гнівом",
        description = "Я не музикантка, хоча й провела чимало годин, насолоджуючись виставами в Тазавеші.\n\nЩоб цей ріг заговорив, доведеться зібрати сильні почуття.\n\nУ проклятих бідолахах, кинутих у Річку Душ, нестримно вирує лють. Скористайся цим висмоктувальним пристроєм, щоб витягти гнів цих розлючених тіней у свій інструмент.\n\nЗойки люті, які ти здобудеш, дадуть тобі змогу пронизати Пащу й дістатися до своїх союзників.\n\nПідозрюю, що мелодія вийде не надто приємна.",
        objectives = "Скористайся висмоктувальним пристроєм, щоб витягти гнів із розлючених тіней у Річці Душ.",
        completion = "Голос цього інструмента мало кому потішить слух, але, гадаю, він послужить своїй меті.",
    },
    [63892] = {
        title = "Рунні жетони віщуна",
        description = "<Усередині торбинки лежить один рунний жетон. Він обертається і перевертається, наче його рухає невидима рука.\n\nУ камінь майстерно вирізьблено руни, що віддалено нагадують мову врайкулів. На звороті жетона є позначка, що він — частина набору.>",
        objectives = "Збери 20 рунних жетонів, а тоді принеси їх Архіваріусу Ро-Суїру в Реліквіарій спогадів.",
        progress = "Ти диви, це що, торбинка рунних жетонів? Скільки їх у тебе?",
        completion = "Тобі вдалося зібрати повний набір Рунних жетонів віщуна!\n\nЦе одна з перших реліквій, які я досліджував ще послушником-ученим. Якщо кинути жетони, їхнє розташування й повороти дадуть відповідь на будь-яке поставлене їм питання, хоча тлумачення їхнього змісту потребує досвіду й неабиякої інтуїції.\n\nЯ вже й не сподівався знову побачити повний набір.",
    },
    [63895] = {
        title = "Торба несподіванок",
        description = "Цікаво. Слухові секвенсори та ефірний плащ. Притримай їх, {name}. Маю підозру, що вони стануть у пригоді.\n\nО, і дещо особливе для мене теж. Якщо я не помиляюся — а помиляюся я вкрай рідко — це проєкційний механізм. Дуже зручно!\n\nА це що таке? Якийсь транспортувальний пристрій. Слід випробувати його негайно.\n\nПід «слід», звісно ж, я маю на увазі тебе.",
        objectives = "Випробуй транспортувальний пристрій із торби Ве'нарі.",
        completion = "Цей проєктор безумовно корисний. Приземлення безпечне, як я бачу.",
    },
    [63896] = {
        title = "Сльози проклятих",
        description = "Щоб прикувати інструмент до Пащі й надати йому потрібної тобі сили, його треба просочити сирою, непогамованою мукою душ, ув'язнених у цій проклятій темниці.\n\nГоря тут удосталь, тож роздобути його просто. Тобі лише треба дістатися до Горгоа. Прокляті проливають рясні сльози, що падають кристалізованою скорботою, поки їх несе Річкою Душ.\n\nБудь обережн$p(ий:а), щоб їхній сум не охопив тебе сам$p(ого:ої).",
        objectives = "Збери 10 сліз проклятих у Горгоа — Річці Душ.",
        progress = "Чи зібрано сльози?",
        completion = "Сила зібраного тобою горя прикує інструмент до Пащі.",
    },
    [63899] = {
        title = "Книга прив'язування: Божевільна відьма",
        description = "<Ти чуєш приглушений голос, що лунає зсередини цієї книги, час від часу переплітаючись із тріскотливим шумом. Хоча слова здебільшого нерозбірливі, ти можеш розчути повторюване прохання повернути багряні сторінки.\n\nГортаючи том, ти помічаєш, що багатьох його сторінок бракує.\n\nЯкби сторінки знайшлися, книгу можна було б повернути Архіваріусу й зібрати наново.>",
        objectives = "Збери 12 багряних сторінок, а тоді принеси їх Архіваріусу Ро-Суїру в Реліквіарій спогадів.",
        progress = "Ця книга... говорить?",
        completion = "Цей том досліджували вчені з Кворуму Шукача.\n\nСхоже, його розірвав хтось із самих учених, а не пащеприсяжні чи дикі звірі. Це тривожно.\n\nЗадля нашої безпеки я вшию назад у палітурку всі сторінки, крім однієї, перш ніж додати книгу до архіву. Доки ми не дізнаємося більше про цю реліквію, ми не можемо ризикувати й відновлювати її повністю.",
    },
    [63901] = {
        title = "Зосередження Ока",
        description = "Поєднання горя і люті, яке ти зібра$p(в:ла), достатнє для твоїх потреб. Найпевніше.\n\nЯкщо ти наполягаєш на тому, щоб довести цю нерозважливу справу до кінця, скористайся рогом на Кінцевій платформі, де Річка Душ тече вгору до Торгаста. Тамтешні енергії справді найпотужніші.\n\nПрисутність твоїх золотих союзників має привернути Око Тюремника. Сподіваюся лиш, що це не стане твоїм кінцем. Не люблю, коли вкладення йдуть намарно.",
        objectives = "Вирушай на Кінцеву платформу й скористайся Ілскагорном, щоб прикликати Гнів Одіна.",
        completion = "Пісні увічнять діяння цього дня, {NAME}.",
    },
    [63902] = {
        title = "Гарні новини, друзі!",
        description = "Ходімо, $p(друже:подруго). Покиньмо це огидне місце.\n\nТвої товариші, поза сумнівом, нетерпляче чекатимуть звістки про поразку Ока. Я віднесу тебе до них.\n\nДай знати, коли будеш готов$p(ий:а) вирушати, {name}.",
        objectives = "Лети з Данікою до Кортії, щоб сповістити Болвара.",
        progress = "Що трапилося?",
        completion = "Око переможено? І справді гарні новини.",
    },
    [63903] = {
        title = "Штурм Святилища",
        description = "Тюремник захопив сигіли всіх чотирьох ков'янтів. Цілком очевидно, що він має намір вирватися з Пащі й викрасти сигіл Вершительки з Орибоса.\n\nМи не можемо цього допустити.\n\nНа вершині Торгаста стоїть Святилище Панування, осідок могутності Тюремника. Настав час увійти до цього темного володіння.\n\nПоза сумнівом, силами, що спробують нас спинити, командуватиме Сильвана Віндраннер. Ми мусимо здолати її... і врятувати Андуїна Рінна з її лабет.\n\nЗбирай свої сили, {name}. Чорна Клинок стане поряд із тобою.",
        objectives = "Здолай Сильвану Віндраннер у Святилищі Панування.",
        progress = "Як точиться битва у Святилищі?",
        completion = "Тюремник здобув те, чого прагнув... та ще й Андуїна на додачу.\n\nНаша єдина перемога — якщо це можна так назвати — у тому, що Сильвана тепер під вартою.\n\nМолюся, щоб вона володіла знаннями, які дадуть нам перевагу й допоможуть спинити те, що Тюремник замислив далі.",
