    [63908] = {
        title = "Оплот божественного задуму",
        description = "<Твоє знайомство з Кодексом архіваріусів підтверджує, що це одна зі зниклих реліквій.\n\nАрхіваріус Ро-Суїр має місце для цього щита в Реліквіарії Спомину.>",
        objectives = "Віднеси Оплот божественного задуму Архіваріусу Ро-Суїру в Реліквіарій Спомину.",
        completion = "Цей щит походить із потойбіччя, яке ми неофіційно звемо Заїздом Вічності.\n\nКоли чийсь дух дістається Заїзду, він вішає зброю на стіну. Цей щит було навіки відкладено, коли його власник пішов до вічних гулянь біля вогнища. Було б не зовсім точно сказати, що щит просякнутий його почуттям обов'язку й самовідданістю... він і Є цими поняттями.\n\nЦікаво, чи можна було б скористатися цим щитом у полі. Результати таких випробувань були б захопливі. Може, колись...",
    },
    [63909] = {
        title = "Личина перевертня",
        description = "<Твоє знайомство з Кодексом архіваріусів робить очевидним, що це одна зі зниклих реліквій.\n\nАрхіваріус Ро-Суїр має місце для цієї маски в Реліквіарії Спомину.>",
        objectives = "Віднеси Личину перевертня Архіваріусу Ро-Суїру в Реліквіарій Спомину.",
        completion = "Оце так знахідка!\n\nЛичина перевертня здатна переконливо змінювати подобу свого носія, але має власну волю. Той, хто її вдягає, не може керувати ілюзією, і маска полюбляє ставити його в незручні чи небезпечні становища.",
