    [64171] = {
        title = "Чемпіонка: Кіараніка",
        objectives = "Дякую тобі, Ходоку Пащі. Знаю, мій послушник буде вдячний. Я хотіла б допомогти тобі у твоїй справі, якщо дозволиш.",
