    [64175] = {
        title = "Чемпіон: Лассік Хребтогин",
        objectives = "Твоїм товаришам потрібна допомога? Певен, я стану в пригоді.",
        completion = "Твоїм товаришам потрібна допомога? Певен, я стану в пригоді.",
    },
    [64194] = {
        title = "Воєнний прототип",
        description = "Я, Першоковаль, завжди прагну зробити щось краще!\n\nАле найбільші центуріони — вони надто великі, щоб тягти їх до Кортії. Це я виправив. Ось Атлеос, прототип польового колоса. Авангард кіріанців!\n\nЙого треба випробувати. Іще випробувати. Він має бути бездоганний проти потужного супротивника.\n\nІди, бери Атлеоса й здолай велику звірюку Пащі! Тисни на всі кнопки!",
        objectives = "Скористайся прототипом «Атлеос» у Вітровіяному гніздовищі, щоб здолати Краксіса.",
    },
    [64196] = {
        title = "Улюбленцям на поміч",
        description = "Схоже, якась зграя браконьєрів, що крадуть улюбленців, затіяла лихе в Оці Азшари. А маршрут польоту мого постачальника пролягає якраз над тим місцем!\n\nЗантіні та його улюбленці, Стрінгфеллоу і Спіді IV, везли назад рідкісного мурлока-улюбленця, а разом із ним — ще й інших улюбленців та припаси.\n\n{name}, будь ласка, відшукай Зантіні та його улюбленців. Допоможи їм. А тоді ми спробуємо повернути і вкрадених улюбленців, і припаси.",
        objectives = "Знайди Зантіні та його улюбленців на узбережжі Ока Азшари й допоможи їм.",
        completion = "Дякую за порятунок, друзяко. Стрінгфеллоу, Спіді IV і я — ми всі це цінуємо.",
    },
    [64202] = {
        title = "Дай-но руку",
        description = "Твоя сила, Ходоку Пащі... вона дорівнює навіть моїй до того, як Зоваал відділив мене від мого тіла.\n\nЦе лише мала частка мене цілого, та її більш ніж достатньо...\n\nДозволь мені допомогти тобі в боротьбі проти Зоваала. Так я звершу свою помсту.",
        objectives = "Прийми допомогу Нілґаніхмахта.",
        completion = "<П'ять перснів сяють і зливаються — їхня сила стікається в маленький перстень, що ідеально пасував би тобі на палець.>\n\n<Голос Нілґаніхмахта гримить у твоїй голові.> \n\nВирушаймо звідси й здолаймо Зоваала разом.",
    },
    [64203] = {
        title = "Узбережжя вільне",
        description = "Я завершував останній відтинок рейсу з припасами, коли нас збили! Вони забрали улюбленців, але припаси розкидало по всій цій смузі пляжу.\n\nНе знаю, що вони задумали, але знаю: ми мусимо повернути свої припаси. Ми з тобою — не з тихих... Зате Спіді IV... через нього всі ці пірати не позалазять у схованки. Він збере припаси, поки Стрінгфеллоу стежитиме за околицею з повітря.\n\nСпіді тебе любить, тож побалакай із ним — і спробуймо повернути припаси, що тліють, поки вони геть не згоріли.",
        objectives = "Збери припаси для улюбленців на берегах Ока Азшари разом зі Спіді IV.",
        progress = "Припасів завжди бракує.",
        completion = "Ми повернули припаси для улюбленців. Тепер треба повернути й самих улюбленців.",
    },
    [64210] = {
        title = "Скриня Незліченних Речей",
        description = "А, Ходоку Пащі, звісно. Скоро мене не стане, цей край забере мене назавжди. Але ти й далі ступатимеш його залами, незламн$p(ий:а)!\n\nМоєю великою мрією було перемогти за допомогою цієї скрині. На жаль, я переоцінив власні сили.\n\nСподіваюся, твоїх я не переоцінюю. Бери скриню. Доведи, що ти її гідн$p(ий:а).",
        objectives = "Принеси Скриню Незліченних Речей Різьбяру Рун.",
        progress = "А, ти знову тут.",
        completion = "А... цікавий пристрій. Закріпити його в цьому місці буде вельми корисно.",
    },
    [64211] = {
        title = "Двері в темряву",
        description = "Боюся, нашим спробам зупинити Зоваала завадили, смертний.\n\nХтось відчинив двері до забороненого світу... і Вигнанець повернув собі силу, відібрану в нього давним-давно.\n\nЯ відчуваю, що твої союзники повертаються із Святилища Панування. Я мушу знати кожну подробицю того, що там сталося.",
        objectives = "Поговори з Джайною та стань свідком завершення битви в Торгасті.",
        completion = "<Джайна сумна, але сповнена рішучості.>\n\nУ нас ще є надія.",
    },
    [64212] = {
        title = "Двері в темряву",
        description = "Боюся, нашим спробам зупинити Зоваала завадили, смертний.\n\nХтось відчинив двері до забороненого світу... і Вигнанець повернув собі силу, відібрану в нього давним-давно.\n\nЯ відчуваю, що твої союзники повертаються із Святилища Панування. Я мушу знати кожну подробицю того, що там сталося.",
        objectives = "Поговори з Траллом та стань свідком завершення битви в Торгасті.",
        completion = "<Чоло Тралла спохмурніло.>\n\nМи не можемо дозволити Тюремнику перемогти.",
    },
    [64213] = {
        title = "Символ надії",
        description = "Перш ніж рушити за Тюремником крізь портал, Андуїн дещо впустив.\n\nНе думаю, що це входило в плани Тюремника. Це має бути знак, що душа Андуїна досі належить йому самому!\n\n<Джайна розкриває долоню й показує тобі золотий компас.>\n\nЦя річ була дуже дорога Андуїнові. Я відчуваю в ній його присутність.\n\nНам треба з'ясувати, чому він лишив її для нас.",
        objectives = "Допоможи Джайні дослідити компас Андуїна.",
        progress = "Якщо Андуїн зумів залишити це для нас, то якась частина його єства досі вільна від панування Тюремника...",
        completion = "<З очей Джайни котяться сльози.>\n\nМи не можемо його втратити, {NAME}. Хоч би чого це коштувало.",
    },
    [64214] = {
        title = "Символ надії",
        description = "Перш ніж рушити за Тюремником крізь портал, Андуїн дещо впустив.\n\nЯ не певен, що це було, але Джайна підняла цю річ. Можливо, це знак, що Андуїн досі чинить опір Тюремникові!\n\nНам треба з'ясувати, що це за річ і чому юний король лишив її для нас.",
        objectives = "Допоможи дослідити компас Андуїна.",
        progress = "Чому Андуїн залишив це для нас?",
        completion = "Андуїн Рінн не заслуговує на таку долю.\n\nМи мусимо боротися за його порятунок, {NAME}!",
    },
    [64215] = {
        title = "Лапатий патруль",
        description = "Поки Спіді IV збирав припаси, Стрінгфеллоу розвідував решту Ока Азшари.\n\nВиявляється, на заході аж кишить піратами. Певно, саме там і тримають улюбленців.\n\nВирушай туди й визволь їх.",
        objectives = "Здобудь ключі в піратів Фіолетових Вітрил на західному узбережжі Ока Азшари. Тоді звільни впійманих улюбленців.",
        progress = "Тобі вдалося їх знайти, {NAME}?",
        completion = "Чудова робота з визволенням улюбленців, {NAME}. \n\nАле Ґурґла й досі не видно.",
    },
    [64216] = {
        title = "Знання вежі",
        description = "Зіткану силу цієї скрині можна вивільнити, лише живлячи її гордістю та спогадами. У її плетиві приховані заклинання, які мені траплялося бачити в інших світах — ними висмоктують або підкоряють душу. Ця... мерзота... використала ці знаряддя спокути й честі, щоб створити замок.\n\nКоли ти долатимеш поверхи Торгаста, твоя вправність, швидкість та ефективність — усе це примножуватиме Знання вежі, яким живиться ця скриня.\n\nНагодуй її, щоб дістати сховані в ній сили.",
        objectives = "Розмісти Скриню Незліченних Речей у Торгасті.",
        progress = "<Скриня Незліченних Речей гуде від сили.>",
        completion = "<Скриня зголодніла: вона сягає у твої спогади про Торгаст у пошуках минулих звершень, якими можна поживитися.>",
    },
    [64218] = {
        title = "Загроза близька й далека",
        description = "Наразі ми зробили щодо Тюремника все, що могли, $p(друже мій:подруго моя).\n\nІнші справи потребують нашої уваги. Як-от розломи пожирачів, які нещодавно на моїх очах відкривалися на сході!\n\nЯкщо ми їх не спинимо, ці звірі влаштують тут справжній хаос.\n\nДопоможеш мені впоратися з ними, {name}?",
        objectives = "Досліди Поля Генезису.",
        completion = "Хтось усередині потребує нашої допомоги!",
    },
    [64219] = {
        title = "Таємничий голос",
        description = "Стільки руйнувань. Пожирачі ненаситні.\n\nСподіваюся, істота, яку ми чули, не тяжко поранена.\n\nЗвичайним способом ці двері не відчинити. Можливо, разом ми зможемо прокласти собі шлях силою!\n\nХай хто там по той бік — він потребує нашої допомоги.",
        objectives = "Увійди до Колиски Зародження.",
        progress = "Ми мусимо допомогти тому, хто там ув'язнений!",
        completion = "Ми спізнилися... але не можна втрачати надію.",
    },
    [64223] = {
        title = "Суть справи",
        description = "Вона впала, але, здається, ще жива. Має бути щось, чим ми можемо їй зарадити.\n\nПогляньмо, чи знають щось Просвітлені. Я знайду спосіб її переправити й зустріну тебе в Прихистку.",
        objectives = "Поговори зі Старійшиною Кретом у Прихистку.",
        progress = "Сподіваймося, що ще не запізно.",
        completion = "Це нам не зарадило...",
    },
    [64224] = {
        title = "У пошуках невідомого",
        description = "Якщо Старійшини нам не допоможуть, треба знайти когось, хто допоможе.\n\nТой інший Просвітлений, Фірім... його куди більше цікавили автома.\n\nВін казав, що віддалився від своїх родичів. Хтось у Прихистку має щось про нього знати.\n\nПошукай у таборі підказок про те, де перебуває Фірім. А я знову спробую переконати Старійшин заговорити.",
        objectives = "Обшукай Прихисток у пошуках відомостей про Фіріма.",
        progress = "Тобі вдалося щось знайти?",
        completion = "Старійшини відмовляються казати бодай щось про Фіріма.\n\nСподіваюся, тобі вдалося щось дізнатися.",
    },
    [64225] = {
        title = "Знайти Фіріма",
        description = "Ти щось знайш$p(ов:ла)? Оце пощастило! Дозволиш мені поглянути на листа?\n\nОтже, Просвітлений на ім'я Ксеввет почув, що Фіріма востаннє бачили на захід від Кузні Загробних Світів, і вирушив його розшукувати.\n\nЗвідти й нам слід почати пошуки.",
        objectives = "Знайди Фіріма.",
        completion = "Цим убивцям потрібне не лише моє життя. Вони хочуть викрасти мої дослідження! Я не можу цього допустити.",
    },
    [64226] = {
        title = "Заходи безпеки",
        description = "Схоже, приховані пастки, які я розставив довкола гроту, не такі дієві, як мені хотілося б, зважаючи на твою присутність у моєму домі.\n\nПроте вони й досі корисні, бо відваджують більшість небажаної уваги.\n\nОскільки ти так люб'язно прив$p(ів:ела) до мене вбивць, я не можу наставити пастки наново сам.\n\nТож тобі доведеться зробити це за мене. Я лишуся тут, щоб охороняти й себе, і свої дорогоцінні дослідження. Скористайся цим Сенсорним синхронізатором, який я поставив неподалік, — він покаже тобі, які пастки треба наставити наново.",
        objectives = "Скористайся Сенсорним синхронізатором, а тоді настав наново 10 спрацьованих пасток біля Закутка Вигнанця.",
        completion = "Добре. Це на якийсь час заслонить нас від чужих очей.",
    },
    [64227] = {
        title = "Невидимі агенти",
        description = "Відколи ти відкри$p(в:ла) шлях з Орибоса, певні картелі скористалися нагодою, щоб узятися за мене й мою роботу в доволі... смертоносний спосіб. Вони знають, наскільки важливі мої дослідження для всього.\n\nНові вбивці напевно не забаряться, адже ти прокла$p(в:ла) чітку стежку просто до мене!\n\nЯ не впораюся з усіма сам. Ти маєш це виправити й допомогти захистити мої таємниці.\n\nРозберися з ними замість мене.",
        objectives = "Перебий убивць біля Закутка Вигнанця.",
        completion = "Що ж, користь від тебе таки є. Дякую.",
    },
    [64228] = {
        title = "Тепер можна й поговорити",
        description = "Ти й справді прив$p(ів:ела) мені оракула! Та ще й цілого!\n\nЯ ніколи не чув, щоб ці божественні створіння розмовляли з кимось, окрім автома. Вона могла б розповісти нам стільки про Зерет Мортіс.\n\nТи маєш розповісти мені все!",
        objectives = "Поговори з Фірімом про оракула.",
        progress = "Розкажи мені, що сталося...",
        completion = "Неймовірно!",
    },
    [64230] = {
        title = "Шифри Перших",
        description = "Шлях ще не зовсім ясний, але перші кроки вже зроблено.\n\nСхоже, божественний конструкт вподобав тебе більше, ніж мене.\n\nТепер, коли він дав тобі початкове розуміння, поглянь, що ще він забажає тобі показати.\n\nГадаю, результати нас просвітлять.",
        objectives = "Досліди Консоль шифру.",
        progress = "Тебе благословлено.",
        completion = "Невже ти не відчуваєш, як здобуті знання струмують крізь тебе?!\n\nПодумати лишень: саме ти відкриєш таємниці Зерет Мортіса...\n\nЯ пильно за тобою спостерігатиму.",
    },
    [64237] = {
        title = "Ґурґл і бандит",
        description = "Ми повернули всіх улюбленців, окрім Ґурґла. {name}, треба доправити цього улюбленця назад до Бреанні.\n\nСтрінгфеллоу помітив закуток, де, як ми гадаємо, засів ватажок цих браконьєрів-крадіїв улюбленців.\n\nХодімо по нього!",
        objectives = "Знайди ватажка браконьєрів-крадіїв улюбленців і зітнися з ним у бою.",
        completion = "З поверненням, {NAME}! Та ще й із нашими припасами, улюбленцями і Ґурґлом!!\n\nСхоже, Ґурґл не хоче відходити від тебе ні на крок.\n\nВін пережив доволі скрутних часів, і я не збираюся розбивати його маленьке серденько.\n\nПіклуйся про мого друга, {NAME}.\n\nПіклуйся про $p(мого друга:мою подругу), Ґурґле.",
    },
    [64240] = {
        title = "Політ кіріанів",
        description = "Ми зав'язали запеклий бій біля входу до Сховища Таємниць! Нашим військам не завадило б підкріплення.\n\nПрошу, поведи моїх побратимів Піднесених, щоб підтримати наших бійців там.\n\nБійці на землі впораються із зачисткою, але їм потрібні щити й зцілення.\n\nЩасти тобі!",
        objectives = "Підтримай сили ковенантів з повітря біля Сховища Таємниць.",
        progress = "Тобі вдалося допомогти нашим силам біля Сховища Таємниць?",
        completion = "Не завжди треба вражати силою з небес! Часом трохи додаткового зцілення — найкраща тактика.\n\nДякую тобі, $p(друже:подруго).",
    },
    [64253] = {
        title = "Завдання Ревендрету завершено",
    },
    [64255] = {
        title = "Час святкувати",
        description = "О, чудово, схоже на капелюх Темеля!",
        progress = "О, класно, схоже на капелюх Темеля!\nРожевий Святковий Ковпак (1)",
        completion = "<Твій дворецький розпливається в усмішці від вуха до вуха, забираючи святковий ковпак.>",
    },
    [64267] = {
        title = "Загадкові дарунки від Ве'нарі",
        description = "Мене вражає твоя чиста впертість — виживати й водночас приносити бодай якусь користь, Ходоку Пащі. Ти нагадуєш мені мене саму — значно молодшу й наївну. \n\nВізьми це й продовжуй свою роботу... десь у менш примітному місці.",
        objectives = "Поговори з Ве'нарі в Прихистку Ве'нарі в Пащі.",
        completion = "Мене вражає твоя щира затятість: виживати, та ще й приносити сяку-таку користь, Ходок Пащі. Ти нагадуєш мені мене саму — набагато молодшу й наївну.\n\nВізьми це й продовжуй свою справу... десь у менш помітному місці.",
    },
    [64271] = {
        title = "Більш цивілізований спосіб",
        description = "А, {name}.\n\nМені треба дещо з тобою обговорити. Але не тут.\n\n<Наджія підозріливо оглядає інших мешканців Притулку Хранителя.>\n\nЗустрінься зі мною там, де дорога входить до Кортії з Пащі, і я все поясню.",
        objectives = "Зустрінься з Наджією біля дороги, що веде до Кортії.",
        completion = "Твоїй техніці ще є куди рости. Дякую, що серед нашої нескінченної кампанії знайшлася хвилина для двобою. Ми мусимо пам'ятати: навіть у часи великої боротьби треба робити те, що дарує нам радість.",
    },
    [64273] = {
        title = "Стримати Гелзворнів",
    },
    [64274] = {
        title = "Завдання відстеження",
    },
    [64282] = {
        title = "Сповнений несподіванок",
        description = "Ти не перестаєш мене дивувати, Ходоку Пащі, твоя присутність тут геть несподівана!\n\nРаз ми обидва тут, гадаю, нам варто об'єднати зусилля.\n\nУ Тюремника є сховок, повний коштовностей, десь у цьому розломі. Знайди його для мене або принеси сюди, щоб ми його відкрили, і ми поділимо багатство порівну!",
        objectives = "Знайди сховок Зоваала.",
        progress = "Тобі вдалося знайти сховок?",
        completion = "Оце так прибуткове партнерство. Не сумніваюся, картель Ве буде вельми незадоволений нашим успіхом.",
    },
    [64286] = {
        title = "Взірець Поступу Смерті",
        description = "На заклик знову відгукнулися. Твої зусилля не лишаться непоміченими.\n\nПогляньмо, чи не знайдемо ми гідної нагороди за твою працю.",
        objectives = "Поговори з герцогинею Мінкс у Притулку Хранителя в Кортії.",
    },
    [64287] = {
        title = "Взірець Кодексу Архіваріусів",
        description = "Ти доклав чимало зусиль, щоб відновити те, що нам найдорожче, Ходоку Пащі.\n\nЗустрінься зі мною в моїй залі, коли будеш готовий. Нам треба обговорити одну останню справу.",
        objectives = "Поговори з Архіваріусом Ро-Суїром у Реліквіарії спогадів у Кортії.",
    },
    [64288] = {
        title = "Взірець Ве'нарі",
        description = "Ходи, Ходоку Пащі. Зустрінься зі мною в моєму прихистку.\n\nНам треба обговорити одну останню справу.\n\n...і подбай про те, щоб за тобою не стежили.",
        objectives = "Поговори з Ве'нарі в Прихистку Ве'нарі в Пащі.",
    },
    [64289] = {
        title = "Збираючи уламки",
        description = "Багато що було втрачено, коли Кортію затягнуло в Пащу.\n\nБезцінні реліквії розірвало на шматки. Я бачив істот, що носять рештки цих речей.\n\nЇх треба повернути.\n\nСтань проти сил Тюремника й обшукай те, що лишилося від Кортії, у пошуках цих уламків нашого колись славетного сховища.",
        objectives = "Здобудь 50 уламків реліквій із рідкісних істот і скарбів по всій Кортії.",
        completion = "Вони чудово згодяться. Я багато чого зможу зробити, щоб їх покращити.",
    },
    [64290] = {
        title = "Збираємо дослідження",
        description = "Ти добре попрацював, зібравши ці фрагменти. Вони неабияк допоможуть нам відновити архіви.\n\nЗа допомогою того, що ти знайш$p(ов:ла), я зможу зібрати більше даних про те, що було втрачено в Кортії.\n\nА далі тобі належить відшукати в Кортії ще більше фрагментів і реліквій, щоб поповнити наші архіви.",
        objectives = "Поговори з Архіваріусом Ро-Суїром, щоб обміняти кортіанські реліквії на каталогізовані дослідження.",
        progress = "Ми вдячні тобі за допомогу, Ходаче Пащі.",
        completion = "Це чудово згодиться. Що більше досліджень, то кращим ставатиме реліквіарій.",
    },
    [64292] = {
        title = "Мейлі, Мандрівниця",
        description = "Я не знаю, як тобі дякувати за те, що ти знайш$p(ов:ла) Мейлі! Знаєш, гадаю, вона трохи завелика клопітниця для мене.\n\nЧи не міг би ти наглянути за нею? Здається, ти їй дуже припав до душі!",
        objectives = "Візьми Мейлі під свою опіку.",
        completion = "Піклуйся про Мейлі, Ходаче Пащі.",
    },
    [64306] = {
        title = "Умова завершення завдання",
    },
    [64314] = {
        title = "Оновлені ковенанти",
        description = "Усі наші зусилля були спрямовані на те, щоб не дати Тюремнику зруйнувати бар'єр навколо Пащі й вдертися в решту Тіньокраю.\n\nНатомість він розширив саму Пащу, щоб поглинути Орибос і захопити сигіл Арбітра.\n\nЯ не до кінця розумію те, що ми бачили на вершині Торгаста. Але Прим точно розуміє.\n\nЧас втілити його запасний план. Невдовзі прибудуть ковенанти зі своїми сигілами.\n\nПовідом Прима, що ми готові почати.",
        objectives = "Поговори з Примом, а тоді забери сигіли в кожного ковенанту.",
        completion = "Чудово, смертний. Твою частину виконано.\n\nТепер починається моя робота.",
    },
    [64322] = {
        title = "Ветеран Нічних фей",
        description = "Арденвельд давно не був у такій безпеці — і це завдяки тобі.\n\nТвої звершення не лишилися непоміченими навіть за межами Арденвельда.\n\nРозповіді про твої перемоги лунають залами Орибоса. Зо'сорг, Володар Конфлікту, просить про зустріч із тобою в Анклаві.\n\nВін жваво цікавиться воєнним мистецтвом. Раджу не змушувати його чекати.",
        objectives = "Зустрінься із Зо'соргом в Анклаві в Орибосі.",
        completion = "А, {NAME}. Я чув чимало розповідей про твою звитягу на полі бою. \n\nУ моїх інтересах, щоб такі видатні бійці, як ти, були добре споряджені. Зо'даш уповноважений і далі вдосконалювати твої обладунки та зброю.",
    },
    [64323] = {
        title = "Ветеран Кіріанів",
        description = "Бастіон зцілюється завдяки тобі, {name}. Шлях вільний.\n\nТвої звершення не лишилися непоміченими, навіть за межами Бастіону.\n\nРозповіді про твої перемоги лунають у залах Орибоса. Зо'сорг, Володар Конфлікту, просить про зустріч із тобою в Анклаві.\n\nВін жваво цікавиться воєнним мистецтвом. Раджу не змушувати його чекати.",
        objectives = "Зустрінься із Зо'соргом в Анклаві в Орибосі.",
        completion = "А, {NAME}. Я чув чимало розповідей про твою звитягу на полі бою. \n\nУ моїх інтересах, щоб такі видатні бійці, як ти, були добре споряджені. Зо'даш уповноважений і далі вдосконалювати твої обладунки та зброю.",
    },
    [64324] = {
        title = "Ветеран Некролордів",
        description = "Могутність Некролордів зростає завдяки тобі, {name}.\n\nТвої звершення не лишилися непоміченими, навіть за межами Малдраксуса.\n\nРозповіді про твої перемоги лунають у залах Орибоса. Зо'сорг, Володар Конфлікту, просить про зустріч із тобою в Анклаві.\n\nВін жваво цікавиться воєнним мистецтвом. Раджу не змушувати його чекати.",
        objectives = "Зустрінься із Зо'соргом в Анклаві в Орибосі.",
        completion = "А, {NAME}. Я чув чимало розповідей про твою звитягу на полі бою. \n\nУ моїх інтересах, щоб такі видатні бійці, як ти, були добре споряджені. Зо'даш уповноважений і далі вдосконалювати твої обладунки та зброю.",
    },
    [64325] = {
        title = "Ветеран Гріхопаду",
        description = "Вплив Гріхопаду зростає завдяки твоїм звитягам, {name}!\n\nТвої звершення не лишилися непоміченими, навіть за межами Ревендрету.\n\nРозповіді про твої перемоги лунають у залах Орибоса. Зо'сорг, Володар Конфлікту, просить про зустріч із тобою в Анклаві.\n\nВін жваво цікавиться воєнним мистецтвом. Раджу не змушувати його чекати.",
        objectives = "Зустрінься із Зо'соргом в Анклаві в Орибосі.",
