    [64438] = {
        title = "Підсилення спорядження",
        description = "Дослідження, які ти знаходиш, можуть відкрити чимало можливостей.\n\nОдна з них — покращення спорядження, яке ти можеш знайти в Кортії.\n\nПоговори з моїм помічником поблизу. Він зможе скористатися нашими дослідженнями, щоб повернути цьому спорядженню колишню силу.",
        objectives = "Поговори з помічником-ученим Ка-Везом, щоб покращити одну річ спорядження з Кортії.",
        progress = "Я зроблю все, що зможу, аби допомогти тобі, Ходаче Пащі.",
        completion = "Це найменше, чим ми можемо підтримати твої зусилля, Ходаче Пащі.",
    },
    [64441] = {
        title = "Загублена сторінка",
        description = "<Схоже, книгу нещодавно скинули зі столу в найближчому таборі вентирів.\n\nВентири, мабуть, будуть вдячні, якщо ти повернеш її, перш ніж котрийсь із громитів використає її як підстилку для гнізда.>",
        objectives = "Підбери книгу, щоб повернути її.",
        completion = "<Схоже, ви з Мал'Ґанісом ще не поквиталися одне з одним. Немає сумніву: коли ти нарешті зійдешся з Тюремником віч-на-віч, цей жахолорд теж буде там.>",
    },
    [64458] = {
        title = "Шукачка пригод: Суланум",
        completion = "Твоя відданість Арденвельду поза сумнівом, {NAME}.\n\nСуланум особливо вразив твій незламний дух — настільки, що вона захотіла долучитися до нашої боротьби тут.\n\nСкористаймося ж її послугами якнайкраще!",
    },
    [64459] = {
        title = "Шукачка пригод: Елвін",
        completion = "Ліс благословляє нас, {NAME}. Твоя турбота про добробут Арденвельду не лишилася непоміченою.\n\nШановна Елвін погодилася долучитися до нашої боротьби.\n\nРазом ми захистимо цей край.",
    },
    [64460] = {
        title = "Шукачка пригод: Янлар",
        completion = "{NAME}, за плечима в тебе чимало звитяжних битв за Арденвельд.\n\nЯнлар билася поруч із тобою в багатьох боях по всьому Тіньокраю, і твоя доблесть незмінно її вражала.\n\nМені приємно повідомити, що вона попросилася назавжди битися пліч-о-пліч із тобою.",
    },
    [64461] = {
        title = "Шукач пригод: Гермест",
        completion = "Твоя віра в Бастіон надихає, {NAME}.\n\nГермест бачив твою невтомну відданість нашій справі.\n\nВона надихнула його долучитися до нас у новій ролі тут, у Твердині, щоб іще більше прислужитися загальним потребам Тіньокраю.",
    },
    [64462] = {
        title = "Шукач пригод: Кромас Містик",
        completion = "Вітаю, смертний друже! Маю добрі вісті.\n\nКромас Містик уже давно з великою цікавістю стежить за твоїми успіхами в кіріанів.\n\nТепер він бажає приєднатися до тебе й віддати свою відвагу та вміння нашій справі.",
    },
    [64463] = {
        title = "Шукачка пригод: Аурична духовідниця",
        completion = "Схоже, у нас нове поповнення, {NAME}.\n\nМаю честь повідомити, що Аурична духовідниця вирішила віддати свою мудрість і вміння нашій справі.\n\nЗ неї буде чудова союзниця!",
    },
    [64464] = {
        title = "Шукачка пригод: Ліра Градобуря",
        completion = "Сьогодні в нас захоплива новина, {NAME}!\n\nЛіра Градобуря хоче стати до наших лав тут, біля Престолу Примуса! Її досвід буде дуже доречним.\n\nА тепер ідіть і бийтеся разом на благо Малдраксуса!",
    },
    [64465] = {
        title = "Шукач пригод: Енцелад",
        completion = "Твоя відданість надихає, {NAME}.\n\nЕнцелад під великим враженням від тебе: лагодячи твою зброю, він переконався, що перед ним справжній воїн.\n\nМета ясна — бийся за Малдраксус!",
    },
    [64466] = {
        title = "Шукач пригод: Смертоклик",
        completion = "Сьогодні в нас чудові новини, {NAME}.\n\nБаронеса Драка вшанувала нас особливою честю — зарахувати Смертоклика до нас на службу.\n\nІз допомогою цього лютого звіра Малдраксус переможе!",
