    [64641] = {
        title = "Загадкова зелень",
        description = "З того місця нагорі струменіє яскрава сила. Мене тягне до неї, мов метелика на світло!\n\nХочу глянути, що ж це таке. Складеш мені компанію, будь ласка? Буде так весело!",
        objectives = "Відвідай Неприборкану Зелень із Ґліммеркейном.",
        completion = "Ми — Коло Ко з народу джиро.\n\nМи тут, щоб полагодити цю землю.",
    },
    [64642] = {
        title = "Розчищення руїн",
        description = "Це місце надто довго стояло покинутим. Рослинність поглинула всю землю.\n\nЩоб це виправити, нам треба потрапити до Квітучої Ливарні.\n\nА доти — розчисть територію. Прибери покручів, що спотворилися з плином часу.",
        objectives = "Убий 15 істот у Неприборканій Зелені.",
        completion = "Це добрий початок.",
    },
    [64643] = {
        title = "Рішення з брухту",
        description = "Квітуча Ливарня створила цю місцину. Вона підтримує автома, істот і рослини.\n\nЦе через неї все так заросло.\n\nЩоб привести цю землю до ладу, нам треба потрапити до Ливарні. Цей конструктор зможе пробитися крізь перепони, коли запрацює.\n\nБагато автома в цій місцині давно завмерли без руху. Знайди в їхніх нутрощах придатні деталі.",
        objectives = "Добудь 8 Нутрощів Автоми з покинутих автома в Неприборканій Зелені.",
        progress = "З твоєю допомогою ми повернемо цьому місцю його велич.",
