    [64706] = {
        title = "Питання мотивації",
        description = "Ці піски всіяні велетнями, смертний. Але я вірю, що ми можемо їх оживити.\n\nДля цього стануть у пригоді дрібніші автома, що ховаються в пустелі. Скористайся моїм мотиватором, щоб згуртувати їх задля нашої справи. Якщо назбираємо достатньо, їхня енергія наповнить цих повалених бегемотів і зміцнить наші сили.\n\nПриведи до мене якомога більше їх, і ми приставимо їх до роботи!",
        objectives = "Приведи Фіріму 6 вмотивованих автома.",
        progress = "Чи вдалося їх належно вмотивувати?",
        completion = "Чудова робота, смертний! Скоро ми побачимо плоди твоїх зусиль.",
    },
    [64710] = {
        title = "Шепітливий кристал пекельного вогню",
        description = "Кристал пульсує моторошним зеленим сяйвом пекельного вогню. Тримаючи його, ти чуєш ледь вловиме відлуння гортанних демонічних голосів. Хоч слова й плутані, одне з них можна розібрати, і воно повторюється часто: Даларан. \n\nМожливо, хтось у місті, що ширяє над Розбитими островами, розповість тобі більше про цей кристал та його призначення.",
        objectives = "Принеси Шепітливий кристал пекельного вогню Арідормі в Даларан, що ширяє над Розбитими островами.",
    },
    [64713] = {
        title = "Збираємо уламки... буквально",
        description = "Сфери допомагають нам готувати ґрунт для Кузні. Магія всередині сфер вабить пожирачів. Вони роздирають метал, щоб дістатися до неї. Ми мусимо зібрати рештки.\n\nШукай уламки навколо сфер. Принеси їх нам.",
        objectives = "Збери 30 Уламків Сфер.",
        progress = "Уламки знайдено? Нам потрібно багато шматків.",
        completion = "Вистачить, щоб полагодити невелику сферу. Цього досить.",
    },
    [64717] = {
        title = "Матерія творіння",
        description = "Великі металеві сфери, що всіяли краєвиди Зерет-Мортіса, — це відпрацьовані кузні, відкинуті під час процесу творіння.\n\nСфери поблизу Кузні Загробних Світів містять сліди матеріалів, унікальних для цього місця.\n\nЯ перелаштував свій кузняний відвід, щоб збирати ці матеріали. Застосовуй його поблизу кузень, які я позначив. Найбільший шанс знайти рідкісні ейдолічні фрагменти — на найбільших Кузнях Прабатьків.",
        objectives = "Збери 10 Ейдолічних Фрагментів та 300 Малих Енігметів.",
        progress = "Чи зібрано все, що нам потрібно?",
        completion = "Я негайно пущу їх у діло. Вони допоможуть Сезурі й автома опиратися дії магії Панування.",
    },
    [64718] = {
        title = "Ключі до перемоги",
        description = "Пісня... незавершена. Потрібна гармонія. Знайди тих, хто провидить. Пошли їх служити циклу.\n\nПрислужники Пащі тримають ключі, що сковують. Забери ключі, звільни їх.",
        objectives = "Звільни 6 автома-провидців із їхніх камер.",
        completion = "Хор збирається. Скоро наші голоси зіллються.",
    },
    [64720] = {
        title = "Прокладаємо шлях",
        description = "Ходоку Пащі! Мої розвідники доповідають, що прислужники Пащі підкорили двох автома-оракулів, щоб ті допомагали їм у бою. Ці оракули неодмінно передбачать нашу стратегію й нашу кінцеву мету, якщо дати їм нагоду.\n\nМи мусимо знищити обох оракулів, перш ніж увійти до Крипт. Коли їх не стане, війська прислужників Пащі не знатимуть, що ми робимо, доки ми не завершимо.\n\nВізьми Емені з собою. Вона прагне бою.",
        objectives = "Убий оракула Зокета та оракула Вораксі.",
        completion = "Виконано бездоганно, {NAME}. Втрата цих оракулів має лишити прислужників Пащі в цілковитому невіданні.",
    },
    [64722] = {
        title = "Стукаємо у двері смерті",
        description = "Ось і все, смертний. Сил, які ти зібра$p(в:ла), має вистачити, щоб прорватися крізь прислужників Пащі й дістатися Крипт. Утім, потрапити всередину буде складніше. Прислужники Пащі забарикадували вхід.\n\nКбато понесе тебе в бій. Знищ прислужників Пащі й зруйнуй пристрої, що живлять бар'єр.",
        objectives = "Верхи на Кбато здолай сили прислужників Пащі в Безкраїх Пісках і відкрий шлях до Крипт Вічних.",
        completion = "Клянуся Першими... Я й не мріяв, що побачу це місце на власні очі.",
    },
    [64723] = {
        title = "Проєкт відбудови",
        description = "Без Арбітра саме призначення Тіньокраю опинилося під загрозою. Душі ринуть до Пащі без жодного напрямку.\n\nЯк зауважила Сезура, за звичайних обставин Зерет Мортіс створив би нову істоту, що посіла б місце Арбітра. Підозрюю, що сили Тюремника так понівечили цю землю, що це більше неможливо.\n\nЧас діяти самим і повернути Тіньокраю стабільність! Поговори із Сезурою і з'ясуй, з чого нам почати.",
        objectives = "Поговори із Сезурою.",
        progress = "Чи вдалося з ними поговорити?",
        completion = "Ковенанти неодмінно надішлють допомогу, якщо ми попросимо.",
    },
    [64725] = {
        title = "Непрощенне вторгнення",
        description = "Темрява сіє розлад у цих залах. Прислужники Пащі висмоктують життя з повітря, а навзамін дають лише страждання. Цьому не бути.\n\nЩоб відновити пісню, потрібна тиша. Прислужників Пащі треба знищити.",
        objectives = "Знищ 6 підкорених автома та 3 осквернителів-темновидців.",
        progress = "Коли зали замовкнуть, зможемо продовжити.",
        completion = "Золота година тиші. Простір, де може початися творіння.",
    },
    [64726] = {
        title = "Лад речей",
        description = "Есенції прадавніх душ, спотворені, сочаться з кожної кімнати. Зали треба відновити, а потік душ — спрямувати в інше річище.\n\nКлюч — у сферах. Запечатай проломи, віднови потік, і тоді посудину можна буде наповнити.",
        objectives = "Скористайся $13oa Сферами Стримування, щоб запечатати проломи.",
        progress = "Запечатай пролом, віднови потік.",
        completion = "Затамований подих — передчуття. Скоро душа зіллється, і пісня творіння почнеться.",
    },
    [64727] = {
        title = "Нескінченне коло",
        description = "Творіння кличе — чуєш його? Та внизу причаїлася темрява й опоганює прадавню мелодію.\n\nЩоб творити наново, потрібно повернути мир. Ходок мусить іти і захищати.\n\nЗробити треба чимало. Веди.",
        objectives = "Проведи Сезуру до центру Крипт Вічних.",
        completion = "Наші голоси приглушені в темряві, що не відступає.",
    },
    [64728] = {
        title = "Забуті знайомі",
        description = "Час настав. Пісня принесе нове життя. Скажи мені, коли будеш готов$p(ий:а) почати.",
        objectives = "Заверши ритуал.",
        progress = "Ритуал має бути завершено.",
        completion = "Дисонанс не вщухає. Потрібен чистий тон. Розпочни цикл наново.",
    },
    [64729] = {
        title = "Життя, про які варто подумати",
        description = "Цю пісню завершено, і гармонію відновлено. Та Зерет Мортіс досі мучить розбрат.\n\nЗа цими стінами все ще лишається розлад. Ми мусимо піти, перш ніж він нас відшукає.\n\nПоговори з тим, кого ти звеш Фірімом, — він відкриє нам шлях.",
        objectives = "Повернися до Лощини Вигнанця.",
        completion = "Аж не віриться, скільки ми звершили... воістину, цей день вартий пам'яті. Ми не досягли б цього без тебе, $p(друже:подруго).",
    },
    [64730] = {
        title = "Переломний момент",
        description = "Пауза, позбавлена подиху. Мелодія ще лунає. Цикл чекає на голос.\n\n<Ти не пев$p(ен:на), що саме має на увазі Сезура. Можливо, варто спробувати влаштувати ритуал знову, почавши з Посудини й провидців.>",
        objectives = "Оглянь Посудину та автома-провидців.",
        progress = "Чи все випробувано?",
        completion = "Не хочеться цього казати, але... схоже, ми зазнали невдачі, $p(друже:подруго).",
    },
    [64731] = {
        title = "За кожну душу",
        description = "Без Арбітра, який стримував би потік душ до Пащі, Тіньокрай ніколи не зцілити повністю.\n\nЦе не може бути кінцем. Ти ж напевно щось придумаєш?",
        objectives = "Знайди спосіб створити нового Арбітра.",
        progress = "Ця мить має величезну вагу.",
        completion = "Новий голос долучився до хору — цикл невпинно триває далі.",
    },
    [64733] = {
        title = "Допомога здалеку",
        description = "Якщо ми хочемо мати бодай якийсь шанс прорватися крізь сили прислужників Пащі, нам знадобиться допомога всіх ковенантів.\n\nЯ поговорю з кіріанами. Ти й Пелагос можете поговорити з рештою. Але перш ніж піти, спитай Фіріма, чи є якийсь спосіб заручитися також підтримкою Просвітлених.",
        objectives = "Поговори з представниками Просвітлених, вентирів, некролордів та нічних фей.",
        completion = "Із силою військ ковенантів та допомогою автома ми зможемо дістатися Крипт!",
    },
    [64739] = {
        title = "Хватка Зоваала",
        description = "Я пам'ятаю цей метал. Я бачила його, коли мене торкнулася магія Пащі. Коли мене відсікли...\n\nЯ покажу тобі, де це сталося. Іди за мною. Дорогою розповім тобі свою історію.",
        objectives = "Іди за Ганоа Вигнанницею та вислухай її історію.",
        completion = "Усе гірше, ніж я думала. Набагато гірше.",
    },
    [64741] = {
        title = "Перевірка безпеки",
        description = "Не розумію — це ж мої побратими! Як можна бути такими безтурботними, коли до самого порога підступають і захланні картелі, і Пащеприсяжні?\n\nЇхня захисна технологія застаріла — небезпеки вона не спинить. Якщо вже я не можу вмовити їх піти, то принаймні подбаю, щоб там, де вони так уперто лишаються, було безпечно.\n\nЯ не хочу знову втратити друзів.\n\nУздовж краю щита сховано чотири провідники. Візьми цей набір — з ним ти зможеш оглянути їх і, як буде треба, полагодити.",
        objectives = "Перевір провідники щита довкола Прихистку.",
        progress = "Якщо ці провідники вийдуть з ладу, доведеться будувати нові. Цього не хоче ніхто.",
        completion = "Я так і знав! Захист Прихистку зумисне пошкоджено — і це зробив картель Ксай!",
    },
    [64742] = {
        title = "Сліди втручання",
        description = "Отже, щит саботували. Ну звісно, безжальний картель Ксай першим кинувся наживатися на цій землі.\n\nЇхня жадоба наразила всіх нас на ще більшу небезпеку. Ми мусимо їх спинити. Пошукаймо разом сліди їхньої присутності.",
        objectives = "Знайди сліди присутності картелю Ксай.",
        completion = "Картель Ксай десь поруч.",
    },
    [64743] = {
        title = "Чим це ви тут займаєтесь, Ксай?",
        description = "Ми їх не бачимо, але я певен: саме тут картель Ксай облаштував свою базу.\n\nЩось привабило Ксай саме в цю частину Зерет Мортіса, і ми мусимо з'ясувати, що саме, якщо хочемо захистити наших тутешніх друзів.\n\nЇхні маскувальні плащі кепсько приховують запаси. Подивися, що можна дізнатися з їхніх речей.",
        objectives = "Збери 10 Підозрілих Паперів.",
        progress = "Ми мусимо з'ясувати, що задумав тут картель Ксай.",
        completion = "О, вони гадали, що сховають свої плани за шифром? Зачекай, $p(друже:подруго), це забере якусь мить...",
    },
    [64744] = {
        title = "Викривач посередників",
        description = "Відчуваєш, як змінилося повітря? Вони, може, й невидимі, але картель Ксай десь поруч.\n\nНа щастя, пристрої, якими вони себе маскують, мені добре знайомі. Ось, візьми. Постав на землю — і воно на якийсь час викриє агентів поблизу.\n\nЗупини їх, навіть якщо доведеться забрати їхні життя.",
        objectives = "Убий 12 агентів картелю Ксай неподалік Прихистку.",
        completion = "Шкода, що довелося їх убити, але ми мусимо захистити Прихисток.",
    },
    [64745] = {
        title = "Безкорисливе збереження",
        description = "Колись автома були тут усюди: вони співали, будували різні речі, виконували задум Перших. Та потім загарбники з Пащі винищили їх усіх.\n\nОстанні автома, що загинули, захищали щось важливе в сусідній споруді.\n\nЯ бачила, як один із проклятих Пащеприсяжних украв пристрій біля дверей. Старійшини кажуть, що нам не можна чіпати артефакти, але хіба буде гріхом повернути вкрадене?",
        objectives = "Знайди Викрадений Артефакт у Покажчику Впорядкування та поверни його на законне місце.",
        completion = "Ця автома ще жива! Але така слабка.",
    },
    [64758] = {
        title = "Слідом за ватажком",
        description = "Щойно прибувши, ми запечатали двері Дрімотного Сховку. Це святилище, колиска всього найціннішого, що тут є. Силу, яка спить усередині, нам не можна чіпати.\n\nЯкщо ватажок Ксай прослизнув крізь щити, поки ми милувалися красою цього місця, страшно навіть подумати, що він уже встиг потривожити.\n\nШвидше! Треба дістатися Дрімотного Сховку й переконатися, що з ним усе гаразд.",
        objectives = "Обстеж Дрімотний Сховок.",
        progress = "Картель Ксай треба спинити!",
        completion = "Ні! Що цей дурень накоїв із консоллю?!",
    },
    [64759] = {
        title = "Брухт ще живий",
        description = "Ось де ховалася ця автома! Підозрюю, що вона не зрадіє нашій допомозі.\n\nМені незручно таке пропонувати, але якщо служитель пов'яже тебе з цим місцем, він стане поступливішим.\n\nЯкщо маєш змогу, перепиши гліфи, викарбувані на схожих автома назовні. Ті, кого торкнулася Паща, зіпсовані, та зі свого спостережного пункту я бачила в пісках кілька полеглих автома з неушкодженими гліфами.",
        objectives = "Здобудь гліфи з 6 виснажених служителів довкола Покажчика Впорядкування.",
        completion = "Сподіваюся, це заохотить нашого друга бачити в нас союзників. Хай Перші нам пробачать.",
    },
    [64760] = {
        title = "Технічні негаразди",
        description = "Консоль геть знавісніла! Треба її полагодити!\n\nМоже, ці кнопки щось та роблять?",
        objectives = "Понатискай кнопки на консолі в Дрімотному Сховку.",
        progress = "Треба якось полагодити консоль!",
        completion = "Дякую за допомогу, Ходаче Пащі.\n\nЯ мушу повернутися до Орібоса. Я скажу картелю Ал, що наші друзі не втрачені — вони Просвітлені.",
    },
    [64761] = {
        title = "Ключова компетенція",
        description = "Бідолашне створіння.\n\nСвященне не годиться тривожити, але... чи осудять нас старійшини, якщо ми допоможемо йому вижити? Це збереження, а не втручання.\n\n...сподіваюся.\n\nМи можемо знову його запустити. Використай це виснажене ядро як провідник. Можливо, у більших диких оживлених із довколишніх пісків стане енергії, щоб його зарядити.",
        objectives = "Заряди Виснажене Ядро Автома, витягуючи енергію з убитих диких створінь у Покажчику Впорядкування.",
        completion = "Цей самотній знову стане сильним.",
    },
    [64762] = {
        title = "Відродження найсильнішого",
        description = "Це ядро аж вирує енергією!\n\nВикористай заряджене ядро, щоб оживити автома. Сподіваймося, вона більше не бачитиме в нас загрозу.\n\nБудь обереж$p(ний:на). Сила Перших не призначена для того, щоб нею керували ми.",
        objectives = "Оживи прихованого служителя в Покажчику Впорядкування.",
        completion = "Підтримка прибула. Відновлення може розпочатися.",
