    [64794] = {
        title = "Знання — половина битви",
        description = "{name}, приєднайся до Шандріс і проникни до лав Пащеприсяжних зі сходу. Хоч би що ви двоє дізналися, це підкаже нам наступний крок.\n\nБережи себе. Ми гадки не маємо, що на вас там чекає.",
        objectives = "Зустрінься із Шандріс біля Провіс-Страти.",
        completion = "Ти вже тут.\n\nЇхні пересування тут дивні. Схоже, ніби основна частина їхніх сил деінде.",
    },
    [64796] = {
        title = "Прочеши піски",
        description = "Те небагато, що я досі побачила, майже нічого не сказало мені про наших ворогів. Доведеться придивитися ближче.\n\nЗа твоїм наказом я сховаю нас обох від чужих очей. Але тримайся подалі від жахолордів — їхні очі досить гострі, щоб розгледіти навіть приховану мисливицю.",
        objectives = "Розвідай Провіс-Страту разом із Шандріс Фезермун.",
        progress = "Що менше уваги ми привертаємо, то краще.",
        completion = "Ми розкрили їхню найближчу мету. Треба швидко повертатися до союзників.",
    },
    [64797] = {
        title = "Гармонія і розбрат",
        description = "Ці обеліски, безперечно, ключ до планів Зоваала. Навіть не знаючи достеменно їхнього призначення, ми маємо завадити Пащеприсяжним біля них хазяйнувати.\n\nЯ передам ці відомості Верховному лорду Болвару. А ти вирушай до Даріона Мограйна і зроби те саме. Йому доведеться вибудовувати оборону з огляду на це.",
        objectives = "Поговори з Даріоном Мограйном у Провіс-Террі.",
        completion = "Ворог поки не зміг прорвати нашу оборонну лінію, але, боюся, без твоєї допомоги ми програємо цю битву.",
    },
    [64798] = {
        title = "Те, що ми долаємо",
        description = "Тепер я розумію. Усі ми, кого торкнулося Панування, змогли черпати з чогось усередині. Чи то шляхетність, чи то жага помсти — це давало силу опиратися.\n\nПісля всього, через що я пройшов, я мушу пам'ятати, що я досі тут.\n\nІ якщо є ті, хто готовий стати поруч із Сильваною, я мушу вірити, що вони стануть і поруч зі мною.\n\nЯ готовий спробувати знову. Цього разу я здолаю все, що постане на моєму шляху.",
        objectives = "Здолай Пащезв'язане страховисько і влий силу в останній уламок.",
        progress = "Ми не зазнаємо поразки. Іншого вибору немає — лише небуття.",
        completion = "Тепер усі уламки наснажені опірністю, яку ми здобули, переживши Панування.\n\nЦе не було легко — нікому з нас. Але я пишаюся тим, чого ми змогли досягти разом.\n\nЩодо решти — наше майбутнє в руках Примуса.",
    },
    [64799] = {
        title = "Зламана корона",
        description = "Наші друзі повернулися з Гробниці Перших зі знайомим обличчям.\n\nАндуїн... Скільки ж жахіть він пережив.\n\nХоч як важко й боляче це буде, ми мусимо дізнатися все, що йому відомо. Тюремник перекрив нам шлях усередині Гробниці, і якщо ми сліпо рушимо за ним, то ризикуємо самі стати жертвами Панування.\n\nАндуїн — наша найкраща надія.",
        objectives = "Поговори з Андуїном Рінном у Геометричній Печері.",
        progress = "Ми мусимо здолати Зоваала, інакше все втрачено.",
        completion = "Скільки страждань він витерпів... \n\nЦе буде важко подолати.",
    },
    [64800] = {
        title = "Наш останній вибір",
        description = "Зоваал зупинив нашу погоню. Якщо ми хочемо здолати його, то мусимо знайти спосіб протистояти Пануванню.\n\nАле щоб подолати його, потрібно зрозуміти, як воно діє.\n\nПанування створив Примус із Малдраксуса — він зможе розповісти нам більше.\n\nЯ попросив Талію принести уламок Шолома Панування до Зерет Мортіса. Боюся навіть подумати, що могло б статися, якби я спробував нести його знову...\n\nОбговорімо наші подальші кроки.",
        objectives = "Вислухай план.",
        progress = "Минулого не повернути. Нам лишається жити зі зробленим вибором і рухатися вперед.",
        completion = "Мені цей варіант подобається не більше, ніж Талії, але ми мусимо навчитися безпечно володіти Пануванням, якщо хочемо знайти спосіб його подолати.\n\nПерший крок — переконатися, що шолом досі діє. На нас.",
    },
    [64801] = {
        title = "Старійшина Еру",
        description = "Відколи ми здобули довіру Просвітлених, я дізнався більше про їхні дослідження Зерет Мортіса.\n\nВони знають більше, ніж готові розповісти, але часто не діють на основі цих знань. Можливо, там, де вони лише спостерігають, ми зможемо стати поштовхом до дії.\n\nУ відлюдному закутку, що зветься Лексична галявина, живе старійшина на ім'я Еру. Можливо, вона підкаже нам, як скористатися мовою Перших.\n\nРозшукай її й дізнайся, чи допоможе вона нам.",
        objectives = "Знайди старійшину Еру біля Лексичної галявини.",
        completion = "Що таке? Хочеш дізнатися, чи є тут щось, що допоможе опиратися магії Пащеприсяжних?\n\nТобі пощастило, чужин$p(че:ко). Так сталося, що я знаю: це місце — бібліотека. А бібліотеки — чудові місця, щоб знайти те, що шукаєш.",
    },
    [64802] = {
        title = "Вітаю, темряво",
        description = "Я створив Панування як знаряддя, щоб покарати Зоваала.\n\nМій гнів живив це творіння, і тепер ми платимо ціну за мою пиху. Навіть Вічні часом помиляються.\n\nАле надія ще не втрачена.\n\nВізьми половину зламаного Шолома Панування й випробуй її на комусь зі своїх. Якщо вона зберегла достатньо сили, її можна буде випробувати й деінде в Зерет Мортісі.",
        objectives = "Випробуй зламаний Шолом Панування на Даріоні Мограйні.",
        progress = "Ми не здамося, доки не спинимо Зоваала.",
        completion = "Навіть ті, хто подолав Панування, нині не мають до нього цілковитого імунітету.\n\nАле в тій історії може критися щось, що нам допоможе. \n\nЯ поміркую над цим.\n\nА поки що зосередься на створіннях Зерет Мортіса. З'ясуй, що робить їх опірнішими.",
    },
    [64803] = {
        title = "Раз, два, перевірка",
        description = "Створіння Зерет Мортіса жили тут задовго до того, як я створив Панування.\n\nМи бачили, як на них вплинули сили Зоваала, та я певен, що дізнатися можна ще більше.\n\nЗастосуй шолом на мешканцях Зерет Мортіса й з'ясуй усе, що зможеш, про їхню природну опірність.",
        objectives = "Випробуй зламаний шолом на створіннях Зерет Мортіса.",
        progress = "У тебе предмет, що володіє силою Панування, але він тебе не підкорив? Цікаво.",
        completion = "Розвиненіші створіння опираються Пануванню довше? \n\nНу звісно, я могла б і сама тобі це сказати. Уся суть у мові!",
    },
    [64804] = {
        title = "Загадковий каталог",
        description = "Ця місцина — сховище найрізноманітніших текстів. Гм? Про що в них ідеться? Гадки не маю!\n\nЯ присвятила себе їхній каталогізації та впорядкуванню. Зараз це важливо як ніколи, адже загарбники порушують рівновагу в Зерет Мортісі! Ми мусимо вберегти все, що знайшли досі.\n\nТи можеш допомогти. Іди на галявину й запам'ятай тамтешні фрази, а потім приходь до мене вниз, у грот. Там є дещо, що допоможе тобі випробувати твій шолом далі.",
        objectives = "Запам'ятай фрази на Лексичній галявині.",
        progress = "Подумай, скільки ми могли б дізнатися, якби розуміли задуми Перших.",
        completion = "Це місце дивовижне.\n\nЯ могла б провести тут усе своє існування.",
    },
    [64805] = {
        title = "Ненауковий метод",
        description = "Мова Перших не статична, як більшість інших. Вона розвивається.\n\nСтворіння на кшталт вартових, певна річ, розвиненіші за звичайного птахіда. Складніший плин їхніх думок дає їм вроджену опірність до підкорювальної магії загарбників.\n\nАле не вір мені на слово. Це можна перевірити!\n\nУ гроті є бібліотекар. Візьми ті фрази, що запам'ятав, і влий їх у нього. А тоді випробуй свій шолом.",
        objectives = "Випробуй зламаний шолом на активованому бібліотекарі Лексикону та простеж за результатами.",
        completion = "От бачиш! Пануванню знадобилося значно більше часу, щоб придушити вроджене призначення бібліотекаря.\n\nЗрештою воно, звісно, не встояло, але для твоєї мети я назвала б це успіхом.\n\nНе хвилюйся, місце цього автома посяде інший. Бібліотекар має бути завжди.",
    },
    [64806] = {
        title = "Там, де живе пам'ять",
        description = "Гадаю, я знаю, чого від нас вимагатимуть у Бастіоні. Це буде нелегко.\n\nЗ цією половиною Шолома ми зібрали першу частину того, що потрібно, аби протистояти Пануванню. Та серед нас є й ті, хто також страждав від нього. Хто пройшов крізь це.\n\nУ певному сенсі воно затаврувало нас. Усіх нас.\n\nУ цих переживаннях має бути щось, що допоможе нам вирватися з-під впливу Зоваала.\n\nХодімо до Зали Першого Відбиття в Бастіоні.",
        objectives = "Зустрінься з Верховним лордом Болваром у Залі Першого Відбиття в Бастіоні.",
        completion = "Добре, що ти вже тут.\n\nМи зібрали тих, хто в минулому постраждав від Панування. Дехто — зовсім нещодавно. \n\nУсі пройшли крізь це — не завжди неушкодженими, але ми досі стоїмо. Саме це нам і треба вловити.",
    },
    [64807] = {
        title = "Те, що ми хочемо забути",
        description = "Хоча мова Прабатьків допоможе нам, є ще одна риса, що дасть змогу розбити хватку Панування над нами.\n\nНездоланна воля.\n\nТі з нас, хто витерпів усе це раніше й вижив, мають цю вроджену опірність, і ми віддамо її, щоб влити в кожен з уламків.\n\nПримус запевнив мене, що це спрацює. Іншого виходу немає, тож це єдиний шлях.\n\nВірю, що воно буде варте страждань.",
        objectives = "Допоможи з ритуалом і влий силу в Уламки Панування.",
        progress = "Ми зробимо все, що буде потрібно.",
        completion = "Я почуваюся... легше. Але я не можу забути, що привело мене сюди й що ще належить зробити.\n\nСподіваюся, Талія запам'ятає те, що побачила... того, ким я є тепер. Не самотню постать під замком, а того, хто робить необхідне заради загального добра.",
    },
    [64808] = {
        title = "Те, що робить нас сильними",
        description = "Якби ж я знав про це місце раніше. Де можна вигнати з себе жахливу темряву, переглянути й стерти спогади...\n\nЯ готовий зробити все, що знадобиться, щоб допомогти здолати Зоваала, хай яка буде ціна.\n\nЦе єдиний шлях.",
        objectives = "Допоможи з ритуалом і влий силу в Уламки Панування.",
        progress = "Щоб зробити те, що мусить бути зроблене, потрібна не лише груба сила.",
        completion = "Гадаю, я розумію.\n\n<Андуїн збирається з духом.>\n\nЯ готовий спробувати знову.",
    },
    [64809] = {
        title = "Половина рівняння",
        description = "Теорія Примуса про мову Перших підтвердилася.\n\nУсе ж цього може бути замало.\n\nПоки Примус завершує свої плани, ходімо вглиб Безкраїх Пісків, щоб знайти частки цієї сили й влити їх у шолом.\n\nДаріон, Талія і я зустрінемо тебе там і допоможемо впоратися з Пащеслугами.",
        objectives = "Вирушай до Покинутого Оглядового Майданчика.",
        completion = "Ворог грізний, але з міццю нашої зброї та силою зламаного Шолома ми зможемо зрівняти шанси.\n\nХоча, зізнаюся, коли на полі бою моя донька, я обережний удвічі.",
    },
    [64810] = {
        title = "Гнобити й нищити",
        description = "Те, що ми шукаємо, лежить у сховищах Безкраїх Пісків. Щоб дістатися туди, знадобиться сила й чисельність.\n\nРазом ми знищимо Пащеслуг.\n\nНе можу дочекатися, коли ми вдаримо просто по них.\n\nПам'ятай: вони вразливі до зламаного уламка Шолома Панування.",
        objectives = "Убивай Пащеслуг у Безкраїх Пісках.",
        progress = "Яке величне спустошення.",
        completion = "Чудова робота. \n\nБудемо сподіватися, що ми востаннє бачимо цей шолом у ролі зброї.",
    },
    [64811] = {
        title = "Агресивні розкопки",
        description = "Старійшина Еру казала, що саме тут ми знайдемо найскладніші зразки мови Перших.\n\nНам доведеться пробитися до сховищ, а коли знайдемо ці фрази — наповнити ними шолом.\n\nЯкщо чесно, я ніколи не думала, що матиму нагоду битися пліч-о-пліч зі своїм батьком. Та коли на кону так багато, це чомусь видається саме тим місцем, де я маю бути.\n\nЯ готова, коли скажеш.",
        objectives = "Збери Незбагненні Фрази.",
        completion = "Нам вдалося. Зламану половину шолома наснажено найскладнішими зразками сили Перших, які лише вдалося знайти.\n\nМи так близько до успіху.",
    },
    [64812] = {
        title = "Кузня Панування",
        description = "У нас є всі потрібні частини. Зламану половину шолома ми наповнили всією складністю мови Перших, а уламки несуть наші спогади.\n\nНашу волю опиратися Пануванню.\n\nЛишилося тільки, щоб Примус наново викував Шолом, і тоді ми самі зможемо черпати цю об'єднану силу.\n\nЯ знаю, що це небезпечно, але це наша єдина надія.",
        objectives = "Вирушай до Темниці Різьбяра Рун у Торгасті.",
        completion = "Як доречно, що місце, де я був ув'язнений, стане місцем нашого визволення.",
    },
    [64813] = {
        title = "Корона Воль",
        description = "Коли я створив Панування, я не передбачав, скільки болю воно завдасть світам. Не лише Тіньокраю, а й твоєму.\n\nНастав час узяти цей шолом, цей символ тієї магії, і викувати його наново. Але не для тієї мети, якій він колись слугував.\n\nХай він уособлює силу волі, яку маєте ти і подібні до тебе, щоб нарешті допомогти нам здолати й перемогти Зоваала.",
        objectives = "Перекуй Шолом Панування.",
        progress = "Шляху назад немає.",
        completion = "Ця сила не схожа на жодну, яку я відчував раніше. Ми створили щось нове.\n\nВона стане нашим ключем до перемоги над Зоваалом.",
    },
    [64814] = {
        title = "Битва за Кузню",
        description = "Поки що наші війська тримаються, але територію ми ще не убезпечили. Нам не завадила б допомога, щоб прорідити ворожі лави.\n\nДля тебе це має бути проста справа, Ходоку Пащі.",
        objectives = "Убий 8 Пащеприсяжних.",
        progress = "Справу зроблено?",
        completion = "Ми мусимо лишатися пильними. Ніхто не сміє пройти крізь нашу оборону.",
    },
    [64815] = {
        title = "Мчимо разом",
        description = "Чотири ковенанти діють тут пліч-о-пліч з автома.\n\nНа жаль, дехто з наших солдатів відбився від своїх або дістав поранення і не може повернутися сюди.\n\nЯкщо зможеш їм допомогти — це стане величезною підмогою.",
        objectives = "Допоможи 5 бійцям ковенантів.",
        completion = "Що менші наші втрати тут, то довше ми зможемо тримати оборону.",
    },
    [64816] = {
        title = "На порозі реальності",
        description = "Настав час рушити за Зовалом у саме серце Тіньокраю.\n\nМи мусимо повернутися до Зерет-Мортіса і завершити це.",
        objectives = "Повернися до Зерет-Мортіса.",
        completion = "Тут, у Зерет-Мортісі, ще багато роботи, перш ніж вплив Зоваала буде викорінено з Тіньокраю.",
    },
    [64817] = {
        title = "На видноті",
        description = "Цей звук! Він долинув з боку обеліска біля Провіс-Флори.\n\nНеможливо. Ми нікого не пропускали. Швидше, {name}. За мною!",
        objectives = "Захисти обеліск біля Провіс-Флори.",
        progress = "Треба поспішати!",
        completion = "Їм вдалося сховатися. Це не віщує нам нічого доброго.",
    },
    [64818] = {
        title = "Можливо, знадобиться підкріплення",
        description = "Жахолорди проникли глибоко в наші лави. Болвар має дізнатися, що сталося.\n\nЯ не можу покинути свій пост. Мерщій передай йому новини. Можливо, і рада Просвітлених щось порадить.",
        objectives = "Поговори з Болваром Фордрагоном у Прихистку.",
        completion = "Мограйн отримає потрібні йому сили.",
    },
    [64820] = {
        title = "Це твоя провина — виправляй",
        description = "Провіс-Фауну зазвичай регулюють автономні конструкти, але надходять повідомлення, що вони більше не працюють.\n\nЗгідно з тими повідомленнями, відповідальність за втручання в ці вузли лежить на тобі. А отже, тобі їх і лагодити. Візьми цей налаштовувач — він має допомогти. І коли все полагодиш, більше до них не лізь.",
        objectives = "Полагодь 5 захисних вузлів.",
        completion = "Тепер, коли захист знову працює, присутність Пащеприсяжних, сподіваймося, зменшиться.",
    },
    [64821] = {
        title = "Ніщо не є істиною",
        description = "Якщо ми маємо справу з жахолордами, вони можуть прибрати будь-якої подоби... зокрема й мешканців Зерет Мортіса. На щастя, у нас є саме те, що треба, аби розвіяти їхні ілюзії.\n\nОбшукай поля й перевір автома. А якщо знайдеш жахолордів — розправся з ними.",
        objectives = "Знайди і вбий 4 жахолордів-диверсантів.",
        completion = "Це має сповільнити їхні плани. Гарна робота, Ходаче Пащі.",
    },
    [64822] = {
        title = "Розрив зв'язку",
        description = "Прохання Мограйна про підкріплення дивує: ми й так збиралися зміцнити цю територію і вже відправили до нього три загони.\n\nСхоже, жоден із них не прибув. Знайди їхніх командирів і подбай, щоб вони дісталися Мограйна.",
        objectives = "Передай нові накази трьом командирам ковенантів.",
        progress = "Вдалося їх знайти?",
        completion = "Вони запевняли, що попередні накази їм відда$p(в:ла) саме ти? Дивно.",
    },
    [64823] = {
        title = "Двобій двійників",
        description = "Щось тут не дає мені спокою. З твоїх слів це скидається на навмисну диверсію зсередини наших лав... або на справу рук нових жахолордів.\n\nЯкщо тут замішані жахолорди, обеліск може бути в небезпеці! Мерщій — загаємося, і буде запізно!",
        objectives = "Знайди сліди Пащеприсяжних у Колі Думки.",
        progress = "Час тут вирішує все.",
        completion = "Мал'Ґаніс...\n\nМи програємо ці перегони.",
    },
    [64824] = {
        title = "Бій за Кузню",
        description = "Ми дісталися сюди так швидко, як тільки могли. Андуїна помітили біля споруди в серці цих земель — її називають Кузнею Загробних Світів.\n\nТюремник, без сумніву, невдовзі приєднається до нього. Вирушаймо негайно.",
        objectives = "Вирушай до Кузні Загробних Світів із Джайною.",
        completion = "Андуїне...\n\nМи якось тебе врятуємо.",
    },
    [64825] = {
        title = "У пошуках Прихистку",
        description = "Я не знаю, що робити далі.\n\nМи не маємо змоги піти слідом за Зоваалом та Андуїном. Я відкрию портал назад до Прихистку. Там і обговоримо подальші кроки.",
        objectives = "Повернися до Прихистку разом із Джайною та Бейном.",
        completion = "Ми з'ясуємо, як вирушити за ними до Гробниці. А доти зосередься на нагальніших справах.",
    },
    [64829] = {
        title = "Знайти Талі",
        description = "Після цілих епох спокою вплив Пащі приніс у Зерет Мортіс горе. Одна з наших послушниць, Талі, особливо тяжко переживає останні події. Вона пішла деякий час тому й досі не повернулася.\n\nЧи не перевіриш, як вона? Востаннє її бачили, коли вона прямувала до руїн, похованих під пісками.",
        objectives = "Знайди Талі біля Покажчика Впорядкування.",
        completion = "Навіть тепер це місце прекрасне.",
    },
    [64830] = {
        title = "Заручитися підтримкою Просвітлених",
        description = "Доля Сильвани зараз не є моїм найпершим клопотом.\n\nТюремник знищив Гармонійні Канали, аби ми не змогли вирушити за ним.\n\nМожливо, допитливі Просвітлені Посередники знають про ці канали щось таке, що нам допоможе, — але співпраця з посередниками часто має свою ціну.\n\nРоби все, чого вони вимагатимуть. Ми мусимо дізнатися більше.",
        objectives = "Переконай старійшин Прихистку надати допомогу.",
        completion = "У Зерет Мортісі є відповіді, яких ти шукаєш.\n\nЯкщо знати, де шукати.",
    },
    [64831] = {
        title = "Рештки Перших",
        description = "У Провіс Еспері можуть лишитися сліди руйнувань, заподіяних Присяжними Утроби. Якщо ми відшукаємо ці сліди, вони дадуть нам якусь підказку, як вистежити цього Тюремника.\n\nПолюймо разом. Я впізнаю прикмету магії Перших, щойно ми опинимося поруч із нею.",
        objectives = "Збери 3 Залишки Провідності.",
        progress = "Чи всі рештки ми знайшли?",
        completion = "На жаль, лише інертні рештки.\n\nАле не втрачай надії, $p(друже:подруго)!",
    },
    [64832] = {
        title = "Повернути Провіс Еспер",
        description = "Провіс Еспер заполонили пожирачі — гудуть навколо, наче голодні веспоїди.\n\nВони нищать тутешніх автома, а це геть суперечить задуму Перших. Час провести очищення.\n\nЗаради нашої безпеки й задля відновлення природного ладу винищ частину з них.",
        objectives = "Убий 20 ненаситних кліщів, 5 душеспраглих ненажер і 2 проривачів реальності.",
        progress = "Провіс Еспер очищено?",
        completion = "Прийдуть нові пожирачі, але поки що їхній натиск ослаблено.",
    },
    [64833] = {
        title = "Єдність із розмаїття",
        description = "Інші Старійшини дотримуються суворого тлумачення того, як найкраще шанувати творіння Перших.\n\nЯ ж не такий непоступливий. Адже наша кінцева мета однакова.\n\nПовернімося туди, де ти востаннє бачи$p(в:ла) Тюремника.",
        objectives = "Зустрінься зі Старійшиною Арою над Провіс Еспером.",
        completion = "Місцина внизу аж кишить пожирачами. Але ти ж упораєшся, так?",
    },
    [64834] = {
        title = "Сяй і споглядай",
        description = "Поглянь, {name}. Рештки ледь помітно сяють!\n\nВони, певно, реагують на щось у Благодаті Прочанина.\n\nЗ'ясуй, що спричиняє цю реакцію!",
        objectives = "З'ясуй, що спричиняє реакцію Залишків Провідності.",
        progress = "Рештки зреагували на цей транслокатор? Неймовірно!",
        completion = "Отже, рештки якось пов'язані з транслокатором. Але як?\n\nХай яким було їхнє колишнє призначення, тепер у них немає сили.",
    },
    [64835] = {
        title = "Зірвати з лоз",
        description = "Я біг, продираючись крізь колючі зарості, а батожники хапали мене за п'яти.\n\nМоїм побратимам-прочанам пощастило менше. Тікаючи, я чув їхні крики болю й жаху.\n\nТи маєш знайти спосіб пробратися всередину. Врятуй їх, {name}!",
        objectives = "Врятуй 5 зниклих прочан.",
        progress = "Зниклих прочан урятовано?",
        completion = "Не знаю, як і дякувати за порятунок тих прочан, кого ще можна було врятувати.",
    },
    [64836] = {
        title = "Викорінити зло в зародку",
        description = "Колись Станції Каталізатора були мирним місцем. Прочани приходили сюди століттями, щоб споглядати дива Перших. Та це місце вже не безпечне. Культиватор без жалю й без причини вбив кількох наших братів.\n\nТи мусиш знищити його.\n\nІнші Старійшини зі мною не погодилися б. Інші Старійшини помиляються.",
        objectives = "Убий Культиватора.",
        progress = "Що могло змусити Культиватора поводитися так нерозважливо... так люто?",
        completion = "Знищити Культиватора було правильним рішенням.",
    },
    [64837] = {
        title = "Подорож прочанина",
        description = "Благодать Прочанина — священне місце для Просвітлених. Тамтешні Старійшини глибоко розуміють творіння Перших.\n\nСаме там ми знайдемо відповіді щодо цих дивних решток, які ми відшукали.\n\nЗустрінься зі мною в Благодаті Прочанина. Це недалеко.",
        objectives = "Зустрінься зі Старійшиною Арою в Благодаті Прочанина.",
        completion = "Ласкаво просимо до Благодаті Прочанина.",
    },
    [64838] = {
        title = "Де є прочанин, там є і шлях",
        description = "Якщо рештки можна відновити, хтось у Благодаті Прочанина може знати, як це зробити.\n\nПочни зі Старійшини Нірава. Сподіваюся, він захоче допомогти. Сьогодні він здається стривоженим і неуважним.\n\nКоли впораєшся, знайди мене в місті.",
        objectives = "Поговори з мешканцями Благодаті Прочанина.",
        progress = "Вдалося поговорити з Просвітленими в Благодаті Прочанина?",
        completion = "Наша найкраща надія — Фероз? І він зник разом із кількома іншими прочанами?\n\nТреба поспішати.",
    },
    [64839] = {
        title = "Корінь проблеми",
        description = "Підозрюю, що ми можемо використати енергію росту, що міститься в цих рослинах, для власних потреб, але мені потрібні свіжі зразки.\n\nТи можеш зібрати наснажену рослинну речовину з будь-яких батожників чи обплетених лозами автома поблизу, або з тих, що всередині Станцій Каталізатора.",
        objectives = "Збери наснажену рослинну речовину.",
        progress = "Наснажену рослинну речовину зібрано?",
        completion = "Ці корені аж переповнені енергією росту.",
    },
    [64840] = {
        title = "Нестримний ріст",
        description = "Ця енергія росту вкрай незвичайна. Я хотів би дізнатися більше про те, як вона впливає на місцевих автома.\n\nЗбери реплікаційну есенцію з полеглих автома в Садах Каталізатора.\n\nПринеси її мені для вивчення.",
        objectives = "Збери 12 Реплікаційних Есенцій.",
        progress = "Реплікаційна есенція вже в тебе?",
        completion = "Гм... вона стрімко реплікується, доки не вб'є носія. \n\nЦе радше прокляття, ніж дар!",
    },
    [64841] = {
        title = "Скинути напругу",
        description = "Та плавуча споруда, що нависає над головою, — це Каталізатор Творення.\n\nЯ не можу наблизитися до нього. Вежа перевантажена надлишком енергії Прабатьків. Вирушити туди зараз було б самогубством.\n\nУ садах є консолі, якими можна розрядити цю енергію. Зроби це.",
        objectives = "Розряди надлишкову енергію Каталізатора Творення.",
        progress = "Чи безпечно вже летіти до Каталізатора Творення?",
        completion = "Чудова робота, Ходаче Пащі!",
    },
    [64842] = {
        title = "Шал флори",
        description = "Ті автома-вартові зіб'ють усе, що спробує дістатися до Каталізатора Творення.\n\nДозволь запропонувати: чому б не клин клином вибивати? Точніше — битися з творіннями Перших їхньою ж енергією творення?\n\nУ мене було обмаль часу як слід перевірити цю теорію, але це зілля має дати тобі потрібний поштовх, щоб знищити їх... в ідеалі — не загинувши при цьому від дії енергії творення.",
        objectives = "Випий розчин Фероза і знищ автома Садів Каталізатора.",
        progress = "Твоя безпека ймовірна, але не гарантована.",
        completion = "Як на мене, було доволі поетично обернути їхню ж енергію росту проти них.",
    },
    [64843] = {
        title = "Виготовлення ключа",
        description = "Тепер, коли тих збурених автома втихомирено, лишається тільки одне завдання.\n\nМи переправимо тебе та твого Просвітленого супутника нагору, до Каталізатора Творення.\n\nРешта залежить від тебе.",
        objectives = "Віднови Ключ Транслокатора біля Каталізатора Творення.",
        progress = "Неймовірно бачити Каталізатор Творення зблизька.",
        completion = "Нам це вдалося!",
    },
    [64844] = {
        title = "Прощу завершено",
        description = "Ти врятува$p(в:ла) багатьох прочан, а я відновив тобі вхід до Гробниці. На цьому нашу угоду виконано — а разом з нею завершено й мою прощу.\n\nАле твоя подорож триває.\n\nПовернися до оглядового майданчика за Благодаттю Прочанина та відкрий транслокатор.\n\nДякую тобі, {name}. Ця пригода мене... просвітлила.",
        objectives = "Повернися на оглядовий майданчик за Благодаттю Прочанина.",
        progress = "Послухаймо, що вони скажуть.",
        completion = "Наступний крок — великий. Ти готов$p(ий:а), {NAME}?",
    },
    [64846] = {
        title = "Торгаст",
        description = "Незліченні душі катують у залах Торгасту. Їм потрібна твоя допомога!",
        objectives = "Поговори з Тал-Інарою.",
        completion = "Торгаст поглинув надто багатьох. Шлях усередину важкий... але не неможливий.",
    },
    [64849] = {
        title = "Вежа Проклятих",
        description = "Ми мало знаємо про Торгаст. Утім, Літописець долі Рох-Таль стверджує, що там є справа, яку треба зробити.\n\nВін вважає, що для тебе є шлях, аби дістатися цього місця... і що там комусь потрібна твоя допомога.\n\nЗроби все необхідне, щоб дістатися Торгасту, і допоможи кожному, хто там опинився.",
        objectives = "Вирушай до Торгасту, стрибнувши в Кільце Переносу, а тоді знайди там будь-кого, хто потребує твоєї допомоги.",
        completion = "Назад! \n\nСтривай... ти не з військ Тюремника.\n\nСкринько! У нас гість — заграй приємної музики, гаразд?",
    },
    [64850] = {
        title = "Мандрівка Торгастом",
        description = "Я чув про тебе, Той, що ходить Пащею! Ти ж, певно, знаєш про мене — легендарного Ве'ніша.\n\nЯ тут, аби знайти в Торгасті величезні скарби за допомогою моєї скриньки. Бачу, ти милуєшся нею.\n\nМожливо, ми могли б діяти разом. Чому б тобі не вирушити в Торгаст попереду мене на розвідку?\n\nЯ навіть винагороджу тебе за все, що ти там знайдеш.",
        progress = "Як просувається розвідка темряви Торгасту?",
        completion = "А, це місце по вінця повне всіляких жахливих створінь... а ще там повно сил!\n\nЧудово! Ти чула, скринько? Ми знайдемо тут чимало... може, навіть більше, ніж та боягузка Ве'нарі в Пащі.\n\nКхм, дякую тобі, Той, що ходить Пащею. Свою частину ти викона$p(в:ла) добре. Пізніше я матиму ще запитання.",
    },
    [64852] = {
        title = "Матриця еонів",
        description = "<Фірім міг би скористатися цією річчю.>",
        objectives = "Достав річ Фіріму.",
        completion = "Саме це мені й було потрібно! Візьми оце на знак вдячності за твої зусилля!",
    },
    [64853] = {
        title = "Два шляхи попереду",
        description = "Це відповіло на твоє запитання?\n\nО, ти хоті$p(в:ла) спосіб повністю опиратися магії Панування? Боюся, його я не знаю. Мова Перших лише відтермінує неминуче.\n\nТа ось що я скажу: якщо хочеш знайти ще смачніше закручені фрази мови Перших, тобі варто вирушити до Безкраїх Пісків і обшукати сховища.\n\nХотіла б я піти сама, але там усе заполонили ці гидкі Пащеслуги.\n\nЩасти тобі в подальших дослідженнях!",
        objectives = "Звітуй Примусу в Геометричній Печері.",
        completion = "Ця Старійшина дала нам важливу відповідь на цю загадку. Але тепер треба діяти на основі цих знань. Хоча зробити це буде непросто.\n\nСпершу ми мусимо наснажити шолом тими нерозбірливими фразами Перших, що зберігаються в Безкраїх Пісках.\n\nАле самого цього не вистачить. Нам знадобиться більше. Я підготуюся, а ти здобудь те, що нам потрібно. Потім я пришлю по тебе звістку.",
    },
    [64854] = {
        title = "Пастка для успіху",
        description = "Звірину Зерет-Мортіса вабить шалена енергія творення, що тече по всьому краю. Коли звірина знаходить щось, наснажене цією енергією... вона це з'їдає!\n\nПоневолені Пащею крипторозвидники дізналися про це й намагаються відшукати таку звірину, щоб видобути з неї будь-які рештки тієї енергії.\n\nЗнищ крипторозвидників і скористайся Утримувальною Пасткою, щоб приборкати й дослідити звірину для нашого вивчення.",
        objectives = "Убий 5 поневолених Пащею крипторозвидників та оглянь перелічену звірину.",
        progress = "Ти зібра$p(в:ла) дані раніше за крипторозвидників?",
        completion = "Ці відомості допоможуть нам і далі розгадувати таємниці Зерет-Мортіса.",
    },
    [64860] = {
        title = "Етерна решітка",
        description = "<Фіріму ця річ напевно знадобиться.>",
        objectives = "Достав річ Фіріму.",
        completion = "Саме це мені й було потрібно! Візьми оце на знак вдячності за твої зусилля!",
    },
    [64861] = {
        title = "Кисметричний диск",
        description = "<Фіріму ця річ напевно знадобиться.>",
        objectives = "Достав річ Фіріму.",
        completion = "Саме це мені й було потрібно! Візьми оце на знак вдячності за твої зусилля!",
    },
    [64863] = {
        title = "Арканні вартові",
        description = "Ці конструкти, що патрулюють хорт, оживлені не магією Хранителя Землі.\n\n<Дервішіан примружує очі.>\n\nМи не можемо терпіти ворогів у своїх лавах.\n\nЗнищ їх і розчисть нам шлях уперед.",
        objectives = "Здолай 4 вартових або конструктів.",
        progress = "Хто б наважився так зневажити волю Хранителя Землі?",
        completion = "Ці конструкти були оживлені магією синього роду драконів. \n\nХранитель Землі ніколи б цього не дозволив!",
    },
    [64864] = {
        title = "Прокиньтеся, драктири",
        description = "<Поки ти струшуєш із себе те, що видавалося нескінченним сном, у пам'яті лишилися самі уривки спогадів.\n\nДрактир перед тобою не реагує, ніби скутий якоюсь невідомою магією. Ти відчуваєш, що в тобі криється сила визволити твого союзника.\n\nУ хорті можуть бути й інші, застиглі в такому ж заціпенінні.\n\nТвій обов'язок — пробудити їх.>",
        objectives = "Розбуди інших драктирів.",
        completion = "<Азуратель вислуховує твою доповідь.>\n\nМої спогади розбиті так само, як і твої, {NAME}. Але зараз не час на цьому зациклюватися.\n\nНам треба оцінити становище і скласти план.",
    },
    [64865] = {
        title = "Озброюйся",
        description = "Вороги вдерлися до нас, наших побратимів скувало магічне заціпеніння, а наш хорт, здається, руйнується.\n\nСаме заради цього ми й тренуємося, {name}. Коли вагаєшся — покладайся на те, що добре знаєш.\n\nСпершу — найнеобхідніше. Зброя, обладунки, припаси. Збери все, що знайдеш, і споряджайся, доки я скликаю наші сили.\n\nПотім ми відшукаємо Хранителя Землі. Нелтаріон неодмінно дасть нам відповіді, яких ми шукаємо.",
        objectives = "Роздобудь зброю, обладунки та припаси.",
        progress = "Коли зраджує пам'ять, покладайся на вишкіл.",
        completion = "Це спорядження давнє, а їжа обернулася на порох.\n\nБезглуздя якесь... цих припасів мало б вистачити на ціле життя.\n\nЩо ж, обійдемося тим, що маємо.",
    },
    [64866] = {
        title = "У саме горнило",
        description = "Твої вміння потрібні, $p(пробуджувачу:пробуджувачко).\n\nХорт розсипається, а припасів у нас обмаль. Ми мусимо дістатися проходу назовні, та спершу слід здолати цей арканний бар'єр.\n\nУ залі за ним є драктири, які потребують допомоги. Зціли їхні рани. Знищ будь-якого ворога, що стане тобі на шляху.\n\nМожливо, ми востаннє йдемо цими залами разом, {name}. Тож нехай це буде недарма.",
        objectives = "Приготуйся покинути хорт.",
        completion = "Ти зціли$p(в:ла) наших. Чудова робота.\n\nТепер розберімося з тим драконом.",
    },
    [64870] = {
        title = "Взірець Просвітлених Мостивців",
        description = "Ти ба. А ти не сиділа без діла, чи не так?",
        objectives = "Поговори з Віло в Прихистку в Зерет Мортіс.",
    },
    [64871] = {
        title = "Дракон на порозі",
        description = "Цей синій дракон обвалить хорт і замурує нас усередині!\n\nВін стверджує, що служить Малігосу. Це ім'я мені знайоме, але... навіщо якомусь дракону тримати нас у полоні?\n\nСлухай, {name}. Нас навчали битися пліч-о-пліч із драконами, а не проти них. Та нам не лишили вибору.\n\nЧас зробити те, що мусимо, $p(пробуджувачу:пробуджувачко).",
        objectives = "Здолай Лапісагоса і втечи з Воєнного Хорту.",
        completion = "Ми розчистимо завали й подбаємо, щоб жоден {race} не лишився позаду.\n\nАле спершу треба убезпечити цю територію.",
    },
    [64872] = {
        title = "Вогонь усередині",
        description = "Ти пробуджувач, {name}. Еліта з еліти — боєць, що опанував уміння кожного з наших вейрнів.\n\nЯ чекаю від тебе багато чого.\n\nНехай твої спогади розбиті — у твоїх жилах струмує міць драконів. Загнуздай її.\n\nЧи не найгрізніша твоя зброя — атака подихом. Що довше вдихаєш, то потужнішим стає вогонь усередині.\n\nКомахи, що рояться над тренувальним майданчиком, будуть чудовими цілями.",
        objectives = "Вивчи Вогняний подих і повправляйся в посилених атаках.",
        progress = "Гарний глибокий вдих прочищає голову.",
        completion = "Добре. Ти пам'ятаєш свій вишкіл.\n\nТримай голову нижче, а легені — повними.",
    },
    [64873] = {
        title = "Розправ крила",
        description = "Втішно бачити, що стільком вдалося вирватися з Воєнного Хорту. Моєму власному вейрну... поталанило менше.\n\n<Емберталь якусь мить стоїть мовчки.>\n\nПо всьому Обширу розкидані інші хорти, повні драктирів у біді. Щоб дістатися туди, знадобляться дужі крила.\n\nЗосередься. Згадай вишкіл. Відчуй вітер знову. Поверни собі силу — і лети до інших хортів.\n\nЧас спочинку минув.",
        objectives = "Повправляйся у застосуванні Ширяння.",
        completion = "У тебе це виходить значно швидше, ніж свого часу в мене!\n\nТа й не дивно — вишкіл {class} у тебе вже за плечима. Мені ж хотілося обрати шлях дипломата.",
    },
    [64875] = {
        title = "Щось дивовижне",
        description = "{name}, як добре, що ти тут! Фірім послав мене знайти тебе.\n\nЦе оракул, він... ну... це важко описати. Краще приходь і подивися на власні очі. Поквапся!",
        objectives = "Вирушай до Лощини Вигнанця, щоб на власні очі побачити, що діється із Сезурою.",
        progress = "Треба поспішати, {NAME}. Ми не знаємо, скільки це триватиме.",
        completion = "Можливо, ми на порозі дивовижного одкровення!",
    },
    [64876] = {
        title = "Музика сфер",
        description = "Усе почалося поступово: енергія, що випромінювалася з оракула, дедалі наростала, доки не набув форми той величний візерунок, який ти бачиш перед собою.\n\nЖахливий гамір у наших вухах залунав невдовзі по тому.\n\nМої спроби наблизитися до фракталів були... марними. Але вони, схоже, відгукуються на Покопока.\n\nТебе з ним єднає особливий зв'язок; можливо, тобі поталанить більше, ніж мені.",
        objectives = "Оглянь фрактали, що оточують тіло Сезури.",
        completion = "Видіння! Оракул спілкується з нами! Ти теж це бачи$p(в:ла)? Яка велич! І яка... мігрень після нього.",
    },
    [64877] = {
        title = "Тест навігації: підвищення рівня (ЧАСТИНА 2)",
        description = "Насолоджуйся завершенням Низин!",
    },
    [64878] = {
        title = "Який довгий і дивний шлях",
        description = "<Голос із видіння говорить крізь Покопока, хоч і звучить далеким і спотвореним.>\n\nЯ... Саезура. Оракул. Ця автома... говорить моїм голосом. Діє моєю волею. Поки що.\n\nВізерунок... розірваний. Порушений. Його треба відновити.\n\nВелика жадоба роїться над пісками. Те, що вона шукає, не можна поглинути.\n\nМандруй зі мною. Іди за моїм голосом.",
        objectives = "Вирушай із Покопоком, щоб розібратися у своєму видінні.",
        progress = "Покопок ще не дістався місця призначення.",
        completion = "Над пісками. Над нами. Посудина чекає.",
    },
    [64879] = {
        title = "Доленосне відкриття",
        description = "Той, хто ходить Пащею, Пелагос завітав раніше зі звітом і сказав, що приготування оракула завершено й ти терміново потрібен.\n\nЯкщо це може допомогти нашій справі, я хочу, щоб ти долучи$p(вся:лася). Вирушай до Лощини Вигнанця й дізнайся, що їм потрібно.",
        objectives = "Зустрінься з Фірімом у Лощині Вигнанця.",
        completion = "Смертн$p(ий:а), у мене грандіозні новини. Саезура сповістила: приготування завершено. Час створити нового Арбітра!",
    },
    [64888] = {
        title = "Позичена сила",
        description = "Земля дає. Земля жадає. Загарбники пожирають те, що нам потрібне.\n\nПоверни поглинуте. Увібери те, чого ще вдосталь.\n\nКрилам потрібен вітер, щоб летіти. Нам потрібна сила, щоб піднестися.",
        objectives = "Перемагай нестійких принаджених ворогів або вбирай силу з калюж, щоб повернути Космічну Енергію та наснажити Покопока.",
        progress = "Більше сили Покопокові.",
        completion = "Сила вирує. Надія відроджується.",
    },
    [64889] = {
        title = "Союз, укладений у Зерет Мортіс",
        description = "Шифри — це ключ. Кожен із них — крок на шляху. Ти маєш знайти їх усі.\n\nУвійди до внутрішньої зали. На тебе чекає Розташування Первинного Локусу.\n\nПерший крок до піднесення. До посудини.",
        objectives = "Вивчи Розташування Локусів і скористайся Зсувом Локусу, щоб дістатися Локуса Ультімус.",
        progress = "Треба зібрати шифри, щоб дістатися дверей, за якими чекає посудина.",
        completion = "Починається останній відтинок подорожі.",
    },
    [64935] = {
        title = "Між каменем і каменем",
        description = "<Купи каміння розкидані по всій місцевості. Пожирачі завдали достатньо руйнувань, щоб приховати шифр, який ти шукаєш.\n\nМожливо, когось із прислужників поблизу можна змусити розчистити завали.>",
        objectives = "Розбий завали, що закривають доступ до Розташування Локуса Секундус.",
        progress = "Доки не знайдемо шифр, треба й далі трощити завали.",
        completion = "Наша мандрівка триває.",
    },
    [64936] = {
        title = "Шукати скрізь і всюди",
        description = "Три замки на дверях, три ключі сховано на вершині.\n\nЗнайди фрази. Промов слова. Убезпеч посудину.",
        objectives = "Збери на Локусі Ультімус Пропускні Гасла, потрібні, щоб забрати Посудину.",
        progress = "Посудина дрімає високо вгорі.",
        completion = "Одна подорож завершується. Інша починається.",
    },
    [64937] = {
        title = "Ти осяюєш моє життя",
        description = "Велика сила вабить велику жадобу. Ненаситні пожирачі видираються на скелі в пошуках поживи.\n\nНезабаром вони заполонять плато. Вони прагнуть поглинути все, що зустрінуть. Посудину. Її силу. Нас.\n\nЦього не можна допустити. Скористайся цією автомою. Обірви їхнє слиняве виття.",
        objectives = "Скористайся Покопоком, щоб захистити посудину від пожирачів.",
        completion = "Затишшя, поки що. Лишається більше завдання.",
    },
    [64941] = {
        title = "Куряча душа",
        description = "<Куряча душа жвава й ненажерлива. Тепер ти можеш прибирати подобу курки.>",
        objectives = "Принеси Курячу Душу Чуфі в Серце Лісу.",
    },
    [64942] = {
        title = "Поклик Примуса",
        description = "Хоч ми й боролися, щоб спинити Тюремника в Святилищі Панування, ми зазнали поразки. Він огорнув Орибос Пащею, повалив Арбітра й відкрив шлях до Зерет Мортіс.\n\nНастав час піти за ним.\n\nУ Залі Арбітра ми прокладемо власний шлях.\n\nПоспішай, Той, Хто Ходить Пащею. На кону доля Тіньокраю і всіх світів поза ним.",
        objectives = "Поговори з Тал-Інарою в Орибосі, щоб вирушити до Зали Арбітра.",
        completion = "Щоб рушити за Зоваалом, бракує лише одного, останнього сигіла.",
    },
    [64944] = {
        title = "Поспішна подорож",
        description = "Шлях до Зерет Мортіс відкрито.\n\nТут наші дороги розходяться. Вічним заборонено повертатися до місця нашого створення. Зовал зневажив найсвященніші закони Прародичів.\n\nЦю подорож тобі доведеться здійснити на самоті.\n\nІди. Здобудь плацдарм у Зерет Мортіс, щоб ми могли переправити туди сили ковенантів.\n\nТоді ми вирушимо за Тюремником і покладемо край його божевіллю.",
        objectives = "Розпочни свою подорож до Зерет Мортіс, осідлавши анімавирма.",
        completion = "Це... точно не Орибос.",
    },
    [64945] = {
        title = "Чужинці в чужому краю",
        description = "Ми... ми дісталися Зерет Мортіс? І ми йдемо по воді?\n\nЯке дивовижне місце! Принаймні з того, що я можу розгледіти крізь цей туман.\n\nЗдається, я бачу якусь споруду вдалині. Можливо, там ми знайдемо відповіді.",
        objectives = "Іди разом із Пелагосом і досліди околиці.",
        completion = "Я не потерплю, щоб прислужники Тюремника оскверняли цю землю!",
    },
    [64947] = {
        title = "Дай-но руку",
        description = "Щоб вигнати Тюремника із Зерет Мортіс, ми маємо кинути проти ворога всі наші сили.\n\nУ сховищі неподалік лежить предмет, що може приховувати велику силу, але захист тієї зали відгукується лише на автома. Я б нізащо не завдав шкоди їхньому роду, та я натрапив на одного, що більше не діє.\n\nЯкщо ти видобудеш його руку, ми зможемо скористатися цією нерухомою кінцівкою, щоб дістатися сховища.\n\nМені огидно так зловживати творіннями Перших, але ми не можемо терпіти присутність прислужників Пащі в цьому світі.",
        objectives = "Допоможи Фіріму.",
        completion = "Визнаю, такого результату я не передбачав.",
    },
    [64949] = {
        title = "Заради досліджень",
        description = "Увесь час у Зерет Мортіс я докладав усіх зусиль, щоб не турбувати автома, і досі вони майже не зважали на мене.\n\nСхоже, останні події це змінили.\n\nДозволь ще раз чітко сказати: я не маю жодного бажання шкодити творінням Перших. Та якщо під час твоїх дій сутички з автома не уникнути, ми мусимо подбати, щоб із цього вийшла хоч якась користь.\n\nЯкщо я зможу оглянути уламки полеглих автома, це дасть нам знання, які можна обернути проти прислужників Пащі.\n\nІди обережно.",
        objectives = "Збери 12 Цілих Фрагментів Автома зі сполошених автома в Переддвер'ї Генези.",
        progress = "Чи знайшлися корисні уламки?",
        completion = "Хоч втрата автома й прикра, ці уламки можуть неабияк прислужитися моїм дослідженням.",
    },
    [64950] = {
        title = "Взаємний обмін",
        description = "Схоже, решта автома не зраділи, що ми привласнили руку їхнього побратима. Вони стали ворожими.\n\nПрикро, але ми не можемо дозволити цьому стати нам на заваді.\n\nРука автома має активувати консоль у Сховищі Генези. Гадаю, там зберігається предмет величезної сили.\n\nКоли ти його здобудеш, я проведу тебе до місця, звідки, можливо, вдасться дістатися до союзників, яких ти залиши$p(в:ла) позаду.\n\nДомовилися?",
        objectives = "За допомогою руки автома активуй консоль автома та здобудь скарб сховища.",
        progress = "Чи вдалося здобути предмет із консолі?",
        completion = "<Фірім вихоплює ядро тобі з рук.>\n\nЦікаво. Я оглянув чимало ядер автома, але це сяє енергією, якої мені ще не траплялося бачити.",
    },
    [64951] = {
        title = "Шлях до Прихистку",
        description = "Я не сподівався сьогодні зустріти живого смертного та кіріанця, але твоя допомога виявилася безцінною.\n\nПерш ніж узятися до вивчення цього ядра автома, я проведу тебе до Прихистку — поселення, яке заснувала моя експедиція по прибутті.\n\nХоч мої колеги вирішили вигнати мене за те, що я ставив під сумнів їхні догми «Просвітлених», я не бажаю, щоб Тюремник стер Прихисток з лиця світу.\n\nДопоможи їм — і вони, можливо, посприяють твоєму поверненню до союзників. Ми, посередники, понад усе цінуємо вигідний обмін.",
        objectives = "Проїдь із Фірімом зі Сховища Генези.",
        completion = "Далі я йти не можу.\n\nУ нас із колишніми колегами... філософські розбіжності.",
    },
    [64952] = {
        title = "Знищити нищителів",
        description = "Прислужники Пащі мають страхітливу зброю, що збирає темну магію й шпурляє її в наші ворота.\n\nЗахисний бар'єр навколо Прихистку довго не протримається. Усе, чим ми є, усе, що нам дороге, скоро буде стерте з лиця світу.\n\nЯкщо ти справді $p(той:та), ким себе називаєш, доведи це нам. Знищ ворожу зброю та допоможи захистити наш дім.\n\nМолю Перших, щоб тобі це вдалося.",
        objectives = "Знищ 4 нищителі Пащі.",
        completion = "Ти вигра$p(в:ла) нам час, смертн$p(ий:а). Хай Перші благословлять нас усіх.",
    },
    [64953] = {
        title = "Оборона Прихистку",
        description = "Прислужники Пащі збирають сили просто під нашими воротами. Ясно, що вони мають намір захопити наш дім!\n\nПросвітлені прагнуть лише в мирі шанувати дива Перших. Захисний бар'єр Прихистку поставили, щоб боронити нас від дрібних загроз. Ми й уявити не могли, що Тюремник кине проти нас свої війська.\n\nКажеш, ти наш союзник, смертн$p(ий:а)? Тоді допоможи нам захистити цю священну землю.",
        objectives = "Здолай 13 прислужників Пащі у Великому Вельді.",
        progress = "Наші прочани так довго не витримають.",
        completion = "Ти дові$p(в:ла) свій гарт, але ворог дедалі зухвалішає.",
    },
    [64957] = {
        title = "Цей старий дороговказний камінь",
        description = "Тюремник відвів свої сили. Я мала б відчути полегшення, та боюся, це означає, що він знайшов шлях до Гробниці.\n\n<Старійшина Ара здригається.>\n\nПопри сумніви старійшини Крета, ти дові$p(в:ла), що ти союзник. А таких нам бракує.\n\nКоли наша експедиція прибула до Зерет Мортіс, ми виявили сплячий дороговказний камінь. Якщо ти й справді Той, Хто Ходить Пащею, то, як кажуть пророцтва, ти зможеш його активувати.\n\nЯкщо твої союзники здатні врятувати це священне місце, нам слід відкрити до них шлях.\n\nХодімо.",
        objectives = "Відкрий дороговказний камінь до Орибоса.",
        completion = "Ходаче Пащі! Дякувати Світлу, ви з Пелагосом цілі!",
    },
    [64958] = {
        title = "Війська збираються",
        description = "Я радий, що ти пережи$p(в:ла) перехід до Зерет Мортіс. З того, що я почув із розмови Пелагоса з Клеєю, у тебе була неймовірна подорож.\n\nЦі Просвітлені посередники можуть стати цінними союзниками. Їхні знання про автома й саму цю землю стануть нам у пригоді проти Тюремника.\n\nНаші війська зібрані й готові рушити за тобою до Зерет Мортіс.\n\nПеред нами остання битва, {name}.",
        objectives = "Поговори зі старійшиною Кретом у Зерет Мортіс.",
        completion = "Ти захисти$p(в:ла) Прихисток, а тепер приводиш союзників, щоб уберегти цю священну землю.\n\nБлагословення Перших на тебе, смертн$p(ий:а).",
    },
    [64959] = {
        title = "Душа видри",
        description = "<Душа видри прудка й хвалькувата. Віднині ти можеш прибирати подобу видри.>",
        objectives = "Принеси Душу Видри Чуфі в Серце Лісу.",
    },
    [64960] = {
        title = "Нагодуй кільчастих",
    },
    [64961] = {
        title = "Душа кота",
        description = "<Душа кота елегантна й допитлива. Віднині ти можеш прибирати подобу кота.>",
        objectives = "Принеси Душу Кота Чуфі в Серце Лісу.",
    },
    [64962] = {
        title = "Як було провіщено",
        description = "Сфери на місці. Здіймається мелодія. Іди — приведи хор Провидців, щоб міг початися цикл переродження.",
        objectives = "Приведи Фіріма та Провидців до центру.",
        progress = "Пісня чекає на свій хор.",
        completion = "Шелест творення, шепіт у пітьмі. Можемо починати.",
    },
    [64963] = {
        title = "Прохання перебіжчика",
        description = "<Розгорнувши сувій, ти можеш розібрати, що це зашифрована вимога зброї від малдраксійців із Краю Смерті до їхніх союзників-вентирів... усі вони слуги Тюремника.\n\nХтось із Поступу Смерті в Кортії напевно зможе допомогти тобі повністю зламати шифр і дізнатися, що саме вони замислювали.>",
        objectives = "Достав послання герцогині Мінкс у Притулок Хранителя в Кортії.",
        completion = "<Герцогиня Мінкс переглядає принесений сувій, і її обличчям розпливається усмішка. За мить із неї виривається розкотистий сміх.>\n\nСили Тюремника користуються такими жалюгідними шифрами! У цьому твоєму сувої не сказано, де саме, але, схоже, десь на нових власників чекає схованка зі зброєю. Загін твоїх союзників зможе все розвідати й забрати її без особливих клопотів.",
    },
    [64964] = {
        title = "Вибери свого бійця",
        description = "Присутність сил Тюремника в Провіс-Страті завдає краю невимовної шкоди. Якщо їх не спинити, ми втратимо всі знання цієї місцевості.\n\nОдин із наших родичів підготував кілька автома, щоб дати відсіч приплічникам Пащі. Зустрінься з ними й дай бій тим, хто отак зневажає Зерет Мортіс.",
        objectives = "Вибери конструкт автома й застосуй його проти приплічників Пащі.",
        progress = "Завдання виконано?",
        completion = "Гарна робота.",
    },
    [64969] = {
        title = "У самій гущі",
        description = "Тепер я розумію, чому Старійшина Нірав сповнений тривоги.\n\nБагато прочан, що вирушили до Станцій Каталізатора, так і не повернулися. Серед них Фероз, який, найпевніше, має потрібні нам відомості, щоб відновити рештки.\n\nГотуйся. Біля Каталізатора аж кишить новітніми витворами Перших. Якщо там щось пішло не так, це може бути смертельно небезпечно.",
        objectives = "Зустрінься зі Старійшиною Арою біля Станцій Каталізатора.",
        completion = "Фероз пояснив, що сталося зі зниклими прочанами.\n\nВони в пастці всередині Оберегів Каталізатора!",
    },
    [64970] = {
        title = "Витертий часом ключ-камінь: Зламані острови",
        description = "Нещодавно до мене потрапив незвичайний ключ-камінь. Він може здаватися старим і витертим, та я певен, що йому ще є про що розповісти.\n\nВізьми його із собою. Можливо, він стане нагадуванням про давно минулі пригоди. Пригоди, про які ти, звісно ж, неодмінно мені розкажеш.",
        completion = "Твої розповіді про пригоди просто захопливі, $p(друже:подруго)! Прошу, дозволь запропонувати тобі знак моєї вдячності.",
    },
    [64974] = {
        title = "Приберіть у проході Автома",
    },
    [64977] = {
        title = "Крок на арену",
        description = "Одна з дивовижних рис, які ми відкрили в цих землях, — те, що вони, попри всю свою прадавність, начебто здатні пристосовуватися й змінюватися. Тут ніщо не стоїть на місці.\n\nУ глибинах Нексуса Втілення є кузня, яка, схоже, створена для того, щоб випробовувати ці різноманітні задуми й учитися на них. Колись ці створіння можуть стати в пригоді для захисту Зерет Мортіс від загроз, тож тобі варто перевіряти їхню дієвість, де лиш можна.\n\nВирушай туди, кинь виклик тому, що породжує кузня, і повернися до мене зі звітом.",
        objectives = "Здолай породжені творіння в Нексусі Втілення.",
        completion = "Який дивовижний пристрій. Певна річ, його витворам явно є куди вдосконалюватися. Та, можливо, він засвоїть уроки, які ти йому да$p(в:ла).",
    },
