    [65031] = {
        title = "Поля битв",
        description = "Звитяжці Орди й Альянсу й далі б'ються на незліченних полях битв. Посередники картелю Зо платять бійцям, щоб спостерігати за їхньою тактикою.\n\nЧи відгукнешся ти на поклик і кинешся в бій?",
        objectives = "Поговори з Тал-Інарою.",
        completion = "Посередники картелю Зо, безперечно, будуть задоволені твоїм вибором.",
    },
    [65032] = {
        title = "Спостерігачі за полем бою",
        description = "Зо'сорга та інших посередників картелю Зо ти знайдеш одразу далі по коридору.\n\nВони, безперечно, радо почують, що масштабні битви теж входять до Призначення.",
        objectives = "Поговори зі стратегом Зо'раком в Орибосі.",
        completion = "Картель Зо — надійний партнер. Ти зроби$p(в:ла) добрий вибір.",
    },
    [65033] = {
        title = "Спостереження за перемогою",
        description = "Нитки долі покликали тебе у світ протистояння, {name}.\n\nЧи приймеш ти виклик, який кидають тобі суперники в боротьбі за території? Чи зійдешся з ними в бою і здобудеш перемогу?\n\nЯкщо дозволиш мені поспостерігати за твоєю перемогою, я гідно її винагороджу.",
        objectives = "Здобудь перемогу на будь-якому полі бою.",
        completion = "Перемога ніколи не гарантована. Повертайся завтра — на нове спостереження.",
    },
    [65034] = {
        title = "Повернення до Орибоса",
        description = "Повертайся завтра — на нове спостереження.\n\nА доти Тал-Інара допоможе спрямувати твої зусилля в потрібне русло.",
        objectives = "Поговори з Тал-Інарою в Орибосі.",
        completion = "Картель Зо високо цінує твої зусилля. Призначення очевидне.",
    },
    [65035] = {
        title = "Повернення до Орибоса",
        description = "З тобою було чудово працювати, Ходоку Пащі. Тобі варто віднести ці відомості тому, хто тебе сюди прислав.\n\nЯ? О, я лишаюся тут зі своєю корисною скринькою.\n\nЗаходь, коли захочеш. Може, у мене навіть знайдуться для тебе нові завдання!",
        objectives = "Поговори з Тал-Інарою в Орибосі.",
        completion = "Тобі трапилися божевільний посередник і... скринька? \n\nДобре, що ти поверну$p(вся:лася) ціл$p(им:ою), Ходаче Пащі.",
    },
    [65036] = {
        title = "Тренуйся так, як б'єшся",
        description = "Стрибки крізь обручі допомагають освоїтися, але ми тренуємося так само, як б'ємося, — невблаганно.\n\nПолітай Ширянням околицями, доки не відчуєш, що цілком володієш технікою. Звісно, зважай на місцеву звірину й видивляйся можливі загрози — зрештою, саме для цього ми й тренуємося.\n\nКоли відчуєш готовність, повертайся до Емберталь зі звітом. Щасти!",
        objectives = "Повправляйся в Ширянні.",
        progress = "Вітер набирає сили.",
        completion = "Часу обмаль. Насувається буря.",
    },
    [65045] = {
        title = "Кратер Штормолам",
        description = "Донесення Дервішіан тривожне. Ворожі сили, що звуть себе первісниками, вдерлися до кратера Штормолам і затиснули Чорну Луску в Облоговому Гніздів'ї.\n\nЗагарбники прикликають лютих елементалів і вербують до своїх лав жорстоких тарасеків.\n\nАзурателю знадобиться твоя допомога біля кратера. Крилом чи кігтем — врятуй наших.\n\nКоли Чорна Луска буде в безпеці, попроси їхнього командира прибути до мене. І застерігаю: Саркарет буває... колючим.",
        objectives = "Зустрінься з Азурателем біля кратера Штормолам.",
        completion = "Що ж, {class}, сподіваюся, ти готов$p(ий:а) забруднити кігті.",
    },
    [65046] = {
        title = "Первісники",
        description = "Мої спогади після стазису досі затуманені, але я певна: ми вже стикалися з цими первісниками.\n\n<Дервішіан зціплює ікла.>\n\nМарно. Намагатися згадати — однаково що ганятися за уламками сну.\n\nМоже, тобі пощастить більше. Пошукай будь-які підказки: що — чи хто — стоїть за цими загарбниками.",
        objectives = "Знайди підказки про походження й наміри первісників.",
        completion = "Первісник говорить про те, щоб вивільнити жахливу бурю.\n\nНевже десь на Обширі замкнено ще більшу загрозу?",
    },
    [65049] = {
        title = "Сутичка з тарасеками",
        description = "Тарасеки непередбачувані й дикі. Сказати б, первісні драконіди.\n\nНелтаріон мав їх заледве не за гарматне м'ясо — за мішені для нашого вишколу. Але вони хитрі мисливці, а в зграях — смертельно небезпечні.\n\nЯкщо первісники наділять їх силою стихій, вони стануть ще небезпечнішими.\n\nМи не можемо цього допустити, {name}. Прорідь їхні лави.",
        objectives = "Убий 7 тарасеків.",
        completion = "Не журися за кількома тарасеками.\n\nДе є один — там у тінях чигають десятки.",
    },
    [65050] = {
        title = "Прикликана армія",
        description = "Ці первісники прикликають цілу армію елементалів. Треба виходити з того, що вони збираються спустити її на наші сили.\n\nЩо ж, не на нашій варті.\n\nПролий на них дощ вогню, пробуджувач! Випали цих елементалів з Обширу й розберися з їхніми заклиначами, поки ті не прикликали нових.",
        objectives = "Убий 12 прикликаних елементалів.",
        progress = "Звідки вони черпають усю цю силу? І задля чого?",
        completion = "Прикликані елементалі — може, й не найдостойніший супротивник, але як же приємно знову розправити крила.",
    },
    [65052] = {
        title = "Чорна Луска",
        description = "Ми прорвалися крізь вторгнення первісників. Тепер треба дістатися гніздів'я.\n\nЛускокомандир Саркарет — міцний горішок, і його вейрн тримає оборону. Але Чорну Луску притиснув до землі дракон.\n\nЧас і нам вступити в бій!\n\nІди попереду. Дай сигнал, щойно дракон буде в межах досяжності. Тоді вдаримо по ньому всім, що маємо.\n\nСтережися засідок. У мене погане передчуття.",
        objectives = "Дістанься лускокомандира Саркарета.",
        completion = "Ти добре б'єшся, {class}, але ми й самі давали собі раду.\n\nЧорна Луска дбає про своїх.",
    },
    [65053] = {
        title = "Велетенський легенекап",
    },
    [65054] = {
        title = "Тренувальні манекени",
    },
    [65055] = {
        title = "Захисні жаровні",
    },
    [65056] = {
        title = "Не дай йому вислизнути",
    },
    [65057] = {
        title = "На збір до Емберталь",
        description = "Бій скінчився — і ти просиш мене з'явитися з доповіддю до Емберталь. Азуратель гадає, що я виконуватиму його накази?\n\nНе думаю.\n\nЧорна Луска кориться лише Вартовому Землі. А від Нелтаріона я наказів поки не отримував.\n\n<Саркарет супиться.>\n\nУтім, я не сліпий і бачу загрозу, яку несуть ці первісники. Я певен, що вже бився з такими, як вони, і все ж...\n\nМи прибудемо на плацдарм, щойно мої бійці оговтаються. Можеш іти, пробуджувач.",
        objectives = "З'явися з доповіддю до Емберталь.",
        completion = "Первісники наділили свого ватажка силою в якомусь ритуалі?\n\nРозповідай мені все.",
    },
    [65060] = {
        title = "Кальдера Цілителів",
        description = "Твоє видіння біля арканного маяка показало, що в хортах замкнені драктири. Ми не можемо дозволити собі втратити ще когось із наших.\n\n<Емберталь замовкає, насупивши брови.>\n\nЦілющі Крила — найкращі медики в наших лавах. Їхній хорт лежить у Кальдері Цілителів. Сіндретреш знає дорогу.\n\nНе покинь там нікого, пробуджувачу.",
        objectives = "Зустрінься із Сіндретреш у Кальдері Цілителів.",
        completion = "Поглянь, скільки поранених...\n\nУсередині ще цілителі. Треба їм допомогти!",
    },
    [65063] = {
        title = "У вулик",
        description = "Хоч який токсин розповзся цим хортом, він досить сильний, щоб звалити наших найкращих цілителів.\n\nЦе не віщує нічого доброго ні мені, ні тобі, {name}.\n\nТа байдуже. Всередині в пастці драктири. Ми йдемо туди, хай який ризик.\n\nВдихни глибше — і за мною!",
        objectives = "Іди за Сіндретреш, щоб знайти Віридію.",
        completion = "Добре. Ти прийш$p(ов:ла) до тями.\n\n<Віридія відкашлюється, прочищаючи горло.>\n\nНам просто зараз потрібні вміння {class}.",
    },
    [65064] = {
        title = "Дивись, кого я знайшов!",
        description = "Поглянь на це чудове створіння!\n\nСайло каже, що в нас немає ресурсів ще на одного мого «ненормального улюбленця».\n\nАле, можливо, ми зуміємо змінити Е'рні так, щоб я міг лишити його собі. Це середовище по-дивному впливає на тутешніх створінь. Може, вдасться зробити його меншим.\n\nЯ знаю місце, де можна провести наше дослідження. Неподалік ростуть квіти, які називають барвистими розидами, — вони можуть викликати реакцію. Чому б тобі не зібрати кілька дорогою?",
        objectives = "Роздобудь 6 барвистих розид біля Вимірних водоспадів.",
        progress = "Треба знайти спосіб залишити Е'рні.",
        completion = "Мабуть, перш ніж випробовувати щось на Е'рні, варто поекспериментувати на інших піддослідних.",
    },
    [65065] = {
        title = "Рогарти",
        description = "О, перепрошую, але ми не знали, що ваш народ живе на цьому острові. Ми лише нещодавно прибули до цих берегів у пошуках вільної землі, яку могли б назвати домівкою. Ми не маємо лихих намірів і підемо далі, якщо ця земля справді заборонена.\n\nМій син То'но дуже любить драконідів усіх видів, і я певна, що в нього знайшлося б до тебе чимало запитань. Він мій маленький дослідник. Якщо побачиш його раніше за мене, знай: на тебе може посипатися ціла купа запитань.\n\nІ куди ж подівся цей малий пустун...?",
        objectives = "Знайди То'но й познайомся з ним.",
        completion = "Ой! Драконід! Ти худіш$p(ий:а) за інших. Ой! І в тебе крила! \n\nЕм... поможи?",
    },
    [65066] = {
        title = "Квітковий аромат",
        description = "Мабуть, не варто експериментувати з Е'рні, доки ми не знаємо наслідків.\n\nПритримай решту цих розид. Проведемо ще кілька випробувань. Деякі створіння тут, біля водоспаду, сумирніші за інших — вони підійдуть для таких дослідів.\n\nЗ'ясуймо, чи по-різному різні створіння реагують на аромат розид.",
        objectives = "Поекспериментуй із барвистими розидами біля Вимірних водоспадів.",
        progress = "У цих розид такий дивний аромат... Можливо, різні створіння відгукнуться на нього по-своєму.",
        completion = "Ці результати якісь... неоднозначні.",
    },
    [65067] = {
        title = "Колба посередника",
        description = "До твого приходу я й сам проводив тут деякі експерименти.\n\nТі випробування... минули не надто добре. Виявилося, що деякі складники з довкілля можуть розлютити створінь: навіть найсумирніші стають хижаками.\n\nЯ впустив свій контейнер зі складниками й кинувся тікати, а тепер не пригадаю, де його лишив.\n\nКолба має бути десь серед стада хижих оленів. Якщо ці квіти не подіють, той контейнер знадобиться нам для наступних випробувань.",
        objectives = "Забери Колбу зі Складниками в м'ясоїдних цервідів біля Вимірних водоспадів.",
        progress = "Обережно з тими хижими оленями — вони кусаються!",
        completion = "Ага. Це неодмінно стане в пригоді.",
    },
    [65068] = {
        title = "Величні каскади",
        description = "Багато створінь тут, біля Вимірних водоспадів, особливо чутливі до впливу довкілля. Гм... поекспериментуймо із самими водоспадами!\n\nМи бачили неповторні ефекти від різних природних складників тут, у Зерет Мортісі. Чому б не спробувати й воду?\n\nНабери трохи води, а тоді побризкай нею на створіння біля водоспадів і поглянь, що станеться.",
        objectives = "Поекспериментуй із водою водоспадів у Вимірних водоспадах.",
        progress = "У цих водоспадах, певно, криється магія, якої нам навіть не осягнути.",
        completion = "Це було несподівано.",
    },
    [65069] = {
        title = "Приборкання виру",
        description = "Ті маленькі двійники Е'рні виявилися не надто приязними.\n\nЇх породив якийсь ефект водоспадів. Вони нестабільні. Ти бачи$p(в:ла), куди вони поділися?\n\nЇх треба знищити, доки вони не нашкодили решті місцевої живності. Подбай про це, поки я візьму ще один зразок із водоспадів.",
        objectives = "Убий 50 двійників Е'рні.",
        progress = "Ти знайш$p(ов:ла) двійників?",
        completion = "Ой леле... що з тобою сталося?",
    },
    [65070] = {
        title = "Можна, я лишу його собі?",
        description = "О ні. Я влаштував хаос у цьому священному місці.\n\nПоглянь. Е'рні прив'язався до тебе. Мені боляче це казати, але ти будеш йому кращим опікуном, ніж був я.\n\nКоли ми все владнаємо, забери його собі.\n\nПринаймні тепер ми знаємо, що водоспади здатні змінювати розмір створінь. Спробуймо ще раз.",
        objectives = "Хлюпни водою на Е'рні.",
        progress = "Якщо не спрацює — завжди можна спробувати ще раз!",
        completion = "Спрацювало! Не знаю, як і дякувати тобі за допомогу. Тепер він твій. Добре про нього дбай.\n\nПрощавай, Е'рні.",
    },
    [65071] = {
        title = "Рятуйте!",
        description = "Мені потрібна допомога!\n\nЯ То'но, я досліджував усе довкола, бо це в мене найкраще виходить, але я не помітив, що за мною пішла моя сестричка Ко, і мені треба, щоб ти допоміг мені знайти її, бо вона в біді, тож будь ласка, допоможи, будь ласка?\n\nВона зайшла в цю печеру, але вона ховається не так добре, як я, а наші батьки надто далеко, щоб допомогти.\n\nТи зможеш знайти її раніше, ніж це зроблять монстри?",
        objectives = "Врятуй малу Ко.",
        completion = "Ти знайш$p(ов:ла) моїх малят!",
    },
    [65072] = {
        title = "Небезпечна робота",
        description = "Відкриття Раною реліквій Прабатьків біля Позачасових Уламків неабияк сколихнуло Просвітлених. Ці реліквії давніші за всі наші попередні знахідки, і завдяки їм ми, можливо, глибше зрозуміємо устрій Зерет Мортіса.\n\nРана збирає реліквії, але я боюся, що вона в небезпеці. У цій місцевості помічено агентів картелю Ксай, і вони, найпевніше, спробують викрасти реліквії.\n\nПрошу, вирушай до Позачасових Уламків і допоможи Рані зібрати реліквії.",
        objectives = "Допоможи Рані в пошуках і збери 8 реліквій Прабатьків.",
        progress = "Чи зібрано реліквії Прабатьків?",
        completion = "Ми завжди вдячні за твою допомогу, {NAME}.",
    },
    [65073] = {
        title = "Токсична проблема",
        description = "Ти швидко приходиш до тями, {name}. Добре.\n\nТі, хто вибрався з мого хорту, вже одужують, але інші досі в пастці всередині. Кинешся їх рятувати — і мені знову доведеться тебе звідти витягати.\n\nДовкола кальдери розкидані гнізда жуків. З їхніх отруйних залоз можна добути засіб проти цієї отрути.\n\nЗібрати їх самотужки мені зараз не до снаги. Мушу покластися на твою вправність, пробуджувачу.",
        objectives = "Збери 6 отруйних залоз.",
        progress = "Часу обмаль.",
        completion = "Добре. Це саме те, що мені було потрібно.\n\nЯ приготую щось проти токсину — і ти зможеш повернутися до хорту.",
    },
    [65074] = {
        title = "Легка здобич",
        description = "У хащах довкола хорту водяться сцитиди — ненажерливі комахоподібні, здебільшого територіальні й агресивні.\n\nУсі наші поранені стали б для цих бестій легкою здобиччю. Не хочу, щоб вони нападали на цілителів, поки ті одужують.\n\nПроріди їхні зграї, поки я подбаю про Віридію.\n\nВона... дуже хоробра.",
        objectives = "Убий 4 сцитидів.",
        progress = "Цілителям не треба зайвих хвилювань.",
        completion = "Сцитиди завжди були грізні, але, схоже, за час нашого стазису вони стали ще більшими й загрозливішими.",
    },
    [65075] = {
        title = "Цілющі Крила",
        description = "Пробуджувачу, прийми мою вдячність за порятунок мого вейрну в найтяжчу для нас годину.\n\nЩойно відновимо сили, Цілющі Крила приєднаються до решти нашого війська.\n\nСіндре каже, що Емберталь втратила весь свій вейрн. Боюся, такої рани не загоїть жодна моя магія.\n\nЕмберталь може здаватися незворушною, та цю втрату вона переживає глибоко, {name}. Перекажи їй, що я вже в дорозі.",
        objectives = "Поговори з Емберталь.",
        completion = "Мені відлягло від серця, що Віридія жива.\n\nЯкщо Дервішіан каже правду, у прийдешній битві нам знадобляться її таланти.",
    },
    [65080] = {
        title = "Аніма, відведена",
        description = "Тепер — вирішальна мить.\n\nСклади всю аніму, яку маєш при собі, до Польового відвідника аніми позаду мене.\n\nЯкщо пощастить, ти не зазнаєш жодних побічних ефектів — втрати аніми, втрати свідомості, втрати пам'яті. Чогось такого.",
        objectives = "Склади аніму до Польового відвідника аніми в Реліквіарії Пам'яті.",
        progress = "Чи вдалося тобі скласти аніму до Польового відвідника аніми?",
    },
    [65081] = {
        title = "Яблуко на день",
    },
    [65084] = {
        title = "Сховище Морозокаменю",
        description = "Поглянь туди, через Обшир! Сили первісників стягуються до Сховища Морозокаменю.\n\nБуря, яку вони прагнуть вивільнити, певно, замкнена всередині.\n\n<Емберталь кривиться, борючись із розбитими спогадами.>\n\nМи вже билися з цим ворогом — і перемогли. Нелтаріон наказав узяти сховище під охорону, але я... не можу пригадати чому...\n\nЗараз не час для роздумів. Приєднайся до Саркарета й Чорної Луски біля сховища. Не дай ворогові прорватися всередину!",
        objectives = "Вирушай на збір до Сховища Морозокаменю.",
        completion = "Тримайся, {class}. Чорна Луска покладе край цьому вторгненню.",
    },
    [65087] = {
        title = "Скарб усередині",
        description = "Тож первісники хочуть того, що лежить у цьому сховищі?\n\n<Саркарет примружує очі.>\n\nНехай приходять.\n\nМи покажемо їм, для чого народилися драктири!",
        objectives = "Захисти сховище.",
        progress = "Ми обороняємо не хорт. Ми обороняємо щось значно небезпечніше. Я це відчуваю.\n\nМагія за тим бар'єром рветься назовні. Тримай позицію й НЕ пропускай цих первісників.",
        completion = "Нас заполонили! Вони ось-ось прорвуться до сховища!\n\nДе ті чорні дракони?!",
    },
    [65089] = {
        title = "Жабомить",
    },
    [65090] = {
        title = "Поверни ще загублених душ",
        description = "Душі досі ринуть до Пащі. Чи можеш ти знову вирушити туди, щоб урятувати ще?\n\nМи мусимо зірвати його плани.\n\nПовертайся до Пащі й урятуй усіх, кого зможеш.",
        objectives = "Врятуй 20 душ у Пащі.",
        completion = "О, ти знайш$p(ов:ла) ще стільки гідних душ!\n\nЯ подбаю, щоб тут, в Арденвельді, про них добре піклувалися.",
    },
    [65096] = {
        title = "Твоя смерть або моя",
        description = "Ми здобули безліч відомостей із реліквій, знайдених біля Позачасових Уламків.\n\nПрислужники Пащі знають про наші відкриття й намагаються нас спинити. Вони наставили пасток довкола, щоб перекрити доступ до реліквій.\n\nМи не можемо дозволити Тюремнику відрізати нас від цих реліквій.\n\nБудь ласка, усунь цю загрозу від прислужників Пащі й поверни якомога більше реліквій.",
        objectives = "Убий карателя Макаріса і збери 6 Священних Реліквій.",
        progress = "Чи вбезпечено реліквії біля Позачасових Уламків?",
        completion = "Благословенні твої зусилля!",
    },
    [65097] = {
        title = "Тікай!",
        description = "Бурі ось-ось накриють нас! Ми мусимо евакуюватися!\n\nРятуй усіх, кого можеш. І знайди тих чорних драконів!",
        progress = "Який... біль.",
        completion = "Дякую, {NAME}. \n\nТвоя допомога несподівана... але дуже доречна.",
    },
    [65098] = {
        title = "Ціна відваги",
        description = "Дякую, що зціли$p(в:ла) мене, {name}. Сподіваюся, ми здобуваємо довіру одне одного.\n\n<Вратіон здригається.>\n\nПожирачка Бур. Я ще ніколи не стикався з драконом такої первісної стихійної сили. Якщо є й інші, як вона...\n\nСтривай... де Ебіссіан? Він уцілів? Ти мусиш його знайти!",
        objectives = "Знайди Ебіссіана.",
        completion = "Яке полегшення, що ти вибра$p(вся:лася), {NAME}.\n\nАле я... не можу позбутися відчуття розгубленості.",
    },
    [65100] = {
        title = "Останні накази",
        description = "Буря, яку вивільнила Расзаґет, надто потужна. Ми мусимо покинути єдину домівку, яку будь-коли знали.\n\nБільше немає Вартового Землі, який командував би нами. Уперше ми вільні робити власний вибір. Самі шукати свою долю.\n\nХай куди ти пода$p(вся:лася) в цю нову добу — сподіваюся, ти знайдеш гідних союзників. Розкажи їм нашу історію.\n\nЩодо мене — я лишуся тут і шукатиму вцілілих. Можливо, дорогою знайду відповіді про наше минуле.\n\nХай доля сприяє нам усім, {name}.",
        objectives = "Організуй евакуацію Забороненого Обширу.",
        progress = "Ми відлітаємо! Хто б міг подумати, що все буде саме так, — але ми повернемося, підготувавшись краще.",
        completion = "Вратіон розповідає про спільноту, що зветься Альянсом. Шляхетний народ, який дбає одне про одного й боронить цей світ.\n\nВін запропонував відрекомендувати нас їхнім очільникам у місті, що зветься Стормвінд. Ходімо, {NAME}.",
    },
    [65101] = {
        title = "Знакова драконяча подоба",
        description = "Своєю появою ти змуси$p(в:ла) усіх у Стормвінді обернутися, {name}. Поза сумнівом, дехто з містян поставився до твоєї присутності... прихильніше за інших.\n\nЩоб краще спілкуватися з іншими расами, ми, дракони, прибираємо смертну подобу — на кшталт тієї, яку ти бачиш перед собою. Це не лише заспокоює союзників, а й значно полегшує прохід крізь двері.\n\nОчевидно, есенція драконячої зграї тече в драктирах. Підозрюю, що й ти маєш нашу здатність прибирати подобу.\n\nХодімо зі мною.",
        objectives = "Прибери свою смертну подобу.",
        progress = "Смертні бувають такими знервованими поруч із вищими істотами.",
        completion = "Твоя подоба тобі дуже личить, {NAME}. Такої я ще не бачив!\n\nМожливо, коли ми дізнаємося більше про твоє походження, то зрозуміємо, чому подоба {race} відрізняється від драконової.\n\nА тепер на нас чекає підготовка до експедиції.",
    },
    [65102] = {
        title = "Риб'ячі очі",
    },
    [65103] = {
        title = "Поверни ще загублених душ",
        description = "Душі досі ринуть до Пащі — ми мусимо триматися наміченого й знаходити ще гідних душ.\n\nПовертайся до Пащі й рятуй усіх, кого зможеш.",
        objectives = "Врятуй 20 душ із Пащі.",
        progress = "Немає долі, гіршої за Пащу. Чи вдалося знайти ще?",
        completion = "Чудово. Я знаю: ми зможемо вберегти від цього воістину жорстокого животіння ще більше душ.",
    },
    [65104] = {
        title = "Поверни ще загублених душ",
        description = "Ходоку Пащі, ми мусимо зробити більше, щоб позбавити Тюремника сили й не дати йому жодної душі.\n\nПовертайся до Пащі й урятуй усіх, кого зможеш.",
