    [65349] = {
        title = "Втрачена благодать",
        description = "Води Джерела більше не течуть.\n\nТворіння Перших ще ніколи нас не підводили. Прочани починають замислюватися... чи не розгнівалися Перші?\n\nНехай собі питають, але МОЯ віра лишається непохитною. І, як я й очікував, Перші, схоже, послали нам відповідь.\n\nТебе, певна річ.\n\nСтародавні дослідження й тексти вказують, що витік Джерела — у підземному храмі в Провіс-Еспері. Іди, я вірю, що ти відновиш Джерело.",
        objectives = "Вирушай до Провіс-Есперу.",
        completion = "<Цього автома розтерзали пожирачі. У руці він стискає дивний предмет.>",
    },
    [65350] = {
        title = "Відновити потік",
        description = "Поглянь! Пожирачі прорвалися крізь оборону храму. Ці ненажерливі почвари живляться будь-якою енергією, яку лише знайдуть. Їх, певно, привабила сила Джерела.\n\nЗ такими завадами не дивно, що води спинилися!\n\nВідповідь має бути всередині Локрійського Еспера. Опинившись там, спробуй знайти спосіб виправити заподіяну шкоду.",
        objectives = "Знайди спосіб відновити Локрійський Еспер.",
        progress = "<Консоль гуде від енергії.>",
        completion = "<Схоже, твої зусилля увінчалися успіхом — води знову течуть храмом. Джерело має відновитися.>",
    },
    [65351] = {
        title = "Реасиміляція схеми: резонансне відлуння",
        description = "<Ця схема містить взірець нової протоформної конструкції. Принеси її до відповідної протоформної кузні, і вона, можливо, створить для тебе одну з цих істот.>",
        objectives = "Принеси схему до відповідної протоформної кузні.",
        completion = "<Протоформна кузня видзвонює тужливу пісню, вбираючи схему.>",
    },
    [65353] = {
        title = "Дієта без автома",
        description = "Ці пожирачі невблаганні! Вони живляться будь-якою енергією, яку знайдуть. Якщо їх не спинити, вони неодмінно пожеруть увесь Зерет Мортіс. Ми не можемо дозволити, щоб ці загарбники споганили творіння Перших!\n\nЯ не воїн. Але ти... можливо, Перші все ж таки послали тебе до нас. Допоможеш?",
        objectives = "Убий 10 ненажер-загарбників і руйнівників реальності.",
        completion = "$p(Чужинцю:Чужинко), я... я перепрошую. Мені бракувало довіри до тебе. А з нею похитнулася й моя віра. Пробач мені й прийми мою подяку — твоєю рукою воістину провадять Перші.",
    },
