    [65420] = {
        title = "Питання совісті",
        description = "О ні... Ні-ні-ні... Що я накоїла?\n\nСтарійшини нізащо не приймуть мене назад. Вони виженуть мене так само, як вигнали Фіріма.\n\nПрошу тебе, $p(чужинцю:чужинко), поговори зі старійшиною Аміром у Благодаті Прочанина. Передай йому мою подяку за те, що він прислав тебе, і розкажи все, що тут сталося. Він зрозуміє, чому мені більше не можна повертатися.",
        objectives = "Поговори зі старійшиною Аміром у Благодаті Прочанина.",
        completion = "Тахлі жива? І з її допомогою тобі вдалося зберегти архів автома?! Ох. Це... нелегко осягнути.\n\nІ, звісно, почуття провини не дає їй повернутися додому. Ох, Тахлі.",
    },
    [65421] = {
        title = "Скори кожну вершину",
        description = "Сподіваюся, ти швидко вчишся, {class}. Бо я не маю часу на уроки!\n\nХапай рюкзак і шукай шлях на вершину того піка.\n\nЯк опинишся нагорі, кинь цей парашут нашій подрузі Йіпс. Бідолашна застрягла в ліанах, коли ці повітряні елементалі розбили наш літак!\n\nХутко, щоб ми могли вибратися звідси!",
        objectives = "Візьми спорядження для сходження, знайди виступ і видерися на скелю, щоб урятувати слідопитку Йіпс!",
        progress = "Хутчіш, ну ж бо! Йіпс довго не протримається!",
        completion = "Гарно лазиш! Йіпс тепер винна тобі чарку-другу!\n\nА, елементалі? Та не переймайся ними. Це НАША пригода!\n\n<Рокі знову весело решетить кулями повітряних елементалів.>",
    },
    [65422] = {
        title = "Полювати на скарби нелегко",
        description = "Я бачу це в твоїх очах: тобі кортить вилізти на вершину цієї гори й дізнатися, що там нагорі!\n\nМи, скелелази, завжди впізнаємо одне одного. Не дамо жодній горі змусити нас почуватися малими, еге ж?\n\nЩо ж, тобі пощастило — я прихопив чимало спорядження для лазіння. Хапай рюкзак і шукай шлях нагору!",
    },
    [65426] = {
        title = "Втрачений компонент",
        description = "Ходоку Пащі! Поглянь.\n\nМи вже певний час вивчаємо цей компонент автома. Його шифри схожі на ті, що в компонентів поблизу Сховища Протоформ і всередині нього.\n\nОстання праця Коди не має піти намарно. Прошу, поверни цей компонент до сховища, яке відновив наш друг.",
        objectives = "Підбери Протоформний Каталізатор і поверни його до Сховища Протоформ.",
        progress = "$p(Смертний:Смертна) прагне синтезу протоформ.",
        completion = "Вітання, Архітекторе.",
    },
    [65427] = {
        title = "Новий архітектор",
        description = "Архітектори створюють прототипи задумів, щоб втілювати замисли Перших.\n\nЦей архів містив багато таких задумів.\n\nЧастину записів про задуми втрачено або пошкоджено через вторгнення Пащі.\n\nПоблизу виявлено неторкану решітку задуму та інструменти. $p(Смертний:Смертна) здобуде їх, щоб розпочати процес синтезу.",
        objectives = "Збери 1 Решітку Оленя й 3 Протоформні Інструменти та принеси їх до Інтерфейсу Служителя у Сховищі Протоформ.",
        progress = "Чи знайдено необхідні матеріали?",
        completion = "Успіх. \n\nСховище Протоформ відновлено.",
    },
    [65431] = {
        title = "Подальше дослідження: аеалійська",
        description = "Ходоку Пащі, ти зроби$p(в:ла) чимало дивовижних відкриттів, але таємниці ще лишаються.\n\nПерший крок позаду — консоль розблоковано, і я вірю, що ти готов$p(ий:а) до наступного.\n\nПрошу, дослідь консоль — побачиш, яка нова частка візерунка тобі відкриється.",
        objectives = "Дослідь консоль шифрів у Лощині Вигнанця глибше.",
        progress = "Іди поглянь, які таємниці на тебе чекають!",
        completion = "Нові знання! Перші воістину залишили дивовижні прозріння.",
    },
    [65432] = {
        title = "Подальше дослідження: деалійська",
        description = "<Консоль гуде таємничою енергією.>",
        objectives = "Продовж дослідження консолі шифрів у Лощині Вигнанця.",
