    [65435] = {
        title = "Драконові острови чекають",
        description = "Герої Орди, я приніс новини. Драконові острови пробуджуються!\n\nОстрови поринули в сон після Розколу. Та нині, нарешті, вони покликали мене та моїх родичів додому.\n\nХоч Острови й приховують безліч чудес, це також небезпечний край. Нам знадобиться допомога наших смертних союзників, щоб повернути нашу спадщину.\n\nЯ маю невдовзі представити запрошення Аспектів Раді Орди в Оґриммарі. Зустрінь мене там — і побачимо, що скаже Рада.",
        objectives = "Зустрінь Ебіссіана в Оґриммарі.",
        completion = "Я вдячний, що ти відгукну$p(вся:лася) на поклик. Твоя відвага стане в пригоді в прийдешній подорожі.",
    },
    [65436] = {
        title = "Драконові острови чекають",
        description = "Дивовижні новини, $p(друже:подруго)! Драконові острови пробуджуються!\n\nМій народ лишив наші землі спати після Розколу. Та нині, нарешті, ми відчуваємо поклик домівки.\n\nХоч Острови й приховують безліч чудес, є тут і небезпеки. Нам знадобиться допомога наших смертних союзників, щоб повернути нашу спадщину.\n\nЗустрінь мене у Стормвінді. Я маю передати запрошення Аспектів Альянсу.",
        objectives = "Зустрінь Вратіона у Стормвінді.",
        completion = "Запрошення Аспектів поширюється й на тебе, друже.",
    },
    [65437] = {
        title = "Запрошення Аспектів",
        description = "Ти прибу$p(в:ла) саме вчасно, {name}.\n\nЯ щойно зустрівся з Радою Орди, і вона прийняла запрошення Аспектів на Драконові Острови.\n\nТе саме запрошення стосується й тебе.\n\nТакож ти, мабуть, помітиш тут, в Оґриммарі, кілька незнайомих облич. Драктири — новоприбулі; більше про них ти дізнаєшся в подорожі, що чекає попереду.\n\nПоговорімо детальніше.",
        objectives = "Поговори з Ебіссіаном.",
        completion = "Для мене честь, що ти вирушиш на батьківщину драконячого роду.\n\nОдин із твоїх союзників радо допоможе тобі підготуватися до того, що чекає попереду.",
    },
    [65438] = {
        title = "Чудовий початок завдання",
        description = "Початок Лазурової протоки.",
    },
    [65439] = {
        title = "Шепіт на вітрах",
        description = "Вітаю, {name}. Давно не бачилися, і шкода, що в нас немає більше часу надолужити згаяне.\n\nАле бачиш, я щойно мав доволі повчальну... ні, радше лиховісну... так, лиховісну розмову зі старим другом.\n\nЗрештою, іноді одкровення буває і тим, і тим.\n\nЯ неодмінно мушу розповісти тобі про те, що дізнався.",
        objectives = "Поговори з архімагом Хадґаром біля Оґриммара.",
        progress = "Наша подорож починається з тебе.",
        completion = "Справді тривожні новини — але тобі слід було знати про небезпеку, що нависла над нами.",
    },
    [65443] = {
        title = "Координація експедиції",
        description = "Приємно познайомитися, я Налейдея Ріверґлім.\n\nЗапрошення відвідати Драконові острови — доволі захоплива перспектива. Правда ж?\n\nРеліквіарій об'єднав зусилля з колегами з експедиції, щоб допомогти скоординувати нашу роботу. Мені, як представниці Експедиції Драконячої Луски, випала честь привітати тебе.\n\nХоча спершу нам треба зібрати ще кількох учасників для нашої подорожі. Почнімо?",
        objectives = "Завербуй дослідників, майстрів і вчених по всьому Оґриммару для експедиції на Драконові Острови.",
        progress = "Ти вже поговори$p(в:ла) з іншими?",
        completion = "Вірю, що ця експедиція завершиться великим успіхом.",
    },
    [65444] = {
        title = "До Драконових островів!",
        description = "Наша передова експедиція висадилася на Драконових островах.\n\nЗавдяки зусиллям тих відважних членів Експедиції Драконячої Луски ми облаштували захищене місце висадки на Драконових островах і налагодили зв'язок із посольством зграї драконів.\n\nТи готов$p(ий:а) супроводжувати нас у наступній подорожі до Драконових островів?",
        objectives = "Сядь на «Непокірну Драконячу Луску» біля вежі дирижаблів під Оґриммаром і вирушай на Драконові Острови.",
        completion = "Ласкаво просимо на Драконові острови!",
    },
    [65445] = {
        title = "Необхідні ресурси",
        description = "Пожирачі поглинають неомоти.\n\nНам потрібні неомоти для важливої роботи зі створення. Без них ми не можемо завершити нашу справу.\n\nЗнищ пожирачів і добудь неомоти.",
        objectives = "Здобудь 30 залишків неомотів і 3 затверділі неомоти з пожирачів у Зерет-Мортісі.",
        progress = "Неомоти зібрано?",
        completion = "Завдання виконано. Дякуємо за допомогу.",
    },
    [65448] = {
        title = "Повернення благодаті",
        description = "<Тепер, коли храм відновлено, а його захист знову діє, Джерело має бути в безпеці від пожирачів. Охоронець Олем захоче дізнатися, що ти тут зроби$p(в:ла).>",
        objectives = "Поговори з охоронцем Олемом і повідом йому добру новину.",
        progress = "Ти повертаєшся — і, як я й очікував, з успіхом.",
        completion = "Як я й гадав — твоє прибуття було задумом Перших. З нетерпінням чекаю на спадщину, яку ти викуєш у цій землі наших творців.",
    },
    [65451] = {
        title = "Тренувальні матеріали",
        description = "Ці протодраки несхожі на жодних, яких я бачив раніше на Азероті.\n\nЇхня луска, схоже, від природи вогнестійка, міцніша за сталь, і при цьому не втрачає гнучкості. Неймовірно.\n\nМої майстри — усі до одного — прагнуть роздобути трохи цієї луски, щоб попрацювати з нею.\n\nПочни з малят. Менша луска має бути податливішою, доки ми не опануємо роботу з нею.",
        objectives = "Зібрати луску первісного протомаляти (20).",
        progress = "Уже дістав луску? Алхіміки нервуються, а від цього нервуюся і я.",
        completion = "<Бос Маґор уважно вивчає луску.>\n\nНаші майстри знайдуть їй добрий ужиток. Дякую.",
    },
    [65452] = {
        title = "Дослідники в небезпеці",
        description = "Не сприймай наукові прагнення експедиції за боязкість, {name}.\n\nМи не самітники, що вивчають книги у віддалених вежах.\n\nМи шукачі пригод, які здобувають знання з перших рук у кожному куточку Азероту!\n\nЦя пристрасть до пригод нерідко веде нас на шлях небезпек і ризиків, і кілька членів експедиції відкусили трохи більше, ніж могли проковтнути...",
        objectives = "Урятувати членів Експедиції драконячої луски на Дикому узбережжі (3).",
        completion = "Драконів тут немає, щоб зустріти нас, як казав Ебіссіан...",
    },
    [65453] = {
        title = "Первісні шкідники",
        description = "<Сіндретреш підозріло поглядає на протодраконів, що чигають на хребті позаду неї.>\n\nКлянуся, ці протодракони підбираються все ближче до табору щоразу, коли я відвертаюся...\n\nЦе не ті дракони, з якими Ебіссіан запросив нас зустрітися.\n\nПротодракони — безжальні хижаки, з якими годі домовитися. Ми мусимо відповісти їм тим самим.\n\nПроріди їхні ряди, щоб стримати їхню зухвалість, інакше ця експедиція скінчиться, не встигнувши початися.",
        objectives = "Убити первісних протодраків на Дикому узбережжі (8).",
        completion = "Це, можливо, відвадить їх від нападів на табори виправи на якийсь час.\n\nНа Драконових Островах — або ти їси, або з'їдять тебе, {NAME}. Варто це запам'ятати.",
    },
    [65456] = {
        title = "Давно загублений Фірім",
        description = "Я збирав тут дані, коли відкрився твій портал. Це збурення активувало механізми, що замикають ворота.\n\nТож буде цілком справедливо, якщо ти збереш ключі від воріт, чи не так? Поговоримо, поки ти шукатимеш.",
        objectives = "Допоможи Фіріму відчинити ворота до Зерет-Мортіса.",
        progress = "А тепер — далі.",
        completion = "Сили й терпіння в тобі більше, ніж здається на око.",
    },
    [65460] = {
        title = "Твій перший кантарійський протозамок",
        description = "Ходоче Пащі, схоже, Покопок опанував уміння Качіал. Це дає тобі доступ до Сховків Творіння. Ти знайдеш кілька видів цих сховків по всьому Зерет-Мортісу.\n\nЩоб допомогти мені в моїх дослідженнях, тобі треба навчитися розшифровувати різні шифри, як-от кантарійський протозамок.\n\nА тепер дозволь показати тобі, що потрібно робити, щоб мені допомагати.",
        objectives = "Розгадай кантарійський протозамок.",
        progress = "Добре. А тепер застосуй свої нові знання на ділі.",
        completion = "Чудова робота, Ходаче Пащі.\n\nПевен, за достатньої енергії та зусиль твій супутник зможе допомогти тобі здолати ці випробування, якщо вони виявляться заважкими.",
    },
    [65461] = {
        title = "Твій перший меццонічний протозамок",
        description = "Щоб допомогти мені в дослідженнях, тобі доведеться розшифровувати різноманітні шифри Прабатьків, як-от меццонічний протозамок. Зараз я покажу тобі, що треба робити.",
        objectives = "Розгадай меццонічний протозамок.",
        progress = "Використай ці знання, щоб зібрати більше даних на місцях.",
        completion = "Скористайся цими знаннями й збери більше даних, Ходаче Пащі.\n\nЛишився ще один Сховок Творіння, про який я маю тобі розповісти.",
    },
    [65463] = {
        title = "Джерело Перших",
        description = "$p(Смертний:Смертна), тут? Як незвично! Ласкаво просимо до Благодаті Прочанина. Шкода, що ти прибу$p(в:ла) не за кращих обставин. Зазвичай прочани приходять сюди, щоб відвідати священне Джерело Перших.\n\nНа жаль, Джерело пересохло. Я цього не розумію. Творіння Перших мали б бути бездоганними!\n\nЦя ситуація така ж незвична, як і твоя поява — можливо, ти зможеш допомогти? Вирушай до Джерела й поговори з охоронцем Олемом.",
        objectives = "Поговори з охоронцем Олемом про проблему Джерела Перших.",
    },
    [65466] = {
        title = "Твій перший фуґальний протозамок",
        description = "Щоб допомогти моїм дослідженням, тобі доведеться розшифровувати різноманітні шифри Прабатьків, як-от фуґальний протозамок. Це найскладніший шифр, тож я покажу тобі, що треба робити.",
