    [65563] = {
        title = "Доставка для Касеї",
        description = "Сподіваюся, ти не образишся, але я взяв трохи твоїх матеріалів, щоб змайструвати дещо, про що мене просила Касея.\n\nНе занесеш їй це?",
        objectives = "Достав Шолом із Лезами Касеї Енджерфордж.",
        completion = "То Тургаден нарешті впорався? І передав саме з тим, з ким треба!",
    },
    [65564] = {
        title = "Гарний вогняний хлопчина",
        description = "Я тренґую гончаків усіх порід, аби лиш вони були вогняні. Оцього Грімгаула я виховую ще відколи він був малим цуценям, та життя в Місті Тіньової Кузні — не для нього!\n\nГрімгаулу потрібен хтось особливий, щоб заприятелювати, хтось, хто візьме його у мандри всім Азеротом. Може, це будеш ти?\n\nПобудь із ним трохи, познайомся. Гадаю, Грімгаул дуже швидко до тебе прихилиться!",
        objectives = "Заприятелюй із Грімгаулом.",
        progress = "Якщо заприятелюєш із цією звірючкою, матимеш вірного супутника на все життя!",
        completion = "Ти йому подобаєшся, справді подобаєшся! Стався до цього цуцика з любов'ю — і він на довгі роки стане твоїм напарником у пригодах.",
    },
    [65594] = {
        title = "Робити з гнола слона",
        description = "Дурний розклад думати, що він головний, але головний я. Ми його зараз уб'ємо. Я зробив зі слизу друзів.",
        objectives = "Знищ 3 тотеми гнилі.",
        progress = "ВІН ТАКИЙ СТРИБУЧИЙ!",
        completion = "Ти прожити так довго? Добре м'ясо.",
    },
    [65595] = {
        title = "Одне гниле яблуко",
        description = "Гниль морить гнолів голодом.\n\nГниль ранить друзів.\n\nМи зараз уб'ємо гниль. Так роблять Мон-Арки.",
        objectives = "Убий Корінь Гнилі.",
        completion = "Я тепер вести гнолів на кращі лови. Ти... не таке вже погане. Але гноли голодні, а ти досі м'ясо.\n\nІди. Я не гнатися.",
    },
    [65598] = {
        title = "Шанувати Елуну",
        description = "Храм Елуни!\n\nО, я не можу проґавити нагоду відвідати сестру моєї любої королеви в одній з її святих обителей! Та вона ж нам, фейрі, практично як тітка!\n\nТепер, коли вони помирилися, саме час навідатися й подивитися, як тут усе влаштовано!",
    },
    [65599] = {
        title = "Мерл",
