    [65642] = {
        title = "Завдання з оперення",
    },
    [65647] = {
        title = "Приготування: Велике полювання рівнин",
        description = "Приготування потребують часу. Щойно поповнимо припаси, ми рушимо.",
    },
    [65652] = {
        title = "Поклик Матріарха",
        description = "Вітаю, {name}.\n\nНе гаймо слів — ти терміново потрібен у Сільвермуні.\n\nУ Кель'Таласі ми спостерігаємо нове піднесення Погибелі. Якщо нічим не стримати Погибель, нас невдовзі захлеснуть. Ми мусимо втримати рубіж!\n\nЗустрінься зі мною в Залі Крові, і ми введемо тебе в курс справи.",
        objectives = "Зустрінься з леді Ліадрін у Сільвермуні.",
        completion = "Добре, ти вже тут.\n\nПочнімо.",
    },
    [65653] = {
        title = "Перемога за сін'дорей",
        description = "Сила рансера вичерпана, але ми перемогли! Тепер, коли Ворат повалений, можливо, з Погибеллю буде впоратися легше — завдяки тобі.\n\nПовертайся до мене в Зал Крові. Сільвермун вдячний за твою хоробрість.",
        objectives = "Повернися до леді Ліадрін у Сільвермуні.",
        completion = "Це ще не кінець Погибелі, але відрадно з такою завзятістю виганяти загрозу з наших земель.\n\nСьогодні Сільвермун вдячний тобі.",
    },
    [65655] = {
        title = "Очі вовка",
        description = "Тривожна чутка дійшла до мене завдяки нашим шпигунам.\n\nВідступники збираються в Тірісфальських галявинах. З якою метою — не знаю. Прикметно, що туди ж подалася й Калія Менетіл.\n\nМи мусимо дізнатися більше про їхні наміри, тепер, коли проклята Королева Банші більше не об'єднує їх.\n\nІди, перевдягнися й роздивися, що зможеш виявити. Спостерігай за всім. А якщо випаде нагода завоювати їхню довіру й дізнатися більше — роби, як вони просять.\n\nЯ з нетерпінням чекаю на твою доповідь.",
        objectives = "Зустрінься з Калією Менетіл у Бріллі, що в Тірісфальських галявинах.",
    },
    [65656] = {
        title = "Поклик Лордерона",
        description = "Тепер, коли Тіньокрай зцілюється, час знову звернути увагу на справи ближче до дому, в Азероті.\n\nВідступники збираються в руїнах королівства Лордерон. Вони прагнуть повернути собі якомога більше Тірісфальських галявин, щоб нарешті залишити позаду спустошення, заподіяне Четвертою війною.\n\nІ я маю намір допомогти їм усім, чим тільки зможу.\n\nЯ також знаю, що мушу багато довести Орді. Ходімо, приєднуйся до мене в Бріллі, і ми разом допоможемо Відступникам.",
        objectives = "Зустрінься з Калією Менетіл у Бріллі на Тирісфальських Галявинах.",
    },
    [65657] = {
        title = "Збери Відступників",
        description = "Приємно бачити, що у відбудові Брілла досягнуто поступу, та це лише перший крок. Руїни столиці й досі недоступні через моровицю.\n\nІ саме тут я сподіваюся на твою допомогу нашій справі.\n\nЩоб відновити якомога більшу частину цих земель, потрібно зібрати докупи всі уми, аби вони працювали задля єдиної мети.\n\nСеред Відступників здобули вагу кілька впливових постатей. Прошу, допоможи звести їх разом, щоб ми могли зустрітися й обговорити подальший шлях.",
        objectives = "Збери разом темну вартову Велонару, Ліліан Восс і головного аптекаря Фаранелла.",
        progress = "Усі тяжко працюють, щоб знову стати на ноги. Може, і не на ті ноги, з якими починали, але вони служать.",
        completion = "Схоже, ми готові починати.\n\nЗдається, стільки Відступників в одному місці не збиралося з часів... ну, Темного Узбережжя.\n\nАле тепер ми на своїй землі, і час подбати про своїх.",
    },
    [65658] = {
        title = "Ця земля наша",
        description = "Чума, випущена під час війни, отруїла землю й потривожила мертвих. Тобто ще дужче, ніж доти.\n\nМи тяжко працювали над відбудовою, та наш народ не може завершити свою справу, поки над ним нависає загроза.\n\nМій найперший обов'язок — убезпечити Відступників. Я зустрінуся з рештою, як просить Калія, та спершу ти маєш допомогти мені винищити декого з цих Зачумлених.",
        objectives = "Убивай Зачумлених солдатів на Тірісфальських галявинах.",
        progress = "Треба послабити натиск на Брілл, щоб ми могли продовжити відбудову.",
        completion = "Це дасть нашим вартовим змогу перевести подих. Метафорично кажучи, звісно.\n\nДякую за допомогу, {NAME}.",
    },
    [65659] = {
        title = "Нарада щодо моровиці",
        description = "Ми, Відступники, пережили чимало від часу руйнування Лордерона. Та ми сповнені рішучості зберегти свій дім.\n\nЧому ми маємо віддавати те, що так тяжко для себе виборювали?\n\nКалія в дечому ще новенька серед нас, але нашому народові вона, певна річ, добре відома. Як могло б бути інакше — адже вона рідна сестра самого Артаса?\n\nСподіваюся, ми зможемо рухатися вперед і що вона справді допоможе. Її голос може мати вагу, якщо вона по-справжньому віддана нашому народові.",
        objectives = "Вислухай Відступників.",
        completion = "Я очікувала, що моя присутність може викликати тертя. Але я вдячна Ліліан за посередництво й за надану мені можливість показати, що я віддана справі допомоги народові Відступників.\n\nТа тепер я мушу це довести.",
    },
    [65660] = {
        title = "Хода віри",
        description = "Я обіцяла, що допоможу, — і допоможу. Нам потрібен чистий зразок чуми, що вразила Лордерон, але ми не можемо наражати на небезпеку нікого іншого.\n\nХодімо зі мною. Я прикличу щит зі Святого Світла, що оберігатиме нас на шляху вглиб зачумлених земель, де ми зможемо взяти той зразок.\n\nЦе закляття вимагатиме від мене цілковитого зосередження. Покладаюся на тебе — захисти нас від усього, що спробує нас спинити.\n\nТи зі мною?",
        objectives = "Захищай Калію всередині її щита та збери чистий зразок чуми.",
        progress = "Мабуть, мені варто мати віру.",
        completion = "Таке не щодня побачиш.",
    },
    [65661] = {
        title = "Порадитися із союзниками",
        description = "Сподіваюся, Калія має рацію щодо цих володарів Малдраксуса. І що вони знають, як дати раду такій потужній чумі.\n\nДо того ж у нас лишився всього один пожирач чуми, та Фаранелл каже, що зможе відтворити їх більше, якщо вони будуть досить міцні, щоб вижити.\n\nВирушаймо до Тіньокраю.",
        objectives = "Поговори з маркграфинею Сін'дане в Малдраксусі.",
        completion = "Ти несеш доволі гидкий взірець нічим не стримуваних і невгамовних амбіцій творця чуми.\n\nСподіваюся, автора цієї потвори вже викорінено. Чого ж ти просиш у домів Малдраксуса?",
    },
    [65662] = {
        title = "Дім Чум",
        description = "Той, хто володіє потрібним тобі знанням, — уцілілий із Дому Чум. Ти вже його знаєш.\n\nВинахідник чуми Марілет, може, й не найпослідовніший співрозмовник, та він знатиме, що робити з твоєю чумою.\n\nЗнайди його біля руїн того полеглого дому. Але будь насторожі! Багато чого з того, що там чаїться, може обірвати твоє існування, й оком не змигнувши.",
        objectives = "Зустрінься з винахідником чуми Марілетом у Домі Чум.",
        completion = "Привіт, $p(мій улюблений учню:моя улюблена ученице)! \n\nСлухай, вигляд у тебе трохи блідий. Точно висипаєшся?",
    },
    [65663] = {
        title = "Нагодуй пожирача",
        description = "Дім Чум спіткало лихо, так само як і Лордерон. Сподіваюся, наша праця й зусилля тут бодай почасти виправлять ту руїну.\n\nАле спершу нам треба пройти глибше в Дім Чум, щоб зміцнити здібності пожирача чуми Фаранелла.\n\nКожен убитий слиз, кожне вбите створіння неодмінно додасть йому сили.",
        objectives = "Убивай слизів і чумароків у Домі Чум.",
        progress = "Кожен із нас може чимось прислужитися.",
        completion = "Пожирач чуми вже помітно зміцнів. Гадаю, головний аптекар Фаранелл був би задоволений.",
    },
    [65664] = {
        title = "Сутність чуми",
        description = "Твій маленький друг геть зголоднів! Та не хвилюйся, я точно знаю, чим його погодувати. Скоро він виросте великим і сильним і зможе пожирати стільки чуми, скільки подужає.\n\nПоблизу є різні зілля, що нададуть йому зміцнювальних властивостей. І кожен колір — то інший смак!\n\nЯ занесу зразок чуми, який ти мені $p(приніс:принесла), глибше в Дім Чум, щоб подивитися, що ще ми можемо дізнатися. Зустрінься там зі мною й дай своєму пожирачеві чуми поласувати на славу!",
        objectives = "Поглинь різні зілля в Домі Чум.",
        progress = "Кожен колір — то інший смак!",
        completion = "Ти це бачи$p(в:ла)? Який грізний зразок чуми ти мені $p(приніс:принесла)!\n\nВін поцілив мені в голову й мало не вбив твоїх друзів, $p(учню:ученице). Пречудово!",
    },
    [65665] = {
        title = "Втілення",
        description = "Яку ж паскудну чуму ти мені $p(приніс:принесла), $p(учню:ученице). Її, певно, зварив справжній садист.\n\nЩоб вивчити зразок, я надав йому подобу. Та невдячне створіння обернулося проти мене й напало — геть без жодного приводу!\n\nВоно сповзло трохи далі вглиб Дому. Не хочеться цього казати, та, гадаю, його треба прикінчити, перш ніж воно стане ще сильнішим... чи більшим.\n\nГлянь на це з кращого боку. Якщо твій пожирач чуми зуміє вижити, він буде налаштований саме на цю твою особливо жахливу моровицю.",
        objectives = "Убий Моровицю Лордерона.",
        progress = "Ти вже $p(позбувся:позбулася) того втілення?",
        completion = "Попри весь клопіт, якого завдав нам той зразок, здається, у мене тепер справді з'явилася крихта надії.",
    },
    [65666] = {
        title = "Повернення до Брілла",
        description = "Ми зміцнили нашого пожирача чуми, і тепер він, схоже, готовий узятися за куди більшу поживу.\n\nПовернімо його до Фаранелла. Він казав, що зможе відтворити його властивості й розсіяти пожирачів чуми по всіх руїнах.\n\nА тоді, можливо, лише можливо, ми знову ступимо на землю нашого дому.\n\nОсь, візьми мій камінь повернення. Він перенесе тебе назад до Брілла.",
        objectives = "Повернися до головного аптекаря Фаранелла біля Руїн Лордерона.",
        progress = "Що ти мені $p(приніс:принесла)?",
        completion = "Чудово! Ти не лише не загуби$p(в:ла) мого пожирача чуми — ти $p(повернув:повернула) його ще сильнішим!\n\nА тепер стань свідком геніальності та швидкості моїх машин. Пожирачів чуми вистачить із лишком, щоб розсіяти їх по всій поверхні Андерсіті.",
    },
    [65667] = {
        title = "Ліки Лордерона",
        description = "Час настав. Молю Світло, щоб наш план спрацював.\n\nУ возах головного аптекаря Фаранелла відтворено безліч пожирачів чуми, і кажани готові рознести їх.\n\nЯкщо побачиш місце, де наші сили могли б поширити ще більше ліків, можеш подати їм знак сигнальною ракетою.\n\nЗдіймайся в небо, і покладімо край цій моровиці. За Лордерон і за Відступників.",
        objectives = "Сядь на тіньового кажана й розсій пожирачів чуми в Руїнах Лордерона.",
        completion = "Нам вдалося. Спільною працею ми очистили поверхню від смертоносної чумної хмари.\n\nЩоб вичистити нижні яруси Андерсіті, потрібно більше часу, але початок чудовий.",
    },
    [65668] = {
        title = "Знедолена рада",
        description = "Поєднавши наші знання та вміння, ми повернули Відступникам поверхню Андерсіті.\n\nЦе стало можливим лише тому, що ми відклали недовіру вбік і діяли заради добра нашого народу. Тепер настав час офіційно заснувати цю раду.\n\nМи вже не та нежить, що йшла за Сильваною Віндраннер і служила їй. Відтепер ми керуємо собою самі — з тим самим духом незалежності та гордості, який маємо відтоді, як повернули собі свободу волі.\n\nНастав час нового майбутнього з новим проводом.",
        objectives = "Стань свідком заснування нової Знедоленої ради.",
        progress = "Надію — і свіже повітря — відновлено.",
        completion = "Для мене велика честь, що мене прийняли до нового проводу Відступників. \n\nПрисягаюся: я робитиму все можливе, щоб захищати й оберігати наш народ, хай звідки хто походить і хай яка форма нежиття його створила.",
    },
    [65669] = {
        title = "Доповідь Ґреймейну",
        description = "Дякую тобі за всю допомогу, що привела нас до цієї історичної миті.\n\nГадаю, є й інші, кому цікаво, що тут сталося. Прошу, передай цього листа і мої найкращі побажання, коли повернешся до них.",
        objectives = "Достав листа Калії Ґенну Ґреймейну в Орибосі.",
        progress = "Що сталося у Відступників?",
        completion = "Вони зробили ЩО?\n\nІ Калія запропонувала обговорити повернення Ґілнеасу?\n\nТвій хист мене вражає, {NAME}. Чудова робота.",
    },
    [65674] = {
        title = "Що це таке?",
        description = "<Невизначена есенція у твоїх руках виглядає так, ніби може служити безлічі цілей. Власне, вона мовби аж випромінює можливості.>\n\n<Можливо, у Фіріма знайдуться відповіді щодо цього.>",
        objectives = "Принеси невизначену есенцію Фіріму в Лощину Вигнанця.",
        completion = "О, це справді прецікава знахідка, $p(смертний:смертна).\n\nТакий матеріал уже траплявся мені в дослідженнях. Теоретично він може змінювати долю різних предметів — так би мовити, розкривати їхній потенціал. Цікаво, чи не так?\n\nЦю есенцію я залишу собі, бо маю в ній потребу. Натомість поділюся з тобою знанням, як використовувати подібні матеріали у власних творіннях.",
    },
    [65680] = {
        title = "Реасиміляція схеми: серцевірний вовк",
        description = "<Ця схема містить взірець нового конструкта з протоформи. Піднеси її до відповідного горна протоформ, і воно, можливо, створить для тебе одну з цих істот.>",
        objectives = "Піднеси схему до відповідного горна протоформ.",
        completion = "Чудово. Із цією схемою та належними складниками тут може зазвучати нова пісня, що супроводжуватиме тебе.",
    },
    [65686] = {
        title = "До Лазурового Простору",
        description = "Вітаю, {name}!\n\nМи з Пакіною тут від імені Кірін-Тор і шукаємо допомоги.\n\nКірін-Тор працюють над тим, щоб уберегти дику арканну магію, що розлилася по всьому Лазуровому Простору.\n\nКалекґосу, Аспекту синьої зграї драконів і одному з наших проводирів, теж потрібна допомога, щоб повернути тамтешній Лазуровий Камінь Клятви.\n\nЯкщо ти готов$p(ий:а) допомогти, рухайся далі дорогою, доки не знайдеш Гланію з Благословенних.\n\nВона вкаже тобі, де твоя допомога буде найпотрібніша.",
        objectives = "Зустрінься з Гланією з Благословенних у Лазуровому Просторі.",
        completion = "Чудово, шукач пригод. Уведу тебе в курс справи, поки мені не довелося вчитися... рибалити.",
    },
    [65687] = {
        title = "Дати відсіч",
        description = "Декотрі з інших учнів... дуже злі.\n\n<Інґот тре свіжу рану на писку.>\n\nРаніше такого не було, та коли прийшов Сиґенот, він сказав: «Ми маємо цінувати силу понад усе». Тепер усі весь час б'ються.\n\nЯ намагаюся давати відсіч, але їхні шкури надто товсті... а я надто малий.\n\nАле ти ж ні! Ти, певно, постійно б'єшся з кривдниками. Може, ти допоможеш?",
        objectives = "Убий 12 драконідів Світоруйнівника.",
        progress = "Не всі Світоламачі — кривдники. Чесне слово!",
        completion = "Ці криволускі бовдури більше нікого не скривдять! Вартовий Землі дякує тобі! \n\nО. І я. Я теж дякую.",
    },
    [65688] = {
        title = "Зустріч із Калекґосом",
        description = "Боюся, нам доведеться розділити сили. Загрозу первісників на сході треба здолати.\n\nМушу попросити тебе вирушити до Лазурових Архівів замість мене й допомогти Калекґосу повернути Лазуровий Камінь Клятви.\n\nТобі знадобиться дещо з припасів, щоб упоратися з тим, що там коїться.\n\nПоговори з нашим інтендантом порталів — у нього має знайтися щось, що стане тобі в пригоді в дорозі.\n\nЩасти, {name}. Калекґос буде вдячний за допомогу.",
        objectives = "Візьми торбу з корисним добром, а тоді зустрінься з Калекґосом біля підніжжя Лазурових Архівів.",
        progress = "Мені аж відлягло від серця, що є хоч якась допомога. Знаю, Хадґар та інші, певно, дуже заклопотані первісниками.",
        completion = "Хадґар мудро вчинив, спрямувавши зусилля на первісників.\n\nАле тепер... роботи в нас тут чимало.",
    },
    [65689] = {
        title = "Численні подоби Калекґоса",
        description = "Радий познайомитися з тобою як належить, {name}. Мене звати Калекґос, архімаг Кірін-Тор і Аспект синьої зграї драконів.\n\nМені непросто полагодити Лазурові Архіви, щоб повернути Лазуровий Камінь Клятви. Зайва пара справжніх рук дуже б згодилася.\n\nЗараз я нагорі, в самих архівах. Я зумів знову ввімкнути пілон зовні, тож ти зможеш піднятися сюди.",
        objectives = "Скористайся кристальним пілоном, щоб дістатися Лазурових Архівів.",
        progress = "Радий, що тобі вдалося дістатися.",
        completion = "Берімося до роботи. Повернути Лазуровий Камінь Клятви — справа нагальна.",
    },
    [65690] = {
        title = "Сумніви культиста",
        description = "Учора прибула ще одна чужинка. Вона назвалася «посланницею» червоної зграї драконів і попросила аудієнції в нашого проводиря — Голосу Нелтаріона.\n\nАле Голос страшенно розлютився. Він сказав, що Землехранитель випробовує нас і що ми мусимо її стратити!\n\nЯ знаю, що ми не повинні довіряти чужинцям, та це ще не означає, що їх треба вбивати! Прошу, допоможи мені врятувати її.",
        objectives = "Знайди Аясант у Тліючому Сідалі.",
        completion = "Це драконеня просило твоєї допомоги?\n\n<Аясант полегшено видихає.>\n\nМожливо, Світоламних усе ж можна врятувати.",
    },
    [65691] = {
        title = "Тінь його крил",
        description = "Голос Нелтаріона мешкає внизу, сіючи брехню серед своїх послідовників.\n\nСхоже, він драконороджений, як і я, але його драконіанська незграбна — годиться хіба що для безлускових.\n\nЯ підозрюю обман: можливо, ілюзію. Якщо ми зможемо здолати його, певен, правда вийде назовні.",
        objectives = "Стань до бою із Сиґенотом, Голосом Нелтаріона.",
        completion = "Сьогодні ми загасили останні жарини Сутінкового Молота. Але Світоламні — то інша річ: ці лускороджені знайдуть нові пояснення своїм нещастям, нові міфи й нових проводирів.\n\nМи з родичами наглядатимемо за ними. Якщо постане новий Голос — ми втрутимося.\n\nСьогодні зроблено добре діло.",
    },
    [65700] = {
        title = "Контроль ядра",
        description = "Ти прийшов якнайдоречніше.\n\nСхоже, одна з моїх пасток щойно зловила доволі цікаву істоту. Я не наважуюся придивлятися ближче, та ти... ти можеш зробити це за мене.\n\nВізьми з собою Покопока. Можливо, на тебе чекають ще не розкриті таємниці.",
        objectives = "Оглянь цікаву істоту біля Лощини Вигнанця.",
        progress = "Знайшлося щось цікаве?",
        completion = "Покопок вельми цікавий, чи не так? Мені справді кортить дізнатися, на що він здатен.",
    },
    [65701] = {
        title = "Збереження, Підсилення чи Спустошення",
        description = "Якщо те, що кажуть ці дракони, правда, то на нас чекає велика битва. Нам потрібні твоя зосередженість і сила, пробуджувачу.\n\nНастав час обрати бойову спеціалізацію. Чи берегтимеш ти своїх союзників, чи спустошуватимеш ворогів?\n\nЩоб відточити свої бойові навички до блиску, обери Спустошення.\n\nЩоб розкрити весь свій потенціал зцілення, ступи на шлях Збереження.\n\nЩоб посилювати побратимів по крилу, прийми Підсилення.\n\nКожна спеціалізація стане тобі в пригоді. І пам'ятай: ти завжди можеш змінити чи пристосувати її пізніше.",
        objectives = "Обери спеціалізацію.",
        completion = "Чудовий вибір.\n\nПам'ятай: ти завжди можеш переглянути свою спеціалізацію й налаштувати вміння як заманеться — аби лиш не в розпалі бою.",
    },
    [65702] = {
        title = "Доведені до безумства",
        description = "Колись Лазурові Архіви були місцем, де сині дракони збиралися, щоб обговорювати магію.\n\nТепер я тут єдиний зі свого роду.\n\nЦе місце керує лей-лініями під Лазуровим Простором, але й воно саме, і його служителі вийшли з-під контролю.\n\nГадаю, якщо ми наведемо тут лад, я зможу повернути Лазуровий Камінь Клятви.\n\nРізноманітні конструкти й елементалі переповнені нестабільною арканною енергією, яку треба перенаправити.\n\nЗнищ їх і збери все, що зможеш.",
        objectives = "Здобудь 40 нестабільних арканних енергій.",
        progress = "Для більшості тутешніх вартових архіви перебувають у стані безнастанного перестворення. Мусимо виправити їхній потік.",
        completion = "Чудова робота. Навіть ця дещиця вилученого нестабільного аркану вже вгамовує тутешні творіння.",
    },
    [65709] = {
        title = "Арканне підрізання",
        description = "Ми не зможемо активувати Камінь Клятви в Лазурових Архівах, доки не вирішимо проблему з некерованою лей-енергією тут.\n\nДві з трьох драконячих рун, що мали б її контролювати, придушені нестабільним арканом.\n\nПробач, що це випадає на тебе, але Хадґар має забагато обов'язків, а мої родичі так і не з'явилися.\n\nУ тій торбі з корисним добром, що в тебе є, має бути лей-скіпетр.\n\nСкористайся ним, щоб полагодити руни неподалік.",
        objectives = "Знайди в торбі з корисним добром лей-скіпетр, а тоді полагодь ним 2 платформи.",
        progress = "Лей-скіпетр допоможе тобі як слід вирівняти й налаштувати руни неподалік.",
        completion = "Чудова робота. Схоже, ці руни можуть перенести нас на вершину архівів.\n\nГадаю, саме там засіла наша остання проблема...",
    },
    [65711] = {
        title = "Вкрасти грім",
        description = "Це ти! Слава Он'агрі. Я вдавала поранену, щоб ошукати наступного бевзя, який наважиться сюди зайти. Ох... ці підлабузники наклали на мене закляття, що сковує. Я з ним розберуся.\n\nВони тримають Лізі в печері. Прошу, врятуй її. Я вже якось дам собі раду й звільнюся.\n\nРоби те, що мусиш.",
        objectives = "Убий видобувачів бурі та врятуй Лізі Громохребту в таборі Кайган.",
        progress = "Кожен, хто наклав копито на Лізі, поплатиться!",
        completion = "<Радія незвично мовчазна і злегка тремтить, дивлячись на замучену звірину.>",
    },
    [65717] = {
        title = "Провідні мотиви",
        description = "<Невеличка річ привертає твій погляд. Вона мерехтить магією Прабатьків — прадавньою, та все ж... дивно витонченішою.>\n\n<У пристрій вплетені тихі вібрації й звуки, що повторюються рефреном, який немовби намагається... говорити?>\n\n<Фіріма це дуже зацікавило б.>",
        objectives = "Принеси Відлуння Альманаху Фіріму в Лощину Вигнанця.",
        completion = "Клянуся Першими... ти знову приносиш мені щось надзвичайне. Кажеш, воно знайшлося після перемоги над Тюремником? Як цікаво.\n\nВоно немовби намагається... якось спілкуватися. Самі лише наслідки цього... ах! Пробач, що захопився. Боюся, тут знадобиться щось більше за звичайне дослідження.\n\nПрошу, візьми це навзаєм. Одна з моїх перших знахідок — підозрюю, її рухливість стане тобі в більшій пригоді, ніж мені.\n\nДякую тобі, друже.",
    },
    [65725] = {
        title = "Закопаний буфонід",
        description = "Великий буфонід під грязюкою досі не ворушиться.\n\nМає ж бути щось, що йому до вподоби. Чи нема в тебе м'яса, яким ми могли б його виманити?",
        progress = "Великий буфонід під грязюкою досі не ворушиться.\n\nМає ж бути щось, що йому до вподоби. Чи нема в тебе м'яса, яким ми могли б його виманити?\nТіньові Реберця (30)",
        completion = "Дякую, {NAME}. Погляньмо, чи це подіє.",
    },
    [65726] = {
        title = "Закопаний буфонід",
        description = "Якщо ні м'ясо, ні мед не змогли виманити цю істоту з води, спробуймо інший підхід.\n\nПринеси мені трохи запиналкової тканини. Я сплету з неї сітку, яка, можливо, буде дієвішою.",
        progress = "Якщо ні м'ясо, ні мед не змогли виманити цю істоту з води, спробуймо інший підхід.\n\nПринеси мені трохи Огорнутої Тканини. Я сплету з неї сітку — можливо, вона буде дієвішою.\nОгорнута Тканина (200)",
        completion = "Дякую, {NAME}. Спробуймо — як не заради власної цікавості, то заради Бутончика.",
    },
    [65727] = {
        title = "Закопаний буфонід",
        description = "Чи спинявся ти колись, щоб поспостерігати за буфонідами?\n\nЧудовий екземпляр причаївся під водою. Тихий, терплячий, нерухомий. Мудрий Бутончик удався в нього. Вони дуже схожі. Відчуваю, що Бутончик прагне роздивитися цього великого буфоніда зблизька.\n\nМабуть, цю істоту можна виманити медом веспоїдів тут, у Зерет Мортіс. Чи не міг би ти трохи назбирати?",
        objectives = "Збери 15 порцій меду веспоїдів із веспоїдів по всьому Зерет Мортісу.",
        progress = "Чи знайшовся той мед?",
        completion = "Дякую, {NAME}. Тепер погляньмо, чи спокусить це буфоніда вилізти.",
    },
    [65728] = {
        title = "Закопаний буфонід",
        description = "Оскільки пастка не спрацювала, спробуймо знову знайти принаду, яка зацікавить цього суворого буфоніда.\n\nМабуть, він хоче риби? Принеси нам трохи.",
        progress = "Оскільки пастка не спрацювала, спробуймо знову знайти принаду, яка зацікавить цього суворого буфоніда.\n\nМабуть, він хоче риби? Принеси нам трохи.\nЕлізійський Тейд (10)",
        completion = "Дякую, {NAME}. Сподіваймося, це спрацює.",
    },
    [65729] = {
        title = "Закопаний буфонід",
        description = "У мене закінчуються ідеї. Чим іще можна привабити нашого сором'язливого друга?\n\nСпробуймо ще м'яса істот Зерет Мортіс. Щось же має привернути його увагу!",
        progress = "У мене закінчуються ідеї. Чим іще можна привабити нашого сором'язливого друга?\n\nСпробуймо ще м'яса істот Зерет Мортіс. Щось же має привернути його увагу!\nПротоплоть (5)",
        completion = "Дякую, {NAME}. Погляньмо, чи дасть це результат.",
    },
    [65730] = {
        title = "Закопаний буфонід",
        description = "Що ж іще ми могли б спробувати, щоб умовити цього буфоніда вилізти?\n\nМабуть, джиро знають хитрість. Я чув, що один із них пропонує фруктові тістечка. Принеси нам одне, будь ласка.",
        progress = "Що ж іще ми могли б спробувати, щоб умовити цього буфоніда вилізти?\n\nМабуть, джиро знають хитрість. Я чув, що один із них пропонує фруктові тістечка. Принеси нам одне, будь ласка.\nКаталізований Яблучний Пиріг (5)",
        completion = "Дякую, {NAME}. Може, наш друг-буфонід просто має витонченіший смак.",
