    [65890] = {
        title = "Руїни Нелтазана",
        description = "Експедиції Драконячої Луски потрібна твоя допомога.\n\nДо руїн відправили небесного писаря збирати відомості. Там мало б бути безлюдно, але я навіть звідси чую його крики.\n\nЯкщо його чути на такій відстані, він точно вскочив у халепу.\n\nУ нашій експедиції ми дбаємо про своїх. Навіть про нестерпних. Розшукай його й захисти від хай якої небезпеки, на яку він натрапив.",
        objectives = "Зустрінься з небесним писарем Аденедалем біля Руїн Нелтазана.",
        completion = "Та звісно, що я кричу! Книга ж не слухається. А що мені ще робити?",
    },
    [65891] = {
        title = "Знаряддя для справи",
        description = "Добре. Я саме думав, що мені потрібен шукач пригод на кшталт тебе. Сильний. Витривалий. Готов$p(ий:а) працювати за дрібні гроші.\n\nНаче я викликав тебе самою лише волею. Молодець я. Схоже, ці руїни привернули увагу інших. Не можна покладатися на них — вони не розкопають усе як слід. Вони зіпсують зразки!\n\nВізьми ось це. Розставляй довкола цікавих артефактів по руїнах. Воно зачароване виконувати будь-яку потрібну роботу.",
        objectives = "Розстав зачаровані знаряддя біля 5 куп уламків.",
        progress = "Гадаю, напишу трохи поезії. Точніше, загадаю книзі написати її за мене.",
        completion = "З часом ми зберемо все.",
    },
    [65892] = {
        title = "Розколоте на друзки",
    },
    [65893] = {
        title = "Розслідування реліквій",
        description = "Тут Розколоте Полум'я. Ти довірив би безцінні артефакти комусь, хто зве себе розколотим?\n\nОтож-бо. Хай там як, нам треба знати, чого вони сюди прийшли, перш ніж рушати далі. Збери все, що зможеш у них здобути, і повертайся до мене зі знахідками.\n\nУ цій загадці більше частин, ніж ми відкопаємо в землі.",
        objectives = "Збери 60 уламків артефактів Нелтазана.",
        progress = "Ці руїни вже й так зруйновані далі нікуди.",
        completion = "Вони досі щось шукають? То нащо мені це сміття?\n\nМи мусимо знайти це раніше за них!",
    },
    [65895] = {
        title = "Поінформовані суперники",
        description = "Ба! З різанини робітників ми нічого не дізнаємося.\n\nРозшукай їхніх ватажків. Хтось із них знатиме те, що нам потрібно.\n\nА, і ще, {name}. Цього разу спершу вислухай їх, а тоді вже вбивай. Може, дізнаєшся щось корисне.",
        objectives = "Збери відомості про Розколоте Полум'я.",
        progress = "Що вдалося дізнатися?",
        completion = "Таку хворобу я вже бачив колись у житті. І сподівався більше ніколи не побачити.",
    },
    [65896] = {
        title = "Нехай зцілення почнеться",
        description = "Ти гадав, що зможеш увійти в це місто непомітно для мене? Аж ніяк!\n\nЯ й раніше не помилявся щодо таких, як ти, і будь я проклятий, якщо знову дозволю драконам зруйнувати мій дім.\n\nКолись це був парк, сповнений радості й спокою. А тоді прийшов твій прабатько, Дезвінг. О так, я знаю про нього все.\n\nПоглянь на власні очі на спадок руйнування, що він лишив по собі. На біль, який досі блукає цими вулицями.",
        objectives = "Допоможи мешканцям Стормвінда зцілитися.",
        completion = "Кращого дарунка мені сьогодні годі й бажати. Тепер я знаю: моє місто готове зцілюватися. Наша спадщина досі в наших руках.\n\nІди з честю, друже.",
    },
    [65898] = {
        title = "Прото-проблеми",
        description = "Я не плекаю любові до Розколотого Полум'я, та навіть я не можу стояти осторонь, поки вони отак шматують одне одного. Надто вже знайома картина.\n\nХоч би що це за Локус, у наших руках він безпечніший, ніж у їхніх лапах. Іди слідом із тіл — гадаю, так ми його й знайдемо.\n\nБудь обережний, {name}. Боюся, ми побачимо, що це гніздо не таке порожнє, як здається.",
        objectives = "Здобудь Локус і здолай протодрейка, що його охороняє.",
        progress = "Добре, що ти вже тут, у безпеці. Локус у тебе?",
        completion = "Дякую, {NAME}.\n\nТвоя допомога неоціненна.",
    },
    [65899] = {
        title = "Знайди Терамуса",
        description = "{race}! Ти прийшов помилуватися чудовим Бузковим Гаєм? Мені так прикро за його теперішній стан. Присягаюся, зазвичай він не такий занедбаний!\n\nТерамус, доглядач саду, мав сьогодні з нами зустрітися, щоб разом узятися за справи. Останнім часом йому важко давати раду догляду, тож ми з Феліною допомагаємо. Але ми не встигаємо все.\n\nДопоможеш нам пошукати його? Може, він і справді забув.",
        objectives = "Обшукай печери поблизу та знайди Терамуса.",
        completion = "Він знайшовся! Схоже, сьогодні він зовсім занепав духом.",
    },
    [65900] = {
        title = "Підозріло приправлений стейк",
        description = "Задумка моєї сестри чарівна, але Терамусові потрібне справжнє підбадьорення.\n\nА це — щедра порція кислоцвіту. З нього можна зробити пасту й намастити нею його улюблену страву: м'ясо черепахи!\n\nДопоможеш мені зібрати інгредієнти?",
        objectives = "Збери 2 шматки ідеально ніжного черепашого м'яса, 6 рептилячих шкаралуп і 15 кислоцвітів.",
        progress = "Знаєш, чому кислоцвіт росте під прибережними деревами?\n\nКоріння дерев затримує безліч поживних речовин із хвиль, і ними живиться кислоцвіт. Тому він неймовірно поживний.",
        completion = "Співвідношення м'яса й кислоцвіту — саме те, що треба.",
    },
    [65901] = {
        title = "Втеча крадькома",
        description = "Мене покарали на невизначений строк! Невже мій Он не знає, що наступної весни мені виповниться шістнадцять? Я маю право йти, коли захочу.\n\nТи, схоже, можеш мені допомогти. У мене є план втечі: каналізуючи ці тотеми, я згущу повітря й здійму неабиякий переполох. Але сама розставляти їх я не можу, бо за мною стежать пильніше нікуди. Навіть Тоґо мені не допоможе.\n\nА от з твоєю допомогою... Будь ласка! Обіцяю, я покажу тобі дещо круте.",
        objectives = "Розстав тотеми повітря в Джерелах Он'ірі, а тоді сповісти Радію.",
        progress = "Спробуй лише мене виказати — і я переслідуватиму тебе найвітрянішим привидом... ВІЧНО! Навіть не думай!",
        completion = "Ху-у, дякую! Свобода!",
    },
    [65902] = {
        title = "Поласувати чи погладити?",
        description = "Поглянь лишень на це соковите й апетитне м'ясо черепахи з травами! Я, звісно, кажу це цілком неупереджено. Я ж бо вегетаріанка.\n\nНу ж бо! Він, мабуть, цілий день нічого не їв.",
        objectives = "Принеси Терамусу черепаше м'ясо з травами та галявинних стрибунців.",
        progress = "Іди, поки м'ясо не вичахло!",
        completion = "Ой лишенько. Ми чули його спалах гніву. З тобою все гаразд?",
    },
    [65903] = {
        title = "Проти пухнастиків не встояти",
        description = "Бідолашний Терамус. Я знаю, як його розрадити!\n\nВізьми цю сітку й налови місцевих стрибунців — вони сумирні, але прудкі. Вони добряче облаштувалися на узбережжі.\n\nМи принесемо їх Терамусу. Він буквально потоне в пухнастому щасті!",
        objectives = "Налови 12 галявинних стрибунців.",
        progress = "Вони неймовірно м'якенькі! Їх хочеться гладити цілісінький день.",
        completion = "Стільки! Багато! Стрибунців! Нумо гладити всіх!",
    },
    [65904] = {
        title = "Досить уже",
        description = "Хай буркотливий, хай ні, а Терамус має свою справу. Поки він ховається всередині, він не бачить, до чого призводить його відсутність.\n\nХодімо разом. Ми покажемо йому докази.",
        objectives = "Принеси Терамусу докази шкоди, завданої Бузковому Гаю.",
        progress = "Це переконало б будь-кого, що гаю потрібна допомога — негайно!",
        completion = "...Здається, спрацювало? Він вийшов із печери!",
    },
    [65905] = {
        title = "Не просто бур'яни",
        description = "Мабуть, краще дати Терамусу трохи спокою.\n\nАле сидіти склавши руки ми не можемо. Гай руйнується дедалі швидше! Будь ласка, допоможи нам.",
        objectives = "Розчисть Бузковий Гай від заростей і потвор.",
        completion = "Дякую, {race}.",
    },
    [65906] = {
        title = "Невдоволена послушниця",
        description = "Я отримав цікавого листа з джерел Он'ірі.\n\nЩодо змісту листа, то в ньому йдеться, цитую, про жахливе ув'язнення, владних наставників і нестерпну нудьгу. Підписано офіційно: послушниця Радія. Ще там є малюнок орла... який скидає зі скелі кентаврицю на ім'я Мелуун.\n\nЩо ж. Гадаю, це заклик про допомогу, якщо тобі заманеться поглянути самому. Як по правді, думаю, з Радією все гаразд. Вона часто шле мені такі листи.",
        objectives = "Поговори з послушницею Радією в Джерелах Он'ірі на Рівнинах Он'агри.",
        completion = "Хто ти? Тебе прислав Ордвен? Він і справді читає мої листи?!\n\n<Радія форкає від подиву й утіхи.> Слава Он'агрі!",
    },
    [65907] = {
        title = "Улюблений фрукт",
        description = "Навчання на містика — така нудьга. Половину днів я витріщаюся, як вода тече. Мої брати вже там, у дикому краю, полюють на драків і первісників та змінюють світ.\n\nХай там як, я обіцяв показати тобі дещо круте! А ти зна$p(в:ла), що багнотопи обожнюють кущові ягоди? Вони ростуть неподалік, серед гейзерів. Назбирай трохи, і ми разом їх погодуємо.",
        objectives = "Назбирай диких кущових ягід біля Гейзерів Он'ір і нагодуй ними 6 розімлілих багнотопів.",
        progress = "Колись я дуже любив кущові ягоди, поки одного дня не переїв.\n\nУсе тіло тремтіло, як від лютої застуди, а подих іще кілька днів був м'ятним.",
        completion = "Здається, ти їм подобаєшся! Або просто ягоди. Це теж нічого. <Радія підморгує.>",
    },
    [65911] = {
        title = "Лазурова згуртованість",
        description = "Узи цієї спільноти... дружба й родина, що єднають їх усіх.\n\nЯ... ніколи такого не мав. Синя зграя драконів ніколи такого не мав. А може, це тому, що ми просто не мали нагоди.\n\nТепер час настав. Я мушу зібрати свій рід.\n\nЗустрінемося в Лазурових Архівах. На нас чекає чимало роботи.",
        objectives = "Повернися до Калекґоса в Лазурові Архіви.",
        completion = "Я й не сподівався, що стільки навчуся від тускарів. Гадаю, навідуватимуся до них за нагоди й плекатиму ці узи дружби.",
    },
    [65913] = {
        title = "Як справи, вартівнице?",
        description = "Хвала Титанам! {class}, нам потрібна твоя допомога!\n\nЛише мить тому на нас напали первісники. Ми із сестрами зуміли відбитися, але зазнали тяжких втрат...\n\nБуде час оплакати загиблих, коли моя вартівниця буде в безпеці! Гурт первісників відколовся, поки ми билися, і присягаюся, якщо вони скривдять нашу Вартівницю...\n\nТи мусиш допомогти їй, поки не пізно!",
        objectives = "Врятуй вартівницю Мару від первісників у Резервуарі Тіргольду.",
        completion = "Дякую тобі, {race}. Якби не твоя допомога, я б напевно загинула.",
    },
    [65914] = {
        title = "Мамонти важливі",
        description = "Наше плем'я гордо плекало стадо мамонтів Он'тук упродовж поколінь. А тепер вони... загинули.\n\nПісля такої різанини їхні душі линутимуть у люті. Ми маємо вшанувати їхнє життя, належно скориставшись їхніми рештками.\n\nЇх забагато, самі ми не впораємося. Прошу, збери якомога більше матеріалів з молодняку та матріархинь, а тоді зустрінься зі мною в Озерці Кауріку.",
        objectives = "Збери клапті шкіри та бивні он'туків із полеглих мамонтів Он'тук біля Озерця Кауріку.",
        progress = "Мої діти вже нагледіли собі телят, щоб виростити з них супутників. Як я їм тепер скажу?",
        completion = "Гадаю, з цих решток ми зможемо створити щось справді особливе... щось, що заспокоїть душі мамонтів.",
    },
    [65916] = {
        title = "Ми не ведемо перемовин з первісниками",
        description = "Первісники гадали, що подужають міць Тіра. Вони помилялися.\n\nМої рефті вистежили первісників до печери неподалік звідси. Як я й думав, ключові камені в них.\n\n$p(Захиснику:Захиснице), якщо ми хочемо відновити резервуар, ми мусимо повернути ці ключові камені.\n\nБільше того, їхнього ватажка треба вбити, щоб вони не наважилися на другий напад.",
        objectives = "Убий ватажка первісників Ко'джо та поверни зниклі ключові камені в Резервуарі Тіргольду.",
        progress = "Певно, коли ми повернемо ключові камені, Зуттікі вже не виглядатиме так... похмуро.",
        completion = "Дякую, {NAME}. Попереду наше останнє завдання — відновити обереги.",
    },
    [65918] = {
        title = "Запобіжні заходи",
        description = "Первісні елементалі розмножуються без упину. Зазвичай ми із сестрами впоралися б із ними, але ми не в змозі з ними битися. Ми втратили надто багато наших воїнів.\n\nДо того ж, тих небагатьох, хто лишився, чекають інші справи.\n \n<Зуттікі здригається від болю.>\n\nОсь тут стаєш у пригоді ти, {name}. Чи не міг би ти впоратися з елементалями?",
        objectives = "Убий 8 вивільнених елементалів у Резервуарі Тіргольду.",
        progress = "Мара, мої сестри? Такого не мало статися.",
        completion = "Дякую, {NAME}. Це має стримати їх на якийсь час.",
    },
    [65920] = {
        title = "За оберіг!",
        description = "Нарешті ми можемо відновити обереги. Ми зазнали тяжких втрат, але наша робота має бути завершена.\n\n{name}, нам знову потрібна твоя допомога. Постав кожен ключовий камінь на належне місце, щоб обереги знову стали цілими.\n\nКоли впораєшся, повертайся, щоб ми активували консоль і відновили лад у резервуарі.",
        objectives = "Використай зниклі ключові камені, щоб полагодити обереги резервуара, а тоді активуй консоль.",
        progress = "Коли всі три обереги буде полагоджено, повертайся сюди, щоб активувати консоль оберегів.",
        completion = "Чудова робота, {NAME}. Обереги відновлено, і Резервуар Тіргольду знову під захистом. Дякую тобі за все. Талдразус у великому боргу перед тобою.",
    },
    [65921] = {
        title = "Відплата Рефті",
        description = "Це не йде мені з голови, {name}. Стільки моїх сестер убито! Стільки занапащених життів... Їхня жертва не залишиться без відповіді!\n\nМої воїтельки вистежили Першородних і кажуть, що дехто з наших сестер ще живий.\n\nМи мусимо їх врятувати й подбати, щоб кожен Першородний відчув мій гнів!",
        objectives = "Убивай первісників і рятуй рефті в Резервуарі Тіргольду.",
        progress = "Я знала, що цей день може настати, — лише сподівалася, що не настане.",
        completion = "Біль за тими, кого ми втратили, залишиться зі мною назавжди, але я вдячна за тих, кого ми врятували.",
    },
    [65925] = {
        title = "Винищити винищувачів",
        description = "Цим вирмам тут не місце. Не знаю, що вигнало їх з підземних лігвищ, але тепер їм уже не зарадити.\n\nМи не можемо дозволити їм нищити тутешнє життя.\n\nПовбивай вирмів, {name}. Залиш собі їхні рештки, якщо треба, а коли впораєшся, знайди мене у Сяйнику.",
