    [65956] = {
        title = "Удар пазурів",
        description = "З твоєю допомогою мої вбивці Чорного Пазура знищать джарадинів, що обороняють зовнішній периметр. Познач будь-яку ціль маленькою оглушливою бомбою — і вони прийдуть тобі на поміч.\n\nДій швидко й усувай усе, що може завадити нашому просуванню.",
        objectives = "Оборону джарадинів зірвано.",
        progress = "Чи знищено їхню оборону?",
        completion = "Наш наступ відтісняє їх! Лишилося тільки проламати браму.",
    },
    [65957] = {
        title = "Не час для героїв",
        description = "З того, що ми бачили, суспільство джарадинів тримається на силі. Найдужчі служать прикладом для інших, щоб ті билися ще запекліше.\n\nСеред військ унизу є троє з наймогутніших джарадинів... і це твої цілі.\n\nТи, {name}, особисто їх усунеш. Це має завдати нищівного удару по їхньому бойовому духу.",
        objectives = "Убий Модака Вогнеплюя, Пронизувача Ґіґру та Олфіса Розплавленого.",
        progress = "Чи здолано твої цілі?",
        completion = "Сьогоднішня перемога — твоя заслуга, {NAME}.",
    },
    [65958] = {
        title = "Первісна сила",
        description = "Боюся, мені дедалі важче підтримувати свої дзеркальні відображення. Первісники зосередили всі зусилля на тому, щоб скинути мене з неба.\n\nАле не хвилюйся... У мене є план.\n\nВізьми сферу, яку ти здобу$p(в:ла), і збери стихійну магію з убитих первісників.\n\nЦя стихійна сила знадобиться нам попереду, щоб відвернути від мене їхні війська.",
        objectives = "Використай Стихійний Фокус, щоб витягти стихійну енергію з убитих первісників та елементалів.",
        progress = "Ми мусимо діяти швидко.",
        completion = "Ця сфера аж вирує від сили! Якраз те, що треба для наступного кроку.",
    },
    [65962] = {
        title = "Нескінченний відлік",
        description = "Ніколи не думала, що рятуватиму наш храм, розбираючи той самий захист, який ми звели, щоб його вберегти, — та ось маємо!\n\nЕлементалів часу знищено, наші Мандрівники часу вільні, а Вартові напоготові — нарешті час зняти останню бульбашку стазису й розібратися з Етернус.\n\nДай знати, коли будеш готов$p(ий:а). Знаю: коли ти поруч, нічого не може піти не так.",
        objectives = "Поговори з Хромі, коли будеш напоготові.",
        completion = "Етернус і Хромі провалилися крізь простір і час. Ми мусимо повернути їх за будь-яку ціну!",
    },
    [65977] = {
        title = "Порятунок Кірін-Тор",
        description = "Коли первісники напали на нашу експедицію, мені здавалося, що багатьох наших магів ми втратили назавжди.\n\nВиявляється, первісники захопили їх і катують просто зараз!\n\nПрошу, ти мусиш урятувати магів, які лишилися тут. Можливо, вони й не зможуть допомогти в цьому бою, але ми не можемо покинути їх напризволяще!",
        objectives = "Врятуй 6 магів, що помирають.",
        progress = "Ми мусимо допомогти тим магам.",
        completion = "Прийми мою подяку. У цій боротьбі ми не можемо покинути нікого.",
    },
    [65989] = {
        title = "Джарадини-загарбники",
        description = "Можливо, нам бракує сил, щоб відбити нашу заставу, але це не означає, що ми мусимо здаватися без бою.\n\nПокажи їм, що в нас іще є зуби.",
        objectives = "Убий 6 джарадинів біля Застави Драконячого Серця.",
        progress = "Джарадинів не бачили багато поколінь. Ми були... не готові.",
        completion = "Чудово.",
    },
    [65990] = {
        title = "Визволи драконят від лукавого",
        description = "Вони налетіли на нас, перш ніж ми встигли бодай відреагувати. Мої вартові трималися, скільки могли, поки ми евакуювали малих і беззахисних, та боюся, що на заставі їх лишилося ще більше.\n\nПерейди той міст і пошукай уцілілих.",
        objectives = "Врятуй 4 скімливих драконят із Застави Драконячого Серця.",
        progress = "Ми відіб'ємо місто, щойно зберемо сили... але зараз життя нашого народу понад усе.",
        completion = "Спочивати ще рано, але мені дихається легше від того, що ми їх урятували. Дякую.",
    },
    [65991] = {
        title = "Час розплати",
        description = "Кадетка Сендракс повідомила мене про плани мажордома Селістри. Дяка Життєдайній за їхню допомогу. Їхнє втручання дає нам перепочинок, потрібний, щоб доправити поранених до Озер Життя на лікування.\n\nЯ хотів би надіслати Селістрі підкріплення, та мушу тримати вартових біля поранених. Вирушай до ворожої твердині й зустрінься з ними там.\n\nЯкби був інший спосіб дати раду джарадинам, я вдався б до нього. Але як є...\n\nТи мусиш зробити те, що мусиш.",
        objectives = "Зустрінься з Вратіоном і мажордомом Селістрою у Фортеці Лускотрощ.",
        completion = "Серцю легшає від таких добрих звісток із Застави Драконячого Серця в такі страшні часи. Біженці будуть у безпеці біля Озер Життя.\n\nНавіть джарадини не наважаться здійняти зброю проти могуті самої королеви Алекстрази.",
    },
    [65992] = {
        title = "Відомості Чорного Пазура",
        description = "Поки ми із Селістрою привертали їхні погляди до себе нагорі, тіні прокралися крізь їхній захист.\n\nМої агенти з Чорного Пазура пильнують усю фортецю очима й вухами. Зустрінься з ними й дай їм знати, що ти на нашому боці. Вони нададуть тобі цінні відомості про наших ворогів.",
        objectives = "Поговори з Вратіоновими шпигунами, що ховаються довкола Фортеці Лускотрощ.",
        progress = "Я довіряю їм власне життя. Можеш довіряти і ти.",
        completion = "Це щонайменше тривожно. Ще одна причина з ними битися.",
    },
    [65993] = {
        title = "Зіпсоване свято",
        description = "Ах, так.\n\nНевдовзі після мого прибуття очільниця цих велетнів саме повернулася з набігу. Десь у таборі вона святкує їхню перемогу.\n\nБуло б шкода, якби хтось урвав її гуляння, чи не так?",
        objectives = "Убий М'ясоруба Сотока у Фортеці Лускотрощ.",
        completion = "Схоже, джарадинам не бракує тіл, щоб кидати їх нам під ноги... але, можливо, цей удар змусить їх замислитися. Чудова робота, друже.",
    },
    [65994] = {
        title = "Джарадинське правосуддя",
    },
    [65995] = {
        title = "Обсидіанова Цитадель",
        description = "<На перший погляд це схоже на внутрішнє листування між таборами джарадинів.\n\nСлова «Обсидіанова Цитадель» одразу впадають тобі в око.\n\nМабуть, Вратіона це зацікавило б.>",
        objectives = "Віддай Креслення Каляші Вратіону.",
        completion = "Яка розкіш! Люблю зазирати в думки своїх ворогів. Це допомагає бити швидко і влучно.\n\nПодивімося...\n\nОбсидіанова Цитадель?\n\nНі.\n\nНі!",
    },
    [65996] = {
        title = "Ветеранське підкріплення",
        description = "Командир Летанак був проникливий, як завжди. Щоб спинити цю загрозу, нам знадобиться поміч наших найдосвідченіших вартових. Зібрати їх — ідеальне завдання для юної кадетки, як-от Сендракс, але їй може знадобитися підтримка.\n\nШлях Сендракс веде на захід, який, можливо, вже захлеснула ця дедалі більша загроза. Там теж потребуватимуть допомоги. Візьми цей трунок і підтримай їх.",
        objectives = "Допоможи пораненим вартовим і знайди Сендракс.",
        progress = "Ми всі в цьому разом, {NAME}. На кону безпека островів.",
        completion = "Сендракс заскочила сюди й помчала далі. Справжній вихор, а не кадетка.\n\nВона мені подобається.",
    },
    [65997] = {
        title = "Услід за Сендракс",
        description = "Кадетка Сендракс проходила тут не так давно.\n\nВона передала наказ командира Летанака всім драконідам зібратися назад біля Озер Життя. Увесь наш оборонний полк рушив у тому напрямку невдовзі по тому.\n\nАле наші розвідники тоді патрулювали старі руїни, тож вона подалася туди, щоб зібрати і їх.",
        objectives = "Знайди Сендракс у руїнах Консерваторії Хранительки Життя.",
        progress = "Пригнися, {NAME}.",
        completion = "Я ще не читала в архівах, щоб первісники крали драконячі яйця.\n\nЦе погано. Дуже погано.",
    },
    [65998] = {
        title = "Майбутнє драконячих зграй",
        description = "Немає вищого обов'язку, покладеного на драконіда після випуску, ніж захищати кожне без винятку драконяче яйце ціною власного життя.\n\nСаме тому ми тренуємося. Тому ми існуємо.\n\nЯ більше не можу ховатися й спостерігати, {name}. Викрадаючи ці яйця й наповнюючи їх силою, первісники загрожують усьому майбутньому драконячих зграй!\n\nНас значно менше, але чи станеш ти поруч зі мною? Чи битимешся, щоб урятувати драконячі роди?",
        objectives = "Врятуй Рубінові Драконячі Яйця.",
        progress = "Така жорстокість і себелюбство... мені це годі осягнути.",
        completion = "<Сендракс помітно вражена тим, що їй довелося зробити.>\n\nСмерть була єдиною милістю, що лишилася для тих бідолашних драконят...",
    },
    [65999] = {
        title = "Кров на іклах і пазурах",
        description = "Командир Летанак попереджав нас, новобранців, що отримав звістки про втечу Пожирачки Бур, Расзаґет, з її в'язниці. Схоже, її прислужники рушили слідом за нею, загрожуючи всьому, що нам дороге.\n\nВони просуваються швидко. Під час останнього патрулювання ці руїни ще вважалися покинутими.\n\nМи мусимо зупинити первісників тут.\n\nЗа Життєдайну і за всі драконячі роди!",
        objectives = "Убий 15 первісників-нападників.",
        progress = "Драконячі роди здолають первісників.",
        completion = "<Сендракс збиває з обладунку залишки полум'я.>\n\nМи зробили, що могли. Те, що було потрібно.",
    },
    [66000] = {
        title = "Бібліотека Алекстрази",
        description = "<Сторінки цієї книги обвуглені.\n\nСхоже, первісники палять знайдені тут стародавні фоліанти, ставлячи під загрозу саму історію драконячих зграй. Наче первісники хочуть стерти драконячі роди з історії.\n\nВрятуй те, що зможеш.>",
        objectives = "Врятуй 4 культурні цінності.",
        progress = "Вітер доносить запах паленого пергаменту...",
        completion = "Наша історія вціліє.",
    },
    [66001] = {
        title = "Остання надія",
        description = "Цілий виводок драконят — втрачено...\n\n<Сендракс випростовується і піднімає підборіддя.>\n\nЄ ще одне місце, якого ми досі не перевіряли. Велике ритуальне святилище, де той протодракон лишив яйця.\n\nПрорвімося разом крізь їхню жорстоку оборону, {name}, і врятуймо стільки, скільки зможемо.",
        objectives = "Врятуй останнє Сповнене Силою Драконяче Яйце.",
        completion = "Це ж...?",
    },
    [66003] = {
        title = "Кільця, щоб скувати їх",
        description = "Тутешні джарадини обнахабніли: вони сковують вогняних елементалів і дають їм бешкетувати по всій околиці. Звірина розбіглася, а елементалі небезпечно близько до наших таборів.\n\nНа щастя, я зміг звести невеликий кам'яний бастіон, щоб устояти проти цієї вогняної повені, яку випустили джарадини... і ми не впадемо!\n\nЗбери магічні кільця, що сковують цих вогняних елементалів. Ми використаємо їх, щоб зміцнити наш захист проти вогняних елементалів.",
        objectives = "Збери 12 розплавлених кілець скування.",
        progress = "Чи зібрано всі кільця, про які я просив?",
        completion = "Чудово! Залишкову енергію цих кілець можна повернути проти їхніх творців — і прикликати конструкта під нашим контролем!",
    },
    [66004] = {
        title = "Ґалґреш",
    },
    [66005] = {
        title = "Медальйон загиблої подруги",
        description = "<Цей пожований шматок металу колись був чудовою прикрасою, дуже важливою для центаврки з Шикаару.\n\nХасар може знати більше про власницю.>",
        objectives = "Поверни медальйон загиблої подруги Касару.",
        completion = "Цей медальйон — усе, що лишилося від моєї дорогої подруги, яка минулого сезону зайшла надто далеко в болото. Я думав, його забрала стихія.\n\nЦю шкіру я вирізав після її першого полювання на мамонта. Ми тоді були дітьми.",
    },
    [66006] = {
        title = "Повернення до Роші",
        description = "Баба відпочив, а припаси Роші повернуто. Ми можемо повертатися, не засмучуючи її ще більше.\n\nВізьми з собою кілька ящиків, коли підеш. По решту я надішлю воїнів.",
        objectives = "Поверни припаси ковальці Росчі.",
        progress = "Чого так довго?",
        completion = "Припаси в тебе? Добре.\n\nЗалиш їх біля кузні.\n\n<Роша роззирається і хмурніє.>",
    },
    [66007] = {
        title = "Вільне небо",
        description = "Первісники використовують ці величезні сфери, щоб стримувати Калекґоса.\n\nЯкщо так піде далі, Калекґос буде надто поранений, щоб продовжувати бій. Якщо він упаде, я не зможу відбити Расзаґет.\n\nНаповнений силою самоцвіт, який ти тримаєш, має дозволити тобі замаскуватися під елементаля, щоб прокрастися вперед.\n\nВикористай самоцвіт, щоб знищити сфери. Це дасть Калекґосу простір, аби вивільнити свою силу.\n\nЯ зосереджуся на тому, щоб захистити вежу від Расзаґет.",
        objectives = "Знищ 4 лавові маяки.",
        completion = "Дякую, {NAME}. Тепер час показати первісникам справжню міць Аспекта синьої зграї драконів!",
    },
    [66009] = {
        title = "На захист Вактроса",
        description = "Час настав, {name}. Сили первісників у повітрі вже рідшають, відколи ти впора$p(вся:лася) зі справами на землі.\n\nЗавдяки твоїм зусиллям Расзаґет викликає одного зі своїх лейтенантів, щоб підкріпити війська первісників.\n\nМені потрібно, щоб ти впора$p(вся:лася) з цим чудовиськом, поки я пробиватимусь уперед, щоб стати до бою з Расзаґет і допомогти Хадґару.\n\nВиглядай мою магію під час бою. Я зроблю все, що зможу, аби тобі допомогти.\n\nНастав час Расзаґет зустрітися з люттю Аспекта магії!",
        objectives = "Здолай Кортрокса Руйнівника.",
        completion = "Радий бачити тебе, шукачу пригод. Час не жде!",
    },
    [66011] = {
        title = "Пам'яті Ісери",
        description = "О ні! Здається, тепер я розумію. Терамус... він сумує за Ісерою, а вона не може повернутися.\n\nХодімо! Гадаю, я знаю, куди він пішов. Ми не турбуватимемо його більше, та варто сказати йому, що нам шкода, і що ми дамо йому той простір, якого він прагне.\n\nМи є одне для одного, серед природи, що нас оточує.",
        objectives = "Знову знайди Терамуса.",
        progress = "Ми вдячні, що ти й досі з нами, {race}. Твоя допомога неоціненна.",
        completion = "<Терамус мовчки споглядає щойно відновлене святилище.>",
    },
    [66012] = {
        title = "Запечатані двері",
        description = "Наші розвідники прочісували Драконові Острови в пошуках чогось цікавого. Вони повернулися з безліччю важливих знахідок, але одне відкриття вирізняється з-поміж усіх — двері.\n\nДвері, викувані титанами й запечатані від світу. Нікому ще не вдалося знайти шлях до артефактів, що, безперечно, лежать усередині.\n\nАле ж жодна таємниця не встояла перед прозірливим поглядом Реліквіарію.\n\nЗ допомогою Ліги Дослідників упоратися буде нескладно, я певна.",
        objectives = "Вирушай до Запечатаних Дверей у Талдразусі й поговори з Налейдеєю.",
        completion = "Гадаю, для когось із твоїми здібностями ця подорож була дрібницею.",
    },
    [66013] = {
        title = "Дослідити двері",
        description = "Ось ми й на місці. Якщо ми хочемо пройти крізь ці двері, нам треба зрозуміти, хто їх замкнув і як.\n\nРоззирнися довкола — може, знайдеш щось, що дасть нам відповіді, яких ми шукаємо.",
        objectives = "Обшукай місцевість у пошуках зачіпок.",
        progress = "Яка захоплива знахідка. Як гадаєш, що там, по той бік?",
        completion = "Самого цього нам замало — потрібно більше зачіпок.",
    },
    [66015] = {
        title = "Камінь клятви синіх драконів",
        description = "Лазуровий Простір поки що стабілізувався, і прибуло більше синіх драконів... якраз вчасно.\n\nЧас рушати до Лазурових Архівів — і повернути собі камінь клятви.\n\nЯ просив би тебе бути там, {name}. Ти бу$p(в:ла) великою підтримкою впродовж усього цього випробування.",
        objectives = "Супроводь Калекґоса, щоб повернути Камінь Клятви синіх драконів.",
        progress = "Мені значно легше від того, що ви не дали цілком знищити Лазуровий Простір.\n\nПродовжимо?",
        completion = "Камінь клятви знову наснажено. Роботи ще багато... але Лазуровий Простір принаймні стає таким, як колись.",
    },
    [66016] = {
        title = "Клан Тіраї",
        description = "<Поки хан Сансок говорить жестами, Окір озвучує її слова.>\n\nКлан Тіраї — це клан нашої Ханам Матри, наш прямий зв'язок із предками Марууків. Вони — берегині наших традицій і наші оповідачі.\n\nЩоб зрозуміти Марууків, ти маєш зрозуміти клан Тіраї. Одна з дочок Ханам Матри, Каріін Дотур, готує трапезу для наших предків. Допоможи їй. Від неї ти дізнаєшся про наш народ.",
        objectives = "Зголосися до Каріін Дотур.",
        completion = "Вітаємо тебе, чужинцю.",
    },
    [66017] = {
        title = "Клан Он'ір",
        description = "<Поки хан Сансок говорить жестами, Окір озвучує її слова.>\n\nМістики наших земель, як-от Он Сештенг, належать до клану Он'ір. Цей клан складається не з родин, а з кентаврів з усіх куточків рівнин, що мають вроджений зв'язок з Он'агрою. Вони присвячують своє життя зміцненню цього зв'язку та вдосконаленню своїх умінь. Зрештою вони отримують доручення радити різним кланам і захищати наші землі.\n\nОн Сештенг пішла поговорити про отримане знамення зі своєю хан. Приєднайся до неї, щоб дізнатися про Он'ірів.",
        objectives = "Зустрінься з Он Сештенг біля містичних озерець.",
        completion = "Добре знову бути зі своїм кланом.",
    },
    [66018] = {
        title = "Клан Нохуд",
        description = "<Поки хан Сансок говорить жестами, Окір озвучує її слова.>\n\nКлан Нохуд — наймолодший із тих, що піднялися до влади. Їхній покійний хан, Джакан, зібрав могутнє військо, щоб відібрати землі в попередників. Такий звичай нашого народу.\n\nДжакан здобув повагу, але його син — ні. Балакар убив свого батька й перебрав владу над кланом. Відтоді вони ще більше замкнулися в собі. Та щоб пізнати Марууків, ти маєш пізнати і їх.",
        objectives = "Супроводь Томул до вартової Бахір.",
        completion = "Маю превелику неприємність відрекомендувати тобі Бахір, одну з посіпак хана Балакара.",
    },
    [66019] = {
        title = "Шана нашим предкам",
        description = "Наші предки крокують поряд із нами на вітрах Он'агри, ведуть і захищають нас. Усі Марууки, мертві й живі, збираються під перемир'ям на Куралі.\n\nЗапах цієї трапези прикликає предків до нашого вогнища. Коли вони прийдуть, почнеться Курал.",
        objectives = "Допоможи Каріін Дотур приготувати трапезу для предків.",
        progress = "Марууки повертаються на це місце покоління за поколінням. Ми крокуємо пліч-о-пліч із нашими предками.",
        completion = "Наші предки багато чим ризикували заради нашого майбутнього. Справедливо запросити їх зібратися поруч із нами.",
    },
    [66020] = {
        title = "Знамення й пахощі",
        description = "Я розповіла хан Тіґарі про знамення, яке ми отримали, перш ніж увійти до Маруукаю. Вона занепокоїлася, бо вітер і їй здався холодним.\n\nМи вирощуємо тут особливі квіти — суцвіття, що їх можна змолоти й спалити, аби викликати стан, подібний до трансу. Так ми поглиблюємо свій зв'язок зі знаменням.\n\nПрошу тебе зібрати кілька таких квітів, щоб ми могли зробити пахощі й запалити їх. З допомогою моєї хан ми, можливо, дізнаємося більше про біду Он'агри.",
        objectives = "Збери 5 суцвіть солодколозу, змели їх на пахощі з солодколозу, а тоді допоможи Он Сештенг із ритуалом.",
        progress = "Хан Тіґарі найкраще знається на тлумаченні знамень. З її допомогою ми дізнаємося більше про це знамення.",
        completion = "Зрада загрожує самій Он'агрі. Ми мусимо вистояти, {NAME}. Нині час союзників.",
    },
    [66021] = {
        title = "Небажаний чужинець",
        description = "Ха! Поглянь на себе. Сама слабкість. Як і ті нікчемні мисливці, що привели тебе сюди.\n\nХочеш пізнати Нохудів? Наша мова — битва.\n\nНаш бойовий ритуал зветься «табарр». Ми тренуємося. Ми б'ємося. І це гартує нас. Тепер у нашому клані немає слабкості.\n\nДосить балачок. Іди бийся.",
        objectives = "Здолай 6 кентаврів клану Нохуд.",
        completion = "Нохуди понад усе цінують грубу силу й могутність.\n\nМи з ними багато в чому не сходимося.",
    },
    [66022] = {
        title = "Ханам Матра",
        description = "Я не можу затримуватися в землях кентаврів; мушу повернутися до садів, щойно зможу.\n\nХанам Матра погодилася вислухати наше прохання про допомогу. Вона чекає на мене на вершині крутала, центральної будівлі Маруукаю.\n\nСпершу я маю поговорити з нею сама, а тоді ласкаво просимо приєднатися до нас.",
        objectives = "Зголосися до ханського гвардійця Акато, щоб приєднатися до аудієнції Ґемісат у Ханам Матри.",
        progress = "Ханам Матра чекає на тебе.",
        completion = "От зрадливий дурень.\n\n<Акато спльовує на землю.>",
    },
    [66023] = {
        title = "Порушники перемир'я",
        description = "Балакар ганьбить свій клан. Він веде його в бурю, осліплений жагою влади.\n\nЦя зрада виказує їхню слабкість. Знищ їх.",
        objectives = "Убий 10 бійців Нохудів.",
        progress = "Напасти на Ханам Матру... це зречення наших звичаїв.",
        completion = "Шлях, який вони обрали, тепер заплямований кров'ю.\n\nРозвідниця Томул намагалася попередити нас, що таке може статися. Можливо, вона має й інші підозри.",
    },
    [66024] = {
        title = "Прикриваючи свої хвости",
        description = "Нохуди марять воєнними переказами про давнє минуле нашого роду. Насправді ж вони слабкі — діти, що бавляться у війну. І одним ударом блискавки вони обірвали свій зв'язок з Он'агрою.\n\nЩо ж! Якщо задля війни вони ладні йти шляхом зіпсуття — ми вдовольнимо їхнє бажання.\n\nЗвісно, Балакар лишив командувати Бахір, щоб прикрити власну втечу. Незабаром її кров заплямує землю.",
        objectives = "Убий вартову Бахір.",
        progress = "<Сарест озирає поле бою, примруживши очі.>",
        completion = "Балакар був легкою здобиччю для розтлінного впливу Королет.\n\nБуря прийшла.",
    },
    [66025] = {
        title = "Загроза від Нохудів",
        description = "Військо клану Нохуд захоплює Маруукай.\n\nОбговорімо наші наступні кроки в ханських покоях. Ми мусимо вберегти Марууків.",
        objectives = "Обговори наступні кроки.",
        completion = "У небезпеці сама життєва сила Марууків.",
    },
    [66026] = {
        title = "Потрібні негайні дії",
        description = "Джерело цих нападів — напевно Папоротешкурі.\n\nМи б'ємося з гнолами Папоротешкурих уже багато поколінь, але досі вони були не більш ніж дрібною прикрістю.\n\nУ нас немає вибору, окрім як негайно діяти проти гнолів. Їхня мерзенна гниль знищить Лазуровий Простір, разом з усім, що ти шукаєш.\n\nЗустрінься з нами біля Лощини Папоротешкурих. Нам знадобиться вся можлива допомога.",
        objectives = "Зустрінься з Бреною біля Лощини Папоротешкурих.",
        completion = "Навіть просто стоячи тут, я відчуваю, як мене огортає жах цього лісу. Тут щось глибоко не так.\n\nМені вже починає здаватися, що дарма ми відіслали нашого найкращого бійця назад до Іскаари.",
    },
    [66027] = {
        title = "Поклик до синіх драконів",
        description = "Я більше не можу боятися возз'єднати синіх драконів, {name}. Краще нам бути родиною... ніж лишатися тінню нас колишніх.\n\nНавіть якщо я не зможу повернути собі камінь клятви, я все одно скористаюся його силою, щоб надіслати звістку всім синім драконам.\n\nНастав час їм почути слово... від свого Аспекта.",
        objectives = "Стань свідком того, як Калекґос кличе назад синю зграю драконів.",
        progress = "Відійди, {NAME}.",
        completion = "Нам треба рушати, {NAME}.",
    },
    [66028] = {
        title = "У майбутнє!",
        description = "Я простежив шлях Хронорму й Етернус до одного з можливих майбутніх. Не знаю, що ти там знайдеш, — лиш те, що воно темне й хаотичне.\n\nСоридормі повела частину наших мандрівників часу вперед, до того майбутнього, щоб утримати наш зв'язок із тим часом стабільним. Уся її чимала сила піде на те, щоб тримати портал відкритим, тож вона покладатиметься на твій хист.\n\nСоридормі дасть тобі подальші вказівки, коли ти зустрінеш її там.\n\nПоспішай, {name}. Знайди Хронорму.",
        objectives = "Вирушай у майбутнє первісників.",
        completion = "Треба знайти Хромі та Етернус, перш ніж цьому часові буде завдано ще більшої шкоди.",
    },
    [66029] = {
        title = "Темпоральне налаштування",
        description = "Хронорму й Етернус падають крізь час, але я відчуваю, що іноді вони спиняються. Ці короткі миті — наша нагода їх знайти.\n\n<Ноздорму створює невеликий хронокристал.>\n\nЯ наповнив цей кристал силою, а також власним темпоральним резонансом. Вони потрапили в... тривожне можливе майбутнє. Знайди їх і скористайся кристалом. Сподіваюся, ти встигнеш зафіксувати їхнє положення в часі, перш ніж вони знову вислизнуть.",
        objectives = "Використай хронокристал на Етернус і Хромі в майбутньому первісників, щоб спинити їхнє падіння крізь час.",
        completion = "Процес не завершено, але тепер я можу точніше відстежувати Хронорму.",
    },
    [66030] = {
        title = "Спротив не марний",
        description = "Темпоральні брижі завдали клопоту тутешнім людям. Вороги з'являються там, де їх не було, або стають набагато сильнішими, ніж мали б. Ці зміни малі, але згубні.\n\nПрошу тебе допомогти тутешнім бійцям спротиву. Зціли їхні рани, щоб вони могли знову битися. Поверни їхню часову лінію на правильний шлях, ніби вона ніколи й не перетиналася з нашою. Це небагато, але це все, що ми можемо для них зробити.",
        objectives = "Зціли бійців спротиву в майбутньому первісників.",
        progress = "Чи вдалося тобі допомогти спротиву?",
        completion = "Ці відважні бійці знову зможуть зміцнити свої лави.",
    },
    [66031] = {
        title = "Виграти час",
        description = "Гадаю, мені не варто дивуватися, що я опинилася тут.\n\nЦе не той Азерот, якого я прагнула, але це той, що в мене є. Ми б'ємося, щоб зберегти те, що лишилося, і повернути собі світ, та твоя поява наробила біди.\n\nМи використовуємо есенцію тих елементалів там, аби живити наш захист і вберегти себе. Бачиш отой щит? Це єдине, що рятує нас від викриття та знищення, а ти виснажи$p(в:ла) наші запаси. Принеси трохи тієї есенції, і ми, можливо, протримаємося ще день.",
        objectives = "Збери есенцію елементалів для табору вцілілих.",
        progress = "Чи зібрано те, що нам потрібно?",
        completion = "Завдяки тобі ми маємо перепочинок.",
    },
    [66032] = {
        title = "Повернення в сьогодення",
        description = "Ця часова лінія темна й хаотична. Розлад часу тут був тяжкий. Я ще трохи побуду в цій часовій лінії, щоб дати раду брижам, які ще можуть з'явитися.\n\nПовертайся до Ноздорму. Він захоче дізнатися про наш успіх, навіть якщо той був не таким повним, як нам хотілося б.",
        objectives = "Повернися до Ноздорму в сьогодення.",
        completion = "Твоя мандрівка не досягла нашої мети, та все ж була успішною.",
    },
    [66033] = {
        title = "У... минуле?",
        description = "Прикро, що нам не вдалося стабілізувати Хронорму, але є ще одне можливе місце, де ми зможемо її перехопити й покласти край її падінню крізь час.\n\n<Ноздорму супить брови.>\n\nПроблиски минулого цієї часової лінії... дивні. Навіть як на ті видіння, що я споглядав за своє життя.\n\nБудь насторожі, {name}. Я не певен, із чим ти зіткнешся, але воно могутнє і... дивно знайоме.",
        objectives = "Пройди крізь портал і зустрінься з Андантенорму в Азмерлоті.",
        completion = "Хай чого я очікував... але точно не цього.",
    },
    [66035] = {
        title = "Мурлоцькі частинки",
        description = "Альтернативна часова лінія, що зродилася з мурлоків??!\n\nВибач мені це себелюбне прохання, та чи не $p(міг:могла) би ти зібрати кілька розсіяних частинок темпоральної енергії, поки шукатимеш посланницю Хронорму?\n\nПросто заходь у них, а твій посох зробить решту. Я вивчу дані пізніше. Коли ми не будемо в розпалі мандрів крізь розриви в розмаїтих реальностях Азерота.",
        objectives = "Поглинь 12 часових частинок.",
        progress = "Не сумніваюся, що сьогодні ми здолаємо нескінченних, а вивчення цієї чужорідної енергії стане нам нагородою!",
        completion = "Приголомшлива робота!\n\nА тепер — як гадаєш, що за мурлоки живуть у цьому Мурлочому Світі? Аж моторошно уявити...",
    },
    [66036] = {
        title = "Муґурлґлрлґл!",
        description = "Мрґлґулґлррлґлґул! Ґрурґуґлуллґурл!\n\nҐруґлрлґллруґл ррґулґрулґрґл ґруґлл ґурґулл ґур. Мурґллґллруґл ґурґллґлрл Мурґул ґруґґуллґл. Мурґуґлеґурґллґур ґурґлл ґурґулґул ґуруулґурллґр ґууґлрллґл.\n\nМґрґулллґллл ґурл ґуґлл.\n\n<Ти не $p(певен:певна), що саме він каже, але він раз у раз замахується, наче штрикає когось ножем. Схоже, цей мурлок хоче, щоб ти когось уби$p(в:ла).>",
        progress = "Мурґлґулґлррлґлґул!",
        completion = "Фррґ трґ Аллрґннґе!\n\n<Мурлоки, схоже, задоволені.>",
    },
    [66037] = {
        title = "Назад до реальності",
        description = "Нам удалося зміцнити зв'язок посланниці Хронорму з нашим часом. Поза сумнівом, коли ми знайдемо її знову, то зможемо завершити ритуал.\n\nА поки що повернімося в наше сьогодення — у світ зі... значно меншою кількістю мурлоків.",
        objectives = "Повернися до Ноздорму в сьогодення.",
        completion = "Дякую за допомогу в підтримці часових ліній... хай якими дивними вони часом бувають.",
    },
    [66038] = {
        title = "Перегони крізь час!",
        description = "{name}, ми мусимо діяти швидко, щоб наздогнати посланницю Хронорму, і я кажу це цілком буквально.\n\nМи із Зерою зробимо все можливе, аби пришвидшити наш поступ, але вкрай важливо якомога менше вплутуватися в цей часовий період. Інакше ми сповільнимося й можемо не встигнути впіймати посланницю, перш ніж вона стане недосяжною навіть для магії Ноздорму.\n\nНе можна гаяти ні миті!\n\n(Прийнявши це завдання, ти запустиш відлік часу)",
        objectives = "Мчи крізь час слідом за Хромі та Етернус.",
        completion = "Клянуся Аспектами... Це Чорна Імперія!",
    },
    [66039] = {
        title = "Час Хромі",
        description = "Це... Це Чорна Імперія. Ми й справді зайшли дуже далеко в минуле.\n\nДивись! Я бачу посланницю Хронорму й Етернус! Нам треба поспішити й завершити ритуал.\n\nНавіть моєї цікавості не вистачає, щоб захотіти побачити, куди вони можуть податися далі.",
        objectives = "Знайди Хромі та заверши ритуал темпоральної стабілізації.",
        completion = "Оце вже значно краще!\n\nО, за Етернус не хвилюйся. Ми з нею наразі уклали щось на кшталт перемир'я.",
    },
    [66040] = {
        title = "Назад у майбутнє",
        description = "Ми більше не падатимемо крізь час, але ми далеко в минулому. Дуууже далеко в минулому. Настільки далеко, що «Титани ще навіть не відвідали Азерот». Дістатися додому буде... непросто.\n\nАле ми, дракони, впораємося!\n\nТреба тільки, щоб ти відганя$p(в:ла) від нас отих прислужників Чорної Імперії. Це не має забрати багато часу!\n\nГадаю.\n\nМабуть.\n\nТа не хвилюйся! Просто тримай отих моторошних чудовиськ подалі, а решту ми владнаємо! Простіше простого!",
        objectives = "Захищай союзників від сил Чорної Імперії, доки не буде створено темпоральний портал.",
        progress = "Це був... несподіваний поворот подій.",
        completion = "Час знову стабільний.",
    },
    [66042] = {
        title = "Візерунки всередині візерунків",
        description = "Ми стоїмо біля самого витоку Тіньокраю. Не можна допустити, щоб це місце стало його згубою.\n\nПрацюй разом із нашими новими союзниками, {name}. Їхня допомога вирішить, чи переможемо ми, чи все суще загине.",
        objectives = "Допоможи своїм союзникам у Зерет Мортісі, виконуючи світові завдання, щоденні завдання, забираючи скарби та вбиваючи рідкісних істот.",
        completion = "Ми наближаємось до мети. Уперед і тільки вперед.",
    },
    [66044] = {
        title = "Штурм мурів",
        description = "Сабелліан та інші дракони поки що стримують джарадинів. Треба діяти швидко: захопити високі вежі й закріпити нашу перемогу.\n\nМи з тобою знищимо облогові арбалети, що загрожують нам згори.\n\nДай знати, коли будеш готов$p(ий:а).",
        objectives = "Знищ три облогові арбалети та чемпіона Чорука.",
        progress = "Чи знищено арбалети й чемпіона Чорука?",
        completion = "Чудова робота, {NAME}. Сабелліан із військом стримуватиме джарадинів, поки я активую Камінь Клятви, щоб відновити силу.",
    },
    [66048] = {
        title = "Найкращі плани й наміри",
        description = "Напасти на джарадинів, що володіють Обсидіановою Цитаделлю, буде непросто. Навіть із Вратіоном і його військом Чорного Пазура на нас чекає лютий бій. Вратіон, може, і впевнений, але... я не настільки.\n\nЗвернімося до тих, хто допомагає складати стратегію, і подивімося, чи не можна її покращити.",
        objectives = "Обговори плани з різними бійцями війська Вратіона.",
        progress = "Чи можеш ти підвищити наші шанси на успіх?",
        completion = "Зрозуміло. Я, звісно, уважно обміркую твою оцінку.",
    },
    [66049] = {
        title = "Обсидіановий Камінь Клятви",
        description = "Коли Нелтаріон став Хранителем Землі, він присягнувся захищати цей світ, {name}. Берегти найглибші місця землі й разом зі своїм роєм бути захисником Азерота. Обсидіановий Камінь Клятви — символ цієї обітниці.\n\nМи маємо активувати камінь і сповістити Драконові Острови, що чорна зграя драконів повернувся!\n\nЗа мною, {name}.",
        objectives = "Знайди Обсидіановий Камінь Клятви.",
        progress = "Тобі вже вдалося побачити Камінь Клятви?",
        completion = "Це прикра перешкода, але з твоєю допомогою ми, певен, полагодимо Камінь Клятви. Працюй із Базентусом... зроби це.",
    },
    [66055] = {
        title = "Розбите минуле",
        description = "Камінь Клятви пошкоджено! Бракує кількох частин.\n\nЗроби все можливе, щоб роздобути уламки... можливо, є спосіб полагодити камінь!",
        objectives = "Здобудь 12 уламків Каменя Клятви.",
        progress = "Чи знайдено втрачені уламки Каменя Клятви?",
        completion = "Схоже, це всі частини. Гадаю, ми зможемо це полагодити!",
    },
    [66056] = {
        title = "Кувати нове майбутнє",
        description = "Кузня Хранителя Землі — наймогутніша з усіх драконячих кузень, що існують. Наші предки кували в ній найміцнішу зброю та обладунки, щоб захищати Азерот.\n\nУ серці тієї кузні криється сила, потрібна, щоб знову з'єднати розбиті уламки Каменя Клятви.\n\nХодімо й підготуймо кузню до роботи.",
        objectives = "Підготуй кузню Хранителя Землі.",
        progress = "Чи завершено потрібну нам роботу?",
        completion = "Дуже добре. Тепер, коли прибув наш принц, можемо починати.",
