    [66210] = {
        title = "Зібрати родину",
        description = "Твій друг Калекґос хоче поговорити про лінії лей, але треба підготуватися до похорону.\n\nПоки я розмовлятиму з ним, збери, будь ласка, останні дари довкола Іскаари й поклади їх до похоронного човна поруч із любим старим Поноляком.\n\nСподіваюся, ти також знайдеш хвильку, щоб помилуватися містечком! Мій народ радо тебе привітає, надто після твоєї допомоги проти Папоротешкурих.",
        objectives = "Збери 4 похоронні дари довкола Іскаари, а тоді поклади їх у похоронний човен.",
        progress = "Чи перепала тобі вже миска супу?",
        completion = "Твій друг такий допитливий! Він хоч колись дозволяє собі перепочити?",
    },
    [66211] = {
        title = "Лощина Брекенгайд: до джерела",
        description = "Ми не можемо віддячити тобі сповна за допомогу в боротьбі з ґнолами Брекенгайду.\n\nАле вони й далі збираються, живлячи свою мерзенну магію тліну з якогось джерела глибоко в Лощині Брекенгайд. Гірше того, ми вже кілька тижнів нічого не чули про тускарів із тих країв.\n\nБоюся, там коїться щось жахливе. Ми мусимо захистити свій дім. Прошу, збери свої сили, знайди наших людей і поглянь, що можна вдіяти з цим тліном!",
        progress = "Ми мусимо врятувати наших людей і зупинити поширення тліну!",
