    [66675] = {
        title = "Сила Аспектів",
        description = "Материнський Камінь Клятви — це прадавній дар, який Титани піднесли нашим зграям. Якщо те, що ми дізналися, правда, можливо, мені вдасться знову його активувати й цим відновити наші сили аспектів.\n\nХоч ми й не певні наслідків, та якщо є бодай найменший шанс на успіх, я мушу спробувати.\n\n{name}, я була б вдячна, якби ти долучи$p(вся:лася) до мене в цьому.",
        objectives = "Допоможи Алекстразі біля Материнського Каменя Клятви.",
        completion = "Що сталося, {NAME}? Де Алекстраза?",
    },
    [66676] = {
        title = "Прокрастися всередину",
        description = "Це Лізі... вона моя таємна подруга. Я доглядаю її, відколи її відштовхнула мати.\n\nСправи кепські. Те, що з нею зробили, поза межами мого знання. Я мушу відвести її додому. Мій Он, може, покарає мене до кінця віку, та Лізі потрібна допомога. Я безмежно вдячна тобі, {name}. Шкода, що це завдало більше клопоту, ніж ти сподіва$p(вся:лася).\n\nЯкщо не проти ще однієї пригоди... зустрінь гнів мого Она разом зі мною? Чекаю на тебе біля джерел.",
        objectives = "Повернися до Радії біля Джерел Он'ірі.",
        completion = "Ти поверну$p(вся:лася)! Поглянь — з Лізі все буде гаразд.",
    },
    [66679] = {
        title = "Коло Рубінового Святилища Життя",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
