    [66704] = {
        title = "Муґурлґлрлґл!",
        description = "Мрґлґулґлррлґлґул! Ґрурґуґлуллґурл!\n\nҐруґлрлґллруґл ррґулґрулґрґл ґруґлл ґурґулл ґур. Мурґллґллруґл ґурґллґлрл Мурґул ґруґґуллґл. Мурґуґлеґурґллґур ґурґлл ґурґулґул ґуруулґурллґр ґууґлрллґл.\n\nМґрґулллґллл ґурл ґуґлл.\n\n<Ти не $p(певен:певна), що саме він каже, але він раз у раз замахується, наче штрикає когось ножем. Схоже, цей мурлок хоче, щоб ти когось уби$p(в:ла).>",
        objectives = "Мурґлґулґлррлґлґул!",
