    [66724] = {
        title = "Сяйвориболка",
        description = "Прикро, що тебе втягнули в це, $p(мандрівнику:мандрівнице).\n\nМій брат схильний... захоплюватися надміру. Це лише остання з його дурниць. Та ця може коштувати йому життя.\n\nМене він не слухає. Тебе він, певно, теж не послухає.\n\nА от наша прародителька, Каурік Сяйвориболка, - осердя його одержимості. Її він, можливо, послухає.\n\nБудь ласка, налови трохи сяйвориб і принеси їх сюди. Я використаю їх, щоб допомогти нам поспілкуватися з її духом, що досі живе в цьому камені.",
        objectives = "Принеси 3 сяйвориби й поклади їх у кошик для підношень.",
        progress = "Не всі мої задуми вдавалися, але це не означає, що не вдасться цей!",
        completion = "Ти ж усе це чу$p(в:ла), геро$p(ю:їне)?",
    },
