    [66779] = {
        title = "Очевидний спадкоємець",
        description = "Як спадкоємець Нелтаріона й очільник єдиного вцілілого рою чорних драконів, я не сподівався, що доведеться змагатися за те, що моє за правом народження. І вже точно не проти пихатого щеняти, молодшого за тебе, смертн$p(ий:а).\n\nТа якщо тобі замало цих очевидних фактів, поговори з драконами мого рою. Не мусиш вірити мені на слово.",
        objectives = "Поговори з прибічниками Сабелліана.",
        progress = "Мій рій чекає.",
        completion = "Сподіваюся, тепер тобі все зрозуміло.",
    },
    [66780] = {
        title = "Претендент на трон",
        description = "Я знову й знову присвячував себе порятунку Азероту від загибелі, а цей дурень гадає, що може просто звалитися з неба й привласнити титул Аспекта? Аж ніяк.\n\nПоговори з моїми прибічниками, {name}. Послухай, що вони скажуть про мене і про те, що я зробив для цього світу.",
        objectives = "Поговори з прибічниками Вратіона.",
        progress = "Їхня відданість беззаперечна.",
        completion = "Ти ж, певна річ, підтримуєш моє право, чи не так, {NAME}?",
