    [66834] = {
        title = "Реллен Учений",
        description = "Принеси свої дари до центрального лігва. Там ти зможеш побачити легенду про Реллена Ученого, який дав кентаврам той спосіб життя, що ми знаємо нині.",
        objectives = "Зроби підношення в лігві для підношень і побач кожне з повчань Реллена.",
        progress = "Лігво для підношень стоїть у центрі Тіракай.",
        completion = "Реллен утвердив кентаврів на цих рівнинах. Без його наук ми б нізащо не вижили.",
    },
    [66835] = {
        title = "Траса Сонцекрапного гаю",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
