    [66890] = {
        title = "Викрадені інструменти",
        description = "Гнолли не дають нам спокою, нападаючи на наші каравани з припасами. Здається, вони просто одержимі різноманітними інженерними інструментами, які ми перевозимо. Ми не можемо ризикувати, щоб ці буйні нападники розгадали наше особливе ремесло! До того ж ці крадіжки відкинули наш виробничий графік далі назад, ніж мені хотілося б визнавати.\n\nЯкщо ти зможеш повернути частину викрадених інженерних деталей, ми надолужимо графік.",
        objectives = "Збери 20 Вкрадених Інструментів у гнолів Драконових Островів для Дотеноса з Валдраккенської угоди.",
        progress = "Тобі вдалося повернути викрадені інструменти?",
        completion = "Ці деталі допоможуть нам повернутися до наших інженерних проєктів.",
    },
    [66891] = {
        title = "Вибухова зола",
        description = "Розплавлені фенікси Драконових островів, помираючи, лишають по собі незвичайну золяну речовину. Її можна було б використати, щоб поліпшити матеріали для складних механізмів, які змінюють життя. Хоча я, мабуть, пустив би її радше на вибухівку.",
        objectives = "Збери 20 Вибухового Попелу з феніксів Драконових Островів для Ґнокліна Квіркойла з Експедиції Драконячої Луски.",
        progress = "Тобі вдалося назбирати досить золи?",
        completion = "Ця зола могла б стати важливою складовою для безлічі механізмів, що полегшили б життя людей по всьому Азероту. Та кого я обманюю? Ми зробимо з неї вибухівку. БУМ!",
    },
    [66892] = {
        title = "Потопна халепа",
        description = "Елементалі вбивають рогоступів! Я вмію приборкувати великих звірів, але ніколи не думав, що доведеться стати на герць з елементалем! Це тобі не якісь там малі громоящери...\n\n<Дазакрос засмучено зітхає.>\n\nБудь ласка, повали кількох цих елементалів. Рогоступи набагато тямущіші, ніж ми звикли вважати. Вони дадуть відсіч, якщо матимуть змогу!",
        objectives = "Убий 12 водяних елементалів у Переповнених Порогах.",
        progress = "Якщо битися з елементалями бодай трохи схоже на приборкання ящерів, то просто дай цим мокрим нікчемам добрячого щигля по носі — і вони враз стануть шовковими!",
        completion = "А я гадав, що вже все на світі бачив. Ти тільки поглянь, як ці малі вигулькують із джерела!\n\nВиявляється, бути доглядачем не так уже й легко. Дякую за поміч, {NAME}. Я багато чого від тебе навчився!",
    },
    [66893] = {
        title = "Дзьобате одужання",
        description = "Я, може, нічого й не тямлю у водяних елементалях, зате на рогоступах знаюся!\n\nЯ нашвидкуруч приготував мазь, яка тримає рогоступів здоровими й готовими до бою. Мені ще ніколи не випадало нанести її на справжнього рогоступа, але я вивчив усе, що тільки міг.\n\nЧас набратися хоробрості й добряче їх намастити!",
        objectives = "Зціли 8 поранених рогоступів у Переповнених Порогах.",
        completion = "Аж на душі теплішає, коли бачиш, як рогоступи повертають собі домівку. Це ти подарував їм таке, {NAME}. Дякую за допомогу.",
    },
    [66894] = {
        title = "Що новий ватажок, що старий",
        description = "Драконіди Світоламів — народ довірливий. За ці роки ми йшли за багатьма різними проводирями, вірячи, що кожен з них приведе нас до Години Сутінків і повернення Дезвінга.\n\nОднак Дезвінг так і не повернувся, і Сутінків досі немає.\n\nЧас обрати нового проводиря. Ти можеш допомогти здійснити цю зміну.",
        objectives = "Знищ Айзіра Розпаленого.",
