    [66945] = {
        title = "Крижане чорнило",
        description = "Крижані звірі в замерзлих краях виділяють вельми рідкісну й загадкову рідину. Завдяки своїм властивостям вона ідеально пасує як зв'язувальна речовина для наших чорнил. Я шульга, тож думка про те, що більше не доведеться розмазувати написане, мене дуже тішить.",
        objectives = "Збери 20 Крижаних Випорожнень із крижаних павуків і крижаних ведмедів Драконових Островів для Дотеноса з Валдраккенської угоди.",
        progress = "Тобі вдалося зібрати крижані виділення?",
        completion = "Дякую за старанну працю. Із цього вийде чудове чорнило.",
    },
    [66946] = {
        title = "Перегони Лазурового кряжа",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [66947] = {
        title = "Перегони Лазурового кряжа - просунутий рівень",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [66948] = {
        title = "Прибуття посланниці",
        description = "Зізнаюся, що за все життя я ніколи не покидала Смарагдових Садів, а тому ніколи не зустрічала ані кентавра, ані тим паче смертного з материка.\n\nОднак я тут не з дружнім візитом — я прибула благати кентаврів про допомогу: нам треба вберегти наш камінь клятви й захистити тих, хто під нашою опікою.\n\nРада бачити, що й ти тут, щоб допомогти. Нам багато про що треба поговорити.",
        objectives = "Дізнайся про становище у Смарагдових Садах.",
        progress = "Зелена драконяча зграя втратила чимало за ці роки. Нам потрібна допомога смертних, де тільки можливо.",
        completion = "Ще більше приязних облич — це справді на добро.",
    },
    [66949] = {
        title = "Викрадачі дрібничок",
        description = "У гнолів зібралася чимала колекція дрібничок. Дрібничок тускарів. Вони або викрали їх із наших селищ, або, ще гірше, зняли з відважних тускарів, які полягли в бою проти них. Ці дрібнички — наша спадщина, і їм належить бути в нас.\n\nЯкщо принесеш мені кілька, я навчу тебе прийомів, якими їх виготовляють.",
        objectives = "Збери 10 Вкрадених Дрібничок у гнолів Драконових Островів для Темнааю з Тускарів Іскаари.",
        progress = "Тобі вдалося повернути викрадені дрібнички в гнолів?",
        completion = "Я впізнаю ці дрібнички. Пам'ятаю тих, кому вони належали. Дякую, що повернув їх нам.",
    },
    [66950] = {
        title = "Серце велетня",
        description = "Кажуть, що в серцевині деяких велетнів Драконових островів криються прекрасні самоцвіти. Зазвичай ми не полюємо на створінь островів заради скарбів, але ці велетні наробили чимало лиха.\n\nОтож можемо заразом зібрати ці самоцвіти, поки розчищаємо острови від руйнівних велетнів.",
        objectives = "Збери 5 Сердець Велетнів із гірських, крижаних чи розплавлених велетнів Драконових Островів для Темнааю з Тускарів Іскаари.",
        progress = "Тобі вдалося знайти якісь самоцвіти в нутрощах велетнів?",
        completion = "Це й справді прекрасні скарби.",
    },
    [66951] = {
        title = "Контроль популяції",
        description = "Останнім часом на Драконових островах розплодилося кілька видів. Зокрема, скелезуби та бруфалони.\n\nМи, звісно, не хочемо марнувати здобич. Неодмінно збери з цих створінь якомога більше шкур.",
        objectives = "Збери 25 Врятованих Шкур зі скелезубів і бруффалонів Драконових Островів для Темнааю з Тускарів Іскаари.",
        progress = "Тобі вдалося впоратися з перенаселенням і принести трохи шкур?",
        completion = "Дякую, що владнав ситуацію й не змарнував шкур.",
    },
    [66952] = {
        title = "Гнолячі вбрання",
        description = "Гноли — постійна загроза: вони влаштовують криваві набіги й напади на експедиції та народи Драконових островів. То як же їхній одяг лишається таким чистим?\n\nПісля сутичок із цими нападниками не міг би ти зібрати для мене зразок їхньої поношеної тканини, щоб я її дослідив?",
        objectives = "Збери 20 Зношеної Гнольської Тканини з гнолів Драконових Островів для Дотеноса з Валдраккенської угоди.",
        progress = "Ти приніс поношену гнолами тканину?",
        completion = "Дякую за ці зразки. На перший погляд це просто дикотканина, вкрадена в тускарів, але я попрошу наших кравців ретельно оглянути шви, щоб упевнитися.",
    },
    [66953] = {
        title = "Усе пухнасте",
        description = "Кравці завжди прагнуть роздобути ту пухнасту вовну аргалі. Ця вовна особливо стає в пригоді, щоб вижити в крижаних горах Драконових островів.",
        objectives = "Збери 20 Пухнастого Хутра з аргалі Драконових Островів для Дотеноса з Валдраккена.",
        progress = "Тобі вдалося роздобути трохи тієї пухнастої вовни?",
        completion = "Така пухнаста! Так, це підійде.",
    },
    [66956] = {
        title = "Драконобій Іґордан",
    },
    [66957] = {
        title = "Тінь у кризі",
        description = "Поки я проходив через табір Антонідаса, до мене долинали тривожні чутки. Кажуть, що скрізь по крижаних степах знаходять понівечених звірів. Від декого лишилися самі криваві патьоки.\n\nХоч би що це було, воно нагнало страху на магів, і живності в околиці майже не лишилося.\n\nРозвідай вершину льодовика. Якби я був дворфом-картярем, то поставив би на те, що саме там і влаштував собі лігво якийсь хижак-владар.\n\nПринеси мені шматок його туші, щоб ми могли заспокоїти Кірін Тор.",
        objectives = "Розвідай вершину льодовика, що нависає над табором Антонідаса.",
        progress = "Будь обережний. Хоч би що це було, воно сильне. І невблаганне.",
        completion = "Крижаний велетень? Присягаюся бронзовою бородою Маґні... Та ще й ти цілий-цілісінький! Вражає.\n\nЯ покажу це Кірін-Тор. Тепер, може, вони дадуть нам спокій!",
    },
    [66958] = {
        title = "Захищай і оберігай",
        description = "Днями я балакав з мисливцями з Іскаари, і вони розповіли про моторошну картину.\n\nСхоже, що особливо кровожерний носоріг на ім'я Кривавий Ріг шматує менших бруффалонів у цих краях.\n\nБруффалонам і так вистачає суперництва в Лазуровій широчіні, щоб іще й переживати за свої стада, які проріджує чужинський брутальний зайда!\n\nПринеси мені його ріг. Я хотів би справити добре враження на наших друзів-тускарів!",
        objectives = "Уполюй Кривавого Рога на схід від Іскаари.",
        progress = "Пам'ятай: стережися його копит! Саме ними носороги тебе й дістають.",
        completion = "Чудова робота, {NAME}! Це неабияк допоможе бруффалонам процвітати й, сподіваюся, покаже нашим сусідам-тускарам, що ми теж дбайливі господарі цієї землі.\n\nМи могли б повчитися в Кривавого Рога. Те, що ми топчемося цим прекрасним краєм, не дає нам права робити з ним усе, що заманеться!\n\nЗавжди залишай світ кращим, ніж застав його.",
    },
    [66959] = {
        title = "Огляньте торговельний пост",
        description = "<Гнаний вітром листок впурхує тобі до рук.>\n\nРідкісні старожитності з усіх куточків Азероту! Добірні товари на будь-який смак!\n\nЦих унікальних скарбів ти не знайдеш більше ніде, $p(друже:подруго).\n\nЗавітай до нас в одну з наших факторій у Оґриммарі чи Дорноґалі та помилуйся таємницями, що чекають на тебе!\n\n— Торговий пост Зен'шірі\n\n<Ти примружуєшся, щоб прочитати дрібний шрифт.>\n\nОбов'язково покажи цей листок, щоб отримати додаткові торговельні гроші!",
        objectives = "Отримай торговельні гроші зі Схрону Колекціонера та оглянь Торговий пост.",
        progress = "Ласкаво просимо до Торгового посту.\n\nУ нас тут товари з усіх куточків Азероту, щоб ти їх зібрав. Прошу, поглянь.",
        completion = "А, ти приніс один із наших листків! Як і обіцяли, ось трохи торговельних грошей, які можна витратити в нашій крамниці.\n\nЯкщо хочеш і далі заробляти гроші, зазирни до розділу «Журнал мандрівника» в Путівнику пригод, щоб дізнатися, які заняття тобі до снаги. Виконай достатньо занять — і ми винагородимо тебе грошима та іншими дивовижними речами.",
    },
    [66960] = {
        title = "Клозікк Піднесений",
    },
    [66961] = {
        title = "Долучайся до полювання",
    },
    [66963] = {
        title = "Доставка затримується",
        description = "Я ж казав Вевесі, що сам витягну воза з багнюки.\n\nАле ж ні, він неодмінно мусив скористатися магією, щоб його витягти... І ось поглянь, що він накоїв.\n\n<Перевізниця Беннет зітхає.>\n\nПоки я намагаюся напоумити Вевесі, чи не збігаєш ти на пагорб до Базового табору й не скажеш каталогізаторові Вульферду, що йому, можливо, доведеться замовити ще одну скриню приладдя для камер із Боралуса?",
        objectives = "Скажи каталогізаторові Вульферду в Базовому таборі неподалік, що його припаси прибудуть іще нескоро.",
        completion = "<Каталогізатор Вульферд сміється.>\n\nЖодних проблем. Я взяв удосталь запасної плівки в ручну поклажу.",
    },
    [66964] = {
        title = "Артефакти не в тих руках",
        description = "У нас тут безліч, ні, незліченна кількість проблем!\n\nОй, та з чого ж почати!\n\nКірін Тор викрили змову Розколотого Полум'я. Вони полюють за артефактом на ім'я «Валтрукс».\n\nВін неймовірно могутній і... мислячий? Це, як ти розумієш, збільшує небезпеку в рази.\n\nЯкась Алія Сонцесяйна вирушила на південь із двома тускарами, щоб розслідувати дії Розколотого Полум'я. Вона мала б уже повернутися.\n\nБудь ласка, знайди її та не дай Розколотому Полум'ю заволодіти артефактом!",
        objectives = "Знайди Алію Сонцесяйну в Загублених Руїнах у Лазуровому Просторі.",
        completion = "Нарешті хоч трохи щастя! Нам би тут дуже знадобилася поміч.",
    },
    [66968] = {
        title = "Проріджування зграї",
        description = "<Несінгварі вказує вбік стежки.>\n\nБачиш ці відбитки на снігу?\n\nСліди єті.\n\nЩось мусило їх розворушити, якщо вони полюють так близько до дороги. Спробуй вистежити їхнього ватажка зграї. Ми не хочемо, щоб вони почали нападати на подорожніх!\n\nЯкщо він виявиться особливо лютою тварюкою, забери його голову. Це має відлякати решту.",
        objectives = "Уполюй Єтора біля Щита Роніна.",
        progress = "Обережно, друже. Єті полюють зграями.",
        completion = "Ого! Оце так люта морда... Я радий, що ти повернувся живий!\n\nЯк би не було прикро робити з нього приклад, тримати єті подалі від доріг — це найкраще для них.\n\nІ для нас.",
    },
    [66969] = {
        title = "Клани рівнин",
        description = "Поки ти чекаєш на прибуття посланниці, хан Сансок хотіла б почути, як минула зустріч із кланами. Вона послала мене знайти тебе й попросити прийти до неї в центр Маруукаю, щоб усе обговорити.",
        objectives = "Відзвітуй перед ханом Сансок у Маруукаї.",
        progress = "<Хан Сансок усміхається тобі, вітаючи з поверненням.>",
        completion = "<Поки Хан Сансок жестикулює, Окір озвучує за неї.>\n\nХоч по рівнинах розкидано багато кланів різного розміру, найбільшу владу мають Шікаар, Тірай, Он'ір і Нокхуд.",
    },
    [66970] = {
        title = "Тай'фун Піднесений",
    },
    [66971] = {
        title = "Обличчя смерті",
        description = "Скажи мені, $p(друже:подруго). Чи бачи$p(в:ла) ти коли-небудь обличчя смерті?\n\n<Несінгварі робить драматичну паузу.>\n\nТа що це я кажу? Звісно ж, бачи$p(в:ла).\n\nЗрештою, у смерті багато облич.\n\nЯ чув від тускарів Імбу, що одне з них живе тут, на цих пагорбах. Навіть вимовити його ім'я — це накликати жорстоку, крижану смерть:\n\nМорозощелеп.\n\n<Несінгварі сторожко роззирається.>\n\nОтож, тепер тобі доведеться вполювати його — бодай заради мене!",
        objectives = "Уполюй Морозощелепа на північ від Лощини Зимохутра.",
        progress = "Не барися. Я тепер у смертельній небезпеці!",
        completion = "Ти живий!\n\nХа-ха! Уявити не можу, який бій дала та тварюка, коли ти загнав її в кут. Завдяки тобі Лазуровий Простір став трохи безпечнішим!\n\nЗроби ласку, навідайся до мого та...",
    },
    [66972] = {
        title = "Старий Камінь-Бивень",
        description = "У мене для тебе похмуре доручення, {name}. Не кожне вбивство — це міра вправності. Деякі — це міра милосердя.\n\nУ лісі на схід від табору Антонідаса блукає старий самець мамонта. Я бачив його здалеку якийсь час тому й вряди-годи чую його сумне сурмлення. Він явно тяжко страждає.\n\nВін почав наосліп ломитися крізь хащі, і я боюся, що він стає небезпечним для інших.\n\nМоє старе серце звеселилося б, якби ти впокої$p(в:ла) таку ж стомлену душу. Принеси мені його бивень, щоб ми могли вшанувати його.",
        objectives = "Впокій Старого Каменя-Бивня біля табору Антонідаса.",
        progress = "Уже по всьому?",
        completion = "Це не дає мені радості.\n\nАле я повішу його бивень на почесному місці.\n\nДякую, {NAME}.",
    },
    [66989] = {
        title = "Корисний урожай",
    },
    [66997] = {
        title = "Лад у яслах",
        description = "Я такий вдячний, що Ласзтак прийняв Поклик доглядача дракончиків! Особливо з огляду на те, скільки цих дорогоцінних малят саме зараз ріжуть зуби.\n\nКрім того, садам-яслам, мушу визнати, нелегко. Дракончики знервовані, а доглядачі — ну, знервовані ще більше, ніж зазвичай.\n\nБудь ласка, щойно матимеш вільну хвилинку, знайди мене в садах унизу. Нам теж не завадила б твоя допомога!",
        objectives = "Зустрінься з Ваеросом у садах Рубінових Озер Життя.",
        completion = "Хвала небесам, ти тут! Мабуть, ти помітив бджіл дорогою сюди. Треба з ними щось робити!",
    },
    [66998] = {
        title = "Клин клином... водою",
        description = "За всі роки, що я доглядаю лавових елементалів, я ніколи не бачив, щоб вони так поводилися! Ми ледве втримуємо їх у печері.\n\nЗнайдеш хвилинку? Ми втримаємо вихід, поки ти проріджуватимеш їхні лави всередині.\n\nОсь, візьми із собою цього елементаля води в пляшці.\n\nЯ завжди ношу кілька запасних елементалів води в пляшках, коли доглядаю лавових елементалів. Природні вороги — гарна відволікалка!",
        objectives = "Убивай лавових елементалів у Печері Виверження.",
        completion = "Дякую за хвилинку перепочинку. Робота доглядача не має кінця.",
    },
    [67002] = {
        title = "Слалом Лазурової широчіні",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [67003] = {
        title = "Слалом Лазурового Простору — просунутий",
        description = "Пролітай крізь контрольні кільця, що позначають трасу.",
    },
    [67004] = {
        title = "Гарні речі у великих скринях",
        description = "Завдяки нашим зусиллям ми зібрали все необхідне, щоб відкрити Сховище Земного Вартового. Під цитаделлю їх кілька. Знайди одне — і я тебе винагороджу.\n\nЯ викував ланцюги, щоб його пересунути. Якщо принесеш Сховище сюди, ми поділимо багатства.\n\nПильнуй, бо Сховище можуть уже кудись переміщати — я ж відрядив на пошуки й інших.",
        objectives = "Знайди для мене Сховище Вартового Землі. Якщо принесеш його назад, поділимо здобич.",
        progress = "Тобі вдалося знайти Сховище?",
        completion = "Чудова робота, {NAME}. Якщо пощастить, скоро ми зможемо відкрити ще Сховища!",
    },
    [67005] = {
        title = "Як приручити протодракона",
