    [69925] = {
        title = "Вгамувати бурі",
        description = "Ці первісники невблаганні — вони сіють стихійне спустошення по всіх Східних Королівствах і Калімдору.\n\nТи маєш виявити таку саму рішучість, {name}. Це єдиний спосіб їх спинити.\n\nЗнайди місце їхнього наступного вторгнення, знищ ворогів у зоні первісної бурі, доки не пізно, і зірви їхні плани.\n\nМи мусимо захистити Азерот!",
        objectives = "Збери 10 крихт первісної енергії з ворогів у місцях активних первісних бур по всьому Калімдору та Східних Королівствах.",
        progress = "Наша боротьба триває.",
        completion = "Гарна робота. Сподіваймося, це виграє нам час до їхнього наступного вторгнення.",
    },
    [69926] = {
        title = "Бекка Чорна і семеро гномів",
        description = "Джарадини сплюндрували Обсидіанову цитадель і викрали чимало цінних артефактів.\n\nВратіон доручив нам повернути кожну річ, забрану з цитаделі. Мій загін уже відшукав декілька в околиці, але нам не завадила б твоя допомога.",
        objectives = "Поверни зниклі артефакти.",
        progress = "Ти знайшов усе зі списку?",
        completion = "Чудова робота, {NAME}. Щойно ми відшукаємо ще вкрадені артефакти, неодмінно знову покличемо тебе на допомогу.",
