    [70048] = {
        title = "Первинна загроза",
        description = "Расзаґет не гаяла часу й нарощувала свої сили первісників.\n\nКірін-Тор виявили, що в ключових точках Калімдору та Східних Королівств вирують потужні бурі.\n\nПервісники вивільняють стихії, щоб примножити свою силу. Схоже, вони задумали посіяти хаос не лише на Драконових островах, а й на землях Альянсу та Орди.\n\nВідшукай ворога й вивчи його методи. Ми мусимо спинити їх, доки не пізно.",
        objectives = "Збери 10 крихт первісної енергії з ворогів у місцях активних первісних бур по всьому Калімдору та Східних Королівствах.",
        progress = "Боюся, це лише початок.",
        completion = "Добре, що ти зірва$p(в:ла) їхній напад, бодай наразі.\n\n<Кадґар розглядає частки, які ти йому $p(приніс:принесла).>\n\nГм, первісна стихійна енергія. Я вивчатиму це далі.",
    },
    [70049] = {
        title = "Вгамувати бурі",
        description = "Ці первісники невпинні — вони сіють стихійну руїну по всіх Східних Королівствах і Калімдору.\n\nТи маєш виявити таку саму рішучість, {name}. Це єдиний спосіб їх спинити.\n\nЗнайди місце їхнього наступного вторгнення, знищ ворогів усередині первісної бурі, доки не пізно, і зірви їхні плани.\n\nМи мусимо захистити Азерот!",
        objectives = "Збери 10 крихт первісної енергії з ворогів у місцях активних первісних бур по всьому Калімдору та Східних Королівствах.",
        progress = "Наша боротьба триває.",
        completion = "Гарна робота. Сподіваймося, це виграє нам час до їхнього наступного вторгнення.",
    },
    [70050] = {
        title = "Гонитва за бурями",
        description = "То ці красені посилають тебе у невеличку пригоду, еге ж?\n\nНічого. Однаково експедиція не зможе вийти в море, доки хтось не приборкає ці елементальні бурі.\n\nЗайди до Штормового мисливця Вільяма. Він керує дослідженням бур у межах експедиції й зможе спорядити тебе всім потрібним.\n\nЯ ж тут злагоджу решту приготувань, поки ти там розважаєшся.\n\nАле з тебе боржок!",
        objectives = "Поговори зі Штормовим мисливцем Вільямом у Гавані Стормвінда.",
        completion = "Якщо збираєшся в самісінькі бурі, тобі знадобиться будь-яка поміч.\n\nНа щастя, я роками запасаюся спорядженням для гонитви за бурями.\n\nПоглянь — може, щось підійде.",
    },
    [70051] = {
        title = "Маршрут понад урвищем",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [70052] = {
        title = "Маршрут понад урвищем — складний",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
