    [70055] = {
        title = "Печатка бур",
        description = "<Хтось із глибокими знаннями магії, певно, захотів би вивчити таку знахідку.>",
        objectives = "Доправ Сигіл Бур Штормовому мисливцю Вільяму в Стормвінді.",
        completion = "Це не мого рівня, як на магію.\n\nАле я передам це Кадґарові. Далі відкидай загрозу первісників.",
    },
    [70057] = {
        title = "Злодійкуваті тарасеки",
