    [70154] = {
        title = "Брама кудись",
        description = "Чари захистять нас від нестабільної енергії, що міститься всередині.\n\nЯ відкрию шлях до найближчого каменя.\n\nЯк пройдеш крізь нього, тримайся поруч. Коли прибудемо, мені знадобиться твоя допомога, щоб заживити пристрій.",
        objectives = "Іди за Викривлювачкою Деландрою до місця розташування Брами.",
        completion = "Не зовсім те, чого я очікувала, та ми дісталися цілі й неушкоджені.\n\nМушу зізнатися: після всього, що сталося, мене ще дужче, ніж будь-коли, цікавить, наскільки потужним є вміст цієї посудини.",
    },
    [70155] = {
        title = "Дивись, слухай і дихай",
        description = "Вітаю, {race}. Мало хто спиняється привітатися, не кажучи вже про те, щоб затриматися. Більшість поспішає до наступної мети.\n\nХочеш порибалити зі мною?",
        objectives = "Порибаль із Трешраком.",
        progress = "Якби я міг сказати одну річ собі молодшому, я б сказав: спробуй рибалити.",
        completion = "Повертайся коли завгодно, юна душе.",
    },
    [70156] = {
        title = "Прадавнє пробудження",
        description = "Брама стоїть просто за мною. Годі вгадати, скільки в нас часу, перш ніж чари на цій посудині, які й так уже слабнуть, розвіються остаточно чи — ще гірше — зламаються.\n\nВивільнення такої кількості нестабільної енергії може мати катастрофічні наслідки.\n\nПродовжимо?",
        objectives = "Заживи Браму.",
        completion = "Тепер, коли ми — а під «ми» я маю на увазі тебе — з'ясували, для чого ці штуки, годі й вгадати, скільки їх іще там!\n\nПильнуй, {NAME}. Хтозна, що ми можемо знайти на цих островах.",
    },
    [70157] = {
