    [70701] = {
        title = "Бакарам сняться загублені арґалі",
        description = "Кілька клановних арґалі знову відбилися від нашої отари.\n\nХребет довкола нас надто небезпечний, щоб наші пастухи шукали їх. Це було б великим благом, якби ти взя$p(в:ла) одного з наших бакарів і повернув арґалі. Наші пастухи вкажуть тобі правильний напрямок.",
        objectives = "Пожени загублених арґалі назад до клану Айлааг.",
        completion = "Ми мусимо пильнувати нашу худобу. Наші ресурси й без того обмежені. Втрата арґалі — це прикрість, якої ми воліли б уникнути.",
    },
    [70702] = {
        title = "Подальше дослідження порталів",
        description = "<Гучний, пронизливий крик маленького гінця привертає твою увагу. Він тицяє тобі записку й тікає геть.\n\nУ записці прохання від Таліна Темнокова, який потребує твоєї допомоги.>",
        objectives = "Зустрінься з Таліном Темноковом на заставі Рубінової Луски на Берегах Пробудження.",
        completion = "Бачу, ти знайш$p(ов:ла) мого листа. Радий знову тебе бачити!",
    },
    [70703] = {
        title = "Спадок Тіргольда",
        description = "Хранитель Тір таки любив свої загадки. Вочевидь, у дарунку, який він нам залишив, прихований глибший сенс. Оскільки цю луску він, найімовірніше, викував у своїй колишній цитаделі, можливо, вона стане ключем до розкриття її таємниць.\n\nВирушай із Кораносом до Тіргольда, {name}. Як довірений радник і споглядач цієї землі, він напевно зможе пролити світло на цю справу.",
        objectives = "Досліди Срібну Луску разом із Кораносом у Тіргольді.",
        progress = "Вдалося щось виявити?",
        completion = "Ця магія... Ти пробуди$p(в:ла) щось у Тіргольді.",
    },
    [70706] = {
        title = "Портал: Тінистий Притулок",
        description = "Наша експедиція доповідає про сплячий камінь там, на пишних схилах на південному заході. Дорога неблизька, та варто послати когось із твоїми знаннями, щоб усе розвідати.",
        objectives = "Знайди сплячу Браму в Тінистому Притулку на Рівнинах Он'агри.",
    },
    [70707] = {
        title = "Наступний портал",
        description = "Я тримав оцю-от посудину від твого друга-нічнороджеого в безпеці.\n\nЩо скажеш, як ми пустимо її до діла й вирушимо по ще один з тих давніх каменів?",
        objectives = "Обери, до якої Брами вирушити далі.",
    },
    [70708] = {
        title = "Порожнеча",
        description = "Здається, минули роки. А ще здається, що лише хвилини.\n\nМені б не завадило з кимось поговорити, якщо маєш час.\n\nПринесеш нам по чарці? Бери що хочеш. Я пригощаю.",
        objectives = "Випий чарку з Колгаром.",
        progress = "Знаю, за мною більше, ніж одна чарка, та сподіваюся, поки що цього стане.",
        completion = "Що ж, мабуть, час іти.",
    },
    [70710] = {
        title = "Маршрут річкових порогів",
        description = "Пролети крізь кільця контрольних точок, що позначають траси.",
    },
    [70711] = {
        title = "Маршрут річкових порогів - просунутий",
        description = "Пролети крізь кільця контрольних точок, що позначають траси.",
    },
    [70712] = {
        title = "Перегони драконовершників — маршрут річкових порогів",
    },
    [70713] = {
        title = "Рибальство у нагір'ї",
    },
    [70719] = {
        title = "Тінеруб Траккен",
    },
    [70720] = {
        title = "Це не для тебе",
    },
    [70721] = {
        title = "За покликом серця",
        description = "Біля Дзеркала Небес є невелике озерце, де ми з Нарманом уперше зустрілися під час мого послушницького навчання.\n\nПослушники приходять туди, щоб бути ближче до Он'агри й відчути вітер. Я вперше побачила його у відображенні води, коли раптовий подув вітру розплющив мені очі. Це найпрекрасніше місце на всіх рівнинах.\n\nВоно стане ідеальним місцем для нашого освідчення.",
        objectives = "Допоможи Вітромудриці Даві та мисливцю Нарману з їхніми освідченнями.",
        completion = "Дякую, {NAME}.\n\nМи з Давою завжди пам'ятатимемо, що ти для нас зроби$p(в:ла).",
    },
    [70722] = {
        title = "Що потрібно Лаббінсу",
        description = "Гадаю, я знаю, що нам треба робити, {name}.\n\nАле спершу обговорімо це!\n\nУ мене навіть є для тебе подарунок, коли ми закінчимо! Весело, правда ж?",
        objectives = "Поговори з Патчу в Іскаарі.",
        progress = "Поговорімо!",
        completion = "Обов'язково прикліч Лаббінса, а тоді застосуй на ньому цей бойовий камінь. Він назавжди зробить його сильнішим.",
    },
    [70723] = {
        title = "Розбити земних первісників",
        description = "Рателші у Валдраккені буде вдячний отримати це для свого дослідження первісників.",
        objectives = "Принеси первісне ядро Рателші.",
        completion = "Це допоможе просунути наші дослідження первісників. Дякую.",
    },
    [70730] = {
        title = "Щедрість шикаарів",
        description = "О, {name}.\n\nЧи відчуваєш ти затишок під сонцем? Чи відчуваєш ти себе в безпеці під його яскравими обіймами? Чи означає кожен новий день надію на майбутнє й нагоду прожити життя так, як ти завжди мріяв?\n\nТоді ти знаєш любов так само, як я.\n\nНарман із клану Шикаар — моє сонце. Він — моє тепло. Він — моє світло. Він — моя надія.\n\nТакий чоловік, як він, заслуговує на освідчення, гідне його величі.\n\nМи маємо звернутися по пораду до Онів.",
        objectives = "Допоможи Вітромудриці Даві підготувати ідеальне освідчення.",
        progress = "Нарман заслуговує на жест, такий же величний, як він сам.",
        completion = "Роги Арбгоґа? Вони чудово підійдуть.\n\nАрбгоґ був колись наймогутнішим мускеном на рівнинах. Це гідний дарунок для наймогутнішого мисливця. Я не сумніваюся, що Нарман їх оцінить.\n\nМожливо, колись він навчить мене полювати. Полювання — і хтось із клану Он'ір. Ха! Лишень уяви.",
    },
    [70732] = {
        title = "Тренувальний поєдинок",
        description = "Гаразд! Тепер, коли ти застосува$p(в:ла) той камінь на Лаббінсі, влаштуймо тренувальний поєдинок, щоб випробувати його вміння!\n\nНа березі на північ звідси живе великий старий горнсвоґ на ім'я Ґвош. Ґвош обожнює битися! Ну, точніше, гратися. Він чудово ладнає й з іншими улюбленцями!\n\nЦе буде ідеальна гра... тобто бій... для Лаббінса.",
        objectives = "Здолай Ґвоша в бою улюбленців.",
        progress = "Ґвош дуже лагідний, але все ж завзятий боєць. Гадаю, вони з Лаббінсом гарно розважаться в поєдинку! \n\nПросто рушай на північ звідси — там його й знайдеш.",
        completion = "Ого! Все пройшло чудово! Молодець, Лаббінсе!\n\nЗа Ґвоша не хвилюйся, він великий старий добряк. З ним усе буде гаразд.",
    },
    [70738] = {
        title = "Урок ти-ґи",
        description = "Усе йшло так добре, але тепер? Елементалі завдають нам деяких, гм, невеликих клопотів.\n\nНаші гості насолоджувалися процедурами, аж раптом з'явилися всі ці елементалі! Ці бридкі почвари все зіпсували. Мабуть, навіть нову інструкторку з ти-ґи.\n\nО так, ти-ґа — це новий вид розтяжки, що водночас допомагає медитувати. Я певна, що і вчителька, і учні такі розслаблені, що навіть не помічають елементалів.\n\nАле краще перестрахуватися. Будь ласка, розшукай їх.",
        objectives = "Знайди інструкторку та 6 учнів ти-ґи.",
        completion = "Сподіваюся, ця пригода не зіпсує їхніх відгуків!",
    },
    [70739] = {
        title = "Родоводи, солодощі й Тераї",
        description = "Я полював із ханами, переганяв наших найшвидших бакарів і голіруч здолав дорослого бика-бруффалона. Як мисливцю, мені більше нічого доводити.\n\nПроте як партнеру мені ще багато чого треба навчитися.\n\nВітровидець Дава з клану Он'ір — моє серце й моя радість. Я прагну лише довести, що гідний його любові, та я нічого не знаю про традиції й ритуали. Мені потрібна мудрість старійшин у Маруукаї.",
        objectives = "Допоможи мисливцеві Нарману здобути традиційне благословення для освідчення.",
        progress = "А що, як я не гідний любові Дави?",
        completion = "Я радше попросив би всі зорі нічного неба захоплюватися мною у відповідь, аніж назвав себе цілком гідним любові Дави.\n\nІ все ж я знайду в собі мужність діяти далі. Коли настане час, чи допоможеш ти мені з величним освідченням?",
    },
    [70740] = {
        title = "Парове прибирання",
        description = "Сіджан, схоже, вважає, що вторгнення елементалів у наш чудовий спа — лише дрібна проблема, але цей сплеск полум'я й пари треба негайно взяти під контроль.\n\nМи запросили музичні гурти грати в нижній зоні, але елементалі знищили їхнє спорядження. Оскільки такого рівня елементальних руйнувань у цій місцині ще ніколи не було, я підозрюю вплив первісників.\n\nЯкщо хочеш допомогти, очисти елементалів у східній частині нижнього спа. Саме там заплановані перші виступи.",
        objectives = "Убий 12 елементалів у нижньому спа.",
        completion = "Добрий початок, але їх усе ще занадто багато, як на мене...",
    },
    [70741] = {
        title = "Кілька улюблених речей",
        description = "<Схоже, урок ти-ґи перервали, і речі учнів розкидані повсюди.\n\nЗбір цих предметів неодмінно допоможе спа \"Безтурботні Сни\".>",
        objectives = "Збери 6 загублених речей.",
        completion = "Дуже мило з твого боку зібрати ці речі. Ми одразу ж повернемо їх власникам!",
    },
    [70742] = {
        title = "Сімейна риса",
        description = "З повітря я розгледіла один з артефактів, які Едресс знайшла біля входу в руїни. Усередині їх напевно більше.\n\nВони чимось захищені, та мені треба підібратися ближче, перш ніж я зможу їх дослідити. Магія тут дуже давня.\n\nЗемлі здаються покинутими, але я не певна, що так лишатиметься надовго, щойно ми почнемо тут порядкувати. Будь насторожі. Ми розкриємо все, що зможемо.",
        objectives = "Обшукай Обсидіанову Обсерваторію в пошуках слідів минулого драктирів.",
        completion = "Це дало мені... багато поживи для роздумів. Я воліла б трохи побути на самоті, якщо ти не проти.",
    },
    [70743] = {
        title = "Дорогенька Крихітка",
        description = "Гей, ти, {race}! Маєш хоч якісь здібності?\n\nУмієш правильно розставляти пріоритети?\n\nЧудово!\n\nМоя дорогенька Крихітка зникла. Негайно врятуй її. Поквапся, вона не дасть собі ради в цих жахливих умовах.",
        objectives = "Знайди Крихітку Елзари.",
        completion = "<Ельзара не зважає на тебе й дивиться на Крихітку.>\n\nТи ціла, моя дорогоцінна пухнасточко?\n\nЦі первісники не заляпали тебе кров'ю? Як вони посміли!\n\n<Ельзара помічає тебе.>\n\nЯ неодмінно поставлю цьому спа одну зірку. Я розраховувала на відпочинок без крові.",
