    [70977] = {
        title = "Торби Скапса",
        completion = "ТИ ПРИНЕСТИ СКАПСУ ЇСТОЧКИ? ПРИНЕСТИ РИИБУ?\n\nНІ?\n\n<СКАПС спостерігає, як ти показуєш на його заплічну торбу.>\n\nХОЧЕШ СПИНО-ТОРБУ? \n\n<СКАПС розмірковує.> \n\nТИ ВЗЯТИ СПИНО-ТОРБУ, ГАРАЗД?\n\nАЛЕ НАСТУПНОГО РАЗУ — НЕСТИ РИИБУ! ТОДІ ДАТИ ТОРБУ! \n\nСКАПС ГОЛОДНИЙ!",
    },
    [70978] = {
        title = "Оповіді чемпіонів Драконових островів",
