    [71230] = {
        title = "Рибальське спорядження тускарів",
        description = "Привіт іще раз, {name}.\n\n<Роуї озирається й наспівує мелодійку.>\n\nА, точно! Тавіо робила мені нову сітку й сказала, що може зробити одну й тобі. Вона може зробити й інше рибальське спорядження, якщо принесеш їй усі матеріали.\n\nТобі варто з нею поговорити.",
        objectives = "Поговори з Тавіо в Іскаарі, що в Лазуровому Просторі.",
        completion = "Мою родину знають як найкращих плетільників сітей і майстрів гарпунів. Якщо принесеш потрібні матеріали, я змайструю тобі нове знаряддя.",
    },
    [71231] = {
        title = "Поклик полювання",
        description = "<Рокі кладе тобі в руку записку.>\n\n{name}, клан Шикаар запрошує тебе на Велике Полювання. Зустрінься з тренером Фродрумом на рівнинах Он'агрі.",
        objectives = "Поговори з тренером Фродрумом на Рівнинах Он'агри.",
        completion = "Вершнику драконів! Твоя допомога стане в пригоді в прийдешніх полюваннях.",
    },
    [71232] = {
        title = "Слава Драконових островів",
        description = "Іще багато чого треба зробити, щоб допомогти Драконовим островам.\n\nПрошу тебе поговорити з Кошару. Він має багато відомостей про те, кому потрібна допомога в цих краях.",
        objectives = "Поговори з Кошару у Валдраккені.",
        completion = "Радий тебе бачити, {NAME}. \n\nНа Драконових Островах багато джерел сили — треба лише знати, де шукати!",
    },
    [71233] = {
        title = "Спадна вода",
        description = "Я люблю водоспади.\n\nХочеш знати, що краще за водоспад?\n\nДва водоспади.\n\nА єдине, що краще за це... ну, завітай до Трьох Водоспадів на захід звідси й сам побачиш!\n\nКорчмарка там дуже мила.",
        objectives = "Поговори з Віллою на Заставі Трьох Водоспадів у Лазуровому Просторі.",
        completion = "Ласкаво просимо до Оглядового пункту Трьох Водоспадів! \n\nМи тут доволі високо, і звідусіль мчить вода — тож пильнуй, куди ступаєш!",
    },
    [71234] = {
        title = "Новини затоки",
        description = "Гей, ти, {race:v}.\n\nНа вигляд ти бувала людина.\n\nМій двоюрідний брат Ваюн привозив улов із Китобійної затоки й згадав, що там отаборилися якісь... дивні особи.\n\nСхоже, вони поводяться чемно, але чи не міг би ти перевірити, як там Ваюн?\n\nВін буває трохи дратівливий.",
        objectives = "Навідайся до Китобійної затоки в Лазуровому Просторі.",
        completion = "Ще хтось?\n\nОт радість-то.",
    },
    [71235] = {
        title = "Польові маги",
        description = "Лок'тар, {race:v}.\n\nЯкщо маєш час, тут неподалік двоє наших магів працюють у полі, і їм точно не завадить допомога.\n\nЦей край небезпечний навіть у найкращі часи.\n\nА зараз — далеко не найкращі часи.",
        objectives = "Провідай магів Кірін-Тору біля Заводі Слайвернів у Лазуровому Просторі.",
        completion = "Нам не потрібна твоя допомога.\n\nАле ми її приймемо.",
    },
    [71238] = {
        title = "Рубінова учта!",
        description = "Увага всім завзятим кулінарам!\n\nЧи прагне твоє серце найвишуканіших смаків цього світу? Чи шукаєш ти нагоди для великих мандрів? Чи готовий ризикнути життям заради цілковитих незнайомців?\n\nЯкщо це про тебе, поговори з винятково шанованим, всесвітньо відомим дуетом кухарів — Руміастразою та Морселем! Зараз вони влаштовують Рубінову учту в місті Валдраккен!",
        objectives = "Поговори з кухарями Руміастразою та Морселем на Рубіновій учті.",
        completion = "Це через оголошення? Вони що, справді спрацювали?!",
    },
    [71239] = {
        title = "Загублена в небесах",
        description = "Мені потрібна послуга, а ти, схоже, з тих, хто залюбки допомагає.\n\nМоя давня подруга, Гарлін Цвіркосміх, мала зустріти мене в місті кілька днів тому. Ми збиралися смакувати все підряд на Рубіновій учті, підстригтися в перукарні, а тоді навідати той шикарний аукціонний дім, що тут у них є.\n\nАле вона так і не з'явилася. Вона часто з головою поринає в роботу, та мені було б куди спокійніше, якби я знала, де вона.\n\nПошукай у горах на південь звідси. Вона казала, що дорогою сюди заскочить туди.",
        objectives = "Знайди Гарлін Цвіркосміх на Синьоперих скелях.",
        completion = "Стара Фіззлкренк хвилюється, еге ж? Що ж, тоді напої з мене, коли закінчу тут справи.",
    },
    [71241] = {
        title = "Качка, качка, пастка",
        description = "Гай під назвою Первісна Долина повниться магією прадавніх драконів. Один вид слайвернів, що там живе, цінується моїм народом за хутро, та вони полохливі й важко вловимі.\n\nЗамість того щоб вистежувати їх, ти можеш знайти в окрузі наші мисливські пастки. Скористайся м'ясом місцевої водоплавної птиці, щоб знову їх насторожити, — а я надішлю когось із нашого клану забрати здобич.",
        objectives = "Наладнай мисливські пастки клану Айлааг у Первісній Долині.",
        progress = "Птиця в цій окрузі — улюблена пожива слайвернів.",
        completion = "Дякую. Сподіваюся, наш клан зможе пустити здобуте хутро на торгівлю.",
    },
    [71242] = {
        title = "Підмога дослідникам бурі",
        description = "Схоже, це великий згусток надлишкової сили від істот зі Стихійної Бурі.\n\nУ Валдраккені напевно знайдеться дослідник, якому це знадобиться.",
        objectives = "Віднеси Скупчення Стихійного Надлишку досліднику у Валдраккені.",
        completion = "О, чудово! Це саме те, що ми шукали, дякую.",
    },
