    [72038] = {
        title = "Припаси Драконових Островів",
        completion = "Твої звершення конче потрібні для успіху нашої експедиції на Драконових Островах. Тому мені дозволили видати тобі цей наділ припасів на підтримку. Так тримати, шукачу пригод!",
    },
    [72048] = {
        title = "Припаси Драконових Островів",
        completion = "З поверненням, шукачу пригод. Радію, що мені дозволили збільшити твій наділ припасів, — ти на нього безперечно заслуговуєш. Знаю, що повторюю це щоразу, але я справді сподіваюся, що ти й далі підтримуватимеш наші зусилля.",
    },
    [72050] = {
        title = "Балґар",
    },
    [72052] = {
        title = "Коло Рубінової Святині Життя — у зворотний бік",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [72058] = {
        title = "Ось де собака зарита... тобто копито: Таролекк",
    },
    [72060] = {
        title = "Особливе піклування",
        description = "<Багниста маска з цікавістю вдивляється у твої наміри, та на цій гілці їй нема куди тікати!>",
        objectives = "Поверни сонцезахисні окуляри Зелдісу. Знову.",
        progress = "Знаю, мої сонячні окуляри розкішні, але ж годі вже. Це вже вдруге слиз тікає з ними!\n\nЯк узагалі можна мати розкішний вигляд у таких умовах?\n\nСтривай, невже вони знову знайшлися?!",
        completion = "Ого. Ти глянь, скільки на них шмарклів.\n\n<Зелдіс замовкає на мить.>\n\nЗнаєш, вони, здається, все одно виходили з моди.\n\nТримай цю жижу подалі від мене. \n\nАбо залиш собі як улюбленця — як тобі до вподоби.",
    },
    [72061] = {
        title = "Покликниця Бурі Велдра",
    },
    [72062] = {
        title = "Валдкачка",
        description = "Кря! Кря!\n\n<Качка-мати помітила тебе.>\n\nКря кря кря кря! Кря кря кря! Кря кря кря кря кря.\n\n<Бурчання в качиному животі уриває її завзяте кряканнячко. Поки вона порається з гніздом, їй бракує їжі для своїх каченят. Можливо, якщо зарадити цьому клопоту, вона стане прихильнішою до тебе?>",
    },
    [72063] = {
        title = "Поверни Йенну іграшковий човник",
        description = "<Цей саморобний іграшковий човник схожий на кораблі тускарів. Йенну, мале тускареня, нарікало на якийсь човник — мабуть, він належить йому.>",
        objectives = "Поверни іграшковий човник Йенну біля річки на Рівнинах Он'агри.",
        completion = "Мій човник! Дуже-дуже дякую.",
    },
    [72067] = {
        title = "Час відпочинку!",
        description = "Гей, ти!\n\nМаєш геть виснажений вигляд. Зморений. Тобі вкрай потрібен відпочинок. І в мене є саме те, що треба! Спа «Безтурботні Сни» — це місце для тебе!\n\nНасолоджуйся нашими новими заняттями з йо-ги, вони ПРОСТО ЧУДОВІ! Чи, може, тобі більше до душі догляд за обличчям із багнистою маскою? Раджу і те, і те!\n\nЩоб дістатися спа, рушай на північ одразу за місто!",
        objectives = "Вирушити до спа «Безтурботні Сни».",
    },
    [72068] = {
        title = "Підмога Узгоді: Учта для всіх",
        description = "Нашим союзникам потрібна твоя допомога, {name}!\n\nТвої зусилля на островах не лишилися непоміченими. Наші вірні союзники на півдні, іскаарські тускари, хочуть відсвяткувати твої звершення учтою над учтами!\n\nВирушай у землі Іскаари, не полишаючи праці пліч-о-пліч із союзниками Узгоди. А коли дістанешся мерехтливих вод південних земель, не вагайся приєднатися до святкувань!",
        progress = "Так швидко? І куди тільки дівається час?",
        completion = "Вигляд у тебе, {NAME}, бувалий... і ситий. Твої пригодницькі звершення несуть лад нашим землям і розраду нашим союзникам.",
    },
    [72069] = {
        title = "Підльодне поповнення",
        description = "Риба могла б клювати й краще, тобі не здається?\n\nЗнаєш, це наштовхнуло мене на думку. Схоже, ми вже виловили майже всю рибу під кригою. Чи не міг би ти наловити ще трохи нижче за течією, на Стежці Деревозубів, принести сюди й випустити в ополонку?",
        objectives = "Назбирай риби, щоб поповнити рибне місце, і вкинь її в ополонку.",
        progress = "Ну що, риба вже в ополонці?",
        completion = "Гарна робота! Я вже бачу, як під льодом виблискує більше риби.",
    },
    [72071] = {
        title = "Другий раунд, рибо!",
        description = "То як щодо невеличкої риболовлі, {name}?\n\nТрохи від берега є зграйка наживкової рибки, на яку ця дурна почвара нападає щоразу, коли та збирається купно, — забуваючи, що вона й сама вже мертва.\n\nПливи туди й помахай тією приманкою, удай із себе пораненого тюленя — і вона не зможе встояти.",
        objectives = "Убий Мочобі.",
        progress = "Вона там, у воді. Я це відчуваю.",
        completion = "Ну, і хто тепер веде в рахунку?",
    },
    [72072] = {
        title = "Драконоджерельний скид",
        description = "Риба могла б клювати й краще, не думаєш?\n\nЗнаєш, це наштовхує мене на думку. Легенда каже, що в цих озерах і річках не завжди була риба. Подейкують, ці водойми зариблялися тоді, коли дракони, що пролітали вгорі, кидали в них рибу! Можеш у таке повірити?\n\nМоже, ви з твоїм драконом спробуєте?",
        objectives = "Збери рибу, щоб поповнити рибну водойму, і сядь на дрейка, щоб скинути її згори.",
        completion = "Ха! Легенди правдиві, як чудово!",
    },
    [72074] = {
        title = "Високогірне середовище",
        description = "Риба могла б клювати й краще, не думаєш?\n\nЗнаєш, це наштовхує мене на думку. Легенда каже, що в цих озерах і річках не завжди була риба. Подейкують, ці водойми зариблялися тоді, коли дракони, що пролітали вгорі, кидали в них рибу! Можеш у таке повірити?\n\nМоже, ви з твоїм драконом спробуєте?",
        objectives = "Збери рибу, щоб поповнити рибне місце, і сядь на свого дракона, щоб скинути її згори.",
        progress = "Ну що, рибу вже скинуто?",
        completion = "Ха! Легенди правдиві — от дивовижа!",
    },
    [72075] = {
        title = "Гарячий запас",
        description = "Риба могла б клювати й краще, не думаєш?\n\nЗнаєш, це наштовхує мене на думку. Легенда каже, що в цих лавових озерах не завжди вдосталь риби, яка любить жар. Подейкують, ці водойми зариблялися тоді, коли дракони, що пролітали вгорі, кидали в них рибу! Можеш у таке повірити?\n\nМоже, ви з твоїм драконом спробуєте?",
        objectives = "Назбирай риби, щоб зарибнити місце вилову, і осідлай свого дракона, щоб скинути її згори.",
        completion = "Ха! Легенди правдиві — оце дивовижа!",
    },
    [72079] = {
        title = "Громадський бенкет",
    },
    [72083] = {
        title = "Моя щаслива приманка",
        description = "Ти застаєш мене в скруті, {race}, і не тому, що я мертвий.\n\nЯ загинув на полюванні, дбаючи про те, щоб звір, який убив мою команду, більше ніколи не вбивав. У цьому немає нічого поганого, цього хотів би й мій батько.\n\nНі, біда в тому, що бій завершився внічию!\n\nДух звіра досі десь там, так само певно, як я стою тут перед тобою. Але, бувши привидом, я навіть не можу забрати свою щасливу приманку в тих падложерів, що обгризли моє тіло до кісток, аби спробувати ще раз!\n\nДопоможеш мені, гаразд?",
        objectives = "Поверни щасливу приманку капітана Гааба.",
        progress = "Ні, я не знаю, котрий саме її проковтнув. Мені тоді було ніколи — я саме був мертвий.",
        completion = "Жодна риба не встоїть перед моєю щасливою приманкою — ні жива, ні мертва!",
    },
    [72089] = {
        title = "До Небосяжної Обсерваторії",
    },
    [72090] = {
        title = "Зірвати задум первісників",
    },
    [72113] = {
        title = "Постаті за Завісою",
        completion = "Вітаю, любий друже.\n\nТвоя поміч за час, проведений тут, безцінна, але я відчуваю: доля кличе тебе деінде.\n\nНа честь численних душ, врятованих тобою в цій подорожі, і як провідне світло для тих, кого ти ще зустрінеш, прошу, прийми цей дарунок. Хай він нагадує, скільки дивовиж може принести життя, коли йому трохи допомогти.",
    },
    [72114] = {
        title = "Акросот",
    },
    [72116] = {
        title = "Ліскрон Сліпучий",
    },
    [72117] = {
        title = "Культурний обмін",
        completion = "Чужинцю, від тебе стає дедалі більше користі. Хай це гріє тебе холодними ночами. А коли грітиме — пам'ятай, що ми друзі.\n\n<Хусенг шкіриться.>\n\nБачу, ти робиш великі речі для нашого народу, {NAME}.",
    },
    [72121] = {
        title = "Великий Панцеркан",
    },
    [72122] = {
        title = "Колишні екологи",
        description = "Поранених стабілізовано, та дещо досі непокоїть мене, {name}.\n\nДвоє екологів із драконячої зграї прибули до застави, щоб дослідити болота. Від часу нападу я не бачив ані лусочки, ані кігтика від них, і це починає тривожити.\n\nЯкщо вирушаєш у дорогу, чи не міг би ти пильнувати й переконатися, що з ними все гаразд?\n\nІ будь обережний. Подейкують, ті болота кишать ґорлоками.",
