    [72396] = {
        title = "Достаток рогів",
        description = "Багато наших винаходів потребують міцного й пружного матеріалу. На щастя, роги ворквінів стали ідеальною основою для багатьох наших сучасних творінь.\n\nЩе більше нам пощастило, що Драконові острови аж кишать ворквінами. Тобі буде неважко зібрати для нас трохи пружних рогів ворквінів.",
        objectives = "Збери 20 Пружних Рогів із ворквінів Драконових Островів для Дотеноса зі Згоди Валдраккена.",
        progress = "Вдалося зібрати роги ворквінів?",
        completion = "Наші інженери будуть у захваті від нових матеріалів. Дякую за твій внесок.",
    },
    [72397] = {
        title = "Орієнтування: Базовий табір Драконячої Луски",
        description = "Ласкаво просимо до базового табору, {name}.\n\nНам із Тоді знадобився час, щоб обрати ідеальне місце для табору, та я не могла бути щасливішою від нашого вибору.\n\nЛегкий доступ до руїн, місць гніздування протодраконів і, звісно ж, до драконових зграй.\n\nЧому б тобі не приділити кілька хвилин, щоб оглянути табір і познайомитися з декотрими постачальниками, які живлять нашу експедицію?",
        objectives = "Познайомся з головними постачальниками в Базовому таборі Драконячої Луски.",
        progress = "Ласкаво просимо до табору, {NAME}!",
        completion = "То ви з моїм дідусем уже познайомилися, га?\n\nТільки не вір усім його байкам... Він страх як любить вихвалятися родиною!",
    },
    [72398] = {
        title = "Камінь і скеля",
        description = "Земляні елементалі на Драконових островах складаються з різноманітних порід і мінералів. Наші ковалі геть зачаровані тими унікальними інструментами, які можна викувати, переплавивши такі матеріали. Власне, вони саме переплавили останні свої зразки.\n\nНе хотілося б псувати їм утіху. Чи не міг би ти поповнити запаси?",
        objectives = "Збери 15 Земляних Зразків із земляних елементалів Драконових Островів для Дуррела з кентаврів маруків.",
        progress = "Чи вдалося назбирати достатньо Земляних Зразків з елементалів?",
        completion = "О, ковалі будуть задоволені цими зразками.",
    },
    [72399] = {
        title = "Сад відлюдника",
        description = "Батьки завжди кажуть нам не ходити до садів над Ґелікіром. Вони думають, що садівник злий і небезпечний.\n\nАле це неправда! Він трохи буркотливий, та насправді дуже добрий!\n\nНіхто з нас не бував там, відколи з'явилися первісники. Тепер там надто небезпечно. Та все ж я сподіваюся, що садівник у порядку. Чи не міг би ти піти й перевірити, як він там, бо ми вже не можемо його провідати?",
        objectives = "Поговори із Сзаретом на Тіньовому Виступі.",
        completion = "Краще б жодна з моїх рослин не постраждала під тими твоїми незграбними тупалами. Ну, чого тобі від мене треба?",
    },
    [72405] = {
        title = "Несподівана інформаторка",
        description = "Це цілком таємна місія, {name}.\n\nДо нас вдерлися.\n\nЗ Фортеці викрали могутній історичний артефакт... і схоже, що винне Братство Дефаїв. Одного злодія ми спіймали, але другий утік.\n\nАле мені це не до вподоби, {name}... Чуття підказує, що тут щось більше.\n\nЯ викликав... експертку з Братства. Зустрінемося в підвалі корчми «Лев'яча гордість» у Голдширі.",
        objectives = "Зустрінься з Матіасом Шоу в підвалі корчми «Лев'яча гордість».",
        progress = "Ми мусимо повернути викрадене з Фортеці за будь-яку ціну.",
        completion = "Ті нечисленні розмови, що я мав із Ванессою, показали: її не цікавить бандитство старого Братства Дефаїв. Для неї Братство означало підтримку знедолених... тих, кого Стормвінд лишив напризволяще. \n\nЦе я можу поважати. \n\nАле більшість її Братства й далі оббирає невинних подорожніх. Це не революція, це грабунок на битому шляху.\n\nВона запевняє, що намагається їх спинити.",
    },
    [72406] = {
        title = "Орієнтація: Валдраккен",
        description = "Ласкаво просимо до Валдраккена, {name}. Я Унатос, Хранитель Слави Валдраккенського Договору.\n\nНа знак визнання твоєї допомоги драконячим зграям кільком постачальникам по місту дозволено забезпечувати тебе нашими найкращими товарами.\n\nЧому б тобі не приділити трохи часу й не познайомитися з тим, де вони і що пропонують?",
        objectives = "Зустрітися з важливими постачальниками Договору у Валдраккені.",
        completion = "Від імені Згоди Валдраккена скажу: ми з нетерпінням чекаємо на співпрацю з тобою, {name}.",
    },
    [72407] = {
        title = "Просякнуті успіхом",
        description = "Рибалки нашого племені постійно потерпають від просяклих водою торб і чобіт. Останнім часом річкові звірі заполонили місця для риболовлі й коять ще більше шкоди.\n\nШкура річкових звірів доволі гладенька й водовідштовхувальна. Можливо, ми вирішимо дві проблеми одразу. Якщо ти допоможеш упоратися з надміром річкових звірів і принесеш їхні шкури, наші рибалки будуть дуже вдячні.",
        objectives = "Збери 18 Водонепроникних Шкір із річкових звірів Драконових Островів для Темнааю з Тускарів Іскаари.",
        progress = "Вдалося знайти шкури з водовідштовхувальними властивостями?",
        completion = "Не сумніваюся, що ці шкури добре вбережуть наше спорядження від подальшої шкоди від води. Дякую за допомогу.",
    },
    [72408] = {
        title = "Вікно в минуле",
        description = "У цьому я довіряю слову Ванесси. Не думаю, що вона знає, що таке Амулет Драконячого Вогню. Дещо з історії про Оніксію стало відомим, але не все.\n\nМожливо, навіть ти цього не знаєш.\n\nЯ поясню все вам обом.",
        objectives = "Поговори з Шоу під корчмою «Лев'яча гордість» у Голдширі, щоб почути історію Амулета Драконячого Вогню.",
        progress = "<Ванесса міряє тебе оцінювальним поглядом.>",
        completion = "У кожного з нас своя версія минулого, чи не так? \n\nМені байдуже, що якась драконяча пані мала чарівний амулет. То не було цілковите керування розумом. \n\nШляхта й без того ненавиділа простолюд. Гільдії Каменярів ніколи не довелося б вдатися до бандитства і стати Братством Дефаїв, якби не вони.",
    },
    [72409] = {
        title = "Гнилі давні спогади",
        description = "Що б тут не коїлося, мені це не подобається. Бракувало тільки, щоб сила цієї драконихи знову затуманила всім розум.\n\nХоч би хто це зробив, він мав чимало знати про Оніксію. Шоу згадував такого собі... Реджинальда Віндзора. Він єдиний підозрював леді Престор. Що ж, може, його друзі в Палаючих Степах мають більше його відомостей.\n\nУ неї мали бути спільники. Стане в пригоді все, що виведе нас на близьких до неї людей.\n\nРозвідай це, гаразд?",
        objectives = "Поговори з Обідраним Джоном у Чатуванні Морґана в Палаючих Степах.",
        progress = "Чарка все порожня... чого це в мене чарка все порожня?",
        completion = "Ех, Віндзор...",
    },
    [72410] = {
        title = "Клешні та голки",
        description = "Останнім часом нам бракує голок для кравецтва. Ці кляті штуки весь час ламаються навпіл!\n\nГострі частини сцитидів у цій місцевості могли б стати добрим замінником.",
        objectives = "Збери 10 Гострих Клешень зі сцитидів Драконових Островів для Ґнокліна Квіркойла з Експедиції Драконячої Луски.",
        progress = "Вдалося знайти гострі частини на заміну нашим голкам?",
        completion = "Чудово! Тепер кравці можуть повернутися до роботи.",
    },
    [72411] = {
        title = "Причина без бунтівника",
        description = "Рада знову тебе бачити, {name}! Алекстраза не вважає, що ми зможемо дієво спинити бунтівників силою, попри всі твої успіхи.\n\nЩоб знайти інші шляхи, Алекстраза покликала сюди Малдру Полум'яний Язик — поговорити про повстання й про те, що її до нього привело.\n\nМабуть, було б корисно долучитися до розмови й почути, що скаже Малдра. Щоб уникнути допитливих очей і вух бунтівників, вони зустрінуться нижче, на другому рівні Престолу Аспектів.",
        objectives = "Послухай розмову Алекстрази з Малдрою Полум'яний Язик.",
        completion = "Я з'ясував, що бунтівники накопичують величезну кількість бомб під акведуком Валдраккена! Ми мусимо їх спинити!",
    },
    [72412] = {
        title = "Вибухове втручання",
        description = "Мені вдалося проникнути до табору бунтівників унизу, в Печерах Лускатої Варти. Він здавався б таким, як і будь-який інший, якби не часті вози, що заїжджали до табору з накритим вантажем.\n\nЗрештою я зміг непомітно дістатися туди, де ті вози розвантажували. Бунтівники запасають бомби, але це ще не найгірше!\n\nВони складають бомби біля колони просто під акведуком із Тіргольду.\n\nЗустрінь мене там унизу, і ми знайдемо спосіб це спинити!",
        objectives = "Зустрінься з Ерімою в Печерах Лускатої Варти.",
        completion = "Схоже, ми вчасно, {NAME} — покладімо цьому край, поки акведук не зруйновано!",
    },
    [72413] = {
        title = "Непримиренні розбіжності",
        description = "Хотіла б я, щоб нам ніколи не довелося піднімати зброю проти своїх же драконородних, {name}. Ми маємо бути союзниками, а не ворогами. На жаль, їхній очільник, Підбурювач Зоралек, зробив цей вибір за нас, коли пригрозив акведуку.\n\nПробийся в печеру й спини Підбурювача Зоралека будь-якою ціною, перш ніж він зможе підірвати ті бомби. Тоді принеси його детонатор, щоб ми його убезпечили. Коли він буде в нас, Лускоприсяжні зможуть безпечно прибрати бомби.",
        objectives = "Убий Підбурювача Зоралека й забери детонатор.",
        progress = "Чи вдалося спинити Зоралека? Акведук у безпеці?",
        completion = "Зоралека спинено, його детонатор здобуто — тож акведук убезпечено, і для Валдраккена, і для ставків життя.",
    },
    [72414] = {
        title = "Полонених — брати!",
        description = "Якщо Алекстраза справді хоче з'ясувати причини цього повстання, нам треба вислухати бунтівників.\n\nА для цього доведеться безпечно затримати бунтівників, що прагнуть нас убити. Ну, тебе. Це набагато складніше, ніж удатися до насильства, та й небезпечніше.\n\nАле я й сама це пережила, коли покинула бунтівників. Оріан Дарквотер наклала закляття, що цілком мене скувало. Воно спрацювало, а я уважно все запам'ятала.\n\nЯ вклала те закляття в перстень. Ним ти зможеш безпечно їх зв'язати. У всякому разі, мало б спрацювати!",
        objectives = "Скористайся перснем зв'язування Малдри, щоб затримати 8 бунтівників.",
        completion = "Це складніший шлях, але кожен бунтівник, якого ми захопимо замість убити, — це шанс покласти край насильству. І врятоване життя.",
    },
    [72415] = {
        title = "Бунтівні писання",
        description = "Схоже, бунтівники мають чимало вивісок і листівок по всій печері. Певно, вони так тримають усіх відданими своїй меті й налаштованими на боротьбу.\n\nНелегко згуртувати велику юрбу навколо однієї справи — надто коли вдаєшся до мерзенних методів на кшталт бомбардування мирних мешканців чи знищення джерела води — без постійного підживлення запалу.\n\nЗберімо трохи їхньої пропаганди. Вона може чимало розповісти про те, що вони думають, або про те, хто вказує їм, що думати.",
        objectives = "Збери 5 зразків пропаганди бунтівників.",
        progress = "Вдалося зібрати добірку їхніх писань?",
        completion = "Схоже, більшість із цього написала Підбурювачка Белафон — я якось зустрічала її, коли була в повстанні. Якщо ми її знайдемо, можливо, зможемо спинити її, щоб не розпалювала стільки гніву! \n\nА ще я перегляну ці писання — раптом там є коди чи шифри з моїх бунтівних днів, якими вони досі користуються, — і, може, ми дізнаємося більше. Гарна робота, {NAME}!",
    },
    [72416] = {
        title = "Тимчасове житло",
        description = "Полонених бунтівників ми відправляємо до Валу Сталескелля. Це казарми, де базується міська варта Валдраккена — Лускоприсяжні.\n\nТож вартових там удосталь, аби ніхто з полонених не наробив лиха й не втік.\n\nВирушай туди, і ми поміркуємо, які кроки зробити далі, щоб остаточно покласти край цьому повстанню.",
        objectives = "Вирушай до Валу Сталескелля.",
        completion = "Дякую, що ти тут, {NAME}. Я хочу обговорити з цими полоненими, чому вони прагнули повстати проти драконів. Приєднуйся до мене — і послухаємо, що вони скажуть.",
    },
    [72417] = {
        title = "Затяті дисиденти",
        description = "Моя мета — завершити це повстання з якомога меншим насильством. Та для цього мені треба зрозуміти його глибинні причини.\n\nБунтівники явно затаїли образу на Аспектів і драконячі зграї. І хоча нам довелося застосувати силу, щоб захистити Валдраккен, повстання це не спинило.\n\nХочу, щоб ти поговори$p(в:ла) із полоненими й розпита$p(в:ла), чому вони повстали. Я піду з тобою, аби почути їхні причини.",
        objectives = "Розпитай 5 драконородних, чому вони повстали.",
        completion = "Я, може, і не погоджуюся з усіма їхніми причинами — і точно не з насильницькими методами, — але тепер краще розумію, чому вони прагнуть змін.",
    },
    [72418] = {
        title = "Погляд збоку",
        description = "Це було, м'яко кажучи, повчально. Бунтівники, з якими ми говорили, розповіли чимало такого, чого я не сподівалася почути.\n\nУ мене вже склалася власна думка про ситуацію, та що ти скажеш про їхні нарікання?\n\nТи не належиш ні до драконів, ні до драконородних, тож дивишся на цю справу з певною об'єктивністю.",
        objectives = "Обговори нарікання бунтівників з Алекстразою.",
        progress = "Чи є слушність у словах драконородних, чи це лише нехтування обов'язком?",
        completion = "Я зважу на твою пораду. Ще раз дякую за допомогу, {NAME}.",
    },
    [72419] = {
        title = "Прибрати набрід зі скель",
        description = "{name}! Малдра переглядала здобуту тобою пропаганду, користуючись шифрами, які знала ще з тих часів, коли сама була бунтівницею.\n\nВона знайшла зашифроване послання, що привело її до іншого табору бунтівників, де Белафон підбурює до бунту всіх, кого тільки може.\n\nМалдра і слідчий Еріма вже там — приєднуйся до них, і погляньмо, чи зможемо ми нарешті покласти край цьому повстанню!",
        objectives = "Зустрінься з Малдрою та Ерімою на Бунтівних Скелях.",
        completion = "Бунтівники стікаються сюди з Лускатої Варти та інших місць за тими самими шифрами, які знайшла Малдра, {NAME}. Тепер їх аж надто багато, щоб ми спинили Белафон без твоєї допомоги.",
    },
    [72420] = {
        title = "Важке примирення",
        description = "Капітанка Драйн повідомила, що Алекстраза хоче владнати це якомога мирніше. А ще до мене дійшла звістка, що Алекстраза розглядає можливість надати драконородним більше прав. Або навіть свободу.\n\nЗамість того щоб прорубувати собі шлях крізь усіх цих бунтівників, коли мир уже на обрії, краще розповсюдьмо звістку! Скажи тутешнім драконородним, що все змінюється. Можливо, дехто складе зброю або вирішить піти.\n\nАле приготуйся мати справу з тими, хто наполягатиме на бійці.",
        objectives = "Повідом 12 драконородних про заплановані зміни Алекстрази.",
        progress = "Пам'ятай: кожен переконаний тобою драконородний — це врятоване життя.",
        completion = "Як добре, що стільки їх припинило битися! Шкода тих, хто не припинив, але якби мені сказали, що цілий табір бунтівників здебільшого складе зброю, я б не повірила. Алекстраза буде задоволена, {NAME}!",
    },
    [72421] = {
        title = "Перо до влади",
        description = "{name}, нам треба спинити пера, що підбурюють бунтівників, бодай настільки, щоб нас почули.\n\nЇхня ватажка Белафон, схоже, надає перам певну самостійність за допомогою того осяйного жезла. Збери їх якомога більше, щоб вони не могли далі повторювати її слова.\n\nКоли ми виведемо їх із ладу, то станемо з нею віч-на-віч — але ми не хочемо, щоб пера розлетілися й продовжили поширювати ці послання.",
        objectives = "Збери 6 зачарованих пер.",
        progress = "Скільки пер вдалося знайти, {NAME}?",
        completion = "Якби ми не зібрали ті пера, вони й далі підбурювали б драконородних, а нам довелося б давати раду дедалі більшій кількості бунтівників. Дякую за те, що цьому покладено край.",
    },
    [72422] = {
        title = "Спинити друкарські верстати",
        description = "Ось і вирішальна мить, {name}. Белафон поширює ідеї, що рухають повстання, тож якщо ми спинимо її, повстанню настане кінець.\n\nСпробуй зв'язати її моїм перснем, хоча спершу її, найпевніше, доведеться послабити. Якщо вона погодиться здатися, ми приведемо її до Алекстрази.\n\nГадаю, Королева Драконів матиме для неї чимало добірних слів під час їхньої зустрічі.",
        objectives = "Підбурювачку Белафон переможено.",
        progress = "Які вісті про ватажку бунтівників, Белафон?",
        completion = "Дякую, {NAME} — твоя допомога у протистоянні цьому повстанню була з нами від самого початку. Тепер Валдраккен у безпеці, а що важливіше — я подбаю, щоб до драконородних ставилися з повагою, на яку вони заслуговують.",
    },
    [72423] = {
        title = "Вистояти проти бурі",
        description = "А, ти прибу$p(в:ла) якраз вчасно! Ми чули перекази, що в кентаврів Нокгуд є потужна, небезпечна зброя, насичена грозовими чарами. Ми хотіли б принести кілька зразків нашим чарувальникам на вивчення.\n\nЩонайменше ми зможемо знешкодити цю зброю й застосувати її з кращою метою.",
        objectives = "Збери 12 Озброєнь Бурі в кентаврів Нокгуд Драконових Островів для Темнааю з Тускарів Іскаари.",
        progress = "Вдалося знайти зброю для вивчення?",
        completion = "Тепер, коли ця зброя вже не в руйнівних руках, нам спокійніше — і ми можемо почати розбиратися в цих чарах.",
    },
    [72424] = {
        title = "У пошуках чогось конкретного",
        description = "<Обідраний Джон мляво кліпає, дивлячись на тебе.>\n\nТож ти завали$p(в:ла) того старого ворга, га? А ти ж найбільша й найдужча людина, яку я бачив від часів старого Віндзора.\n\n<Обідраний Джон зітхає.>\n\n...Ну? Чого ти ще тут стовбичиш? Неси свою знахідку тому, хто тебе сюди й послав!",
        objectives = "Повернися до Шоу в підвал корчми «Лев'яча гордість».",
        completion = "Обідраний Джон досі тримається, он як? Давненько я не посилав агентів його провідати. У глибині душі він добрий чоловік. \n\nНу ж бо, що це за нотатки? Гм-м... Клессінґтон?",
    },
    [72426] = {
        title = "Новий маєток Клессінґтонів",
        description = "Чудово, {name}. Нарешті щось, із чим можна працювати.\n\nГраф Клессінґтон — член Дому Шляхти й могутній маг. Відколи Андуїн узявся викорінювати корупцію в Стормвінді, настали для нього тяжкі часи.\n\nЯ б не здивувався, якби він був до цього причетний.\n\nНещодавно він придбав старий маєток у Сутінковому лісі. Я зв'яжуся зі своїми джерелами й погляну, яку ще інформацію вдасться роздобути. А ви з Ванессою вирушайте до маєтку й розслідуйте все на місці.",
        objectives = "Обстеж маєток на Воронячому Пагорбі в Сутінковому лісі.",
        progress = "Відчуваєш? \n\nМоторошне місце. Присягаюся, час від часу щось торкається мене мимохідь. Волосся на потилиці так і стає дибки!",
        completion = "Прийми мої найглибші вибачення, друже, за поведінку моїх «прислужників». \n\nХоча, гадаю, вони ніколи не були моїми. Вони — мого батька. Певно, їх послали зі мною, щоб я не плуталася в нього під ногами, поки він коїть щось жахливе. \n\nЯ сподівалася, що до цього не дійде. Мені так прикро. Прошу, дозволь допомогти тобі спинити його.",
    },
    [72427] = {
        title = "Жвава настоянка",
        description = "Сьогодні в мене до тебе проста справа.\n\nАлхімікам бракує одного інгредієнта для особливо складного відвару. Зілля знайти неважко. Тобі лишень треба відшукати кілька агресивних рослин і взяти з них зразки. Гадаєш, упораєшся?",
        objectives = "Збери 13 Колючого Листя з хльостунів Драконових Островів для Дуррела з кентаврів маруків.",
        progress = "Вдалося роздобути зілля?",
        completion = "Що ж, не кожне полювання буде найзахопливішим. Проте здобуті тобою зразки підуть на добру справу.",
    },
    [72428] = {
        title = "Рогохробні скнари",
        description = "Не секрет, що тутешні рогохробні обожнюють самоцвіти, коштовності й усе блискуче. Та я ось нещодавно знайшов дуже рідкісну коштовність у послідах рогохробного!\n\nЩо ж, завдання, можливо, не найприємніше, але, схоже, рогохробні мають звичку не лише збирати цінності, а й поїдати їх.",
        objectives = "Збери 20 Смердючих Самоцвітів у рогохробних Драконових Островів для Ґнокліна Квіркойла з Експедиції Драконячої Луски.",
        progress = "Вдалося знайти самоцвіти?",
        completion = "Що ж, пахнуть ці самоцвіти не надто чарівно... Негайно візьмемося їх відчищати.",
    },
    [72429] = {
        title = "Знайомство: Маруукай",
        description = "<Поки Сансок Хан говорить жестами, Окір озвучує її слова.>\n\nМаруукі не затяті вороги чужинцям, але вимагаємо, щоб кожен потенційний союзник довів, чого він вартий. Знайомся з кланами, ставай у пригоді в наших справах — і слава про твою підтримку розійдеться сама.\n\nНа нижньому ярусі круталу на пагорбі знайдеш одну з доньок Ханам Матри — вона підкаже, як наш народ до тебе ставиться. Неодмінно відрекомендуйся їй.",
        objectives = "Зустрінься з Охоронцем Слави та Інтендантом Слави в Маруукаї.",
        progress = "Я з нетерпінням чекаю нагоди побачити, чим ти прислужишся маруукам.",
        completion = "Я з нетерпінням чекаю нагоди побачити, чим ти прислужишся маруукам.",
    },
    [72430] = {
        title = "Лиходійства в Мунбруку",
        description = "Мунбрук? Що цей граф Клессінґтон забув у моєму рідному місті?!\n\nНічого доброго це не віщує. Я подам сигнал Шоу.\n\n<Ванесса кидає погляд на Сесілію Клессінґтон.>\n\nЗ неї вийде непогана заручниця. Прихопимо й багату панянку.\n\nЗустрінемося там.",
        objectives = "Зустрінься з Ванессою та Шоу в Мунбруку у Вестфолі.",
        completion = "Чому тут... так порожньо?",
    },
    [72431] = {
        title = "Голодна спадщина",
        description = "Я вже давно не була вдома.\n\nЩось тут не так. Мої люди мали б бути тут.\n\nЯ йду всередину... але від підмоги не відмовлюся.\n\n...Не варто було мені зникати так надовго.",
        objectives = "Обстеж сховок Дефаїв у Мунбруку разом із Ванессою.",
        completion = "Та як вони сміють!",
    },
    [72432] = {
        title = "Лише добірні горлорізи",
        description = "Ці «прислужники» мого батька напали на нас, щойно ми прибули!\n\nЦе точно не ті лагідні слуги, яких я знала в дитинстві. Це наймані вбивці!\n\nЯкщо мій батько задумав те, що я підозрюю... ми не можемо їм цього дозволити. Вони повбивають кожного, хто стане їм на шляху.\n\n<Сесілія здригається.>\n\nЯкщо вже або ми їх, або вони нас...",
        objectives = "Убий 16 прислужників Клессінґтона у сховку Дефаїв у Мунбруку.",
        progress = "Якби ж я могла допомогти більше. Ніколи ще я так не шкодувала, що не перейняла батькових умінь у таємній магії.",
        completion = "Сподіваюся, їхні душі знайдуть спокій. Шкода, що інакше було не можна.",
    },
    [72434] = {
        title = "Коло Рубінового Святилища Життя",
        description = "Кажуть, я ще замалий, щоб літати деякими з цих трас.\n\nАле я все одно можу дивитися, як це роблять інші. Тобі варто позмагатися! Тоді я зможу подивитися на твої перегони.",
        objectives = "Пройди трасу «Коло Рубінової Святині Життя».",
    },
    [72435] = {
        title = "Знайомство: Іскаара",
        description = "Ласкаво просимо до Іскаари, $p(друже:подруго).\n\nЧутки про твої подвиги в Брекенгайді вже розійшлися серед нашого народу. Ти вже зустрів багатьох із нас, але є й інші, хто радо обмінявся б із тобою знаннями та товаром.\n\nПрошу, приділи хвильку, щоб ближче познайомитися з кількома привітними обличчями Іскаари. Ми — громада, що тримається одне за одного, тож як ти маєш багато чого нам запропонувати, так і багато хто з наших людей має чим віддячити тобі.",
        objectives = "Познайомся з деякими торговцями, що мають цінний крам.",
        progress = "Нам є чим обмінятися, друже.",
        completion = "Сподіваюся, тобі буде приємно в Іскаарі. \n\nЯк тобі тепер відомо, багато хто з нас — вправні ремісники й торговці. Раджу й далі розпитувати та дізнаватися, що може запропонувати кожен із мого народу.",
    },
    [72438] = {
        title = "Наміри тарасеків",
        description = "Коли тарасеки прийняли силу від первісників, вони викрали чимало старовинних сувоїв та фоліантів, щоб поєднати їх зі своєю новонабутою магією. Нам потрібна допомога, щоб повернути ці сувої собі.",
        objectives = "Збери 15 Драконічних Сувоїв у тарасеків Драконових Островів для Дотеноса зі Згоди Валдраккена.",
        progress = "Вдалося повернути якісь із сувоїв?",
        completion = "Дякую, що допомагаєш нам повернути ці цінні знання.",
    },
    [72440] = {
        title = "Срібний гарт",
        description = "Гадаю, Срібна Луска ще може стати нам у пригоді. Під час спостережень я відчув у ній... енергію, що сягає поза межі часу й, схоже, співзвучна Тіру. До того ж вона має таку саму будову, як і диск.\n\nЦілком імовірно, що за допомогою Срібної Луски ми зможемо здобути один зі спогадів Тіра, який він не закарбував у диск.\n\nХай це й видається моторошним, але якщо вирушити до його гробниці в Тірісфалі, ми зможемо хоча б частково його відновити.\n\nАлекстраза розповість тобі більше, {name}.",
        objectives = "Вирушай до Гробниці Тіра з допомогою Аспектів.",
        progress = "Не хочу налякати цього чоловіка своєю... присутністю. Мабуть, буде краще, якщо спершу до нього підійдеш ти.",
        completion = "Це місце — пам'ятник спадщині Тіра. Ми мусимо просуватися обережно й з побожною шаною.",
    },
    [72441] = {
        title = "Прорив до гробниці",
        description = "Щось нещодавно ввімкнуло титанічну захисну систему гробниці. Раніше я не бачив тут титанічних конструктів.\n\nЯ саме з'ясовував, чому вони з'явилися, коли мене замкнули поза гробницею. Можливо, їх пробудила твоя місія.\n\nЯкщо ми хочемо рушити далі, нам слід знешкодити нові засоби захисту. Сяйливі кулі обабіч дверей можуть стати ключем. Якби ж вони не були пошкоджені...",
        objectives = "Знешкодь кулі титанів біля входу до гробниці.",
        completion = "Твоя місія відновила мою віру. Отже, що ми маємо зробити, аби відродити Тіра?",
    },
    [72442] = {
        title = "Останки Тіра",
        description = "Як Ноздорму відчував силу, що зачаїлася в лусці, так і я відчуваю тут Тіра. Він — у самому камінні цього місця.\n\nПідозрюю, що інші конструкти теж це відчувають. Вони, певно, прийшли сюди, коли Тіра перековували. Ми, мабуть, на правильному шляху.\n\nЯкщо щось від його присутності ще лишилося, луска має зібрати це — за допомогою цієї консолі. Та конструкти можуть сприйняти наш збір останніх спогадів Тіра як спробу їх знищити.\n\nСтримуй їх, якщо вони прокинуться.",
        objectives = "Захищай Споглядача Кораноса від конструктів у гробниці.",
        completion = "Завдання виявилося заважким для цієї старої консолі, але нашу наполегливість винагороджено.\n\nУ лусці щось є, та я не певен, що саме.\n\n Я... не впевнений, що хочу повертатися до Алекстрази з самим лише «чимось». Луска може містити нісенітницю, спотворену збоєм консолі. А може — саме те, що нам потрібно.\n\nМожливо, інша консоль зможе перевірити її вміст?",
    },
    [72443] = {
        title = "Падіння Тіра",
        description = "Ця консоль дасть нам змогу дослідити вміст луски, але я не знаю, що ми там знайдемо.\n\nІнші слуги титанів тут мають дати нам спокій; доступ до вмісту не спричинить такого збурення, як перенесення того, що ми відчули від Тіра.\n\nЩось непокоїть Траварда. Будь готов$p(ий:а) до всього, {name}.\n\nВклади Срібну Луску в консоль, коли вирішиш продовжити.",
        objectives = "Скористайся консоллю титанів, щоб побачити останні спогади Тіра.",
        progress = "Ми досі багато чого не знаємо про Тіра.",
        completion = "Яке шляхетство навіть в останні миті. Закайз глузував із нього, згадуючи драконів... Та чи справді Тір знав, що ті їх зрадять? А Алекстраза — чи знатиме? \n\nЦе стало б для них тяжким ударом... \n\nЯкщо Тіра не вдасться відродити, можливо, їм і не треба цього знати.",
    },
    [72444] = {
        title = "Дрібка срібла",
        description = "Останні спогади Тіра — у наших руках. Цю відповідальність не можна сприймати легковажно.\n\nВіднесімо Срібну Луску до Ноздорму в Тіргольд. Ми спробуємо скористатися тамтешньою консоллю, щоб пробудити його.\n\nЯкщо він знову стане цілим, нам буде що обговорити.",
        objectives = "Вийди з гробниці й повернися до Аспектів у Тіргольд у Валдраккені.",
        progress = "Ми зробимо все необхідне, щоб відродити Тіра.",
        completion = "Дякую, {NAME}.\n\nЯ... розчарований, що Срібна Луска не стала відповіддю.\n\nМожливо, нам доведеться змиритися з майбутнім без Тіра.\n\nЯ все ще не втрачаю надії, що ми знайдемо диск і відродимо Тіра. А якась частина мене вірить, що ми зможемо здолати нескінченних — і Втілених — самотужки. \n\nАле деякими шляхами, хоч би які темні вони були, судилося пройти.",
    },
    [72445] = {
        title = "До Нортширу",
        description = "Турбота Ванесси про своїх людей заслуговує на більше, ніж братство бандитів. Я радий бачити, що їхні шляхи розходяться.\n\nІ мені, як майстрові шпигунів, неабияк відлягло від серця.\n\nА тепер — Нортшир. Там прості селяни можуть стати героями. Можливо, і твоя власна подорож почалася в тому абатстві?\n\nДо того ж це міцна, добре захищена позиція, звідки можна вдарити по Стормвінду. Ми не можемо допустити, щоб Нортшир упав!\n\nМерщій, до Нортширу!",
        objectives = "Зустрінься з Ванессою, Сесілією та Шоу в Нортширі.",
        completion = "Ми мусимо допомогти!",
    },
    [72446] = {
        title = "У чому їхня біда?",
        description = "Радий знову тебе бачити, рекруте. Шкода лише, що за таких обставин.\n\nХоч би що це був за «вплив», тепер кожен, у кого є бодай дрібка злоби, вважає, що заради цього варто проливати кров!\n\nА ще ж усі ці бандити Дефаїв! І найняті горлорізи! За такого стану справ нові солдати зі Стормвінда лише посіють ще більше сум'яття.\n\nЗ того, що я бачив, більшість цих людей можна привести до тями. Та якщо вони й далі нападатимуть на тебе, коли в очах проясниться... роби, що мусиш. Вони зробили свій вибір.",
        objectives = "Захисти Нортшир.",
        progress = "Чого я тільки не бачив за роки вишколу новобранців... але це вже божевілля!",
        completion = "Ми приймемо всіх, кого зможемо, і вилікуємо. Навіть якщо декого доведеться зв'язати. \n\nДуже сподіваюся, що ця магія не лишає тривалих наслідків.",
    },
    [72447] = {
        title = "Найстрашніша з загроз",
        description = "Могутні джарадини та інші створіння загрожують і Обсидіановій цитаделі, і безпеці мого роду.\n\nЦього не можна терпіти.\n\nДопоможи убезпечити цю місцевість. Розшукай і знищ двох наших найсильніших ворогів.",
        objectives = "Знищ двох рідкісних ворогів в Обсидіановій Цитаделі чи Шлаковій Трясовині.",
        progress = "Справу зроблено?",
        completion = "Чудова робота. Твою готовність допомагати помічено... і поціновано.",
    },
    [72448] = {
        title = "Захистити нашу спадщину",
        description = "Я не працював так тяжко і не зайшов так далеко, щоб тепер втратити Цитадель!\n\nНа жаль, з'явилися нові загрози. Чи можу я розраховувати на твою допомогу, щоб дати їм раду?\n\nДопоможи убезпечити цю місцевість. Розшукай і знищ двох наших найсильніших ворогів.",
        objectives = "Знищ двох рідкісних ворогів в Обсидіановій цитаделі чи Шлаковій Трясовині.",
        completion = "Молодець! Я знаю, що на тебе завжди можна покластися, друже.",
    },
    [72449] = {
        title = "Годі вже!",
        description = "Ми спізнилися, {name}.\n\nКлессінґтон засів усередині абатства й поширює хаотичний вплив амулета на весь Нортшир!\n\nГадаю, більшість тутешніх людей уже не відрізняє друга від ворога.\n\nЦей чоловік скидається на того, хто завжди має запасний план. У цих агентів має бути спосіб пройти крізь бар'єр Клессінґтона. Прибери їх і пошукай щось корисне!",
        objectives = "Збери 4 Ключі від Бар'єра зі старших прислужників.",
        progress = "Ми мусимо пройти крізь бар'єр і дістатися Клессінґтона, і то якнайшвидше.",
        completion = "Гм, схоже, їх можна якось поєднати...",
    },
    [72450] = {
        title = "Воля Клессінґтона",
        description = "Я не така вправна в магії, як мій батько, але кілька його хитрощів знаю.\n\nЯ бачила ті печатки, що ти зня$p(в:ла) з горлорізів. Особисті покої мого батька були замкнені схожою магічною дрібничкою, яку можна розламати на частини.\n\nДозволь мені скласти ці печатки докупи в арканний ключ. Він має провести нас крізь бар'єр.\n\nА тоді... мені лишається тільки сподіватися, що ми зможемо напоумити його.",
        objectives = "Постань перед графом Клессінґтоном у Нортширському абатстві.",
        progress = "Ненавиджу, що дійшло до такого...",
        completion = "Вибач, мені потрібна хвилинка. Він не був доброю людиною, але... він усе ж був моїм батьком.",
    },
    [72451] = {
        title = "Воля до життя",
        description = "...Отже, справу зроблено.\n\nЯ б охоче розпитав цього чоловіка ще. Але сила виявилася для нього завеликою.\n\nНе можна допустити, щоб амулет потрапив у чужі руки. Забери його, {name}, і ми разом подбаємо, щоб він безпечно повернувся до Стормвінда.",
        objectives = "Забери Амулет Драконячого Вогню.",
        progress = "Ми тут закінчили?",
        completion = "Я втомилася, {NAME}. Втомилася від безперервних битв. Втомилася від того, що мною маніпулюють, мене покидають і кривдять. Як і весь наш народ. \n\nМені бракує тієї, ким я була колись. Простої дівчини, яка хотіла піти батьковими слідами й водночас допомагати рідному краю. Дівчини, яка вірила, що це можливо. \n\n \n\n...Мабуть, я завинила тобі подяку. Завдяки тобі мені є про що подумати.",
    },
    [72452] = {
        title = "Іди з честю, друже",
        description = "Це завдання виявилося куди складнішим, ніж будь-хто з нас сподівався, {name}, і ти впора$p(вся:лася) чудово. Я здригаюся на саму думку про те, що сталося б без тебе.\n\nСвого часу король замовив виготовити обладунок. Обладунок, що прикрасить наших найвидатніших героїв.\n\nТи дові$p(в:ла), що більш ніж гідн$p(ий:а) такої честі.\n\nЗустрінься зі мною в Долині Героїв, {name}.",
        objectives = "Зустрінься з Шоу в Долині Героїв у Стормвінді.",
        progress = "Стормвінд багато чим завдячує тобі, герою.",
        completion = "Це місто стільки всього тобі завдячує. Дякую, герою. \n\nНоси цей обладунок із гордістю.",
    },
    [72453] = {
        title = "Зрада Братства",
        description = "Я мала б здогадатися. Я втратила владу над Братством тієї миті, коли запропонували помилування. Усі, хто мав принципи, давно пішли.\n\nЛишилися самі головорізи. А Дункон Ратсбон завжди був найбільшим головорізом з усіх.\n\nЗабираймося звідси, {name}. Якщо хтось із цих дурнів спробує стати нам на заваді, провчімо їх — хай знають, як це: заступати дорогу комусь із ВанКліфів.",
        objectives = "Утечи зі сховку Дефаїв.",
        completion = "Дивне відчуття, і все ж... до цього давно йшло. \n\nВідколи ми билися з Легіоном, я почувалася далекою від Братства. До Вестфолу почала надходити більша допомога, і хоч її ніколи не буде досить... іскра революції пригасла.\n\n...А може, я просто старію.\n \nІ все ж колись я вважала себе тією, хто заступається за людей. Я помилялася, я кривдила їх... але хто ще в них є? \n\nЯ мушу стати кращою — не заради Дефаїв, а заради Вестфолу.",
    },
    [72454] = {
        title = "Обсидіанове драконятко",
        description = "Яйце чорного драконячої зграї готове ось-ось проклюнутися.\n\nЗвернися до Матері Еліон у Рубіновій Святині Життя, щоб забрати яйце. Тоді, прошу, віднеси яйце до Обсидіанового Каменя Присяги, щоб воно проклюнулося в місці, сильному міццю їхнього роду.\n\nКоли впораєшся, повертайся сюди з драконятком, і ми далі про нього подбаємо.",
        objectives = "Забери Яйце Чорного Дракона в Рубіновій Святині Життя, а тоді дай йому проклюнутися біля Обсидіанового Каменя Присяги.",
        progress = "Найновіше драконятко вже з тобою?",
        completion = "Неосквернене обсидіанове драконятко.\n\n<На обличчі Ластака проступає легка усмішка.>\n\nМинуло чимало часу.",
    },
    [72455] = {
        title = "Тепло й затишок",
        description = "Щоб обсидіановому драконятку було затишно, ми маємо звести йому належне гніздо.\n\nТобі доведеться збудувати гніздо з вугілля Обсидіанової цитаделі, щоб воно було теплим і придатним. По-друге, архіваріус Едресс зможе допомогти тобі знайти щось, що поєднає його з його родом.\n\nМи також захочемо роздобути щось із Печери Заралек, адже значна частина історії їхнього роду закорінена саме там. Напевно хтось у Лоаммі зможе допомогти.",
        objectives = "Збери припаси для гнізда обсидіанового драконятка.",
        progress = "Із цим драконятком нам найбільше треба навчитися... Сподіваюся, їй стане терпіння, поки ми вдосконалюємося.",
        completion = "<Аґапантус із полегшенням позирає на гніздо обсидіанового драконятка.>\n\nУ новому гнізді їй буде дуже затишно. Чудова робота.",
    },
    [72456] = {
        title = "Фоліанти довіри",
        description = "Попри те, що ми убезпечили верхні мури Обсидіанової цитаделі, сили джарадинів і далі грабують подвір'я. Ця місцевість повна безцінних історичних записів! Ми мусимо діяти швидко, щоб уберегти все, що задокументувало родовід чорного драконячої зграї.\n\nІ Вратіон, і Сабелліан прагнуть цих відомостей, тож ти можеш заслужити їхню прихильність, роздобувши по фоліанту для кожного з них.\n\nВирушай до завеленої вежі цитаделі. Там ти маєш знайти щось варте порятунку.",
        objectives = "Віднайди томи Обсидіанового Родоводу й достав їх інтендантам Вратіона та Сабелліана.",
        progress = "Вдалося знайти фоліанти?",
        completion = "Пречудово! Певна річ, і Вратіон, і Сабелліан будуть задоволені твоїми стараннями.",
    },
    [72457] = {
        title = "Домашня страва",
        description = "Малята чорних драконів мають вирости великими й сильними. Наше пташеня тут зовсім маленьке, тож, гадаю, їй знадобиться щось ситне й поживне, аби набратися сил.\n\nСмажена качка корисна не лише для витривалості, а й для розуму. Думаю, це буде ідеальна страва для нашого юного пташеняти.",
        objectives = "Роздобудь Смакоту зі Смаженої Качки для обсидіанового драконятка. Її можна приготувати за допомогою професії кулінарії або купити на аукціоні.",
        progress = "Качка — місцевий делікатес Драконових островів. Чи відомо тобі, що більше ніде в Азероті ми їх не знаходили?",
        completion = "Малятам, щоб рости, потрібне добре джерело енергії. Вони страшенно ненажерливі!",
    },
    [72458] = {
        title = "Квач, ти боїшся",
        description = "Кожному маляті потрібен час для ігор, щоб випустити енергію. Наша нова обсидіанова подруга не виняток.\n\nПташенята обожнюють гарну гру в квача. Поглянь, чи захоче вона погратися з тобою!",
        objectives = "Пограйся з обсидіановим драконятком.",
        progress = "Кожне пташеня обожнює гру в квача!",
        completion = "Вона доволі полохлива, чи не так?",
    },
    [72459] = {
        title = "Що таке качка?",
        description = "Буду з тобою чесна, {name}.\n\nМинуло стільки часу, відколи ми мали справу з родом чорних драконів, що я небагато можу про них розповісти. Знаю лише, що вони сильні воїни, відважні захисники всіх нас.\n\nРусіона ще зовсім юна, але, можливо, нам варто перевірити, як вона дає собі раду в бою? Візьми її повправлятися на качках у Рівнинах Он'агри. Подивимося, на що вона здатна.",
        objectives = "Убий 5 Синьодзьобих Перевальців у Первісній Долині разом із Русіоною.",
        progress = "І як Русіона впоралася з качками?",
        completion = "Вона ЩО?!\n\n<Аґапантус хапається за голову й тяжко зітхає.>\n\nЗнаєш, це було нетактовно з мого боку. Я мав би краще розуміти.\n\nГадаю, нам доведеться почати все з чистого аркуша.",
    },
    [72460] = {
        title = "Надійний улюбленець",
        description = "Я хвилююся за Русі. Вона страшенно нервова й невпевнена, лякається майже всього! Ніколи не чула, щоб чорний дракон так боявся світу.\n\nГадаю, найкращий спосіб додати їй упевненості — знайти їй супутника. Когось міцного й сильного, хто не рухається швидко чи різко.\n\nРід чорних драконів покликаний оберігати землю. Можливо, маленький елементаль їй добре підійде.\n\nПоговори з Лісіндрою в крамниці улюбленців у Валдраккені. У неї має бути щось підхоже.",
        objectives = "Роздобудь улюбленця для Русіони.",
        progress = "Земляні елементалі — чудові перші улюбленці. Їдять гравій, не тікають далеко й швидко, а ще можуть вистояти майже проти будь-чого!",
        completion = "Поглянь на цього чудового елементаля! Сподіваймося, він допоможе нашому пташеняті набратися впевненості.",
    },
    [72461] = {
        title = "Анатідаефобія",
        description = "Настав час, {name}. Її новий улюбленець Іґґі творить дива з упевненістю Русіони, і тепер, гадаю, вона готова стати на герць зі своїм найбільшим страхом.\n\nКачками.\n\nНа Узбережжі Пробудження є таврен, яка майстерно зцілює душевні рани за допомогою улюбленців. Думаю, вона саме те, що нам потрібно.\n\nЛастак і Русіона зустрінуть тебе там.",
        objectives = "Допоможи Русіоні та Іґґі перемогти качку в бою улюбленців.",
        progress = "Доросла качка для Русіони, мабуть, ще занадто, а от каченя буде саме те.",
        completion = "Дякую тобі за все, що сталося з Русіоною, {NAME}. Вона спитала, чи можна їй вирушати з тобою в деякі з твоїх пригод. Вона впевнена: поки вона з тобою, їй нічого не загрожує.",
    },
    [72462] = {
        title = "Народ, що потребує зцілення",
        description = "Це дивно, {name}. Попри роки миру, я не маю спокою. Попри те, що поруч Орда й мій син, я почуваюся самотнім. Ти відчуваєш те саме, чи не так? Я бачу це в твоїх очах і в очах багатьох орків.\n\nМабуть, я відчуваю, що, знайшовши свій шлях на Азероті, ми загубили свій шлях як орки.\n\nХодімо зі мною. Я хочу поговорити про ці тривоги зі старим другом, і хотів би, щоб ти бу$p(в:ла) поруч.",
        objectives = "Вирушай з Ейтріґґом до Альтеракської Долини, щоб обговорити майбутнє орочого народу з Дрек'Таром.",
        completion = "Це мали бути тихі родинні відвідини Дрек'Тара — і, може, розмова з Дураком про його майбутнє. \n\nНатомість ми стали на шлях, що вплине на весь орківський народ!\n\nНе зрозумій мене хибно: гадаю, це найкращий спосіб дій. Просто дивно, як швидко все сталося. Я маю стати Провидцем...\n\nНа нас чекає багато роботи. Берімося до діла.",
    },
    [72463] = {
        title = "Кактусово-яблучний сюрприз Ґалґара...",
        description = "<Останніми словами юної орки було прохання передати ці кактусові яблука Ґалґарові.\n\nЧи виконаєш ти її прохання?>",
        objectives = "Віднеси торбу кактусових яблук Ґалґарові.",
        progress = "О, привіт, {NAME}. Що це там у тебе?",
        completion = "Чому це приносиш ти? Я ж просив...\n\nО ні.\n\nНіхто не мав через них гинути! Я просто прошу про це всіх юних орків! Це ж мало бути легко!\n\nЩо ж... Мабуть, дякую, що це зроблено за неї. Насолоджуйся винагородою...",
