    [72513] = {
        title = "Наша доля",
        description = "$p(Пробуджувачу:Пробуджувачко)! Можливо, ти нещодавно відчу$p(в:ла) збурення.\n\nМи з Ебіссіаном почали руйнувати прадавні сифони, що витягали есенцію чорної зграї драконів із драктирів. Гадаю, лише повністю навчені пробуджувачі, як-от ти, достатньо чутливі, щоб відчути цю зміну.\n\nАле це ще не все. Прошу, приєднайся до нас із Ебіссіаном біля Високих Ясел на Заборонених Обширах. Нам треба звільнити дракона з кайданів.",
        objectives = "Поговори з лускокомандиром Ембертал біля Високих Ясел.",
        completion = "{class}, будь напоготові. Схоже, у нас проблема.",
    },
    [72514] = {
        title = "Високі Ясла",
        description = "Ти відчу$p(в:ла) це?\n\nМи вже почали руйнувати бар'єр. Ця в'язниця для Адамантії тримала в собі стільки сили.\n\nІ тепер я знову можу підсилювати! Повністю навчений пробуджувач завжди був покликаний підсилювати союзників — так само, як зціляти чи нищити. Тепер я це згадую... і не лише це.\n\nЯ починаю згадувати, ким був цей ув'язнений чорний дракон... ким вона була для всіх драктирів.\n\nПрошу, {name}, допоможи мені зняти ці кайдани.",
        objectives = "Знешкодь 4 збирачі есенції.",
        progress = "Яка мстивість у цій пастці... як ми могли бути такими сліпими до жорстокості Нелтаріона?",
        completion = "Чудова робота. Нам знадобиться Ебіссіан, щоб розітнути останню нитку магії, яка підтримує це ув'язнення.",
    },
    [72515] = {
        title = "Підсилення дракона",
        description = "Адамантія!\n\nВона була ув'язнена цілі віки, замкнена в муках. Поки драктири спали, вона страждала.\n\nМожу лише сподіватися, що за час свого довгого ув'язнення вона не піддалася божевіллю Дезвінга. Плин часу міг зламати її розум.\n\nБудь напоготові, $p(чемпіоне:чемпіонко). Якщо вона накинеться, допоможи Ебіссіану. Підсили його здібності, щоб він зумів приборкати Адамантію, а не вбити її.\n\nВона заслужила на шанс. Ми мусимо їй його дати.",
        objectives = "Допоможи Ебіссіану приборкати Адамантію.",
        progress = "Адамантія чекала на цей день доволі довго. Сподіваймося, він не настав запізно.",
        completion = "Ми... впоралися.\n\nГадаю... з нею все буде гаразд. Дякую, {class}. Тепер ми подбаємо, щоб Адамантія отримала допомогу й зцілення, яких потребує, — і зможемо привітати її в цьому новому світі.",
    },
    [72519] = {
        title = "Темпоральне дволаштування",
        description = "Розумію... Вони падають крізь можливості так само, як і крізь час.\n\nПоспішай, я виявив іще одну точку в часовій лінії, де ми могли б їх перехопити. Це... незвичне місце, але не дай дивності цього світу себе сповільнити. Доля Хронорму у твоїх руках.",
        objectives = "Використай Хронокристал на Етернус і Хромі в Азмерлоті, щоб зупинити їхнє падіння крізь час.",
        completion = "Процес не був завершений, але тепер я можу точніше відстежувати Хронорму.",
    },
    [72524] = {
        title = "Базове спорядження для сходження",
        description = "<Слідопит Джеб показує на набір припасів поряд із собою.>\n\nТобі знадобляться припаси, щоб вижити там.\n\nЗберімо тобі все потрібне, щоб почати сходження.",
        objectives = "Використай Набір Припасів Експедиції, щоб дослідити спорядження для сходження.",
        completion = "Це базове спорядження стане тобі в пригоді для початку.\n\nПовертайся, коли назбираєш більше Припасів Драконових островів, щоб опанувати нове спорядження.",
    },
    [72525] = {
        title = "Базове спорядження для каталогізації",
        description = "Кожен каталогізатор експедиції заслуговує на власну камеру!\n\nТобі не обов'язково давати своїй особливе ім'я, але я дуже раджу це зробити. Так значно цікавіше.\n\nХай там як, слідопит Джеб має дати тобі все, що потрібно.\n\nМені ще жодного разу не знадобилося чогось, чого він не мав би при собі. Він неймовірний!",
        objectives = "Використай набір експедиційних припасів, щоб дослідити спорядження для каталогізації.",
        completion = "О, твоя нова камера прекрасна. Вона пасує тобі просто ідеально!",
    },
    [72526] = {
        title = "Спочинок Хранителя",
        description = "Мені прикро бачити, як інші створіння, викувані Тіром, виходять з ладу. Вони доклали стількох зусиль, щоб уберегти гробницю від обвалу, а тепер вона занепадатиме, позбавлена навіть тих решток світла Тіра, що лишалися.\n\n<Коранос показує на Срібну Луску.>\n\nСподіваюся, те, що в лусці, варте їхнього знищення. Знайдімо іншу консоль, щоб дізнатися, що саме записано на лусці, якщо там узагалі щось є.",
        objectives = "Утечи до Темного Ходу.",
        progress = "Ми діємо на службі Тіра. Він би зрозумів.",
        completion = "Поки що ми в безпеці, але затримуватися не варто.",
    },
    [72527] = {
        title = "Не буває ніякого невезіння",
        description = "Слухай, вір чи не вір, але якби не незавершені справи, я б уже давно був на Островах. Останнім часом доля до мене неласкава. Я заборгував Барону, а Барону ніхто не винен довго. Якщо не заплачу — він мене знайде і злупить шкуру, це вже напевно.\n\nЙого гроші я вклав у ці магічні кристали, але ціна на них щойно обвалилася — через скандальну статтю на першій шпальті «Вісника Бухти Здобичі». А партія кристалів ще й зникла безвісти!\n\nХтось точно замислив мене згубити. Може, Ґудстічі мені допоможуть.",
        objectives = "Знайди Бліксреза Ґудстіча в шкіряній майстерні «Вичини Мою Шкуру» в Бухті Здобичі.",
        completion = "...Не варто було й дивуватися, що ніхто не допоможе мені задарма. Спитай у Бліксреза його ціну.",
    },
    [72529] = {
        title = "Інформація править світом",
        description = "Інформація дешевою не буває. Кому-кому, а Зеросу це слід знати найкраще.\n\nКажуть, біля мису Жанейро бачили небезпечних кроколісків. А знаєш, що бачу я? Гроші, гроші, гроші! Принеси мені їхні дорогоцінні шкури — і, може, я пригадаю дещо важливе про ті кристали, за якими ганяється Зерос.\n\nЯкщо це для тебе занадто ризиковано, я готовий розглянути й інші форми оплати. Ну, знаєш, найпоширенішу.\n\n<Бліксрез схрещує руки на грудях і вичікувально дивиться.>",
        objectives = "Збери 3 шкури кроколіска біля мису Жанейро або віддай золото Бліксрезу Ґудстічу.",
        progress = "Дружба — як терези. Вона мусить лишатися врівноваженою за всяку ціну!",
        completion = "Угу, це згодиться!",
    },
    [72530] = {
        title = "Коротше, я почав давати хабарі",
        description = "От негідник! Ми з Арті домовлялися, що він розрекламує кристали в газеті. Мабуть, хтось запропонував йому вигіднішу угоду.\n\nАрті регулярно оглядає робочу зону Компанії «Венчер» на узбережжі. Він завжди бере із собою охорону, але в Бухті Здобичі ніхто не встоїть перед золотом.\n\nОсь, візьми моє останнє золото. Іди до нафтових вишок і підкупи охоронців, щоб відвернулися, а тоді вже притисни Арті.",
        objectives = "Підкупи золотом найнятих охоронців Арті, а тоді притисни розвідника надр Арті на Дикому узбережжі.",
        progress = "Це все золото, що я мав, тож якщо доведеться докинути кілька стусанів, щоб підсолодити угоду, — прошу дуже.",
        completion = "Пірати?! Ну звісно. Тепер ми знаємо, куди йти далі.",
    },
    [72532] = {
        title = "Гроші, гроші, гроші!",
        description = "Ґраб Редкат і його команда сумнозвісні своєю любов'ю до грошей. Заради них вони підуть на все.\n\nГадаю, на його кораблі знайдеться скарб, та якщо раптом ні — золото точно є в їхніх кишенях. Візьмешся за цю брудну справу й збереш його для мене?\n\nЯ не розпитуватиму про твої методи переговорів — тільки не вбивай їх! Я не планую сьогодні розпочинати справжню кровну ворожнечу.",
        objectives = "Збери 1500 золотих монет у піратів Ґраба Редката на Південному Лютому узбережжі.",
        progress = "Давно час тим піратам затямити, що вони не можуть тероризувати всіх, кого їм заманеться.",
        completion = "О золото моє, оце вже схоже на чималеньку суму.",
    },
    [72533] = {
        title = "Кристали-шмистали",
        description = "Ґраб. Редкат. <Зерос спльовує.> Скиглій і зачерствілий невдаха, який має себе за крутого, бо великий і накачаний. Його гризе, що такий, як я, заробляє більше за нього.\n\nВір чи ні, але на аукціоні я граю чесно. Порівняно з ним я просто святий!\n\nТо Ґраб продав мої кристали, кажеш? А потім заплатив Арті, щоб той про них збрехав — аби ніхто не кинувся шукати. Гарний план.\n\nНа тому його кораблі точно є щось цінне. Що ж, ми це заберемо. Обшукай корабель як слід.",
        objectives = "Забери скарб Ґраба Редката з його корабля на Південному Лютому узбережжі.",
        progress = "Прошу, поквапся! Барон не жартував щодо моєї луски — я ж, як ти знаєш, дракон, і моя луска коштує чимало.",
        completion = "Що тобі вдалося принести?",
    },
    [72534] = {
        title = "Розрахунок із Бароном",
        description = "Ха!.. Ти саме вчасно. Ще хвилина — і тобі на руки дістався б дракон без шкури.\n\nВіддай йому скарб, хутко.",
        objectives = "Віддай скарб Барону Ревілґазу.",
        progress = "Та віддай уже йому золото, гаразд? Благаю!",
        completion = "Сенеґосе! Ти щойно врятував мені життя.",
    },
    [72545] = {
        title = "Ясла полеглих",
        description = "Це мій провал, {name}.\n\nЦе я привела сюди цих драктирів. Вони знали, що смерть можлива, але й вірили, що я буду поруч.\n\nЯ мала бути там, унизу, розчищати руїни, а не тут, гортати книги.\n\n<Ембертал стискає кулаки.>\n\nМені потрібно, щоб ти забра$p(в:ла) їхні рогові печатки. Ми маємо віддати їм шану.",
        objectives = "Збери рогові персні-печатки Тетсоса, Арроша, Екраті та Герміна в Загубленому Атенеумі.",
