    [72679] = {
        title = "Арканний реквієм",
        description = "Час настав, {name}. З твоєю допомогою більшість неспокійних відлунь Шандаралу вже вгамовано. Проте лишилися ті, чия лють і скорбота палають надто яскраво, щоб їх могли розрадити самі лише слова.\n\nЗі знайдених тобою уламків мені вдалося відтворити подобу кристалічного фокуса, що призвів Шандарал до загибелі. Якщо застосувати його тут, прикуті до цього місця духи постануть перед нами — і ми зможемо подарувати їм останній спочинок.\n\nБудь напоготові. Я не знаю, як проявляться їхні багатовікові жалі.",
        objectives = "Подаруй відлунням Шандаралу останній спочинок.",
        progress = "Це не буде щасливий кінець — але це все одно буде кінець.",
        completion = "Нарешті магію, що прив'язувала ці змучені спогади до цих руїн, зруйновано.\n\nМине ще якийсь час, перш ніж менші відлуння повністю розвіються. Але тепер, коли їхнє джерело вигнано, а уламки реліквії прибрано, фрагменти пам'яті, що лишалися тут у пастці, нарешті звільняться від своїх мук.",
    },
    [72681] = {
        title = "Прибути до торгової застави",
        description = "<Зблиск віддаленого предмета привертає твою увагу. Ти раптом згадуєш, що маєш зібрати девізи для використання на торговому посту T&W.>",
        objectives = "Повернися до торгового посту, щоб забрати свої девізи зі Скрині колекціонера.",
        completion = "Сподіваюся, тобі сподобається цьомісячна добірка нових та екзотичних товарів, {NAME}.",
