    [72881] = {
        title = "Ластівчина історія",
        description = "Горянине!\n\nЯ Еффервеста, леді Пахощ ніффенів Лоамма — донька їхньої очільниці. Та облишмо формальності, можеш звати мене просто Еффі!\n\nХай це лишиться між нами, але ми трохи запізнюємося з кількома поставками до Ґліммероґґа, і дроґбари цьому геть не раді! Ти вже так допоміг старійшині Медошкуру... може, і мені підсобиш?\n\nНаш доглядач ластівок, Невролл, можливо, зможе щось рознюхати про цю справу.\n\nСходиш до нього поговорити, будь ласка?",
        objectives = "Поговори з доглядачем ластівок Невроллом у печері Заралек.",
        completion = "Справді? Ти допоможеш?",
    },
    [72882] = {
        title = "Пташки розлетілися",
        description = "Їх немає! Просто... немає!\n\nЛастівки, Невролл — усі зникли!\n\nІ тепер ти кажеш, що Еффервеста повідомила тобі, що ми запізнюємося з поставкою ластівчиних гнізд для дроґбарів?\n\nЦе справді кепсько, горянине.\n\nЯкщо хочеш допомогти, почни з того, що поверни якомога більше пташок, скільки зможеш знайти.\n\nА я тим часом спробую нашкребти хоч кілька придатних гнізд для дроґбарів.",
        objectives = "Знайди 6 загублених ластівок у печері Заралек.",
        progress = "Якщо Невролл чи дроґбари з'являться раніше, ніж ми знайдемо тих пташок, — нам гаплик!",
        completion = "Ох, як добре, що вдалося відшукати бодай декого з них!",
