    [73031] = {
        title = "Ідол Зимохутрих",
        description = "Дякую тобі за все, що ти зроби$p(в:ла), {name}.\n\nЗанадто легко замкнутися в собі й просто жити так, як завжди.\n\nЗимохутрі повернуться у світ. Ми повернемося на шлях, з якого збилися наші предки.\n\nІ ми ніколи не забудемо твоєї ролі в цьому.\n\nЯ зібрав плем'я та наших нових союзників на святкування. Поговори зі мною, коли будеш готовий почати.",
        objectives = "Поговори з Кранаком, щоб розпочати святкування.",
        progress = "Розпочнімо?",
        completion = "Дякую тобі, друже.",
    },
    [73032] = {
