    [73124] = {
        title = "Звички скарбохрана",
        description = "Дракончики люблять проводити час із сером Прінглі, але через їхнє тупотіння його оселя зносилася.\n\nЧи не принесеш ти йому новий кущик? І раз уже вийдеш, йому б не завадила нова чарівна іграшка. І пахощі.\n\nМи ж не можемо дозволити, щоб його оселя занепала.",
        objectives = "Збери матеріали для оселі сера Прінглі.",
    },
    [73126] = {
        title = "Малювання, рукоділля і купання",
        description = "Наші сьогоднішні заняття з малювання та рукоділля геть вийшли з-під контролю. Один з дракончиків зачарував свій пензлик, а решта взяли з нього приклад. Тепер усе вкрите фарбою.\n\nПриберись, будь ласка, у дитсадку, поки ми відмиваємо фарбу з дракончиків.",
        objectives = "Допоможи прибрати фарбу довкола Садочка «Маленькі Лусочки».",
        completion = "Ти $p(нагодився:нагодилася) саме вчасно, {NAME}. Дякую. Це була робота на трьох.\n\nА тепер час насварити Сера Прінглі за те, що потурає поганій поведінці драконят...",
