    [73130] = {
        title = "Пернаті рунічні кривульки",
        description = "Учорашній урок магічних рун, схоже, перетік і на сьогодні. Дракончики прагнуть вправлятися з рунами де тільки можна, доречно це чи ні.\n\nЦе захоплення обернулося доволі цікавим часом для ігор! Допоможи нам, будь ласка, повернути іграшки на свої місця і розвіяти всі руни, які трапляться тобі на шляху.",
        objectives = "Допоможи навести лад у Яслах «Маленькі Лусочки».",
        progress = "Нам справді варто було б навчити їх рун для чогось кориснішого — скажімо, полірування каменю...\n\nВоно б отут дуже прислужилося.",
        completion = "Дякую за допомогу, {NAME}. Та пісочниця живе власним життям! \n\nМи зробимо все можливе, щоб дракончики більше не розбурхували її рунами.",
    },
    [73131] = {
        title = "Гідні перевдягання",
        description = "{name}! Я змайстрував чудові перевдягання для себе і своїх друзів, але є лише один спосіб дізнатися, чи вони бездоганні.\n\nЗаграймо у схованки! Знайди нас у Валдраккені, і я зрозумію, що над перевдяганнями ще треба попрацювати!",
        objectives = "Знайди Беластразу та її друзів у Валдраккені.",
        completion = "Було весело! А тепер я маю нове натхнення для перевдягань. Негайно піду над ними працювати!\n\nМожеш іти!",
    },
    [73132] = {
        title = "Обшук полиць",
        description = "Привіт, {name}! Хочеш зіграти у гру?\n\nЯ читав про найкращу гру в схованки в усьому Азероті!\n\nДумаю, я можу вдосконалити стратегії, які пропонує ця книжка. Зіграймо разок і перевірмо мою теорію!",
        objectives = "Знайди Залета і його друзів у Валдраккені.",
        completion = "Треба вдосконалити мою стратегію. А ти справді вправно шукаєш!\n\nОбожнюю хованки! Зіграймо ще колись!",
