    [73133] = {
        title = "Затишне маскування",
        description = "<Посідрісс позіхає.>\n\nМені просто не спиться. Краще зіграймо в гру!\n\nДесь там, певно, є зручна схованка. Б'юсь об заклад, ти не знайдеш мене в місті!",
        objectives = "Знайди Посідрісса та його друзів у Валдраккені.",
        completion = "Дякую, {NAME}! Було справді весело!\n\nОт якби ще заснути...",
    },
    [73134] = {
        title = "Вічні витівки",
        description = "А... АПЧХИ!\n\nВибач. Хочеш пограти в хованки? Я знайшов нові місця, де можна сховатися, і хочу пограти!\n\nСподіваюся, моя алергія не наробить клопоту!",
