    [73137] = {
        title = "У погоні за полум'ям",
        description = "«Він чекає на тебе в темряві»?\n\n<Ембертал примружується.>\n\nЯ знаю, де Саркарет.\n\nМені знадобиться твоя допомога, щоб притягнути його до відповідальності. Якщо хочеш, можеш ще побути тут і обнишпорити ці руїни, та, гадаю, зараз у нас є нагальніші справи. Якщо ти готов$p(ий:а) довести це до кінця, тоді йди за мною.\n\nЯ вирушаю на острів Драконячого Черепа.",
        objectives = "Зустрінься з лускокомандиром Ембертал на острові Драконячого Черепа.",
        completion = "Я знала, що ти прийдеш. \n\nДякую, {NAME}.",
    },
    [73139] = {
        title = "Припаси з глибин моря",
        description = "Ми звикли до загроз, що приходять із моря. Та є вороги, яких ніколи не можна підпускати до наших берегів.\n\nНа сході нага наступають на наші пляжі й бухти. Вони принесли із собою припаси. Якби ми могли зменшити тутешню кількість нага й захопити їхні припаси, наші шанси вижити тут зросли б.\n\nОсь план: забери ці припаси з їхніх схованок чи з трупів і вбий їхнього ватажка. На кону людські життя.",
        objectives = "Убивай наг Далекої Луски та збирай їхні припаси.",
        progress = "Припаси вже зібрано?",
        completion = "Дякую за бій із хвилею за хвилею нага. Їхні припаси неабияк допоможуть нашому поселенню — і ми зможемо влаштувати тут дім.",
    },
    [73140] = {
        title = "Розколоти кратер",
        description = "Первісні зайшли в кратер Штормового Розколу. Вони пробуджують елементалів і визискують землю.\n\nЗ ними слід розібратися швидко й рішуче. Прорідь їхні лави. Знищ їхні тотеми. Допоможи нам зробити Заборонені обшири безпечними для драктирів, тускарів і всіх знедолених, хто хоче знову назвати їх своїм домом.",
        objectives = "Убивай Первісних у кратері Штормового Розколу.",
        progress = "Ну що, з Первісними в кратері Штормового Розколу покінчено?",
        completion = "Чудова робота. Їхнім планам тут, у Заборонених обширах, щойно завдано серйозного удару.",
    },
    [73141] = {
        title = "Вічногорючі жарини",
        description = "Тепло й вогонь — постійний клопіт для нас тут, у поселенні. Ми не хочемо спалити все, що принесли, і не любимо збирати плавник на ворожих берегах. Надто ризиковано!\n\nА от Первісні носять трохи власного вогню із собою.\n\nЯкби ти вби$p(в:ла) кількох могутніх Первісних вогню, забрав їхні вічногорючі жарини й приніс ці жарини сюди, ми б добре їх використали.",
        objectives = "Збери вічногорючі жарини з могутніх Первісних вогню в Облоговому Виводку.",
        progress = "Вічногорючі жарини точно допомогли б зігрівати табір цілий рік.",
        completion = "Вони ідеальні! Зігріватимуть нас найхолоднішими ночами. Навіть у найгіршу негоду вони не дадуть згаснути вогнищам, на яких ми куховаримо.\n\nДякую! Нехай тут на тебе завжди чекає теплий прийом.",
    },
    [73142] = {
        title = "Лупцюємо синіх",
        description = "Малігос лишив тут сили, щоб наглядати за нами, поки ми спали. Його вже немає, та його посіпаки досі тут і всім ускладнюють життя.\n\nРозвідники бачили, як вони послуговуються арканними фокусами. Гадаю, ми могли б ужити їх із більшою користю. Піди й набери кілька. Їхня охорона, може, чинитиме опір, та для тебе це ж не проблема, чи не так?\n\n<Сіндретреш пирхає.>\n\nМоже, вони зрозуміють натяк і заберуться.",
        objectives = "Забери арканні фокуси в синьої охорони на землях Старого Вейрну.",
        progress = "Ну що, фокуси зібрано?",
        completion = "Аж від серця відлягло. Дякую. Тепер ми всі спатимемо трохи спокійніше.",
    },
