    [74282] = {
        title = "Справжній дозвіл",
        description = "Важливість цієї експедиції годі переоцінити. Запевняю тебе, усі, хто бере участь, увійдуть в історію... разом зі мною, певна річ!\n\nЯкщо я зроблю бодай одне визначне відкриття, моя наукова спадщина буде забезпечена! Та що ж ми знайдемо? Копію Нелтаріонового підпису? Один із його особистих листів? Не дочекаюся, коли знайду щось, чим можна поділитися з прихильниками. До того ж у мене з'явиться більше прихильників!\n\nЯкщо будеш такий ласкавий і знайдеш мені щось пам'ятне, я гідно тебе винагороджу! Я можу заплатити!",
        objectives = "Знайди запечатаний лист до Нелтаріона.",
        progress = "Вдалося щось знайти?",
        completion = "Яка дивовижна знахідка. Аж голова обертом.\n\nО, і я не дочекаюся, коли напишу про це відкриття й опублікую наші результати. Ми опублікуємо... або загинемо, намагаючись!",
    },
    [74291] = {
        title = "Синій — мій улюблений колір",
        description = "О, Кірі тут! Цікаво, чи вона вже ухвалила рішення.\n\nБудь ласка, розпитай її, що вона думає, {name}.",
        objectives = "Поговори з Кіриґосою, а потім повернися до Лазурових Архівів.",
        completion = "Повертаймося до роботи.",
    },
    [74292] = {
        title = "Таємниці Глибокої Улоговини",
    },
    [74293] = {
        title = "Не забуті",
        description = "Віридія певна, що в цих покоях можуть спати й інші драктири, давно забуті серед реліквій Нелтаріона.",
        objectives = "Звільни драктирів, ув'язнених у стазисі, у Сховищах Зскери.",
        completion = "Серце радіє, коли бачу стільки новоприбулих. Ми зробимо все можливе, щоб допомогти їм освоїтися зі змінами, що сталися за час їхнього сну.\n\nДякую тобі, друже.",
    },
    [74294] = {
        title = "Потрібні тобі ключі",
        description = "Чи можу я тобі довіряти? Це єдині ключі, що в нас є. Якщо ми їх загубимо, то не зможемо відчинити жодних замкнених дверей.\n\nОсь. Бери їх. Скористайся ними на дверях у цих покоях. Ти схожий на героя. Будь сміливий! Розчахни ті двері навстіж! Знайдеш славу або... гм... щось не славне, але все одно неймовірне! Тільки не загинь.\n\nМожливо, знайдемо ще, та для цього доведеться обшукати острів.",
        objectives = "Візьми ключі в Тачі біля Сховищ Зскери.",
        completion = "Гляди, не загуби ті ключі. Я це вже казав? Здається, казав.",
    },
