    [74489] = {
        title = "Жумса",
        description = "Бронзові дракончики бувають необачними, коли прагнуть перемоги, тож стережися часоплинів!\n\n[Стрибок росту]: Перетворює на дорослого й дає підвищену швидкість.\n[Перемотка до сну]: Відновлює 1 снагу, доки вся снага не повернеться.\n[Священна часова лінія]: Скидає перезарядження.",
        objectives = "Допоможи Жусадорму пролетіти крізь кільця.",
    },
    [74490] = {
        title = "Залет у дорозі",
        description = "Сині дракончики намагатимуться зрізати, де тільки зможуть, але будь обережний, переносячись крізь кільця!\n\n[Ривок переносу]: Переносить уперед і робить ривок.\n[Арканне прискорення]: Збільшує прискорення вперед.\n[Прискорене відновлення]: Споживає арканне прискорення й відновлює снагу.",
        objectives = "Допоможи Залтгосу пролетіти крізь кільця.",
        completion = "Гарна робота!",
    },
    [74491] = {
        title = "Посідрісс на старті",
        description = "Зелені дракончики полюбляють короткий сон і ривки швидкості, тож зроби все можливе, щоб не відставати.\n\n[Вітер природи]: Злітає вгору, тоді відновлює 1 снагу.\n[Смарагдова стриманість]: Додає 5 сек до тривалості Вітрів життя.\n[Вітри життя]: Щоразу, коли відновлюєш снагу, робиш ривок уперед.",
        objectives = "Допоможи Посідріссу пролетіти крізь кільця.",
        progress = "Як там перегони?",
