    [74492] = {
        title = "Палка Беластраза",
        description = "Червоні дракончики можуть трохи виходити з-під контролю, тож щасти тобі!\n\n[Рубінове виснаження]: Поступово споживає всю снагу.\n[Багряний політ]: Відновлює всю снагу, щоразу даючи поштовх уперед.\n[Оновлення]: Споживає Багряний політ, скидає перезарядження.",
        objectives = "Допоможи Беластразі пролетіти крізь кільця.",
        progress = "Як там перегони?",
        completion = "Чудова робота!",
    },
    [74493] = {
        title = "Вдруге і навпевно",
        description = "<Вораксіан кілька разів підкидає Дивну Круглу Річ у руках.>\n\nХм, вона добре лягає в долоню, наче для цього й створена. Поговорімо з Верітістразом, може, він знає більше.",
        objectives = "З'ясуй походження Дивної Круглої Речі.",
        progress = "Сподіваймося, цього разу це щось захопливе!",
        completion = "Клянуся Титанами... оце я вклав кіготь у щелепу.\n\nВибач, {NAME}, я посиджу тут трохи з Верітістразом і почекаю, доки він знову буде готовий говорити.\n\nЯкщо знайдеш ще щось цікаве, неодмінно приноси.",
    },
    [74494] = {
        title = "Луска за луску",
        description = "Пробудження старійшини було загрозою, безперечно. Але перш ніж ми вирушимо, я мушу виконати ще одне завдання — інакше ми назавжди втратимо єдину нагоду це зробити.\n\nХай як плем'я закалі відрізняється від калаші, вони все одно вбивці драконів. Їхні знаряддя війни не менш смертельні для нашого роду.\n\nМені потрібен спис, рівний тому, що ми бачили біля старійшини. Знайди найбільший, який зможеш, і принеси мені.",
        objectives = "Здобудь для Сабеліана спис закалійського вбивці драконів.",
        progress = "Зброя джарадинів — мерзенне творіння, та створене воно задля одного-єдиного призначення.",
        completion = "Це єдиний шлях уперед.",
    },
    [74495] = {
        title = "Оповідь про Граксіана",
        description = "Вітаю, {name}, радий тебе бачити.\n\nХочеш долучитися до нас біля вогнища? Гадаю, настав час почути добру історію про давній обсидіановий рій.\n\nКолись я обіцяв тобі й Вораксіану, що розповім історію з вази, яку ти знайш$p(ов:ла) у Сховищах Зскера. Гадаю, той час настав.",
        objectives = "Послухай оповідь про Граксіана.",
        progress = "Завжди радий, {NAME}.",
        completion = "<Верітістраз якийсь час сидить мовчки.>\n\nДякую, що слухаєш, {NAME}. Багато що я забув за своє життя, але не це.\n\nСподіваюся, історія Граксіана подарує обсидіановому рою надію після відкриттів, які ми тут зробили.",
