    [74900] = {
        title = "Камінь отримання: Останнє попередження",
        description = "<Цей камінь отримання досі береже прадавні слова Нелтаріона, мовлені давнім драконячим діалектом.>\n\n<Зміст цього документа неабияк зацікавив би драктирських лускокомандирів.>",
        objectives = "Знайди камінь отримання.",
        progress = "Що тобі вдалося знайти?",
        completion = "Ох... Я пам'ятаю цей тон.\n\nПочинаю думати, що Адамантія перейшла межу — і вже не змогла повернутися назад.\n\nЯ подбаю, щоб переклад цього каменя додали до наших записів.",
    },
    [74901] = {
        title = "Камінь надсилання: Протест",
        description = "<Цей камінь надсилання досі береже прадавні слова, що їх Адамантія мовила Нелтаріонові давнім драконячим діалектом.>\n\n<Зміст цього документа неабияк зацікавив би лускокомандирів.>",
        objectives = "Знайди камінь надсилання.",
        progress = "Що тобі вдалося знайти?",
        completion = "Що ж, приємно бачити, що чорний дракон за нас заступився, хай навіть цього було замало й запізно.\n\nЦікаво, що воно таке — цей «Аберрус». Якщо це ще одне місце, де тримали драктирів, нам, можливо, доведеться його знайти.\n\nЯ додам це до перекладених записів. Раджу заглядати в них, коли знаходитимеш нові камені.",
    },
    [74902] = {
        title = "Камінь надсилання: Перший звіт",
        description = "<Цей камінь надсилання досі береже прадавні слова, що їх Адамантія мовила Нелтаріонові давнім драконячим діалектом.>\n\n<Зміст цього документа неабияк зацікавив би лускокомандирів.>",
        objectives = "Знайди камінь надсилання.",
        progress = "Що тобі вдалося знайти?",
        completion = "Вони знали, що ми не зламані.\n\nВОНИ ЗНАЛИ.\n\nГадаю, ми й самі це знали, але читати це... наче ще більше оливи у вогнище.\n\nІ все ж дякую тобі за цю знахідку. Я подбаю, щоб її переклали для всіх і додали до записів.",
    },
    [74903] = {
        title = "Камінь надсилання: Бранка",
        description = "<Цей камінь надсилання досі береже прадавні слова, що їх Адамантія мовила Нелтаріонові давнім драконячим діалектом.>\n\n<Зміст цього документа неабияк зацікавив би лускокомандирів.>",
        objectives = "Знайди камінь надсилання.",
        progress = "Що тобі вдалося знайти?",
        completion = "Ха. Якщо це правда, то Расзаґет не спала весь той час, поки ми були в стазисі.\n\nЗрозуміло, чому вона так оскаженіла. Мені й досі не до вподоби ні вона, ні її методи, але будь-хто, кого замкнули на десять чи двадцять тисяч років у ямі, куди майже не сягає світло, зрештою збожеволіє.\n\nЯ подбаю, щоб перекладену версію додали до записів, які ми передаємо з рук у руки. Дякую за це, {NAME}.",
    },
    [74905] = {
        title = "Дослідники під обстрілом",
    },
    [74906] = {
        title = "Дослідники під обстрілом",
    },
    [74908] = {
        title = "Нові пригоди",
        description = "Каталогістка Даела прибула сюди, щоб дослідити місця чудес і таємниць. Лігво Небесного Лиса й Кальдера Цілителів видаються особливо багатообіцяльними.\n\nЯкщо виконаєш її завдання, сьогодні відкриються її доручення посланця. Доручення посланця інших фракцій ти зможеш відкрити завтра.",
        objectives = "Поговори з каталогісткою Даелою.",
        completion = "Захопливо! Мусимо мудро спланувати подальші кроки. Я дам тобі докладні настанови.",
    },
    [74909] = {
        title = "Нові улови",
        description = "Турик прибув сюди, щоб дослідити багатства моря довкола Забороненого Берега від імені тускарів Іскаари.\n\nЯкщо виконаєш це завдання, сьогодні відкриються його доручення посланця. Доручення посланця інших фракцій ти зможеш відкрити завтра.",
        objectives = "Поговори з Туриком.",
        completion = "Сьогодні риба клює як ніколи!",
    },
    [74910] = {
        title = "Нові вороги",
        description = "Хранителька оповідей Ашех прибула сюди, щоб вистежити ворогів маруків.\n\nЯкщо виконаєш це завдання, сьогодні відкриються її доручення посланця. Доручення посланця інших фракцій ти зможеш відкрити завтра.",
        objectives = "Поговори з хранителькою оповідей Ашех.",
        completion = "Дай-но мені зважити сили наших ворогів. Попереду багато роботи.",
    },
    [74911] = {
        title = "Нові обрії",
        description = "Краксус уособлює тут, на Забороненому Березі, силу Валдраккенської угоди.\n\nЯкщо виконаєш це завдання, сьогодні відкриються його доручення посланця. Доручення посланця інших фракцій ти зможеш відкрити завтра.",
        objectives = "Поговори з Краксусом.",
        completion = "Вітаю на Заборонених Обширах, друже!",
    },
    [74912] = {
        title = "Спадок Нелтаріона",
        description = "<Коли ти вдивляєшся у тріснутий самоцвіт титанів, у твоїй голові відлунює голос.>\n\n{name}! Це Ноздорму. \n\nНастав час виправдати спадок твого творця, Нелтаріона. \n\nУ тебе в руках — важлива частина артефакта, яким Нелтаріон колись керував тобою і всіма драктирами.\n\nЗустрінься зі мною у Валдраккені. Нам багато про що треба поговорити.",
        objectives = "Зустрінься з Ноздорму у Валдраккені.",
        completion = "Дякую за візит. Я вже давно готуюся до цієї миті.",
    },
    [74913] = {
        title = "Спогади про артефакт",
        description = "Ембертал допомогла мені знайти Скріплювача Клятв. Це був той самий артефакт, яким Нелтаріон керував усіма вами.\n\nЯ нишпорив по часовій лінії, щоб з'ясувати, як його було створено, і викувати йому противагу, що захистить твій рід.\n\nЦей самоцвіт, що ти його $p(здобув:здобула), — саме той ключ, якого мені бракувало, щоб просунути мої дослідження далі.\n\nНаступного разу ми зустрінемося в Печері Заралек, де ти колись $p(бився:билася) за зламаного Скріплювача Клятв.\n\nСаме там ми знайдемо таємниці, потрібні, щоб викувати твою власну зброю проти тиранії.",
        objectives = "Зустрінься з Ноздорму в Печері Заралек.",
        progress = "Погляньмо, що ми знайдемо в печерах.",
        completion = "У твоїх руках — спогади про те, як викувати противагу Скріплювачеві Клятв.\n\nЧас тобі ступити на цей шлях.",
    },
    [74923] = {
        title = "Щоб створити артефакт, потрібне ціле село",
        description = "Тепер ти маєш вирушити й шукати допомогу, щоб виготовити ключові складники для кування нової рукавиці.\n\nЕсенцію Порядку зазвичай нелегко знайти, але здобуті тобою спогади дозволять тобі віднаходити її в багатьох місцях.\n\nЦя нова рукавиця наснажуватиме твоїх союзників і твою спільноту... а отже, тобі доведеться покластися на інших, щоб вони тобі в цьому допомогли.\n\nВізьми здобуті спогади й навчи з їхньою допомогою інших виготовляти ці частини.",
        progress = "Вдалося зібрати всі предмети? Щоб виготовити всі частини, тобі доведеться попросити допомоги в інших шукачів пригод.",
        completion = "Чудова робота! Скільки ж зусиль пішло на виготовлення кожної з цих частин.\n\nТепер треба відшукати останню складову, що з'єднає все докупи.\n\nЕсенцію першого Аспекта чорних драконів.",
    },
    [74924] = {
        title = "Назз'уро, Звільнена Спадщина",
        description = "Завдяки моїм дослідженням я знайшов останню частину, що зробить цей артефакт справжньою противагою Скріплювачу Клятв.\n\nЕсенцію Нелтаріона.\n\nСаме тут я нарешті можу допомогти драктирам. Ми вирушимо до Виру, щоб побачити його останні миті.\n\nЗ його есенцією ми завершимо створення твого артефакта, Назз'уро, Звільненої Спадщини.\n\nПоговори зі мною, коли будеш $p(готовий:готова).",
        objectives = "Поговори з Ноздорму, щоб вирушити до Виру й побачити поразку Нелтаріона.",
    },
    [74925] = {
        title = "Політ над кальдерою — навпаки",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [74939] = {
        title = "Сірчана гонка",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
    },
    [74942] = {
        title = "Бруд лишається там, де ти б'єш слизів",
        description = "Ти бачив це? Деякі слизи лишають по собі купки бруду. Гм...\n\nМеллі майструє всіляке з найрізноманітніших речей. Гадаєш, вона могла б використати цей бруд, щоб допомогти Темпо? Б'юся об заклад, що могла б.",
        objectives = "Назбирай часового бруду.",
        progress = "Бруд-час — саме раз! О, та мені сьогодні римується як ніколи.",
