    [75165] = {
        title = "Потрібні концентровані первісні фокуси",
        description = "Великі фракції Драконових островів прагнуть покращити спорядження своїх воїнів.\n\nЧи не маєш ти, бува, концентрованих первісних фокусів, які був би готовий пожертвувати на цю справу? Фракція, якій ти пожертвуєш, неодмінно це відзначить.",
        progress = "Великі фракції Драконових островів прагнуть покращити спорядження своїх воїнів. \n\nЧи не маєш ти, бува, концентрованих первісних фокусів, які був би готовий пожертвувати на цю справу? Фракція, якій ти пожертвуєш, неодмінно це відзначить.\nКонцентрований Первісний Зосередник (1)",
        completion = "Дякую!\n\nСкажи, якій із великих фракцій ти бажаєш пожертвувати цей фокус, і я подбаю, щоб там почули про твою щедрість.",
    },
    [75166] = {
        title = "Потрібно багато первісних фокусів",
        description = "Великі фракції Драконових островів прагнуть покращити спорядження своїх воїнів.\n\nЧи не маєш ти, бува, первісних фокусів, які був би готовий пожертвувати на цю справу? Фракція, якій ти пожертвуєш, неодмінно це відзначить.",
        progress = "Великі фракції Драконових островів прагнуть покращити спорядження своїх воїнів. \n\nЧи не маєш ти, бува, первісних фокусів, які був би готовий пожертвувати на цю справу? Фракція, якій ти пожертвуєш, неодмінно це відзначить.\nПервісний Фокус (10)",
        completion = "Дякую!\n\nСкажи, якій із великих фракцій ти бажаєш пожертвувати ці фокуси, і я подбаю, щоб там почули про твою щедрість.",
