    [75168] = {
        title = "Контроль повітря",
        description = "Ми ніколи не просунемося вперед, поки ці тінепломінні драки притискають нас із повітря.\n\nПіднімися туди й позбивай їх із небес.",
        objectives = "Убий первісних нічних пломенів або збий їх із неба Вихровим ривком.",
        progress = "Не лише вони вміють літати.",
        completion = "Небеса вже чистішають.",
    },
    [75181] = {
        title = "Добровільні пожежники",
        description = "Ми мусимо стримати пожежі, які спричиняють ці ритуали.\n\nМи надто далеко від річки, щоб скористатися її водою, та, на щастя, у нас є двоє... добровольців... з-поза рівнин, які запевняють, що можуть допомогти. Їм потрібна ще одна пара рук.\n\nПрошу, знайди ґобліна й ґнома. Я ціную їхню допомогу, та їм потрібен хтось третій, щоб ними керувати.",
        objectives = "Скористайся водяним елементалем, щоб погасити пожежі в Таборі насичення.",
        progress = "Хутко, поки вогонь не розповзся.",
        completion = "Корисний трюк, що й казати. Тепер би ще ті двоє хоч трохи порозумілися.",
    },
    [75182] = {
        title = "Викрадення мамонта",
        description = "Джарадини навантажили мамонта здобиччю своєї праці, щоб відправити її Фіракові.\n\nПереправ той вантаж до нас. Нам згодяться будь-які припаси, які вони зібрали.",
        objectives = "Осідлай перевантаженого мамонта й приведи його до своїх лав.",
        progress = "Його важко проґавити. Мамонти, зрештою, чималенькі.",
        completion = "Чудово! Це залишить у їхніх планах вм'ятину завбільшки з мамонта.",
    },
    [75189] = {
        title = "У гурті безпечніше",
        description = "Час нам приєднатися до решти вцілілих. Інші казали, що король Ґреймейн і його королівська варта зараз трохи південніше звідси.",
        objectives = "Поговори з королем Ґенном Ґреймейном у Військовому кварталі.",
        completion = "Добре, що ти тут. Якщо ми, гілнеасці, триматимемося разом, то ще можемо здолати цього жахливого ворога.",
    },
    [75190] = {
        title = "Абель напоготові",
        description = "Майже всі ми дісталися сюди живими... але воргени є й по цей бік міста.\n\nЩойно переконаємося, що всі на місці, рушимо далі на південь.\n\nДо речі, хтось про тебе питав. Монах, Тодд Абель: казав, що мусить із тобою поговорити. Видавався дуже стривоженим.",
        objectives = "Поговори з Тоддом Абелем у Військовому кварталі.",
        completion = "Добре, що тобі вдалося безпечно сюди дістатися.",
    },
    [75200] = {
        title = "Згуба глибдерів",
    },
    [75203] = {
        title = "Відсутні друзі",
        description = "Я непокоюся за нашу королеву.\n\nАлекстраза вже певний час тому пішла, щоб зібратися з думками, і досі не повернулася. Справжньої причини для тривоги немає, але після всього, що сталося, я не можу не боятися за її благополуччя.\n\nПрошу, заспокой розум старого дракона й переконайся, що з нею все гаразд.",
        objectives = "Провідай Алекстразу.",
    },
    [75221] = {
        title = "Знайди монету Rumble",
        description = "Щоб скористатися цим ігровим автоматом, тобі потрібна монета Rumble.\n\nПо всіх Драконових островах поховано чимало таких монет. Та про це ми поговоримо згодом.\n\nОдну монету я заховав тут, у «Смаженому барані». Знайдеш її — вона твоя, $p(друже:подруго).\n\nВкинь цю монету Rumble в автомат Rumble і дивись, як починається веселощі!",
        progress = "<Перед тобою стоїть автомат Warcraft Rumble. Маленька табличка повідомляє:>\n\nЩоб зіграти, вкиньте монету Rumble.",
        completion = "<Щойно ти вкидаєш монету, веселий автоматик гуркоче й дзеленчить.\n\nТи отримуєш приз!>",
    },
    [75222] = {
        title = "Панцирний вогонь",
