    [75223] = {
        title = "Мініатюри Warcraft Rumble: новий вигляд!",
        description = "<Ти помічаєш послання, видряпане на фользі.>\n\nЦю фольгу Rumble можна використати біля автомата Warcraft Rumble. Іди і здобудь новий вигляд для однієї зі своїх мініатюр!",
        completion = "<В автоматі Warcraft Rumble є люк. Він якраз такого розміру, щоб вкласти іграшкову мініатюру й фольгу Rumble.>",
    },
    [75228] = {
        title = "Розчищення завалів",
        description = "<Схоже на гарне місце.>",
    },
    [75230] = {
        title = "Примиренні дисиденти",
        description = "Я сподіваюся, {name}, що наша праця задля розуміння бунтівників дозволить нам знайти шлях до миру.\n\nМене непокоїть ось що: якщо ми не зможемо порозумітися з Белафон, інші бунтівники можуть вважати її мученицею за справу.\n\nЩо б не сталося, я вдячна тобі за допомогу впродовж усього цього повстання.",
        objectives = "Вислухай розмову Алекстрази з підбурювачкою Белафон.",
        progress = "Сподіваюся, Белафон зможе побачити шлях уперед для драконороду.",
        completion = "Ця криза привела нас до кращого розуміння одне одного, а мене змусила стати кращою провідницею.\n\nІ без твоєї допомоги ми не знайшли б шляху до миру. {NAME}, дякую тобі.",
    },
    [75232] = {
        title = "Речі полеглого",
        description = "<Ти загортаєш речі Шерідона у вузол і складаєш їх у свій наплічник, щоб повернути людям у таборі.>",
        objectives = "Поверни речі Шерідона Гастла землецілительці Нарврі в таборі Експедиції Драконячої Луски в Печері Заралек.",
        completion = "Ох... Шерідон... Він заплатив за наші життя своїм власним. Я... Я подбаю, щоб його родина це отримала.\n\nЯ позначу місце, де лежить тіло, — попросимо Руперта забрати його, щоб поховати як належить.\n\nДякую тобі. Прошу, візьми оце.",
    },
    [75233] = {
        title = "Плоть на кістку",
        description = "Ми знайшли Скаттоґа біля печери на півночі, поряд із гидкими павуками. Схоже, його шкіра перетворюється на кістку.\n\nЯ можу його зцілити, але мені потрібна отрута того, хто його вкусив. Прошу, допоможи.",
        objectives = "Знайди отруту звіра, що вкусив Скаттоґа.",
        progress = "Прошу, поквапся. Він уже майже статуя.",
        completion = "Цього має вистачити. Погляньмо, чи подіє.",
    },
    [75234] = {
        title = "Дряпни й понюхай",
