    [75647] = {
        title = "Вшануй полум'я",
        description = "Свято літнього сонцестояння — це час ушановувати стихії. Стихія вогню розпалює пристрасть у кожному з нас. Часто ця пристрасть виливається в агресивні вчинки. Та тут, у цьому краю, ми спрямовуємо свою пристрасть на шанобу.\n\nМи вшануємо полум'я, як велить традиція. Чи вшануєш полум'я разом із нами, {name}?",
        objectives = "Вшануй Багаття Літнього Свята на Забороненому Березі.",
        completion = "Вшануй полум'я Заборонених Обширів.",
    },
    [75650] = {
        title = "Вшануй полум'я",
        description = "Свято літнього сонцестояння — це час ушановувати стихії. Стихія вогню розпалює пристрасть у кожному з нас. Часто ця пристрасть виливається в агресивні вчинки. Та тут, у цьому краю, ми спрямовуємо свою пристрасть на шанобу.\n\nМи вшануємо полум'я, як велить традиція. Чи вшануєш полум'я разом із нами, {name}?",
        objectives = "Вшануй Багаття Літнього Свята в Печері Заралек.",
        completion = "Вшануй полум'я Печери Заралек.",
    },
    [75657] = {
        title = "Трійця, загублена в часі",
        description = "У нас є малесенька проблема, з якою мені б знадобилася твоя допомога. Але вона... непроста.\n\nДеякий час тому король Варіан Рінн був у гладіаторській трійці разом із Броллом Ведмежим Плащем і Валірою Сангвінар. Ці троє щойно з'явилися на так званому \"Полі Лютості\" і не лише приймають усіх охочих позмагатися, а й перемагають їх! Вони не повернуться крізь наші портали, доки не програють.\n\nЯк гадаєш, чи зміг би ти знайти кількох друзів і здолати їх? Якщо тобі це вдасться, ми зможемо переконати їх повернутися, я цього певен!",
        objectives = "Здолай Валіру, Бролла й Ло'Ґоша.",
        completion = "Гм. Я й не знав, що в розкладі була така група. Ні про золотисту іскристу піротехніку.\n\nАле, гадаю, перемога твоя, тож ось, тримай.",
    },
    [75660] = {
        title = "Кінець їхньої варти",
    },
    [75661] = {
        title = "Збір цілющих кристалів",
    },
    [75662] = {
        title = "Гонка до фінішу",
        description = "Ти схожий на того, хто любить добрі перегони равликів!\n\nА що робить перегони равликів добрими, питаєш ти? Кожен равлик повинен мати шанс на перемогу!\n\nІ часом равликам може знадобитися невеличка допомога.\n\nЯкщо взяти в кухаря торбинку ласощів і кинути її равликові на шляху, це його розворушить.\n\nМожемо підштовхнути Сором'язливого до перемоги?",
        objectives = "Допоможи Сором'язливому виграти перегони.",
        progress = "Твій равлик уже виграв перегони?",
        completion = "Оце була знаменита перемога! Гадаю, тобі варто стати новим тренером Сором'язливого!",
    },
    [75663] = {
        title = "Невгамовна мука",
    },
    [75664] = {
        title = "Розладнані кристали",
    },
    [75665] = {
        title = "Гідний союзник: ніффени Лоамма",
        description = "Джарадини, дратири й дракони! Ой леле! Просто неможливо не занюхати небезпеку в цих печерах. Нам би дуже не завадила збройна підмога.\n\nТи допоможеш нам, а я подбаю, щоб наша рідня віддячила тобі! У нас купа добрих припасів... для гідних клієнтів.\n\nТо як? Вирушиш туди й закопаєш нашу конкуренцію?",
        objectives = "Допомагай ніффенам та їхнім союзникам по всій Печері Заралек.",
        completion = "Ти на стільки ж ближче до того, щоб унюхати справжнє добро. \n\nДякую, друже.",
    },
