    [75720] = {
        title = "Зробимо обмін?",
        description = "Гей, верхоземцю!\n\nЧув, ти любиш допомагати. Може, допоможеш і мені?\n\nМені треба переслати кілька пакунків до Валдраккена. Якщо не заглядатимеш усередину й не ставитимеш питань — я гідно тобі віддячу.\n\nЗазирни до мене, коли будеш у Лоаммі. Домовимося!\n\nТвій новий друг, Понзо.",
        objectives = "Поговори з Понзо в Лоаммі.",
        completion = "Я чую на тобі запах свого листа. Готов$p(ий:а) допомогти?",
    },
    [75721] = {
        title = "Основи обміну",
        description = "Ось що мені від тебе потрібно.\n\nМій приятель Каянн подався аж до Валдраккена. Він чекає на мою посилку. Можеш доставити її йому?\n\nТільки без питань. Не зазирай, не нюхай, не куштуй. Це лише для носа Каянна!\n\nЯкщо тебе це влаштовує — вирушай у дорогу. Звісно ж, із моєю подякою!",
        objectives = "Достав посилку Понзо Каянну у Валдраккені.",
        completion = "Я впізнаю пакунок Понзо, щойно його нюхну!\n\nДякую за доставку нагору — шлях був неблизький! Ось дещо, на що Понзо залюбки поміняється.",
    },
    [75722] = {
        title = "Торбинка золота",
        description = "Вітаю, {name}!\n\nЯ чула, що ти нам допомагаєш! Добрі вчинки слід винагороджувати — і в мене є для тебе дещо особливе! Може, зустрінемося в Лоаммі?\n\nТак тримати,\n\nМімуп",
        objectives = "Поговори з Мімуп у Лоаммі.",
        completion = "Ми завжди будемо тобі вдячні!",
    },
    [75723] = {
        title = "Спостереження за драками в печерах",
        description = "О, привіт, верхоземцю!\n\nКажуть, ти добряче нам допомагаєш! У нас є для тебе дещо натомість. Знайди мене в Лоаммі, і я тобі це передам!\n\nЗ повагою,\nГарлоу Марл",
        objectives = "Поговори з Гарлоу Марл у Лоаммі.",
        completion = "Нам пощастило, що ти поруч!",
    },
    [75724] = {
        title = "Як уміють ніффени",
        description = "Привіт, {name}!\n\nМи хочемо подякувати тобі за всю допомогу, яку ти нам надав. Так і має бути!\n\nЗустрінься зі мною в Лоаммі, і я навчу тебе копати так, як це робимо ми, ніффени!\n\nЩиро твоя,\nМімуп",
        objectives = "Поговори з Мімуп у Лоаммі.",
        completion = "Просто вдягни ці рукавиці, занур їх у землю, розкрий носа — і бум!\n\nЛоамм можна винюхати з будь-якого куточка Печери Заралек.\n\nСекрет — у кігтях! Він завжди був у кігтях!",
    },
    [75725] = {
        title = "На трасу",
        description = "Гей, $p(чемпіоне:чемпіонко)!\n\nУ нас для тебе новенька золота нагода. Перегони равликів! Один із найдинамічніших видів спорту на іграх!\n\nПонзо казав, що тобі буде цікаво. Назвав тебе справжнім завзятцем!\n\nТож гайда! Біжи на трасу в Гліммерогу!\n\nДо зустрічі там,\nБріґґул",
        objectives = "Поговори з Бріґґулом у Гліммерогу.",
    },
    [75726] = {
        title = "Спітніла броня",
        description = "О, привіт, друже!\n\nЧутки про твою незмінну підтримку вже розходяться! Ми знайшли броню, яка може стати тобі в пригоді, — на знак подяки за всі твої клопоти.\n\nОбов'язково завітай до Лоамма, щоб ми тебе спорядили.\n\nЗ повагою,\nГарлоу Марл",
    },
    [75727] = {
        title = "Найсмердючіша накидка",
        description = "Вітаю, {name}!\n\nТи знай собі робиш нам дивовижні послуги, чи не так? Повертайся до Лоамма по особливу нагороду!\n\nЩиро твоя,\nМімуп",
        objectives = "Поговори з Мімуп у Лоаммі.",
        completion = "Ось вона — зроблена власноруч і напахчена власноніс!",
    },
    [75728] = {
        title = "Обмін на брили",
        description = "О, привіт, верхоземцю! Мені знову не завадила б твоя допомога.\n\nМені до вподоби твоя манера торгуватися. Але оці цеглини? Вони нікчемні! Ось брили — це справжня річ!\n\nЗазирни до мене в Лоамм, і я розкажу тобі всі подробиці.\n\nПонзо",
        objectives = "Поговори з Понзо в Лоаммі.",
        completion = "Сподіваюся, ти в добрій формі. Вони геть не легенькі!",
    },
    [75729] = {
        title = "Налаштування на Спостерігача",
        description = "Уявляєш, колись це була обсерваторія? За нашими записами, тутешні драконіди стежили за небесними тілами, намагаючись передбачити майбутнє.\n\nІ як їм це вдавалося, по-твоєму?\n\nЯ вловлюю часткову сигнатуру, що збігається з тим часовим вікном, яке ми шукаємо. Надягни Технопровидці й спробуй визначити джерела, щоб ми могли точно налаштуватися.",
        objectives = "Проведи техноворожіння, щоб виявити три реліквії налаштування.",
        progress = "Без тих реліквій налаштування нам не розгадати цієї таємниці, {NAME}.",
        completion = "Ага! Давай-но сюди свої Технопровидці — я їх відкалібрую.",
    },
    [75730] = {
        title = "Спостереження за повзучим драконом",
        description = "О, вітаю!\n\nТут подейкують, що ти й далі нас підтримуєш, тож ми приготували для тебе дещо. Зустрінься зі мною в Лоаммі, і я тобі це передам!\n\nЗ найкращими побажаннями,\nГарлоу Марл",
        objectives = "Поговори з Гарлоу Марл у Лоаммі.",
        completion = "Нам пощастило, що ти поруч!",
    },
    [75731] = {
        title = "Запашні чоботи",
        description = "О, вітаю!\n\nЧутка про твою незмінну підтримку розійшлася всюди. Ми знайшли броню, яка може тобі знадобитися. Завітай до мене в Лоамм, і ми подивимося, чи буде вона корисною!\n\nЗ найкращими побажаннями,\nГарлоу Марл",
        objectives = "Поговори з Гарлоу Марл у Лоаммі.",
    },
    [75741] = {
        title = "Купа валунів",
        description = "Гей, верховинцю!\n\nЯ чув, ти розповідаєш людям, ніби я погано до тебе ставився.\n\nЦе неправда, але мені сказали бути добрішим до тебе, бо ти стільки для нас зробив.\n\nКористуюся тобою? Та я ж просто даю тобі чесну роботу!\n\nЩоб порадувати тебе й інших, дам тобі трохи валунів.\n\nЗнайди мене в Лоаммі,\nПонзо",
        objectives = "Поговори з Понзо в Лоаммі.",
        completion = "Не забудь сказати Мімуп, що я був до тебе добрим, чуєш?",
    },
    [75742] = {
        title = "Шоломи драконів",
        description = "Привіт!\n\nЧутка про твою незмінну підтримку розійшлася всюди.\n\nМаємо для тебе дещо. Зустрінься зі мною в Лоаммі, і я тобі це передам!\n\nЗ найкращими побажаннями,\nГарлоу Марл",
        objectives = "Поговори з Гарлоу Марл у Лоаммі.",
        completion = "Пощастило нам, що ти поруч.",
    },
    [75744] = {
        title = "Знак нашої вдячності",
        description = "Вітаю!\n\nЗа всю допомогу, яку ти нам надав, ми вирішили, що буде справедливо віддячити тобі.\n\nЗустрінься зі мною в Лоаммі. У нас є нагорода, яку ми прагнемо тобі вручити.\n\nЩиро твій,\nМімуп",
        objectives = "Поговори з Мімуп у Лоаммі.",
        completion = "Дякую за все, верхоземцю!",
    },
    [75750] = {
        title = "Хіба вони не прекрасні?",
        objectives = "Перемож Шинмуру в бою улюбленців.",
    },
    [75765] = {
        title = "Рідке мистецтво",
        description = "<Глиняний горщик, наповнений... багном?\n\nСхоже, він ніффенського походження. Можливо, його шукає хтось із мешканців Лоамма!>",
        objectives = "Поверни глиняний горщик його власникові в Лоаммі.",
        progress = "Ой, це ж...?",
        completion = "Це ж мій улюблений горщик для шлікеру!\n\nЯ можу робити шлікер у будь-якому горщику, але цей — один із перших, зліплених із особливих осадів, накопаних власними кігтями.\n\nВін сентиментальний... І СЕДИМЕНТАЛЬНИЙ!",
    },
    [75766] = {
        title = "Рубін у необробленому вигляді",
        description = "<Прекрасний рубін в оправі з вишуканого золота лежить у скриньці драконічного походження.\n\nЮвелірка з Лоамма залюбки погляне на це.>",
        objectives = "Достав Мерехтливий Драконовий Самоцвіт Фаніллі в Лоаммі.",
        progress = "Він ТАКИЙ блискучий!!",
        completion = "Яка краса! Це дракони зробили? Він такий червоний і мерехтливий!\n\nДякую, {NAME}!",
    },
    [75767] = {
        title = "Веселун",
        description = "<Геть мокрий тотем горлоків лежить на підлозі печери. Як він узагалі сюди потрапив?\n\nНіффени обожнюють такі речі. Можливо, хтось у Лоаммі забере його в тебе.>",
        objectives = "Знайди новий дім для Просяклого Тотема в Лоаммі.",
        progress = "Мені якраз бракувало підтанцьовки!",
        completion = "<Ніффен потужно обнюхує тотем.>\n\nВін пахне рибою! Чудово!\n\nЗ нього вийде відмінний викидайло для моїх виступів. Гадаю, я назву його... Свистунчик!",
    },
    [75768] = {
        title = "Щасливе каченя",
        description = "<Ти знаходиш маленьке іграшкове каченя.\n\nВоно трохи нагадує тобі ластівок Лоамма. Можливо, воно сподобається Циннаму?>",
        objectives = "Віддай Пернатого Друга Циннаму в Лоаммі.",
        progress = "Це мені?",
        completion = "Ого! Дякую, {NAME}.\n\nОскільки я тепер новий головний доглядач ластівок, мені якраз потрібен підмайстер!",
    },
    [75769] = {
        title = "Порожнє полотно",
        description = "<Викинута картина, вкрита пилом, лежить на підлозі печери.\n\nМожливо, комусь у Лоаммі вона знадобиться?>",
        objectives = "Віддай Натягнуте Полотно котромусь ніффену в Лоаммі.",
        progress = "Звідки тобі відомо, що мені кортіло спробувати свій ніс у малюванні запахами?",
        completion = "Новісіньке полотно! Ідеально, щоб вправлятися в малюванні запахами.\n\nЗараз воно пахне так... порожньо! Дякую!",
    },
    [75770] = {
        title = "Келих ігристого",
        description = "<Ти знаходиш сяйливе синє зілля невизначеного походження.\n\nМожливо, алхімістка з Лоамма захоче на нього поглянути?>",
        objectives = "Віднеси Булькітливий Еліксир Місті в Лоаммі.",
        progress = "Гм... Треба буде провести аналіз!",
        completion = "Це вельми цікаво.\n\nДоведеться залучити найкращі носи Лоамма, щоб визначити, що ж це таке.\n\nДякую, {NAME}!",
    },
    [75771] = {
        title = "Запах знайомих пахощів",
        description = "<Ти знаходиш якісь пахощі зі знайомим ароматом, але ніяк не можеш пригадати, де його чув.\n\nЦитрос неодмінно захоче їх понюхати.>",
        objectives = "Віднеси Загадкові Пахощі Цитросу в Лоаммі.",
        progress = "Оце так! Ну й міцнющі пахощі!",
        completion = "Це не пахне ніффенами!\n\nАле й поганим не пахне, аж ніяк!\n\nЯкщо ти не проти, можна мені нюхнути ближче?",
    },
    [75772] = {
        title = "Загублена фляга",
        description = "<На полиці в печері лежить невелика фляга, обтягнута шкірою.\n\nМожливо, хтось її загубив.>",
        objectives = "Знайди власника фляги, обтягнутої шкірою.",
        progress = "Ну, вона не моя, але я охоче її заберу!",
        completion = "Ця фляга нізащо не могла належати комусь із Лоамма. Такої шкіри мені ще не траплялося.\n\nЯкщо ти не проти, можна я обнюхаю її зблизька? Може, вдасться перейняти деякі з цих технік!",
    },
    [75773] = {
        title = "Маленька порожня книжка",
        description = "<Ти знаходиш книгу, списану драконічними письменами, і більше нічим.\n\nМожливо, хтось у Лоаммі допоможе тобі її розшифрувати?>",
        objectives = "Віднеси книгу назад до Лоамма.",
        progress = "Тобто як — прочитати її? Вона ж порожня, смішно й казати!",
        completion = "Тут нічого не написано! Пахне самим лише чистим папером!\n\nЯ не можу це прочитати, якщо нема чого нюхати, верхоземцю.\n\nІ все ж, як мило — принести мені чистого записника.",
