    [75831] = {
        title = "Вигідний обмін",
        description = "Вітаю, $p(друже:подруго)!\n\nЯ чув, тобі трапилося дещо, що могло б мене зацікавити.\n\nДуже пахуча дещиця — я б охоче на неї поглянув.\n\nНу, знаєш, просто щоб переконатися, чи варта вона мого часу.\n\nТвій надзвичайно люб'язний друг,\n\nПонзо",
    },
    [75833] = {
        title = "Прибути до торгової застави",
        description = "<Зблиск віддаленого предмета привертає твою увагу. Ти раптом згадуєш, що маєш забрати кошти для торгової застави T&W.>",
        objectives = "Повернися до торгової застави, щоб забрати свою Торговельну плату зі схованки колекціонера.",
        progress = "Кошти за цей місяць уже в тебе?",
        completion = "Сподіваюся, цьогомісячна добірка нових та екзотичних товарів припаде тобі до смаку, {NAME}.",
    },
    [75834] = {
        title = "Дослідниця Мардеї",
        objectives = "Перемож дослідницю Мардеї в бою улюбленців.",
    },
    [75835] = {
