    [76030] = {
        title = "Звивисті польоти",
        description = "О, привіт!\n\nТут подейкують, що ми й надалі маємо твою підтримку, тож приготували для тебе дещо. Зустрінься зі мною в Лоаммі, і я тобі це передам!\n\nЗ найкращими побажаннями,\nГарлоу Марл",
        objectives = "Поговори з Гарлоу Марл у Лоаммі.",
        completion = "Нам пощастило, що ти з нами!",
    },
    [76032] = {
        title = "Приховане у смітті",
        description = "<Ця статуя дракона схожа на інші, що трапляються в цій місцевості, але вся вкрита фарбою.\n\nВитрішкуваті очі, лінії смороду, вуса й усілякі інші грубі малюнки оздоблюють цей загалом величний камінь. Фарба здається старою і місцями облущується, але вона не така давня, як сама статуя.\n\nРоска захоче на це поглянути!>",
        objectives = "Обережно розкопай споганену статую дракона.",
        progress = "Нема нічого кращого за вулканічну породу, еге ж, {NAME}? Ніколи не знаєш, що знайдеш!",
