    [76361] = {
        title = "Тиждень моди",
        description = "Ах, {class:v}, наближається Випробування стилю.\n\nВбрання, креативність, елегантність цього випробування — справді видовище, варте уваги.\n\nПоговори з посланцем Випробування стилю, щоб дізнатися більше про цю подію.\n\nЛише попереджаю: із цими посланцями буває... непросто мати справу.",
        objectives = "Поговори з Посланцем Випробування Стилю.",
        completion = "Гадаєш, тобі справді до снаги Випробування стилю?\n\nУ цьому вбранні?",
    },
    [76362] = {
        title = "Череп із рогами",
        description = "<Попри довкілля, цей череп, схоже, не зіпсований Скверною.\n\nКоли ти підносиш до нього руку, то відчуваєш, як від нього віє спокоєм.\n\nСоридормі захоче це побачити.>",
        objectives = "Принеси Рогатий Череп Соридормі в Резервуарі Тіргольда.",
        completion = "<Соридормі обережно підносить череп до рівня очей.>\n\nКажеш, це знайшлося біля спаплюженого Скверною Іллідана?\n\nПрипускаю, це Малфуріон.\n\nА ми ще думали, що їхні родинні негаразди в нашій часовій лінії — це погано.",
    },
