    [76379] = {
        title = "Мурлок і дракон заходять у часовий розлом...",
        description = "Ґрурґуґлґ.\n\nҐууґлрллґгулґрґл ґруґлл ґур. Мурґлллґллруґл ґуґлрллґ мурґу ґруґґуллґл. Мурґлґуррррр ґурґлл Ґурлґул, ґуруууурллґр ґурґулл ґурґлллґлрл.\n\nАрґурґулул?\n\n<Ти не певен, що саме було сказано. Тутешня версія Алекстраси простягає тобі пісковий годинник і жестами показує, що його треба перевернути. Це, напевно, зацікавить Соридормі.>",
        objectives = "Принеси Азмерлотський Пісковий Годинник Соридормі в Резервуарі Тіргольда.",
        completion = "<Соридормі дивиться на пісковий годинник у твоїх руках.>\n\nЦей годинник — робота бронзових драконів. Він дозволяє тимчасово перестрибнути до іншого часового шляху. \n\nКажеш, тобі його дала тамтешня версія Алекстрази? \n\n<Соридормі зиркає на Алекстразу.>\n\nЩо ж, це має бути цікаво.\n\n<Соридормі перевертає пісковий годинник.>",
    },
    [76380] = {
