    [76398] = {
        title = "Панування в небі",
        description = "Драконячі зграї прибули. Час повернути собі небо! І ти допоможеш нам схилити шальки терезів.\n\nСідай на свого дрейка й бери на приціл ворогів у височині. Тобі досить лише стрімко напасти й заскочити їх зненацька. Решту твій дрейк зробить сам.",
        objectives = "Убий 15 ворожих протодрейків, що літають над Полем Полум'я, вражаючи їх ударами свого їздового дрейка.",
        progress = "Що швидше ми знищимо повітряні сили Фіракка, то швидше проб'ємося до храму й покладемо край цьому безумству.",
        completion = "Чудово. Сили Фіракка хитаються від нашого натиску.\n\nРешту полиш нам, драконам, {NAME}. Це наш Сон, і я більше не терпітиму цих загарбників.",
    },
    [76399] = {
        title = "Перегони лісом Елвінн - Просунуті",
        description = "Пролітай крізь кільця контрольних точок, що позначають трасу.",
        objectives = "Пролітай крізь кільця.",
