    [77433] = {
        title = "Розкопки: річкове русло",
        description = "Біля Маруукаю на Рівнинах Он'агри є річкове русло, що аж кишить місцевими переказами про загублений караван!\n\nЗустрінься зі мною там якнайшвидше! І взуй свої найкращі старі чоботи — ті, що не бояться багнюки!",
        objectives = "Зустрінься з Роскою Роктут біля розкопу «Річкове русло» на Рівнинах Он'агри.",
        completion = "Цією знахідкою ми сколихнемо весь світ кентаврів!",
    },
    [77434] = {
        title = "Техноворожіння: Обсерваторія",
        description = "Мої лози-шукачі вказують на руїни драконідів на вершині скелі на Берегах Пробудження.\n\nНе знаю, що ми там знайдемо, та сумніватися в забаганках моїх винаходів ніколи не варто. Вони завжди мають рацію на 97%.\n\nЗавжди.",
        objectives = "Зустрінься із Зенатою в Обсерваторії Згоди на Берегах Пробудження.",
        completion = "Ну що, зазирнімо в минуле цих розкришених каменів?",
    },
    [77436] = {
        title = "Палаючий Курган",
        description = "Сили Фіракка вже почали втілювати свої плани. Ми на крок позаду, і мусимо швидко надолужити відставання, якщо хочемо як слід захистити Амірдрассіл.\n\nПоки тривала твоя подорож сюди, ми отримали звістку про підозрілих осіб, які проникли до одного з навколишніх курганних лігв. Тіранда вже вирушила розвідати, що там коїться. Знайди її і допоможи їй.",
        objectives = "Знайди Тіранду біля Курганного Лігва Сор'теріл.",
        completion = "Ти вчасно, {class}. Мені потрібна ще одна пара рук.",
    },
    [77437] = {
        title = "Межа Еону",
        description = "Мандрівник у часі Темпо та його команда нарешті розморозили Межу Еону!\n\nЕ-е... майже. Мандрівники в часі більш-менш тримають усе під контролем, але на Межі Еону лишилося кілька клопотів, з якими містяни були б раді допомозі.\n\nСкажи Бобу, що тебе прислав я!",
        objectives = "Знайди бармена Боба на Межі Еону.",
    },
    [77483] = {
        title = "Техноворожіння: Острів Драконячого Черепа",
        description = "Я налаштувала свої сенсори на реліквії драктирів, і вони обчислили нове місце для дослідження біля східного узбережжя Заборонених Обширів.\n\nМісцеві драконіди кажуть, що зветься воно острів Драконячого Черепа. Зловісно, еге ж? Ти ж не з лякливих, правда?",
        objectives = "Зустрінься із Зенатою біля Печери Драконячого Черепа на Заборонених Обширах.",
        completion = "Мої попередні сенсори зашкалюють біля входів до печери. Те, що ми шукаємо, точно всередині.",
    },
    [77484] = {
        title = "Техноворожіння: Дозор Іґіри",
        description = "Хто б міг подумати, та мої сенсори вказують на цікаве місце під поверхнею в Печері Заралек.\n\nКраще візьми зброю на цю вилазку. Моя попередня розвідка виявила там підвищену присутність як лави, так і джарадинів.",
        objectives = "Зустрінься із Зенатою в Дозорі Іґіри в Печері Заралек.",
        completion = "Схоже, вони воліють обходити цю печеру десятою дорогою, еге ж...",
