    [77788] = {
        title = "Дослідницькі нотатки про ясенцвіт",
        description = "<На вбитому друїдові ти знаходиш обгорілі дослідницькі нотатки.\n\nУ нотатках описано досліди, які проводять Друїди Полум'я.\n\nТи дізнаєшся, що вони створили незвичайний пилок, здатний наповнити флору Сну їхньою вогняною магією. Наступний етап спрямований на тутешню фауну з тим самим пилком.\n\nК'онзу неодмінно зацікавиться зразком цього пилку й цими нотатками.>",
        objectives = "Збери Зразок Попелястого Пилку.",
        progress = "<К'онзу повільно кліпає, дивлячись на тебе згори.>",
        completion = "Це... було нищівно буденно. Сажа й попіл, навіки незмінні? \n \n<К'онзу хитає своєю величезною головою.> \n \nНі. Мені не подобається.",
    },
    [77789] = {
        title = "Розірвані зв'язки",
        description = "Налридун зібрав невелику армію культистів. Вони вірять, що через реліквію він промовляє від імені Саргераса, і ловлять кожне його слово. Так само, як ми ловили слова наших провідників, коли Саргерас прийшов на Аргус. Це була втіха. Надія.\n\nА зрештою — порожній обман.\n\nАле його послідовники не вірять, що їх ошукали. Вони спорудили в цій місцині власні канали, щоб спробувати черпати силу реліквії. Щоб самим почути голос.\n\nВони спробують нас зупинити. Ми мусимо прорубати шлях крізь них.",
        objectives = "Убий 10 культистів ман'арі та перевантаж 5 Каналів Саргереїв.",
        progress = "Нехай їхні марення помруть разом із ними.\n\nМи не можемо ризикувати жодною силою, яку вони можуть додавати до ритуалів Налридуна.",
        completion = "Я знаю, що таке страх. Але вони мали вибір — і вибрали лишитися на шляху, який ми проклали по тліючих рештках незліченних світів. \n\nЧому, коли наш власний дім був першим зі світів, які ми знищили?",
    },
    [77791] = {
        title = "Як з цим упоратися: Симбіотична Рукоять Сяйних Спор",
        description = "Я знаю майстра, який міг би допомогти загартувати Фір'алат. Ерден із клану Шикаар надзвичайно винахідливий. Він провів безліч дослідів із різними реагентами по всіх Драконових Островах.\n\nМисливець вартий рівно стільки, скільки його зброя. Ерден славиться тим, що майструє вишукану зброю з екзотичних матеріалів. Його знання різноманітної флори й фауни будуть вельми корисні.",
        objectives = "Розшукай Ердена на Рівнинах Он'агри.",
        completion = "Зрозуміло. \n\nТакою сокирою справді було б боляче орудувати. Дай-но хвильку подумати.",
    },
