    [77795] = {
        title = "Здобуті артефакти",
        objectives = "Якщо в тебе є припаси, у мене є товари. Старі речі. Деякі — священні.",
        completion = "Якщо в тебе є припаси, у мене є товари. Старі речі. Деякі — священні.",
    },
    [77802] = {
        title = "Як мені тебе називати?",
        description = "Опікун! Або... учитель! Батько?\n\nХочу, щоб ти сказа$p(в:ла) мені, як тебе називати. Інші дріади питатимуть, хто тепер мій друїд, адже я працюю в саду сама.\n\nЯ хочу сказати їм, що в мене немає друїда. У мене є ти!\n\nСкажи мені, який титул тобі до вподоби.",
        objectives = "Поговори з Діонаессою в Оплетеному Корінням Святилищі, щоб обрати титул.",
        progress = "Я чула стільки титулів від друїда Крікворда. Певна, ми придумаємо щось значно цікавіше.",
        completion = "Який чудовий титул! Уживатиму його за кожної нагоди.\n\nДякую.",
    },
    [77813] = {
        title = "Удари блискавки",
        description = "<Ляпокрил робить піруетку й кладе тобі в руку заслинену записку.>\n\nА, {name}. Мені казали, що ти роздобу$p(в:ла) чудову нову їздову тварину — грифона, що ширяє на самій бурі!\n\nЯ дуже хотів би побачити, як літає це дивовижне створіння. Чекатиму на тебе в Небосяжній обсерваторії.",
        objectives = "Зустрінься з лордом Андестрасом у Небосяжній обсерваторії.",
        completion = "І знову вітаю, {NAME}. Ну ж бо, погляньмо на цього грифона!",
    },
    [77815] = {
        title = "Тур штормових перегонів",
        description = "Цей штормовий грифон — справжня дивовижа! Земля, що породила таке створіння, безперечно варта дослідження.\n\nАле раз уже ти тут, випробуймо його вишкіл — і твою вправність у сідлі.\n\nМої колеги з бронзової зграї проклали нові маршрути, щоб добряче поганяти твого скакуна. Коли хронометрист побачить тебе на грифоні, він запропонує тобі взяти участь у цих «штормових перегонах».\n\nДоля прихильна до сміливих, {name}. Щасти!",
        objectives = "Пролети всі траси штормових перегонів на Драконових Островах.",
        completion = "Чудово! Цей штормовий грифон — і справді дивовижне створіння. Нехай на вас чекає багато чудесних пригод!\n\nЯсного неба й сильних вітрів, {NAME}.",
    },
    [77818] = {
        title = "Жорстока",
        description = "Первісники, джарадини й друїди Полум'я — усі вони діють проти нас заодно.\n\nАле я відчуваю: це ще не всі. Крізь цей портал намагається пробитися щось могутнє. Спробуймо запечатати його й не пускати їх сюди якомога довше.",
        objectives = "Допоможи Мерітрі запечатати палаючий портал.",
        completion = "Я рада, що тобі вдалося вибратися. Нам не лишається нічого, крім як відступити до дерева, перш ніж прибудуть сили Фіракка.\n\nА старійшина Кассафіна... Боюся, її вже забрало це пророцтво полум'я.",
    },
    [77822] = {
        title = "Титанічна форма",
        description = "<Форма титанового ключа була там, де й сказано в оповіді. Зброяр Кореф буде в захваті, коли побачить форму!>",
        objectives = "Поверни форму титанового ключа зброяреві Корефу у Валдраккен.",
        progress = "Клянуся горном, невже це правда? Форму титанового ключа знайдено?",
    },
    [77829] = {
        title = "Перековування легенди",
        description = "Ось ти де! Зброяр Кореф щойно тебе шукав. Залишив мені записку, де просить, щоб ти зустрі$p(вся:лася) з ним в Обсидіановому Конклаві.\n\nСхоже, ти допомагаєш йому перекувати древній ключ титанів? Розкажи мені потім, як усе пройде! Це ж готова сенсація, якщо я взагалі коли-небудь її чула.",
        objectives = "Розшукай зброяра Корефа в Обсидіановому Конклаві.",
        completion = "Нам знадобляться рідкісні матеріали для ключа: особливий золотий пил і флюс. І те, і те знайдеться на Берегах Пробудження.\n\nКоли роздобудеш матеріали, зустрінься зі мною біля Горна Вартового Землі в Обсидіановій Цитаделі. Саме там я викую ключ титанів. І посяду місце серед легенд ковальства, якщо моє ковадло вдарить влучно.\n\nОсь записка з усіма подробицями. Ми вже так близько, {class}!",
    },
    [77831] = {
        title = "Ключ до перековування",
        description = "У тебе є останні матеріали! Чудово.\n\nЯ підготував горно й форму. Тобі лишається тільки додавати складники, коли я скажу.\n\nА, і будь готовий скористатися тим Смолоскипом Піррета. Схоже, ця реліквія вкрай важлива для процесу кування. Я скажу, коли настане час!",
        objectives = "Допоможи зброяреві Корефу перекувати ключ титанів.",
        progress = "Ключ титанів. Клянуся горном... Дай-но погляну.",
        completion = "Це неймовірно! І він уже холодний на дотик? Що за дивовижна магія.\n\nХм. На стрижні є написи. Більшості з них я не впізнаю, але оце — символ Тіра. Я швидко замалюю решту послання й спробую щось з'ясувати.\n\nГадаю, найбезпечніше ключу буде в тебе. Зрештою, що таке ключ без замка? І якщо хтось і знайде титанський замок, який треба відімкнути, то це ти.",
    },
    [77832] = {
        title = "Тіні на тінях",
        description = "Я мушу його врятувати.",
        objectives = "Убий Тіні.",
    },
    [77833] = {
        title = "Як з цим упоратися: концентрований мудрий пергамент",
        description = "Я знаю одну мудрицю, яка допоможе загартувати Фір'алат. Шаласар Ґліммердаск — знавчиня всього інтелектуального, вона часто розмірковує над теоріями приборкання нестійкої магії. Мало хто розуміється на мудрих матеріях так, як вона.\n\nЗвернися до неї по пораду, як упоратися з тіньовим полум'ям. Підозрюю, її рішення міститиме дрібку хроматичного пилу!",
        objectives = "Розшукай Шаласар Ґліммердаск на Рівнинах Он'агри.",
        completion = "А, так! Дякую за подорож сюди. \n\nІнші застерігали мене не відриватися від академічних кіл, але я знала: усамітнення в цій віддаленій природній місцині колись стане в пригоді.",
    },
    [77835] = {
        title = "Як з цим упоратися: Руна Тіньового Зв'язування",
        description = "Лідіара Вісперфезер — вчена, яка визнає непохитність правил, що керують нашим світом. А ще вона любить їх обходити.\n\nЯкщо хтось і здатен допомогти зв'язати міць Фір'алата, то це вона.",
        objectives = "Розшукай Лідіару Вісперфезер у Лазуровому Просторі.",
        completion = "Ти хочеш зв'язати тіньове полум'я? Як небезпечно! Як зухвало! Берімося.\n\nЯ вивчала флору Смарагдового Сну. Дослідження екзотичних, немов зі сну, рослин цього краю добряче відволікає, але одну з них я примітила — вона може допомогти нам знайти відповіді.",
    },
    [77838] = {
        title = "Подертий сонний лист",
        description = "Властивості сонного листа тобі незнайомі.\n\nЗавершуючи події під час Суперцвітіння, ти здобудеш знання, потрібні, щоб допомогти своєму союзникові.",
        objectives = "Завершуй події під час Суперцвітіння.",
        completion = "Тіньовий сонний лист досі спантеличує, але, сподіваймося, твоєму союзникові ці знання все одно прислужаться.",
    },
    [77839] = {
        title = "Траси Кубка Східних королівств",
        description = "Знову настав час випробувати свою звитягу.\n\nМої колеги з бронзового роду вирушили до Східних королівств, щоб улаштувати нові гоночні випробування. По всьому континенту на тебе чекає безліч трас.\n\nТобі це до снаги?",
        objectives = "Пролети вступні траси Кубка Східних королівств.",
        progress = "Як літається сьогодні?",
        completion = "Ти попереду серед своїх товаришів — небесних вершників! Поки триває Кубок Східних королівств, знаходь там інші перегони й доводь, що тобі немає рівних.",
