    [78504] = {
        title = "Легенько струшений подарунок",
        objectives = "Цей дарунок, схоже, кілька разів добряче трусили. На бирці написано:Комусь дуже особливому — &lt;race&gt; &lt;class&gt;.",
        completion = "Цей дарунок, схоже, кілька разів добряче трусили. На бирці написано:\n\nКомусь дуже особливому — {race} {class}.",
    },
    [78529] = {
        title = "Жорстокий удар",
        description = "<Зір пливе перед очима, коли ти повільно приходиш до тями. У вухах, що дзвенять, відлунюють далекі крики й зойки.\n\nОстаннє, що ти пам'ятаєш, — Даларан, велике летюче місто магії, що стрімко падає до землі, а далі лише пітьма.\n\nПоміж криками й гуркотом бою ти чуєш дивне комашине цокотіння.\n\nНеруби чекали на тебе.\n\nТи мусиш повернутися до бою, але спершу маєш вивільнитися з-під нищівної ваги уламків, що навалилися на тебе.>",
        objectives = "Виберися з-під уламків і знайди своїх уцілілих очільників.",
        completion = "{NAME}! Ти серед живих!\n\nДобре.\n\nТримай зброю напоготові. Ця битва лише починається.",
    },
    [78530] = {
        title = "Убий диверсантів",
        description = "Неруби всюди, {name}.\n\nЇх забагато, щоб усі були лише вцілілими після падіння. Я бачив, як інші вигрібаються з-під землі.\n\nЦя Королевина варта Зірікс залягла тут, щоб нас здолати.\n\nПокажи їм, що ми не легка здобич. Поруби їх!",
        objectives = "Убий 12 нерубіанців.",
        completion = "Гарна робота. Ми теж просунулися. Можливо, тепер ми зможемо рушити далі.",
    },
    [78531] = {
        title = "Нагальний порятунок",
        description = "Ми вціліли майже неушкодженими. Не всім так пощастило.\n\nБагато тих, хто був у Даларані під час падіння, досі зникли безвісти. Їм знадобиться наша допомога.\n\nОбшукай поле бою в пошуках тих, хто вижив. Допоможи їм усім, чим зможеш.\n\nНам потрібні всі на ногах і в бою!",
        objectives = "Допоможи 7 уцілілим після падіння Даларана.",
        completion = "Добре знати, що багато хто вцілів.\n\nКоли ця битва скінчиться, ми віднайдемо тіла тих, кому не пощастило.",
    },
    [78532] = {
        title = "Несправні артефакти",
        description = "У Даларані зберігалося чимало коштовних і могутніх реліквій. Багато з них пошкодило під час падіння, і тепер вони збожеволіли.\n\nЇх треба знищити!\n\nВізьми цей сувій. Я вклала в нього руйнівне закляття. Прочитай слова вголос — і його магія вивільниться.\n\nКоли впораєшся, доповіси Джайні про те, що ти зроби$p(в:ла). Вона зрозуміє.",
        objectives = "Знищ 5 пошкоджених арканних реліквій.",
        completion = "Руйнувати Даларан іще більше — річ, здавалося б, немислима.\n\nАле ти й Ейтас вчинили правильно.\n\nВони були нестабільні, і ми не могли ризикувати тим, щоб їхню силу обернули проти нас.",
    },
    [78533] = {
        title = "Захопи берег",
        description = "Королевина варта Зірікс виринула з-під землі й заскочила Маґні зненацька.\n\nВін на найдальшому краю уламків відбивається від її рою.\n\nМоїра і я намагалися допомогти, та не змогли відтягнути їх убік.\n\nХодімо зі мною. Маґні потрібна наша допомога!",
        objectives = "Знайди Маґні й здолай Королевину варту Зірікс.",
        completion = "Може, ви й не порушники меж, але й не наші союзники, чужинцю.\n\nЯкщо це через тебе вигулькнули нерубіанці, то на тобі й провина за напад на Дорноґал.",
    },
    [78534] = {
        title = "До Дорноґала",
        description = "Ти приніс на наші береги смерть і руйнацію, яких не бачили вже тисячоліттями.\n\nАле в тебе на руках кров нерубів, а поруч — траеґар. Цього досить, щоб заслужити мою довіру — поки що.\n\nЯ та мої штормові вершники мусимо повернутися до нашої столиці, Дорноґала, і з'ясувати, що там, найпевніше, триває напад. Лети з нами. Наш потік повітря дасть тобі легко ширяти небом.\n\nЯ пошлю інших штормових вершників, щоб забрати твоїх союзників, щойно їм стане безпечно приземлитися.",
        progress = "Нам потрібні відповіді.",
        completion = "Що накоїли неруби? І навіщо?",
    },
    [78535] = {
        title = "Вони приходять із глибин",
        description = "Я ще не знаю, чому ти прибу$p(в:ла) сюди, $p(чужинцю:чужинко). Та ти, схоже... вправно вбиваєш нерубів.\n\nЯк і ми, штормові вершники, передова варта цього острова.\n\nНеруби — давній ворог. Я не здивувався б, якби ця Зірікс знала й боялася мене, штормового стража.\n\nХай там як, твоя вправність стала б нам у пригоді в обороні Дорноґала.\n\nУ мене є штормовий крук, на якому ти можеш літати. Сідай верхи й допоможи нам очистити місто від цих комах!",
        completion = "Я не знаю, чому неруби повернулися...\n\nІ навіщо їм нападати на Дорноґал.\n\nНаразі я мушу зосередитися на оцінці шкоди, завданої Стрижневому шляху.\n\nНашим браттям, Машинним речникам, може знадобитися наша поміч, а воля титанів — щоб шлях до центру Азерота лишався відкритим.",
    },
    [78536] = {
        title = "Безнадійні шанси",
        description = "Заради титанів... Стрижневий шлях, схоже, зруйновано вщент! Знадобляться роки, а може, й століття, щоб розгребти уламки й полагодити шкоду, яку неруби завдали його внутрішній будові, не кажучи вже про те, щоб дістатися до ядра світу.\n\nА надто тепер, коли каменепов'язані зникли...\n\nМені треба хвильку, щоб вирішити, як діяти.\n\nТвої друзі прибули цілими. Поговори з ними і не плутайся в мене під ногами.\n\nЯкщо ти нам знадобишся, я дам тобі знати.",
        objectives = "Поговори з Траллом.",
        progress = "Раду треба сповістити. Попереду багато роботи...",
        completion = "Моя директива тебе не передбачає, чужин$p(цю:ко).",
    },
    [78538] = {
        title = "Спільні зусилля",
        description = "Незв'язані прибули зі спорядженням і ресурсами, потрібними, щоб почати відбудову Стрижневого шляху.\n\nЦе знаменна подія. Гідна Архіву! Аделґоннові я б цього не сказав, та я бачу в цьому руку титанів...\n\nА тепер настав час виконати мою директиву! Я склав план, як найефективніше організувати наших робітників, а також виділив припаси, щоб гідно їх зустріти.\n\nВіднеси ці накази робітникам Аделґонна, щоб вони могли взятися до справи всерйоз. Ми невдовзі приєднаємося до тебе там.",
        objectives = "Роздай накази Меррікса 10 незв'язаним робітникам довкола Стрижневого шляху.",
        progress = "Мусимо негайно братися до роботи.",
        completion = "Навіть із такою кількістю робітників ремонт Стрижневого шляху забере час.\n\nТреба вирішити, що робити тим часом.",
    },
    [78539] = {
        title = "Тривкий ремонт",
        description = "Оскільки мої штормові вершники... бездіяльні, Дорноґал лишився без захисту, якщо не рахувати жменьки звичайних охоронців порядку. Якщо неруби знову нападуть на нас тут, Дорноґал упаде — а з ним і всі ми.\n\nКонче потрібно відманити їх від міста і знищити їхнього командира.\n\nМи можемо й сплетемо власну павутину та впіймаємо в неї Зірікс.\n\nУ мене є план.",
        objectives = "Обговори з Баелґрімом план нападу на нерубів.",
        progress = "Ми не можемо лишатися в обороні.",
        completion = "Тоді вирішено.\n\nМи дамо бій біля медоварні Глутбрю.",
    },
    [78540] = {
        title = "До медоварні",
        description = "Твоя подруга-лучниця має рацію. Ми мусимо знищити Зірікса та його війська, якщо хочемо вберегти Стрижневий шлях.\n\nРушаймо до медоварні Глутбрю негайно.",
        objectives = "Зустрінься з Баелґрімом біля медоварні Глутбрю.",
        completion = "Дяка титанам! Неруби ще не рушили забирати мед.",
    },
    [78541] = {
        title = "Розставити пастку",
        description = "З усіма цими діжками глутбрю медоварня палала б жаркіше за Кузняну площу, якби їх усі підпалити.\n\nПідозрюю, саме тому Венбрандт робить діжки з міцного й твердого залізодерева — вони так просто не тріскаються й не займаються.\n\nНа щастя, ми можемо запустити реакцію зсередини, якщо протягнемо до кожної з них ґноти.\n\nТі мотузки, що робітники лишили довкола, у скруті згодяться.",
        objectives = "Приєднай 4 мотузяні ґноти до шиплячих діжок.",
        progress = "Треба підготувати діжки з глутбрю.",
        completion = "Зірікс упаде від моєї руки. Це моя директива. Це моя воля.",
    },
    [78542] = {
        title = "Зона евакуації",
        description = "Слухай, можеш висадити в повітря справу всього мого життя, якщо іншого виходу немає, але я не наражатиму своїх робітників на небезпеку.\n\nЦей шлях ми обрали всі разом, та я не дозволю, щоб вони жертвували собою заради цього у вогні чи від нерубіанців. Перекажи їм, що я наказав негайно забиратися звідси.\n\nІ якщо хоч на одному з них з'явиться бодай подряпина, Раді буде за що відповідати!",
        objectives = "Евакуюй 8 незв'язаних робітників медоварні.",
        progress = "Якщо моїх робітників не можна вберегти, я покладу цьому плану край.",
        completion = "Радий чути, що їм стало глузду забратися звідти без зайвого галасу.",
    },
    [78543] = {
        title = "Розворушити гніздо павуків",
        description = "Медоварню евакуйовано, вибухівку приготовано. Час заманити нерубіанців у нашу пастку.\n\nТвоя соратниця стоїть біля нерубіанської нори на північ звідси. Вона сказала, що її доручення — наглядати за норою на випадок, якщо нерубіанці почнуть діяти раніше, ніж ми будемо готові.\n\nДосі вони не ворушилися, тож тепер їх, можливо, треба... підштовхнути. Віднеси діжку глутбрю до нори. Кинь її туди — це має сколихнути їхнє «гніздо».\n\nПісля цього мерщій повертайся до нас, на медовий двір.",
        objectives = "Кинь діжку глутбрю в нерубіанську нору, а тоді повернися на медовий двір.",
        completion = "Нерубіанський рій уже на підході.\n\nПриготуйся.",
    },
    [78544] = {
        title = "Накликати грім",
        description = "Нерубіанці кинуться в атаку з люті й гордині — а саме цього нам і треба.\n\nНезабаром вони ринуть на медоварню, прагнучи покарати нас за напад на їхню нору. Ми втримаємо їх тут, на землі, поки ти здіймешся в небо. Щойно з'явиться Зірікс, аби командувати своїм військом, ми підпалимо ґноти.\n\nВенбрандт назбирав дещо з припасів, чим ми зможемо загнати нерубіанців у пастку. Розстав їх швидко, а тоді ми посадимо тебе на штормокрука. Вперед!",
        objectives = "Стримуй нерубіанців біля Медоварні «Жаровар», доки не з'явиться Королевина варта Зірікс.",
        completion = "Зірікс мертвий. Ми впоралися. Усе скінчено. Це зробив Бейлґрім.\n\n<Вона повторює останню фразу знову і знову, щоразу тихіше, наче не в змозі осягнути те, що сталося.>",
    },
    [78545] = {
        title = "Повернення на Стрижневий шлях",
        description = "Ми завдали нерубіанцям тяжкого удару. Але Бейлґрім...\n\n<Адельґонн замовкає, аби опанувати себе.>\n\nВін був до сказу впертий, і ми сварилися без упину, та зрештою... він був захисником нашого народу — усього, до останнього.\n\nБейлґрім пожертвував собою, щоб уберегти острів Дорн від нерубіанців. Про це мають дізнатися всі — і ми не можемо знову дозволити нерубіанцям отак вивернути нам руки.\n\nПовертайся до Меррікса в Дорноґал. Скажи йому, що ми скоро прибудемо. Нам просто... потрібна тут хвилина.",
        objectives = "Повернися до Меррікса в Дорноґалі.",
        completion = "Ти жив$p(ий:а)! Але що з рештою?",
    },
    [78546] = {
        title = "Відплата",
        description = "Відлуння вибуху ми чули аж звідси.\n\nГадаю, ти здобу$p(в:ла) перемогу, та твоє самотнє повернення натякає, що не все гаразд.\n\nЩо сталося?",
        objectives = "Поговори з Адельґонн, щоб сповістити Меррікса про долю Бейлґріма.",
        completion = "Нехай усі ми навчимося зі звитяги Бейлґріма.\n\nВін загинув, щоб зберегти наш народ — нашу єдність. Ми не сміємо допустити, щоб це було марно.",
    },
    [78555] = {
        title = "Під землею і в скруті",
        description = "Мене не було надто довго. Машинним речникам тут вочевидь ведеться несолодко. Чи знає про це Верховний речник?\n\nНерубіанський саботаж укупі з кричущою недбалістю — згубне поєднання. Мусимо якнайшвидше повернути станцію Залізовіз до ладу. Це життєво важлива ланка між Дзвінкими Глибинами й містом нагорі.\n\nПрошу, {name}, допоможи нашим пораненим робітникам, збери весь придатний вантаж і віднови безпеку на станції Залізовіз.",
        objectives = "Допоможи Машинним речникам убезпечити станцію Залізовіз.",
        progress = "Мертві нерубіанські шкряботуни, нерозірвані бомби, поранені робітники... ото гармидер.",
        completion = "Дякую, що допом$p(іг:огла) робітникам стати на ноги. Порядок відновлено — принаймні настільки, щоб ми могли повернутися до роботи.\n\nНайкращий спосіб справити враження на наглядача Узджакса — виконана робота, і в тебе це виходить.\n\n*пошепки* ...але будь обережн$p(ий:а). Він відданий владі, тож нам варто зважати на слова.",
    },
    [78557] = {
        title = "Зійти з рейок",
        description = "Речницю Брінте розпізнано. $p(Чужинцю:Чужинко), тут є робота.\n\nОдна з наших більших вагонеток зійшла з рейок. Вона перекриває головну розв'язку станції.\n\nПродуктивність моїх робітників знижена, а їхня робота далека від оптимальної. Титани поставили нас сюди працювати, та не всі мої робітники працюють. Зможеш повернути нас на правильні рейки?\n\nТільки обережно. Я бачу, що ти з плоті й кісток. Не хочу, щоб тебе розчавило.",
        objectives = "Оглянь вагонетку, що зійшла з рейок, на станції Залізовіз.",
        progress = "Поки ми лишаємося відданими, дотримуємося строків і виконуємо норми, усе буде добре. \n\nШестерні крутяться, а ми працюємо.\n\nСлава Машині.",
        completion = "Запит на звіт. Чи вдалося щось знайти? \n\nЦе що? «Скар-дин»? \n\nЦя інформація не стосується мого доручення. Зосереджуюся на роботі.",
    },
    [78558] = {
        title = "Гонитва Шолазару",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
        objectives = "Пролети крізь кільця.",
    },
    [78559] = {
        title = "Гонитва Шолазару — Просунута",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
        objectives = "Пролети крізь кільця.",
    },
    [78560] = {
        title = "Гонитва Шолазару — Зворотна",
        description = "Пролети крізь кільця контрольних точок, що позначають трасу.",
        objectives = "Пролети крізь кільця.",
    },
    [78562] = {
        title = "Викинуте й зламане",
        description = "Гей, ти! Ти ж тут, щоб допомогти, чи не так?\n\nГудіння машин, їхня мелодія, змінюється, і я... зізнаюся, я не готовий. Стільки років я служив вірно, а потім...\n\nЩо ж, головне те, що я знову готовий узятися до роботи. Та бачиш, усі мої інструменти зламані й розкидані хтозна-де.\n\nЯкби ти пильнува$p(в:ла) за ними і приніс їх мені, я був би тобі винен.",
        objectives = "Збери загублені інструменти машиніста Кіттріна.",
        progress = "Машиніст — ніщо без інструментів свого ремесла.",
        completion = "Мій вимірювач! Мій штангенциркуль! Мій гайковий ключ!\n\nЯк добре знову тримати їх у руках. Хоча, мушу визнати, я був не до кінця чесний з тобою.",
    },
    [78563] = {
        title = "Тягар цілого світу",
        description = "Мої інструменти опинилися там, де ти їх знайшов, не випадково. Їх там поклали. Я сам.\n\nЯ дійшов до такого відчаю, що не бачив іншого виходу. Машини, велике творіння мого народу, уже ніколи не заспівають знову. То навіщо мені завдавати собі клопоту, лагодячи їх?\n\nАле тепер я бачу, і тепер я розумію!\n\nОстанній інструмент, що мені потрібен, я впустив у воду, і його проковтнула велетенська істота. Гадаю, щоб повернути його мені, доведеться застосувати трохи більше сили.",
        objectives = "Здобудь калібрувальний тягарець машиніста Кіттріна.",
        progress = "Щойно всі мої інструменти повернуться до мене, я знаю: усе знову буде як слід.",
        completion = "<Кіттріна, схоже, анітрохи не бентежить кишковий слиз, що вкриває калібрувальний тягарець.>\n\nТи знайш$p(ов:ла) його! Тепер дай-но я все це відчищу й полагоджу решту інструментів. І тоді я знову буду готовий служити.",
    },
    [78564] = {
        title = "Віднайдене покликання",
        description = "Це всі вони! Тепер настав час виконати свій обов'язок і перелити ці інструменти заново. Перекувати їх, і себе самого, на те, ким мені судилося бути: гордим машиністом Дзвінких Глибин.",
        objectives = "Допоможи машиністу Кіттріну перекувати інструменти й наново присвятити їх справі.",
        progress = "Я готовий знову виконувати свою частку роботи. Лишилося тільки перекувати ці старі інструменти.",
        completion = "Не знаю, як і дякувати тобі за всю допомогу. Я втратив був віру, але тепер зі мною знову і віра, і мої інструменти.\n\nЯ довіку тобі вдячний.",
    },
    [78565] = {
        title = "Втеча до мальовничих Грізлячих пагорбів!",
        description = "Сьогоднішня спецпропозиція — магічна втеча до величних лісів Нортренду!\n\nСлухай, ти ж один із тих шукачів пригод, так? Зроби мені послугу.\n\nМіг би ти нарвати мені кілька квітів на Грізлячих пагорбах? У мене тут роботи по горло, а є одна особа, якій я дуже хотів би подарувати букет.",
        progress = "Моїй половинці ці квіти дуже припали б до душі.",
        completion = "Дякую по самі вінця, {NAME}!\n\nСподіваюся, мандрівка пагорбами припала тобі до душі! Куди не глянь — усюди є що відкрити.",
    },
    [78570] = {
        title = "Пошарпана спадщина",
        description = "Не зраджуй себе, {race}t.\n\nМи, Варта Пущі, дотримуємося давньої обіцянки, даної Фреї, — піклуватися про ці землі. Наш указ давніший за ті, якими розмахують демагоги в Дорноґалі. Давніший за сам Дорноґал.\n\nОднак не всі землі доглядали однаково. Очільниця нашого ордену мала дбати про улоговину неподалік, але ми вже багато циклів нічого про неї не чули.\n\nЯ відіслав послушницю на розвідку. Допоможи їй — і мій орден буде тобі вдячний.",
        objectives = "Зустрінься з Іґріс біля Лісокореневої Улоговини на острові Дорн.",
        completion = "Ця улоговина не така, якою має бути. На нас чекає багато роботи.",
    },
    [78571] = {
        title = "Грибний хаос",
        description = "Фрейдрін була очільницею мого ордену. Мене відіслали сюди їй на поміч. Я спізнилася.\n\nУ цих лісах оселилася темрява, {race}s.\n\nЦі ліси були домівкою Фрейдрін. Доглядати за ними було її обов'язком, покладеним самою Хранителькою. А тепер її немає, і ліси її поринули в хаос.\n\nПринеси мені спори цих потвор, що сіють хаос. Можливо, ще є спосіб очистити цю землю.",
        objectives = "Збери 30 спор Лісокореня з фунґаріан у Лісокореневій Улоговині.",
        progress = "Чи всі вони вже в тебе?",
        completion = "Дякую, {NAME}. Я уважно їх огляну. Фунґаріани цих лісів становлять більшу небезпеку, ніж будь-хто з нас передбачав.\n\nМи мусимо запобігти їхньому поширенню.",
    },
    [78572] = {
        title = "Спогади Пущі",
        description = "Фрейдрін напевне мала якийсь спосіб давати відсіч фунґаріанам.\n\nХоч у цих краях лишилося небагато тих, хто й досі дотримується Указів, Фрейдрін довго була щиро віддана їм. Вона нізащо не дозволила б цим лісам дійти до такого стану, доки трималася віри.\n\nНам варто оглянути її домівку в лісі. Можливо, всередині знайдеться щось корисне.",
        objectives = "Обшукай домівку Фрейдрін, щоб знайти засіб проти фунґаріан у Лісокореневій Улоговині.",
        progress = "Мені моторошно перебирати речі доглядачки Пущі. Стільки нерозказаних історій.",
        completion = "У цьому посоху — знайома магія, яку я сподівалася забути. Ох, Фрейдрін, що ж тут сталося?",
    },
    [78573] = {
        title = "Поміч Хранительки",
        description = "Магічний посох? Обереги? Що ж ти робила, Фрейдрін?\n\n<Іґріс на мить поринає в роздуми: чоло її морщиться, очі сяють. За хвилю вона обертається до тебе з усмішкою, наче викарбуваною на обличчі.>\n\nПридумала!\n\nЖиттєва енергія цього посоха має подолати будь-яку грибну заразу в тутешній звірині. Поверни тварин до природного циклу — і з часом земля зцілиться сама.\n\nА якщо побачиш обереги — познімай їх. Про всяк випадок візьми її самоцвіт пам'яті. Він може розповісти ще більше.",
        objectives = "Скористайся посохом Фрейдрін, щоб очистити Лісокореневу Улоговину.",
        progress = "У цьому посоху дрімає чимало прихованої магії. Можливо, він — наша єдина надія приборкати цих фунґаріан.",
        completion = "Просто дивовижно.",
    },
    [78574] = {
        title = "Володар гаю",
        description = "Мушу попросити тебе про останнє.\n\nЦими лісами блукає величезне чудовисько. Я певна, ти відчуваєш його присутність. Його треба здолати.\n\nГнилокор був останнім засобом Фрейдрін, щоб тримати цю улоговину під контролем, та навіть це виявилося непосильним для одного земельника. Наша справа — не панувати, а дбати про потреби землі.\n\nСкористайся посохом іще раз і поклади край володарюванню Гнилокора.",
        objectives = "Здолай Гнилокора Незваленого в Лісокореневій Улоговині.",
        progress = "Якщо ми хочемо відновити це місце, мусимо зробити це інакше. Мусимо прокласти новий шлях.",
        completion = "Загибель Гнилокора стане кінцем занепаду цієї улоговини.\n\nДякую, {race}. Твоя допомога була просто неоціненною.",
    },
    [78589] = {
        title = "Інвазивна кухня",
        description = "<Ця рідкісна рослина може стати в пригоді кухареві Дінеру.>",
        objectives = "Достав Тіньовий Баклажан кухареві Дінеру на Грибних полях.",
        completion = "Тіньовий баклажан — не всім він видається смакотою, але коли його готую я, він стає улюбленцем публіки!",
