    [78591] = {
        title = "Втеча до мальовничого Награнда!",
        description = "Сьогоднішня спецпропозиція — магічна втеча до великих рівнин Награнда!\n\nЯкщо прямуєш туди, чи не міг би ти підстрелити кількох тварин? О, ні, не в тому сенсі! Ось, позич мій фотоапарат.\n\nМоя подруга Беатріс останнім часом блукає тими краями. Вона була б дуже рада кільком світлинам, але мені треба наглядати за порталами.",
        progress = "В Азероті стільки місць, куди можна втекти від буденності! Куди не глянь — усюди щось нове.",
        completion = "Беатріс точно оцінить твої світлини.\n\nДякую за твою доброту, {NAME}.",
    },
    [78594] = {
        title = "Втеча до мальовничого Фераласу!",
        description = "Сьогоднішня спецпропозиція — магічна втеча до сонячних пляжів Фераласу! У курорті Парових Купалень триває чудове свято, і запрошені всі!\n\nНа жаль, дехто з гостей, які скористалися цим порталом раніше, лишив свої подарунки тут, на гала-вечорі.\n\nЧи не допоможеш повернути їх? Зустрінь мене на пляжі, і ми розберемося, який подарунок кому належить.",
        progress = "В Азероті стільки місць, куди можна втекти від буденності! Куди не глянь — усюди щось нове.",
        completion = "Дякую за допомогу, {NAME}! Ти зроби$p(в:ла) багатьох людей щасливими, повернувши їм їхні подарунки.\n\nІ яке ж то було розмаїття дарунків! Мабуть, мова любові в кожного своя.",
    },
    [78595] = {
        title = "Просочений Сном",
        description = "<Мелсісра вкладає тобі в руку трохи вологу записку.>\n\n{name}, твої вчинки допомогли зібрати достатньо сили для просочення Сном! Зустрінься зі мною в Центральному таборі, щоб я могла тобі його передати.\n\n- Еліанна",
        objectives = "Поговори з Еліанною в Центральному таборі.",
        completion = "Просочуйся на здоров'я!",
