    [78596] = {
        title = "Виклик до лорда Ґреймейна",
        description = "Вітаю, \n\nЛорд Ґреймейн просить тебе прибути до гавані Стормвінда, щоб допомогти йому в справі, що стосується Ґілнеасу.\n\nБільше я сказати не можу.\n\nХай щастить, {name}.",
        objectives = "Зустрінься з Ґенном Ґреймейном у гавані Стормвінда.",
        completion = "{NAME}, дякую, що прибу$p(в:ла).\n\nДозволь увести тебе в курс справи.",
