    [78874] = {
        title = "Викликана допомога",
        description = "Якщо ти шукаєш їжу — м'яку їжу — то, боюся, у нас усе скінчилося. Зараз тут немає нічого, крім старого доброго каміння та самоцвітів.\n\nЧесно кажучи, це починає ставати проблемою.\n\nСлухай... а ти часом не міг би з цим щось зробити? Роздобути для нас, м'ясистих, якогось харчу?",
        objectives = "Приклич їжу для корчмаря Бракса в корчмі Ґундарґаза.",
        progress = "Не хочеш скуштувати шматочок кобальту?",
        completion = "Вдар мене молотом і назви ковадлом — оце так гора їжі!",
    },
    [78875] = {
        title = "Невбивний",
        description = "Б'юсь об заклад, що за всім цим стоїть оґр Май'Зот. Він мав би загинути давним-давно, але його магія досі сильна.\n\nВін використовує осердя вівтаря як провідник, щоб висмоктувати силу Лукоу.\n\nЗабери осердя й доведи, що він не такий уже й невбивний, коли в нього немає заручника-лоа.",
        objectives = "Забери осердя вівтаря в Май'Зота.",
        progress = "Ну що, дов$p(ів:ела) ти, що Май'Зот не такий уже й невбивний?",
        completion = "Це осердя — критично важливе. Через нього безпосередньо висмоктували силу Лукоу.",
    },
    [78876] = {
        title = "Сяйливий пам'ятний знак",
        description = "<Незвично стійка жарина привертає твій погляд. Вона світиться чистим, первісним жаром.>\n\n<Віранот це було б цікаво.>",
        objectives = "Принеси Вічножевріючу Жарину Віранот — в Амірдрассіл або до Центрального табору в Смарагдовому Сні.",
        completion = "Жарина первісного полум'я, якимось дивом не торкнута тіньополум'ям тієї клятої печери... \n\nДякую. Це теплий спогад про брата, який був у мене давним-давно.",
    },
    [78877] = {
        title = "Благослови ці оселі",
        description = "Божественну присутність визнано.\n\nЩодня, скільки сягає моя пам'ять, я ходив цими стежками й запалював пахощі довкола наших осель. Це стерло мої суглоби на порох, але це важлива справа.\n\nСвященна справа.\n\nМи живемо в темні часи... можливо, ти додаси власні благословення до наших скромних обрядів?",
        objectives = "Благослови пахощі довкола Ґундарґаза.",
        progress = "Ти робиш нам честь, приносячи свою віру в ці печери. Хай вона благословить ці машини й тих, хто з ними працює, як вони благословляють нас у відповідь.",
        completion = "Ми всі — гвинтики в машині. Ми обертаємося, обертаємося й обертаємося... \n\nУ цьому є краса. \n\nІ тиша.",
    },
    [78879] = {
        title = "Пробудження кузні",
        description = "Гм! Ця клята кузня дихає на ладан. Ми б її полагодили, але каменяр Ітсак узяв зміну на станції Залізовіз, коли обвалився Ядрошлях, і ось...\n\nБільше нема кому її лагодити.\n\nЯкщо ти знайдеш спосіб знову розжарити її як слід, Ґундарґаз буде твоїм боржником!",
        objectives = "Знайди спосіб розпалити кузню біля Ґундарґаза.",
        progress = "Мені бракуватиме Ітсака. Він смажив найкращу печеню з каменю наприкінці зміни...",
        completion = "Ого! Оце вперше таке бачу! Ти що... просто тримаєш вогонь у горлі?\n\nОт би й собі такого трюку навчитися!",
    },
