    [78941] = {
        title = "Час переломити хвилю",
        description = "Армія Ксал'атат уже давно завдає нам відчутних ударів. То що ж змусило її обрати саме цю мить?\n\nТут щось не так. Вона чекала, поки ми у відповідь зберемо військо, а тоді нападає відкрито. Ми граємо їй на руку.\n\nДоповідай генеральші Араті. Я ж вирушу просто на поле бою.",
        objectives = "Зустрінься з генералкою Стілстрайк у Голловфолі.",
        completion = "Добре, що ти тут. Буду стислою.",
    },
    [78942] = {
        title = "Міць Каз Алґару",
        description = "Провісниця гадає, що зможе застати нас зненацька, але вона дурна, якщо сподівається перемогти в цьому бою.\n\nАлґарська офензива прикриває тобі спину, {name}. Не щади жодного ворога.",
        objectives = "Дай відсіч нерубіанцям.",
        completion = "Ваші Орда й Альянс — грізна армія. Без них ми навряд чи багато вдіяли б.",
    },
    [78943] = {
        title = "Сталь і полум'я",
        description = "Наші сили, можливо, й здатні втриматися самі, та коли вони побачать тебе в бою, це піднесе їм дух.\n\nВізьми цей бойовий ріг. Нехай він прогримить і сповнить наших ворогів жахом. Коли надихнеш наші війська, прямуй до своїх командирів.",
        objectives = "Надихни 20 бійців Алґарської офензиви.",
        completion = "Ти прибу$p(в:ла) саме вчасно.",
    },
    [78948] = {
        title = "Світло в пітьмі",
        description = "Щось дуже не так. Що довше триває битва, то агресивнішою стає кожна сторона.\n\nСкидається на те, що Аллерія щось знає - посеред бою вона раптом кудись помчала. Ми кинулися навздогін, але я не можу покинути цих солдатів на смерть. Вона зовсім поряд, попереду; разом ми зможемо її наздогнати.",
        objectives = "Поговори з Андуїном і наздожени Ксал'атат.",
        completion = "Хадґарові потрібна негайна допомога. Святкування зачекають.",
    },
    [78950] = {
        title = "Підрубати ноги",
        description = "Ксал'атат ми поки не вистежили, та з глибини поля бою надходять звістки, що накази віддають певні неруби. Це небагато нам дасть, але важлива кожна дія.\n\nЗнищ їх. Сподіваюся, це дасть нам трохи перепочити.\n\nКоли впораєшся, поговори з Андуїном. Він і дівчина з Араті подалися навздогін за Аллерією.",
        objectives = "Убий лейтенантів нерубів.",
        progress = "Поговори з Андуїном у Багряних Лещатах.",
        completion = "О, добре, ти $p(дістався:дісталася).",
    },
    [78951] = {
        title = "Дедалі глибша тінь",
        description = "Коли я потягнулася до Полум'я, то відчула всю гнітючу безнадію та відчай, що були в нього влиті.\n\nМені боляче це казати, але... мого світла самого по собі не досить, щоб вигнати ці тіні.\n\nОтже, ми оберемо прямішу дорогу. Якщо рештки культистів відступили до Гаю Похмурої Скелі, то їхня об'єднана сила, певно, і тримає Полум'я в темряві.\n\nМи мусимо спинити їх, доки ця темрява не поширилася.",
        objectives = "Убий 10 культистів Ордену Ночі в печері під Світанковою Вежею.",
        progress = "Це колись були мої люди. Мої союзники. Мої наставники. \n\nКолись я намагалася їх напоумити. Намагалася відкрити їм Світло... показати, що Світло досі в усіх нас.\n\n<Обличчям Фейрін перебігають то смуток, то гнів.>\n\nВони не слухали. А тепер убивають невинних. \n\nЯ не можу вагатися. Більше ні.",
        completion = "<Щелепа Фейрін тверда.> \n\nВони зробили свій вибір.",
    },
    [78952] = {
        title = "Останній опір",
        description = "<Фейрін говорить притишеним, лютим шепотом.>\n\nГарна робота. Та перш ніж піти, є ще одна справа.\n\nОтам, унизу, кілька могутніх жерців. Гадаю, вони щось прикликають -- щось велике. Безсумнівно, щоб ударити по нас згори й вибити нас із самої вежі.\n\nЦе буде небезпечно, але ми мусимо їх спинити. Ти зі мною?",
        objectives = "Знищ Тіньовий Розлом.",
        completion = "<Очі Фейрін потемніли від утоми.> \n\nЦе ніколи не скінчиться, правда ж?",
    },
    [78954] = {
        title = "Відродити полум'я",
        description = "Відчуваєш це? Як повертається надія?\n\nДякую за допомогу, {name}.\n\nПолум'я Світанкової Вежі досі темне. Та цього разу, гадаю, нам вдасться його відродити.\n\nЗустріньмося біля вежі.",
        objectives = "Допоможи Фейрін відродити Священне Полум'я біля Світанкової Вежі.",
        progress = "Я лише сподіваюся, що разом ми зможемо запалити трохи більше світла в нашому маленькому світі.",
        completion = "<Фейрін тепло й утомлено всміхається.> \n\nДякую. Дяка Світлу, що ви прибули саме тоді, коли прибули. Я рада, що ми можемо допомагати одне одному.",
    },
    [78972] = {
        title = "Жнивний хаос",
        description = "Наші батьки пішли битися з потворами, що вдерлися на нашу ферму. Поки їх немає, ми намагаємося давати лад господарству.\n\nУ нас є жнивороб, що допомагає з роботою, та я весь час заганяю його в річку. Ми б упоралися зі своїми справами, якби ти допоміг нам кермувати жниворобом!",
        objectives = "Керуючи жниворобом Ремі, повантаж у вози 4 капустини й 4 морквини. А ще вбий 12 інвазивних жуків.",
        progress = "Чи всі справи по господарству зроблено?",
        completion = "У тебе чудово виходило керувати Ремі.  Може, повернешся й наступного тижня допомогти!",
