    [82417] = {
        title = "Рідкісний ключ",
        completion = "Робота Розтятих Ниток швидко просувається. Тож наші покровителі вирішили винагородити твою невпинну відданість.\n\nА тепер бери це і щезни. Ти привертаєш підозріливі погляди.",
    },
    [82432] = {
        title = "Дарунок, витканий руками",
        completion = "Робота Розтятих Ниток швидко просувається. Тож наші покровителі вирішили винагородити твою невпинну відданість.\n\nА тепер бери це і щезни. Ти привертаєш підозріливі погляди.",
    },
    [82441] = {
        title = "З любові до самоцвітів",
        description = "Доки Даларан не впав, я була визначною фахівчинею із самоцвітів. Але я втратила все - самоцвіти, книги, сувої - як і всі інші.\n\nУяви ж мій подив, коли я дізналася про істоту на ім'я Базальтій, яка володіє знаннями про самоцвіти, що сягають часів ще до Розколу.\n\nЯ хочу ці знання. Я зроблю заради них що завгодно.\n\nАле ці кам'яношкірі селюки тут не хочуть розповідати мені більше про Базальтія. Чи зможеш ти змусити земельних заговорити?",
    },
    [82442] = {
        title = "Зберегти лице",
        completion = "Робота Розтятих Ниток швидко просувається. Тож наші покровителі вирішили винагородити твою невпинну відданість.\n\nА тепер бери це і щезни. Ти привертаєш підозріливі погляди.",
    },
    [82446] = {
        title = "За тим, що мерехтить у пітьмі",
        completion = "Робота Розтятих Ниток швидко просувається. Тож наші покровителі вирішили винагородити твою невпинну відданість.\n\nА тепер бери це і щезни. Ти привертаєш підозріливі погляди.",
