    [89029] = {
        title = "Обслуговування фішками",
        description = "Чим можу прислужитися?",
    },
    [89032] = {
        title = "Прихильність Сингулярності",
        description = "Ти й далі доводиш нам, що є невід'ємною частиною нашої спільноти. \n\nЩоб ушанувати цей зв'язок, розшукай мене в Іскаарі — я приготував для тебе пакунок припасів на поміч.",
        objectives = "Поговори з дослідником Порожнечі Аномандером на Виючому хребті.",
        completion = "Знову ж таки, ми можемо лише безмежно тобі дякувати, і ці припаси не віддячать як годиться, та знай: твоя допомога важить для нас неймовірно багато!",
    },
    [89034] = {
        title = "Спалення Гіркоцвітів",
        description = "Рутаані, уражені Світлоцвітом, завзято розносять заразу селищем. У цієї рослини — виразні ознаки хвороби.\n\nЗнищ усі рослини, яких вони торкалися. Ми мусимо стримати пошесть!",
        objectives = "Знищ 6 заражених Світлоцвітом рослин у Гар'марі.",
        completion = "Молодець, {NAME}. Нехай Гар'мара знову стане мирним оазисом, яким була, коли ми прибули.",
    },
    [89035] = {
        title = "Уславлений серед гара'ті",
        description = "Гара'ті стали сильнішими завдяки твоїм звершенням.\n\nІди до Найнар. Вона подбає, щоб твої діяння не забулися, і вручить трофеї, гідні всього, що зроблено тобою.",
        objectives = "Поговори з Найнар у Лігві.",
        completion = "Гара'ті цінують те, що ти робиш для нас.\n\nВізьми це. Дар, який, сподіваємося, зміцнить тебе так само, як твоя допомога зміцнила Гарандар.",
    },
    [89056] = {
        title = "Скат-ракетбол, матч-реванш",
        description = "Знову час перевірити рефлекси нашого малюка.\n\nМоже, зіграєш іще одну партію в скат-ракетбол?",
    },
    [89057] = {
        title = "О-де-Фу від Фоксі",
        description = "{name}! Готов$p(ий:а) до нової пригоди у світі нюхової досконалості?\n\nУ мене готова ще одна суміш для терношипів. Ця партія точно вдалася краще за попередню.\n\nЗробиш ласку — сходиш випробуєш її?",
    },
    [89061] = {
        title = "Внесок на рахунок",
        description = "<Здолавши навалу пожирачів, ти витягну$p(в:ла) цей твердий згусток аніми зі шлунка їхнього ватажка. \n\nВе'нарі стане у пригоді — ним можна живити екокуполи.>",
    },
    [89062] = {
        title = "Внесок на рахунок",
        description = "<Здолавши навалу пожирачів, ти витягну$p(в:ла) цей твердий згусток аніми зі шлунка їхнього ватажка. \n\nВе'нарі стане у пригоді — ним можна живити екокуполи.>",
    },
    [89063] = {
        title = "Внесок на рахунок",
        description = "<Здолавши навалу пожирачів, ти витягну$p(в:ла) цей твердий згусток аніми зі шлунка їхнього ватажка. \n\nВе'нарі стане у пригоді — ним можна живити екокуполи.>",
    },
    [89065] = {
        title = "На всіх скатах у майбутнє",
        description = "Схоже, нам трапився ще один норовливий некроскат! Не хочеш його втомити?",
    },
    [89192] = {
        title = "Важкий робочий день",
        description = "У нас закінчуються щити Порожнечі. Потрібна твоя допомога, щоб виготовити новий.\n\nЗустрінься зі мною за межами купола, на сході. Змайструємо його разом.",
    },
    [89193] = {
        title = "Аратор",
        description = "Архієпископ Алонсус Фаол залишив повідомлення з проханням поговорити з тобою щодо проєкту, який має допомогти Аратору та Авангарду Світла.",
    },
    [89194] = {
        title = "Поворуши задком",
        description = "{name} — саме той {race}, якого я й хотів бачити! Потанцюй для ме... тобто для бджіл. \n\nА я просто подивлюся, як ти йдеш.",
    },
    [89195] = {
        title = "Дивний бзнес",
        description = "Здається, мій запас бджолиних каламбурів саме вичерпався, але бджіл із Долини Штормової Пісні мені все одно треба більше. Будь $p(медоласкавий:медоласкава), назбирай їх для мене, гаразд?",
    },
    [89197] = {
        title = "Скатарство",
        description = "А, ось і ти. Мені треба провести медичний огляд некроскатів, і не завадила б допомога з їхнім відловом. Може, підсобиш?",
    },
    [89198] = {
        title = "Хімчистка",
        description = "От халепа! К'арроки знову розбуянилися.\n\nНе помиєш їх як слід, щоб їхній природний аромат знову проступив?",
    },
    [89199] = {
        title = "Невелике доручення",
        description = "Даруй, що без люб'язностей: ситуація вимагає негайного втручання.\n\nТобі досить знати, що я Арадіс, коваль оберегів Сільвермуна. Ми — орден Магістрів, що підтримує захист міста.\n\nЯ одужую після... незначного бойового поранення, тож потребую допомоги із заряджанням мого посоха-руйнівника оберегів. Тобі заплатять, а може, і запропонують ще кілька нагод мені прислужитися.\n\nПодробиці розповім, поки працюватимеш — якщо, звісно, не працюватимеш нестерпно повільно.",
    },
    [89200] = {
        title = "Розплітання оберегів",
        description = "Донблейз тримає документи для шантажу у своєму кабінеті. Він, певна річ, щільно обвішаний оберегами.\n\nСамі обереги зроблені жалюгідно. Проте вона підживлює їх додатковою силою через арканні провідники, розставлені по всьому місту. Першу ланку цього ланцюга я знайшов і приніс сюди для вивчення.\n\nВона теж під оберегом, але слабким. Я припускаю: якщо руйнувати провідники по черзі, щити на кабінеті Донблейз стануть вразливими.\n\nВиведи їх з ладу, а тоді добудь документи. Зрозуміло?",
    },
    [89201] = {
        title = "Перехитрено",
        description = "Вхід до кабінету Донблейз — на терасі просто під нами.\n\nЯкщо моя магія може сягати так близько до її оберегів, значить, чари, що охороняють це місце, ослабли... як я і передбачав.\n\nЗруйнуй великий оберіг, що запечатує вхід, і знайди документи, які вона підробила, щоб обмовити мене. Після цього чекатиму на твоє швидке повернення до мого кабінету.",
    },
    [89202] = {
        title = "Розворушити гніздо",
        description = "Арадіс сказав, що шантаж — вигадка? Аякже. Він мітить на мою посаду. Ці розписки його знищили б.\n\nВін чорнокнижник, а щодо магії Скверни в нас є правила. Вона не заборонена, але користуватися нею слід обачно. Арадіс не з обачних. Зловживання магією, несанкціоновані демони, контрабанда Скверни, хабарі... Список його злочинів довгий.\n\nАле не мусиш вірити мені на слово. Арадіс нажив у місті чимало ворогів. Якщо знайдеш у Завулку чоловіка на ім'я Джейт, він розповість тобі все про нашого любого чорнокнижника.",
        objectives = "Допитай 8 щурів Завулку про місцеперебування Джета.",
    },
    [89203] = {
        title = "Взаємна вигода",
        description = "<Джейт змахує рукою, уриваючи твої пояснення.>\n\nГаразд, тебе прислала Донблейз. Отже, є робота. Не дивно, що вона не хоче бруднити мантію, спускаючись у Завулок особисто. Ті, хто нас наймає, ніколи цього не роблять.\n\nТам, на верхах Сільвермуна, всі штрикають одне одного в спину. А коли йдеться про справжній ніж, вони платять нам, щоб ми зробили це за них. Вони отримують владу, за якою женуться, а ми — досить монет, щоб прожити ще тиждень.\n\nТо в чию спину цього разу встромлять ножа?",
        objectives = "Покажи Джету викривальні документи про Арадіса.",
        completion = "Минулого тижня він теж намагався мене схопити. Я штрикнув його в живіт, перш ніж він утік.\n\nЯ погнався за ним, але його лігво біля гавані було захищене магією Скверни. Якщо Світанкове Полум'я знайде спосіб пробратися всередину, я залюбки його прикінчу.",
    },
    [89204] = {
        title = "Знижка спритних рук",
        description = "Арадіс віддав тобі свій руйнівник оберегів? От йолоп. Такі штуки продають на чорному ринку як відмички. Коштують дорого, але їх треба налаштувати на магію, яку збираєшся ламати, а це непросто.\n\nСхоже, твій розряджений. Це можна виправити. Якщо поцупимо кілька магічних цінностей по місту, мій приятель нагорі розчаклує їх і наповнить руйнівник магією Скверни.\n\nТоді Арадісу вже ніде буде сховатися.",
        objectives = "Допоможи Джеетові поцупити магічні речі з крамниць на Базарі.",
        progress = "Це найлегша частина.",
        completion = "Чисто й гарно. Я краду, щоб звести кінці з кінцями, ще з дитинства, але напарника по злочину маю нечасто.",
    },
    [89205] = {
        title = "Виточити ключ",
        description = "Я переповів Заніену всю історію. Він уже давно навчає чорнокнижників — і якщо хтось і ненавидить недбалих, то це він.\n\nВін упевнений, що зможе перезарядити руйнівник оберегів. Виконуй його вказівки — а тоді можна буде вирушати.",
        objectives = "Налаштуй Зламувач Оберегів на магію скверни.",
        progress = "Тепер цей посох має зламати цей оберіг.",
        completion = "Я здивуюся, якщо Арадіс іще не засів тут. Та навіть якщо ні, певен, ми скоро його побачимо.\n\nУ такі вигадливі обереги завжди вплетено сигнали тривоги.",
    },
    [89206] = {
        title = "Злам і проникнення",
        description = "Чуєш? Звук наче знизу. Ніби комусь боляче.\n\nОстаннє викрадення із Завулка було зовсім нещодавно. Можливо, саме тут він тримає людей, яких забрав.\n\nМоїх людей. Моїх друзів.\n\nНавіть якщо Арадіс не покажеться, ми не дозволимо йому тримати їх тут. Знеси цей оберіг. Заходимо.",
        objectives = "Знищ магію Скверни, що захищає особистий кабінет Арадіс.",
        completion = "<Джает намацує пульс на шиї Сарві, тоді гнівно зітхає.>\n\nВона вже мертва. Я знаю її брата. Подбаю, щоб її повернули йому.\n\nАле спершу ми пустимо Арадіс кров.",
    },
    [89207] = {
        title = "Щури кусаються",
        description = "Я знаю всіх цих людей. Вони робітники, а не бійці. Арадіс полював на тих, хто не міг дати йому відсіч. Тому він і втік, коли спробував схопити мене й зрозумів, що обрав не ту ціль.\n\nПісля галасу, який ми зчинили, він точно знає, що ми тут.\n\nБудь напоготові. Щойно він покажеться — йому кінець.",
        objectives = "Вбий магістра Арадіса.",
        completion = "Завулок завжди буде в небезпеці, доки Сільвермун заплющує на нас очі.\n\nАле наразі ми трохи в більшій безпеці. Туди йому й дорога.",
    },
    [89208] = {
        title = "Те, що нам належить",
        description = "Усі, хто тут, мають оклигати. Сарві... Я віднесу її назад до Завулка. Якщо залишимо її тут, варта просто накаже викинути тіло.\n\nСподіваюся, з Арадісом вони вчинять так само, та певен, що ні.\n\nХодімо. Поговорімо з Донблейз і заберімо нашу платню. Я пам'ятаю, де її кабінет.",
        objectives = "Повідом Магістра Дунблейза, що роботу виконано.",
        completion = "Приємно було попрацювати з тобою, {NAME}.",
    },
    [89209] = {
        title = "Бз-з-з",
        description = "Ці бджоли — справжні робочі коні... робочі бджоли? Вони ж бджоли-трудівниці, тож, мабуть... ох, вибач, щось я відволікаюся.\n\nКілька бджіл геть заморилися. Повернеш їх до вулика?",
    },
    [89210] = {
        title = "Фотографія — королева жанрів",
        description = "Гаразд, {name}. Тримай оцю камеру й оцю плівку. Тобі не первина. Час братися за документацію!\n\nЗнаю, ти вже аж дзижчиш від нетерпіння, але зараз головне — бджолина зосередженість.",
    },
    [89212] = {
        title = "Королівський фотограф",
        description = "<Ом'талад зосереджено робить кілька знімків самого себе.>\n\nО! {name}! Нам треба оновити записи про терношипів.\n\nЦя камера, яку я... випробовував, схоже, працює справно. Будь ласка, сходи онови нашу документацію.",
    },
    [89213] = {
        title = "Політ фантазії",
        description = "Нам потрібні нові знімки к'арроків для наших архівів. Будь ласка, зроби кілька для нас, поки будеш в екокуполі.",
    },
    [89221] = {
        title = "Залишити чи залистити?",
        description = "Я прокинулася сьогодні й подумала собі: «Та таця з їжею, що {name} $p(виставив:виставила) для колінників, була чудова. Гадаю, колінникам сподобалося б, якби {name} $p(зробив:зробила) так іще раз».\n\nЧому б тобі не влаштувати це, га?",
    },
    [89222] = {
        title = "Залишок Азероту",
        description = "На перший погляд це здається кристалізованим уламком життєвої крові Азероту. Якщо вдивитися в уламок, постають видіння війни на знайомих фронтах, незліченні життя, скуті битвою. Гуркіт буремних штормів і розбитих хвиль починає накривати тебе, а тоді враз обривається в моторошній тиші.\n\nКул-Тірас кличе тебе.",
        completion = "Уламок Азероту з часів чвар і розбрату. Такому неспокійному артефакту не місце на шляхах часу — дякую, що поверну$p(в:ла) його.",
    },
    [89223] = {
        title = "Залишок Азероту",
        description = "На перший погляд це здається кристалізованим уламком життєвої крові Азероту. Якщо вдивитися в уламок, постають видіння війни на знайомих фронтах, незліченні життя, скуті битвою. Гуркіт буремних штормів і розбитих хвиль починає накривати тебе, а тоді враз обривається в моторошній тиші.\n\nЗандалар кличе тебе.",
        objectives = "Принеси Залишок Азероту Чурбро в Дазар'алор.",
        completion = "Залишок Азероту з часів конфліктів і чвар. Такому неспокійному артефакту не місце в часоплинах — дякую, що поверну$p(в:ла) його.",
    },
    [89230] = {
        title = "Закоханий, а не Боєць",
        description = "Старійшини готують свято подяки лоа. Я хочу запросити Намаджі піти зі мною, але...\n\nЗа традицією залицяльник має піднести дарунок, що доводить його воїнську доблесть. А боєць із мене кепський, і решта глузує з мене через це.\n\n<Каґара понуро схиляє голову.>\n\nМоже, ти мені допоможеш? Я знаю, що Намаджі завжди мріяла про намисто із зуба трешадона. Такі роблять корчедіни, але мають їх лише найсильніші.\n\nЗнайдеш таке намисто й передаси їй від мого імені?",
        objectives = "Здобудь Намисто із Зубів Трешадона в корчедінів на Обширі Акіл'зона.",
        progress = "Тобі щось треба?",
        completion = "Це від Каґари? Я завжди мріяв про таке!\n\nЯ залюбки піду з ним на фестиваль. Спершу докінчу тут свою роботу, а тоді сам йому й скажу.\n\nДякую, що передав це!",
    },
    [89231] = {
        title = "Боєць, а не Закоханий",
        description = "Ти йдеш на свято лоа? Від молодих тролів, як-от я, чекають, що вони запросять із собою того, хто їм до серця. І піднесуть дарунок на доказ того, що гідні.\n\nЯ хочу піти з Намаджі. Боєць із мене чудовий, але ж і інших воїнів, охочих піти з нею, не бракує!\n\nВони даруватимуть їй трофеї та здобич. А я буду інакшим.\n\nГадаю, їй сподобався б головний убір, та я й гадки не маю, як його змайструвати. Зробиш для мене убір із пір'я і віддаси їй?\n\nПір'я знайдеться в Обширі Акіл'зона.",
        objectives = "Збери 8 Орлиних Пер на Обширі Акіл'зона й зроби Головний Убір Амані.",
        progress = "Ще один дарунок?",
        completion = "Чудовий головний убір! Від Зак'каша? Ох...\n\n<Намаджі стривожено супиться.>\n\nІ Зак'каш, і Каґара хочуть, щоб я пішла з ними на фестиваль. Що ж мені робити?",
    },
    [89233] = {
        title = "Любовний Трикутник",
        description = "Здається, у нас проблема: і Каґара, і Зак'каш хочуть піти зі мною на свято! Кого ж обрати?\n\nОбидва мені до вподоби. Прошу, {name}, поможи мені! Що скажеш?",
        objectives = "Допоможи Намаджі вирішити, з ким піти на фестиваль.",
        completion = "Дякую, що допоміг мені. Каґара, Зак'каш... Сподіваюся, після цього ми всі лишимося друзями.\n\n<Намаджі насуплює брови, але потім усміхається.>\n\nТож піду-но я скажу своєму супутнику на фестиваль про моє рішення! Ще раз дякую.",
    },
    [89238] = {
        title = "Повторний огляд",
        description = "Обстеження к'арроків може дати чимало цінних медичних даних.\n\nБудь ласка, візьми диск-конденсатор, щоб зменшити їх, а тоді позбирай малят для зручного перенесення.",
    },
    [89240] = {
        title = "Сон-сон-сон-сон-сонне царство!",
        description = "Нам треба перевірити, як розвиваються колючохвости. Чи не зробиш ласку, зібравши ще зразків крові?\n\nЯк і раніше, скористайся дротиками, щоб приспати їх, а тоді забери дротик із кров'ю.",
    },
    [89241] = {
        title = "Усе вище й вище",
    },
    [89242] = {
        title = "Хочу золотий слиз!",
        description = "Схоже, наші доглядачі знову занедбали свої обов'язки.\n\nВізьми всмоктувальний пристрій. Прибери грудки. Відріжу тобі відсоток від виторгу.",
    },
    [89249] = {
        title = "Здолані",
        description = "Ми спізнилися. Навіть усієї нашої сили разом виявилося замало.\n\n<Аратор сторожко озирається через плече. Тоді присідає й кладе руку Аллерії на плече. У відповідь вона лише хрипко видихає.>\n\nВідступаймо. Поки ми йшли за Лотраксіоном, рен'дорей досліджували ці нетрі. Можливо, десь поблизу знайдеться їхній табір.",
        objectives = "Знову зустрінься з Аратором у Локус-Точці.",
        completion = "Навіть сили наару не вистачило...",
    },
    [89250] = {
        title = "Палаюча гума",
        description = "<Мало що так бадьорить, як нестримна швидкість, і мало що шанують так, як G-99 «Шибайголова» в гаражі бабусі Талулли.\n\nМоббер напевне знатиме, як налаштувати твою машину з новою деталлю.>",
    },
    [89251] = {
        title = "На повних обертах!",
        description = "Чим можу прислужитися?",
    },
    [89252] = {
        title = "Потрібен поштовх?",
        description = "Чим можу прислужитися?",
    },
    [89254] = {
        title = "Клац-клац",
        description = "Світлини з колінниками стали справжнім хітом. Нам потрібно більше таких для реклами.\n\nВибач, {name}. Цього разу колінники в капелюшках затребуваніші за тебе. Але не сумуй. Принаймні тобі платять, та ще й обличчя твоє бачать усі, еге ж?\n\nА тепер берися клацати.",
    },
    [89263] = {
        title = "Твоя частка здобичі",
        description = "Це ти, {name}? Маю дещо для тебе.",
    },
    [89267] = {
        title = "Таємнича сутність",
        objectives = "Вбий ефіріалів або гравців\nВбий бійця Тіньової варти\nВбий ефіріала\nВбий ефіріала",
    },
    [89268] = {
        title = "Втрачені Легенди",
        description = "Поміж цих стін спочивають реліквії — мовчазні й забуті, їхні історії затерті часом.\n\nШлях до повернення нашого минулого ясний: віднеси реліквію до святилищ і ступи у відлуння її історії. Видіння вестимуть тебе — ти пройдеш оповідь від початку до кінця й знову вдихнеш життя у пам'ять.\n\nЯкщо бажаєш віддати цій справі частку свого духу — обери реліквію, щоб пробудити її історію.",
        objectives = "Обери реліквію для пошуку.",
        completion = "Хай буде так. Твій шлях визначено. Правда цієї реліквії чекає на тебе.",
    },
    [89271] = {
        title = "Мій син",
        description = "Хвилинку, {name}. У мене особиста справа. Прошу тебе: розшукай мого сина, Аратора. Він лицар ордену Срібної Длані, вправний паладин.\n\nЯ знаю: його, певно, теж покликали. Його віра міцна. Світло хотіло б, щоб він був тут і бився проти Ксал'атат.",
        objectives = "Знайди Аратора й приведи його до Тураліона на Шпиль Світла.",
        completion = "Ти знайш$p(ов:ла) його? Дякувати Світлу!\n\nНам не до відволікань. Мені потрібен Аратор тут, разом зі зібраним військом, цілком зосереджений на штурмі проти Ксал'атат.",
    },
    [89274] = {
        title = "Бридке дзеркало",
    },
    [89276] = {
        title = "Легкі закуски",
        description = "Класика лишається класикою недарма, серденько. Хіба ж можна влаштувати пристойний прийом без добірної мани, якою гості могли б посмакувати?\n\nМагістри могли б принести свою, але мана найсмачніша щойно висмоктана. Манавирми на півдні Лісу Вічної Пісні мають особливо декадентський блиск — як на мене, просто чарівний.\n\nБудь золотком, назбирай нам трохи.",
    },
    [89277] = {
        title = "Освітити простір",
        description = "Я поділяю любов нашого дорогого Салтеріла до старовинних світильників, але чари освітлення, до яких він удається, надто буденні для такої урочистої нагоди.\n\nМої Магістри створять значно ефектніші чари. Просто назбирай для мене волокон Світлоцвіту, а я звелю переробити їх на реагенти для заклять.\n\nЕфект буде дивовижний.",
    },
    [89278] = {
        title = "Не забуваймо про обов'язок",
        description = "Хоч двір і вимагає нашої уваги, про обов'язки забувати не можна. Наші гості почуватимуться значно вільніше, знаючи, що оборона Лісу Вічної Пісні непохитна.\n\nМагістрам доручено пильнувати захисні чари рунокаменів по всьому Лісі Вічної Пісні. Будь ласка, обійди їх для нас і сповісти, чи не потребує котрийсь з оберегів нашої уваги.",
    },
    [89285] = {
        title = "Прихильність Салтеріла",
        description = "Чим завдячую такій приємності?",
    },
    [89286] = {
        title = "Прихильність Салтеріла",
        description = "Чим завдячую такій приємності?",
