    [89293] = {
        title = "Особливе доручення: під наглядом",
    },
    [89294] = {
        title = "Особливе доручення: спільні погляди",
    },
    [89295] = {
        title = "Полум'я палає вічно",
        description = "Оці Сурекі й справді вперта зграя! На їхню впертість ми маємо відповісти своїми клинками.\n\nЧи можемо ми й надалі розраховувати на твою підтримку в прийдешніх битвах?",
