    [90601] = {
        title = "Збір сяйногрибів",
        description = "Ру'ґар розповідав мені, як прокрадався до сусідньої печери по сяйногриби. Схоже, вони конче потрібні для розвитку насіння тла'так, яке він вирощував. Назбираєш там цих грибів?\n\nА, і ще: Ру'ґар згадував, що зірвані гриби виявляють дивні властивості. Не знаю, що він мав на увазі, але про всяк випадок будь напоготові.",
        objectives = "Назбирай 6 сяйногрибів.",
        progress = "Ру'ґар розповідав, що сяйногриби, домішані в землю, де він садив рослини, робили врожай щедрішим. Як він до цього додумався — навіть не уявляю.\n\nЯ хочу продовжити справу Ру'ґара. А раз ми вже тут, варто зібрати все, що зможемо.",
        completion = "О, з поверненням! І скільки сяйногрибів! Чудово. Сподіваюся, обійшлося без дивних пригод.\n\nДякую за всі ці гриби. Щоб відтворити методи Ру'ґара, мені знадобиться час, але тепер я вірю, що ми зможемо продовжити його справу.",
    },
    [90602] = {
        title = "Ґомфуста",
        description = "Попрошу тебе про останню послугу. Чимало фунґаріан згадували свого ватажка, Ґомфусту. Схоже, саме він стоїть за сплеском їхньої люті, і саме через нього вони крадуть насіння.\n\nКоли будеш у печері, знайди його і знищ. Без Ґомфусти, який смикає за ниточки, решта фунґаріан порине в хаос і вже не зможе так вправно влаштовувати засідки.",
        objectives = "Убий Гомфусту.",
        progress = "Фунґаріани не завжди такі люті й агресивні. Певно, це Ґомфуста їх штовхає. Схоже, саме він заражає живих істот спорами.\n\nКоли його не стане, фунґаріани, можливо, повернуться до звичної рівноваги.",
        completion = "Що це? Нотатки Ру'ґара про його досліди з вирощування!\n\nЦе чудово. Тепер я зможу спробувати відтворити його роботу.\n\nІ з Ґомфустою покінчено — гарна робота. Нехай це посіє розбрат серед фунґаріан, а мандрівникам на дорогах стане безпечніше.",
    },
    [90615] = {
        title = "Злоби Тобі!",
        description = "Ти виглядати... інакше! Бувати колись у Ямі Злоби?\n\nЯма Злоби — чудове місце! Повно бійок, і вигуків, і фунґаріан. А ще гниття!\n\nБолетус завжди шукати сильних істот, щоб бути вбиті в Ямі Злоби. Або щоб робити так, щоб інші бути вбиті.\n\nТи сильна істота? Треба йти в Яму!",
        objectives = "Поговори з Болетусом біля Ями Злоби.",
        completion = "Ти виглядати, як дати сильний бій, перш ніж почати гнити.\n\nБуло б дуже цікаво!",
    },
    [90616] = {
        title = "Є Сила?",
        description = "Ти виглядати сильно.\n\nТреба випробувати себе на нашій арені.\n\nПобачити, чого ти вартий проти сильних фунґаріан.",
        objectives = "Знищ ворогів у Ямі Злоби.",
        progress = "Багато фунґаріан дивитися бої.\n\nЗавжди так захопливо!",
        completion = "Ми, е-е... в тебе так багато сили.\n\nЯк, е-е...? Ти дуже інакше.\n\nНавчити фунґаріан бути інакше, як ти?",
    },
    [90617] = {
        title = "Кілька Веселих Грибців",
        description = "У тебе багато сили, {name}.\n\nБудеш навчати фунґаріан битися?\n\nБагато чого ми могти навчитися від тебе.\n\nБагато фунґаріан дивитися битву.\n\nСпитай, чи хотіти вони бути сильними в Ямі.",
        objectives = "Завербуй 3 фунґаріан.",
        completion = "Знайти, кого вчити?\n\nПерший крок — битися, побачити, що вміти!",
    },
    [90619] = {
        title = "Що Їх Не Вбиває",
        description = "Мати команду — тепер готові битися.\n\nВеди свою команду на вільне місце. Тренувальний бій — і побачити, що вміти.",
        objectives = "Проведи тренувальний бій із товаришами по команді.",
        progress = "Ми битися з тобою?\n\nТи сильно.\n\nБитися разом — добре тренування, щоб бути сильно.",
        completion = "Очі відкриті, {NAME}! Ми теж могти бути сильні.\n\nМи будемо сильні, як ти!\n\nКоли боляче, фунґаріани рости сильніші. Ти бити багато — ми ставати сильніше багато.\n\nТреба йти казати Болетусу: ми готові!",
    },
    [90620] = {
        title = "На Ринг",
        description = "TeamName? Непогано. Мені подобатися!\n\nТи і TeamName спускатися вниз, а ми казати слова.\n\nВи битися з Бурею Спор. Якщо перемогти — битися зі Зіткненням Шапок.\n\nЯкщо перемогти — битися з Грибною Силою.\n\nЗавжди-переможці — Осяйна Варта. Їх вам не перемогти.\n\nНе тікати з рингу! Тікати — це великий, великий програш.",
        objectives = "Іди битися зі своєю командою.",
        completion = "Бракко бути певен, що досить сильний. Бо тренуватися із сильним {NAME}!\n\nАле Бракко боятися споролітунів. Вони з'їсти шапку!\n\nБракко дуже сумний, що підвести {NAME}.\n\nЗіні й Туктук теж. Усі втекти.\n\nМи втекти — і Грибне Братство програти.\n\nАле як не втекти, коли споролітуни нападати?",
    },
    [90621] = {
        title = "Мандри Маленьких Героїв",
        description = "Ти їх навчати. Чому вони втекти?\n\nУсі фунґаріани дуже хотіти побачити, чи може {race} навчити фунґаріан бути сильними.\n\nТи спробувати ще раз, добре?\n\nСпершу зробити те, що треба, щоб вони бути готові.",
        objectives = "Допоможи кожному з команди подолати свої перепони.",
        completion = "Уже закінчити вчити? Подивімося, що вміти Грибне Братство.",
    },
    [90622] = {
        title = "Ще Не Переможені Чемпіони",
        description = "{name}, PHTeamname тепер виглядати сильнішими! Більш готовими. Сподіватися, вони більше не втечуть.\n\nНаступний бій — проти Осяйної Варти. Осяйна Варта завжди ніколи не програвати.\n\nСподіватися, твоє тренування зробити бій кращим, перш ніж TEAMNAME програти.\n\nБуде весело для дивитися!",
        objectives = "Увійди в Яму Злоби й переможи Осяйну Варту.",
        progress = "Яма Злоби завжди шукає нових чемпіонів, {NAME}. Та досі ми лише знову й знову знаходили старих.",
        completion = "Ого, шок! Спороприсяжні побити Осяйну Варту!\n\nЯ знати, що {NAME} — сила. Але не знати, чи тренування вистачити.\n\nЖоден фунґаріан не ставити на Спороприсяжних. Ми не думати, що Осяйну Варту можна побити.\n\nТепер кожен фунґаріан знати: {NAME} — найкращий вчитель сили!",
    },
    [90630] = {
        title = "Невеликий жмут кристалів",
        objectives = "Ще одне завдання виконано. Спілка дякує тобі за старання. Засновник виділив фонд, щоб заохочувати таку ініціативність.",
        completion = "Ще одне завдання виконано. Спілка дякує тобі за старання. Засновник виділив фонд, щоб заохочувати таку ініціативність.",
