    [90843] = {
        title = "Допомога Драконовим Островам",
        description = "Час нам розійтися. На мене чекають нагальні справи далі, у глибині Драконових островів, у місцині під назвою Лазуровий Простір.\n\nНалейдея Ріверґлім з Драконолускої експедиції потребує твоєї допомоги.\n\nЩасливої дороги, {name}. З нетерпінням чекаю нашої наступної зустрічі!",
        objectives = "Зустрінься з Налейдеєю Ріверґлім, щоб почати свою пригоду на Драконових Островах.",
        completion = "Як ся маєш? Нам не завадять зайві руки в дослідженні Драконових Островів!",
    },
    [90844] = {
        title = "Напади ясності",
        description = "Поки я тут причаївся, я слухав.\n\nСхоже, у цієї Тіньової Варти назріває невеличкий бунт. Дехто з ефіріалів поводиться дивно. Їх зганяють докупи й допитують.\n\nЩо ж тут коїться?\n\nПрикінчи кількох бійців Тіньової Варти й перехопи їхні донесення. Я розшифрую все, що ти принесеш.",
        objectives = "Убий ефіріалів на Верхньому подвір'ї Ефіріуму та збери 8 одиниць допитаних даних.",
        progress = "Я думав, що Порожнеча, яка струменить крізь цих ефіріалів, поглинає все.\n\nІ все ж, схоже, дехто здатен опиратися її безмежній темряві.",
        completion = "Щось розпалило бунтівний вогонь у декому з Тіньової варти.\n\nПогляньмо, що ще нам вдасться знайти.",
    },
    [90845] = {
        title = "Далекі спогади",
        description = "Я склав клятву шанувати свою родину... нелегко, коли твою сестру навернули до Тіньової Варти. Її тут може й не бути, але слід Тіньової Варти привів мене саме сюди.\n\nЯ шукаю намисто, що належало моїй сестрі Вераан. Дивна річ... я помітив, що довкола розкидано чимало к'арешських родинних реліквій. Схоже, Тіньова варта прагне знищити будь-які згадки про наш рідний світ.\n\nПринеси мені кілька цих дрібничок і цяцьок — погляну, чи не впізнаю котрусь.",
        objectives = "Збери 8 пам'ятних речей із К'ареша на Верхньому подвір'ї Ефіріуму.",
        progress = "Ці пам'ятні речі — одні з останніх решток нашого рідного світу.\n\nСпогади, що в них живуть, могутні. Тіньова варта недарма їх боїться.",
        completion = "Я справді впізнаю деякі з цих речей! Вони належали близьким друзям і рідні.\n\nЯкщо намисто моєї сестри десь і знайдеться, то саме тут.",
    },
    [90847] = {
        title = "Правда від влади",
        description = "Завдяки здобутим відомостям ми дізналися, що бунтівниками займається допитувач Ксен'даан.\n\nКажуть, після допиту бунтівних ефіріалів кудись забирають, щоб із ними «розібратися».\n\nГоловний допитувач напевно знає більше. Якщо з'ясуємо, куди відвели бунтівників, для них ще може бути надія.",
        objectives = "Убий допитувача Ксен'даана на Верхньому подвір'ї Ефіріуму, щоб з'ясувати, де тримають бунтівників.",
        progress = "Ризикуючи піддатися марним надіям... як гадаєш, чи може серед них бути Вераан?\n\nЧи зміг би я стати перед нею тепер? Після звірств, які вона скоїла в ім'я Порожнечі?",
        completion = "{name}! Це намисто належить Вераан! Вераан і є Похмуроспів!",
    },
    [90848] = {
        title = "Це вона розпалила вогонь",
        description = "Вераан напевно серед бунтівників, яких забрали на Заставу Тіньової варти.\n\nЇї вогняна вдача сповнює мене гордістю!\n\nЯ прийшов сюди, готуючись до своєрідного прощання. Знайти власну сестру я аж ніяк не сподівався.\n\nМожливо, ще не запізно, {name}!",
        objectives = "Зустрінься з Кіфааном на Заставі Тіньової варти.",
        completion = "Нехай Тіньова варта і спотворила сутність Вераан, але цей бунт дає мені надію.\n\nЧи можна вирвати незгодних із лещат Порожнечі цілком?",
    },
    [90849] = {
        title = "Гра світла",
        objectives = "Сяйливі оберіги активовано",
    },
    [90851] = {
        title = "Пожирають своїх",
        description = "Схоже, Тіньова варта без жодних докорів сумління садить у клітки й катує своїх же.\n\nНайменше мені хочеться нового насильства серед народу К'арешу, але краще вони, ніж ми.\n\nЗірви їхню операцію — знешкодь кількох бійців Тіньової Варти.",
        objectives = "Убий 12 інженерів і наснажувачів Тіньової варти на Заставі Тіньової варти.",
        progress = "Ступені зла — ось питання, яке мені й на думку не спадало обмірковувати.\n\nРятуймо, кого можемо, а зважувати, хто чого вартий, будемо потім.",
        completion = "Насильство рідко буває приводом для радості, але я тішуся, що ми бодай сповільнили те, що тут коїться.",
    },
    [90852] = {
        title = "Техномагнітний імпульс",
        description = "Зрадників тримають у стазисних камерах.\n\nЯ вже бачив такі клітки. Їхня конструкція ефективна, але крихка: найменше коливання енергії — і вони виходять з ладу.\n\nЗнайди розкидані довкола посудини з тріскучою енергією та жбурляй їх у стазисні камери. Влучиш точно — виведеш камери з ладу і звільниш зрадників.",
        objectives = "Жбурляй посудини з тріскучою енергією в арканні в'язниці, щоб звільнити ув'язнених зрадників.",
        completion = "Дякую, {name}. Завдяки тобі я знову побачив сестру. За це я довіку перед тобою в боргу.\n\nВераан змінилася. Стала гнівною. Її мучить відчай. Тож ступаймо обережно.",
    },
    [90858] = {
        title = "Пригноби гнобителів",
        description = "Нас привели сюди на розправу — постати перед гнівом душезв'язувачки Д'заар. Вона командує тутешньою Тіньовою вартою. Силою Войдшторму вона обертає душі на енергію, яку сама й поглинає.\n\nВона та її поплічники — зрадники нашого народу!\n\n<Вераан кривиться від болю: її тілом струмує Порожнеча.>\n\nЇх треба зупинити... їхні пристрої — розібрати... їхній волі — покласти край...\n\n{name}... знищ їх усіх!",
        objectives = "Зірви операцію: вбивай ефіріалів, руйнуй Крихкі енергетичні труби та підривай Нестабільні енергетичні резервуари.",
        progress = "<Вераан тремтить від люті.>\n\nЦі братовбивці ладні були жертвувати своїми ж. І заради чого? Волі Ксал'атат?",
        completion = "Я відчуваю Кіфаанове вагання щоразу, коли наші погляди зустрічаються. Він боїться мене...",
    },
    [90860] = {
        title = "Скинути ярмо",
        description = "Таких бунтівників, як ми, приводять до душезв'язувачки Д'заар. Зрадників вона не терпить.\n\nНашою долею було стати жертвами — наші душі мали обернути на енергію. Д'заар з арканною майстерністю орудує провідником, що поглинає ці душі!\n\nЧасу обмаль. Я відчуваю, як Порожнеча тисне зсередини. Якщо вже нам судилося піти з цього життя в бою — Д'заар та її провідник підуть разом з нами!",
        objectives = "Убий душезв'язувачку Д'заар на Заставі Тіньової варти.",
        progress = "Тиск наростає... час майже настав...\n\nТа й, зрештою, чи заслуговую я взагалі жити? Що казатимуть про мене — про бійця Тіньової варти, — коли все скінчиться?\n\nЯк гадаєш, чи зможе Кіфаан колись мені пробачити?",
        completion = "Тіньова варта дістала по заслузі.\n\nАле і я не безгрішна, {name}. Навіть тепер у мені жевріють тіні.\n\nЗадля безпеки всіх мені краще піти.",
    },
    [90861] = {
        title = "Ті, що лишилися",
        description = "Після загибелі Ксал'атат рештки наших сил збираються біля Темного Колодязя, щоб вирішити, що нам робити із залишками Порожнечі.\n\nМи не можемо терпіти присутність такої кількості темної енергії. Дехто з наших найсильніших заклинателів і найученіших мудреців гадає, що, можливо, має рішення, але нам знадобилася б твоя допомога.\n\nПрошу, приєднайся до Аратора біля Темного Колодязя за першої ж нагоди.",
        objectives = "Розшукай Аратора біля Темного Колодязя.",
        completion = "Дякую, що прийшов. Доречно, що ти з нами цього дня.",
    },
    [90862] = {
        title = "У час нужди",
        description = "Останні з-поміж інших ельфійських очільників повернулися, несучи з рідних земель сили, що допоможуть нам очистити Темний Колодязь.\n\nВойдшторм більше не б'є по Темному Колодязю, та його ще потрібно зцілити.\n\nБудь ласка, зустрінься з іншими очільниками й перекажи їм, що ми готові.",
        objectives = "Поговори з кожним із ельфійських очільників.",
        completion = "Ельфи всіх народів цілі віки черпали з колодязів магію, життя та власну сутність. Навіть драконові аспекти не могли б перевершити наше знання цієї години.",
    },
    [90866] = {
        title = "Універсальна Мова",
        description = "Щоб додому — вода життя. Треба.\n\n<Тул'амар поглядом намагається зрозуміти, чи ясно тобі, про що йдеться. Помовчавши, вона проколює собі кінчик пальця вістрям посоха й показує тобі краплину власної крові.>\n\nЦе. Тутешнє. Воно з битви. З битви — Порожнеча. Порожнеча — сила. З силою — додому.\n\n<Вона вискалює ікла в перебільшеному гарчанні, а тоді зображає удар пазурами.>\n\nВода життя. Зі звіра. Багато. Так?",
        objectives = "Збери кров із чудовиськ на північ від Нічного Рову.",
        progress = "Якщо тебе помітять доманаари, не дай їм піти за тобою сюди.",
        completion = "Я б доручив це нашим людям, якби бойові ями не зламали стількох тілом і духом.\n\nПогляньмо, чи моя теорія правильна.",
    },
    [90867] = {
        title = "З темряви — світло",
        description = "Ми не дозволимо, щоб Сонячний Колодязь знову осквернили. Цей Темний Колодязь має змінитися, але змінитися на щось таке, від чого ми вже не залежатимемо так сильно. Нам не потрібно, щоб цей колодязь був принадою для стількох інших сил, які нищать світ.\n\nНі, сьогодні ми зцілимо Темний Колодязь і зробимо з нього щось нове. Дай мені знати, коли будеш готовий.",
        objectives = "Проведи ритуал, щоб очистити Темний Колодязь.",
        completion = "Узри Колодязь Світанку. Хай його води ніколи не знають скверни. Хай він стоїть як нагадування про все, що ми втратили, і як натхнення до того, ким ми можемо стати.",
    },
    [90869] = {
        title = "Уся справа в образі",
        description = "Отже, начальство з відділу маркетингу каже, що тобі потрібен гарний партнер, аби пом'якшити твій образ... ну знаєш, оте «вбиваю всіх навколо заради золота».\n\nОн там стоять двоє гоблінів, схвалених фокус-групою й готових на все, тож іди обирай. Сассі займеться паперами.\n\nО, не дивись на мене так. Вам треба вічно кохати одне одного лише на людях. Щойно камери вимкнуть — усім байдуже. Це чудово вплине на твою репутацію!",
        objectives = "Поговори з Сассі Гардренч, щоб обрати «маркетингового партнера».",
        progress = "Ну ж бо, це ж не ракетна хірургія. Обери будь-кого, з ким хочеш красуватися на обкладинках журналів.",
        completion = "Ось так! Гарно й штучно — саме таким і має бути найкращий маркетинг.\n\nІ я щойно закінчила папери щодо іншого великого оновлення твого образу. Гадаю, тобі дуже сподобається!",
    },
    [90870] = {
        title = "Збираємо харч",
        description = "А, ти тут! Хмільне свято настало, а в нас невеличка проблема. Яке ж бенкетування без їжі, а кілька докучливих гозенів вирішили, що красти наші мішки з харчем — це весело. Певно, вони просто хочуть набити власні черева, але нам це ламає всі плани!\n\nОсь що мені від тебе треба: вистеж тих гозенів і забери мішки, які вони поцупили. Цілком можливо, що кілька мішків просто валятимуться на землі. Коли повернешся, склади знайдені мішки он у той віз.",
        objectives = "Збери мішки зі складниками Хмільного свята та склади їх у віз.",
        progress = "Без тих складників бенкету не буде!",
        completion = "О, таки вдалося! Кухарі будуть задоволені.",
    },
    [90871] = {
        title = "Угода Сільверсанів",
        description = "Чемпіоне.\n\nПісля довгих обговорень, перемовин і навіть деяких криків та трьох дуелей Сонцехапи й Срібний Союз нарешті обрали шлях, що визначить майбутнє нас обох.\n\nЗважаючи на твою допомогу, що привела нас до цього дня, ми хотіли б, аби ти бу$p(в:ла) тут за свідка, поки ми укладаємо й підписуємо наші мирні угоди. Чи зробиш нам честь запалити Полум'я Спомину?",
        objectives = "Допоможи в укладенні Угоди Сільверсанів.",
        progress = "Дивні часи. Воістину дивні часи.",
        completion = "Звершилося. Сьогодні починається перший день Угоди Сільверсанів. Хай клятви, під якими ми сьогодні підписуємося, єднають нас у скрутні часи чинити правильно.",
    },
    [90872] = {
        title = "Просякнутий Наскрізь",
        description = "<Тул'амар відводить погляд від залитого кров'ю і геть зніченого Джураса — до порталу, що мерехтливо оживає. Вона зчитує його своїми арканними силами.>\n\nДобре. Кров — жорсто... жорстока? Жорстоке — сила. Треба більше. Тепер — брати й сестри.\n\n<Вона вказує на кров, що при тобі, а тоді на своїх людей. Багато хто з них поглядає на тебе насторожено.>\n\nТобі можна. Я сказати.\n\nПотім — іти назовні. Дивитися мене.",
        objectives = "Познач 8 Біженців з інших світів Кров'ю хижака, щоб наснажити портал у Притулку Вигнанців.",
        progress = "Зроблено?",
        completion = "Це пекельне місце... Мене тримали тут тижнями, поки я не вислизнув із пут. Тут нашої рідні куди більше, ніж коли я востаннє зважився навідатися.\n\nТепер врятуймо наших братів і сестер. І повбиваймо цих чудовиськ.",
    },
    [90873] = {
        title = "Ці Бурхливі Втіхи",
        description = "Брати й сестри. Тут. Допомогти.\n\n<Тул'амар змикає великий і вказівний пальці на обох руках, наче ланки ланцюга. Тоді різким рухом розриває ланку.>\n\nЯк? Показати.\n\n<Далі вона дістає мерехтливу реліквію і тримає її над своєю латною рукавицею. Вона вливає в реліквію частку своєї арканної енергії. Щойно пробуджена магія розпускає ремінці, які тримають рукавицю на місці.>\n\nВикористати.",
        objectives = "Скористайся Реліквією Визволення, щоб звільнити 10 Підданих Володаря і 3 Невільних Призваних.",
        progress = "<Тул'амар стоїть непорушно, навіть коли ти наближаєшся.>",
        completion = "<Тул'амар киває звільненим дренеям, що ховаються за нею.>\n\nКоли ми б'ємося, то на наших умовах.",
    },
    [90874] = {
        title = "Їхній Бурхливий Кінець",
        description = "Додому. Як?\n\n<Вона театрально змахує кінчиками пальців, викрешуючи арканні іскри. Потім складає з вказівних пальців хрест.>\n\nВід мене? Ні. Від них.\n\n<Тул'амар вказує на гурт блукачів Порожнечі попереду. Тоді проводить великим пальцем по горлу.>\n\nУбити. І.\n\n<Вона сягає в торбинку на стегні й дістає тріснутий камінь роботи доманаарів. Схоже на якийсь реагент для заклять.>\n\nЯк цей. Треба.",
        objectives = "Збери 8 Міток викрадача з блукачів Порожнечі на Сідалі Володарів.",
        progress = "<Тул'амар стоїть незрушно, навіть коли ти наближаєшся.>",
        completion = "Вони хочуть насильства? Дай їм насильство. Я смакувала цим видовищем.\n\nЦі руни мають потужний вигляд. Стількох має вистачити.",
    },
    [90875] = {
        title = "Крізь Світи",
        description = "Людина Порожнечі. Мати ключ. Треба. Ключ додому.\n\n<Тул'амар вказує шлях на північний захід. Озирнувшись на своїх поранених родичів, вона кривиться.>\n\nНазад, ми. Чекати. Сподіватися. На тебе.",
        objectives = "Убий Снаеріуса і поверни його Дороговказ Великої Темряви.",
        progress = "<Тул'амар сумно всміхається до свого народу.>",
        completion = "Ти зробив це можливим, {name}. Ми рідня, втрачена й нарешті возз'єднана... але вони мусять повернутися, і я маю стати тією, хто це забезпечить.\n\nЯ не можу пройти крізь той портал разом із ними. Я мушу знищити його, щоб жоден доманаар не зміг піти за ними слідом і затьмарити наше небо, як колись.\n\nТи моя рідня, але я не можу довірити це тобі. Я не зможу спочити, доки не знатиму, що вони в безпеці.\n\n<Відтак вона простягає вперед свій посох, пропонуючи його Юрасу. Хоч він і вагається його взяти, Тул'амар не здригається.>",
    },
    [90876] = {
        title = "Неохоча рука",
        description = "Чемпіоне, я вважав за важливе, щоб ти бу$p(в:ла) тут цієї миті, аби ні я, ні мій заблудлий колишній рівня не відхилялися від теми, перелічуючи його численні провини.\n\nЯ також хочу мати свідка на випадок, якщо він стане на бік зла.\n\nЧи не будеш ти такий ласкавий розпакувати кілька речей, щоб мені не довелося їх торкатися?",
        objectives = "Допоможи підготувати Тіньовий Атрій.",
        progress = "Я не настільки сповнений гордині, щоб не визнати певної... легкої ностальгії за тими словесними двобоями, які я колись мав із моїм колишнім рівнею.\n\nМагістр Умбрик свого часу був неабияким джерелом контраргументів і пропозицій, що перевершували сподівання й допомагали посувати наші знання про магію все далі й далі.",
        completion = "Отже, ми допомагаємо врятувати місто, а навзамін мені дозволяють повернути мої старі речі.\n\nВід будь-кого іншого це було б образою. Від Роммата? Найвища похвала.\n\nО, він навіть зберіг мій старий алембік... як завбачливо.",
    },
    [90879] = {
        title = "Кухня пивовара",
        description = "Тепер, коли ти зібра$p(в:ла) припаси, можна братися до куховарства! Нам знадобиться вдосталь їжі на весь натовп.\n\nМеню в нас коротке, але смачне: ячмінний суп, кренделі і, звісно ж, добре старе пиво!\n\nГотов$p(ий:а) навчитися ремесла?",
        objectives = "Виконай усі кроки, щоб приготувати страви Хмільного свята та смачне пиво.",
        progress = "Ану до куховарства!",
        completion = "Ех, кренделі пахнуть аж сюди. Такий стіл вдовольнить навіть найвибагливіших дворфів!",
    },
    [90880] = {
        title = "Обслуговувати зі смаком",
        description = "Ти добре впорався на кухні, тепер час навчитися обслуговувати! Хмільне свято — це не лише про їжу, а й про те, щоб усім було весело.\n\nТи прийматимеш замовлення, розноситимеш страви й наливатимеш напої з усмішкою.\n\nІди туди й покажи їм, як це робиться. Без доброго обслуговування Хмільне свято не вдасться!",
        objectives = "Прийми замовлення відвідувача й подай йому страви.",
        progress = "Не забувай обслуговувати з усмішкою!",
        completion = "Скажу так: після такої тяжкої праці ти заслуговуєш на добрий перепочинок і кухоль пива. Але не розслабляйся! Щоб Хмільне свято тривало, роботи ще повно!",
    },
    [90882] = {
        title = "Гнолям зась",
        description = "Розберися з тими гнолами, поки ми обмірковуємо наш наступний крок.",
        objectives = "Убий 10 гнолів у Гаммерфоллі.",
        progress = "Розберися з тими гнолами, поки ми обмірковуємо наступний крок.",
        completion = "Чудова робота. Проте спочивати нам не можна.\n\nДо нас дійшли звістки про новий хаос у нагір'ї.",
    },
    [90883] = {
        title = "До ферми Ґо'шек",
        description = "Ми отримали звістку, що на сусідню ферму напали оґри та кобольди.\n\nТреба вирушати, поки не обірвалося ще більше життів.",
        objectives = "Дійди до ферми Ґо'шек",
        progress = "Знайди фермера Брувка біля ферми Ґо'шек.",
        completion = "Не думав я, що отримаю стільки допомоги! Прошу, ти мусиш спинити їх!",
    },
    [90885] = {
        title = "Мої прекрасні гарбузи",
        description = "Кобольди й оґри з'явилися нізвідки та вигнали нас із ферми!\n\nМені спершу здавалося, що це якась змова Альянсу, аж поки не з'явилися ви. Може, Альянс і справді прийшов нам допомогти.\n\nДопоможи мені повернути мої дорогоцінні гарбузи. На них пішов увесь мій урожайний сезон!\n\nТи веди, а я підбиратиму гарбузи, коли ти їх знайдеш.",
        objectives = "Поверни 4 добірні гарбузи.",
        progress = "Повернися до Тралла з фермером Брувком та його гарбузами",
        completion = "Оце так... чимало гарбузів.\n\nГадаю, нашому другові-фермеру варто відвезти їх назад до Гаммерфолла. Підкріплення Орди вже мають бути там.",
    },
    [90886] = {
        title = "Найкращі плани кобольдів та оґрів",
        description = "Схоже, тутешні кобольди й оґри носять при собі якісь плани свого нападу.\n\nНавряд чи вони надто добре написані, тож мені знадобиться кілька таких, щоб розібратися, що замислили оґри.",
        objectives = "Збери 7 кострубато написаних планів.",
        progress = "Чи вдалося здобути плани? Вони мають бути при більшості ворогів на фермі.",
        completion = "Так я й думав.\n\nТут заледве щось можна розібрати.",
    },
    [90887] = {
        title = "Заклятий ворог фермера",
        description = "Фермер Брувк згадував, що зграю тут очолює оґр на ім'я Ранк.\n\nЦі створіння не заберуться звідси, доки той оґр ними командує.",
        objectives = "Убий Ранка.",
        progress = "Ми залишимося тут охороняти вцілілих фермерів, поки ти розбираєшся з Ранком.",
        completion = "Це має допомогти розігнати створінь. Без ватажка вони повтікають, щойно з'являться підкріплення Альянсу й Орди.",
    },
    [90888] = {
        title = "Порятунок фортеці Стромґард",
        description = "Знайдені тобою плани вказують, що оґри намагаються роздобути харчі для масштабного нападу на фортецю Стромґард!\n\nАбо ж вони хочуть за допомогою врожаю й далі стерегти щось на ім'я «буря». Переклад вийшов доволі вільний.\n\nБезпечніше припустити, що наша проблема — таки перше. Уперед!",
        objectives = "Вирушай до фортеці Стромґард.",
        completion = "Виглядає кепсько, але нам це до снаги.",
    },
    [90889] = {
        title = "Оповідь про відлуння Сай'аліо",
        objectives = "Збери інгредієнти для пігментів\nКартини створено\nОжилу фарбу розчавлено\nПлями фарби зібрано",
    },
    [90892] = {
        title = "Очищення небес: пекельна часина",
        description = "<Небеса повняться залишковою енергією часу та демонами, що вливаються з інших часових ліній.\n\nТреба допомогти Етернус, очистивши небеса. Та й зайва бронзова енергія не завадить.>",
        objectives = "Збери бронзу, пролетівши крізь 10 демонів Загубленого Легіону та 25 крихт бронзи.",
        completion = "<Небеса тепер трохи чистіші. Нескінченних може зацікавити обмін на цю зібрану зайву бронзу.>",
    },
    [90893] = {
        title = "Відбити облогу",
        description = "Ми мусимо зробити все можливе, щоб зупинити цю облогу Стромґарда.\n\nПробивайся в гущу битви й ослаб сили оґрів.\n\nЯкщо захисники Стромґарда здобудуть перевагу, вони зможуть згуртуватися.",
        objectives = "Відбий облогу оґрів під фортецею Стромґард.",
        progress = "Зустрінься з Траллом біля Ар'ґорока.",
        completion = "Облозі кінець. Їхнього ватажка загнано в кут.",
    },
    [90895] = {
        title = "Обстріл із катапульт",
        description = "Ці катапульти не вгавають. Їх треба знищити.\n\nПостав ці рунні камені біля їхньої основи. Вони вивільнять арканну магію, що оберне катапульти на порох.\n\nЯ теж знищу кілька, поки пробиватимуся через поле бою.",
        objectives = "Установи руни Джайни на 4 катапульти.",
        progress = "Зустрінься з Джайною біля Ар'ґорока.",
        completion = "Тепер, коли катапульт немає, солдати Стромґарда зможуть узяти гору.",
    },
    [90896] = {
        title = "Останній оґр",
        description = "Очільник облоги досі ховається в колишньому таборі Орди.\n\nВін примудрився сховатися від закляття Джайни за спинами кількох своїх посіпак.\n\nЧесть стати з ним віч-на-віч належить тобі. Ми з Джайною залишимося тут і подбаємо, щоб рештки облоги не повернулися.\n\nПокінчи з цим.",
        objectives = "Убий Ро'ґрока.",
        progress = "Здолай Ро'ґрока й поклади край цій облозі.",
        completion = "Облогу знято. Сподіваймося, тепер Аратійське нагір'я повернеться до більш-менш мирного життя.",
    },
    [90897] = {
        title = "Назад до Стромґарда",
        description = "Гадаю, нам пощастило, що більшої загрози, ніж зграя надто амбітних оґрів, тут не виявилося.\n\nПро інші небезпеки, що нависають над Азеротом, такого не скажеш.\n\nХодімо. Повернімося до Стромґарда й обговорімо все докладніше.",
        objectives = "Зустрінься з Джайною Праудмур у фортеці Стромґард.",
        completion = "Приємно бачити, що люди тут піднесені духом.",
    },
    [90898] = {
        title = "Назад до Гаммерфолла",
        description = "Не завжди нам щастить покінчити з таким задумом так швидко — та ще й без одного-двох несподіваних порталів.\n\nТа все ж по всьому Азероту чигають інші небезпеки. Я знаю: декому твоя допомога точно стане в пригоді.\n\nПовернімося до Гаммерфолла й погляньмо, як вони оговтуються.",
        objectives = "Повернися до Гаммерфолла.",
        completion = "З часом Гаммерфолл оговтається і стане сильнішим, ніж був.",
    },
    [90901] = {
        title = "Річ у артефакті",
        description = "В артефактах криється більше, ніж видно на перший погляд, {name}.\n\nСаме лиш використання артефакту дає його легенді зростати, а разом із легендою зростає і його сила.\n\nПроте, щоб розкрити весь потенціал цієї сили, тобі доведеться зосередити нескінченну силу в рисах артефакту. Що більше рис буде підсилено, то повніше розкриється справжній потенціал артефакту, і його легенда стане незаперечною.\n\nПочнімо.",
        objectives = "Відкривай риси артефактів за нескінченну силу, здобуту зі Споминів Епохи, які випадають з будь-яких ворогів.",
        progress = "Розкриття всього потенціалу твого артефакту стане ключем до розуміння впливу артефактів на цю часову лінію.",
        completion = "Збираючи нескінченну силу, не забувай зосереджувати її у своєму артефакті.\n\nЩо більше сили вкладеш, то швидше накопичуватимеш нову нескінченну силу і примножуватимеш легенду свого артефакту — і свою власну.",
    },
    [90907] = {
        title = "Перший, хто має знати",
        description = "Нотатки про страх, про непевність... про якусь загадкову істину? Це недобре, {name}. Судячи з усього, до Транквілліена зумів проникнути культ.\n\nЯкщо той запис у щоденнику правдивий, Касієя намагалася вийти з культу.\n\nМусимо сказати Антеноріанові. Він захоче убезпечити місто й подбати, щоб його людям нічого не загрожувало.",
        objectives = "Повідом лорда Антеноріана, намісника Транквілліена, про результати свого розслідування.",
        progress = "Сподіваюся, наше славне місто добре тебе приймає. Якщо щось бодай трохи тривожить — звертайся до мене.",
        completion = "Тішить, що ти довіряєш мені такі серйозні справи.",
    },
    [90910] = {
        title = "Приголомшлива темрява",
        description = "З лігва на південний схід звідси кличе моторошна присутність. Багато із запаморочених рен'дорей, яких ти бачиш у таборі, були приголомшені його сирою силою під час розвідки.\n\nХодімо разом і погляньмо, чи можна прилаштувати до діла те, що там мешкає. Ми не можемо дозволити собі нехтувати силою в боротьбі проти Ксал'атат.\n\nАле спершу: Калґорґ нам майже не потрібен. Через Войдшторм мій блукач Порожнечі став норовливим і неслухняним. Допоможи мені принести його в жертву. Нам знадобиться вся енергія Порожнечі, яку зможемо зібрати.",
        objectives = "Принеси в жертву Калґорґа, а тоді зустрінься з Люсією Найтбрейкер у Лігві Предаксаса.",
        progress = "Ах ти ж мале неслухняне...",
        completion = "Калґорґ спустився сюди, але я не зійдуся з ним непідготовленою.\n\nОте неслухняне мале чудовисько. Воно гадає, що може просто піти геть після двох десятиліть?",
    },
    [90911] = {
        title = "Твоя наступна пригода",
        objectives = "Обери свою наступну пригоду.",
    },
    [90914] = {
        title = "Природжений убивця",
        description = "Ах, {name}. Я так насолоджувався часом, проведеним разом. І прагну більшого.\n\nШкода, що ти знаєш про мене лише мою пристрасть до смаку смертних страждань. Одна з моїх найбільших утіх — вплітати силу Порожнечі в різні предмети та споруди. Це моя пристрасть — моє мистецтво.\n\nОсь, дозволь показати тобі. Спершу нам знадобиться сила. Як її здобути, ти, звісно, вже знаєш: убивай, убивай, убивай.",
        objectives = "Збери 15 есенцій Порожнечі з монстрів довкола Войдшторму.",
        progress = "Яке дивне відчуття. Мене наче... вабить до тебе. Певно, це твоя гіпнотична присутність.",
        completion = "О, який чарівно моторошний успіх.\n\nМені цікаво працювати з тобою разом. Тобі варто більше дізнатися про наш народ і побачити більше моїх умінь.",
    },
    [90915] = {
        title = "Мистецтво агресії",
        description = "Хоч ми, доманаари, найбільш відомі тим, що ведемо армії та смакуємо битви, цим ми не вичерпуємось.\n\nБагато хто з нас, як-от я, залюбки користується нашою владою над Порожнечею, щоб надавати їй форми будівель і предметів, які ти бачиш довкола.\n\nЯк гадаєш, звідки Ксал'атат навчилася створювати оту свою величну вежу? Вона все схоплює на льоту.\n\nХоди-но, я покажу тобі свою роботу.",
        objectives = "Скуй клинок разом із Децимусом.",
        progress = "Як же чудово провести час разом. Ви, смертні, такі цікаві... а ти — над усіх.",
        completion = "Вважай цей клинок моїм дарунком тобі. Ми разом викуємо з тебе справжню зброю руйнування.",
    },
    [90916] = {
        title = "Знайти і знищити",
        description = "Переплести Світло й Порожнечу — справа нелегка. Результат нестабільний, тож ми мусимо й далі його гартувати.\n\nМи загартуємо цей клинок у крові наших ворогів.\n\nДехто з доманаарів намагається відвоювати Вузлову Точку Ксенас і знову наповнити її силою. Твоєму народові це не віщує нічого доброго. Гадаю, ти захочеш цьому завадити.\n\nЯк то кажуть у вас, смертних? Двох зайців — одним ударом?",
        objectives = "Зустрінься з Децимусом біля Вузлової Точки Ксенас.",
        completion = "Колись ці Вузлові Точки були для нас, доманаарів, джерелами сили, якими ми тішилися, — задовго до того, як Ксал'атат скинула нас.\n\nКолись вони знову стануть такими.",
    },
    [90917] = {
        title = "Жнець лютості",
        description = "Клинок зголоднів! Кров наших ворогів допоможе стабілізувати й вигострити нашу новонароджену зброю.\n\nТобі доведеться вимочити клинок у кількох трупах. А отже — спершу наробити трупів.\n\n<Усмішка Децимуса ширшає.>\n\nТобі ж це добре вдається, правда?",
        objectives = "Застосуй новонароджений клинок на трупах у Вузловій Точці Ксенас.",
        progress = "Тутешні потвори люті й жорстокі. Їхня кровожерність і привабила сюди Порожнечу, тож, природно... ми почуваємося тут як удома.",
        completion = "Дуже добре. \n\nЯ розумію: ви, смертні, переймаєтеся такими речами, як екологічна рівновага та проріджування видів. \n\nНе бійся: тутешні чудовиська такі ж нескінченні, як і люті.",
    },
    [90918] = {
        title = "Непрощені",
        description = "Ще до нашої невеличкої халепи Вузлова Точка Ксенас завжди була найслабшою ланкою. Тутешні звірі вперті й могутні — вони постійно пробиваються дедалі глибше.\n\nДехто з доманаарів прагне повернути собі Вузлову Точку. Я їх знаю: слабаки, що гризуться за недоїдки. Подбаймо, щоб у них нічого не вийшло.",
        objectives = "Убий Ноксіана, Аверуса й Тенебре довкола Вузлової Точки Ксенас.",
        progress = "Ноксіан, Аверус і Тенебре... усі до одного — поплічники Ксал'атат, як і більшість мого роду. Цікаво, скільки б кожен із них вичікував, перш ніж спробувати зрадити її.\n\nШкода, що їхніх спроб ми вже не побачимо.",
        completion = "Ах, як мило — згадати минуле зі старими ворогами.\n\nКолись ми, доманаари, мали хитромудрі ієрархії влади. Кожен доманаар б'ється лише заради себе, та часто вигідно об'єднатися з іншими. Тимчасово, певна річ.\n\nНаймогутнішими з-поміж нас були Верховні Лорди. Коли прийшла Ксал'атат... вона показала на них усіх науку. Видовище було таке зворушливе, що пробудило в нас, доманаарів, не лише страх, а й щось ближче до відданості.\n\nУ декого, хоч і не в усіх.",
    },
    [90919] = {
        title = "Потвора, що схибила",
        description = "Клинок звивається. Він готовий до наступного перетворення.\n\nЛишився тільки ватажок — Вортенсіун.\n\nЯ його знаю. Колись ми уклали пакт, щоб здолати спільного суперника. Коли настав час мене зрадити, він зробив це незграбно.\n\nЯ лишив його живим, щоб смакувати його жаль.\n\nЦікаво, як добре той біль промаринувався за цей час? Дізнаймося. Коли клинок загартується в його есенції, він здобуде нову силу.",
        objectives = "Убий Вортенсіуна у Вузловій Точці Ксенас.",
        completion = "Не зважай на слова Вортенсіуна про їжу. \n\nМи ж стаємо добрими друзями, чи не так?",
    },
    [90920] = {
        title = "Тепло для душі",
        description = "Милуєшся краєвидом?\n\nКлинок тепер сильніший, але ще не завершений. Зброя, гідна тебе, заслуговує лише на досконалість.\n\nАле відпочиньмо хвильку. Я так розумію, ви, смертні, полюбляєте... невимушені бесіди, щоб ближче пізнати одне одного.\n\nЗ поняттям я знайомий, але цікаво побачити його в дії. Потішиш мою цікавість?",
        objectives = "Насолодися приємною бесідою з Децимусом.",
        completion = "Дивовижно, як вільно ти видаєш делікатні відомості про себе.\n\nЗвісно, я волію вірити, що ти не брехатимеш мені. Ми ж тепер друзі — ти і я. Це смертне поняття мене інтригує.",
    },
    [90922] = {
        title = "Слід полеглих",
        description = "<Тінь мерехтить. Ти ледве розрізняєш її шепіт.>\n\nТи... $p(покинув:покинула) мене... помирати...\n\n<Її рука тягнеться до тебе, а тоді розвіюється. Чомусь ця присутність здається знайомою. Ти відчуваєш, що знаєш цей дух.\n\nВдалині мерехтять інші постаті. Що це за тіні?>",
        objectives = "Розвіюй духів у Гризькому Обширі.",
        progress = "Яке дивне й страшне місце. Не бійся — якщо захочеш ще поговорити, щоб заспокоїти нерви... я тут, поряд із тобою.",
        completion = "Мені страшенно прикро, що тобі довелося крізь це пройти. Слова цих духів тебе засмутили, чи не так?\n\n<Децимус пильно вдивляється в тебе.>",
    },
    [90923] = {
        title = "Пастир страху",
        description = "Наша подорож триває... останнє поле бою. Тут повно лютих звірів. Їхня Порожнеча наситить клинок ще дужче.\n\nА новоздобута сила клинка сама вбиратиме їхню Порожнечу — самою лише близькістю!\n\nЩоправда, це місце інакше. Можеш натрапити на те, чого не очікуєш.\n\nБудь насторожі.",
        objectives = "Убивай чудовиськ і збирай есенцію Порожнечі в Гризькому Обширі.",
        progress = "Не відволікайся. Усе це окупиться, коли в твоїх руках буде могутня зброя.",
        completion = "Нарешті...",
    },
    [90924] = {
        title = "Лихий кінець",
        description = "Час настав. Останній крок.\n\n<Децимус замовкає, наче смакуючи щось.>\n\nСтворімо найвеличнішу зброю, яку лише бачив твій рід.",
        objectives = "Заверши кування клинка.",
        progress = "Твоє терпіння... гідно оцінено.",
        completion = "Клинок, як і обіцяно. Бачиш? Я й не думав лишати його собі. Я навіть надам йому тієї форми, яка пасуватиме тобі найкраще.\n\nСмак твоїх страждань — ось усе, чого я жадав.",
    },
    [90938] = {
        title = "Стрибок крізь Порожнечу",
        description = "Створіння з плоті, чи знаєш ти про Відв'язаний Простір? Певен, ти знаєш когось, хто з ним стикався.\n\nРаніше ми гадали, що лише енергетичні істоти, як-от ті з К'арешу, здатні на фазове занурення. Та відколи повернулася Провісниця, вона створила спосіб для твердих створінь обертатися на енергію за допомогою Обвоїв Реші.\n\nМене звати Гашим, і я маю при собі кілька Обвоїв Реші. Ми вкрай потребуємо шукачів пригод, досить могутніх, щоб наважитися зануритися в прибуткові глибини Відв'язаного Простору.",
        objectives = "Зустрінься з Гашимом на Заставі Зо'Шуул.",
        completion = "Я можу забезпечити тебе всім потрібним для дослідження Відв'язаного Простору.",
    },
    [90943] = {
        title = "Штурм Штормаріона",
    },
    [90957] = {
        title = "День посвяти",
        description = "{name}, сьогодні той день, коли ти знайдеш своє справжнє місце серед гаранірів.\n\nДоглядач коренів Далнір скерує тебе. Його шлях — це шлях традиції та смирення, тож не чекай гострих вражень. До кінця дня ти залишиш свій слід у Лігві Пам'яті. Історія, яку ти починаєш нині, виросте з тих, що були до неї, — як самі корені, що ростять підвалини Гарандару.\n\nДалнір саме очищав корені від чужорідних приблуд. Перш ніж іти до нього, допоможи йому — винищи трохи цих шкідників.",
        objectives = "Старійшина Гаґар просить тебе вбити 6 навальних дрейфунів довкола коренів Тельдрассила, а тоді зустрітися з Доглядачем коренів Далніром.",
        completion = "Настав час зайняти своє місце серед нашого народу й полишити дитячі пригоди. Дослухайся до моїх настанов, і нехай Ална'гара благословить цей день.\n\nПам'ятай: наші традиції вказують нам шлях.",
    },
    [90958] = {
        title = "Корені понад усе",
        description = "Дехто каже: великі дерева ростуть самі, і Гарандар стоятиме, навіть якщо ми не дбатимемо про них. Наші традиції кажуть: це не має значення. Ми лишаємося тут, щоб захищати, доглядати й служити. І робимо це з відданістю та смиренням.\n\nЧистота довкола коренів, вільних від шкідників, — відображення цього обов'язку. Повернися до мене, коли закінчиш. Ти гідно представиш наші звичаї, {name}.",
        objectives = "Доглядач коренів Далнір просить тебе виполоти бур'яни, прибрати мулистих стрибунів та вивести чужорідні гриби з цієї місцини.",
        progress = "Ти $p(виконав:виконала) завдання, які я просив?",
        completion = "Це спорядження чужинця? Ти $p(допомагав:допомагала) Орвейні з цими... відволіканнями, замість виконувати свої обов'язки. Як ти дотримуватимешся наших традицій, якщо не можеш дослухатися до моїх настанов під час церемонії?\n\nЯ поговорю зі Старійшиною Гаґар. Пам'ятай про важливість цього дня і про свій обов'язок.",
    },
    [90959] = {
        title = "Традиційні обов'язки",
        description = "У словах Далніра про церемонію є рація, та не варто дивитися надто вузько. Я так само шаную цінності нашого народу, але часом мусимо зазирати далі.\n\nНе хвилюйся. Тобі зараз слід зосередитися на церемонії. Чужинців я пошукаю згодом.\n\nНе сумніваюся, що ти зможеш приєднатися до мене, щойно церемонія посвяти завершиться.",
        objectives = "Внутрішній голос велить тобі шукати чужинця в Гар'марі.",
        progress = "Вітаю, {NAME}. За пропозицією Гаґар я зостануся свідком твоєї церемонії.",
        completion = "Чужинець розповів нам про твої вчинки. \n\nЗрозумій, {NAME}: хоч це й було відважно, це було небезпечно — навіть для тебе.\n\nЗнаю, Далнір лютує, але Хаґар розуміє твоє прагнення допомагати.",
    },
    [90960] = {
        title = "Моя історія, мій спадок",
        description = "{name}, попереду остання частина церемонії, хоч через твої манівці вона опинилася під загрозою.\n\nПерша фреска явить тобі видіння твого справжнього єства — того, що відлунює зсередини.\n\nДруга фреска явить видіння місця, де ти потрібн$p(ий:а).\n\nТретя ж фреска, як каже традиція, руйнує межу між нами й самою Богинею.\n\nЗавершиться церемонія тим, що ти намалюєш свою історію в Лігві.",
        objectives = "Старійшина Гаґар попросила тебе поспілкуватися з трьома фресками, а тоді намалювати власну історію.",
        progress = "Не поспішай, {NAME}. У церемонії важлива не швидкість, а те, чого вона тебе навчить.",
        completion = "За всі мої роки посвят таке, певно, вперше. Схоже, сама Богиня зауважила тебе.\n\nЯ відчуваю, що на тебе чекає таємнича й щедра подорож.",
    },
    [90961] = {
        title = "Чужинець у новому краю",
        description = "{name}, тепер я бачу, хто ти насправді. Ти віддан$p(ий:а) не лише нашому народові, а й усьому світові.\n\nБогиня також визнала тебе — я не пригадую нічого подібного: навіть церемонія Орвейни не була такою знаменною.\n\nСаме тут починається твоя історія. Час зробити перші кроки твоєї подорожі.",
        objectives = "Церемонію завершено, тож настав час розпочати твою подорож.",
        completion = "То ти і є {NAME}? \n\nНіхто й подумати не міг, що гаранір з'явиться в місті. Що ж, чутки про твої вчинки випереджають тебе. \n\nДля тебе вже приготовано базове спорядження. Це найменша дяка за порятунок одного з нас.",
    },
    [90962] = {
        title = "Штурм Штормаріона",
        objectives = "Заверши усю подію «Штурм Штормаріона»\nХвилю 1 завершено\nХвилю 2 завершено\nХвилю 3 завершено\nОборонну позицію активовано",
    },
    [90963] = {
        title = "Печери Розколини",
        description = "Чудова робота — полонені рутаані знову на волі. Завдяки поверненому насінню я можу спробувати продовжити справу Ру'ґара.\n\nПоки фунґаріани були зайняті тобою, мені вдалося трохи розвідати околиці й дещо зібрати, тож твоя допомога знадобиться ще в одній справі. Зустрінемося біля печери на північний схід звідси.",
        objectives = "Зустрінься з Ней'леєю біля північно-східної печери в Грибній Розколині.",
        completion = "Це місце здається безпечним, щоб спланувати наші наступні кроки. До того ж тут росте одна з рослин, про які згадував Ру'ґар.",
    },
    [90968] = {
        title = "Титанічні Поголоски",
        description = "Ширяться чутки, що довкола Каз Алґару помічено сили титанів. Бранн попросив Даґрана Тауріссана II допомогти розібратися з цими чутками.",
        objectives = "Розшукай Даґрана Тауріссана II у Штабі дослідників глибин у Дорноґалі.",
        completion = "Якщо ці чутки правдиві, ми мусимо все розслідувати.",
    },
    [90969] = {
        title = "Титанові Консолі",
        description = "Шукачу пригод, чутки правдиві. Я бачив сили титанів на власні очі — і вони аж ніяк не дружні. Треба з'ясувати, чому вони з'являються саме зараз, і не дати їм накоїти забагато лиха.\n\nСтань на шляху цих бунтівних конструктів і зупини їх. Щоб допомогти тобі, я роздобув кілька титанових консолей і зумів встановити їх в уражених місцинах. Через них я зможу зв'язуватися з тобою в полі. Гадаю, ними ж можна скористатися й проти самих сил титанів.",
        objectives = "Розшукай одну з титанових консолей Даґрана в перевантаженій Глибині.",
        completion = "{NAME}, присутність сил титанів перевантажує ці консолі. Якщо ми здолаємо їх і роздобудемо титанові диски, гадаю, ними можна буде підживити консоль, щоб вона дарувала тобі блага в цій місцині. Ці блага поможуть тобі відтіснити бунтівні титанові конструкти.",
    },
    [90970] = {
        title = "Титановий Диск-онт",
        description = "Нам треба роздобути більше титанових дисків. Заглибся далі в цю місцину, знайди титанових конструктів і здолай їх. У них мають знайтися уламки дисків. Ця консоль може зібрати їх докупи й зчитати їхні дані.\n\nНе забудь пошукати й скарбниці. Схоже, конструкти допомагають місцевим мешканцям — дехто з них міг приберегти додаткові титанові диски серед інших своїх скарбів.",
        objectives = "Здобудь скалки Диска Титанів і знищ титанових конструктів у Глибині.",
        progress = "Шукачу пригод? Це ти?",
        completion = "Ну як, знайшлися скалки? Поки тебе не було, я згадав, що й сам назбирав кілька, коли навідувався в ту місцину. Пошукай їх у мішечку, який я сховав біля консолі.",
    },
    [90971] = {
        title = "Перезаряджена Консоль",
        description = "Завдяки знайденим уламкам ми можемо відновити титанові диски через консоль і отримати з них могутні дари.\n\nСкористайся функцією ремонту дисків на консолі, щоб створити титановий диск, а тоді обери за його допомогою початковий вузол в інтерфейсі консолі перезаряду.",
        objectives = "Віднови Диск Титанів, а тоді витрать його, щоб відкрити один із початкових вузлів у дереві технологій перевантаженої консолі.",
        progress = "Спрацювало?",
        completion = "Моя дистанційна консоль показує зміну. Перевантажена консоль спрямовує надлишкову енергію в новий вузол. Це має дарувати тобі силу того вузла в інших місцинах, де з'явилися титанові конструкти.\n\nОбернемо енергію сил титанів проти них самих!",
    },
    [90972] = {
        title = "Спільна справа",
        description = "{name}! Я чув, що ти тут, на К'ареші. Добре. Мені потрібна допомога.\n\nМоя учениця Леона досліджувала нові способи приборкання сили Порожнечі. Вона звернулася до мисливця на демонів на ім'я Адарус, щоб дізнатися, чи можуть методи іллідарі дати якісь підказки.\n\nЧесно кажучи, я не певен, що довіряю Адарусу. Він не... старанний. На відміну від Леони.\n\nЛеона лише мала спостерігати за ним, поки він прагнув опанувати Порожнечу. Але вона зникла. Будь ласка, знайди її. Поговори з Адарусом — він щось знає.",
        objectives = "Поговори з Адарусом.",
        progress = "Ну як, {NAME}, вдалося поговорити з Адарусом? Схоже, апофеоз іллідарі геть позбавив їх гарних манер.",
        completion = "Тебе прислав Адарус? \n\nЙого зневіра в моїх здібностях і любов перекладати справи на інших говорять самі за себе.",
    },
    [90993] = {
        title = "Захопіть Темний Колодязь!",
        description = "Ми маємо своє військо, але за цими стінами на нас чекають найпотужніші, найпідліші й найдужче підсилені вороги з арсеналу Ксал'атат.\n\nЗбери своїх найсильніших союзників, {name}, і приєднайся до нас усередині. Настав час покласти цьому край і повернути собі наш колодязь.",
        objectives = "Рушай на Кель'Данас.",
    },
    [90995] = {
        title = "Майбутнє Скверного Молота",
        description = "О, стривай! Звісно, саме тоді, коли я виряджаю тебе, я згадую найважливіше!\n\nТи з цієї часової лінії зроби$p(в:ла) вирішальний вибір для майбутнього всіх мисливців на демонів. Послідовник, якого ти обра$p(в:ла) своїм особистим чемпіоном, створив дві розбіжні часові лінії для долі іллідарі.\n\nТобі доведеться обрати, яку з цих розбіжних часових ліній досліджувати. Що видається тобі правдивим?",
        objectives = "Обери свого особистого чемпіона.",
        progress = "Вибір зроблено?",
        completion = "Що ж, вивчатимемо цю версію часової лінії. Погляньмо, що чекає іллідарі в майбутньому... е-е, тобто в минулому.",
    },
    [90999] = {
        title = "Відстеження завдань",
    },
    [91000] = {
        title = "Скромний слуга",
        description = "{name}, останні місяці мешканці Гаммерфолла були зосереджені на щоденних справах, обороні й виживанні.\n\nЇм бракувало часу — та, правду кажучи, і рук, — щоб дати раду всій заподіяній шкоді.\n\nМи багато чим можемо допомогти їм знову стати на ноги.\n\nЗнаю, це скромна робота, але для орків, які тут живуть, вона важить дуже багато.",
        objectives = "Допоможи мешканцям Гаммерфолла знову стати на ноги.",
        progress = "Роботи багато, {NAME}.",
        completion = "Гарна робота, {NAME}. Справи починають налагоджуватися.",
    },
    [91001] = {
        title = "Розчистити шлях",
        description = "Їхня магія розбита, їхні лави зламані — Клинок Сутінків втрачає позиції.\n\nМусимо скористатися тим, що вони відвернулися.\n\nЯ поведу наступ через ущелину — до Святилища Завойовника, що за нею. Там Мор'дуун, береже свою боягузьку шкуру від наших списів і сокир.\n\nТа недовго він там буде в безпеці.",
        objectives = "Зберися разом із Зул'джаррою, Зул'джаном і леді Ліадрін біля підніжжя Святилища Завойовника в Розбитому Троні.",
        progress = "Мусимо діяти — негайно!",
        completion = "Мор'дуун може сміятися зараз, засівши в Святилищі.\n\nАле останнім сміятимемося ми.",
    },
    [91009] = {
        title = "Довговічний Інформаційний Сховок-Контейнер",
        description = "Шукачу пригод, ти мене чуєш? Я знайшов менший титановий пристрій — Довговічний Інформаційний Сховок-Контейнер, — який кріпиться на пояс. Я вирахував, що такі пристрої зможуть програвати менші титанові диски, даючи блага, якими можна користуватися будь-де.\n\nКожному такому пристрою потрібен початковий поштовх. Якщо здійняти в цих Глибинах досить куряви, з'явиться іскра, яку пристрій виявить і збере. Її має вистачити, щоб живити його до кінця твоїх днів.",
        objectives = "Пройди Глибину, щоб зарядити пристрій.",
        progress = "Перевантаження — ось що головне.",
        completion = "Приладнай пристрій. Так! Пристрій увімкнувся. \n\nГаразд... Якщо просто запустити послідовність ініціалізації... і готово. Усередині вже є два диски. А в меню буде список місцин, де можна знайти інші мініатюрні титанові диски. Гадаю, я зможу вдосконалити пристрій, але мені потрібен час. Знайди мене згодом — побачимо.",
    },
    [91026] = {
        title = "Збираємо Покращення",
        description = "Агов? Агов? Ти знову тут! Чудово!\n\nЯ вивчав титанову консоль і зібрав купу нових даних із перезаряджених місцин, зокрема про виявлені хибні директиви. Можливо, саме в них ключ до цієї несподіваної поведінки, але щоб знати напевно, мені потрібно більше часу.\n\nПовертайся до Глибин — перевіримо наслідки хибних директив, а я на основі цих даних створю покращення для твого пояса!",
        objectives = "Пройди будь-яку Глибину.",
        progress = "Ну що, успішно?",
        completion = "Ось, так... Із цими відомостями я можу внести останні поправки. І додати оцю директиву...\n\nАга! Має спрацювати. Якщо вставиш це у свій довговічний інформаційний сховок-контейнер, це має оновити дієвість, е-е... ефектів пристрою.",
    },
    [91030] = {
        title = "Нові Титанові Директиви",
        description = "Моїм розрахункам бракує ще багато даних. Я вже майже закінчив нову картку покращення, але не певен, чи вона приживеться як слід.\n\nТа якщо ти повернешся в простори Глибин і здолаєш більше ворогів, я побачу, як вони реагують. За їхніми реакціями я доведу до пуття це покращення для твого пояса.",
        objectives = "Пройди будь-яку Глибину.",
        progress = "Не можу дочекатися нових даних!",
        completion = "Гм, як я й підозрював. Так... треба підправити ось тут... готово.\n\nДобра новина: від цього покращення твій пояс не вибухне! Я думав, є невеликий шанс, але вже ні. Твої дані довели, що я виставив завелику потужність. Тож... добре, що я послав тебе на ту додаткову перевірку, еге ж?",
    },
    [91031] = {
        title = "На Межі Можливостей",
        description = "Уже після твого відходу минулого разу я зрозумів, що, мабуть, трохи налякав тебе балачками про можливий вибух покращеного пояса. Вибач. Часом я надто захоплююся.\n\nЯ таки гадаю, що можу вичавити з пояса ще більше сили. Ну, принаймні трохи більше. Безпечно, звісно ж! У твоїх даних я побачив, скільки ворогів траплялося тобі в численних Глибинах. У цьому й ключ — повернися туди ще раз заради останнього покращення для твого пояса.",
        objectives = "Пройди будь-яку Глибину.",
        progress = "Не терпиться дізнатися, чи я мав рацію!",
        completion = "Дані з тієї останньої вилазки дали мені все потрібне для ще одного покращення. Але це останнє покращення, яке можна зробити для пояса, якщо ми не хочемо великого розплавлення. Хоча розплавлення, звісно, багато розповіло б нам про конструкцію...\n\nМама завжди казала: «Даґране! Якщо вже нищиш стародавні незамінні артефакти — нищ власні». Тож це останнє покращення.\n\nОсь остання картка покращення. Дякую за поміч. Сподіваюся, нам ще випаде нагода поекспериментувати в майбутньому!",
    },
    [91033] = {
        title = "«Конструкт»ивний Нагляд",
        description = "З поверненням, шукачу пригод. Маю до тебе просте прохання: треба й далі наглядати за цими титановими конструктами.\n\nМи бачили, як вони пересуваються Азеротом у різних місцях, але я досі не збагнув ані їхньої кінцевої мети, ані того, які вказівки вони могли отримати. Можливо, якщо зібрати більше відомостей, розгадка знайдеться сама.",
        objectives = "Пройди перевантажену Глибину.",
        completion = "Їхня поведінка, схоже, майже не змінилася. Це дуже прикро. А ще, якщо твої дані правильні, вони, здається, потроху вгамовуються. \n\nПобачимо, чи підтвердиться це спостереження. А ось додаткове спорядження, яке ми назбирали. Сподіваюся, воно добре прислужилося тобі за час наших наукових звершень!",
    },
    [91035] = {
        title = "Деескалація Конструктів",
        description = "Твої попередні результати показали, що перезаряд у конструктах зменшився. Треба з'ясувати, чи це поодинокий випадок, чи спад набирає обертів...\n\nПовертайся в перезаряджені місцини, перевір заряд конструктів і доповідай.",
        objectives = "Здолай 5 конструктів і пройди перевантажену Глибину.",
        completion = "Ого! Оце так спад. Якщо так триватиме й далі, скоро цих конструктів може не стати зовсім! \n\nМи досі не знаємо, що змусило їх вийти на поверхню! А раптом так і не дізнаємося? Сподіваюся, вони повернуться.\n\nОй, ні! Я ж не хочу, щоб вони знову все псували. Просто страх як не люблю лишати загадки нерозгаданими. \n\nПринаймні ми будемо краще готові, якщо знову їх побачимо. Дякую за поміч, {NAME}. Я перевірив розрахунки: твій пояс має працювати й далі, навіть якщо конструкти відступлять. \n\nІ ще один, останній ящик припасів за твою допомогу.",
    },
    [91038] = {
        title = "Потрібні мисливці на пекло",
        description = "<До стіни прибито обпалений лист.>\n\nПЕКЛО ЙДЕ ПО ТЕБЕ!\n\nТепер, коли ми привернули твою увагу, будь обережний: у цей світ потрапили скалки сірки. Вони теплі на дотик, і їх у жодному разі не можна встромляти собі в голову, в голову будь-кому іншому чи в будь-який інший життєво важливий орган твій або тих, хто поруч.\n\nБудь ласка, неси всі знайдені скалки НЕГАЙНО до нас у Дорноґал.\n\nА якщо побачиш якихось крихітних посіпак, що несуть торбу зі скарбами, ВБИВАЙ ЇХ НА МІСЦІ.",
        objectives = "Віднеси послання Баранару в Дорноґал.",
        completion = "Ми цінуємо твоє бажання нам допомогти.\n\nСкалки нашої часової лінії потрапили у твій світ. Наш світ похмуріший і темніший за твій: у ньому дехто з лиходіїв став героєм, а декому з героїв не випало й шансу.\n\nДопоможи нам знайти ці пекельні уламки поза часом і повернути їх на належне місце, а ми забезпечимо тебе обладунками, загартованими у вогні нашого світу.\n\nА якщо натрапиш на скарбових ґоблінів, що причаїлися у твоєму світі, — благаємо, вбивай цих почвар.",
    },
    [91039] = {
        title = "Прохання Фейрін",
        description = "{name},\n\nҐея'ра й Данат прибули в Дорноґал. Обох, здається, непокоїть напруга, що наростає в Аратійському нагір'ї. Справа, схоже, серйозна.\n\nЧи можеш ти прибути в Дорноґал? Гадаю, твоя присутність допоможе залагодити ситуацію.\n\nФейрін",
        objectives = "Поговори з Фейрін Лотар у Дорноґалі.",
        completion = "{NAME}! Дякую, що ти тут.",
    },
    [91040] = {
        title = "Докучливі Лихогіллі",
        objectives = "Сили Лихогіллів знищено",
    },
    [91041] = {
        title = "Легенько струшений подарунок",
        objectives = "Цей подарунок, схоже, вже кілька разів трусили. Напис на бирці:Дуже особливому персонажеві — &lt;race&gt; &lt;class&gt;.",
        completion = "Цей подарунок, схоже, вже кілька разів трусили. Напис на бирці:\n\nДуже особливому персонажеві — {race} {class}.",
    },
    [91042] = {
        title = "Дарунок Зимової Завіси",
        completion = "Маленька бирка на цьому подарунку повідомляє:\n\nВеселих свят, {NAME}!",
    },
    [91044] = {
        title = "Голод Порожнечі",
        description = "Я зробила все, що могла, аби запобігти такому результату. Якби ти не зіштовхну$p(в:ла) його крізь портал, нестримна енергія Порожнечі обвалила б печеру навколо нас.\n\nВін був сильний. Певним чином, гадаю, це обернулося проти нього.\n\nЗустрінься зі мною знову в Шан'дора. Я маю доповісти Умбрику й сповістити його про те, що тут сталося.",
        objectives = "Зустрінься з магістром Умбриком і Леоною знову в Шан'дорі.",
        progress = "Я навіть звідси відчував, як вирують енергії Порожнечі, {class}. Що саме сталося?",
        completion = "Щиро сподіваюся, що з Адарусом усе гаразд і що він не тримає на нас зла. У рен'дорей і без того досить ворогів.\n\nЯ радий, що Леона зробила прорив. Хоча без твоєї допомоги їй нізащо б не вдалося.",
    },
    [91047] = {
        title = "Еруунді",
    },
    [91048] = {
        title = "Тремора",
    },
    [91050] = {
        title = "Територіальний Косар Порожнечі",
    },
    [91051] = {
        title = "Нічний Виводок",
    },
    [91052] = {
        title = "Світодуша: перевантажені Глибини",
        description = "Щось пробудило ворожі конструкти титанів, і вони проникають у печери й порожнини по всьому Каз Алґару. Вирушай до цих місць, розвідай усе й усунь загрозу, яку вони становлять.",
        objectives = "Пройди перевантажену Глибину Війни Всередині на будь-якій складності.",
        completion = "Тривожно не знати, що саме змусило ці ворожі загони титанів вийти на поверхню. Але завдяки твоїм зусиллям їхній загрозі покладено край.",
    },
    [91061] = {
        title = "Нескінченний хаос",
        description = "Ти можеш вважати це за іронію, але наш час спливає, {name}. Великі сили загрожують майбутньому не одного лише світу.\n\nНоздорму це не сподобається, та я мушу пришвидшити наше дослідження експериментами. Я виокремив надламану лінію часу, щоб ти її дослідив. Але стережися — цей світ позбавлений будь-якої надії. Це єдиний спосіб по-справжньому підготувати нас до того, що насувається.\n\nЯ встановив дослідницьку консоль біля монумента Скверни позаду тебе. Скористайся нею, щоб увійти в це заборонене майбутнє, аби ми могли пізнати незбагненне.",
        objectives = "Досліди героїчний світовий рівень.",
        progress = "Ну що, як тобі темні часи, які могли б настати?",
        completion = "У тебе більше хоробрості, ніж я гадав, {NAME}.\n\nБудь ласка, продовжуй експерименти. Я не дозволю нам увійти в небезпечні варіанти майбутнього непідготовленими.",
    },
    [91062] = {
        title = "Зруйновані мости",
        description = "Маю до тебе останнє прохання, перш ніж ти вирушиш із Ліадрін до Сільвермуна, гаш'ура.\n\nЗнайди Зул'джана. Ніхто не бачив його, відколи ми повернулися до Амані'Зару.\n\nДорогою назад я прямо спитала з нього за те, що він повів наших воїнів до Розбитого Трону всупереч моєму наказу.\n\nЗагинули ті, хто не мав загинути. Я спитала його: чого тут не розуміти?\n\nВін не сперечався. Він був наче порожній: тіло тут, а розум?\n\nЧасом він шукає спокою в шумі океанських хвиль.\n\nМожливо, знайдеш його на Небесному Мосту.",
        objectives = "Розшукай Зул'джана на Небесному мості.",
        completion = "Рада, що знайшла тебе. Зул'джарра сказала мені, що ти шукатимеш Зул'джана в цих краях, але ця земля для мене досі така незнайома.\n\nЯкщо ти вже знайш$p(ов:ла) його й натішився святкуванням, нам варто повертатися до Сільвермуна.",
    },
    [91063] = {
        title = "Квітуче Плетиво",
        description = "То це про тебе я стільки чула, так? Я Су'міра, учениця художника Джа'кула. Знаєш про нього? Ні? Може, його роботи просто ще не дійшли до твоїх країв. Воно й не дивно, мабуть.\n\nХай там як, кажуть, тобі до вподоби допомагати іншим. Так-от, коли на Джа'кула напали й убили його, зникло кілька важливих речей. Я хочу їх повернути.\n\nЗустрінемось біля Квітучого Плетива?",
        objectives = "Зустрінься із Су'мірою біля Квітучого Плетива.",
        completion = "Дякую, що ти тут. Я не була певна, що прийдеш. Отам, угору пагорбом, — Квітуче Плетиво, селище вельми лютих рутаані.\n\nЇхні ватажки вбили Джа'кула й забрали його речі. Я хочу їх повернути!",
    },
    [91065] = {
        title = "Пелюсткові Крадії",
        description = "Кілька днів тому зграя рутаані напала на мого наставника Джа'кула і вбила його. А їхні дурні птахи тоді поцупили в нього кілька речей. Ці пелюсткоголові тягнуть усе блискуче, що не приросло шипами.\n\nПовернеш мені речі Джа'кула? Я художниця, а не боєць. Сама я там довго не протримаюся.",
        objectives = "Поверни викрадені речі з Квітучої Тераси.",
        progress = "Ті птахи і голову б у тебе поцупили, якби вона не трималася на плечах. Особливо якби на ній був блискучий капелюх чи шолом. Просто з плечей!\n\n<Вона на мить замовкає, наче уявляючи це, тоді трохи зеленіє і здригається.>",
        completion = "Вийшло! Я знала, що це в них, у тих мерзенних стерв'ятників із бур'яном замість мізків!\n\nЗнаю, нерозумно побиватися через таку річ, як улюблена ложка, але вони забрали життя Джа'кула. Більше я їм нічого його не віддам.\n\nТи просто золото, {NAME}.",
    },
    [91066] = {
        title = "Кухня пивовара",
        description = "Чудово, ти приніс припаси. Тепер починаймо бенкет. Нам знадобиться вдосталь їжі, щоб не втрачати сил.\n\nМеню просте, але гідне: ячмінна юшка, печені на камені крендлики й міцне варево, щоб надати снаги Орді!\n\nТи готовий учитися?",
        objectives = "Виконай усі кроки, щоб приготувати страви Броварства і смачне вариво.",
        progress = "Розпалюй вогонь — і до роботи!",
        completion = "Ха! Я аж звідси чую запах тих крендликів. Такий бенкет змусить замовкнути навіть буркотливих дворфів!",
    },
    [91067] = {
        title = "Збираємо харч",
        description = "А, ти тут. Броварство почалося — але в нас халепа. Який же це бенкет без їжі, а кілька злодійкуватих гозенів вирішили, що буде розумно поцупити наш харч.\n\nОсь що ти зробиш: вистеж тих гозенів і поверни те, що належить нам. Можеш також натрапити на кілька торб, що просто валяються довкола, — хапай їх. Коли роздобудеш усе добро, кидай його у віз позаду мене.",
        objectives = "Збери торби складників Броварства і поскидай їх у віз.",
        progress = "Без тих складників бенкету не буде!",
        completion = "Вдалося! Кухарі будуть задоволені.",
    },
    [91068] = {
        title = "Обслуговувати зі смаком",
        description = "Ти довів свою вправність у куховарстві, тепер час довести її в залі! Броварство — це не лише про бенкет, а про те, щоб принести веселощі в кожен закуток табору.\n\nТи прийматимеш замовлення, носитимеш тарелі й розливатимеш ель, як справжній воїн святкування.\n\nА тепер гайда туди й покажи їм, який має бути справжній сервіс! Броварство не тримається на порожніх кухлях!",
        objectives = "Прийми замовлення відвідувача й подай йому страви.",
        progress = "Не забувай подавати з усмішкою!",
        completion = "Скажу так: після такої роботи ти заслуговуєш на перепочинок і кухоль міцного варива. Але дивись мені, не розслабляйся! Броварство ще не скінчилося, і роботи попереду вдосталь.",
    },
    [91069] = {
        title = "Помста за Толбані",
        description = "Ми з Толбані завантажили ялик ліками, сталлю та харчами, щоб відвезти все вгору річкою до передового табору.\n\nЦе мала бути тиха ходка: без пригод і без чужих очей.\n\nАле на мілководді з очерету раптом посунули мурлоки — самі піна й зуби. Вдарили сильно — надто швидко, щоб як слід відбитися. Ялик перекинувся, і вантаж пішов на дно. Мені ледве вдалося дістатися берега.\n\nТолбані не вдалося. Його тіло, всіяне дротиками, довелося тягти сюди мені.\n\nМурлоки заплатять за те, що накоїли.",
        objectives = "Убий 12 мурлоків в Атал'Абасі.",
        progress = "Пусти кров цим безтямним тварюкам. Хай страждають за вбивство Толбані.",
        completion = "Чуєш?\n\nТиша.\n\nОсь як звучить помста.",
    },
    [91070] = {
        title = "Повернути вантаж",
        description = "Дорогою назад від річки — а шкутильгати довелося добряче — мені трапилися на очі кілька мурлоків, що волокли наші мішки з харчами через багнюку. І діяли вони геть не разом: гарчали одне на одного, і кожен намагався урвати собі найкращий шмат.\n\nОдин на моїх очах заховав цілу торбу за поваленим деревом. Інший закопав щось під купою каміння. Жадібні малі потвори гадають, що можуть красти в нас — і їм це минеться.",
        objectives = "Знайди 6 украдених харчових припасів в Атал'Абасі.",
        progress = "Так, {class}?",
        completion = "Добре. Оце вже все.",
    },
    [91071] = {
        title = "Загроза Атал'Абасі",
        description = "Наш човен не сам сів на мілину.\n\nМи відбивалися від мурлоків — і раптом опинилися в повітрі.\n\nОтоді він і трапився мені на очі — той, що був не такий, як решта. Більший. Сильніший. Коли він нападав, інші мурлоки кидалися врозтіч.\n\nВін підняв наш човен, наче той нічого не важив, і жбурнув його на скелі. Мені ще не доводилося бачити, щоб мурлок таке витворяв.\n\nМи й далі втрачатимемо своїх і припаси, поки той м'язистий мурлок пильнує річку.",
        objectives = "Знайди і вбий Мррука М'язоплавця в Атал'Абасі.",
        progress = "Річка небезпечна. Ми мусимо її відвоювати.",
        completion = "Малі тікали, охоплені жахом, — це було видно здалеку. Гарна робота, {class}.",
    },
    [91072] = {
        title = "Зотлілий Діамантоспин",
    },
    [91073] = {
        title = "Аш'ан Наснажений",
    },
    [91084] = {
        title = "Навислі тіні",
        description = "Хоч над Руєю і Світлоцвітом ми наразі взяли гору, роботи ще багато. Старійшини захочуть зібратися й обговорити нове місце Гара'ті у світі — тепер, коли ми вийшли з тіней власного минулого.\n\nНаша замкненість і наш страх не зникнуть за одну ніч. Але це важливий перший крок.\n\nУ нас усе буде добре, {name}. Старійшин полиш нам з Орвейною. Коли настане час, Гара'ті стануть пліч-о-пліч із тобою. А поки, гадаю, на тебе чекають нагальніші справи.",
        objectives = "Повернися до регента-лорда Лор'темара Терона у Святиню Світла в Сільвермуні.",
        completion = "Коли Галдурон увірвався на воєнну раду, волаючи про приховані світи й прадавніх воїнів, я думав, що він збожеволів. Та тепер, коли я на власні очі побачив гаранірів...\n\nНам пощастило мати їх потенційними союзниками. І пощастило мати тебе, я б сказав, у налагодженні цих стосунків.\n\nНа нас чекає ще багато справ. Та я не маю сумніву, що Гара'ті стануть для Сільвермуна життєво важливими союзниками у прийдешні дні.",
    },
    [91085] = {
        title = "Пелюстковий Ворс",
        description = "Джа'кул саме полював на пелюсткокрилів, коли рутаані заскочили його і вбили. З їхнього пір'я ми робимо деякі з наших пензлів. Вони особливо помічні, коли молоді паростки вчаться працювати точніше й делікатніше.\n\nЯк будеш там, нагорі, принесеш мені трохи їхніх пір'їн?",
        objectives = "Збери 8 пір'їн пелюсткокрила.",
        progress = "Чи вдалося зібрати пір'їни пелюсткокрилів, про які я просила? Вони конче потрібні для навчання молодших гаранірів.",
        completion = "Дякую тобі за ці пір'їни! З однієї я зроблю пензля й намалюю пам'ятну картину на честь Джа'кула. Решта піде дітям.\n\nСхоже, тепер навчати їх доведеться мені.",
    },
    [91086] = {
        title = "Зрізати Бутони",
        description = "За нападом на Джа'кула стоять рутаані з Квітучого Плетива. Їх веде верховний вартовий цвіту — ще лютіший за решту. Ненавиджу їх, вони всі жахливі!\n\nМоже, підріжеш ці зарості, щоб решті з нас жилося спокійніше?",
        objectives = "Убий рутаані та верховного вартового цвіту в Квітучому Плетиві.",
        completion = "Готово? Дякую. Джа'кула це не поверне, але тепер вони більше нікого не скривдять.",
    },
    [91087] = {
        title = "Звіти доставлено",
        description = "Я вирушу до Сільвермуна, але... потім повернуся сюди — радити Зул'джаррі.\n\nВідчуваю, що дозволила своєму минулому й своїм упередженням затьмарити мій погляд на амані. Можна сказати, що бути гаш'урою — гідна спокута, та... мене тягне залишитися. Можливо, щоб допомогти Зул'джаррі повернути її народ до лоа.\n\nЯ піду з тобою до Сільвермуна — донести звіт... і знести реакцію Лор'темара.\n\nЯкщо рушимо зараз, то, може, ще встигнемо повернутися на... святкування.\n\n<Легка усмішка торкається зазвичай незворушного обличчя Ліадрін.>",
        objectives = "Доповідь Лор'темару Терону в Сільвермуні.",
        completion = "<Лор'темар підводить брову й трохи насуплюється. Видно, що він стримує роздратування й гнів.>\n\nЦе... вельми несподіваний поворот подій. Та попереду на нас, певен, чекає ще чимало.",
    },
    [91088] = {
        title = "За Водоспадом",
        description = "Сувій, який тобі вдалося повернути, — це послання, що лишив мені мій наставник Джа'кул. Я навіть не встигла його прочитати, перш ніж його вкрали!\n\nУ сувої Джа'кул залишив вказівки, як знайти печеру за водоспадом у Квітучому Плетиві. Не знаю, що ми там знайдемо, але я була б дуже вдячна за компанію, поки все оглядатиму. Зустрінемось там?",
        objectives = "Зустрінься із Су'мірою в печері за водоспадом у Квітучому Плетиві.",
        completion = "Це неймовірно! Аж не віриться, що тут ховається ціла печера. І Джа'кул залишив для мене камінь видінь.",
    },
    [91089] = {
        title = "Перемога над Кай'везою",
        description = "То вона з'явилася по винагороду, га?\n\nЇй ніхто не казав, що намагатися вбити Захисника Азерота — це нечемно? Та ще й Бронзбірд, до того ж?",
        objectives = "Підвищ рівень своїх предметів, щоб кинути виклик Кай'везі в її Глибині 8-ї складності на К'ареші.",
        completion = "Ху! Нарешті здихалися.\n\nТерпіти не можу все це скрадання і теліпання туди-сюди телепортами.\n\nПісля таких пригод, мабуть, саме час подумати про невеличку відпустку.",
    },
    [91090] = {
        title = "Докучливі шкідники",
        description = "Навколишні створіння потерпають від зараження Світлом, і їх тягне до Сонячної Купелі. Наших гостей це бентежить. А це вже проблема, коли хочеться безтурботно сховатися від усього світу.\n\nЗізнаюся: коли щось таке тицяється тобі в ногу під час плавання, стає моторошно.\n\nБудь ласка, відвади непроханих сонцеличинок від нашого товариства, а тоді здіймися в небо й прожени тих настирливих метеликів.",
        objectives = "Убий 10 сонячних личинок і злети, щоб відігнати 10 Невідчепних Метеликів.",
        progress = "Комахи завдають тобі клопоту?",
        completion = "Не так і страшно, правда?\n\nВал часом надто драматизує, але ти впора$p(вся:лася) чудово.",
    },
    [91093] = {
        title = "Більше, ніж просто фаза",
        description = "Відв'язаний простір — постійна загроза для нашого народу на К'ареші. Він кишить вигнаними душами, поламаною технологією та різноманітними чудовиськами.\n\nДопоможи Спілці К'ареша й здолай наших ворогів у Відв'язаному просторі. Можеш користуватися фазовими провідниками, щоб пересуватися між уламками К'ареша під час фазового занурення.",
        objectives = "Виконуй активності під час фазового занурення у Відв'язаному Просторі на К'ареші.",
        progress = "Мрію про день, коли ми, к'арешці, зможемо вільно й без страху ходити цими землями.",
        completion = "Твоя допомога дуже цінна для нас, {race}. Спілка вчинила мудро, доручивши тобі підтримати наші зусилля.",
    },
    [91095] = {
        title = "Здобич: магістр Санбрейкер (звичайний)",
        description = "Колись він був шляхетним магістром Сільвермуна, що присягнувся захищати Кель'Талас за будь-яку ціну. Тепер він порвав з орденом і прагне помсти на власних умовах.\n\nЯ бачу в ньому щось від себе.\n\nУбий його для мене.",
    },
    [91096] = {
        title = "Здобич: магістриса Жаробатіг (звичайний)",
        description = "На жаль, можна спопелити лише певну кількість невинних перехожих своїми вогняними кулями, перш ніж тебе виженуть з порядного товариства. Жаробатіг завжди більше цікавило полум'я, ніж друзі...\n\nВона спалила вже на одного спільного знайомого більше, ніж слід.\n\nЯкщо вона не приборкає свою силу, ми залюбки заберемо її собі.",
    },
    [91097] = {
        title = "Здобич: старший механік Озвольд (звичайний)",
        description = "Подейкують, що Озвольд власноруч підняв страхові внески в Ґномреґані ще до їхнього невеликого виходу звідти. Хай там як, він невпинно вдосконалює свої механізми, не зважаючи на те, чого це коштує іншим.\n\nЙого амбіції гідні захоплення, але його методи — непростимі.\n\nІди й поклади край його винахідницькій діяльності.",
    },
    [91098] = {
        title = "Здобич: Л-Н-0Р Утилізаторка (звичайний)",
        description = "Знаєш, чому її називають Утилізаторкою, {name}? Я — ні. І зважаючи на її історію зі «зниклими» помічниками з крамниці, я не надто схильний її розпитувати.\n\nТим не менш, дивися під ноги. Наскільки я розумію, вона полюбляє вбудовувати своїх жертв у власні механізми. Не хотілося б, щоб ти ста$p(в:ла) кишеньковим годинником чи чимось таким.",
        objectives = "Вистеж Л-Н-0Р Утилізаторку і вбий її.\n\nПоступ Полювання здобувається виконанням дій Здобичі, світових завдань, убивством рідкісних і збиранням скарбів у вибраній зоні.",
        completion = "Ти живий! І не кишеньковий годинник. Погляньте на нього. Гарна робота.",
