    [91197] = {
        title = "Збирання решток",
        description = "Доманаарам потрібні заражені Порожнечею рештки, щоб живити свої воєнні зусилля. Обшукай околиці або вбивай інших шукачів пригод по всій Височині Вбивць, щоб добути цей ресурс.",
        objectives = "Збери 50 заражених Порожнечею решток.",
        progress = "Доманаарам потрібні рештки, скверні Порожнечею, щоб живити свою війну. Нишпори по місцевості або вбивай інших шукачів пригод по всьому Височині Вбивць, щоб роздобути цей ресурс.",
        completion = "Дякую за твій внесок.",
    },
    [91206] = {
        title = "Неспокій лоа",
        description = "Тепер, як ми пробуємо докликатись до всіх лоа, згадався мені Кулзі, лоа медицини, — і те безумство, що коїться довкола його святилища.\n\nЙого речник, Сідж'та, був мені добрим другом. Скільки бойових загонів він зцілив від ран! Але біля святилища Кулзі щось сталося, і тепер там аж роїться від розгніваних духів.\n\nВони нападають на кожного, хто пробує до них достукатися, а лоа мовчить.\n\nМоже, тобі нарешті вдасться дотягнутися до лоа і знайти його речника!",
        objectives = "Знайди речника лоа Сідж'ту біля Святилища Кулзі.",
        completion = "Як це — у тебе немає ліків? Я ж відіслав тебе по них цілу вічність тому!\n\nМи мусимо йому допомогти... навіть якщо лоа не допоможе!",
    },
    [91207] = {
        title = "Здобич: верховний хижак",
        objectives = "Перемагай ворогів, щоб виманити свою здобич\nІстот убито\nЗасідку подолано",
    },
    [91210] = {
        title = "Здобич: магістр Санбрейкер (важко)",
        description = "Колись він був шляхетним магістром Сільвермуна, що присягнувся захищати Кель'Талас будь-якою ціною. Та він відколовся від ордену й тепер прагне помсти на власних умовах.\n\nЯ бачу в ньому дещицю себе самого.\n\nУбий його заради мене.",
    },
    [91211] = {
        title = "Здобич: магістр Санбрейкер (жахіття)",
        description = "Колись він був шляхетним магістром Сільвермуна, що присягнувся захищати Кель'Талас будь-якою ціною. Та він відколовся від ордену й тепер прагне помсти на власних умовах.\n\nЯ бачу в ньому дещицю себе самого.\n\nУбий його заради мене.",
    },
    [91212] = {
        title = "Здобич: магістриса Жаробич (важко)",
        description = "На жаль, можна спопелити лише певну кількість невинних перехожих своїми вогняними кулями, перш ніж вишукане товариство відцурається від тебе. Жаробич завжди більше цікавило полум'я, ніж друзі...\n\nВона спалила на одного спільного знайомого більше, ніж слід.\n\nЯкщо вона не приборкає свою силу, ми залюбки заберемо її собі.",
        completion = "Що я тобі казав, {name}? Найшвидша вогняна куля по цей бік Лісу Вічної Пісні.\n\nСхоже, тобі вдалося вціліти від найгіршого.",
    },
    [91213] = {
        title = "Здобич: магістриса Жаробич (жахіття)",
        description = "На жаль, можна спопелити лише певну кількість невинних перехожих своїми вогняними кулями, перш ніж вишукане товариство відцурається від тебе. Жаробич завжди більше цікавило полум'я, ніж друзі...\n\nВона спалила на одного спільного знайомого більше, ніж слід.\n\nЯкщо вона не приборкає свою силу, ми залюбки заберемо її собі.",
    },
    [91214] = {
        title = "Здобич: старший майстровий Озвольд (важко)",
        description = "Подейкують, що Озвольд власноруч підняв страхові внески в Ґномреґані ще до їхнього невеличкого виходу звідти. Хай там як, він невпинно вдосконалює свої механізми, незважаючи на те, чого це коштує іншим.\n\nЙого завзяття гідне захвату, та його методи — непростимі.\n\nІди й подбай, щоб його винахідницькі дні скінчилися.",
    },
    [91215] = {
        title = "Здобич: старший майстровий Озвольд (жахіття)",
        description = "Подейкують, що Озвольд власноруч підняв страхові внески в Ґномреґані ще до їхнього невеличкого виходу звідти. Хай там як, він невпинно вдосконалює свої механізми, незважаючи на те, чого це коштує іншим.\n\nЙого завзяття гідне захвату, та його методи — непростимі.\n\nІди й подбай, щоб його винахідницькі дні скінчилися.",
        completion = "Схоже, наш маленький друг подав свій останній патент.",
    },
    [91216] = {
        title = "Здобич: L-N-0R Утилізаторка (важко)",
        description = "Знаєш, чому її називають Утилізаторкою, {name}? Я ні. А зважаючи на те, як у неї «зникають» крамничні помічники, я не надто прагну її про це питати.\n\nХай там як, пильнуй за кожним кроком. Наскільки я розумію, вона полюбляє вбудовувати своїх жертв у власні механізми. Не хотілося б, щоб ти ста$p(в:ла) кишеньковим годинником чи чимось таким.",
    },
    [91217] = {
        title = "Здобич: L-N-0R Утилізаторка (жахіття)",
        description = "Знаєш, чому її називають Утилізаторкою, {name}? Я ні. А зважаючи на те, як у неї «зникають» крамничні помічники, я не надто прагну її про це питати.\n\nХай там як, пильнуй за кожним кроком. Наскільки я розумію, вона полюбляє вбудовувати своїх жертв у власні механізми. Не хотілося б, щоб ти ста$p(в:ла) кишеньковим годинником чи чимось таким.",
        completion = "Тобі вдалося вижити! І не стати кишеньковим годинником. Тільки поглянь. Чудова робота.",
    },
    [91218] = {
        title = "Здобич: Мордріл Тінепад (важко)",
        description = "Порожнеча — річ підступна, наче вода. Мудрі тримаються від неї на шанобливій відстані, ніколи не танцюючи надто близько до краю. Дурні пірнають у неї — і так тонуть.\n\nМордріл — небезпека для себе самого й для всіх навколо, так глибоко він загруз у власній одержимості.\n\nПодбай, щоб він більше не становив загрози для цього світу.",
        completion = "Я ніколи не тішуся смертю побратима-ельфа. \n\nЩо ж. \n\nЦього разу — ні.",
    },
    [91219] = {
        title = "Здобич: Мордріл Тінепад (жахіття)",
        description = "Порожнеча — річ підступна, наче вода. Мудрі тримаються від неї на шанобливій відстані, ніколи не танцюючи надто близько до краю. Дурні пірнають у неї — і так тонуть.\n\nМордріл — небезпека для себе самого й для всіх навколо, так глибоко він загруз у власній одержимості.\n\nПодбай, щоб він більше не становив загрози для цього світу.",
        objectives = "Вистеж Мордріла Шедоуфелла і вбий його.\n\nПоступ полювання дають заняття «Здобич», світові завдання, рідкісні вороги та скарби у вибраній тобі зоні.",
        completion = "Я ніколи не радію смерті ельфа-одноплемінника.\n \nНу...\n \nХіба що цього разу.",
    },
    [91220] = {
        title = "Здобич: Делія Хмуроспів (важко)",
        description = "У минулому житті Делія Хмуроспів була надзвичайно обдарованою ученицею — справжнім дивом честолюбства, таланту й невгамовної допитливості.\n\nСаме остання й узяла над нею гору.\n\nПоклади край її кривавій навалі вбивств.",
        objectives = "Вистеж Делію Похмуроспів і вбий її.\n\nПоступ полювання зростає від виконання занять Здобичі, світових завдань, рідкісних істот і скарбів у вибраній тобою зоні.",
        completion = "Вона цілилася в зорі, а впала серед Порожнечі...",
    },
    [91221] = {
        title = "Здобич: Делія Похмуроспів (Жахіття)",
        description = "У минулому житті Делія Похмуроспів була обдарованою ученицею — справжнім дивом честолюбства, таланту й невгамовної допитливості.\n\nСаме остання й узяла над нею гору.\n\nПоклади край її кривавій різанині.",
        completion = "Вона цілилася в зорі, а опинилася серед Порожнечі...",
    },
    [91222] = {
        title = "Здобич: Талаша Фазоклинок (Складно)",
        description = "Ефіріали... від них у мене мороз поза шкірою. Загадкові. Незбагненні. Я не довіряю нічому, чому не можу глянути в очі, поки воно плазує переді мною.\n\nМої розвідники доповідають, що в сусідній околиці завелася особливо небезпечна ефіріалка. Нам варто придушити це в зародку, поки ще можемо.",
        completion = "Схоже, руки-ноги в тебе цілі, та й ножа в спині не видно. Чудова робота, {NAME}.",
    },
    [91223] = {
        title = "Здобич: Талаша Фазоклинок (Жахіття)",
        description = "Ефіріали... від них у мене мороз поза шкірою. Загадкові. Незбагненні. Я не довіряю нічому, чому не можу глянути в очі, поки воно плазує переді мною.\n\nМої розвідники доповідають, що в сусідній околиці завелася особливо небезпечна ефіріалка. Нам варто придушити це в зародку, поки ще можемо.",
        completion = "Схоже, кінцівки в тебе цілі, і в спині жодного ножа. Гарна робота, {NAME}.",
