    [91301] = {
        title = "Як приборкати підопічного",
        description = "Я зробив усе, що вони просили, — випробування, уроки — і всі сказали, що я впорався добре... але я досі не знаю, де моє справжнє місце.\n\nКожен шлях по-своєму здавався правильним, і тепер серце моє тягне одразу в три боки.\n\nБудь ласка... допоможеш мені вирішити?",
        objectives = "Віддай обрану рекомендацію інструктору Талендіру в Сільвермуні.",
        completion = "А... отже, хлопець нарешті обрав. Серця йому не бракує — може, навіть занадто.\n\nТак. Це буде записано й ушановано. Це більше, ніж доставлене послання, — це допомога у формуванні цілого життя. Дякую.",
    },
    [91302] = {
        title = "Рясність: рясний гай",
    },
    [91309] = {
        title = "Корґот Голодар",
    },
    [91310] = {
        title = "Сорот Міазмаврат",
    },
    [91311] = {
        title = "Жнець",
    },
    [91312] = {
        title = "Стінолам",
    },
    [91314] = {
        title = "Невгамований потенціал",
        description = "{class} — я чув, ти досліджува$p(в:ла) Невгамований простір? Те місце просякнуте незайманою енергією Порожнечі. Я й сам залюбки дослідив би його, та всіх, хто туди наважувався вирушити, поглинула Порожнеча.\n\nМені потрібна допомога з моїми дослідженнями. У Печері Шраму Порожнечі є створіння, загублені у фазі, чию есенцію я хотів би вивчити. Якби ти зібра$p(в:ла) її для мене, я був би вдячний.\n\nДій обережно.",
        objectives = "Збери 5 есенцій, змінених фазою, у Відв'язаному Просторі.",
        progress = "Вдалося зібрати есенцію, змінену фазою?",
        completion = "Це неабияк просуне мої дослідження Відв'язаного Простору. Дякую тобі.\n\nНавіть не уявляю, які таємниці К'арешу ми тепер зможемо почати розкривати.",
    },
    [91328] = {
        title = "Таємні інгредієнти",
        description = "Наші компанійські гості так щедро черпали з наших запасів, що особливої солаарської синталії лишилося небезпечно мало.\n\nНасичений смак беланісу з його п'янким ароматом ідеально відтіняє гостру терпкість місцевих ягід. Усе це дбайливо готується, вимочується в нашій особливій суміші міцних напоїв і подається до столу — смакота, за яку й померти не шкода!\n\nТільки між нами: якщо з ягодами обійтися не так, як слід, настоянка може виявитися смертельною. А в іншому разі... смачно, бадьорить, очищає — розкіш!",
        objectives = "Збери 6 Беланійських квіток і 5 Сінарських ягід для соларіанської синталії.",
        progress = "Чи ретельно ти збираєш?",
        completion = "Магія! Досконалість! Навіть якби я виплекала тебе бажанням, ти не бу$p(в:ла) би вправнішим.\n\nЦікава думка. А раптом і виплекала?",
    },
    [91339] = {
        title = "Задушені в колисці",
        description = "Свого першого біса мені вдалося прикликати в брудному, повному диму кублі під Завулком Убивць — після дюжини невдалих спроб. Щоразу доводилося сягати далі, до того, що змушує так звані вищі сили коритися смертним. Зрештою все вийшло — після того, як мої руки зросила гаряча кров молодого кролика. Відтоді кривавий будяк уже не давав мені колишньої втіхи.\n\nЗ того часу моя техніка визріла. Знайди дитинчат цих звірів. Перекачай їхню енергію в мій релікварій темряви. З їхньої жертви ми почерпнемо силу, щоб здолати Калґорґа.",
        objectives = "Висмокчи 9 молодих звірят за допомогою Релікварію Темряви.",
        progress = "Не бійся сили, {NAME}: бійся тих, хто нею орудує.",
        completion = "Це теж природний лад речей.",
    },
    [91340] = {
        title = "Заради насильства",
        description = "Як і багато чорнокнижників, я зв'язую своїх демонів умовами контракту. Мені варто було збагнути, що Порожнеча й насильство цього світу можуть змінити правила, які здавалися мені непорушними. Калґорґ скористався цією силою, щоб розірвати свої пута й покласти край нашій угоді.\n\nКоли ми станемо перед Калґорґом, від нас має тхнути кров'ю і насильством. Убивай звірів, яких знайдеш, щоб показати Калґорґу: ми готові вчинити з ним так само. Владу над Порожнечею здобувають і втрачають за одну мить.",
        objectives = "Убий звірину на поверхні Лігва Предаксаса.",
        completion = "<Люсія оглядає тебе з ніг до голови, а тоді винагороджує жорстокою посмішкою.>\n\nЧудово. Ти така ж умілий, як і на вигляд.",
    },
    [91341] = {
        title = "Без обмежень",
        description = "Тепер — спускаємося. Енергія Порожнечі внизу не схожа ні на що з відчутого мною раніше — наче саме тяжіння поступається Порожнечі. Щойно ввійдеш до печери, її вплив ляже й на тебе.\n\nКалґорґ уже повбивав істот усередині й забрав їхню силу. Їхні жорстокі смерті лишили по собі якусь прокляту землю, але ми мусимо йти далі й заволодіти силою, що там ховається. Наповни релікварій по вінця.\n\nНе знаю, чого чекати від мого блукача Порожнечі. Нам знадобиться вся сила, яку тільки зможемо втримати.",
        objectives = "Збери Силу Порожнечі в Лігві Предаксаса.",
        progress = "Слід різанини, що він лишив по собі... Я майже пишаюся.",
        completion = "Калґорґ чекає перед нами. Час витратити зібрану тобою силу, щоб повернути його.",
    },
    [91342] = {
        title = "Хочеш зробити добре...",
        description = "З усіма бідами, що спіткали Ліс Вічної Пісні, у далекоходів роботи по самі вуха!\n\nЯ тямущий арканіст. Здавна захоплююся далекоходами — то чом би не прислужитися їхній справі своїм хистом? Вони стільки всього роблять руками, а дрібка магії подарувала б їм куди більше часу на пригоди!\n\nНа жаль, моя ідея із зачарованими мітлами пішла не зовсім так, як хотілося. Вони такі норовливі, що замість прибирати кидаються на новобранців!\n\nСхоже, цю проблему таки доведеться розв'язувати старою доброю ручною працею.",
        objectives = "Убий 8 буркотливих прибиральників.",
        progress = "Капітан Донраннер застерігає мене від спроб розв'язувати всі проблеми магією... Вочевидь, мені ще багато чого треба навчитися.",
        completion = "Прибирати все одно доведеться, та принаймні тепер на нікого не нападатимуть.",
    },
    [91343] = {
        title = "Нагорода за амбіції",
        description = "Релікварій наповнено силою, з якої я можу черпати. Тепер пожнемо плоди наших приготувань.\n\nКалґорґ чекає просто попереду — висмоктує звіра, що колись зробив цю печеру своїм лігвом. Ослаб Калґорґа, і я зв'яжу його, як колись, багато років тому.",
        objectives = "Приборкай Калґорґа Розкутого.",
        completion = "Калґорґ поглинув чимало енергії Порожнечі в тій печері, а отже, її вплив уже навряд чи здолає моїх родичів. Гадаю, якась користь із цього таки вийшла.\n\nМушу зробити Калґорґу щонайменший комплімент. Бувши приборканим звіром Порожнечі, я теж намагалася б утекти. За це він має мою повагу.\n\n<Люсія обертається до Калґорґа з гострою посмішкою.>",
    },
    [91345] = {
        title = "До Північної Вежі",
        description = "Рейнджер Валсарін — кухар у Твердині Далекоходів. На кухні він дає собі раду, але справжня його пристрасть — похідна кухня.\n\nБули часи, коли можна було піти будь-якою стежкою Лісу Вічної Пісні й назбирати складників на добрячий обід. Мрія далекохода! Досить докласти рук — і ми допоможемо лісу відродитися, а починається все з оздоровлення ґрунту.\n\nЗустрінься з Валсаріном біля Північної Вежі, і він розповість більше.",
        objectives = "Зустрінься зі слідопитом Валсарін біля Північної вежі.",
        completion = "Сподіваюся, ти не проти забруднити руки.",
    },
    [91346] = {
        title = "Прохачі Богині",
        description = "Ми здавна доглядаємо коріння разом з істотами, які тут живуть і ростуть. Вважай це симбіозом, з якого маємо користь і ми, і істоти, і коріння. Щоправда, мій напарник Річколуск останнім часом не надто старається!\n\nПрошу, допоможи мені знайти спосіб знову його розворушити.\n\nСпершу треба змити з себе есенцію зовнішнього світу. Очисться у водах Гар'куаю.",
        objectives = "Очисться у водах Гар'куаю.",
        completion = "Може здатися, що це дрібниця, але все це — частина процесу.",
    },
    [91347] = {
        title = "Тупіт яструбоступів",
        description = "Аж не віриться, що колись тут пролягав Мертвий Шрам.\n\nТут, ближче до міста, земля майже повністю відновилася. І це добре, бо ротів у нас чимало.\n\nЯструбоступи — ідеальні помічники для підготовки ґрунту. Їхні міцні кігті чудово розкидають насіння і чавлять шкідників!\n\nСпускайся до Тихого Спокою, і я осідлаю одного для тебе.",
        objectives = "Осідлай яструбоступа і підготуй Тихий Спочинок до садівництва.",
        progress = "Немає нічого кращого за сівбу.",
        completion = "Не знаю, що й думати про ті великі суцвіття... та хай що ми робимо, земля, схоже, задоволена.",
    },
    [91348] = {
        title = "Мана-справа до вирма",
        description = "Манавирми, може, й не такі показні, як рисі чи яструбоступи, але саме вони підтримують плин магії в лісі.\n\nВони збираються на лей-лініях, щоб линяти, та часом трохи нервуються. І тоді ми мусимо їм допомогти! Силою!\n\nКілька лей-каналів уже напоготові — з них і почнемо. Знайди вирмів, яким, на око, не завадила б поміч, і лупцюй їх, доки не скинуть арканний панцир. Не хвилюйся — уся та мана врешті повернеться до лісу!",
        objectives = "Завзято допоможи 8 збудженим манавирмям із линянням.",
        progress = "Не хвилюйся! Вони миттю оговтуються.",
        completion = "Ще одне вдале линяння... За кілька тижнів повернемося сюди й почнемо все спочатку!",
    },
    [91349] = {
        title = "Темний закуток лісу",
        description = "Більша частина лісу відновилася, але на півдні... Усе, що випало на долю Лісу Вічної Пісні, — Погибель, Скверна, а тепер і Клинок Сутінків — уся ця магія просочується в ґрунт. Вона накопичується в істотах, аж доки геть не поглинає їх...\n\nМої прилади вміють виявляти зараження в цих тваринах. Тих, кого вже не врятувати, ми відбракуємо, а решту — врятуємо. Веселого мало... але це заради добра Лісу Вічної Пісні!",
        objectives = "Перевір 8 істот на зіпсуття і розберися з наслідками.",
        progress = "Це важка праця, але зрештою вона принесе спокій.",
        completion = "Ці бідолашні малята... Вони вціліли лише завдяки тій дивній магії!\n\nЯ не такий простак, щоб вірити в старі легенди... та що ж іще це могло бути?",
    },
    [91350] = {
        title = "Справжнє доручення",
        description = "Капітан Доунраннер мала перевірити Анклав, а тоді зустріти нас тут. Рейнджерки вправнішої за неї ще пошукати! Якщо її щось затримало — це поганий знак.\n\nВ Анклаві Далекоходів зазвичай проводять вишкіл у дикій місцевості. Але через усі ці негаразди кожного відіслали деінде. Вона може бути там сама-одна, у серйозній небезпеці!\n\nНе можна гаяти ні хвилини. Я врятую свого капітана і доведу, що мені місце серед далекоходів!",
        objectives = "Знайди капітанку Світанкобіжку в Анклаві далекоходів.",
        completion = "Ось що буває, коли нема кому прибирати!\n\nУсі прагнуть пригод, але ніхто не хоче брати мітлу.",
    },
    [91359] = {
        title = "Батожників — геть!",
        description = "Жити в Гарандарі — благословення, але й обов'язок. Цими землями в'ється коріння Світових Дерев. Ми плекаємо його — і воно буяє. Ось чому так важливо, щоб Річколуск повернувся до служби.\n\nТреба очищати ці землі від грибних батожників, поки вони не присмокталися до коріння. Є й приємний бонус: Річколуск страшенно любить листя батожників. Знайдеш і принесеш йому трохи?",
        objectives = "Збери 6 Гармонійних Листків на околицях Гар'куаю.",
        progress = "Важливо не давати батожникам висмоктувати цінні поживні речовини зі Світового Дерева.\n\n...а ще я люблю розпещувати свого впертого малюка.",
        completion = "Хотілося б, щоб мій помічник не був найледачішим за всю історію помічників, але таке життя!\n\nЯкщо вже його улюблені ласощі його не піднімуть — то не підніме ніщо.",
    },
    [91360] = {
        title = "Виполоти небажане",
        description = "Коріння Світових Дерев напоєне і поживою, і магією Гарандару. Як усякі великі судини, воно притягує до себе небажану фауну і флору. Дещо з того нешкідливе, але коріння ми воліємо тримати чистим.\n\nУ гаранірів часто буває алергія на зелені бур'яни, що розростаються попід корінням Світових Дерев. Якщо повириваєш їх із коренем, заощадиш нам купу часу — і вбережеш від кропив'янки!",
        objectives = "Вирви 8 Алергенних Бур'янів на околицях Гар'куаю.",
        completion = "Ти просто гроза бур'янів — і жодної кропив'янки!",
    },
    [91361] = {
        title = "Знову до служби?",
        description = "Нарешті! Я знала, що малий впорається.\n\nНі, це відверта брехня. Якби цей повзун гаю міг якось залізти назад у свій кокон, він давно був би там.\n\n<Сієнна зітхає.>\n\nЙого другі улюблені ласощі — картопуха. Якщо не спрацює, треті улюблені — пелюсткокрил. Після цього він має повернутися до своїх обов'язків — полювати на кліщів.\n\n...Хребет у мене — як мокра стеблина.",
        objectives = "Допоможи Річколуску повернути впевненість: убий 8 картопух і пелюсткокрилів на околицях Гар'куаю.",
        completion = "Я знала, що ти впораєшся, Річколуску! Хто хороший повзун гаю? Хто найкращий повзун з усіх?\n\nХто великий сильний повзун гаю, що вміє вчити чужинців дбати про Світові Дерева?\n\n<Сієнна підводить погляд на тебе.>\n\nТобі вдалося вибити з нього лінощі, {NAME}. Не знаю, як і дякувати за допомогу.",
    },
    [91363] = {
        title = "Жнива темряви",
        description = "А ти... зроби щось корисне.\n\nЯ приборкую жахливих звірів, і моя справа — виховувати з цих малят страхітливих бестій. Я нацьковую їх одне на одного, і вони стають дедалі лютішими.\n\nАле тутешні ельфи запевняють, що кращих результатів я доб'юся дрібкою... ласки й турботи. Що ж, перевірмо.\n\nЦей малий — Фідофікус. Ти виявлятимеш до нього ніжність і прихильність, а тоді побачимо, наскільки лютим він виросте.\n\nНазбирай для нього смачних поживних ласощів і повертайся до мене.",
        objectives = "Збери 10 Просочених Порожнечею шматочків і 6 Сяйливих світлошапок за межами Виючого Хребта.",
        progress = "З цих складників вийде надзвичайно поживна й така само смаковита страва.",
        completion = "Фідофікус прославиться своєю лютістю.\n\nЯ бачу, як у ньому росте насильство.\n\nОдного дня він стане гідним улюбленцем для такого доманаара, як я.",
    },
    [91375] = {
        title = "Тиша в селищі Фунґара",
        description = "У селищі Фунґара вже давненько тихо.\n\nМи були здебільшого зайняті Світлоцвітом і загрозою, яку він несе, тож не мали часу навідатися до фунґаріан на сході. Зазвичай вони галасливі, але з ними можна дати раду... а от щоб зовсім замовкнути — таке в них трапляється рідко.\n\nЯ вирушаю розібратися. Якщо хочеш довести, що ти $p(справжній союзник:справжня союзниця), варто піти зі мною.",
        objectives = "Розшукай Ґікал біля селища Фунґара в Гарандарі.",
        completion = "Зазвичай я б і не замислюючись відкинула втручання чужинця... але зважаючи на обставини, від тебе, можливо, буде якась користь.",
    },
    [91376] = {
        title = "Маленькі чудовиська",
        description = "Мені й на думку не спадало, що у відповідь на прохання про допомогу Гар'альнор пришле чужинця. Та нехай.\n\nМешканці селища Фунґара замовкли. Здавалося б, мені варто радіти: вереск у них просто нестерпний. Але те, як вони тиняються, ледве переставляючи ноги... наче забули, що й досі живі.\n\n<Ґікал здригається.>\n\nМої спроби підійти ближче скінчилися тим, що вони накинулися на мене, щойно помітили.\n\nМені знадобляться зразки їхньої плоті. Іди й принеси їх мені — треба з'ясувати, що тут сталося.",
        objectives = "Збери 10 зразків дивного міцелію з колишніх мешканців селища Фунґара.",
        progress = "Не знаю, що тут коїться, але — про всяк випадок... не дозволяй їм себе кусати, гм? Хай що їх вразило, воно може бути заразним.",
        completion = "Богине, боронь. Це зовсім не плоть фунґаріана.\n\nТо ЩО ж вони таке?",
    },
    [91377] = {
        title = "Поріддя мертвих",
        description = "Очевидно, що в селищі сталося щось жахливе. Звідси мені видно тіла їхніх найбільших особин, розкидані південними околицями, але й з ними щось не так. Фунґаріани зазвичай не лишають тіла родичів просто валятися.\n\nІ хоч я спостерігаю здалеку, присягаюся: деякі з них... сіпаються.\n\nРозвідай усе. Дізнайся, що зможеш, і повертайся до мене зі звітом.",
        objectives = "Обстеж 5 квітучих трупів у селищі Фунґара.",
        completion = "Усе набагато гірше, ніж мені здавалося.\n\nМи мусимо знайти джерело цієї зарази й знищити його, поки воно не вразило щось більше й небезпечніше за фунґаріана.",
    },
    [91378] = {
        title = "Ти — легенда",
        description = "Чим би ці істоти не були, вони не фунґаріани. Уже ні.\n\nГар'альнору й без того вистачає клопоту зі Світлоцвітом. Він не може дозволити собі опинитися в лещатах між його силами й цими... істотами.\n\nЗроби те, що має бути зроблено. Знищ їх стільки, скільки зможеш.",
        objectives = "Убий 15 дезанімованих фунґаріан у північній частині селища Фунґара.",
        progress = "Не шкодуй. Ці істоти більше не живі. Принаймні не в тому сенсі, який має значення.",
        completion = "Аберації ти нищиш просто майстерно. Може, варто подумати про ремесло мисливця на чудовиськ.",
    },
    [91379] = {
        title = "Зотліла земля",
        description = "Наскільки можу судити, всі ці фунґаріани вже мертві. Щось оживляє їхні тіла зсередини, смикаючи ними, мов ляльками на невидимих лозах.\n\nГрибна маса, що їх заполонила, мусить звідкись братися... і, судячи з розмірів тих, що далі на північ, там ми знайдемо її вдосталь. Знайди її та позбудься, але, заради Альн'гари, не вдихай її.",
        objectives = "Знищ 8 наростів плодоносного міцелію в селищі Фунґара.",
        completion = "Найгірші нарости на півночі ми викорчували... але менші вже пнуться із землі. Звідки вони беруться?\n\nДесь мусить бути джерело, і нам доведеться його знайти, якщо хочемо покласти цьому край.",
    },
    [91380] = {
        title = "Черево звіра",
        description = "Зазвичай я вигодовую своїх звірів сирими скривавленими тушами й душами, роздертими Порожнечею.\n\nАле спробуємо по-вашому, по-смертному.\n\nКажуть, ти... куховариш? І від цього ласощі стають кращими?\n\nЗроби це. Потім поведи його на прогулянку довкола Виючого Хребта. Навіть мені відомо, що рух корисний для травлення.\n\nСлужити мені гідні лише найлютіші створіння. Сподіваюся, ні ти, ні Фідо мене не розчаруєте.",
        objectives = "Годуй і вигулюй Фідофікуса Виючим Хребтом, щоб сприяти його зростанню й лютості.",
        progress = "Він ще малий, та одного дня з нього виросте страхітливий супротивник.",
        completion = "Чи росте лютість звіра?\n\nЯ певен, що скоро почну чути про його насильство від тих, хто живе довкола Виючого Хребта.",
    },
    [91381] = {
        title = "Мовчазне зло",
        description = "Не розумію. Ми обнишпорили все вздовж і впоперек, північ і південь. Куди не підемо — всюди оживлені трупи та дрібні плодоносні гриби, але де ж центральне тіло? Де--\n\nО, богине. Ну звісно.\n\nВода, {class}. Перевір воду.",
        objectives = "Знищ Аґерикуса Деканіматуса.",
        completion = "Отже, справу зроблено.\n\nВижити й не підхопити зарази — неабияке досягнення. Дикі землі небезпечні, і виживання тут ніхто не обіцяє.\n\nА тепер іди. Я мушу лишитися й подбати, щоб ці гидоти не розповзлися далі.",
    },
    [91382] = {
        title = "Могутній і неперевершений",
        description = "Звір нагодований і вигуляний. Тільки уяви, смертне створіння... одного дня його паща виросте так, що ти вмістишся в ній тисячу разів.\n\nТепер перевіримо, чи здатний він на справжнє насильство.\n\nНа південь від Виючого Хребта якась бестія зайняла собі лігво.\n\nФідофікус тепер тобі довіряє. Іди з ним — і стань свідком його могутності.",
        objectives = "Стань свідком лютості Фідофікуса, коли він уб'є Зітоца, пожирача лігва.",
        progress = "Фідофікус став грізним, і, можливо, частка його зростання належить і тобі.",
        completion = "Прикро, що звір виявився таким жалюгідним і кволим, як і ви, смертні.\n\nВи варті одне одного.",
    },
    [91383] = {
        title = "Наведи лад",
        description = "З капітаном Доунраннер усе гаразд, дякувати сонцю. Єдина небезпека в тому, що... ми геть занедбали побутові справи.\n\nЦе не героїчно й не романтично, але Анклав Далекоходів не може лишатися в такому стані. Тутешні слідопити завалені роботою по самі вуха. Тож долучаймося всі — допоможемо їм навести тут лад.\n\nАж не віриться, що все зрештою зводиться до підмітання. Ось у чому насправді полягає служба далекохода.",
        objectives = "Розчисти 5 захаращених гнізд і вимети 5 запорошених павутин.",
        completion = "Мої слідопити сьогодні відпрацьовують свій хліб, це вже точно.",
    },
    [91384] = {
        title = "Місія з повернення",
        description = "Ми розсилаємо далекоходів по всьому лісу — битися з амані, зі Світлоцвітом, з Порожнечею... але за всіма цими подвигами нікому доглянути за звіриною! Ані дати лад будівлі! Ані вести облік припасів!\n\nІ тепер наш любий Анклав скидається на загороду для яструбоступів. З мене досить!\n\nДопомогти я, може, й не в змозі, але вірю: ви всі разом позбираєте все, що звідси розтягли, і це місце знову матиме пристойний вигляд.",
        objectives = "Збери 12 розкиданих припасів довкола Анклаву далекоходів.",
        progress = "Якщо ми хочемо бути корисними решті Лісу Вічної Пісні, спершу мусимо дати лад у себе.",
        completion = "Це добрий початок. Досить лише, щоб жменька з нас доклала трішки зусиль.",
    },
    [91385] = {
        title = "Дух слідопита",
        description = "Сьогодні Темін довів, що вправний не гірше за будь-якого далекохода. Та боюся, сам він може дивитися на це інакше.\n\nВін прийшов до нас із такими піднесеними уявленнями про слідопитів — усі ті історії про відчайдушні пригоди, усі ті романтичні старі легенди. А насправді служба слідопита — це здебільшого... клопоти. Важкі, нудні, важливі клопоти.\n\nМоже, підеш поговориш із ним? І переконайся, що він не надто розчарований.",
        objectives = "Знайди новобранця Таеміна.",
        progress = "Краса лісу? Вона ніколи не набридає.",
        completion = "Легенди справжні... Ліс Вічної Пісні, мабуть, задоволений нами!",
    },
    [91386] = {
        title = "Скроєно до сказу",
        description = "Ці... туристи! Ці невиховані, невдячні нечупари!\n\nАвангард Світла, певна річ, приніс Сільвермуну чимало замовлень. Але ніхто з них по-справжньому не цінує, що таке таласійська майстерність. Жодної поваги до ельфійських мистецтв — їм аби блискучі, лискучі сувеніри!\n\nЯ вам не джерелобіжець, щоб витанцьовувати їм на потіху... але ж і відмовити їм не випадає, чи не так? Мабуть, із помічником це огидне завдання стане стерпнішим.",
        objectives = "Допоможи Солвіну Брайтстітчу шити одяг для нахабних паладинів.",
        progress = "Якби ж хоч одна душа серед цих мугирів виявила бодай краплю вдячності... та ба, схоже, навіть таке мале прохання для них — завелике.",
        completion = "Гаразд... але лише тому, що мені цікава майстерність роботи.\n\nЗнадобиться щось більше за дрібку ввічливості, щоб змінити мою думку про цих паскудних паладинів.",
    },
    [91388] = {
        title = "Незвичайні нитки",
        description = "Наш замовник — Ґаарі, здається, — має дякувати долі. Ці манавирми прядуть найтонший шовк у Лісі Вічної Пісні. Знаю магістрів, які пішли б на вбивство заради мантії з таким оздобленням, — а ми тут пускаємо його на латання. Ну що ж.\n\nКоли вирми досхочу наїдяться арканної енергії, зможеш стягнути з них шовк на оці котушки.\n\nЯкщо ж віддавати шовк вони не схочуть, доведеться, е-е... вибити його з них. Але мене запевнили, що це цілком етично.",
        objectives = "Висмокчи 8 повних котушок манашовку з ослаблених вирмів у Північному Святилищі.",
        progress = "Це, звісно, найлегша частина.",
        completion = "Ах... прекрасний, мерехтливий манашовк. Такий повний потенціалу.",
    },
    [91389] = {
        title = "Одяг красить людину",
        description = "Арканотканий плащ вишуканий не лише завдяки матеріалу, а й самому процесу ткання.\n\nПолагодити такий — надто той, що увібрав стільки історії та прихованої арканної енергії... Мене чекає воістину небезпечне кравецтво. Нарешті — справжній доказ моєї майстерності.\n\nАж дух захоплює. Сподіваюся, нічого не вибухне. Як підготуєшся, зустрінемося всередині.",
        objectives = "Зустрінься із Солвіном усередині, а тоді відбивай будь-які прояви, поки він лагодить плащ.",
        completion = "Це справжня краса... Я радий знати, що він у руках того, хто так його любить.",
    },
    [91390] = {
        title = "Особливе доручення: що лишилося від розбитого храму",
        objectives = "Щоденні завдання в Розбитому Троні виконано",
    },
    [91391] = {
        title = "Досі в розвідці",
        description = "Коли Альянс уперше бився тут з Ордою, Курдран служив розвідником. І дотепер він розвідник хоч куди. Він полетів на своєму грифоні до гори Блекрок — глянути, з якими силами нам там доведеться мати справу.\n\nЗустрінься з ним — і подивіться разом, скільки клопоту зумієте наробити.",
        objectives = "Зустрінься з Курдраном біля гори Блекрок.",
        completion = "Араторе, {NAME} — дякую, що прийшли. Темної Орди там повнісінько.",
    },
    [91392] = {
        title = "Жадібний посланець",
    },
    [91395] = {
        title = "Завдання відстеження",
    },
    [91398] = {
        title = "Фоліанти жаху",
        description = "Знання — то сила, а оґри, бач, узялися читати.\n\nПринеси мені їхні фоліанти, щоб та сила більше ніколи в них не виросла.",
        objectives = "Убий оґрів в Атал'Калдані й збери 4 фоліанти.",
        progress = "Принеси мені ті фоліанти.",
        completion = "Дякую тобі. Оці підуть прямісінько у вогонь.",
    },
    [91399] = {
        title = "Попіл Порожнечі",
        description = "З елементалів Порожнечі є одна користь.\n\nПил, що з них сиплеться, годиться для ритуалів магії тіні.\n\nНазбирай трохи для нашого племені.",
        objectives = "Убий елементалів Порожнечі й збери їхній попіл.",
        progress = "Не хвилюйся, ми проводимо ці ритуали вже століттями.",
        completion = "Наші мисливці добре скористаються цим порохом. Дякую тобі.",
    },
    [91400] = {
        title = "Клинки полеглих",
        description = "Після битви ми покинули чимало своєї зброї.\n\nПозбирай її, будь ласка, щоб вона не дісталася Клинку Сутінків.",
        objectives = "Збери в Атал'Калдані 12 одиниць зброї амані.",
        completion = "Дяка за зібрану зброю. Тепер наші вороги не отримають переваги від майстерної роботи амані.",
    },
    [91401] = {
        title = "Мертві до смерку",
        description = "Культистам Клинка Сутінків стало нахабства спробувати відбити наш храм. Перебий пеонів і принеси мені їхні стегнові кістки.",
        objectives = "Збери 20 стегнових кісток із культистів Клинка Сутінків в Атал'Калдані.",
        progress = "Чому стегнові кістки? Не твоя турбота.",
        completion = "У мене є задум щодо цих кісток. Дякую.",
    },
    [91402] = {
        title = "Надсмертоносний ультрадон",
        description = "Мені на очі трапилися елементалі Порожнечі — вони проводили якийсь підозрілий ритуал посеред поля бою. Скидалося на те, що вони прикликають створінь Порожнечі.\n\nХай там що вони прикличуть — подбай, щоб із ним було покінчено.",
        objectives = "Убий Видатного ультрадона в центрі Атал'Калдану.",
        progress = "Якщо вони почнуть тягнути сюди Порожнечу, клопоту буде повна торба.",
        completion = "Такого мені ще бачити не доводилося — і сподіваюся, більше не доведеться. Чудова робота.",
    },
    [91403] = {
        title = "Ймовірний паралізатор",
        description = "Галаззі каже, що Лихогіллі зробили нову отруту, яка пара... паралі... ну, від неї жертва не може рухатися — щоб її можна було затягти на жертвоприношення. Каже, це жаб'яча отрута.\n\nЯ кажу: це ж безглуздя якесь. Жаби ж і так отруйні, хіба ні? А Галаззі каже, що зазвичай жаби носять отруту на собі, а не жалять нею. Але в цих є гострі рогові шпички, тож, може, вони таки вміють її впорскувати! Для мене новина, що жаби таке можуть, — а для тебе?\n\nНумо з'ясуємо, чи вміють оці, — і тоді Візербарки зможуть зробити протиотруту!",
        objectives = "Збери 8 Отруйних Рогів з рогатих жаб.",
        progress = "Галаззі каже: одні отруйні, коли кусають чи жалять тебе, а інші — коли ти сам їх кусаєш або їси! Хіба не цікаво?",
        completion = "Поглянь, скільки зразків! Вождь точно знатиме, хто зможе зробити протиотруту.",
    },
    [91404] = {
        title = "Найлихіша отрута",
        description = "Лихогіллі варять іще більше гидоти. Іди до самого джерела і поклади цьому край!\n\nГалаззі занюхав місце, де вони змішують отрути, — десь на південному сході. І він гадає, що там не сама лише жаб'яча отрута.\n\n...А, Галаззі ще просив принести якесь величезне ікло. Хоча в жаб же не буває ікол. Ну, все одно знайди його!",
        objectives = "Убий Проклинача Отрут Раксіса та знайди ікло, яке описав Тобуї.",
        progress = "Ну що, знайшлося те велике ікло?",
        completion = "Гей, це ж павуче ікло. Ото, мабуть, був величезний павук!",
    },
    [91405] = {
        title = "Перевірка отрути",
        description = "Отже, в сумішах є і жаб'яча, і павуча отрута. Галаззі каже: він відчуває, що хтось благав Шадру через те ікло. Мабуть, то дуже великий павук, якщо ікло в нього таке здоровенне!\n\nГалаззі не до вподоби, що воно було в Лихогіллів. Я це бачу. Він невеселий. Вуха в нього геть прищулені — пласкі, наче крила шуліки.\n\nТож треба допомогти. Віднеси зразки та ікло вождю Візербарків. У нас, Візербарків, є алхіміки, що зварять протиотрути і від павуків, і від жаб.",
        objectives = "Поговори з вождем Візербарків і знайди в селищі алхіміка, що робить протиотрути.",
        completion = "То це Лихогіллі щось замислили з Шадрою?\n\nНевже павуки діють проти Візербарків? Це якесь безглуздя.",
    },
    [91406] = {
        title = "Далеко від Загір'я",
        description = "Я з роду Торнтусків із племені Ревантусків, тож остерігаюся Візербарків — через нашу спільну історію у Загір'ї. Саме через них моя родина перебралася сюди.\n\nТутешні Візербарки в Зул'Амані наче й поважають нас, але ті Візербарки, яких я пам'ятаю з Загір'я, убивали своїх союзників і били їм у спину заради влади.\n\nВони поклонялися павучій лоа — Шадрі.\n\nКоли Шадра'Алор, храм Візербарків у Загір'ї, упав, Візербарки мусили кудись утекти. Пошукай довкола сліди Візербарків із Загір'я — і самої Шадри.",
        objectives = "Розслідуй Візербарків із Внутрішніх земель на ознаки Шадри.",
        completion = "Усі ті місцини, що вони згадали, просто поруч із Шадра'Алором! Вони, певне, поклонялися Шадрі.\n\nНе можна їм довіряти. Вони мов та отрута, що нею послуговуються. Вони нацькують решту племені проти Ревантусків -- проти всіх нас!",
    },
    [91407] = {
        title = "Око лоа",
        description = "Отрути з павуків Шадри забрали в мене друзів у Загір'ї. Мушу знати, чи не чаїться Шадра десь тут, каламутячи розум цим Візербаркам. Жоден Ревантуск не буде в безпеці в Зул'Амані, поки поруч Візербарки, що поклоняються Шадрі!\n\nМоже, я здаюся параноїком, але на те є причини. А до тебе Галаззі дослухається. Попроси його відкрити тобі всіх прихованих павуків, гаразд? Я знаю: ті довгі вуха чують, як вони шарудять лапками!\n\nПозаду мене є вівтар. Стань перед ним — може, він дарує тобі благословення.",
        objectives = "Знайди свідчення Шадри на Кручах Візербарків з допомогою Галаззі.",
        progress = "Галаззі допоміг тобі? Він може почути будь-що, але й бачить те, що ховається в тіні.",
        completion = "Павуки повтікали? Я думав, вони дадуть справжній бій. І кажеш, вони були малі? Гм.\n\nВтім, байдуже. Галаззі вже поставив нас на це полювання. Треба довести його до кінця.",
    },
    [91408] = {
        title = "У пошуках Шадри",
        description = "Плутанину між Візербарками й Лихогіллями ми скоро розплутаємо. Та найперший наш клопіт — лоа Шадра та її підступи.\n\nПавуки на моїх очах розбігалися від тебе в жаху, і дещо мене вразило. Вони не просто тікають у паніці — вони кудись прямують... туди, де почуваються в безпеці. І тепер навіть я їх бачу.\n\nВони більше не ховаються. Вони тікають! Наше полювання триває.\n\nХодімо за ними.",
        objectives = "Іди за павуками, щоб з'ясувати, куди вони ведуть.",
        progress = "Куди веде цей слід — туди йдемо й ми.",
        completion = "Вислухаймо його, але тримай руку на зброї.",
    },
    [91409] = {
        title = "Сни про павуків",
        description = "Реліквій Шадри три. У мене були лише дві: ікло — в селищі, а око заховане тут. Мабуть, вони якось викрали ікло, а тоді прийшли по око!\n\nПанцира Шадри в нас ніколи не було — він загубився, коли ми покидали Шадра'Алор. Можливо, панцир тепер у Лихогіллів.\n\nІкло й око дозволять нам ненадовго поговорити з Шадрою — хай навіть без останньої ритуальної реліквії прикликати її ми не зможемо.\n\nХодімо зі мною. Я покажу тобі, як це зробити.",
        objectives = "Спробуй провести ритуал з іклом та оком, щоб поговорити з Шадрою.",
        progress = "Двох реліквій має вистачити, щоб поговорити з видінням Шадри.",
        completion = "Оце та Шадра, яку я пам'ятаю з Шадра'Алору. Вона допоможе нам, якщо ми допоможемо їй.\n\nВона дотримує обіцянок.",
    },
    [91410] = {
        title = "Спільна лоа",
        description = "Вождь Візербарків знає, що багато хто з нас прийшов із Загір'я зі своїм поклонінням із Шадра'Алору, але він вважав, що Шадра давно мертва.\n\nТреба сповістити його, як Галаззі допоміг нам знайти й відродити Шадру, і про те, що Шадра тепер у крипті Візербарків. Ще він має дізнатися про порозуміння з Ревантусками.\n\nЯ поки залишуся із Шадрою. Понесеш звістку?",
        objectives = "Поговори з вождем Візербарків про Шадру.",
        completion = "Тепер, коли Шадра з нами проти Лихогіллів, ми жорстоко покараємо їх за лихі діяння.",
    },
    [91411] = {
        title = "Печери Майсари: У глибині Майсари",
        description = "Шадра попросила нас повернути третю частину ритуалу Змішувача Джаманґи — Панцир Шадри. З ним, можливо, ми зможемо повернути і її саму.\n\nВона визнала своїми союзниками і Візербарків, і Ревантусків. Її схвалення лягло на всіх нас — я це відчуваю. Вірю, що це правильний вибір.\n\nНа цей шлях нас поставив Галаззі, і в кожного з нас своя роль, щоб пройти його до кінця. Збирай союзників і рушай до Печер Майсари! Гадаю, панцир тримає хтось із їхніх ватажків. Убий їх і забери його.",
        objectives = "Здобудь Панцир Шадри з глибин Печер Майсари.",
        progress = "Гадаю, Шадра дотримає слова.",
        completion = "Навряд чи це було легко. Певно, Галаззі благословив твоє полювання.",
    },
    [91412] = {
        title = "Повернення Королеви Отрут",
        description = "Час повернути Шадрі належне їй місце — місце лоа Візербарків і Ревантусків. Спершу вона буде малою, та колись може стати великою, як Галаззі й Налоракк!\n\nНавіть мала лоа стане доброю союзницею проти отрут Лихогіллів. Вона — Лоа Шпигунів, і не дасть їм красти наших людей і реліквії, як Галаззі ховає їх у туманах.\n\nСтань із Панциром Шадри в центрі зали — і ми прикличемо лоа до нас!",
        objectives = "Дотримуйся ритуалу Змішувача Джаманги, щоб відродити Шадру.",
        progress = "Це більше, ніж повернення лоа, — це міст між племенами.",
        completion = "Ця подорож... відкрила мені очі.\n\nЯкби на її початку хтось спитав, чи станемо ми союзниками Шадри, — відповіддю був би сміх просто в обличчя!",
    },
    [91413] = {
        title = "Кінець сутінкової клятви",
        description = "<Стародавні руни на сторінці немовби звиваються під твоїм поглядом. Їхня сила, здається, стрімко згасає.>\n\n<Ве'нарі це зацікавить.>",
        objectives = "Віднеси Знак Сутінкової Клятви Ве'нарі в Оазу на К'ареші.",
        completion = "Салгадаар обдурив смерть, щоб воскресити Дименсіуса, і обдурив її знову, утікши від твого гніву.\n\n<Ве'нарі на мить замовкає.>\n\nШкода, що він утік, але Всепожирач загинув. Дякую.",
    },
    [91417] = {
        title = "Знайди Аратора",
        description = "Я бачу, що мій син проводить час із пораненими. Зроби батькові просту послугу й поглянь, чи не знадобиться йому твоя допомога.",
        objectives = "Поговори з Аратором коло поранених воїнів Авангарду.",
        completion = "Ці люди так завзято б'ються за нас. Ми мусимо зробити все можливе, щоб їх захистити.",
    },
    [91419] = {
        title = "Панування стихій",
        objectives = "Влучте снарядом Порожнечі в елементалів або вбий гравців\nВлучте снарядом Порожнечі в елементаля",
    },
    [91420] = {
        title = "Обмін",
        description = "<Загадковий мінерал гуде в твоїй руці. Хтось у Тазавеші знайде йому застосування. Пошукай на Прихованому ринку когось зацікавленого.>",
        objectives = "Принеси свою знахідку до Ом'м'юза в Тазавеші.",
        completion = "<Ом'м'юз пильніше роздивляється руду.>\n\nВельми цікавий камінець тобі трапився. Я хотів би дослідити його докладніше — як і будь-які інші, що ти знайдеш. Що скажеш про обмін?\n\nІнші члени картелю Ом на Завуальованому Ринку теж можуть бути зацікавлені в обміні товарами, якщо тобі трапляться.",
    },
    [91423] = {
        title = "[НЕ ВИКОРИСТОВУВАТИ]",
    },
    [91426] = {
        title = "Заступник народу",
        description = "Гадаю, наразі ми зробили все, що могли, {name}. Повертаймося до місця збору.",
        objectives = "Повернися до місця збору разом з Аратором.",
        completion = "Ми добре попрацювали там, {name}. Це все, на що ми будь-коли можемо сподіватися.",
