    [91437] = {
        title = "Набір учасників",
        description = "<Ти знаходиш у кишені сувій, якого там раніше не було.>\n\nАгов, це Ноствін! Ти зараз чимось $p(зайнятий:зайнята)? Ні? Тоді гайда до нас — робити НАУКУ ПРО ЧАС!\n\nЕтернус розповість тобі більше.\n\nГаразд, дякую, бувай!",
        objectives = "Поговори з Етернус на Нескінченному Базарі біля Даларана.",
    },
    [91438] = {
        title = "Нескінченні дослідження: Героїчні Світові Діяння",
        description = "По всіх Розколотих Островах люди потерпають у біді. Вони шукають надії, та знайти її майже неможливо. Ти можеш стати цією надією.\n\nРозшукай тих, хто в небезпеці на Розколотих Островах, — їм відчайдушно потрібен чемпіон. Стань $p(ним:нею).\n\nСаме з таких вчинків народжуються легенди.",
        objectives = "Виконай 3 світові завдання на героїчному світовому рівні.",
        completion = "Один героїчний вчинок може змінити хід подій. Один шепіт надії може відігнати відчай. Саме це дає легендам їхню силу.",
    },
    [91439] = {
        title = "Нескінченні дослідження: Героїчні Точки Вторгнення",
        description = "Легіон не воює за правилами. Він обманює, маніпулює та підточує сили супротивника на кожному кроці.\n\nПроти Легіону немає лінії фронту. Демони відкривають розломи в слабкому місці й ринуть із них, сіючи смерть і руйнування. Коли вони вторгаються — то лише на власних умовах.\n\nУтім, ця стратегія не є нездоланною. Могутні чемпіони, здатні швидко пересуватися й миттєво реагувати, можуть зупинити такі вторгнення просто в їхньому осередку. Зупини вторгнення Легіону. Покажи всім, що Легіон можна перемогти.",
        objectives = "Заверши точку вторгнення Легіону на героїчному світовому рівні.",
        completion = "Сила, якою володієте ти і твій артефакт, зуміла спинити вторгнення Легіону. Але хто саме спричинився — ти чи артефакт у твоїх руках? Тут мені знадобиться більше інформації.",
    },
    [91440] = {
        title = "Нескінченні дослідження: $p(герой:героїня) Розколотих Островів",
        description = "Героїчні вчинки — питання погляду. Те, що могутньому $p(герою:героїні), як ти, здається дрібницею, для когось іншого може важити понад усе.\n\nРозшукай тих, хто потребує допомоги, і стань їм у пригоді в будь-якій справі, яку вони вважають важливою. Так зростатиме твоя легенда.",
        objectives = "Виконай 5 завдань на героїчному світовому рівні.",
        completion = "Твоє ім'я в людей на думці, його переказують біля вогнищ. Що більшою стає твоя легенда, то могутнішим буде твоє ім'я. Але чи затьмарює сила імені силу артефакту в руках власника? Ось пекуче питання.",
    },
    [91441] = {
        title = "Нескінченні дослідження: Героїчні Великі Точки Вторгнення",
        description = "Щойно Легіон посіє сум'яття і хаос, почнеться його справжній наступ. Відкриються величезні розломи вторгнення, і крізь них незліченними лавами рине Легіон. Захисники, розпорошені між меншими розломами, ніде не матимуть достатньо сил, щоб його спинити.\n\nСаме тоді найбільше потрібні такі чемпіони, як ти.\n\nЗнайди одне з великих вторгнень Легіону і кинь проти нього все, що маєш.\n\nПокажи людям: досить рішучості — і апокаліпсис можна скасувати.",
        objectives = "Заверши велику точку вторгнення Легіону на героїчному світовому рівні.",
        completion = "Точнісінько за моїм прогнозом. Тобі вдалося зупинити масштабне вторгнення Легіону. Це заслуга не тебе окремо й не твого артефакту — перемогу принесло ваше поєднання.",
    },
    [91442] = {
        title = "Екокупол Ал'дані",
        description = "Ми отримали звістку від Ве'нарі, що мешканці пустищ і досі стоять на шляху прогресу на К'ареші. Вони загрожують найперспективнішому екокуполу.\n\nДирективу відновлення К'арешу не можна переривати.\n\nПоклади край цій неефективності.",
        objectives = "Бірґот доручає тобі стати на бій зі Скрижальницею Доль в Екокуполі Ал'дані.",
        progress = "Їхнім зусиллям покладено край?",
        completion = "Це багатонадійний початок наших нових взаємин із К'арешем.\n\nГарна робота, чужинцю.",
    },
    [91443] = {
        title = "Нескінченні дослідження: поглиблені бойові студії, рідкісні істоти",
        description = "Щоб краще зрозуміти силу — і твою власну, і твого артефакту — в цій часовій лінії, нам слід провести кілька бойових студій. Це як суспільствознавство, тільки з травмами від тупих предметів.\n\nЦього разу вивчатимемо рідкісних істот, тож зосередься на боях з рідкісними супротивниками — так ми краще збагнемо твої здібності.\n\nІ пам'ятай: усе це заради вищого блага.",
        objectives = "Убий 4 рідкісних ворогів на героїчному світовому рівні.",
        progress = "Нам потрібно більше бойових даних, щоб завершити дослідження, а час спливає.",
