    [91462] = {
        title = "До Центральної Вежі",
        description = "Слідопитка Астерея — одна з наших ветеринарок. Зазвичай вона доглядає наших рисей, але линька манавирмів надто важлива для здоров'я лісу, щоб лишати її без нагляду.\n\nВирми регулюють потік магії від лей-ліній до решти лісу. Коли лей-лінії було порушено, збився і сезон їхньої линьки. Нині все вже не так кепсько, як колись, але час від часу їм досі потрібна допомога.\n\nЗустрінься з Астереєю біля Центральної Вежі. Вона розповість більше.",
        objectives = "Зустрінься зі слідопиткою Астере біля Центральної вежі.",
        completion = "Добре, що ми прийшли. Манавирмів тут більше, ніж зазвичай.",
    },
    [91463] = {
        title = "До Південної Вежі",
        description = "Хоч Темін у далекоходах і новачок, йому дісталося найважче доручення. Ліс Вічної Пісні здебільшого оговтався, та що далі на південь, то небезпечніше.\n\nУтім, він здібний маг. А його нюх на магію нам конче потрібен.\n\nМи приєднаємося до тебе там, на півдні, щойно впораємося тут. Капітан Доунраннер збиралася забезпечити підтримку. Вона вже мала б бути на місці.",
        objectives = "Зустрінься з арканістом Таеміном біля Південної вежі.",
        completion = "Я-я не хвилююся. Саме в цьому й суть того, щоб бути далекоходом!",
    },
    [91464] = {
        title = "Штурм Штормаріона",
