    [91691] = {
        title = "Зникнення Іридикрона",
        description = "Поки ти $p(мандрував:мандрувала) печерами Заралек, ми з Хронорму зіткнулися з Іридикроном і Нескінченною драконячою зграєю.\n\nМи здолали чемпіона Нескінченної зграї — Хроно-лорда Дейоса, — але, боюся, Іридикрон утік.\n\nДозволь показати тобі, що сталося, — це підкаже нам, що робити далі.",
        objectives = "Переглянь видіння Ноздорму про сутичку з Іридикроном.",
        completion = "Що Іридикрон замислив робити з тим артефактом — поза межами мого видіння.\n\nНаразі мусимо зосередитися на Фіракку та Віранот.",
    },
    [91693] = {
        title = "Тонка гра",
        description = "Видимість — це все. Якщо двір побачить, що я прихильний до певної групи, всі наслідуватимуть мій приклад.\n\nВізьми ці знаки моєї прихильності й роздай їх нашим шановним гостям на власний розсуд. Підозрюю, вони запропонують тобі долучитися до їхніх планів і розділити прибутки, якщо вирішиш пристати на їхній бік.",
        objectives = "Роздай 3 знаки Прихильності Салтеріла угрупованням, яким хочеш допомогти цього тижня.",
        progress = "Прошу, не тримай наших гостей у болісному очікуванні.",
        completion = "Розкішно.\n\nЩиро сподіваюся, ти знайдеш часинку розважитися, поки триває двірський сезон. Я, звісно, ціную похмурих трудяг, націлених на результат, але усмішка тобі не завадила б.",
    },
    [91694] = {
        title = "Арена Шраму Порожнечі: Розбити Тріаду",
        description = "Цей блиск у твоїх очах! Ти вже бачиш у мені ворога й думаєш, як мене вбити, так? Добре.\n\nЯ вислав свої сили до бастіонів Зіадан і Відіуса, щоб скинути їх. Та потім наказ Ксал'атат відкликав мене, і я проґавив усе дійство.\n\nНа щастя, тепер тут є ти. Схоже, ти будеш навіть кращою розвагою, ніж споглядання того, як ці двоє закоханих дурнів відмовляються нарешті покінчити одне з одним.\n\nТож ходи сюди! Я підготую свою арену, і ми влаштуємо справжню виставу! Убий мене, якщо зможеш!",
        objectives = "Увійди на Арену Шраму Порожнечі й здолай Харонуса.",
        completion = "Чим Харонус підсилив своє військо? Бранцями з Азерота? Не дивно. \n\nВін брав би лише найкровожерливіших, яких лишень міг знайти, — якщо це знання допоможе тобі краще спати вночі.\n\nДобра робота. Харонус більше не стоятиме між мною та Відіусом.\n\nВід тебе була користь. Я подбаю, щоб ця поміч обернулася тобі на вигоду.",
    },
    [91695] = {
        title = "По сліду Втілених",
        description = "Іридикрон немов випарувався, тож мусимо зосередити увагу на Фіракку та Віранот.\n\nМерітра й зелена драконяча зграя переслідують його — і натрапили на слід.\n\nУ цій справі їм допомагає Шандріс Фезермун.\n\nВона чекає на тебе у Валдраккені. Шандріс знадобиться твоя допомога в тому, що попереду.",
    },
    [91699] = {
        title = "Завдання відстеження",
    },
    [91700] = {
        title = "Розвіяна темрява",
        description = "Енергії Порожнечі, зосереджені в цій цитаделі, породили безліч спотворених істот.\n\nДика звірина, що мутувала від залишкової енергії, та жахіття родом з-поза аномалій досі живляться тутешніми енергіями й тягнуть їх у себе. Це вкрай неприємно!\n\nЩоб убезпечити мої майбутні справи, ці загрози необхідно нейтралізувати.",
        objectives = "Знищ 2 рідкісних істот у цитаделі Штормаріон і довколишній місцевості.",
        progress = "Загрози вже усунуто?",
        completion = "Мені значно спокійніше від того, що ці загрози усунуто.",
    },
    [91721] = {
        title = "Перевершити власну легенду",
        description = "Хоча артефакти й мають вирішальне значення, ми не повинні нехтувати силою тих, хто ними володіє.\n\nПродовжуй боротьбу проти Легіону. Стань сильним, сильнішим, ніж колись вважав можливим.\n\nТоді ми порівняємо міць твоєї легенди з міццю артефакта.",
        objectives = "Поговори з Етернус на Нескінченному базарі в Даларані, коли перевершиш власну легенду.",
        progress = "Особа, що тримає артефакт, має певну вагу. Але яку саме? Котра легенда більша?\n\nЗ'ясуймо це разом.",
        completion = "Визнаю: я приємно здивована, що помилилася. Твоя сила зросла, і я вже не скажу напевно, хто величніший — ти чи зброя у твоїх руках.",
    },
    [91722] = {
        title = "Створи нову легенду",
        description = "Тепер очевидно, що особа важить щонайменше стільки ж, скільки артефакт, яким вона володіє.\n\nМожливо, саме природа смертності применшує значення особистості крізь призму історії. Артефакт вічний, а ті, хто його тримає, — минущі.\n\nПроте жодне яскраве полум'я не горить вічно.\n\nЯ хочу, щоб ти пала$p(в:ла) так яскраво, як тільки можеш. Підсиль свій артефакт і викарбуй у світі нову легенду, щоб усі її бачили.",
        objectives = "Поговори з Етернус на Нескінченному базарі в Даларані, коли викарбуєш нову легенду.",
        progress = "Артефакт не може підсилити себе сам. Його сила зростає лише тоді, коли власник вершить ним великі діяння.",
        completion = "Це вчить смирення.\n\nВідповідь — у самій природі скінченного існування.\n\nСмертність — це полум'я, що сяє найяскравіше, бо вільне обрати єдину мить слави, замість нести на собі тягар вічності.\n\nОбери свою мить мудро, {NAME}, — і ніщо, навіть час, не зможе тебе спинити.",
    },
    [91726] = {
        title = "Нестримна сила",
        description = "Ця статуя тут наче не на своєму місці. Нічого схожого довкола. Але саме тут Андуїн Лотар поліг у бою з Оґримом Думгаммером у битві біля гори Блекрок.\n\nБагато хто бився на цьому полі. Багато хто не вцілів. Лотар...\n\nДай-но розповім тобі, що сталося тут багато років тому.",
        objectives = "Розпитай Курдрана про події того дня.",
        progress = "То був такий чорний день, {NAME}. Боляче згадувати.",
        completion = "Це трагічна історія, але, можливо, з тих уламків щита Тураліона вдасться створити щось краще.\n\nМожливо, його вдасться відновити — разом із нашим другом.",
    },
    [91727] = {
        title = "Острови об'єднані",
        description = "Я ні на мить не сумнівалася в тобі, {name}.\n\nЯ хотіла осмислити все, чого ти досяг у боротьбі проти Легіону.",
    },
    [91728] = {
        title = "Сурамар звільнено",
        description = "Ти пройшов довгий шлях, {name}. Здається, я ніколи не втомлюся стежити за твоїми звитягами. Навіть здалеку, як мовчазна спостерігачка, я ловлю себе на тому, що цілковито захоплена тим, що ти зробиш далі.\n\nПроте в мене є одне запитання.",
        objectives = "Поговори з Моратарі й дай відповідь на її запитання.",
        completion = "Вельми цікаво.\n\nЯ, звісно ж, занотую це як спостереження.\n\nЗнання того, як ти обираєш шлях дій, ляже в основу подальших гіпотез.",
    },
    [91729] = {
        title = "Армії зібрано",
        description = "Ставки ніколи ще не були такими високими, як зараз, {name}.\n\nМені дуже хотілося б знати, про що ти зараз думаєш.",
        objectives = "Поговори з Моратарі й дай відповідь на її запитання.",
        completion = "Свіжі думки безцінні для наших зусиль тут, {NAME}.\n\nДякую, що ділишся своїми.",
    },
    [91730] = {
        title = "Азерот врятовано",
        description = "{name}.\n\nТи зробив це! Саргераса більше немає, і Азерот врятовано.\n\nЯ можу лише уявляти, що зараз спадає тобі на думку.\n\nЗарадьмо цьому.\n\nДозволь мені записати твої думки і твої слова. Не так, як їх занотував би історик, якого ти ніколи не зустрічав, а як подруга, що не бажала нічого більше, ніж слухати.",
        objectives = "Поговори з Моратарі й дай відповідь на її запитання.",
        completion = "Забагато історій написано про ЩО, ЧОМУ, ЯК і КОЛИ. Але, як не рахувати імен, нам так рідко випадає по-справжньому пізнати ХТО.",
    },
    [91731] = {
