    [91781] = {
        title = "Сезонне нагадування",
        description = "Ми повернулися, щоб розкрити ще більше таємниць у Глибинах!\n\nСпершу введу тебе в курс справи щодо нового.\n\nА потім мені знадобиться твоя допомога з однією моєю дрібною проблемкою...",
        objectives = "Дізнайся про Сезон 3 Глибин із Документів глибинника, а тоді придбай припаси в Рено Джексона й сера Фінлі Мрргглтона.",
        completion = "Гаразд, тепер — до тієї дрібної проблемки, про яку я згадував.",
    },
    [91782] = {
        title = "Конфісковано!",
        description = "Гадаю, ти вже здогада$p(вся:лася), у чому моя проблема, {name}.\n\nМій одяг, мої інструменти, мої дивовижки! Усе, крім чобіт і капелюха, які я більше нікому не віддам.\n\nУсе конфіскував якийсь головоріз із картелю, заявивши, що я заборгував за зберігання в сховищі Порожнечі, уявляєш собі!\n\nЧи не допоможеш старому Бранну виплутатися з цієї халепи? Певен, що варто тобі пояснити, що це все якесь непорозуміння, і вони повернуть усе моє важко зароблене спорядження.\n\nАбо хоча б штани.",
        objectives = "Поверни втрачене спорядження Бранна.",
        progress = "А в Дорноґалі завжди так вітряно?",
        completion = "Аж не віриться, що це від самого початку були хитрощі.\n\nШкода дивовижок, та бодай мої штани до мене повернулися!",
