    [91854] = {
        title = "Тіні глибшають",
        description = "$p(Чемпіоне:Чемпіонко), мені не завадила б твоя допомога. Місцеві тут, у Сільвермуні, виявилися не такими гостинними, як ми сподівалися.\n\nВтім, їх можна зрозуміти: їхнє місто стоїть проти темряви, якої Азерот ще не знав, тож напруга зашкалює.\n\nМоже, скористаєшся своїм особливим поглядом на речі й допоможеш розрядити кілька гарячих точок, що спалахують довкола Сільвермуна?",
        objectives = "Розряди напругу, що наростає в Сільвермуні.",
        progress = "Напруга зашкалює.",
        completion = "Чудова робота. Той Войдшторм викликає страх і жах у кожного, хто його бачить, зокрема й у мене.\n\nАле я обрав це життя — поставати проти зла й плювати йому в обличчя. На жаль, не кожному випала розкіш такого вибору.",
    },
    [91855] = {
        title = "Світодуша: світові завдання К'ареша",
        description = "Тепер я знаю: герої Азерота вирушають усюди, де потрібна допомога. К'ареш — дивний, далекий світ, але наші тамтешні союзники потребують нас.\n\nВирушай туди й допоможи їм. Поглянь, що можеш зробити, аби дати перепочинок ефіріалам і посередникам.",
        objectives = "Виконуй світові завдання в К'ареші.",
        progress = "Наші союзники доблесно опираються в мертвому, розтрощеному світі. Я захоплююся ними.",
        completion = "Ти робиш честь усім героям світу. Дякую.",
    },
    [91863] = {
        title = "Моя перша оселя",
        description = "Ласкаво просимо до сусідства! Можеш вільно роздивитися й оглянути доступні ділянки.\n\nПоговори з управителем, щоб дізнатися більше про те, як стати власником оселі, або якщо хочеш створити власне сусідство.",
        objectives = "Ознайомся з околицею та її мешканцями, а тоді знайди місце, щоб збудувати дім.",
        progress = "Ну як, знайшовся вже дім на все життя?",
        completion = "Вітаємо з придбанням нової оселі! Ми знаємо: тут на тебе чекає щасливе життя — і будемо раді бачити тебе в Сусідстві.",
    },
    [91864] = {
        title = "Підсумок: Розколоті видіння",
        description = "По всьому Азероту багатьом являлися видіння Осяйної Пісні. Спроби зрозуміти те, що здавалося застереженням, зосередилися навколо героїв у Даларані.",
        objectives = "Звернися до Фоліанта Історії, щоб дізнатися про долю Даларана у The War Within.",
        completion = "Острів Каз Алґар був частиною планів Ксал'атат, і саме героям Азерота випало їх зірвати.",
