    [92163] = {
        title = "Лоа мурлоків",
        description = "Чуєш, що за гармидер зчинився коло Атал'Абасі? Тамтешні мурлоки через щось страшенно розбурхалися.\n\nСхоже, мурлоки прикликали собі власного лоа. І той лоа скликає їх на війну.\n\nКажу тобі — бачу на власні очі! Оце сьогодні дивлюся вниз із цієї скелі — а там найбільший мурлок, якого тільки можна уявити!\n\nІ бачило його не лише моє око! Та старійшини кажуть, що в нас є важливіші клопоти. Ба!\n\nХай потім не біжать до мене, коли нас заполонять мурлоки!",
        objectives = "Розвідай про Лоа мурлоків в Атал'Абасі.",
        completion = "Що привело тебе до Лоа мурлоків, $p(мандрівнику:мандрівнице)?\n\n<Король Мрґл-Мрґл стишує голос до шепоту.>\n\nДопоможи мені!",
    },
    [92164] = {
        title = "Мурлоцьке шаленство",
        description = "Ці мурлоки прийшли до мене, Лоа Мурлоків, шукати захисту від лихого загарбника.\n\nГлибокоплавці піднялися з бездонних океанських глибин. Вони вдерлися на цю землю й осквернили її!\n\nДоручаю тобі, $p(чемпіоне:чемпіонко), захистити це королівство й загнати Глибокоплавців назад у море!\n\n<Король Мрґл-Мрґл стишує голос до шепоту.>\n\nПозбудься загарбників — і, може, тутешнім більше не знадобиться мій захист, а я зможу нарешті піти!",
        objectives = "Убий 15 мурлоків-Глибокоплавців в Атал'Абасі.",
        completion = "Готово?\n\n<Король Мрґл-Мрґл прокашлюється, помітивши, що один із його «послідовників» підозріливо на нього зиркає.>\n\nТобто... усе зроблено. Глибокоплавці більше нас не турбуватимуть!",
    },
    [92165] = {
        title = "Риба — це їжа, а не друзі",
        description = "Я почув ваші мрґли, мій народе! Ваші животи ґрґлять від голоду!\n\nЗагарбники відрізали вас від їжі, без якої вам не вижити.\n\nЯ пошлю $p(свого чемпіона:свою чемпіонку) наловити риби, щоб ви знову напхали свої черевця!\n\n<Король Мрґл-Мрґл стишує голос до шепоту.>\n\nАбо можеш просто дати мені риби, якщо маєш?",
        objectives = "Збери 30 Рисориб на Мурлоцькому Рожні або віддай Королю Мрґл-Мрґлу 30 Рисориб.",
        progress = "Моє королівство готове до бенкету! А ти готов$p(ий:а)?",
        completion = "Уздріте міць мого поборника! Наїдайтеся, мій народе, і не знайте більше голоду!",
    },
    [92166] = {
        title = "Костюм зобов'язує",
        description = "Мурлоки мої! Одну з-поміж вас було обрано бути моєю... моєю обраницею!\n\nНа неї чекає велич, і вона моя помічниця... е-е, жриця! Так, жриця лоа!\n\nВаша жриця зникла — можливо, її викрали підступні Глибокоплавці.\n\nЩоб явити свою велику силу, я пошлю $p(свого чемпіона:свою чемпіонку) знайти її й повернути вам.\n\n<Король Мрґл-Мрґл стишує голос до шепоту.>\n\nМоя помічниця зникла, а я тут застряг! Знайди її та скажи, що я на верхівці храму!",
        objectives = "Розшукай жрицю Лоа мурлоків.",
        progress = "{NAME}! Наказую тобі повернути мою жрицю цілою й неушкодженою.",
        completion = "Ти знайшов її! Дякую! Е-е, тобто... Лоа мурлоків дарує тобі свою прихильність, поборнике.",
    },
    [92167] = {
        title = "Лишитися має тільки один",
        description = "Мені доводилося бачити, як Глибокоплавці викрадають тутешніх мурлоків і піднімають трупи тролів, обертаючи їх на поневолену нежить. Але далі вглиб суходолу вони не потикаються — усіх забирають назад у море.\n\nГадаю, ними верховодить могутній мурлок, що безпечно тримається віддалік від берега й ховається з очей, приймаючи данину від своїх посіпак.\n\nМи можемо його виманити. Якщо вдягнеш оцей мурлоцький костюм і принесеш данину, ватажок, може, купиться й покажеться.\n\nЯкщо усунемо ватажка, то, може, врятуємо тутешніх мурлоків!",
        objectives = "Вдягни Запасний Мурлоцький Костюм і піднеси данину біля підводного святилища, щоб виманити й убити ватажка мурлоків-Глибокоплавців.",
        completion = "Ватажком був кобіс? Що таке кобіс?!\n\nТобто... чудова робота, $p(герою:героїне)! Ти добре послужив своєму лоа!\n\nТепер, коли ці мурлоки в безпеці, нам час вирушати!",
    },
    [92177] = {
        title = "Здобич одного героя",
        description = "І знову ми, сін'дорей, бачимо своє місто в облозі. І знову саме найкращим умам серед нас випадає ставати на поміч Сільвермуну.\n\nМука смертних, як виявляється, — могутнє віддзеркалення душі. Якщо її стримати й підкорити, мука діє як різновид магії, якою ми можемо захищати це величне місто.\n\nЯ знайшов чимало сповнених муки цілей по всьому Азероту.\n\nВибери одну з таких цілей, вполюй її і збери її муку в цю кристалічну посудину. Потім повертайся до мене.",
        objectives = "Уполюй ціль Здобичі й поверни кристалічну посудину Асталору Кровоприсяжному.",
        completion = "Поки ти збиратимеш більше муки, я експериментуватиму з потенціалом цієї сили.",
    },
    [92178] = {
        title = "Практична магія",
        description = "Поки тривало твоє полювання на цілі, я розробляв різні способи застосувати муку.\n\nСила, що криється в цих сирих емоціях, незбагненна. Поки що наші напрацювання можуть здаватися скромними, але з часом, я певен, мої відкриття прислужаться цілям Сільвермуна.\n\nДозволь показати. Візьми кристалічну посудину і зустрінь мене внизу.",
        objectives = "Супроводь Асталора до покоїв унизу та наповни предмети силою муки.",
        completion = "Стільки років я присвячував життя цим магічним пошукам.\n\nНаступний розділ буде вартий того, щоб його побачити.",
    },
    [92179] = {
        title = "Темне зцілення",
        description = "Досі мука була неоціненною для зміцнення наших сил. Наша зброя і големи стали ще витривалішими й могутнішими завдяки цій новознайденій силі.\n\nЯ також розробляв способи перетворювати муку на стійкі чари, здатні зміцнювати нас, ельфів.\n\nЗустрінь мене внизу. Покажу тобі, що я знайшов.",
        objectives = "Рушай за Асталором до його нижніх покоїв і допоможи в його відкриттях.",
        completion = "Прикрі побічні ефекти неминучі, коли ми на самому вістрі магічних відкриттів.",
    },
    [92180] = {
        title = "Коштовні самоцвіти",
        description = "{name}...\n\nПоки тебе не було, я вдосконалював нашу роботу.\n\n<Він розкриває долоню, на якій лежить перстень із самоцвітом.>\n\nДрібні прикраси й коштовності, що містять кристалізовану муку.\n\nЯ непомітно подарував їх кільком охочим мешканцям Сільвермуна. Хочу поспостерігати, як діятиме контрольоване зосередження муки з плином часу.\n\nЯ сформував магію так, щоб вона дарувала носієві здоров'я і силу. Розшукай наших добровольців і подивися, як їм ведеться.",
        objectives = "Провідай ельфів, що прийняли прикраси Асталора.",
        progress = "Моя праця змусить світ боятися могутності Сільвермуна.",
        completion = "Агресія — лише вияв сили.\n\nГоловне, щоб хижаками були ми, а не здобиччю.",
    },
    [92181] = {
        title = "Садові жертви",
        description = "{name}... Є справа в місті, якою треба зайнятися.\n\nЛицар-капітан Солара повідомила мені, що в Садах Пам'яті стався інцидент. За її словами, ельфи почали поводитися буйно, через що згущена мука проявилася і взялася тероризувати мешканців.\n\nСкористайся кристалічною посудиною, щоб зібрати згущену муку й заспокоїти ельфів, чий розум не витримав.\n\nТака кількість магії тяжко тиснутиме на тебе, але я впевнений: сили тобі не забракне.",
        objectives = "Врятуй ельфів і поверни згущену муку в Садах Пам'яті.",
        progress = "У всіх моїх справах завжди знаходяться ті, хто прагне стати мені на заваді.",
        completion = "Завжди будуть ті, хто опирається поступу, та хай там якою буде ціна — мої студії муки служать народові Сільвермуна.",
    },
    [92182] = {
        title = "Вівця чи вовк",
        description = "Я чув про твої подвиги в саду. Сільвермун дякує тобі за приборкання хаосу.\n\nА я дякую за таку кількість зібраної муки.\n\nКристалічна посудина, може, і є провідником, але тіло мусить бути міцним, щоб витримати стільки сили... Як і я, ти маєш силу встояти перед потоком муки всередині себе — принаймні ненадовго.\n\nХодімо, дозволь звільнити тебе від цього тягаря.",
        objectives = "Зустрінься з Асталором під його покоями в Сільвермуні.",
        completion = "Мука — це сила, а сила — це хижацтво.\n\nТо ким нам краще бути: вівцею чи вовком?",
    },
    [92184] = {
        title = "Лови картопуголовків",
        objectives = "Картопуголовка спіймано\nВипусти картопух на волю",
    },
    [92185] = {
        title = "Переказ про Володаря Криги",
        description = "Свято Літнього Вогню — пора роздумів про минуле й оповідань біля вогнища.\n\nОдин із таких переказів — це звитяга над Володарем Криги Агуном!\n\nАле це історія, яку ти мусиш побачити на власні очі, щоб переказати її біля вогнища іншим!",
        objectives = "Виклич і здолай Володаря Криги Агуна",
        completion = "Оце, $p(друже:подруго) мій, історія, варта переказування.\n\nЦе переказ, над яким ми, шамани, часто розмірковуємо в цю пору.\n\nПробудження Володаря Криги в пору вогню було порушенням рівноваги природи. Полум'я, що ніколи не мало спалахнути.\n\nЦе застережливий переказ про пристрасть і чвари, який нам усім варто пам'ятати.\n\nДякую тобі за це нагадування.",
    },
    [92195] = {
        title = "Спускайтеся сюди",
        objectives = "Подзвонити в обідній дзвін для яснокрилих метеликів",
    },
    [92319] = {
        title = "Сокирне прохання",
        description = "Ми з Курдраном провели двадцять років в Аутленді, по той бік Темного Порталу, після того як разом із Хадґаром, Тураліоном та Аллерією відкинули Орду.\n\nБували й добрі часи, але кожен день, коли я прокидаюся не у Фортеці Честі, — уже добрий день.\n\nУвесь той час Курдран очолював наших розвідників верхи на своєму грифоні Скай'рі. А вилітаючи з Фортеці Честі, він мчав низько і швидко, ухиляючись від усього, що жбурляли в нього орки. Ото буде сміху, якщо ти знайдеш йому кілька пам'ятних дрібничок!",
        objectives = "Вирушай на півострів Пекельного Вогню в Позамежжі та здобудь 10 іржавих бойових сокир. За бажанням збери також пощерблений спис у Бастіоні Пекельного Вогню.",
        progress = "Що там, {NAME}? Маєш щось для мене?",
        completion = "Нащо ти несеш мені ці старі іржаві сокири?\n\nВони схожі на ті, що їх орки жбурляли в мене колись у Пекельному Вогні...\n\nАж дивно, як далеко орк може метнути сокиру! Мусили бути насторожі — або лишитися без пальців на ногах.\n\nСтривай, це Данат тебе підмовив... ну звісно, що він.\n\nЄдине, що було гірше за довгу розлуку з домом, — це весь той час терпіти Данатове «почуття гумору».\n\nІ не скажу, що летіло повз ціль частіше — сокири чи його жарти!\n\nАле як друг він влучає точно в ціль...",
    },
    [92320] = {
        title = "Досі за ворожими порталами",
        description = "Згадуючи минулі події, ми пригадали про один артефакт, якого так і не здобули під час війни з Палаючим Легіоном.\n\nЦя річ — вмістилище великого зла, і їй не місце в лапах недобитих демонічних сил.\n\nЩоб дістатися до неї, ми маємо вирушити на Розбитий Берег, де Тед має портал, який він пристосував для наших потреб. Приєднаєшся до нашого полювання?",
        objectives = "Вирушай на Розбитий Берег і поверни артефакт великого зла. За бажанням, здобудь також Зіпсутий ліхтар.",
        progress = "Треба було забрати це ще першого разу.",
        completion = "Бачу, вмістилище знайдено. Добре. Ми заберемо його й подбаємо, щоб воно потрапило в належні руки.",
    },
    [92321] = {
        title = "Обморожений підрахунок",
        description = "Ми з Таренаром чули розповіді про штурм Цитаделі Крижаної Корони аж у далеких Чумних землях.\n\nАле він усе переплутав!\n\nЦей ельф вважає, що в Попелястому Вирокові було більше командирів від Чорного Клинка, ніж від Срібного хрестового походу. Він геть здурів. Звісно ж, паладинів було більше!\n\nМоже, понишпориш у Цитаделі Крижаної Корони і знайдеш мені докази? Мені вже набридло з ним сперечатися!",
        objectives = "Знайди 8 Обморожених накидок у Цитаделі Крижаної Корони. За бажанням, здобудь там також Чорний Стяг.",
        progress = "Ну що, знайшлося щось? Мені лиш треба чимось довести Таренарові, що я маю рацію.",
        completion = "Ох, ці накидки геть зносилися. Мабуть, зі старих реліквій і справді важко сказати, хто прийшов більшою силою.\n\nТа ми вже перейшли до суперечки, хто з нас менше спав на Розбитому Березі.\n\nСхоже, тобі вдалося поцупити стяг Чорного Клинка — і вціліти, щоб про це розповісти. Тут поруч, в Аркантіні, є місцина, де його можна повісити.",
    },
    [92322] = {
        title = "Тимеар передбачає доказ загибелі!",
        description = "Вітаю, {name}. Маєш хвилинку?\n\nПід час штурму острова Грому в мене пропала одна важлива річ: кишеньковий годинник, подарунок мого давнього друга, архімага Тимеара. Так, того самого Тимеара... того, що вміє провіщати майбутнє. Він сказав мені, що цей день настане — і що ти мені допоможеш.\n\nГодинник забрала Рада Старійшин, а точніше верховна жриця Мар'лі. Якщо ти вирушиш на острів і повернеш його з Престолу Грому — а ми обоє знаємо, що вирушиш, — я зможу тебе туди переправити.",
        progress = "Чи справдилося передбачення Тимеара? Кишеньковий годинник уже в тебе?\n\nЧи ти просто знову тут, щоб насолодитися моїм блискучим товариством?",
        completion = "Ну звісно, усе вдалося. Тимеар у таких речах має рацію до нестерпності завжди. І він уже повернувся, щоб потикати мене в це носом.\n\nПрийми мою вдячність.\n\nСхоже, тобі трапився й Давній зандаларський сувій. Тимеар уже провидів, що він буде виставлений в Аркантіні. Роззирнися, куди б його прилаштувати.",
    },
    [92323] = {
        title = "Там, де колись горів вогонь",
        description = "Важко повірити, еге ж? Орда й Альянс в одній кімнаті — і ніхто нікого не штрикає ножем.\n\nМені саме згадалися дні у Вогняних Землях, де доводилося збирати люциферни. У них був такий особливий запах... щось середнє між димом і чимось давно мертвим. Стільки часу минуло — я за ним майже сумую.\n\nНазбирай кілька для нас із Зен'таброю, гаразд? Вона заслуговує відчути все сповна.",
        objectives = "Вирушай на гору Хіджал і увійди до Вогняних земель. Усередині здобудь 8 люциферн. За бажання роздобудь також вічнозелену лозу.",
        progress = "Сподіваюся, люциферни вже в тебе — бо як ні, мені засвербить когось штрикнути. Дуже засвербить.",
        completion = "Дивно, як один-єдиний запах може розбудити стільки спогадів. Дякую, що дозволяєш мені цим поділитися.\n\nІ... перепрошую перед усіма іншими. Деяким спогадам судилося не відпускати.\n\nТо у Вогняних землях знайшлася вічнозелена лоза? Якщо це не знак надії, то я вже й не знаю, що ним є.\n\nВстроми її в Аркантіну — може, це буде перша рослина тут, яка не здасться одразу.",
    },
    [92324] = {
        title = "Нерозкрита справа Некоронованих",
        description = "Нам пощастило, що Некороновані вціліли — і їхні архіви разом із ними, завдяки Таоші. Ми саме їх читали...\n\nТобі доводилося чути про Лютопащ, велике місто високорідних? Некороновані пильно стежили за небезпечним принцом Тортельдріном, але після його смерті справу відклали в шухляду.\n\nУ цих нотатках сказано, що в руїнах міста можуть бути речі, варті уваги, — окремо згадано Компендіум Ностро з Винищення Драконів. Ту книгу давно повернули, та мало хто знає, що в ній бракувало кількох розділів.\n\nТож відкриймо справу знову.",
        objectives = "Вирушай до Фераласу та збери 8 загублених сторінок із Компендіуму Ностро. За бажанням, здобудь у Лютопащі також Уламок пілона.",
        progress = "Серед затишку й друзів важко повірити, що Даларана більше немає... \n\n<Келсі дивиться на Таоші з глибокою щирістю.>\n\nНекороновані не гають часу й беруться до своїх справ. Чи знайшлося щось варте уваги?",
        completion = "Оце так несподіванка! Я думала, що все подібне давно розтягли й рознесли світ за очі.\n\nЯ знайду когось, хто попрацює над цими сторінками. Багато писарів були б у захваті від нагоди перекласти прадавню магію.\n\nІ Уламок пілона теж із тобою? Отже, дорога твоя пролягла й через Лютопащ. Яка чудова пам'ятка — майбутні відвідувачі неодмінно розпитуватимуть про неї. \n\nПодумай, куди б поставити його в Аркантіні.",
    },
    [92325] = {
        title = "Спадщина Хеллскріма",
        description = "Моя сестра Кренна колись була завойовницею у військах Орди. Безжальною. Жорстокою. Дехто казав — тиранкою. Але замолоду вона була іншою. Наляканою, та завжди доброю до мене. Теплою до тих, кого підпускала близько. Невже влада її змінила?\n\nА якщо вона зробила з неї тиранку — чи змінила влада й Ґарроша Хеллскріма? Я знаю, ким була Кренна. Я не знаю, ким був Ґаррош.\n\nВирушай до Награнду і з'ясуй це.",
        objectives = "Вирушай до Награнду й дізнайся, ким був Ґаррош замолоду. За бажанням, здобудь також Вивітрений фоліант.",
        progress = "Я хотіла б знати, ким насправді був попередній вождь клану Пісня Війни.",
        completion = "Хеллскрім не мав сили — тож збудував її. Не мав гордості — доки її йому не подарували. І все ж він був таким — вольовим і незламним — від самого початку.\n\nВиходить, влада не змінює людину, а лише виявляє те, ким вона є насправді, глибоко всередині. \n\nМудра ця Праматір Ґея. Колись треба буде її навідати.\n\nА ще з тобою повернувся фоліант, що явно бачив кращі дні. Можу лише уявити, який безмір знань у ньому. \n\nЙого законне місце — тут, в Аркантіні. Знайди для нього, будь ласка, безпечний куточок.",
    },
    [92326] = {
        title = "Аромат дюн",
        description = "Мені бракує запаху пустелі. Це аромат свободи дикого краю. Так хочеться освіжити той спогад.\n\nА як будеш там — прихопи щось із караванів. Цьому місцю не завадить трохи кочового духу.\n\nМоже, ще заскоч до гавані Шаттерстоун і візьми щось для здорованя. Наприклад, якір? Це було б ідеально! Тільки уяви, як він тягатиме його всюди за собою.",
        objectives = "Вирушай до Вол'дуну й принеси Торбинку запашних пісків. За бажанням, роздобудь також Піщаний гобелен зі Сховку вульпер і Важкий якір з гавані Скалкокамінь.",
        progress = "Ну що, мішечок наповнено?",
        completion = "Ах! Просто вдихни це, {NAME}. \n\nДякую за цю подорож в інші часи... і додому.\n\nПовісиш той гобелен, гаразд? Хочу познайомити своїх друзів в Аркантіні з найкращим ткацтвом вульпер.",
    },
    [92327] = {
        title = "Мить поколінь",
        description = "Завжди приємно бачити, що хтось із таким минулим, як у тебе, досі не цурається нас, старих вояків, {name}.\n\nМи з Ейтріґґом нещодавно розмовляли про спадщину. Ти знаєш, що ми обидва билися пліч-о-пліч із валар'ярами проти Легіону? Цікаво, як переплітаються довгі історії.\n\nАле справжня наша спадщина — це наші діти. Може, знайдеш час навідатися до них обох? А заразом переконайся, що вони не дають своїм навичкам заіржавіти.",
        objectives = "Ейтріґґ і Дарій хочуть, щоб ти позмагався з їхніми дітьми.\n\nЗа бажанням здобудь Сушені Троянди з Міста Ґілнеас у Руїнах Ґілнеасу і Шкуру Клефтгуфа з Твердині Чорної Скелі у Палаючих Степах.",
        progress = "Чи вдалося знайти Лорну? А що з Аріоком, сином Ейтріґґа?",
        completion = "З виразу твого обличчя бачу: наші діти показали себе гідно.\n\nПриємно знати: коли на них знову чигатиме небезпека, їхні навички будуть так само гострі.\n\nСхоже, у Спустошених землях тобі трапилася шкура розкопита. \n\nЕйтріґґ знався б на цьому краще за мене, але вона, певно, потрапила сюди крізь Темний Портал із Дренору.\n\nТака річ гідна вітрини, і кращого місця, ніж тут, в Аркантіні, я не придумаю.",
    },
    [92331] = {
        title = "Турбопришвидшення: торгівля має текти",
        description = "<Картелі тиснуть на Трест, вимагаючи тримати ринки відкритими. Ми шукаємо партнерів, здатних усунути певні... перешкоди. Картель Со вповноважено роздати чималі статки в разі твого успіху.\n\nВиконай завдання й забери особливу нагороду в Полагоджувача Со'кіра біля Скарбниці Дорноґала. Сторони лишаються вільними від будь-яких неявних клятв, що можуть виникнути в перебігу торгівлі. Діють стандартні умови Єдиного кодексу посередників.>",
        objectives = "Здолай будь-яких чотирьох босів рейду Манакузня «Омега» на звичайній складності чи вищій або пройди будь-які чотири Міфічні підземелля.",
        completion = "Трест дякує тобі за допомогу, {NAME}. \n\nЯк і обіцяно, ось твоя винагорода. \n\nНа честь успіху нашого нового партнерства ми додаємо невеличку премію за результативність. Повертайся згодом по нову роботу!",
    },
    [92332] = {
        title = "Турбопришвидшення: нескінченне зростання",
        description = "<У Тресту завжди знайдеться робота, якщо ми хочемо забезпечити невпинне зростання нашої торгівлі. Нагадуємо: картель Со вповноважено роздати чималі статки в разі твого успіху.\n\nВиконай завдання й забери особливу нагороду в Полагоджувача Со'кіра біля Скарбниці Дорноґала. Сторони лишаються вільними від будь-яких неявних клятв, що можуть виникнути в перебігу торгівлі. Діють стандартні умови Єдиного кодексу посередників.>",
        objectives = "Здолай будь-яких чотирьох босів рейду Манакузня «Омега» на звичайній складності чи вищій або пройди будь-які чотири Міфічні підземелля.",
        progress = "І знову ти доводиш свою дружбу з картелями! Чудова робота.",
        completion = "Трест дякує тобі за допомогу, {NAME}. \n\nЯк і обіцяно, ось твоя винагорода.",
    },
    [92364] = {
        title = "Сонячна підтримка",
        objectives = "Звірів-загарбників убито\nПідсилити мандрівного листодоглядача",
    },
    [92365] = {
        title = "Створення оборони",
        description = "Розгортання оборони — ключ до безпечної роботи Якоря Сингулярності. Я маю переконатися, що ти повністю розумієш процес.\n\nСпершу забери ядра Штормаріона, які я тримаю на складі. Потім активуй оборонні позиції і, нарешті, обери та розгорни по одному захисному засобу на кожній позиції.\n\nКоли впораєшся, я зможу довірити тобі додаткові Ядра Штормаріона — використовуй їх, як вважаєш за потрібне.",
        objectives = "Виконай кроки та розгорни два захисні засоби.",
        progress = "Ну як, оборону вже розгорнуто?",
        completion = "Чудова робота! Я можу спокійно довірити тобі ці додаткові Ядра Штормаріона — використовуй їх мудро!",
    },
    [92386] = {
        title = "Жменя пилу світла Порожнечі",
        objectives = "Дякуємо за допомогу. Прошу, прийми це на знак подяки.",
        completion = "Дякую за поміч. Прошу, прийми ці дари на знак вдячності.",
    },
    [92387] = {
        title = "Скупчення пилу світла Порожнечі",
        objectives = "Дякуємо за допомогу. Прошу, прийми це на знак подяки.",
        completion = "Дякуємо за допомогу. Прошу, прийми це на знак подяки.",
