    [92388] = {
        title = "Скарбниця пилу світла Порожнечі",
        objectives = "Дякуємо за допомогу. Прошу, прийми це на знак подяки.",
        completion = "Дякую за допомогу. Прошу, прийми це на знак подяки.",
