    [92390] = {
        title = "Ризик заради дослідження",
        description = "На Тіньовій Височині на північному сході коїться щось дивне. Подейкують, що те місце прокляте! Зазвичай там повно вояків Тіньової Варти, але до мене дійшли чутки, що вони покидають це місце.\n\nХочу з'ясувати, чому ж вони насправді йдуть звідти. Підеш зі мною?",
        objectives = "Зустрінься з Ланле Ноксою на Тіньовому Узвишші, щоб оглянути об'єкт Тіньової варти.",
        completion = "<Ланле струшує з себе біль від нападу і силувано всміхається.>\n\nЯка наснага! Оце був добрячий переляк.",
    },
    [92396] = {
        title = "Кличемо підмогу",
        description = "Обереги на рунних каменях слабшають щогодини. Без свіжих кристалів, заряджених арканною магією, Світлоцвіт захоплюватиме дедалі більше землі.\n\nЗнаю, цей тягар не твій — турбот у тебе й без того вдосталь, — але якщо ці припаси буде доставлено, це означатиме для мене більше, ніж можна висловити.\n\nЧи докладеш своєї сили до цієї справи — заради всіх, хто зве це місце домом?",
        objectives = "Доправ заряджені кристали до рунних каменів по всьому Лісі Вічної Пісні.",
        progress = "Що ж робити...",
        completion = "А, то це ти з припасами. Дякую! Обереги тепер стабільні. Але тут є ще одна справа, яка потребує твоєї уваги.",
    },
    [92397] = {
        title = "Оборона Світанкової Зорі",
        description = "Сусідній рунний камінь згас, і Світлоцвіт уже на підході. Сам я не втримаю цих рубежів. Допоможи мені розставити зброю, виставити в ряд зілля й дати лад нашим припасам.\n\nМи зустрінемо це розростання дисципліною й точністю — і пошлемо його назад на шматки.",
        objectives = "Зведи оборону перед навислою загрозою нападу Світлоцвіту.",
        progress = "Ну що, приготування завершено?",
        completion = "Гарна робота. Тепер настала найважча частина.",
    },
    [92398] = {
        title = "А потім прийшли вони",
        description = "Тримайся — наша година настала!\n\nТримай оборону й за будь-яку ціну не дай їм дістатися до рунного каменя. Я зосереджуся на відновленні його сили, а ти маєш захистити мене й усіх тут.\n\nТи готовий?",
        objectives = "Захисти Шпиль Світанкової Зорі.",
        completion = "Рунний камінь знову гуде силою завдяки тобі. Прийми мою вдячність.",
    },
    [92402] = {
        title = "Магічний дотик",
        description = "О, привіт, саме та особа, яку я шукав!\n\nДехто з твоїх сусідів хоче взятися за чаклування. Вони ще не зовсім готові вийти на велику сцену, але я маю задум, як їх розпочати.\n\nСхоже, у твоєму районі є місцина зі слабкою магічною енергією. Можеш узяти цей шукач і знайти для них кілька кристалів?\n\nВони мають бути лише трохи магічними. Не хочеться ж, щоб через них стався нещасний випадок!",
        objectives = "Збери 15 Трохи магічних кристалів у своєму сусідстві.",
        progress = "Ну як, чи випала вже нагода зібрати ті кристали?",
        completion = "О, як добре! Так, це ідеально.\n\nЩиро дякую!",
    },
    [92405] = {
        title = "Зустріч з Аратором",
        description = "Вітаю, $p(чемпіоне:чемпіонко). Маю для тебе термінове послання від Аратора. Він просить тебе приєднатися до нього та його тітки Вереси на острові Озтан, біля узбережжя на заході.",
        objectives = "Розшукай Аратора й Вересу Віндраннер на острові Озтан біля узбережжя острова Дорн.",
        completion = "Мою тітку мучать жахливі видіння, і вони дедалі гіршають.",
    },
    [92407] = {
        title = "Схованка",
        description = "Коли Ксал'атат зникла, вона лишила по собі сила-силенну аномалій — малих кишенькових вимірів, де можуть ховатися вороги. Ромуул кличе їх «схованками».\n\nМайстер зібрав пристрій, який має впоратися із цим завданням.\n\nТреба закрити ці схованки й викурити звідти всіх ворогів, що там причаїлися.",
        objectives = "Скористайся Інвертором аномалії, щоб закрити 5 схованок.",
        progress = "Аномалії вже усунуто?",
        completion = "Чудова робота. Поза сумнівом, ми ще виявимо нові приховані аномалії, але завдяки твоїй допомозі безпосередні загрози усунено.",
    },
    [92408] = {
        title = "Матеріальна вигода",
        description = "Як, в ім'я Азероту, один із цих паладинів-зайд роздобув такий вишуканий взірець таласійського кравецтва — це поза моїм розумінням. Але змарнувати таку нагоду було б недбальством із мого боку.\n\nОднак матеріали, які нам потрібні, значно специфічніші за ті, що я тримаю в крамниці. Манашовк доведеться добути самим. На щастя, це недалеко — одразу за міською брамою.\n\nПринаймні там ми будемо в безпеці від цих дилетантів.",
        objectives = "Зустрінься із Солвіном Брайтстітчем біля манашовкової прядильні в Північному святилищі.",
        completion = "Кращого манашовку не знайти в усьому Лісі Вічної Пісні — що вже казати про світ.",
    },
    [92417] = {
        title = "З поля на стіл",
        description = "Гей, та це ж {name}!\n\nЯ тут трохи в халепі. Готую їжу для всіх, але недооцінив, скільки людей збереться!\n\nМожу нашвидку зварити юшку, і місцеві фермери дозволили мені скористатися їхнім урожаєм, але інші страви зараз на вирішальному етапі, я не можу залишити їх без нагляду!\n\nЧи не міг би ти зібрати трохи стиглих інгредієнтів і принести їх?",
        objectives = "Збери досить інгредієнтів для доброї юшки й повернися до Йолана Гідора в межах сусідства.",
        progress = "Будь ласка, мерщій повертайся з інгредієнтами!",
        completion = "Щиро дякую!\n\nТепер я встигну доготувати решту страв. Кращої помочі годі й уявити!",
    },
    [92418] = {
        title = "Рясність",
    },
    [92420] = {
        title = "Запали небеса: південний Калімдор",
        description = "Щороку, коли племена з півдня та центру Калімдору вирушали до Кам'яного Кігтя, щоб провести там літню пору, обряд сонячних квітів ставав звичною справою.\n\nБагато хто бачив у цьому спосіб віддячити Ан'ше, який невтомно трудився впродовж цієї довгої пори.\n\nОбряд набував особливої ваги наприкінці середини літа, коли південні племена поверталися додому.\n\nЯкщо ти готовий до ще однієї мандрівки, друже, знову здіймися в небеса й слухай уважно...",
        objectives = "Запали небеса, пролітаючи крізь сонцецвіти над Південним Калімдором.",
        completion = "Коли літо добігало кінця, останні підношення сонцецвітів здіймали до небес.\n\nЩойно південні племена поверталися до своїх земель, ці дари правили за смолоскипи, що проводжали Ан'ше додому, у пору його спочинку.\n\nДякуємо, що долучаєшся до цих давно забутих традицій, {NAME}.",
    },
    [92429] = {
        title = "Альтернативне білування",
        description = "Привіт!\n\nЯ працюю над новим способом виготовлення шкіри, але без шкоди для тварин.\n\nМені потрібні лише невеликі зразки: хутро, слина, щось таке. Нічого болісного.\n\nУ мене є ось цей зручний пристрій, який має допомогти!",
        objectives = "Використай Біологічний Пилосос, щоб зібрати зразки з великих тварин у сусідстві.",
        progress = "Дякую за поміч у цій справі. Мені кортить дізнатися, чи вдасться втілити задум.",
        completion = "Погляньмо, що з цього вдасться зробити!",
    },
    [92430] = {
        title = "Прийняти нескінченний хаос",
        description = "{name}, мерщій до Безконечного Базару. Гадаю, ти вже $p(готовий:готова) до експерименту нового кшталту.",
        objectives = "Поговори з Етернус на Нескінченному базарі біля Даларана.",
    },
    [92435] = {
        title = "Запали небеса: Оргріммар",
        description = "Середина літа — час поміркувати про минуле й майбутнє. Поки давні традиції згасають, народжуються нові.\n\nОдна давня традиція, що її дотримувалися колись, полягала в піднесенні сонячних квітів Ан'ше. Коли літні вітри підхоплювали їх угору, квіти палахкотіли яскравою блакиттю та оранжем.\n\nАле забуті традиції не конче лишаються втраченими.\n\n\nЧи здіймешся ти в небеса, щоб запалити сонячні квіти й допомогти відродити цю давню традицію?",
        completion = "Твій вчинок — велика честь для нашого свята.\n\nМинуло багато поколінь відтоді, як небеса вгорі востаннє повнилися сонячними квітами.\n\nТа наші святкування не мусять обмежуватися самими лише небесами Оґриммара. Увесь Калімдор чекає!",
    },
    [92437] = {
        title = "Полювання на декор",
        description = "Чи готовий ти до сьогоднішнього випробування? Я сховав одну річ зі своєї колекції тут, у районі. Щоб знайти її, тобі лишень треба розгадати цю просту загадку:\n\nКамінь, що його клали втрачені руки.\nПерекинутий через гірський потік.\nГлянь туди, де дослухаються лілеї.\n\nХай щастить!",
        completion = "Чудова робота!",
    },
    [92439] = {
        title = "Нескінченні дослідження: бойові студії, Бігун Скверни",
        description = "Щоб краще зрозуміти силу тебе самого і твого артефакту в цій лінії часу, нам треба провести деякі бойові студії. Це наче суспільствознавство, але з тілесними ушкодженнями.\n\nЦе буде дослідження боротьби з Легіоном його ж власною силою, тож зосередься на тому, щоб убивати ворогів демонічною енергією скверни.\n\nІ пам'ятай: це заради спільного блага.",
        objectives = "Убий 100 ворогів, поки твоя активна здібність артефакту — «Спотворений похід».",
        progress = "Пам'ятай: розподіляй сили. Подорож важить не менше, ніж її мета.",
        completion = "Вражає. Я відчуваю твою силу. Це надзвичайно важливий внесок у наші дослідження.",
    },
    [92440] = {
        title = "Нескінченні дослідження: бойові студії, Бігун Бурі",
        description = "Щоб краще зрозуміти силу тебе самого і твого артефакту в цій лінії часу, нам треба провести деякі бойові студії. Це наче суспільствознавство, але з тілесними ушкодженнями.\n\nЦе буде дослідження твого єднання з бурею, тож зосередься на тому, щоб у боротьбі з суперниками буквально повертати течію на свій бік.\n\nІ пам'ятай: це заради спільного блага.",
        objectives = "Убий 100 ворогів, поки твоя активна здібність артефакту — «Гнів бурі».",
