    [92448] = {
        title = "Де танцює пил",
        description = "Упіймавши метелика, ти помічаєш у долонях слабко сяйливий порошок. Він дрібний, сухий і дивно світиться.\nВін не гуде й не ворушиться, але ловить світло так, ніби робить це навмисно.\n\nТи пригадуєш, що хранителька метеликів Вев'там, як відомо, має особливий інтерес до метеликів, які живуть у Гарандарі.\n\nМожливо, цей пил її зацікавить.",
        objectives = "Поговори із доглядачкою нетель Вев'тамом у Лігві.",
        completion = "О-о-ох... цей Пил сяє, наче сон!\n\nЗнайдеш іще — неси мені! А в мене для обміну знайдуться рідкісні й дивовижні скарби!",
    },
    [92450] = {
        title = "Дорослішати нелегко",
        description = "Ой, привіт! Нове обличчя! Я — Ані. А це — Джинкс.\n\nА водоспад тобі вже показували? Усі діти підбивають одне одного стрибнути звідти, але я боюся.\n\nХочеш подивитися?",
        objectives = "Вирушай до водоспаду разом з Ані.",
        completion = "Бачиш? Падати звідси й справді далеко.",
    },
    [92451] = {
        title = "Здається, я зможу",
        description = "Ага, звідси й справді далеко падати.\n\nАле якщо не стрибну, вони кепкуватимуть з мене. Може, якщо ти вболіватимеш за мене, я наважуся?",
        objectives = "Допоможи Ані подолати страх.",
        progress = "Не хочу, щоб з мене більше кепкували. Я-я зможу. Здається...",
        completion = "<Торбинка Ані з коштовними цяцьками лежить порожня на березі багниська й уже занурюється в м'яке багно.>",
    },
    [92452] = {
        title = "Не за планом",
        description = "<Торбинка Ані з цяцьками лежить у м'якому багні на березі річки, але самих цяцьок ніде не видно.\n\nЯкщо пощастить, вдасться пройти її слідом.>",
        objectives = "Простеж слід речей Ані.",
        completion = "Я вже й не знала, чи довго ще тут протримаюся. Каміння майже скінчилося!",
    },
    [92453] = {
        title = "Безстрашна",
        description = "Ті ящірки на дні чигали, та й потягли мене!\n\nТо мої цяцьки знайшлися, і все інше теж? Я навмисне їх розкидала, щоб хтось мене знайшов. Аж не віриться, що спрацювало!\n\nЗдається, вони тебе злякалися й повтікали. Тепер Джинкс зможе спокійно витягти мене звідси.",
        objectives = "Повернися до Ані в селище Амані'Зар.",
        progress = "Стрибнути з отого водоспаду тепер уже не так і страшно.",
        completion = "Гей, {name}! Я стрибнула з водоспаду й убила велику ящірку!\n\nЗнаю, ти $p(допоміг:допомогла).\n\nДжинкс теж допоміг.\n\nДякую!",
    },
    [92455] = {
        title = "Інспектор привидів",
        description = "Щороку на Морок-ніч одне й те саме... духи лізуть із землі, наче забули, що вони мертві.\n\nМи пробували трощити. Пробували палити. Не помогло. Тепер у нас є ці нові знаряддя, що їх змайстрував якийсь гоблін, — вони впораються з тими привидами.\n\nСпоряджайся і вирушай! Перебий їх досить, щоб поки що очистити вулиці, але не лінуйся. Вони завжди якось знаходять шлях назад.",
    },
    [92492] = {
        title = "Вшануєм жертву",
        description = "Ти ба, знову гаш'ура. То як, поможеш мені, чи Зул'джарра тримає тебе на короткому повідці?\n\nНі? Тоді маю для тебе роботу. Одного з моїх вартових, Ідаґо, вбили під час різанини в Осоці Ревантусків. Хочу вшанувати його поховальним обрядом. Ми, Ревантуски, спалюємо тіла своїх мертвих. Але тіла Ідаґо в нас нема.\n\nОтож я вертаюся до Осоки — забрати щось із його речей. Ото й спалимо натомість.\n\nПел'на з моєї почесної варти йти відмовляється — каже, надто небезпечно. Але ж ти мене вбережеш, еге ж?",
        objectives = "Зустрінься з Ліладжу в Осоці Ревантусків.",
        completion = "Пригнися, {NAME}! Не викажи мою схованку.",
    },
    [92493] = {
        title = "Що лишилося від Ідаґо",
        description = "Ідаґо був моїм найдовіренішим вартовим. Скільки себе пам'ятаю — він завжди був мені наставником. Хто ж знав, що його заберуть у мене так скоро... а тоді Клинок Сутінків напав на нас без попередження.\n\nЦе ж Ідаґо витяг мене з селища. Свій спис і свій стяг він покинув там. А ще там лишилася записка — він дав її мені на випадок, якщо він...\n\nПринеси мені ті речі. З ними ми вшануємо його силу і його вірність — і проведемо його дух далі.",
        objectives = "Знайди бойовий спис, стяг і записку Ідаґо в Осоці Ревантусків.",
        progress = "В Осоці Ревантусків аж кишить цими мерзенними магами. Ти робиш справу лоа.",
        completion = "Ідаґо забрали до крипти! Кажуть, їхній верховода Міш'мош приготував для нього щось лихе.",
    },
    [92495] = {
        title = "Ламаєм плани Клинка",
        description = "Ти глянь, що ці культисти зробили з Осокою Ревантусків!\n\nКолись тут панував мир... тут був наш дім. А вони його опоганюють.\n\nЗнаю, ми прийшли по речі Ідаґо, але я геть не проти, якщо ти піднімеш зброю на Клинок Сутінків.\n\nПоклади їх у землю. Покажи їм лють ведмедя.",
        objectives = "Убий в Осоці Ревантусків 7 карателів Клинка Сутінків, 7 тіньомагів і 3 зловісних темнопороддя.",
        progress = "Колись ми підемо походом на цих загарбників і повернемо собі нашу Осоку!",
        completion = "Клянуся пащею Налоракка, їхні лави добряче поріділи завдяки тобі.",
    },
    [92496] = {
        title = "Списи супроти тіні",
        description = "Ідаґо живий, {name}!\n\nЙого поволокли нагору, до крипти, просто в мене на очах — усього обплутаного магічними рунами.\n\nКультисти кажуть, що тягнуть його до якогось Смертеспівця Міш'моша. Певно, цей культист і стоїть за смертю й руїною, що спіткали нашу Осоку.\n\nЗаради честі тих, кого ми втратили, — викури цю гадину з нашого дому!",
        objectives = "Убий Смертеспівця Міш'моша у крипті в Осоці Ревантусків.",
        progress = "Світ буде кращим, коли зло Міш'моша перестане його поганити.",
        completion = "Захист наших земель від Клинка Сутінків — велика шана для нашого племені, і це твоя заслуга.\n\nАле Ідаґо не радий, що я повернулася.",
    },
    [92497] = {
        title = "Магія, та й годі",
        description = "Хто... Хто ти? Хто тебе прислав? Ліладжу?\n\nКультисти вирізали наше селище. Я лишився, щоб усі встигли втекти.\n\nАле культисти схопили мене, а тепер кажуть, що для Ідаґо в них припасено щось особливеньке. Волів би й не дізнаватися, що саме.\n\nМагія, що тримає мене тут, — робота дилетантів. Закляття, що знімуть ці пута, напевно записані в магічних фоліантах, які культисти сюди притягли.\n\nЗнайди ті фоліанти й видери з них кілька сторінок. Тоді складемо докупи потрібні слова — і визволимо мене.",
        objectives = "Видери сторінки з Фоліанта Пут і Фоліанта Болю та прочитай їхні слова, щоб звільнити Ідаґо.",
        progress = "Дякую тобі, {NAME}. За звільнення — і за те, що пильнуєш оцю-от.",
        completion = "Хай там що втнула ця дівчина, я завдячую тобі життям.",
    },
    [92498] = {
        title = "Цукрова виправа",
        description = "Ах, Свято Мерцяної ночі. Найкраща пора для моторошних історій, сяйливих гарбузів і солодких-пресолодких цукерок!\n\nАле цьогоріч я хочу створити щось справді незабутнє. Смачнезну добірку цукерок, натхненну краями з усього Азероту!\n\nДля цього я залучив дещицю допомоги. Одного... ексцентричного кулінарного генія. Можливо, ти його знаєш. Я відіслав його до Друствару на пошуки примарних рецептів, які напевне всіх захоплять.\n\nЗнайди його і принеси трохи тих проклятих цукерок.",
    },
    [92499] = {
        title = "Наймудріші вожді вміють іти слідом",
        description = "Ідаґо нагадав мені, що найперший мій обов'язок — перед племенем. Мені страшенно його бракувало, але не годилося ставити на кін власне життя — чи твоє, — аби його знайти.\n\nПел'на намагалася мені це сказати — та мене було не переконати.\n\nЯ мушу бути взірцем для свого народу. Хай ведмежий лоа спрямовує мій шлях. Часом доводиться жертвувати тим, що нам найдорожче.\n\nНалоракку, даруй мені силу і стійкість.",
        objectives = "Повернися до Ліладжу на Кручі Торнтусків.",
        completion = "Я не зрікаюся свого рішення, але маю перепросити і Пел'ну, і Ідаґо.\n\nЇм є чим поділитися зі мною... а я натомість вестиму їх крізь ці буремні часи.",
    },
    [92503] = {
        title = "Запали небеса: Північні Східні Королівства",
        description = "Чи чув ти переказ про дикомудреців та їхню літню зорю?\n\nНі? Що ж, на тебе чекає справжня насолода!\n\nЦя історія поведе тебе в мандрівку шляхом, яким колись, багато місяців тому, мандрували старійшини Дикомолота.\n\nЗдійнися в небеса й запалюй вогники цвіту, поки я оповідатиму переказ.\n\nНаша мандрівка починається тут, у пагорбах Лох-Модану...",
        objectives = "Запали небеса над північними Східними Королівствами.",
        completion = "«Наче смолоскип, що мчить на північ темним літнім небом».\n\nОце була мандрівка, чи не так? А тепер уяви той самий шлях пішки... щоліта!\n\nЦе доволі популярна історія серед малих дітей Дикомолота.\n\nДехто каже, що саме цей переказ надихнув Кардроса оселити наш народ у Передгір'ях після Грім Батолу.\n\nТепер і ти можеш ділитися цим переказом Дикомолота біля вогнища!",
    },
    [92504] = {
        title = "Запали небеса: Південні Східні Королівства",
        description = "Свято вогню — пора, коли люди сходяться разом і діляться історіями довкола вогню.\n\nОдин із таких переказів оповідає про святкування Літнього Вогню й елементальний хаос, який воно накликало на людей Стормвінда.\n\nНаша історія поведе нас небесами навколишніх країв, у землі, нині пошрамовані полум'ям і попелом.\n\nЗдійнися в небеса й запалюй вогники цвіту, поки я оповідатиму тобі історію.\n\nВона починається в Палаючих Степах...",
        objectives = "Запали небеса, пролітаючи крізь цвіт над південними Східними Королівствами.",
        progress = "Тобі ніколи не було цікаво, чому квіти середини літа палають блакитним і помаранчевим? Дивовижно, правда ж?",
        completion = "Уже багато поколінь вогнища Літнього Вогню запалюють літні небеса по всіх людських землях і поза ними.\n\nТа ще до того, як постало королівство Стормвінд, ми, дворфи, всипали ці пагорби своїми вогняними святами.\n\nКажуть, наше перше спільне Свято Літнього Вогню сталося суто з волі випадкових блукань одного особливо спекотного літа дуже-дуже давно.\n\nАле це, $p(друже мій:подруго моя), уже інший переказ. Хочеш іще політати?",
    },
    [92505] = {
        title = "Правда минулого",
        description = "Дякую, що звільни$p(в:ла) мене з тих ефіріальних кліток в Оверкрофті Етереуму. Порожнеча тут могутня так, як ми лише починаємо розуміти, і ця небезпека відкриває нові можливості.\n\nЯкщо пам'ятаєш, мій намір поєднати силу Порожнечі з міццю Іллідарі не змінився.\n\nСтавка на Адаруса була помилкою — але помилкою необхідною, щоб рухатися далі. А тепер знайшлася й охоча наставниця — Алларі. Я знову прошу твоєї допомоги, {name}. Допоможи мені знайти силу, щоб захистити мій народ.",
        objectives = "Вирушай на Аргус.",
        completion = "Моя нога не ступала на Аргус уже багато років. Мертвий світ, заселений зламаним народом і його спогадами.",
    },
    [92506] = {
        title = "Ціна душі",
        description = "Арґус.\n\nКолись рідний світ ередарів, нині — твердиня Палаючого Легіону. Багато років тому Іллідан скористався Печаткою Арґуса, щоб відкрити сюди шлях. І тут його зустрів один із наару, що приніс лиховісну звістку.\n\nЩоб зрозуміти зв'язок Іллідарі з Порожнечею, ти мусиш побачити те, що побачив Іллідан, коли прибув сюди. Ворожі духи в цій місцині мають дати достатньо сили для наших потреб.\n\nЗдолай їх, щоб вивільнити їхню есенцію, — і завдяки цій жертві ми зазирнемо в минуле.",
        objectives = "Звільняй духів і збирай їхню енергію на Терасі Кіл'джедена.",
        progress = "Енергія цих духів стане провідником, що відкриє нам доступ до минулого.",
        completion = "Так, цього має вистачити. Ми майже готові, {name}.",
    },
    [92507] = {
        title = "Могутніший ворог",
        description = "Ми маємо все необхідне.\n\nПриготуйся побачити протистояння Іллідана з наару, що сталося багато років тому.",
        objectives = "Подивися сцену на платформі.",
        completion = "Єдине, чого мені завжди хотілося, — захищати свій народ. Так само, як мисливці на демонів захищають Азерот.",
    },
    [92508] = {
        title = "Знак жертовності",
        description = "Татуювання, що вкривають нашу плоть, — це більше, ніж просто чорнило. Це обітниця, викарбувана на нашому тілі.\n\nОбітниця, що ми стримуватимемо темряву й пекельні сили власними тілами. Що наша кров — валюта, якою куплено майбутнє Азероту.\n\nЗдивован$p(ий:а)? Ми — не просто втілені лють і непокора, хоча й це також.\n\nДопоможи Леоні зібрати життєву есенцію створінь Порожнечі біля Вузлової Точки Антіус. Ми використаємо її, щоб викарбувати татуювання Леони, скріпивши обітницю, яку вона складає, — захищати свій народ.",
        objectives = "Збери життєву есенцію зі створінь Порожнечі Вузлової Точки Антіус.",
        completion = "Так, ця вловлена енергія Порожнечі чудово згодиться.",
    },
    [92509] = {
        title = "Жорстоке знаряддя",
        description = "Войдшторм — світ, де панують найгрізніші хижаки. Один з них, ультрадон, силою і люттю вивищується над усіма.\n\nАле не май сумніву, {name}: справжні верховні хижаки тут — ми, мисливці на демонів, хай куди б ми не прийшли, бо заради панування ми готові на все. Кращої істоти, з якої можна добути знаряддя для нанесення татуювань Леони, годі й шукати.\n\nВирушай із Леоною до Вузлової Точки Антіус. Здолай стільки ультрадонів, скільки знадобиться, щоб знайти ідеальне знаряддя.",
        objectives = "Здобудь кіготь з ультрадонів біля Вузлової Точки Антіус.",
        progress = "Ти вже знайш$p(ов:ла) кіготь, {name}? Без нього ми не зможемо почати ритуал Леони.",
        completion = "Тепер жодних сумнівів, {name}. Мисливці на демонів — верховні хижаки на цій планеті.",
    },
    [92510] = {
        title = "Темне вливання",
        description = "Ритуал таврування, який ми зараз проведемо, постав з обряду, що його мисливці на демонів проходять на Молоті Скверни. Але з огляду на унікальну природу Леони та експериментальну заміну Скверни енергією Порожнечі ризик тут чималий. Навіть більший, ніж зазвичай.\n\nПід час цього процесу Леона буде вразлива — як і я. Ми знайшли відлюдне місце для ритуалу, але щойно почнемо, нам знадобиться твій захист.",
        objectives = "Проведи ритуал таврування.",
        progress = "Те, що ми робимо, ризиковано, {NAME}. Але в Іллідарі так було завжди.",
        completion = "Гадаю, у нас є обладнання, яке можна пристосувати, щоб допомогти Леоні повернутися до нас.",
    },
    [92511] = {
        title = "Горизонт подій",
        description = "Тебе, мабуть, не здивує, що я неабияк знаюся на стабілізації точок входу порталів.\n\nЯкщо Леона жива — а я вірю, що так, — їй знадобляться маяки, щоб визначити точку виходу. Візьми ці маяки, встанови їх там, де я позначив на твоїй карті, і повертайся сюди.\n\nЯкщо Леона жива, вона зможе скористатися цими маяками, щоб знайти й стабілізувати свій вихід.\n\nЯкщо ж ні--\n\n<Умбрик відганяє цю думку.>\n\nПоки що зосередьмося на нашому завданні.",
        objectives = "Установи маяки, щоб допомогти Леоні знайти дорогу назад.",
        completion = "Той голос. Доманаар. Здається, тепер я його відчуваю. Він прийде по нас, якщо ми не знайдемо його першими.",
    },
    [92512] = {
        title = "Пожирач",
        description = "Я не певна, де опинилася, коли ступила в той портал, {name}. Десь поміж світами, де енергія Порожнечі оточувала й наскрізь пронизувала мене.\n\nБез Умбрика я не повернулася б. Тепер я почуваюся інакше, але не думаю, що все скінчилося, доки ми не зустрінемося віч-на-віч із тим доманааром.\n\nЗустрінеш нас біля Шпиля Порожнечі?",
        objectives = "Допоможи Леоні стати проти Рейвенора біля Шпиля Порожнечі.",
        progress = "Чекаю на Леону з нетерпінням — і з дрібкою тривоги.",
        completion = "Рішучість Леони та її готовність боротися за наш народ гідні захвату.\n\nВона тяжко билася й багато чим пожертвувала, щоб дійти до цієї миті, і ці випробування назавжди залишать слід у її житті. Але рен'дорей стали від цього лише сильнішими.\n\nХто б міг подумати, що такий темний і хижий світ стане каталізатором світлішого майбутнього?",
    },
    [92520] = {
        title = "Слід Темного Колодязя",
        description = "Сонячний Колодязь... ні — Темний Колодязь захоплено.\n\nПородження Порожнечі кишать у місцях, де наші найвидатніші чемпіони Світла трималися до останнього.\n\n$p(Чемпіоне:Чемпіонко), можеш оглянути Кель'Данас? Знайти вцілілих? Якщо позначиш їх цими жетонами, наші маги зможуть телепортувати їх назад. Мусимо врятувати якнайбільше.",
        objectives = "Шукай тих, хто вижив, на острові Кель'Данас.",
        progress = "Це воістину темний день.",
        completion = "Так мало. Але ті, кого ти врятував, — це більше, ніж я сподівалася.",
    },
    [92531] = {
        title = "Святилище лоа медицини",
        description = "У кожного свій шлях до розуміння — навіть в Акуту, хоч він, на жаль, ще й кроку тим шляхом не ступив.\n\nКолись моє святилище було для амані місцем відкриттів і пізнання. Прошу, передай їм звістку: я радо вітатиму їхнє повернення.\n\nПривиди з часом угамуються.",
        objectives = "Повернися до старійшини Дору з вістю про повернення Кулзі.",
        completion = "Оце так історія про привидів!\n\nМені сумно, що я більше не поговорю із Сідж'тою і що Кулзі втратив свого речника лоа, та я радий, що Сідж'та нарешті знайшов спокій.\n\nЯ піду й поговорю з Кулзі. Сподіваюся, там не лишилося образ.",
    },
    [92535] = {
        title = "Горобинові трюфелі",
        description = "Трюфелі знайти доволі просто, якщо маєш гострий нюх. На щастя, я можу його тобі позичити!",
    },
    [92536] = {
        title = "Шматочки зачарованих ягід",
        description = "Моє улюблене! Зачаровані ягоди доволі підступні. Ніколи не вгадаєш, що станеться, коли їх зриваєш!",
    },
    [92537] = {
        title = "Зачакловані стільники",
        description = "А ти любиш ризикувати! Стільники смачнющі, але дістати їх буває справжнім болем — у прямому сенсі! Не сподівайся теплого прийому від мешканців вуликів, з яких діставатимеш стільники.",
    },
    [92546] = {
        title = "Хижаки наступають",
        objectives = "Дерикігтя-нападника вбито",
    },
    [92549] = {
        title = "Порожнеча згори",
        objectives = "Аномалії Порожнечі розвіяно",
    },
    [92554] = {
        title = "Примноження мук",
        description = "?",
