    [92555] = {
        title = "Вшануй полум'я",
        description = "Пора Світанкового Літнього Свята здавна була любою порою для нашого народу.\n\nНавіть у роки під холодною хваткою Примарних земель мешканці Транквілліену прагнули зберегти це прадавнє святкування й принести бодай трохи світла в ці колись холодні землі.\n\nА тепер зігрійся біля вогнища й вшануй полум'я літа!",
        objectives = "Вшануй вогнище Літнього Вогню в Транквілліені.",
        completion = "Вшануй полум'я Транквілліену.",
    },
    [92556] = {
        title = "Вшануй полум'я",
        description = "Радісного Літнього Вогню й Світанкового Літнього Свята тобі, {race}!\n\nСвяткуючи довкола вогнища, важливо спинитися на мить для роздумів.\n\nЧимало сталося тут, у Сільвермуні, останнім часом, і хоч ми не можемо застрягати в темряві минулого, мусимо звернути погляд до Світанку, що сходить.\n\nЗатримайся на мить, поки вшановуєш вогнище, і подумай про його тепло!",
        objectives = "Вшануй вогнище Літнього Вогню в Сільвермуні.",
        completion = "Вшануй полум'я Сільвермуна й поміркуй біля нього.",
    },
    [92557] = {
        title = "Вшануй полум'я",
        description = "Фетна Алай-наздо знову з нами!\n\nХай хода її й темна, та її полум'я яскраво палає в усіх нас!\n\nНехай цей поворот пори року палає яскраво й принесе добру долю тобі та всім, хто святкує Фетна Алай-наздо!",
        objectives = "Вшануй вогнище Літнього Вогню в Зул'Амані.",
        completion = "Вшануй полум'я Зул'Аману на честь Джан'алая!",
    },
    [92558] = {
        title = "Вшануй полум'я",
        description = "Я пам'ятаю святкування Світанкового Літнього Свята у Лісі Вічної Пісні й подумала: «А чому б не запалити власне вогнище тут, на Завивному хребті?»\n\nНа щастя, тутешніх мешканців не довелося довго вмовляти.\n\nЯ сказала їм, що вогнища — це жертовні криниці для посудин езотеричної магії і... що ж, це теж непоганий спосіб описати літні квіти сонцестояння, чи не так?\n\nЗатримаєшся на мить, щоб ушанувати полум'я Порожнечі?",
        objectives = "Вшануй вогнище Літнього Вогню у Войдштормі.",
        completion = "Вшануй порожнечне полум'я Войдшторму.",
    },
    [92559] = {
        title = "Вшануй полум'я",
        description = "Пора Літнього Вогню, може, й незнайома нам, та оповідати історії при сяйві наших кореневих вогнів — звична річ.\n\nЗатримайся на мить для роздумів біля вогнища, $p(друже:подруго), і послухай тих, хто довкола.\n\nПоміркуй про те, що було до тебе, і про те, що ще має розгорнутися.",
        objectives = "Вшануй вогнище Літнього Вогню в Гарандарі.",
        completion = "Вшануй полум'я Гарандара.",
    },
    [92560] = {
        title = "Лу'ашал",
    },
    [92563] = {
        title = "Пробуджено прикрасою",
        description = "<Щойно ти вдягаєш прикрасу, відчуваєш, як вона пульсує силою — та тече крізь тебе просто в твою артефактну зброю.\n\nПрикраса розкрила прихований потенціал артефактної зброї, увімкнувши й посиливши одну з її властивостей.\n\nМоратарі захоче записати ці дані.>",
        objectives = "Поговори з Моратарі на Нескінченному базарі біля Даларана.",
        completion = "Неймовірно! Схоже, магія твоєї нової прикраси здатна пробуджувати недосяжні за інших умов сили твоєї артефактної зброї — ба навіть посилювати їх понад усякі межі!\n\nЦікаво, чи всі коштовності мають такий зв'язок із твоєю артефактною зброєю. Прошу, повідомляй мені про будь-які нові аномалії.",
    },
    [92566] = {
        title = "Армії Темряви",
        objectives = "Самовдоволеного блукача Порожнечі видресирувано",
    },
    [92567] = {
