    [92571] = {
        title = "Армії Темряви",
        objectives = "Самовдоволеного блукача Порожнечі видресирувано",
    },
    [92572] = {
        title = "Послуга з умеблювання",
        description = "Вітаю! Бачу, ти задивляєшся на наші чудові меблі.\n\nМене з братами й сестрами відрядили на пошуки лише найвишуканіших оздоб у краю.\n\nОздоба — це більше, ніж меблі, розумієш. Аби створити справді бездоганну оздобу, треба зважати на безліч різних дрібниць.\n\nХодімо, $p(друже:подруго), вирушимо в цю подорож разом! Починаючи від сьогодні. Сьогодні ми знайдемо ящик. Не просто звичайний ящик, а фантастичний. Чудовий ящик.\n\nКажуть, такі, до речі, можуть продавати десь поблизу...",
        objectives = "Придбай ящик для зберігання в Дорноґалі, Стормвінді чи Оґриммарі й повернися до когось із родини Подо.",
        progress = "Як минає твій день? Фантастично, правда ж?",
        completion = "Ох, той ящик, що ти описуєш, і справді видається пречудовим. Радість від розставляння таких не знатиме меж.\n\nДякую за цю знахідку! За витрачений час дозволь подарувати тобі цю рідкісну річ із нашої колекції.\n\nЦе, безперечно, не проста бочка! Сподіваюся, вона потішить тебе сповна.",
    },
    [92576] = {
        title = "Підкорення Доманаар",
        objectives = "Прапори встановлено\nСили Доманаар розладнано\nОберіг Порожнечі знищено",
    },
    [92577] = {
        title = "Мрійливе натхнення",
        description = "Без освітлення ящик — не більше ніж коробка в темряві.\n\nСьогодні ми вирушимо на пошуки крихітних сонць, що осяюють наші покої.\n\nНе будь-яке світло згодиться. Як ти добре бачиш із моєї люстри, ми вже маємо безліч світильників різної якості.\n\nМи шукаємо неповторну форму, неповторне відчуття.\n\nМайстри Бел'амету на Драконових островах добре знані своїми задумами, натхненними мріями. Мандруй Драконовими островами — і знайдеш їх на дальньому краю рівнин.",
        objectives = "Придбай філігранну місячну лампу в Бел'амет на Драконових островах, а тоді повернися до когось із родини Павдо в Дорноґалі, Штормвінді чи Орґріммарі.",
        progress = "Шафу по-справжньому не пізнаєш, доки не перевіриш завіси.",
        completion = "Твій новий магічний світильник просто дивовижний! Ці акценти витончено вигнутого металу... \n\nСеред металевих куль я мало бачив такої якості. Я поставив би його на письмовий стіл чи приставний столик. Уже бачу цю картину! \n\nІ хоч мені тепер нікуди класти сувої, я мушу віддячити. Візьми мою книжкову полицю — вона добре мені послужила.",
    },
    [92578] = {
        title = "Драконячий декор",
        description = "Пам'ятаєш ту люстру, що я тобі показував? Ти, певно, вважаєш її дуже вишуканою.\n\nАле ж я стою тут без пасних свічників на стіну!\n\nЯке освітлення кімнати я створю без пасних свічників? Воно вийде жахливо незавершеним!\n\nВирушай на Драконові острови й поглянь, чи не знайдеться такого в торговців Валдраккена.",
        objectives = "Придбай Драконяче Бра у Валдраккені на Драконових Островах, а тоді повернися до Подо в Дорноґалі, Стормвінді чи Оґриммарі.",
        completion = "Ага! Отже, бра таки знайшлися. Я зараз же піду й сам куплю кілька, дякую! \n\nЩойно ти відвернешся.",
    },
    [92580] = {
        title = "Знайдеться й стілець",
        description = "Ми не можемо насолоджуватися нашими задумами декору, не маючи місця, звідки ними милуватися.\n\nОтже, стілець.\n\nЯк краще насолоджуватися декором, ніж сидячи на самому декорі?\n\nНе уявляю нічого доречнішого.\n\nЗнайди мені стілець, що пасуватиме до цього витка. Майстри механізмів Мехагона знаються на цьому стилі.",
        objectives = "Придбай Стілець із Болтів в Іржоболті в Мехагоні, а тоді повернися до Подо в Дорноґалі, Стормвінді чи Оґриммарі.",
        completion = "Ах, знайдений тобою стілець — саме те, що треба.\n\nА це тобі — котушка. \n\nСподіваюся, тебе не вдарить струмом! Часом заради мистецтва доводиться жертвувати.",
    },
    [92581] = {
        title = "Останнє світло",
        description = "Я сидів на стільці й дивився на світильники, та все одно не задоволений.\n\nДекор досі не передає тієї драматичної ноти, якої ми прагнемо.\n\nМушу потурбувати тебе ще одним джерелом світлових променів.\n\nВирушай у Сурамар і поговори з тамтешніми майстрами. Вони — справжні віртуози мистецтва м'якого освітлення.",
        objectives = "Придбай Ліхтар Нічнороджених у Сурамарі на Розколотих Островах, тоді повернися до Подо в Дорноґалі, Стормвінді чи Оґриммарі.",
        completion = "Тобі знову вдалося знайти замовлений декор! \n\nУ тебе справжній хист до цього. Сподіваюся, твоя пригода у світі декору триватиме, адже меж у ньому немає — окрім твоєї власної уяви. \n\nМожеш забрати стіл, що стоїть переді мною, — мені він більше не потрібен. Можливо, ми ще зустрінемось!\n\nА до того часу — прощавай!",
    },
    [92582] = {
        title = "Нанести на коріння",
        objectives = "Коріння доглянуто",
    },
    [92583] = {
        title = "Фунгіцид",
        objectives = "Пробігти через Прохід\nБитися в Ямі Злоби",
