    [92600] = {
        title = "Тріснутий ключ",
        description = "Уривчасті образи героїчних діянь спалахують у твоїй свідомості, щойно ти торкаєшся каменя, але згасають так само швидко, як і з'являються.\n\nМожливо, виконання достатньо вражаючого подвигу знову стабілізує магію каменя?",
        objectives = "Пройди будь-яке підземелля на складності Міфічний 2 або вищій.",
        completion = "Оповіді про твої власні звершення вплітаються в хор відлунь, що линуть із нині полагодженого каменя.",
    },
    [92603] = {
        title = "О самотня зоре",
        description = "<Ельф Порожнечі корчиться в неспокійному сні — його мучить тінь, що витає поруч.\n\nМабуть, варто спробувати його розбудити.>",
        objectives = "Дізнайся більше про тінь, що мучить Оріна.",
        completion = "Дякую, що склав мені товариство. Мені, власне, не було кого більше попросити.\n\nІнші рен'дорей... Порожнеча багато що змінює, але в Телоґрусі я почуваюся таким же чужим, як і в Сільвермуні.",
    },
    [92604] = {
        title = "Промов кров'ю",
        description = "Після мого невдалого творіння я шукав мудрості в Порожнечі, і вона розповіла мені про це місце.\n\nБув голос — дивний, але знайомий. Він пообіцяв знаряддя для формування Порожнечі й тіні — щось, що звільнить мене від моєї невдачі. Але Порожнеча нічого не дає задарма. Ми мусимо наказувати їй, а насильство — рідна мова цього краю.\n\nУбий тутешніх звірів і принеси мені їхній іхор. Ним ми напишемо наші вимоги.",
        objectives = "Збери 50 Тягучого Ихору зі створінь у Іклопаді.",
        progress = "Він у тебе? Тінь не змовкне. Їй не судилося існувати отак.",
        completion = "Сподіваюся, це не завдало забагато клопоту. Така робота завжди була мені не до снаги. Я ніколи не міг опанувати буйніші мистецтва Порожнечі.",
    },
    [92605] = {
        title = "Чесно, як кістка",
        description = "Якщо іхор стане носієм нашого послання, то кістка буде його барвником. Це місце падлоїдів: кістки, вкрадені з усього цього краю, — старі, нові, і всі вони несуть відлуння насильства, що обірвало їхні життя.\n\nПринеси мені кістяні скалки, і я зітру їх на порошок для нашого чорнила.\n\nПрошу, поквапся. Ця тінь — щось неправильне, і я мушу це виправити.",
        objectives = "Збери 8 Кісткових скалок в Іклопаді.",
        progress = "Ці стерв'ятники, певно, нанесли кісток з усього Войдшторму.",
        completion = "Чудово. Дай мені хвильку розтерти це на порох, і невдовзі ми матимемо потрібний пігмент.",
    },
    [92606] = {
        title = "Прийми свій дар",
        description = "Це місце — ця рана — саме те, що голос із Порожнечі обіцяв мені знайти. Усередині щось чекає... щось, що покладе край цьому зламаному творінню.\n\n<Орін кривиться і зиркає на тінь.>\n\nТи не чуєш? Воно виє. Часом — від люті. А часом його виття таке самотнє, що в мене серце крається.\n\nНе зважай на нього. Гадаю, з правильними рунами, написаними іхором і кісткою, ми зможемо розчахнути цей розлом ширше. Тоді зможеш забрати те, що лежить усередині.",
        objectives = "Допоможи Оріну відкрити розлом і дізнатися, що ховається всередині.",
        progress = "Голос казав правду. Тут щось чекало.",
        completion = "Дивовижно. Це різьбило створене не для каменю чи металу, а для самої Порожнечі. Воно може звільнити мене від цієї тіні.",
    },
    [92607] = {
        title = "І вирізьби нові форми",
        description = "Ось що пообіцяв мені голос із Порожнечі: засіб позбутися цієї тіні.\n\nТобі доведеться взяти його в руки. Не хвилюйся — мені воно не зашкодить. Воно лише відділить мене від тіні. А та потім має просто розтанути — всього-на-всього тінь, що зірвалася з прив'язі.\n\nНу ж бо. Я готовий.",
        objectives = "Відокрем Оріна від його тіні.",
        completion = "Тінь не намагалася мучити мене — вона мучилася сама. Я створив її в глибинах своєї самотності, і вона відбивала це: прив'язана до мене, нездатна існувати окремо, силкуючись дати втіху, якої не могла, застрягши моєю тінню.\n\nЯ шукав ради зі своєю самотністю назовні. Знайшовши Порожнечу, ставши рен'дорей, подавшись сюди за іншими... Я думав, що варто лише знайти правильне місце, і я не почуватимуся так.\n\nАле я помилявся. Воно завжди було всередині мене. Я не міг вигнати його, лише прийняти.",
    },
    [92608] = {
        title = "Пейзажна зйомка",
        description = "Я просто чудово проводжу час у твоєму милому селищі, воно таке затишне!\n\nМене сповнює натхнення. Я хотіла б намалювати пейзаж на згадку про цю нагоду. Та ти знаєш цю місцевість краще за мене.\n\nЧи не могла б ти зробити для мене кілька знімків краєвидів, які я використаю для натхнення? Можеш скористатися моєю камерою. Вона, певна річ, найвищого класу.\n\nПевна, що ідеальні місця самі впадуть тобі в око.",
        objectives = "Зроби достатньо знімків свого сусідства, щоб надихнути Корлен Гордралін.",
        progress = "Це місце — справжня втіха, таке неквапливе й по-сільському затишне.",
        completion = "Ох, ці знімки просто вишукані!",
    },
    [92616] = {
        title = "Хоробрість Росте, як Гриб",
        description = "Бракко шкодувати, що Бракко підвести {name} і TeamName.\n\nБракко дуже боятися споролетягаів. Вони могти підкрастися до Бракко над шапкою, де не видно. Могти сильно поранити шапку!\n\nДуже перепрошувати, {name}. Бракко не думати, що Бракко може бути танком для команди.\n\nХіба що... {name} повправлятися зі споролетягими разом із Бракко?",
        objectives = "Допоможи Бракко здолати страх перед споролетягами.",
        completion = "Споролетяги дуже страшні. Досі могти підкрастися і напасти. Поранити шапку Бракко.\n\nАле {NAME} змусити Бракко тренуватися. Тепер могти битися зі споролетягами, навіть коли страшно.\n\nСтрашно — не означати, що Бракко мусити тікати.\n\nТепер готовий битися за Грибне Братство.\n\nНавіть якщо битися зі споролетягами, Бракко не тікати.",
    },
    [92617] = {
        title = "Стійкість Росте, як Гриб",
        description = "Спершу тікати Туктук, потім тікати Бракко. Не можна бути єдиним, хто ще битися.\n\nЗіні на самоті — це програш. Битися самотою надто важко, сили не вистачити.\n\nНе хотіти програти. Не можна підвести PH_Teamname!\n\nБув вибір: програти або втекти.\n\nАле втекти — це теж програти. Зіні дуже перепрошувати {name}!\n\nМожна потренуватися — битися з великими і страшними ворогами разом?",
        objectives = "Стань разом із Зіні проти 4 страшних ворогів.",
        progress = "Зіні пробувати зцілити {NAME}.",
        completion = "{NAME} не померти! Зіні зцілити {NAME}.\n\nБула б провина Зіні, якби {NAME} померти, але {NAME} вижити. Бо Зіні зцілювати, хоч вороги і страшні.\n\nТакі страшні.\n\nУра! {NAME} — прошу. За допомогу.\n\nІ {NAME} — дякувати. За те, що показати: разом могти.\n\nТепер могти бути Грибним Братством. Точно виграти Яму Злоби.",
    },
    [92618] = {
        title = "Упевненість Росте, як Гриб",
        description = "Отрута Туктука недостатньо добра. Туктук мусити тікати, поки ми не програти.\n\nШкода, якщо ти програти! Туктук не програти. Туктук покинути. Покинути — це безпечно від програшу.\n\nЯма Злоби дуже, ррр... така напружена. Туктук не витримувати. Туктук лишатися зовні, де безпечно.\n\nТуктук знайти місце відпочивати. Подалі від Ями Злоби.\n\nТуктук не може програти, якщо бути далеко.",
        objectives = "Допоможи Туктуку зустрітися віч-на-віч із 3 важкими почуттями.",
        completion = "Туктук могти програти! Бути побитим.\n\nДуже страшно. Але {NAME} все одно бути другом. Бракко все одно бути другом. Зіні все одно бути другом. \n\nВсе одно бути Грибним Водоспадом. Зустрітися знову біля Ями Злоби.\n\nГаразд, Туктук старатися щосили.\n\nЗнову стріляти отрутою.\n\nТак багато отрути.\n\nУсюди.",
    },
    [92630] = {
        title = "Гонитва триває",
        description = "Я приніс звістку від магістра Умбрика!\n\nЙого учениця Леона одержима бажанням опанувати шляхи іллідарі.\n\nВона, схоже, знайшла іншу мисливицю на демонів, ладну її навчати, якщо вона доведе свою гідність. Та після того, що сталося минулого разу, коли вона шукала собі такого наставника, Умбрик непокоїться за її безпеку.\n\nУмбрик просить тебе приєднатися до Леони на цьому випробуванні. Простеж, щоб вона не вплуталася в щось, до чого не готова.",
        objectives = "Знайди Леону й Алларі на К'ареші.",
        completion = "Алларі хоче випробувати мою рішучість. Ніщо не відверне мене від цієї гонитви.",
    },
    [92631] = {
        title = "Огидне горнило",
        description = "Леона має довести, що володіє своєю зброєю — і власною ворожнечею, — здобувши неушкоджені частини вбитих нею ворогів.\n\nЯ спостерігатиму звідси.\n\nТи, {name}, підеш із нею.",
        objectives = "Здобудь 24 неушкоджені частини з аберацій на Грозових полях.",
        progress = "Мисливець на демонів орудує своїм гнівом, але ніколи не дає йому заволодіти собою.",
        completion = "Ці частини бездоганні. Молодці, ви обоє.",
    },
    [92632] = {
        title = "Випробування гнівом",
        description = "Прорубатися крізь юрми слабших ворогів — проста справа для будь-якого мисливця на демонів. Та коли ми стаємо перед однією великою загрозою, ось тоді й випробовується наша вправність.\n\nСаме таким буде випробування Леони. Ти будеш її помічником.\n\nПогляньмо, як вона здолає особливо небезпечного супротивника.",
        objectives = "Убий Враксика, Вимірного Мандрівника.",
        completion = "Той самий вогонь, який я бачу в Леоні, колись привів мене туди, де я нині.\n\nВона добре б'ється. Та важливіше інше: вона показала мені, який потенціал мають ельфи Порожнечі.",
    },
    [92634] = {
        title = "Подорож середини літа до Лох Модану",
        description = "Хай середина літа священна для тауренів, та не лише ми вшановуємо духів вогню в літні місяці.\n\nДикий Молот, наприклад, упродовж років ділився з нами власними звичаями. Схоже, ця пора року здавна важлива для дворфів та мешканців Східних Королівств.\n\nВирушай за море, на їхні святкові землі в Лох Модані, та провідай Дикий Молот.\n\nМожливо, і вони розкажуть тобі якусь оповідь...",
        completion = "То тебе прислав Старійшина Сонцеріг? Що ж, ласкаво просимо, {race}, на наші святкування середини літа!\n\nХочеш почути про витоки свята Вогнепаду й про те, як дворфи святкували середину літа?",
    },
    [92635] = {
        title = "Літня мандрівка до Степу",
        description = "Хоч ми й маємо власні традиції в цю пору, та не лише ми шануємо духів вогню в літні місяці.\n\nЯкщо хочеш почути, як постали тауренські традиції, вирушай до Калімдору, щоб продовжити свою мандрівку.",
        objectives = "Вирушай до місця тауренських святкувань у Степу.",
        completion = "Тебе прислав Едг Вогнебород? Що ж, тоді ласкаво просимо, людино, на наші святкування Літнього Вогню!\n\nХочеш почути наш переказ?",
