    [92895] = {
        title = "Запрошення Гаґар",
        description = "Гаґар має звістку, яку, на її переконання, мусять почути всі ельфи й тролі Азероту. Вона розіслала заклик до проводирів ельфійських і трольських племен прибути до Гарандару.\n\nЯ прийшла сюди, щоб попросити ельфів крові долучитися до нас, але й ти маєш бути там. Ти $p(пройшов:пройшла) із нами через стільки всього.\n\nКореневі шляхи із Сільвермуну будуть найшвидшою дорогою.",
        objectives = "Прийди на зустріч Гаґар у Лігві в Гарандарі.",
        completion = "Тепер уже недовго.",
    },
    [92897] = {
        title = "Приготування завершено",
        description = "{name},\n\nя несу важливу звістку від Гаґар. Тебе запрошено на особливу зустріч у Гарандарі. Прошу, знайди мене в Сільвермуні, щоб ми це обговорили.\n\nОрвейна",
        objectives = "Поговори з Орвейною в Сільвермуні.",
        completion = "Приготування завершено.",
    },
    [92899] = {
        title = "Урок історії",
        description = "Гаґар попросила, щоб ми запросили на цю зустріч усіх знаних нам трольських та ельфійських проводирів.\n\nПереконати їх прийти було нелегко. Між цими групами є... давні образи. Гаґар сподівається подолати цю ворожнечу.\n\nПоки ми чекаємо на решту, можеш поспілкуватися з іншими посланцями. Очікування робить їх неспокійними, тож намагайся не розпалювати напруги.",
        objectives = "Поговори з іншими делегатами, тоді повернися до Орвейни.",
        completion = "Радий бачити тебе знову!\n\n<Кіндуру роззирається Лігвом, тоді зітхає.>\n\nЧасом не знаєш, куди це потупотів Зул'джан?",
    },
    [92900] = {
        title = "Послуга для Кіндуру",
        description = "Зул'джарра не змогла покинути Зул'Аман, бо амані ще оговтуються. Замість себе вона прислала Зул'джана.\n\nВона сподівалася, що ця довіра й відповідальність виведуть його з її тіні. Скористайся його талантами. Але ця звістка...\n\nЯ старий троль. Мені важко тримати Зул'джана в шорах, але тебе він, може, послухає.\n\nПриєднаєшся до нас? Ми із Зул'джаррою були б вдячні, якби Зул'джан не вскочив у халепу.",
        objectives = "Зустрінься із Зул'джаном, Кіндуру та Орвейною в Гарандарі.",
        completion = "Мій терпець уривається.",
    },
    [92901] = {
        title = "Переписування історії",
        description = "Не всі видіння в цьому місці були нам зрозумілі. Деякі з них були... дивні.\n\nОдне особливо стосувалося незнайомого нам народу: народу, який, як ми дізналися, є тролями амані.\n\nМагія, якою створено цю картину, якою вирвано спогади з минулого, пов'язана з гаранірами й тими, хто близький до нас. Якби зв'язку не було, зур'ашари — ті, хто творить картини — не змогли б пригадати історію тролів.\n\nЯ можу показати її тобі й Зул'джанові, і ви самі зможете судити.",
        objectives = "Переживи видіння амані в Лігві Відлунь.",
        completion = "Історія амані, змальована на стінах наших предків. Ця магія не діє без зв'язку між нашими народами.",
    },
    [92902] = {
        title = "Врятуй амані від жертвоприношень жерців",
    },
    [92903] = {
        title = "Бийся пліч-о-пліч з Ула'тек",
        description = "Третє видіння показує Ула'тек й амані в битві проти ворогів амані. Ти допомагаєш їм у бою. Зул'джан у цій сцені — лише голос, що промовляє.",
    },
    [92904] = {
        title = "Повернення до Зул'Амана",
        description = "Я чув цю історію ще змалечку! Амані поступалися числом, та все одно билися далі! Вони здобули перемогу самою лиш силою волі!\n\nОрвейна каже, що видіння не можуть брехати. Дядько гадає, що подробиці битви могли загубитися. Це поставило б під сумнів усе, що означає бути амані.\n\n<Зул'джан супиться.>\n\nЯ мушу знайти правду про це. Дядько каже, що коли хтось і знає, то це лоа. Лоа досі нічого про це не казали, та десь починати треба.\n\nЧас вертатися додому.",
        objectives = "Повернись до Зул'Аману із Зул'джаном і Речником лоа Кіндуру.",
        completion = "І чому в мого дядька такий безлад?",
    },
    [92905] = {
        title = "Поможи дядькові з лоа",
        description = "Ти йдеш шукати дядька Кіндуру. Дядько нічого не знає про Ула'тек, та може запитати лоа-орла. Ти допомагаєш йому провести ритуал, щоб запитати лоа. Він каже, що лоа теж не знають.",
    },
    [92906] = {
        title = "Breadcrumb to Eagle Rise",
    },
    [92907] = {
        title = "Відповіді амані",
        description = "Мій дядько вже почав спілкуватися з лоа, аби розвідати про цього Ула'тек. А ми тим часом перериємо його скрині — побачимо, що знайдемо.\n\n<Зул'джан показує на скрині, розкидані по терасі.>\n\nУ мого дядька найбільша збірка переказів серед амані. Хлопчиськом я їх часто перечитував.\n\nШукай усе про Ула'тек, змій чи ранню історію амані. Я візьму ці, а ти обшукай решту.",
        objectives = "Допоможи Зул'джанові обшукати скрині в пошуках відомостей про Ула'тек.",
        progress = "Що ж відомо цій масці?",
        completion = "Ти чу$p(в:ла), що воно сказало? Зброя!",
    },
    [92916] = {
        title = "Заклик про допомогу",
        description = "{NAME}, я знову закликаю тебе на поміч амані — ти ж бо для них гаш'ура. Над ними нависла нова страшна загроза.\n\nМалакрасс повернувся.\n\nКручі Візербарків атакує жахливий ворог, якого я ще ніколи не бачила. А після нашої сутички з Клинком Сутінків гіршого часу годі й уявити.\n\nЗул'джан покинув нас і... ми гадаємо, що принаймні частково винен саме він.\n\nЗ обома ми розберемося свого часу. А зараз допоможи нам, поки ворог нас не здолав.",
        objectives = "Зустрінься з леді Ліадрін на Кручах Візербарків.",
        completion = "Слава Світлу, що ти тут.\n\nУ нас є робота.",
    },
    [92917] = {
        title = "Порятунок обвитих",
        description = "<Ліадрін витирає піт з чола і звертається до тебе, не обертаючись. Ти помічаєш дрібні порізи й садна, що їх вона так і не зцілила.>\n\nМи відступили від брами селища. Поранених і отруєних було так багато... Орвейна, Так'леджо і я найбільше прислужимося амані тут.\n\nА от тобі варто бути там — допомагати Зул'джаррі.\n\nЗмії Малакрасса хапають Візербарків, обвиваються довкола них і наповнюють їх отрутою.\n\nЗвільни їх — і неодмінно розшукай Дак'зора. Він був на передовій і впав першим.",
        objectives = "Врятуй 8 селян амані та Дак'зора на Кручах Візербарків.",
        completion = "Вони забрали Дак'зора на схід?\n\n<Зул'джарра гарчить.>\n\nДо протоки. До острова. Що їм від нього там треба?\n\nДух я чи ні, я знайду спосіб дістатися горлянки того Володаря вроків...",
    },
    [92919] = {
        title = "І гавкає, і кусає",
        description = "Які рани мені довелося бачити... яка лютість.\n\nЦі змії не лише повзають по землі та обвиваються довкола тіл наших воїнів — вони ще й глибоко ранять отруєними клинками і вражають кігтями, кидаючись із небес.\n\nЗул'джарра з її загоном самотужки цього бою не виграє, але мої руки потрібні тут.\n\nДопоможи Зул'джаррі — розправся з ними.",
        objectives = "Здолай рештки сил Малакрасса довкола Круч Візербарків.",
        completion = "Битва повертається на нашу користь завдяки тобі, але бій ще не скінчено.\n\nТепер ми маємо трохи простору, але треба вдарити по джерелу — Малакрассу — перш ніж на нас полізе ще більше змій.",
    },
    [92920] = {
        title = "Униз із небес",
        description = "Мені треба час, щоб покликати Акіл'зона й відкрити шлях. Ось тут і знадобишся ти.\n\nЗахищай мене, гаш'ура.\n\nЯ ввіряю тобі своє життя. Та й стрибати нам не первина, га?",
        objectives = "Захисти Зул'джарру, поки вона закликає Акіл'зона на Небесному Мості.",
        completion = "Лоа не можуть піти з нами? Тоді доведеться покладатися на власну силу.",
    },
    [92921] = {
        title = "До Небесного Мосту",
        description = "<Обличчя Зул'джарри темніє від люті, коли вона дивиться в бік Небесного Мосту.>\n\nЗул'джане... ти дозволив цій змії Малакрассу затруїти твої розум і серце. Заради чого? Влади?\n\nСвітлодерево — то було одне. Але це?\n\nНе знаю, що Малакрасс замислив для полонених, але ми маємо перенести бій до нього — подалі від нашого народу.\n\nІди слідом чудовиськ назад до Небесного Мосту. Я пораджуся з лоа й зустріну тебе там.\n\nЗ їхньою поміччю ми це спинимо.",
        objectives = "Зустрінься із Зул'джаррою біля Небесного Мосту.",
        completion = "Я проб'юся до Малакрасса, навіть якщо доведеться здерти луску з тисячі цих чудовиськ.",
    },
    [92924] = {
        title = "Що криється за туманом",
        description = "З лоа ми могутні. Без лоа ми все одно амані. Ми повернемо наших родичів.\n\nЛіадрін скоро приєднається до нас із підкріпленням, а мої воїни прагнуть помсти.\n\nЗволікати не можна. Заради мого народу — і заради Зул'джана.",
        objectives = "Зустрінься із Зул'джаррою на Пристані Токки на Звивистому Острові.",
        completion = "Це руїни міста амані.\n\nПевно, це все, що лишилося від тутешнього поселення, перш ніж міст упав, а острів став здобиччю прокляття.\n\nАле якщо сюди не можуть прийти навіть лоа, як вижили ці тортоллани? Чому вони тут?",
    },
    [92925] = {
        title = "Проблиск історії",
        description = "Руїни на цьому острові прадавні — їх давним-давно звели амані. Якщо ми з'ясуємо, як вони тут опинилися, то, можливо, дізнаємося правду про Ула'тек.\n\nТоді ми зможемо показати Зул'джану, за чим він насправді женеться.\n\nЯ здогадуюся, де шукати ту крипту. Ходімо разом, {NAME}.",
        objectives = "Іди за Орвейною на головний острів.",
        completion = "Богиня відповідає нам! У цьому видінні має бути якийсь урок.\n\nПовчімося в минулого.",
    },
    [92926] = {
        title = "Здобич: Ініціатива Асталора",
        description = "А, {name}. Радий бачити тебе тут, у нашому місті, навіть попри ці важкі часи.\n\nНас знову тіснять з усіх боків непевні друзі та небезпечні вороги, але я не беззбройний. Неподалік я прихистив одного... гостя. Можливо, саме він тримає ключ до виживання нашого міста.\n\nЗустрінь мене біля гавані, якщо маєш силу зробити те, що належить.",
        objectives = "Зустрінься з Асталором Кровоприсяжним поблизу гавані в Сільвермуні.",
        completion = "Бачу, твоя цікавість прокинулася.\n\nЧудово.",
    },
    [92927] = {
        title = "Відлуння кроків",
        description = "Часом видіння богині нелегко зрозуміти одразу, але згодом вона відкриває свої наміри.\n\nЯ триматиму Дітей Ула'тек подалі від твого шляху, поки ти йтимеш за її спогадами.\n\nВір: вона відкриє те, що нам належить пізнати.\n\nЗустрінь мене попереду, коли побачиш її спогади про амані.",
        objectives = "Знайди три Спогади Світодуші перед Шляхом Шепотів.",
        completion = "Це, мабуть, її останки. Її запечатали тут і покинули помирати. \n\nАле чому?",
    },
    [92928] = {
        title = "Те, що поховали",
        description = "Видіння Нек'залі привели нас сюди. Те, що ми знайшли місце, де вона зробила свій останній подих, — не випадковість.\n\nУ цій крипті має бути щось, що богиня хоче нам показати.\n\nЗул'джарра доручила нам знайти правду про Ула'тек. Можливо, саме тут ми знайдемо відповіді, яких шукаємо.\n\nПогляньмо, де закінчується історія, яку нам розповіли в Лігві Відлунь, — і де починається правда.",
        objectives = "Досліди три зали у Крипті Відкинутих.",
        completion = "Я вже бачила цю історію, але чогось бракує... \n\nТреба шукати далі.",
    },
    [92929] = {
        title = "Причаєне в темряві",
        description = "Ті, хто звів цю крипту, не запечатали б її без вагомої причини.\n\nТут, мабуть, живе велике зло минулого.\n\nУсіх духів і нежить, яких знайдемо, слід упокоїти. Вони не стануть між нами й відповідями, яких ми шукаємо.",
        objectives = "Убивай нежить і очищай некротичну енергію в Крипті Відкинутих.",
        completion = "Хай з якої причини їх тут поховали і хай чому вони прокинулися — вони заслуговують повернутися до богині.",
    },
    [92930] = {
        title = "Написано переможцями",
        description = "Одна з версій цієї історії записана в Лігві Відлунь. Ті самі події, тільки закарбовані руками амані, а не гаранірів. \n\nАле чогось бракує: Нек'залі. Як вона вплетена в історію Ула'тек? \n\nІ ми не знаємо, як Ула'тек прийшов у цей світ.\n\nМусимо спуститися глибше в крипту й побачити правду, написану на її стінах.",
        objectives = "Убий вартового крипти й побач останню фреску.",
        completion = "Зул'джарра... хвора?\n\nЩо сталося, поки нас не було?",
    },
    [92931] = {
        title = "Стримати отруту",
        description = "Рана від клинка Зул'джана. Вона не гоїться.\n\nЗул'джан, певно, отруїв її. Вона слабне, а мені не вдалося зцілити її Світлом.\n\n<Ліадрін знову огортає Зул'джарру Світлом. Нічого не змінюється.>\n\nПрокляття!\n\nХай що ви знайшли в тій крипті — це почекає.\n\nАмані намагаються знайти ліки. Спитай Раз'таку, чи є в нього поступ.\n\nЯкщо потрібно щось іще, поговори з Так'леджо. Зул'джарра має зосередитися на одужанні.",
        objectives = "Допоможи іншим зцілити Зул'джарру.",
        progress = "<Орвейна заплющує очі, наче до чогось прислухається.>",
        completion = "Цей троль із тобою, {NAME}? Якщо він хоче битися з незліченними ворогами, що стоять між нами й відповідями, яких ми шукаємо, — я вітаю його поміч.",
    },
    [92932] = {
        title = "Зачистити болото",
        description = "Поглянь удалину. Небо повниться неспокійною, лихою енергією. У тій споруді попереду мають бути відповіді, яких ми шукаємо.\n\nІстот, що стоять нам на заваді, треба винищити. Ми не можемо ризикувати поразкою в такій важливій справі.",
        objectives = "Убий 12 болотяних звірів у Болоті Шепотів.",
        completion = "Живучі звірі. Інакше в такому місці не виживеш.",
    },
    [92933] = {
        title = "Берег духів",
        description = "Поки Зул'джарра лежить, амані з кожною миттю занепадають духом. Треба щось зробити, аби показати їм, що це ще не кінець.\n\nЦі тортоллани помагали, чим могли. Відплатімо їм добром і поможімо капітанові. \n\nКоли купка їхньої зниклої команди повернеться до міста, це має дати їм надію в цій проклятій землі.",
        objectives = "Допоможи заблукалим тортолланам у Болоті Шепотів.",
        completion = "Духи болота опанували тортолланів?\n\nУ мене більше запитань, ніж я знаю, що з ними робити.",
    },
    [92934] = {
        title = "Пожива для заклику",
        description = "<Твоя віддана послідовниця стишує голос, коли ти підходиш.>\n\nЯк ти й провістила, з неба падає червоний дощ. Небеса шикуються. Велика звірина пробуджується біля дверей під світом. Нарешті зброя для амані — могутніша за будь-якого лоа зандаларів. Бракує лише поживи, щоб її прикликати.\n\nБільшість ватаги поранена й відрізана. Підкошені солдати радітимуть, побачивши тебе, — чекатимуть, що ти їх зцілиш.\n\nВізьми свій кинджал і зроби те, що мусить бути зроблено. Тільки ти можеш нас урятувати, Нек'залі.",
        objectives = "Зрадь і принеси в жертву Поранених мисливців у Жаху Світодуші.",
        progress = "<Твоя вірна послідовниця схиляє голову, коли ти підходиш.>",
        completion = "Їхня жертва була на благо амані, знали вони це чи ні.",
    },
    [92935] = {
        title = "Загнані на край",
        description = "Океан за нашими спинами аж кишить щупальцями й очима, але там безпечніше, ніж на цій землі. Дурні ми були, що думали відібрати її в Кіт'ікса.\n\nТвоя нова одержимість ритуалами й забобонами досі мені не заважала, Нек'залі. Але тепер мені треба, щоб ти була цілителькою, якою була колись.\n\nПоможи моїм солдатам відбити акірів. Виграй нам час, поки прибудуть транспортні човни.",
        objectives = "Убивай акірів у Жаху Світодуші.",
        completion = "Арміям акірів немає кінця. Вони звідусіль.\n\nМи билися завзято, Нек'залі. Але виходу більше немає.",
    },
    [92936] = {
        title = "Закликання Ула'тек",
        description = "Де решта нашої ватаги?! Лави ламаються!\n\nМої солдати стримуватимуть їх, скільки зможуть. Слабкі хай тікають. Але ти і я... якщо нам помирати — то разом, зі зброєю в руках, сестро.",
        objectives = "Заклич Ула'тек й здолай акірів.",
        completion = "Зброя, що врятувала амані... Це було чудовисько, створене іншим чудовиськом... щоб убити чудовисько!\n\nІ на цьому наші предки збудували імперію?",
    },
    [92937] = {
        title = "Пробуджене зло",
        description = "Нек'залі, та жриця... Треба сповістити гаш'ей про те, що ми бачили.\n\nОрвейно. Гей! Стривай... що це з нею?",
        objectives = "Перевір, як там Орвейна.",
        completion = "Ікло Ула'тек. Кинджал, яким володіє Зул'джан. Ми мусимо його знайти.",
    },
    [92938] = {
        title = "Місце жаху",
        description = "Повітря густе від неприкаяних духів. Але є щось більше — це богиня. Там, де її голос колись був тихим, я чую, як тепер він зривається на муку. Наче крик жаху.\n\nМені лячно від того, що може чекати попереду.\n\nЯ піду за її голосом. Ходімо. Разом ми відкриємо її спогади про це місце.",
        objectives = "Побач спогади Азероту по всьому Вівтарю Гніву.",
        completion = "Богиня волає від болю. Я ще ніколи не бачила її спогадів у такому стані.",
    },
    [92939] = {
        title = "Це не просто камінь!",
        description = "{name}, тут у мене дещо дивне.\n\nПід час розвідки в Штормових полях мені трапився камінь, який гриз якийсь звір. Поглянь! Невже це руни? Письмо?\n\nАле таке прадавнє? Тут? Що б це могло означати?\n\nІ от що дивно: відколи ця штука в мене, у голові наче лунає голос...\n\nТреба розібратися. Може, у черевах тих звірів знайдеться ще таке каміння?",
        objectives = "Збери 6 давніх уламків зі звірів у Штормових полях.",
        progress = "І навіщо ці звірі взагалі гризуть це каміння?",
        completion = "Так, ти знайш$p(ов:ла) ще уламки!\n\nПомічаєш, що руни, викарбувані на цьому камінні, випромінюють Порожнечу? Схоже, істоти Войдшторму мають ненаситний голод до цієї магії.\n\nТож гадаю, ці звірі поїдають Порожнечу із цих рун. Принаймні так воно найлогічніше.",
    },
    [92944] = {
        title = "Просіюючи Порожнечу",
        description = "На поверхні такого каміння немає. Звірі риють нори — отже, знаходять його десь у підземній печері.\n\nЯ все міркую, як нам туди дістатися.\n\nБачиш вихори, якими всіяні Штормові поля? Вони викривлюють простір і переносять речі з місця на місце.\n\nПройди крізь один із них — і я зможу проявити аномальний осад, що їх оточує.\n\nЗбери осад, і я складу закляття, яке спрямує портал туди, звідки походить це каміння!",
        objectives = "Стрибай у зоряні вихори в Штормових полях і збери 10 аномального осаду.",
        progress = "Була в мене підозра, що ці руни — не доманаарські й не ефіріальські. Привид майже підтверджує мої думки. Це може бути щось інше. Може, навіть ціла цивілізація!",
        completion = "Ти це чу$p(в:ла)? Цей світ звався Предацея!\n\nЯке відкриття!",
    },
    [92945] = {
        title = "Сила страждання",
        description = "Загрози, на які ми полюємо, розумні. Рішучі. Смертоносні.\n\nЇхня винахідливість намагатиметься тебе заплутати. Їхня сила прагнутиме тебе знищити. Саме з їхньої волі до життя — до хижацтва — ми видобудемо есенцію, потрібну для живлення магічного захисту нашого міста.\n\nМої помічники вже розклали іграшки нашого друга. Раджу з ними ознайомитися.",
        objectives = "Навчися полювати на свою здобич.",
        progress = "Поговори з Асталором Кровоприсяжним, щоб продовжити.",
        completion = "Пастка одного дурня -- скарб для іншого ельфа.",
    },
    [92946] = {
        title = "Поховане в темряві",
        description = "Ми на порозі грандіозного відкриття! Хутчіш, немає часу навіть кликати підмогу. Мусимо знайти цього дивного духа!\n\nЗ цим осадом я складу закляття, що підлаштує вихор. Він приведе нас до джерела каміння з письменами.\n\nСудячи з підказок привида, гадаю, на нас чекає ціла печера.\n\nБудь напоготові, {name}.",
        objectives = "Стрибни в найпівнічніший зоряний вихор у Штормових полях і дослідь печеру за ним.",
        progress = "Що ще нам вдасться дізнатися?",
        completion = "Якщо вірити цьому духу та його скрижалям, колись цей світ населяли численні квітучі цивілізації.\n\nЯк і на Азероті, вони вели нескінченні війни. Вони попросили в Акінтунде зброю, щоб покласти край усім війнам, — і він виконав прохання... створивши таку, що поклала край усьому.",
    },
    [92948] = {
        title = "Це понад моє розуміння",
        description = "Тож Акінтунде створив зброю, здатну винищити все розумне життя цього світу, — цілі еони тому?\n\nЛедве віриться.\n\nАле правда це чи брехня — лишати цього духа на волі не можна. Він явно небезпечний.\n\nЯкщо він справді знає, як створити таку зброю, не можна допустити, щоб він зв'язався бодай із кимось з Азерота. Ми ж обоє знаємо кількох паліїв війни, ладних на все заради такої сили...\n\nГадаю, я зумію ще раз переналаштувати вихор, щоб він переніс нас просто до Акінтунде. Готуйся до бою, {name}.",
        objectives = "Ступи в найпівнічніший зоряний вихор у Штормових полях, щоб стати до бою з Акінтунде Нездоланним.",
        progress = "Ані сліду каяття я в ньому не відчуваю. Як таке взагалі можливо?",
        completion = "Пробач мені, {name}. Усе сталося так швидко.\n\nЧи було в усьому тому хоч слово правди? Але чим ще міг бути той дух?\n\nЦілий світ... цивілізації, що колись квітли просто там, де ми стоїмо? Невже так справді було?\n\nНапевно можу сказати тобі лиш одне. \n\nЦе переслідуватиме мене до кінця моїх днів.",
    },
    [92949] = {
        title = "Breadcrumb to Bitterbark",
    },
    [92950] = {
        title = "Збери інгредієнти для дядька",
    },
    [92951] = {
        title = "Копати глибше",
        description = "Маска каже, що ми шукаємо сувої Малакрасса. Поки ми в Майсарі, спробуй знайти будь-які сувої, що їх лишили по собі Лихогіллі.\n\nМайсара — небезпечне місце, тож не марнуй часу на те, щоб їх перебирати — просто хапай, а перевіримо пізніше.\n\nНавіть якщо там не згадано Ула'тек, ми можемо знайти відомості про їхні плани чи наміри проти амані.",
        objectives = "Збери 8 Сувоїв Лихогіллі з Глибин Майсари.",
        progress = "Ці пошуки Ула'тек стають небезпечнішими, ніж Зул'джан собі уявляє.",
        completion = "<Кіндуру бере оберемок сувоїв. Він мовчить, але його занепокоєння очевидне.>",
    },
    [92952] = {
        title = "Місія до Майсари",
        description = "Магія допомогла, але... не досить. Я й досі не пам'ятаю ні свого імені, ні минулого життя. Може, ці знання втрачено навіки...\n\nАле я пам'ятаю більше про Ула'тек — точніше, про те, де нам знайти більше відомостей!\n\nУ цю подобу мене загнали тролі Лихогіллих. Вони берегли темні знання в таємниці від інших племен, зокрема й знання про Ула'тек.\n\nЯкщо хочемо дізнатися більше, мусимо вирушити до Глибин Майсари.",
        objectives = "Зустрінь Спантеличену Маску амані біля Глибин Майсари.",
        completion = "Малакрасс мертвий, але це не означає, що його знання втрачено.",
    },
    [92953] = {
        title = "Спогади про Малакрасса",
        description = "Коли я був слугою Лихогіллих, пам'ятаю розмови про дослідження Малакрасса щодо Ула'тек.\n\nМалакрасс записував свої знання на сувоях, які завжди тримав при собі. Тепер, коли він мертвий, нам треба з'ясувати, що з ними сталося.\n\nМайстри вроків Лихогіллих не заговорять із власної волі... але якщо ти вб'єш їх, я зможу обернути проти них їхню ж некромантську магію й змусити заговорити.",
        objectives = "Знищ майстрів вроків Лихогіллі та допитай їхні духи.",
        completion = "Печери Майсари ще небезпечніші за Глибини, а Вордаза настільки ж смертоносна, наскільки й жорстока.",
    },
    [92954] = {
        title = "Печери Майсари: Володарка душ",
        description = "Нотатки Малакрасса тепер у Вордази, і вона використовує їх для своїх некромантських дослідів.\n\nІди в Печери Майсари й поверни їх. Буде небезпечно — перш ніж спускатися, збери союзників.\n\nЯ залишуся тут і оберігатиму дядька. Треба перебрати всі зібрані сувої й дізнатися, що ще з них можна витягти.",
        objectives = "Забери Нотатки Малакрасса у Вордази й пройди підземелля Печери Майсари.",
        progress = "Чи буде в нотатках Малакрасса наступна підказка? Чи все це — лише марнування часу?",
        completion = "Вони в тебе. Що ж, погляньмо, чи було це варте всіх зусиль.\n\n<Зул'джан гортає сувої.>",
    },
    [92955] = {
        title = "Скрижалі Нумазону",
        description = "Предки не схилилися перед лоа — вони здобули зброю! Зброю, що привела нас до перемоги.\n\nЯ маю дізнатися більше.\n\nТи казав, що скрижалі в Нумазоні — найдавніші в усьому Зул'Амані. Там ми можемо продовжити пошуки. Можливо, прадавні амані лишили нам якісь підказки.\n\nДядько каже, що варто взяти маску. Випадковий спогад може стати ключем до розгадки цієї таємниці.",
        objectives = "Зустрінься із Зул'джаном біля Нумазону.",
        completion = "Дядько не розуміє. Ула'тек може змінити все.",
    },
    [92957] = {
        title = "Ось у чім заковика",
        description = "Якщо ці скрижалі зробили тоді, коли амані вперше прибули до Зул'Амана, то тут має бути якась підказка про Ула'тек.\n\nСкрижалі надто важкі, щоб їх нести, тож Дядько запропонував зробити відбитки написів.\n\nЯ пішов уперед на розвідку й уже зібрав кілька, та натрапив на Лихогіллих. Я повернувся сюди, щоб переконатися, що Дядько в безпеці.\n\nЗайди до Нумазону й збери ще відбитків, поки я наглядатиму за Дядьком. Стережися Лихогіллих.",
        objectives = "Зроби 6 відбитків Прадавніх скрижалей амані в Нумазоні.",
        progress = "Дай-но я гляну на відбитки...",
        completion = "Поглянь-но! Тут згадано, як амані прикликали великого змія, щоб той урятував їх від страшного ворога.\n\nА ось тут — змій переміг, але амані запечатали його.\n\nПерше святилище, зведене в Атал'Амані, присвятили змієві.\n\n<Кіндуру далі вивчає відбитки.>",
    },
    [92958] = {
        title = "Витік розуму",
        description = "Хотів би я допомогти більше, але... прогалини в моїй пам'яті. Через ушкодження маски її магія витікала хтозна-відколи.\n\nТи полагоди$p(в:ла) маску ззовні, та магія всередині й досі слабка.\n\nЗул'джан каже, що цю крипту захопили тролі Лихогіллих. Магія, яка тримає мене вкупі, схожа на ту, що використовують вони.\n\nТи зміг би допомогти. Здобудь їхні фетиші вроків — мені має вдатися висмоктати з них магію.",
        objectives = "Збери 6 фетишів вроків Лихогіллів у тролів Лихогіллів у Нумазоні.",
        progress = "Магія Лихогіллів здається такою знайомою... Це вони загнали мене в цю маску?",
        completion = "Висмоктати магію з фетишів — справа однієї миті.",
    },
    [92961] = {
        title = "Полювання на декор",
        description = "Готов$p(ий:а) до сьогоднішнього випробування? Я сховав одну річ зі своєї колекції тут, у нашому околі. Щоб її знайти, тобі лишень треба розгадати цю просту загадку:\n\nКам'яний вартовий.\nПерший вітає кожного нового сусіда.\nШукай у глибокій тіні.\n\nХай щастить!",
        completion = "Чудова робота!",
    },
