    [93382] = {
        title = "Перепрошую за втручання",
        description = "{name}! Радий тебе бачити. Захисникам фортеці не завадить твоя поміч.\n\nОдна з ґномів змайструвала робота, щоб той допомагав боронити твердиню. От тільки він казиться щоразу, як його вмикають.\n\nЇй потрібен той, хто зуміє як слід зривати атаки робота, щоб його можна було полагодити.\n\nЗнайдеш хвильку, щоб допомогти?",
        objectives = "Активуй Бійцебота 11.2.7, а тоді 3 рази перервай його здібності своїм вартовим Скверни або гончаком Скверни.",
        progress = "Хоч якась допомога! Сподіваюся, ти знайдеш спосіб переривати здібності цього бота.",
        completion = "Чудова робота! Тепер у мене буде час полагодити той баг, який усе це насправді спричинив.\n\nА може, просто скажу, що так і задумано, та й по всьому!",
    },
    [93384] = {
        title = "Поклик Глибин: Університетське Лихо",
        description = "Арканний фоліант, чимось явно розтривожений, позначений знаком Таласійського університету Сільвермуна.\n\nВарто було б розібратися, в чому річ.",
        objectives = "Пройди глибину «Університетське Лихо» на будь-якій складності.",
        progress = "В університеті щось негаразд?",
        completion = "Дякую, Флешрейне. Обставини не надто сприяли навчанню.",
    },
    [93385] = {
        title = "Поклик Глибин: Темний Шлях",
        description = "Недобитки Клинка Сутінків шастають, наче щури, тунелями Арквею під Сурамаром.\n\nВинищи цих шкідників, поки вони не розплодилися.",
        objectives = "Пройди глибину Темний Шлях на будь-якій складності.",
        completion = "Дякую тобі за це, {NAME}. Така магія не для їхнього роду.",
    },
    [93386] = {
        title = "Поклик Глибин: Площа Паргеліон",
        description = "Шукачі пригод! Кель'Данас знову атакує Порожнеча, тож усі, хто може стати до помочі, нехай вирушають на укріплення площі Паргеліон, щоб стримати навалу.",
        objectives = "Пройди глибину «Площа Паргеліон» на будь-якій складності.",
        progress = "Порожнеча невблаганна. Пильнуй.",
        completion = "Можливо, колись Сільвермун знову зазнає миру.",
    },
    [93387] = {
        title = "Розправа зі шкідниками",
        description = "Щоразу, як я виходжу з хатини, повертаюся до безладу й вогких мурлоцьких слідів.\n\nЯ задумав інакший підхід до цих настирливих земноводних зайд, але спершу треба зібрати деякі складники.\n\nПоки я складаю список проти цих шкідників — тут є привид на ім'я Джелвік, що все чіпляється до мене за чимось. Скажи йому, хай іде собі.",
        objectives = "Розберися з Джелвіком за дорученням Офі Хитрого.",
        completion = "На цьому етапі це вже гра.\n\nЯ знаю, що він там. Він знає, що я знаю, що він там, але поки я вдаю, що його не бачу, — цей раунд за мною!\n\nХоча якщо ти йому допоможеш, я не ображуся. Тоді виграємо обидва. Тільки не кажи йому, що я таке говорив.",
    },
    [93388] = {
        title = "Незвичайна алхімія",
        description = "Мій список готовий. Збери мені складники, щоб відвадити тих мурлоків назавжди.\n\nСпершу поговори з Макою Тральником. Вони з водоростеплетом із Дзьоба Торґи люблять рибалити в затоці. Принеси мені риб'ячих тельбухів — гидота, саме те, що треба.\n\nДалі вирушай у Багно Млуркра. Мені потрібна та брудна стара перлина, яку вони мають за скарб.\n\nА заразом позбав тих надокучливих змієлюдів кількох лусочок.\n\nІ затям: мені потрібні лише добрі.",
        objectives = "Роздобудь купу риб'ячих тельбухів, потьмянілу перлину й 5 неушкоджених зміїних лусочок і принеси все до хатини Офі.",
        progress = "Товар при тобі?",
        completion = "А ти корисне створіння!\n\nМене діймають привиди, а мурлоки влаштовують безлад щоразу, як я виходжу з хатини. Якби шкідники не шкодили, то були б і не шкідники, правда ж?\n\nЯ бачу: саме ти розв'яжеш мою проблему.",
    },
    [93389] = {
        title = "Роксблад",
        description = "Я тут так довго, що шматки моєї пам'яті загубилися в часі. Відчуваю порожнечу за чимось, що любив.\n\nМені не буде спокою, доки не дізнаюся, хто чи що це було. Пам'ятаю лиш одне слово... Роксблад. Не знаю, хто це чи що це.\n\nПошукай у мурлоцьких руїнах на півдні. Там є хтось, хто вкаже тобі правильний напрямок.\n\nОскільки Офі затявся, потрібна твоя поміч, щоб я згадав.",
        objectives = "Знайди підказки, що відімкнуть втрачену пам'ять Джелвіка.",
        completion = "Шматочки складаються докупи... я майже все згадав. Повертайся до Офі. Мені треба трохи над цим поміркувати.\n\nЯ знову відчуваю надію, {classv}. Це твоя заслуга, і я щиро вдячний.",
    },
    [93390] = {
        title = "Прийнятний підмайстер",
        description = "Оця частина буде весела.\n\nСуміш я вже заварив. Вона й так неприємна, але зараз ми зробимо її по-справжньому гидотною.\n\nКоли відчуєш моральну готовність знову побути корисним створінням — дай мені знати.",
        objectives = "Коли відчуєш готовність створити Смердючу суміш, поговори з Офі.",
        progress = "Ну що, відчуваєш виклик?",
        completion = "Уша! Оце так міць. Не знав я твоєї сили.\n\nПринаймні цього разу обійшлося без вибуху.\n\nНепогано, зовсім непогано.",
    },
    [93391] = {
        title = "Хай смердить",
        description = "Найліпше винеси наші маленькі відлякувачі на смугу землі між моєю домівкою і багном тих навіжених.\n\nВони можуть спробувати тебе спинити — тримайся. Якщо все спрацює, вони тікатимуть, підібгавши хвости.\n\nА в мурлоків узагалі є хвости?",
        objectives = "Розстав 3 відлякувачі мурлоків між хатиною Офі й Багном Млуркра.",
        progress = "Мурлоки забралися?",
        completion = "Ха! Чудова робота. Це змусить їх бігати ще довгенько.\n\nЛюблю запах хаосу зранку. \n\nХоча, звісно, це може бути й від тебе. Не відійдеш трохи далі?",
    },
    [93392] = {
        title = "Повернення спогадів",
        description = "На північному сході є острівець. Пам'ятаю, давним-давно понад водами відлунювали могутній рев і виття.\n\nЯ чув гнів, але був там і біль. Я не наважувався піти в те місце. А що, як я заблукав би там, і мої власні почуття поглинули б ті, більші?\n\nОдного дня там знову стало тихо, але тепер я відчуваю: це останній ключ до замка на моїй душі.\n\nІди туди. Знайди останній шматочок.",
        objectives = "Здолай Самотнього звіра й знайди втрачений спогад Джелвіка.",
        completion = "Я ладен заплакати від радості, що сповнила мій дух. Я думав, вона зникла так давно, що навіть із моїх думок урешті пішла.\n\nТепер моя люба Сава буде зі мною назавжди.\n\nДякую, {NAME}.",
    },
    [93393] = {
        title = "Трохи доброти",
        description = "Знаєш, друже, хоч який я щасливий... усе думаю про те, якого смутку ми завдали тому звірові. Не побажаю такого відчуття жодній живій душі.\n\nВін піклувався про дорогу Саву всі ті роки, що вона була загублена. Допоможеш нам з останнім проханням?\n\nЯкщо приведеш йому власного друга, наш борг буде сплачено.\n\nТоді ми зможемо піти раз і назавжди — ми з Савою будемо вільні.",
        objectives = "Розпитай Офі Хитрого й допоможи Самотньому звірові.",
        progress = "Ти тільки нікому не кажи про мою участь у цьому всьому. \n\nЯкщо люди почнуть думати, що я м'який, мені більше не дадуть спокою.",
        completion = "Ну от і скінчилася наша гра. Гадаю, тут стане тихіше тепер, коли мого друга нема.\n\nЩо? Я завжди вдаю, що моїх друзів не існує. А ти хто? Ха!\n\nО, схоже, одне з малих уподобало твоє товариство дужче за звірове. Краще забери його з собою.",
    },
    [93396] = {
        title = "Тріщить по швах",
        description = "Вераан... жива...\n\n<Кіфаан недовірливо хитає головою.>\n\nЯ безліч годин прокручував цю мить у голові, а тепер, коли вона настала, не можу дібрати слів...\n\nТіньова варта намагалася привести Дименсіуса до влади... вони присягнули на вірність Ксал'атат, поки та веде війну проти світів. І що, мені просто... вдавати, ніби нічого цього не було? ЦЬОГО вимагають мої клятви родині?\n\nА як же Вераан? Чи шкодує вона про свою причетність?\n\nТреба її провідати.",
        objectives = "Допоможи Кіфаанові дізнатися, як почувається його сестра.",
        completion = "Я так зосередився на власних почуттях, що жодного разу не спинився подумати, як може почуватися Вераан.\n\nЯкби МЕНЕ накачали Порожнечею вщерть, я навряд чи тримався б краще.",
    },
    [93397] = {
        title = "Гризучий голод",
        objectives = "Назбирай падла, щоб ослабити слинявих ультрадонів",
    },
    [93400] = {
        title = "Цукрова виправа",
        description = "Ах, Луґнаса. Найкраща пора для моторошних історій, сяйливих гарбузів і солодких-солодких цукерок!\n\nАле цьогоріч я хочу створити щось справді незабутнє. Смачну добірку цукерок, натхненну краями з усього Азероту!\n\nДля цього я залучив помічника. Одного... ексцентричного кулінарного генія. Можливо, ти його знаєш. Я відіслав його до Сутінкового лісу на пошуки моторошних рецептів, які напевно всіх вразять.\n\nЗнайди його й принеси трохи тих проклятих цукерок.",
    },
    [93401] = {
        title = "Моторошні краплі меду",
        description = "А ти любиш ризикувати! Краплі меду смачні, але здобути їх буває справжньою мукою - у прямому сенсі! Не чекай теплого прийому від мешканок вуликів, з яких діставатимеш краплі меду.",
    },
    [93409] = {
        title = "Поклик Глибин: Атал'Аман",
        description = "<Тіло полеглої розвідниці вкрите страшними ранами, але й досі міцно стискає донесення про неминучий напад Лихогіллих на Атал'Аман.>",
        objectives = "Пройди глибину Атал'Аман на будь-якій складності.",
        completion = "Добре. Хай навчаться сидіти у своїх норах.",
    },
    [93410] = {
        title = "Поклик Глибин: Сутінкові Крипти",
        description = "Прадавні крипти амані біля Розбитого Трону захопили чужинці.\n\nОчисти їх від зайд, поки мертвих усередині не осквернили ще більше.",
        objectives = "Пройди Глибину «Сутінкові Крипти» на будь-якій складності.",
        completion = "Одного дня Зул'Аман звільниться від їхньої скверни.",
    },
    [93416] = {
        title = "Поклик Глибин: Затока Пам'яті",
        description = "Ширяться чутки про заворушення в Затоці Пам'яті.\n\nРозберися з цим, поки лихо не вкоренилося.",
        objectives = "Пройди глибину «Затока Пам'яті» на будь-якій складності.",
        progress = "Що вдалося з'ясувати?",
        completion = "Дякую тобі, {NAME}, за те, що це придушено в зародку.",
    },
    [93417] = {
        title = "Сховища Атал'Утек: Вівтар Іклів",
        description = "Орвейна розповіла нам, що бачила...\n\nХай тобі грець, Зул'джане! Невже він справді не розуміє, що накоїв? Попри все, чого ми досягли, він має узи, які Зул'джарра сплела з нами обома, за слабкість — і досі женеться за ідеєю «всевладної Імперії Амані».\n\nА заразом він тяжко поранив рідну сестру.\n\nТа, може, Зул'джарра має рацію — може, він і не відає.\n\nМи мусимо здобути той кинджал. Напоумивши його — або силою.",
        objectives = "Провідай війська в Сховищах Атал'Утек і пройди підземелля Вівтар Іклів.",
        completion = "Відколи ми здобули кинджал, мене морозить зсередини.\n\nОгляньмо його, швидше.",
    },
    [93418] = {
        title = "Отруйна Безодня",
        description = "Я бачив дещо в отруйному мареві.\n\nЧув, як кричить Зул'джан, відчув, що його роз'їдає. \n\nЧув, як Малакрасс шепоче йому на вухо.\n\nУла'тек переслідувала амані від самого початку. На що ми йшли заради влади й імперії, і якою кров'ю це коштувало...\n\nЦе не була велич. У глибині душі Зул'джан теж це знає.\n\nМалакрасс забрав у мене діда. Я не дам йому забрати ще й Зул'джана.\n\n|cffff1919<Сюжетний режим буде доступний незабаром.>|r",
        objectives = "Пройди рейд Отруйна Безодня на будь-якій складності.",
        completion = "Зул'джарра винитиме себе, але ми знаємо: вона зробила все — геть усе, — щоб його врятувати.",
    },
    [93419] = {
        title = "Природа її ран",
        description = "Ікло прокляте від часу прикликання Ула'тек. Ним можна зцілити Зул'джарру. Я тільки...\n\nТреба діяти швидко. Вона згасає!",
        objectives = "Використай Ікло Ула'тек, щоб зцілити Зул'джарру.",
        completion = "{NAME}... дякую. Я стільки всього побачила. \n\n<Зул'джарра дивиться кудись удалину й гарчить.>\n\nЗапізно... Ні!\n\n<Зул'джарра здригається всім тілом і хмурніє, скидаючи з себе видіння.>\n\nМи мусимо знайти мого брата.",
    },
    [93420] = {
        title = "Присуд Лор'темара",
        description = "Ми мусимо розповісти Лор'темару, що тут сталося. Зустрінься зі мною в Сільвермуні.\n\nЩодо Зул'джарри... їй потрібен час. Їй потрібен її народ, а народові потрібна вона.\n\nВона це переживе. Я певен. Мусить!",
        objectives = "Повернися до Лор'темара Терона в Сільвермун.",
    },
    [93421] = {
        title = "Поклик Глибин: Яма Злоби",
        description = "<Це запліснявіле полотнище грубо перемальоване: на ньому один фунґаріанин гамселить іншого чимось схожим на стілець.>\n\nДивись великий бій. Найкращий бій!\n\nЯма Злоби. Приходь!",
        objectives = "Пройди глибину «Яма Злоби» на будь-якій складності.",
        progress = "Як бійка?",
        completion = "Гарний бій? Так.\n\nНайкращий бій? Можливо!",
    },
    [93423] = {
        title = "Іскри війни: Ліс Вічної Пісні",
        description = "Лісом Вічної Пісні блукають загадкові істоти.\n\nВируш туди й дізнайся про них усе, що зможеш.",
        objectives = "Збери 100 Іскор війни в Лісі Вічної Пісні, перебуваючи в режимі війни.",
        progress = "Роботи ще вистачає.",
        completion = "Це дає деякі відповіді. Красно дякую.",
    },
    [93424] = {
        title = "Іскри війни: Зул'Аман",
        description = "У Зул'Амані причаїлася невідома небезпека.\n\nВирушай туди й наведи лад!",
        objectives = "Збери 100 Іскор війни в Зул'Амані, перебуваючи в режимі війни.",
        progress = "Ну ж бо, вперед!",
        completion = "Щира дяка за наведений лад.",
    },
    [93425] = {
        title = "Іскри війни: Гарандар",
        description = "У землях по всьому Гарандару розплодилися могутні створіння. Вирушай і з'ясуй, що там діється.",
        objectives = "Збери 100 Іскор війни в Гарандарі, перебуваючи в режимі війни.",
        progress = "Ще є що досліджувати.",
        completion = "Це були неабиякі зусилля — щира дяка.",
    },
    [93426] = {
        title = "Іскри війни: Войдшторм",
        description = "У Войдштормі коять безлад сили хаосу. Вирушай на розвідку й наведи там лад!",
        objectives = "Збери 100 Іскор війни у Войдштормі, перебуваючи в режимі війни.",
        progress = "Ще є за чим пильнувати.",
        completion = "Це дає деякі відповіді та ясність.",
    },
    [93427] = {
        title = "Поклик Глибин: Святилище Сонцевбивць",
        description = "<До вбитого блукача Порожнечі пришпилено записку.>\n\nСвятилище Сонцевбивць — кубло найжалюгідніших підлабузників Ксал'атат.\n\nЗакликаю всіх найманців, шукачів пригод і просто доброчинців, кому трапиться це оголошення про винагороду: навідайтеся туди й звершіть ту саму справедливість, про яку ви всі так любите розводитися без упину.\n\n - Перодіус",
        objectives = "Пройди глибину «Санктум Сонцевбивць» на будь-якій складності.",
        progress = "А, дренеї. Яка втіха.",
        completion = "Ось твоя винагорода, паладин.\n\nХай це навчить їх надалі не відмахуватися від цілком пристойного хабаря.",
    },
    [93428] = {
        title = "Поклик Глибин: Застава Тіньової Варти",
        description = "Стань свідком долі тих, хто схиляє шию перед Ксал'атат.\n\nЯ кидаю виклик будь-якому створінню — з Порожнечі чи з плоті. Вистеж ефіріалів поблизу і знищ усіх, хто служить так званій Провісниці.\n\n - Перодіус",
        objectives = "Пройди Глибину Застава Тіньової Варти на будь-якій складності.",
        progress = "Тебе привела до мене якась причина, {class}?",
        completion = "За надані послуги.\n\nЯкби ж усі смертні були такі помічні, як ти.",
    },
    [93432] = {
        title = "Мечі на орала",
        description = "Спершу Мор'дуун і Клинок влаштували засідку на Атал'Аман. А тепер його заполонили ці «відлуння»...\n\nПринаймні так їх називає Дору: відлуння. Я ж бачу лише привидів кривавіших часів. І як у ті дні — скільки їх не рубай, вони все сунуть і сунуть.\n\nВирушай туди й подивися на власні очі. І принеси рештки відлунь. Дору хоче дослідити, що вони таке і як діють.",
        objectives = "Збери Попелясті Останки Рейдерів (20).",
        progress = "Це наче сон, з якого не можеш прокинутися.",
        completion = "Бачиш? Безкраїй океан.\n\nМожливо, Дору чогось навчиться з цього попелу.",
    },
    [93433] = {
        title = "Освячено, запечатано, доставлено",
        description = "Кляті відлуння.\n\nКлятий Зул'джин, і Мор'дуун, і той змій Малакрасс.\n\nВід них живим лише більше безладу, який доводиться розгрібати.\n\nСлухай, гаш'ура. Треба доставити припаси до кожного святилища в місті. Ми спакували їжу, воду, бинти й реагенти, щоб їхні бар'єри трималися на повну силу.\n\nІ розпитай, як у них справи. Там хоч і безпечно, але всі вони, певно, почуваються замкненими в чотирьох стінах.",
        objectives = "Доправ припаси старійшинам чотирьох Святилищ Лоа: старійшині Шимаррі, орлоглядові Ріду, старійшині Таку й старійшині Ву'лоні.",
        completion = "Бар'єри тримаються? Добре.\n\nТепер можемо зосередитися на наступі.",
    },
    [93435] = {
        title = "Четверо призвідників",
        description = "Розвідники доповідають, що серед відлунь трапляється кілька особливих облич. Коли до мене дійшли ті імена, в мені прокинулася давня лють.\n\nТо були не гідні бійці, з якими варто мірятися силою, як-от ти. То була погань — жадібні пройдисвіти, що привели сюди легіони підступних шукачів пригод грабувати наші пожитки, наші скарби і... наші бивні.\n\nЯкщо вбити відлуння цих ключових постатей, нових відлунь має з'являтися менше.\n\nА мені буде втішно знати, що вони впали.",
        objectives = "Убий відлуння Пригмона, Зунгама, Бадда Недрека й Гаррісона Джонса.",
        completion = "Зізнаюся, {name}: знаття, що ти вби$p(в:ла) призвідників, гріє мої старі кістки.\n\nЧи не впала через це твоя думка про мене?",
    },
    [93436] = {
        title = "Вроки невинним, розлад винним",
        description = "Я вивчу здобутий тобою попіл, але цю ситуацію можна взяти під контроль і не самою лише сокирою.\n\nТи маєш розладнати їм поле бою, гаш'ура. Відлуння вірять, що й досі ведуть битву, яка відгриміла десятиліття тому, — тож треба вдарити по підтримці, на яку вони тоді покладалися.\n\nОтруї учти, біля яких вони перепочивають, наврочи їхнім зневажливим союзникам з мирного люду й попсуй ту скриню, яку вони так завзято силкуються обчистити!",
        objectives = "Отруї 3 Учти Нападників, зуроч 7 Цивільних і споганій Скриню Воєначальника.",
        progress = "Доведімо, що навіть відлуння минулого можуть звідати горе.",
        completion = "Відлуння тікають з поля бою, як налякані кабани, завдяки твоїй роботі!",
    },
    [93437] = {
        title = "У їхній власній крові",
        description = "Дослідивши попіл, Дору вважає: з минулим можна боротися лише зброєю минулого.\n\nЯ не можу просити такого в жодного з амані. Ані у Візербарків, Ревантусків чи Шедоупайнів. Мабуть, сама доля привела тебе до нас у ці часи... бо з таким проханням ми могли звернутися тільки до чужинця.\n\nТи маєш прийняти в себе душу одного з опоганених — тих, хто пристав на мерзенну угоду Малакрасса й поглинув силу лоа за доби Зул'джина.\n\nПовернися до святилища того опоганеного, з яким хочеш злитися.\n\nПращури, простіть нам...",
        objectives = "Стань одним із чотирьох Аватарів Лоа.\n\nУбивай Відлуння-Нападників в Атал'Амані й здолай Ватажка Набігу на Сходах Воєначальника.",
        completion = "Дякую тобі, гаш'уро. Щиро.\n\nБитва проти відлунь триватиме. Однак, схоже, тепер, коли з їхнім ватажком покінчено, вони не повертатимуться після загибелі.\n\nЦими днями спогади збурили мою кров. Тепер ми всі можемо спочити. А може, навіть і рушити далі?\n\nБа! Це просто марення старого воїна. Не зважай на мене.\n\nВважай лише, що я твій боржник.",
    },
    [93438] = {
        title = "Особливе доручення: точне висічення",
        objectives = "Осідлай бойового вірма\nСили в нижньому дворі знищено\nForces slain in lower courtyard HIDDEN\nСили у верхньому дворі знищено\nForces slain in upper courtyard HIDDEN\nОсобливо цінні цілі ліквідовано\nСили у Варті Штормаріона знищено\nForces slain in Stormarion Watch HIDDEN\nПрипаси Штормаріона знищено",
    },
    [93440] = {
        title = "Особиста історія",
        description = "Мор'дуун убитий, Клинок Сутінків розбитий — і мій народ хоче повернутися до Атал'Аману.\n\nЦе мала б бути мить великого свята, але... щось несподіване заступає нам шлях.\n\nРозшукай Торундо та старійшину Дору. Вони опікуються переселенням і знатимуть, як найкраще застосувати твої таланти.\n\nПриготуйся, гаш'ура, і без вагань захищай Атал'Аман — хоч би хто трапився тобі там.",
        objectives = "Поговори із Торундо Сивим в Атал'Амані.",
        completion = "Тебе прислала Зул'джарра, гаш'ура?\n\nХе. Мабуть, їй набридло чекати, поки ми зрушимо з місця.",
    },
    [93449] = {
        title = "Халепа на болоті",
        description = "Гурт моїх людей подався до Багна Млуркра й не повернувся. Вони розвідували вторгнення Дітей Ула'тек в тих краях. Долинають також тривожні вісті, що місцеві мурлоки стали лютіші, ніж звичайно, а жриця Ва'кані казала, що вловила сильну темну енергію, яку хотіла перевірити.\n\nЇхня очільниця, Заваді, мала відзвітувати ще годину тому. Підеш розшукаєш їх і, як буде треба, подаси поміч?",
        objectives = "Знайди Заваді в Багні Млуркра.",
        completion = "Тебе прислав Ра'каму? Добре. Поміч мені не завадить.",
    },
    [93452] = {
        title = "Знайдений зім'ятий подарунок",
        description = "<Схоже, посіпаки Гринча втекли, залишивши по собі маленький подарунок: пом'ятий, але ще придатний.\n\nМожливо, хтось із організаторів Зимового свята зможе допомогти повернути його тому, кому його й призначали.>",
        objectives = "Поговори з Джоанною Копперпінч у сусідстві Береги Гострого Вітру.",
    },
    [93453] = {
        title = "Питання надгробне",
        description = "Дорогий покійнику,\n\nти щойно скуштува$p(в:ла) гіркого жала смертності, тож кращої миті, аби обговорити з тобою тему, яку так часто оминають, — смерть і пам'ять, — годі й шукати. Те, що ти залишаєш по собі в справжньому, тілесному сенсі.\n\nРозмови про кохання та інші дрібниці лиши філософам і чепурунам. Я кажу про холодний, твердий камінь і про діяння, викарбувані на ньому.\n\nЗнайди мене в Сільвермуні.",
        objectives = "Зустрінься з Нелтіусом Тінекаменем у Сільвермуні.",
        progress = "Ти вже зробив свій вибір?",
        completion = "Чудово. Можеш робити нові домовленості, коли тільки забажаєш.\n\nЯ, як і смерть, людина терпляча.",
    },
    [93454] = {
        title = "Слова, які варто почути",
        description = "Малакрасс допоміг моєму дідові привести амані до загибелі. Тепер він зробить те саме з моїм братом. Якби ж нам просто роз'єднати цих двох... \n\nАле Джан не слухає.\n\nВін вважає Ула'тек зброєю, що поверне Імперію Амані. Після видіння, яке він побачив, — і хтозна, що ще наплів йому Малакрасс, — мені його не переконати.\n\nГаш'ей потребує ради, гаш'ура. Збери інших і приєднуйся до мене.",
        objectives = "Разом із союзниками дай пораду Зул'джаррі.",
        completion = "Ще ніколи видіння гаранірів не завдавали стільки болю...\n\nАле знання не в тих руках може послужити і добру, і злу.",
    },
