    [93495] = {
        title = "Політ крізь час",
        description = "Піски часу плинуть туди й назад, наче океанські хвилі.\n\nЩе раз вирушай часовими стежками — до доби Драконових Аспектів і Первісних Втілень.\n\nПринеси мені перекази про звитяги з епохи великих пригод і небезпек.",
        objectives = "Пройди 5 підземель Мандрівки в часі.",
        completion = "{name}, ти поверну$p(вся:лася).\n\nЯкі перекази ти прин$p(іс:есла)?",
    },
    [93497] = {
        title = "Шлях крізь час",
        description = "То був час, коли кувалися нові союзи й нові вороги. Згадаймо разом про великих Драконових Аспектів та їхнє повернення до колишньої слави.\n\nВирушай у минуле, на Драконові Острови, і повернися з усім знанням, яке здобудеш.",
        objectives = "Пройди 5 підземель Мандрівки часом.",
        completion = "Не щодня випадає бачити, як відроджуються Аспекти Драконів. Цінуй ці миті.",
    },
    [93499] = {
        title = "У пелені арен",
        description = "Важливе випробування для сильного бійця — злагоджені дії з іншими в бою. Знайди соратників, які стануть із тобою пліч-о-пліч у битві на арені.",
        objectives = "Здобудь честь на рейтингових аренах, перебуваючи в групі.",
        completion = "Дуже вражає — тримай, це заслужено.",
