    [93586] = {
        title = "Conditional - Multiple Objectives, Non Sequenced",
        description = "Мене прислали сюди довести, що з мене таки буде воїн амані.\n\nДля цього випробування мені треба зібрати з цих корчедінів якомога більше трофеїв.\n\nНам двом варто працювати разом! А я допоможу тобі здобути визнання воїна амані, гаразд?\n\nПросто рушай туди та здобудь якнайбільше трофеїв із корчедінів.\n\nА я лишуся тут і пильнуватиму наші спини, еге ж?",
        objectives = "Здобудь 1 трофеїв з корчедінів та їхніх союзників.",
    },
    [93593] = {
        title = "Поклик битви",
        description = "Наш світ — світ безнастанної боротьби, чи не так? Навіть у мирні часи варто тримати бойові навички гострими.\n\nДо мене дійшло чимало розповідей про твою майстерність. Погляньмо, на що ти здатн$p(ий:а).",
        objectives = "Виграй 4 матчі на полях бою.",
        progress = "Ніщо не замінить постійної пильності, {class}. Ал'анна, даломор.",
        completion = "Як тобі велося на полях битв? Були перемоги? Були поразки?\n\nІ з перших, і з других можна винести уроки.",
    },
    [93595] = {
        title = "Поклик Глибин",
        description = "Пошуки випробувань і скарбів ставлять уміння на пробу — і водночас відкривають те, що дасть нам ще більшу силу.\n\nНа твоєму місці я поринав би в ті місця, що обіцяють і перше, і друге.",
        objectives = "Заверши 5 глибин Опівночі.",
        progress = "Чи добігли твої виправи в Глибини втішного завершення?",
        completion = "Ти досі жив$p(ий:а), а це означає дві речі. Перша: я не помилився, скерувавши тебе до тих глибин. Друга: ти тепер здібніш$p(ий:а), ніж раніше.",
    },
    [93598] = {
        title = "Емісар війни",
        description = "Лише сягаючи за власні межі, ми по-справжньому зростаємо... або зазнаємо поразки й звільняємо шлях іншим.\n\nПрояви себе, кинувши виклик найсмертоноснішим із місць. Шорел'аран.",
        objectives = "Пройди 4 підземелля на міфічній складності.",
        progress = "Чи станеш ти частиною міфів і легенд, {class}?",
        completion = "Твої звершення перевершили навіть мої найсміливіші сподівання. Чудова робота, {NAME}.",
    },
    [93599] = {
        title = "Найкращі з найкращих",
        description = "Навіть найменші з-поміж нас мають зіграти свою роль. Це стосується й наших маленьких друзів.\n\nХочеш загартувати їхню майстерність і зміцнити ваш зв'язок — кидай виклик іншим. Виживуть лише найпристосованіші.",
        objectives = "Переможи 5 гравців через «Пошук бою» командою улюбленців 25-го рівня.",
        progress = "Зміцнюючи ці узи, ви з маленькими товаришами будете готові до всього, що чекає попереду.",
        completion = "Звістка про твій успіх випереджає тебе. Ти вправно керува$p(в:ла) своєю командою, {name}.",
    },
    [93600] = {
        title = "Арена кличе",
        description = "Старі затхлі підземелля й поля битв — то одне, але саме арена відділяє зерно від полови.\n\nЗможеш проявити себе, {class}? Покажи мені. Хай я почую, як твоє ім'я вигукують з трибун ті, хто прагне крові.",
        objectives = "Виграй 10 битв на арені (сутички).",
    },
    [93605] = {
        title = "Світ чекає",
        description = "Сіну а'маноре, {class}. Так, у минулому мій світогляд був не надто... егалітарним. Але в ці неспокійні часи справ не бракує — чи то тут, у Кель'Таласі, чи деінде.\n\nЧи приймеш виклик і проявиш себе ще раз?",
        objectives = "Виконай 10 світових завдань в Опівночі.",
        progress = "Халепа всюди. Нас міряють тим, як ми долаємо ці перепони.\n\nЗ гідністю чи з люттю? Може, потроху й того, й того?",
        completion = "Про твої зусилля знають і їх цінують. Ану бала белоре'алон.",
    },
    [93607] = {
        title = "Первісний шлях крізь час",
        description = "Вітаю, {class}. Ти приходиш до мене, бо шукаєш відповідей. Я можу дати тобі лише пораду.\n\nМожливо, відповіді, яких ти шукаєш, криються в минулому? Повернися до тих часів, лише за кілька років після завершення Третьої війни. Стань знову проти тодішніх загроз і поглянь, яку мудрість зможеш здобути.",
        objectives = "Пройди 5 підземель Мандрівки в часі.",
        completion = "Неодмінно поділися всім, що ти дізнався з минулого, щоб ми не повторювали тих самих помилок у майбутньому.\n\nАль дієль шала, {NAME}.",
    },
    [93608] = {
        title = "Палаючий шлях крізь час",
        description = "По той бік Темного порталу лежить Позамежжя. Я там ніколи не бував — моя історія пов'язана радше з Кірін-Тор, ніж із Сільвермуном. Та ельфи Кель'Таласа пережили чимало потрясінь у ту пору.\n\nМожливо, ти зможеш дечого навчитися з того розколотого світу. Прийми виклик, якщо вважаєш себе гідним його.",
        objectives = "Здолай 5 рейдових босів або підземель Мандрівки в часі.",
        completion = "Ельфи Кель'Таласа багато вистраждали в той період — але й дізналися більше істин та уроків, ніж можна злічити. \n\nБез сумніву, ти став сильнішим і мудрішим після цієї подорожі.",
    },
    [93610] = {
        title = "Крижаний шлях крізь час",
        description = "Уроки минулого слід час від часу переглядати й повертати в сьогодення як нагадування.\n\nПройди часовими шляхами і повернися до тієї пори, коли Король-Ліч та армії Погибелі вийшли з крижаних пустищ Нордролу й загрожували всьому Азероту. З тих часів можна багато чого навчитися.",
    },
    [93611] = {
        title = "Розтрощений шлях крізь час",
        description = "Катаклізм був жахливим для всього Азерота. Загроза самому існуванню, що нею став Дезвінг, відлунює крізь віки. Хіба не цікаво, що хоч би як усе змінювалося, такі загрози повертаються знов і знов, тільки в інших подобах?\n\nПовернися туди і стань проти тих загроз ще раз. Поглянь, чи знайдеться щось нове, чого можна навчитися з минулого.",
        progress = "Мені... не хотілося б знову переживати ті часи. Деякі спогади краще лишити позаду.",
        completion = "У тебе більше відваги, ніж у мене, чемпіоне. Сподіваймося, що засвоєні тобою уроки й справді підуть у діло.",
    },
    [93612] = {
        title = "Оповитий шлях крізь час",
        description = "Мої спогади про Пандарію... непрості, {class}. Багато уроків було засвоєно в ту буремну пору — одні добрі, інші болючі.\n\nСвіт відтоді дуже змінився. Ми всі змінилися — сподіваюся, на краще.\n\nВирушай назад крізь тумани часу. Перевчи ті уроки, які зможеш.",
        completion = "Чим тебе сповнило повернення — просвітленням чи гіркотою від рішень минулого? Сподіваюся, твої уроки далися тобі легше, ніж мої — мені.",
    },
    [93613] = {
        title = "Дикий шлях крізь час",
        description = "Можливо, тобі вдасться осягнути глибину знань, яку можна віднайти в Дреноре — не в розтрощених рештках Аутленду, а в Дреноре Залізної Орди. Він по-своєму такий самий суворий, якщо не суворіший, ніж будь-коли було Аутленду.\n\nПоглянь, яку мудрість ти зможеш там знайти.",
    },
    [93614] = {
        title = "Сквернений шлях крізь час",
        description = "Я стояв проти багатьох ворогів, та Палаючий Легіон був, мабуть, найбільшою загрозою, з якою стикався наш світ. Принаймні... досі.\n\nЗвісно, є ще й наші внутрішні демони, з якими доводиться боротися.\n\nЧи стане тобі снаги, щоб перемогти Палаючий Легіон?",
        completion = "Снаги тобі й справді не бракує. Хай Легіон ніколи не повернеться.",
    },
    [93627] = {
        title = "Пошрамований шлях крізь час",
        description = "Я добре пам'ятаю битви Альянсу та Орди, що точилися в Кул-Тірасі й Зандаларі. Повернися туди, перепроживи ті спогади.\n\nЧого ти шукатимеш — слави чи знань? А може, і того, і того?",
        objectives = "Пройди 5 підземель мандрів у часі.",
        completion = "От ти й поверну$p(вся:лася) нарешті — з перемогою за плечима чи, може, з уроками, глибшими за ті, що їх можна знайти у вирі битви?",
    },
    [93628] = {
        title = "Затінений шлях крізь час",
        description = "Чи повернешся ти в царство смерті, ризикуючи самим своїм існуванням? Переродження, вічний спокій, нескінченні муки? Усе це можна знайти за завісою.\n\nВирушай до Темних земель ще раз. Якщо здолаєш їхні найнебезпечніші місця, можливо, повернешся до живих мудрішим і могутнішим.",
        objectives = "Пройди 5 підземель Мандрівки в часі.",
        completion = "Сміливо ступити в землі потойбіччя й вийти з іншого боку... воістину Ходок Пащі — до самих кісток.",
    },
    [93640] = {
        title = "Риболовні хитрощі",
        description = "Я хотів принести цей чайний сервіз додому, щоб зробити дружині сюрприз...\n\nАле це не загладить того, що я не принесу додому риби на вечерю.\n\nГм. Пропоную угоду, {class}. Я цілий день тут стою, намагаючись наловити риби, щоб моя красуня-дружина приготувала нам вечерю. Але краби раз у раз крадуть мій улов — і наживку теж! Прожени їх, щоб я зміг наловити риби й зберегти улов, а я віддам тобі цей чайничок.",
    },
    [93641] = {
        title = "Усупереч усьому",
        description = "Друзі, я відчуваю там негаразди. Там є вороги, що плекають злобу й шукають бою. Гуртуйся з іншими й покажи тим, хто рветься в бій, чия сила.",
        objectives = "Вбий 25 бійців Орди 90-го рівня будь-де в межах Опівночі.",
    },
    [93642] = {
        title = "Усупереч усьому",
        description = "Друзі, я відчуваю там негаразди. Там є вороги, що плекають злобу й шукають бою. Гуртуйся з іншими й покажи тим, хто рветься в бій, чия сила.",
        objectives = "Вбий 25 бійців Альянсу 90-го рівня будь-де в межах Опівночі.",
    },
    [93647] = {
        title = "Деревина для тебе",
        completion = "Схоже, ти з тих, хто міг би опанувати мистецтво лісоруба!\n\nЯ швиденько навчу тебе розрізняти, які дерева найкраще годяться на деревину.\n\nДеревина стане в пригоді для всякої всячини, коли майструєш щось для свого дому. Або для чужих домів, якщо схочеш продавати свої вироби. До речі, варто б навідатися до давніх учителів ремесла та освіжити знання. Закладаюся, вони мають чого нового навчити!\n\nТож набери, що зможеш, і подивися, що з того вдасться змайструвати!",
    },
    [93651] = {
        title = "Сліпуча долина: коріння Світлоцвіту",
        description = "Ми простежили втечу Руї кореневими шляхами. Як ми й підозрювали, він знайшов прихисток у глибині Сліпучої долини — там, де Світлоцвіт уперше вкорінився в Гарандарі.\n\nПоки пил Альну посилює нашу владу над життям, ми здатні стримувати неконтрольоване розповзання Світлоцвіту. Але пил Альну скінчиться задовго до того, як у Руї скінчиться терпець.\n\nРуя мудрий і могутній. Але його дії в Лісі Вічної Пісні доводять: його переконаність переросла в некерований фанатизм. Його треба зупинити.",
        objectives = "Пройди підземелля Сліпуча долина.",
        progress = "Руя надто могутній, щоб кидати йому виклик наодинці. Хтозна, які розрослі чудовиська чигають у серці Світлоцвіту?",
        completion = "Отже, справу зроблено.\n\nЗагибель Руї — трагедія. Тобі не випало знати його таким, але колись він був утіленням честі й переконань. Подумати лишень, що Світло так цілковито засліпило його перед безумством власних амбіцій...\n\nЗрештою, він вірив, що чинить якнайкраще для Гарандару. Мені лишається сподіватися, що його душа знайде і спокій, і прощення, шукаючи по смерті Альн'гару.",
    },
    [93667] = {
        title = "Табір Стоунвош",
        description = "Ти не перша дивовижа, яку я сьогодні бачу.\n\n<Розвідниця Зел'канра хитає головою.>\n\nБачила велику панцирну істоту на стежці до Джан'Алору. Амаксі з купкою розвідників подалися за нею навздогін.\n\nЇх давненько немає. Може, глянеш, як вони там?",
        objectives = "Знайди Амаксі за межами табору Стоунвош у Зул'Амані.",
        completion = "Хто ти? Що ти тут робиш?\n\n<Амаксі напружується, але за мить розслабляється.>\n\nТебе прислала Шейдбейсін. Так, у нас усе гаразд. Але цим тортолланам тут не місце!",
    },
    [93668] = {
        title = "Стара гра для нової доби",
        description = "Вітаю, {class}. Чи чув ти про мою спільну справу з Етасом Сонцехапом і Ауриком Сонцеловом? Ми намагаємося відродити цікавість до старовинного арканного турніру, де змагаються прихованість і пильність, — він зветься Декоративний двобій.\n\nЗараз ми навчаємо нових гравців, тож якщо хочеш опанувати основи гри, приходь до нас у тренувальну зону Декоративного двобою, одразу на захід звідси.",
    },
    [93683] = {
        title = "Conditional Objectives - Singular",
        description = "{name}! Радий тебе бачити. Захисникам фортеці не завадила б твоя допомога.\n\nОдна з ґномів збудувала робота, щоб допомогти боронити твердиню. Та щоразу, коли його вмикають, він шаленіє.\n\nЇй потрібен хтось, хто зможе як слід зірвати атаки робота, щоб його можна було полагодити.\n\nЧи маєш хвильку, щоб допомогти?",
        objectives = "Активуй Бійцебота 11.2.7, а тоді 1 раз перервай його здібності своїм вартовим Скверни або гончаком Скверни.",
    },
    [93687] = {
        title = "Скуштуй справжню могутність",
        completion = "Видовище, гідне подиву, чи не так?\n\nІз часів Дат'Ремара ельфи кують у цій великій кузні обладунки незрівнянної моці. Кажуть, що це полум'я вперше роздмухала душа фенікса, який визнав кузню гідним гніздом, і що його сила досі вплітається в кожне творіння.\n\nМи дозволимо тобі розділити її дари.",
    },
    [93690] = {
        title = "Потрібні послуги алхіміка",
        description = "З поверненням, {class}. Якщо ти й досі хочеш співпрацювати з Консорціумом ремісників, ми будемо вдячні за твою допомогу. Нам потрібні вправні майстри, щоб виготовляти припаси для воєнних потреб.\n\nЯкщо твоя робота відповідає високим стандартам якості Сільвермуна, виконуй будь-які публічні ремісничі замовлення з дошки. Ти також можеш виконувати замовлення для себе, для побратимів з гільдії чи для приватних замовників.\n\nПринеси мені підтвердження виконаних замовлень, і я подбаю, щоб ти отрима$p(в:ла) належну винагороду.",
        objectives = "Виконуй ремісничі замовлення з алхімії для Консорціуму ремісників.",
        progress = "Принеси мені підтвердження виконаних замовлень, і я подбаю, щоб ти отрима$p(в:ла) належну винагороду.",
        completion = "Прийми нашу вдячність, друїде. Завдяки твоїй вправності Сільвермун стає міцнішим.",
    },
    [93691] = {
