    [93697] = {
        title = "Мерехтливі мелодії",
        description = "Чуєш? Це магія Лісу Вічної Пісні. Якщо добре прислухатися, вона випромінює ледь вловну мелодію. Складно переплетені нитки магії труться одна об одну, творячи чудову гармонію.\n\nПил, що його дистилюють із такої магії, — надзвичайно потужний. Принеси мені трохи, і я покажу тобі, до чого він придатний.",
        objectives = "Назбирай 20 вічноспівного пилу й достав його Долотосу в Сільвермун.",
        progress = "Пил уже зібрано?",
        completion = "Цей пил — виняткової якості! Ходімо, покажу тобі кілька технік, у яких він стане в пригоді.",
    },
    [93698] = {
        title = "Розколоте сяйво",
        description = "Якщо вловити слушну мить, силу, що струменить із предмета, можна кристалізувати у скалки чистої магічної енергії. Результат сліпить очі — немов сонячні промені, що розщеплюються, линучи крізь вікно.\n\nПринеси мені кілька таких скалок. Без них моя робота не зрушить з місця.",
        objectives = "Збери 10 Сяйливих скалок і віднеси їх Долотосу в Сільвермуні.",
        progress = "Кількох скалок має вистачити.",
        completion = "О, вони сяють такою чудовою силою! Ці чудово підійдуть.",
    },
    [93699] = {
        title = "Промінь сонця",
        description = "У світанку — велика магія. Він осяває й пробуджує все, на що падає, спонукаючи землю до дії. Це потенціал у найчистішому вигляді.\n\nМи, майстри накладання чарів, вміємо кристалізувати цей потенціал. Принеси мені часточку світанку.",
        objectives = "Збери 1 Світанковий Кристал і віднеси його Долотосу в Сільвермун.",
        progress = "Тобі вдалося?",
        completion = "З цього вийде чимало чудових і могутніх чарів.",
    },
    [93700] = {
        title = "Відчуй спокій",
        description = "Ти знаєшся на травництві? Ох, яке щастя.\n\nМені знадобилася просто шалена кількість цвіту спокою. Замовлення від алхіміків усе накопичуються, а я щойно скінчила поповнювати запаси срібнолиста і—\n\n<Натера спиняється, щоб глибоко вдихнути.>\n\nБудь ласка, принеси мені стільки цвіту спокою, скільки зможеш донести. Я буду перед тобою в боргу.",
        objectives = "Збери 20 квітів спокою й віднеси їх ботанікові Натері в Сільвермуні.",
        progress = "Знайшлися якісь квіти спокою?",
        completion = "Благословенний будь. Це дасть мені трохи зайвого часу, щоб надолужити замовлення.",
    },
    [93701] = {
        title = "Крихке й блискуче",
        description = "Щойно насувається війна, срібнолист одразу йде нарозхват.\n\nВисушений, він буквально розсипається на порох, але той порошок годиться для безлічі ліків: заспокоює нерви, прояснює думки, а в скруті може послужити навіть легким знеболювальним.\n\nЯкщо натрапиш на срібнолист у своїх мандрах — принеси його мені, будь ласка.",
        objectives = "Збери 20 Срібнолисту й віднеси його ботаніку Натері в Сільвермун.",
        progress = "Срібнолист, правду кажучи, росте як бур'ян. Знайдеш його вдосталь.",
        completion = "Я одразу ж повішу ці пучки сушитися. Дякую.",
    },
    [93702] = {
        title = "Корінь життя",
        description = "Майже кожен бульбистий корінь має якісь цілющі властивості, але азекорінь — безперечно найсильніший і найуніверсальніший з усіх.\n\nДрібка його соку чи порошку спиняє зараження, загоює рани та заспокоює тіло й розум. Мені траплялося бачити, як ним навіть деревину від гниття берегли!\n\nПринеси мені кілька кошиків — я знайду їм добрий ужиток.",
        objectives = "Збери 3 Азекореня і віддай їх ботаніку Натері в Сільвермуні.",
        progress = "Тобі вдалося роздобути азекоріння?",
        completion = "О, я обожнюю аромат свіжого азекореня. Можливо, варто спробувати, як він поведеться в парфумах...",
    },
    [93703] = {
        title = "Слабкості сін'дорей",
        description = "Хоч більшість нашого врожаю йде писарям та алхімікам міста, час від часу ми отримуємо замовлення й від приватних осіб.\n\nЛорд Салтеріл — один із наших найзавзятіших покупців. Він має маєток на заході Лісу Вічної Пісні й дбає, щоб гостям на його вечірках ніколи нічого не бракувало.\n\nЦього тижня він замовив чималу партію лілей мани та кровотерну. Допоможеш нам виконати замовлення?",
        objectives = "Збери 5 лілей мани та 2 кровотерни й достав їх ботаніці Натері в Сільвермун.",
        progress = "Замовлення лорда Салтеріла завжди до речі, хай він і трохи дивак.",
        completion = "Чудово. З твоєю допомогою та з нашими запасами цього має вистачити на його замовлення.",
    },
    [93704] = {
        title = "Традиційні врожаї",
        description = "Цвіт спокою і срібнолист — основа незліченних зіль, еліксирів, чорнил і багато чого іншого.\n\nЗайвий запас ніколи не завадить. Тож якщо матимеш трохи понад потребу — ми радо заберемо його в тебе.",
        objectives = "Збери 10 цвітів спокою та 5 срібнолистів і достав їх ботаніці Натері в Сільвермун.",
        progress = "Ми візьмемо все, що ти можеш запропонувати.",
        completion = "Іноді проста суміш — найкраща суміш. Немає ганьби в тому, щоб триматися основ.",
    },
    [93705] = {
        title = "Мідяк за твої думки?",
        description = "На тлі показніших матеріалів мідь легко недооцінити, але це надзвичайно надійний і універсальний метал. Зброя, обладунки, дроти, прикраси і, звісно, скромний мідяк — вона годиться на все!\n\nТож не дивно, що мідь завжди в попиті — і в місті, й далеко за його межами. Якщо трапиться зайва руда, охоче заберу її в тебе.",
        objectives = "Збери 20 сяйливої мідної руди й достав її Белілу в Сільвермуні.",
        progress = "Знаєш, я написав дисертацію про застосування міді. Ти її читав?",
        completion = "Це навіть більше, ніж я очікував! Чудово. Я негайно подбаю, щоб це пішло в діло.",
    },
    [93706] = {
        title = "Гарячі голови, м'яке олово",
        description = "Останнім часом до нас ринули новобранці. З них ростуть чудові бійці, та завзяття в них поки що більше, ніж вправності. Запас тренувальної зброї вони вже добряче потріпали.\n\nТренувальну зброю ми зазвичай робимо з олова чи інших м'яких металів: так новобранці не завдають справжньої шкоди ані манекенам, ані одне одному. От тільки довго така зброя не живе.\n\nЩоб устигати за ними, нам знадобиться значно більше олова, ніж є на складі. Принеси нам ще!",
        objectives = "Збери 10 шматків Тіньової Олов'яної Руди й достав їх Белілу в Сільвермун.",
        progress = "Будемо вдячні за будь-який внесок.",
        completion = "Чудово! З цього вийде добрячий набір зброї.\n\nПевен, нове замовлення не забариться, тож тримай трохи олова про запас.",
    },
    [93707] = {
        title = "Недарма він Сільвермун",
        description = "Сін'дорей, може, й полюбляють вишукану золоту філігрань, але наше місто пишається й одними з найкращих срібних справ майстрів в усьому Азероті.\n\nВідколи через місто проходить стільки нових гостей, замовлень у них хоч греблю гати. Якщо натрапиш на якісне срібло — вони знайдуть йому добрий ужиток.",
        objectives = "Збери 10 сяйливої срібної руди й віднеси її Белілу в Сільвермуні.",
        progress = "Правду кажучи, срібло і мені припадає до душі.",
        completion = "Яка неперевершена якість! Негайно відправлю це ювелірам. Дякую тобі.",
    },
    [93708] = {
        title = "Провідні метали",
        description = "Наші арканні конструкти можуть здаватися суто магічними, але під їхньою поверхнею ховається чимало хитромудрої проводки. Інженери Сільвермуна — по-своєму справжні чаротворці.\n\nОстаннім часом вони нарощують виробництво, щоб зміцнити нашу оборону, а по матеріали, звісно, звертаються до нас. Більшість замовленого в мене є, та бракує олова і срібла.\n\nДопоможеш мені виконати замовлення?",
        objectives = "Збери 5 шматків Тіньової Олов'яної Руди та 5 шматків Блискучої Срібної Руди й достав їх Белілу в Сільвермун.",
        progress = "Олово і срібло — напрочуд добрі провідники. Можу розповісти докладніше... якщо маєш кілька вільних годин?",
        completion = "О, так. Такої кількості має вистачити. Звелю запакувати це для інженерів.",
    },
    [93709] = {
        title = "Запаси найнеобхіднішого",
        description = "Міді й торію ніколи не буває забагато. Навіть з усіма новими шахтарями, яких ми найняли, наші запаси щотижня майже вичерпуються.\n\nТакими темпами доведеться налагоджувати імпорт, а морока з паперами, яку він тягне за собою, мені геть не потрібна.\n\nЯкщо допоможеш поповнити запаси міді й торію — буду в боргу.",
        objectives = "Збери 10 шматків Осяйної Мідної Руди та 2 шматки Сліпучого Торію й достав їх Белілу в Сільвермун.",
        progress = "Ну, можна було б узяти ще кількох підмайстрів, якщо доведеться...",
        completion = "Ти — з найнадійніших шахтарів, яких мені випадала честь знати.\n\nДякую. Щиро.",
    },
    [93710] = {
        title = "Загартована темрявою",
        description = "Звірі Кель'Таласу дають шкіру неперевершеної якості, але Порожнеча коїть із нею щось дивне.\n\nЗазвичай ми гартуємо шкіру, нагріваючи її за особливих умов. Але темрява, що в'їлася в ці шкури, схоже, гартує їх сама собою. Гадки не маю, як таке можливо, але скористатися цим ми можемо.\n\nПринеси мені стільки, скільки збереш. Нам ще ціле військо споряджати.",
        objectives = "Збери 20 Загартованої Порожнечею Шкіри й віднеси її Тину в Сільвермун.",
        progress = "Ми знайдемо вжиток будь-якій шкірі, яку ти нам принесеш.",
        completion = "Які дивні властивості... Зразок я залишу для вивчення. А тим часом із цієї шкіри вийде чудова броня для наших далекоходів.",
    },
    [93711] = {
        title = "Холод Порожнечі",
        description = "Коли багато років тому ми вирушали з військами до Нортренду, наших солдатів довелося споряджати так, щоб вони витримали крижаний холод мерзлих пустищ. Секрет простий: обладунок зсередини вистилають хутром і надійно закріплюють його пластинами, щоб тепло не втікало.\n\nТі методи ми свого часу ретельно записали. Порожнеча, може, й не така холодна, як Нортренд, але я волію готуватися до найгіршого.\n\nПринеси мені хутра та пластин — і винагороджу сповна.",
        objectives = "Збери 5 Фантастичного хутра та 2 Загартовані Порожнечею пластини й віддай їх Тину в Сільвермуні.",
        progress = "Додаткова перевага: хутро ще й добряче рятує від натирання.",
        completion = "Наші чинбарі зуміють дати раду цим матеріалам. Гарна робота.",
    },
    [93712] = {
        title = "Стиль і майстерність",
        description = "У бою вигляд важить майже стільки ж, скільки й чиста майстерність. Якщо зумієш налякати ворога ще до того, як оголиш меч, — ти вже на пів кроку ближче до перемоги.\n\nНаші майстри стріл пішли ще далі: вони запевняють, що з гарним пір'ям стріли далекоходів завдають більшої шкоди. Мене це... не надто переконує, але красу я ціную.\n\nОсь список того, що їм потрібно для цьоготижневої партії стріл. Принеси, що зможеш, а про решту подбаю я.",
        objectives = "Збери 5 Гострих іклів і 5 Незрівнянного оперення та віднеси Тину в Сільвермун.",
        progress = "Можеш не зважати на примітку про те, чи мають пера бути багряними чи ясно-червоними.",
        completion = "О, з цього вийдуть чудові стріли.",
    },
    [93713] = {
        title = "Необхідні матеріали",
        description = "Ординська любов до зубів та звіриних шкур передалася й декому із сін'дорей. Останніми роками гуртові замовлення і на те, й на інше — не рідкість.\n\nСаме зараз такий випадок. Якщо маєш зайві шкури або на полюванні трапляться особливо гострі зуби — охоче їх у тебе виміняю.",
        objectives = "Збери 5 Різьбильних іклів і 2 Гартовані Порожнечею шкури та віднеси їх Тину в Сільвермуні.",
        progress = "Ніколи мені не збагнути орчої моди.",
        completion = "Що ж, цього має вистачити, щоб покрити останнє замовлення. Спробую поповнити запаси, готуючись до наступного.\n\nПриємно було мати з тобою справу.",
    },
    [93714] = {
        title = "Мінорна луска",
        description = "Добре зроблений лускатий обладунок — справжня окраса. Така робота вимагає неабиякого терпіння й уваги до найдрібніших деталей, але шкіряники Сільвермуна — майстри своєї справи.\n\nЯкщо полюватимеш на лускатих звірів, ці матеріали нам згодяться. І якщо можна — побільше дрібнішої луски: вона краще лягає шарами в обладунку.",
        objectives = "Збери 20 Загартованих Порожнечею Лусок і достав їх Тіну в Сільвермун.",
        progress = "Луску дістати трохи важче, ніж звичайну шкіру, але результат вартий того сповна.",
        completion = "О, які чудові. Тільки поглянь, як міняться барвами! Негайно ж їх відішлю.",
    },
    [93716] = {
        title = "Опанування маскування — частина 1",
        description = "У грі «Декор-дуель» одна сторона за допомогою ілюзій перевтілюється на звичайні предмети довкола і ховається серед них.\n\nІнша сторона користується затвердженим набором здібностей, що пронизують ілюзії, аби відшукати й упіймати тих, хто ховається під личиною.\n\nНаприкінці раунду команди міняються ролями, тож кожна сторона має нагоду і поховатися, і пошукати.\n\nЧас спробувати тобі! Це крісло зачаровано, щоб вкрити тебе своєю личиною. Прибери його подобу, а тоді кілька разів зміни своє маскування.",
        progress = "Торкнися цього крісла, щоб прибрати його подобу...",
    },
    [93717] = {
        title = "Опанування маскування — частина 2",
        description = "Замаскувавшись, ти зможеш магічно переноситися до іншого предмета декору поблизу.\n\nПрибери знову подобу крісла й цього разу спробуй кілька разів змінити своє розташування. За бажання можеш міняти маскування між переміщеннями.",
        progress = "Скористайся кріслом маскування, щоб мінятися місцями з іншим декором, а тоді повернися до мене.",
    },
    [93719] = {
        title = "Хто не ловить, той не виграє",
        description = "У Дуелі декору є три класи Шукачів, але всі починають із набору Руйнівника чарів. Не хвилюйся — доступ до решти ти ще заслужиш.\n\nКілька основ: щит ілюзії перевдягненого хованця можна зруйнувати за допомогою «Розвіювання магії». Щойно хованця буде позначено як знайденого, ти матимеш коротку мить, щоб його зловити й вибити з гри.\n\nМою статую зачаровано, щоб спорядити тебе набором Руйнівника чарів. Споряджений, користуйся «Розвіюванням магії», щоб знаходити й ловити приманки, що поховалися довкола.",
        objectives = "Торкнися статуї, щоб отримати Набір приборкувача чар, скористайся Фокусом розвіювання, щоб «знайти» тих, хто ховається, а тоді «познач» їх.",
        progress = "Скористайся моєю статуєю, тоді знаходь і мить тих, хто ховається, за допомогою Розвіювання магії та Помітки Руйнівника чарів.",
        completion = "Непогано як на перший раз. У тебе це виходить цілком природно!",
    },
    [93723] = {
        title = "Потрібні ремісники",
        description = "Вітаю. Хочеш докласти рук?\n\nВійна тяжко б'є по ресурсах Сільвермуна. Наші солдати мають бути озброєні та споряджені, але навіть досвідчені ремісники вже не дають ради. Щоб устигати за попитом, ми уклали угоду з Консорціумом Ремісників.\n\nЯкщо маєш власні вміння — поговори з Мар'ною. Вона допоможе тобі переглядати й розміщувати ремісничі замовлення.",
        objectives = "Поговори з Мар'ною на Базарі.",
        progress = "Чи вдалося поговорити з Мар'ною?",
        completion = "Виконання цих ремісничих замовлень конче важливе для воєнних зусиль. Ми щиро вдячні за твої послуги.",
    },
    [93724] = {
        title = "Ремісничі замовлення: алхімія",
        description = "О, то ти алхімік?\n\nТоді тобі варто поговорити з Камбероном. Він вправний алхімік і тримає крамницю тут, у Сільвермуні.\n\nУ його крамниці є робочий стіл, де можна переглядати, виконувати й доставляти замовлення — як із публічних списків, так і від особистих знайомих: друзів чи товаришів по гільдії. А як пощастить, натрапиш і на особливе замовлення від когось славнозвісного.\n\nРозшукай його й подивися, яка робота на тебе чекає.",
        objectives = "Знайди Камберона на Базарі та скористайся його алхімічним робочим столом.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "Зустріти колегу-алхіміка — завжди честь. Прибирай за собою розлите — і ми неодмінно заприятелюємо.",
    },
    [93726] = {
        title = "Ремісничі замовлення: ковальство",
        description = "О, то ти коваль?\n\nТоді тобі варто поговорити з Бемарріном. Він вправний коваль і тримає крамницю тут, у Сільвермуні.\n\nУ його крамниці є робочий стіл, де можна переглядати, виконувати й доставляти замовлення — як із публічних списків, так і від особистих знайомих: друзів чи товаришів по гільдії. А як пощастить, натрапиш і на особливе замовлення від когось славнозвісного.\n\nРозшукай його й подивися, яка робота на тебе чекає.",
        objectives = "Знайди Бемарріна на Базарі та скористайся його ковальським столом.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "Приємно познайомитися. Але якщо кудись занесеш мої добрі обценьки — вилетиш звідси вмить.",
    },
    [93727] = {
        title = "Ремісничі замовлення: інженерія",
        description = "О, то ти $p(інженер:інженерка)?\n\nТобі варто поговорити з Данве. Вона вправна інженерка й тримає майстерню тут, у Сільвермуні.\n\nУ її майстерні є робочий стіл, де можна переглядати, виконувати й здавати замовлення — як із публічних списків, так і від особистих знайомих, як-от друзів чи товаришів по гільдії. Якщо пощастить, натрапиш і на замовлення від знаної особи з особливою винагородою.\n\nЗнайди її та дізнайся, яка робота на тебе чекає.",
        objectives = "Знайди Данве на Базарі та скористайся її інженерним верстаком.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "Добрих інженерів удень з вогнем не знайдеш. Дай раду тим арканним конструктам — і потонеш у замовленнях від самих лише Магістрів.",
    },
    [93728] = {
        title = "Ремісничі замовлення: письменство",
        description = "О, то ти $p(писар:писарка)?\n\nТобі варто поговорити із Зантасією. Вона вправна писарка й тримає майстерню тут, у Сільвермуні.\n\nУ її майстерні є робочий стіл, де можна переглядати, виконувати й здавати замовлення — як із публічних списків, так і від особистих знайомих, як-от друзів чи товаришів по гільдії. Якщо пощастить, натрапиш і на замовлення від знаної особи з особливою винагородою.\n\nЗнайди її та дізнайся, яка робота на тебе чекає.",
        objectives = "Знайди Зантасію на Базарі та скористайся її писарським столом.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "У тебе тонка і тверда рука, {NAME}. Кортить побачити, що ти створиш.",
    },
    [93729] = {
        title = "Ремісничі замовлення: ювелірство",
        description = "О, то ти $p(ювелір:ювелірка)?\n\nТобі варто поговорити з Аміном. Він вправний ювелір і тримає майстерню тут, у Сільвермуні.\n\nУ його майстерні є робочий стіл, де можна переглядати, виконувати й здавати замовлення — як із публічних списків, так і від особистих знайомих, як-от друзів чи товаришів по гільдії. Якщо пощастить, натрапиш і на замовлення від знаної особи з особливою винагородою.\n\nЗнайди його та дізнайся, яка робота на тебе чекає.",
        objectives = "Знайди Аміна на Базарі та скористайся його ювелірним верстаком.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "Здається, нині до кожного обладунку треба інкрустувати з дюжину самоцвітів. Не те щоб я нарікав — надто тепер, коли твоя допомога скорочує чергу замовлень.",
    },
    [93730] = {
        title = "Ремісничі замовлення: кравецтво",
        description = "О, то ти $p(кравець:кравчиня)?\n\nТобі варто поговорити з Ґаланою. Вона вправна кравчиня й тримає майстерню тут, у Сільвермуні.\n\nУ її майстерні є робочий стіл, де можна переглядати, виконувати й здавати замовлення — як із публічних списків, так і від особистих знайомих, як-от друзів чи товаришів по гільдії. Якщо пощастить, натрапиш і на замовлення від знаної особи з особливою винагородою.\n\nЗнайди її та дізнайся, яка робота на тебе чекає.",
        objectives = "Знайди Ґалану на Базарі та скористайся її кравецьким столом.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "Вишукані чаротворці вимагають вишуканих шат, але їхні високі вимоги тримають нашу майстерність гострою. Може, обміняємося прийомами?",
    },
    [93731] = {
        title = "Ремісничі замовлення: шкіряна справа",
        description = "О, то ти $p(майстер:майстриня) шкіряної справи?\n\nТобі варто поговорити з Талмаром. Він вправний шкіряник і тримає майстерню тут, у Сільвермуні.\n\nУ його майстерні є робочий стіл, де можна переглядати, виконувати й здавати замовлення — як із публічних списків, так і від особистих знайомих, як-от друзів чи товаришів по гільдії. Якщо пощастить, натрапиш і на замовлення від знаної особи з особливою винагородою.\n\nЗнайди його та дізнайся, яка робота на тебе чекає.",
        objectives = "Знайди Талмара на Базарі та скористайся його шкіряницьким верстаком.",
        progress = "Замовлення накопичуються без упину. Зайва пара рук мені не завадить.",
        completion = "У звірів Кель'Таласу — найкраща шкіра, з якою тобі коли-небудь доведеться працювати. Кортить побачити, що ти з неї створиш.",
    },
    [93734] = {
        title = "Дорогоцінні цяцьки",
        description = "Нарешті побачимо, які скарби наскладав Ґроффа.\n\n<Очі Фурґа чорніють, щойно він дивиться на торбу. Слина на його щелепах збивається в піну, а кігті дедалі міцніше впиваються в боки торби.>\n\nМоже, дарунки речника лоа не такі вже й погані. Не варто поспішати. Я зазирну всередину. А ти пильнуй і охороняй мене.",
        objectives = "Захищай Фурґа й дослідь скарби.",
        progress = "Хай що там було в Ґроффи — це щось лихе. Правда ж?",
        completion = "Не треба було палити мої речі...",
    },
    [93744] = {
        title = "Єдність проти Порожнечі",
    },
    [93745] = {
        title = "Гар'атір, селище пам'яті",
        description = "Тобі дозволили вільно ходити під світлом нашої Богині. Та це ще не означає, що ми довіряємо тобі беззастережно.\n\nЯкщо хочеш довести гаранірам свою дружбу — стань у пригоді в Гар'атірі. Саме там ми готуємо фарби для наших настінних розписів і доглядаємо наймолодші корені, що тягнуться до світла Богині.",
        objectives = "Зустрінься з вартовим коренів Ку'паалом у Гар'атірі.",
        completion = "Отже, зустріч зі старійшинами вдалося пережити. Це дивує — але й тішить.\n\nТи без вагань допомагаєш дітям Гар'атіра. За це я вітаю тебе й пропоную тобі гостинність коренів Амірдрассіла.",
    },
    [93751] = {
        title = "Шпиль Віндраннерів",
        description = "Колишня домівка Віндраннерів... нині осквернена так, що годі й уявити. Від часів навали Погибелі шпиль став притулком наших найстрашніших жахіть: банші, гидот, сповнених ненависті духів.\n\nТакому місцю вже немає порятунку, але, можливо, ми допоможемо змученим душам знайти спочинок.",
        objectives = "Пройди підземелля «Шпиль Віндраннерів» на будь-якій складності.",
        completion = "Мої здогади справдилися... у шпилі криється більше, ніж самі лише рештки Погибелі. Він — дзеркало трагедій, що спіткали родину Віндраннерів.",
    },
    [93752] = {
        title = "Завулок Убивць",
        description = "Ми з Лор'темаром ніколи не сходилися в поглядах щодо існування Завулка Убивць. Та, мабуть, місто, як і ліс, повинно мати свої таємниці — і матиме їх.\n\nУтім, останнім часом Лор'темар занепокоєний зростанням активності Скверни в цьому районі. Поки більшість варти Сільвермуна зосереджена на Войдштормі, багато хто випробовує межі дозволеного, користається нагодою, тягнеться до влади...\n\nДаю тобі дозвіл розслідувати будь-яку таку незаконну діяльність — і класти їй край.",
        objectives = "Пройди підземелля «Завулок Убивць» на будь-якій складності.",
        progress = "Звіти про діяльність Скверни надходять щодня. Боюся, Сільвермун у небезпеці. Сподіваюся, ти візьмешся за справу..",
        completion = "Чудова робота — зірвати таку масштабну операцію!\n\nЛор'темару відляже від серця. Можливо, це спонукає його запровадити суворіші порядки в Завулку Убивць.",
    },
    [93753] = {
        title = "Тераса магістрів",
        description = "Могутні монстри Порожнечі захопили Терасу магістрів! У цих залах зберігаються незліченні знання й арканна могуть. Ми не можемо віддати ворогові ані крихти.\n\nЗачисти поріддя Порожнечі та їхніх повелителів. Імовірно, доведеться також розібратися із захисними системами тераси — вони створені, щоб за всяку ціну не допускати стороннього доступу й переривати його.",
        objectives = "Пройди підземелля Тераса магістрів на будь-якій складності.",
        progress = "Якщо Порожнеча дістанеться найдобірнішого сховища магії Сільвермуна... Роммат влаштує істерику епічних масштабів.",
        completion = "Ледве обійшлося. А щодо Роммата з Умбриком — це вже загадка на інший день.",
    },
    [93754] = {
        title = "Печери Майсари",
        description = "Коли леді Ліадрін була в Зул'Амані, вона звернула увагу на одне плем'я — Лихогіллих, що чинили розправу над іншими лісовими тролями та їхніми лоа. Свою назву вони цілком виправдовують, безоглядно вдаючись до некромантії.\n\nУвійди до їхніх печер і поклади край їхній чорній магії!",
        objectives = "Пройди підземелля Печери Майсари на будь-якій складності.",
        progress = "Магія Лихогіллих аж тхне вченнями нежиті... а я знаю: це ніколи не закінчується добре.",
        completion = "Хто б міг подумати, що рятувати тролів буде так приємно. Хай Візербарки не забудуть цього вчинку.",
    },
    [93755] = {
        title = "Лігво Налоракка",
        description = "Випробування вправності й сили... Шкода, що справи тримають мене в Сільвермуні.\n\nЩасти, чемпіон$p(е:ко). З нетерпінням чекаю розповіді про твою перемогу над лоа війни амані.",
        objectives = "Пройди підземелля Лігво Налоракка на будь-якій складності.",
        progress = "Не здрейфи$p(в:ла), га? Нічого, твій страх небезпідставний. Ведмеді — королі природи. Вони тобі дадуть чосу.",
        completion = "Неймовірний подвиг. Прийми мою повагу, чемпіон$p(е:ко).",
    },
    [93756] = {
        title = "Сліпуча долина",
        description = "Це місце — епіцентр Світлоцвіту в Гарандарі. Орвейна зробила все, що могла, — а могла вона чимало, — та щоб рослина загинула, треба вдарити по стрижневому корені всіх коренів.\n\nБудь насторожі, навіть якщо гадаєш, що вже добре знаєш Світлоцвіт. Долина не схожа на буйні, але зрештою дикі зарості в Лісі Вічної Пісні. Це виважена сила природи на чолі з вартовим коренів, що прагне задушити тебе й усе інше, чого забажає.",
        objectives = "Пройди підземелля Сліпуча долина на будь-якій складності.",
        progress = "Дізнайся все, що зможеш, від Світлоцвіту в Лісі Вічної Пісні, але стережися: тут може чекати геть інший клубок проблем. Вартовий коренів виглядатиме таких непроханих гостей, як ти.",
        completion = "Чи означає ця перемога смерть Світлоцвіту? Покаже лише час. Але, як підказує мій досвід, життя завжди знаходить шлях.",
    },
    [93757] = {
        title = "Арена Шраму Порожнечі",
        description = "Доманаари жадають битви — і всього болю та розбрату, що йдуть із нею в парі. Якби не це, все тут скидалося б на пастку. А втім, так чи інак це запрошення накласти головою.\n\nЯкщо вже так кортить узяти участь у бойових іграх Порожнечі — зупиняти тебе не стану. Тільки не соромся знищити там якомога більше поріддя Порожнечі, гаразд?",
        objectives = "Пройди підземелля Арена Шраму Порожнечі на будь-якій складності.",
        progress = "Нехай твої стріли влучають у ціль, $p(чемпіоне:чемпіонко).",
        completion = "Усіх переможено! Чудова робота, $p(чемпіоне:чемпіонко). Може, наступного разу і я запишуся! Схоже, там було весело.",
    },
    [93758] = {
        title = "Вузлова Точка Ксенас",
        description = "Ми мусимо й далі пильнувати цей переповнений силою об'єкт. Якщо станеться прорив, лихо розповзеться далеко за межі Войдшторму. На жаль, цей магічно-механічний комплекс — поза межами мого фаху.\n\nПідготуйся як слід і подбай, щоб Вузлова Точка Ксенас лишалася в сплячці.",
        objectives = "Пройди підземелля Вузлова Точка Ксенас на будь-якій складності.",
        progress = "Якщо Вузлову Точку перевантажать, багатьох чекає дуже швидка смерть.\n\nНе розвиваймо цю думку далі. Убезпеч об'єкт!",
        completion = "Швидка робота, $p(чемпіоне:чемпіонко). Схоже, планові огляди доведеться проводити й далі, але наразі можна перепочити.",
    },
    [93766] = {
        title = "Опівніч: Світові завдання",
        description = "Порожнеча прагне роз'єднати нас, вбити клин між родом і королівством. Ми не можемо цього допустити.\n\nКуди не повернуся, всюди чую про тих, хто потерпає: вигнані з домівок родини, виснажені захисники, знесилені цілителі. Ні клинок, ні закляття поодинці не переломлять цю хвилю, а от сила багатьох сердець, об'єднаних разом, — здатна.\n\nРушай і подай свою допомогу там, де вона найпотрібніша.",
        objectives = "Виконай світові завдання в Опівночі.",
        progress = "З твоєю допомогою ми зможемо ще міцніше згуртувати весь наш народ.",
