    [93769] = {
        title = "Опівніч: Житло",
        description = "Міцну спільноту будують не мури, а руки й серця тих, хто в ній живе.\n\nПодаруй сусідству свій голос, свій час і свій дух. Допомагай ближнім, розділяй їхні тягарі й посядь своє місце як діяльна частина дому, який ми зводимо разом.",
        objectives = "Бери участь в ініціативах сусідства та збирай Купони спільноти.",
        progress = "Кожні руки в пригоді. Подивися, що ще можна зробити.",
        completion = "Ти відда$p(в:ла) своє серце. Саме це нас по-справжньому єднає.",
    },
    [93771] = {
        title = "Гар'куай, селище дощу",
        description = "Усі води Гарандара священні. Вони рівною мірою живлять і корені світу, і незліченні творіння Альн'гари. І, мабуть, немає видовища величнішого за води, що спадають із коренів дерева, званого Нордрассилом.\n\nНа півночі ти знайдеш Гар'куай. Дощі, що падають там із неба, несуть дивовижну життєву силу. Якщо хочеш побачити всі величні дива Альн'гари — мандрівка до Гар'куаю стане тобі в пригоді.",
        objectives = "Зустрінься з вартовим коренів Камарі в Гар'куаї.",
        completion = "Чутки про твої мандри дійшли й до мене, чужинцю. Я — Камарі, вартовий коренів Нордрассила.\n\nТумани Гар'куаю приховують багато таємниць. Сподіваюся, гостюючи тут, ти знайдеш у них просвітлення.",
    },
    [93774] = {
        title = "Коли крісло не для сидіння?",
        description = "Етас Санрівер, Рифтклинка Маелла та Аурік Сонцелов нещодавно відродили давню арканну версію гри в хованки під назвою «Декор-дуель».\n\nВони шукають нових учасників, аби розважати ще більше людей.\n\nТобі варто зустрітися з ними на площі Соколиного Крила.",
        objectives = "Поговори з Клинком Розлому Маеллою на Соколинокрилій Площі.",
    },
    [93775] = {
        title = "Гар'мара, селище рівноваги",
        description = "О! Це ж тобі, чужинцю, Гар'мара завдячує порятунком. Звістки швидко ширяться коренями Альн'гари. Старійшина Гаґар, поза сумнівом, була вдячна за твою допомогу.\n\nВона нізащо цього не визнає, але відколи згоріли корені над її селищем, їй ведеться нелегко. Рутаані й фунґаріани дедалі зухваліші у своїх дивацтвах. А спалахи, що досі жевріють на коренях Тельдрассила, — постійна загроза.\n\nЯкщо мандри знову приведуть тебе до Гар'мари, не сумніваюся: додаткова допомога їй не завадить.",
        objectives = "Повернися до Гаґара в Гар'куаї.",
        completion = "Ах! {NAME}. З поверненням. Як бачиш, роботи в нас, як завжди, повні руки.\n\nЗапевняю, я все тримаю під контролем. Але якщо хочеш роздивитися світ трохи далі — певна, декому з інших твоя допомога не завадить.",
    },
    [93776] = {
        title = "Гар'алнор, селище сутінків",
        description = "Наші зусилля в Сліпучому Цвіті поки що спинили наступ Світлоцвіту. Але без вартового коренів Руї тут майже не лишилося тих, хто дав би раду решті клопотів селища.\n\nЯ повертаюся до Гар'алнора, щоб допомогти, чим зможу. Якщо матимеш час і бажання — твоя подальша допомога буде дуже доречною.",
        objectives = "Зустрінься з Ганнаном у Гар'алнорі.",
        completion = "Дякувати богині, що ти поверну$p(вся:лася).\n\nЯк бачиш, у нас тут досі доволі скрутне становище. Хоч ми й приборкали його поширення під корінням Шаладрассілу, Світлоцвіт лишається загрозою. Ходять чутки, що фунґаріани поводяться дивно в селищі Фунґара. До того ж у Гар'алнорі немає вартового коренів, щоб дати цьому раду.\n\nНа щастя, у нас є дещо не гірше: відважний чужинець зі звичкою допомагати іншим.",
    },
    [93782] = {
        title = "Conditional - Multiple Objectives, Sequenced",
        description = "Мене прислали сюди довести, що з мене вийде воїн амані.\n\nДля цього випробування я маю зібрати якнайбільше трофеїв з оцих корчедінів.\n\nНам варто діяти разом! А я поможу тобі здобути визнання воїна амані, га?\n\nПросто йди туди й здобудь якнайбільше трофеїв з корчедінів.\n\nА я лишуся тут — пильнуватиму тил, еге ж?",
        objectives = "Здобудь 1 трофеїв з корчедінів та їхніх союзників.",
    },
    [93783] = {
        title = "Conditional - Just One Objective",
        description = "Мене прислали сюди довести, що з мене вийде воїн амані.\n\nДля цього випробування я маю зібрати якнайбільше трофеїв з оцих корчедінів.\n\nНам варто діяти разом! А я поможу тобі здобути визнання воїна амані, га?\n\nПросто йди туди й здобудь якнайбільше трофеїв з корчедінів.\n\nА я лишуся тут — пильнуватиму тил, еге ж?",
        objectives = "Здобудь 1 трофеїв з корчедінів та їхніх союзників.",
    },
    [93784] = {
        title = "Гризотна Порожнеча цікавості",
        description = "<Артефакт розсипається в твоїй руці, лишаючи по собі лише слабкий, але виразно прадавній арканний слід. Налейдея Ріверґлім неодмінно захоче про це почути.>",
        objectives = "Повідомте про свою знахідку Налейдеї Рівергліам у Сільвермуні.",
        completion = "Надзвичайна знахідка. Арканна енергія, що струменить від твого відкриття, явно сягає часів до Розколу... Ми могли б багато чого навчитися з таких артефактів.\n\n$p(Захиснику:Захиснице)! Чудова робота! Якщо натрапиш на ще якісь під час своїх походів, прошу, принось свої знахідки мені.",
    },
    [93792] = {
        title = "Благословення лоа",
        description = "Мене звати Ду'ґал. А ти — гаш'ура.\n\nЗа наказом Кіндуру я маю навчити тебе, як шанувати лоа. Пишайся цим: мало хто з ґокіньє заслужив таке право, як ти.\n\nПоруч зі мною — Вівтар Благословень. Біля нього можеш вклонитися будь-кому з наших лоа — і на подяку отримаєш крихту сили.\n\nНу ж бо, коли твоя ласка.",
        objectives = "Ушануй лоа біля Вівтаря Благословень.\n\nОтримай благословення, поєднавши силу Акіл'зона, Галаззі, Джан'алая чи Налоракка із силою будь-кого з менших лоа, з ким ти налагоди$p(в:ла) зв'язок.",
        progress = "Лоа й справді вельми щедрі.",
        completion = "Твій дух наливається силою!\n\nМожеш користуватися вівтарем так часто, як забажаєш. Та ти можеш утримувати на собі лише одне благословення водночас.",
    },
    [93801] = {
        title = "Виважене винищення",
        description = "Цей патоген стрімко поширюється серед мешканців Линьки.\n\nНевдовзі після нашого прибуття вилупився рій нетерос. Зараза розповзлася по всьому краю, поки вони билися за територію. Якщо їхнє число й далі зростатиме, вони можуть рознести патоген по решті Войдшторму.\n\n{name}, чи можу я попросити тебе зменшити кількість заражених істот у Линьці?",
        objectives = "Винищте створінь, властивих Линьці.",
        progress = "У цьому місці стільки життєвої сили. Не дивно, що патоген поширився так легко.",
        completion = "Твої зусилля й допомогу помічено та належно оцінено.",
    },
    [93810] = {
        title = "Сідало Володарів",
        description = "Не кожне створіння Порожнечі служить примхам Ксал'атат. Завоювання було нашим шляхом задовго до її приходу.\n\nНа півночі лежить Височина Вбивць — величезне бойовище, де троє доманаарів змагаються за владу. Та й твої союзники рен'дорей, кажуть, облаштувалися в Сідалі Володарів — головній цитаделі.\n\nБезсумнівно, там на тебе чекають великі битви. Рушай.",
        objectives = "Знайди союзників-ельфів Порожнечі на Сідалі Володарів.",
        completion = "Добре, нам потрібно більше вправних бійців.",
    },
    [93811] = {
        title = "Уславлений при Дворі Сільвермуну",
        description = "Народ Кел'таласу цінує твою незмінну підтримку. Коли загрози звідусіль, приємно знати, що нас захищають такі поборники, як ти.\n\nДвір бажає винагородити тебе за старання.",
        objectives = "Поговори з Каеріс Фейрдон у Притулку Салтеріла.",
        completion = "Сонячний Колодязь вистояв ще один день завдяки тобі. Іди з благословенням сін'дорей.",
    },
    [93816] = {
        title = "Зведення докупи",
        description = "Основи ти вже опанува$p(в:ла). Лишилося тільки самому випробувати Арканний Поширювач у справжньому матчі «Декор-дуелі»!\n\nЩо таке Арканний Поширювач, питаєш? Містична реліквія, виткана з ілюзій. Вона дозволяє гравцям маскуватися під подобою зачарованих предметів.\n\nДля навчання ми частково відтворили її за допомогою крісла, як ти бачи$p(в:ла), але оригінал значно кращий. То чому б не зіграти справжній матч просто зараз?",
        objectives = "Поговори з ткалею полів Амоленною, щоб розпочати поєдинок Декор-Дуелі, а тоді поговори з пропагандисткою Найсірою.",
        progress = "{NAME}? Ні, я не бачу твого імені в жодному списку гравців.\n\n\\Поговори з розпорядником гри Флер'яном, щоб долучитися до партії Дуелі декору.",
    },
    [93841] = {
        title = "Привиди Арени",
        description = "Я оце недавно був біля Арени Слави. Доводилося там бувати? Те місце аж кишить духами, і один із них добряче мене налякав! Підійшов упритул і спробував заговорити! Мені забракло сміливості лишитися й дізнатися, чого він хотів.\n\nА ти на вигляд не з полохливих, та й сили не позичати. Може, глянеш, що там коїться?",
        objectives = "Знайди Джа'бону біля Арени Слави.",
        completion = "Кого? А, згадав того жерця. Він так голосно верещав, коли я спробував заговорити з ним. Давно я так не сміявся.\n\nТи тут, щоб допомогти?",
    },
    [93842] = {
        title = "Цвітіння і згасання",
        description = "Мій час спливає, і я мушу спробувати врятувати мою кохану, Ешайє. Вона застрягла в петлі, і я хочу вирвати її з того кола, поки сам не розвіявся остаточно.\n\nКолись я вмів достукатися до неї букетами цвіту солодкопилки. Та тепер я не можу їх узяти в руки. Назбираєш трохи для мене?",
        objectives = "Назбирай 6 квіток солодкопилки довкола Арени Слави.",
        progress = "Здається, саме пахощі цвіту завжди повертали її до тями. Я вже не відчуваю запахів. Якщо й вона не відчуває — може, ніщо її вже не поверне.",
        completion = "Хіба ж не прекрасні?\n\n<Він нахиляється ближче, вдихає, але розчаровано зітхає.>\n\nЯ не чую їхнього запаху. Як би я хотів відчути його ще раз. Сподіваюся, Ешайє ще може.",
    },
    [93843] = {
        title = "Видобуток ектоплазми",
        description = "Нагорі, біля Арени Слави, є такі самі духи, як я, — торговці. Вони продають іншим духам усяку всячину, але колись я привернув увагу Ешайє напоєм від Маб'джула.\n\nТовари на ринку можна купити за ектоплазму, а її можна зібрати з розшарпаних духів довкола Арени. Особливо з культистів — вони крадуть її в інших.",
        objectives = "Збери 20 згустків ектоплазми.",
        progress = "Попервах ми просто блукали болотом: спантеличені, злі, зболені, перелякані. За багато тисяч років дехто навчився перетворювати ектоплазму, що лишається, коли іншого духа розшарпують. Ця валюта стала дуже жаданою.\n\nЗнищити духа тут остаточно неможливо. Зрештою він збереться знову, хоч на це йде дуже багато часу. А позаяк ніхто з нас не може піти далі, ектоплазма тут не переводиться, хоч добувати її й нелегко. Вдалося роздобути досить?",
        completion = "Добра робота. Ми на крок ближче до того, щоб вирвати Ешайє з петлі.",
    },
    [93849] = {
        title = "Ектоплазмова крамниця",
        description = "Ешайє точно зрадіє цим квітам! Тепер бракує лише примарного варива. Віднеси ектоплазму Маб'джулу й виміняй на пляшку примарного варива.\n\nЦе витримане вариво з зібраної ектоплазми, дуже освіжає. Часом воно навіть може притримати розшарпання.",
        objectives = "Принеси Ешайє букет і вариво.",
        progress = "Пам'ятаю, як уперше подарував їй квіти. Не думав, що така воїтелька вміє шарітися, — а вона зашарілася. Хоч би мені ніколи не забути її усмішки того дня.",
        completion = "Зрозуміло. Надто багато часу минуло, відколи я востаннє дарував їй квіти. Пам'ять про них — і про наші спільні дні — мабуть, давно згасла.",
    },
    [93850] = {
        title = "Шпиль Віндраннерів: примарні мелодії",
        description = "Стільки скорботи... Стільки болю. Вони прикували нас до цього місця.\n\nКолись його мелодії втішали нас, та нині їх заглушує гамір насильства.\n\nПрошу, допоможи нам. Іди за звуком ліри. Він сам приведе тебе.",
        objectives = "Заспокой неприкаяних духів усередині Шпиля Віндраннерів.",
        progress = "Прошу... допоможи нам.",
        completion = "Біль, страх... я відчуваю, як ця музика змиває все це геть.\n\nДякую, $p(друже:подруго).",
    },
    [93851] = {
        title = "Розмови з привидами",
        description = "Надії було небагато, але я мусив спробувати.\n\n<Він на мить замовкає і здригається — його обриси немов мерехтять по краях.>\n\nУ мене скінчилися ідеї, {NAME}. Розпитаєш тут довкола? Може, хтось із місцевих знає, як достукатися до Ешайє. Мене до них близько не підпускають, інакше я пішов би з тобою.",
        objectives = "Поговори з привидами довкола Арени Слави.",
        completion = "Викликати Ешайє на бій? Ну звісно! Як я сам не додумався?\n\nЕм... мабуть, тому, що мені її не здолати.",
    },
    [93852] = {
        title = "Загублений райдужний політокамінь",
        description = "Політокамінь мерехтить барвами всіх Аспектів. У його блискотливому сяйві перед тобою постають видіння: шляхетні драконові доми, зчеплені в битві проти Первісних Втілень. Люта какофонія ревіння, поки Тіньове Полум'я пожирає цілі краї землі. І заспокійливі звуки природи, поки розквітає світове дерево.\n\nЗависочілі небеса Валдраккена кличуть.",
        objectives = "Віднеси Загублений райдужний політокамінь Ксайдану у Валдраккені.",
        completion = "Реліквія минулих часів. Вона мерехтить сяйвом усіх драконових зграй — урочисте нагадування про красу й силу, що постають, коли ми разом.",
    },
    [93865] = {
        title = "Зроби собі ім'я",
        description = "Ми терпимо присутність таких, як ти, з однієї причини — через вашу готовність битися. Покажи нам майстерність смертних дуелянтів.\n\nІди, знайди інших свого роду. Яма внизу — ідеальне місце, щоб продемонструвати бойову вправність.",
        objectives = "Переможи в дуелі іншого гравця або Чемпіона Майстрів.",
        progress = "Іди. Покажи мені двобій.",
        completion = "Добре. Та одна перемога нічого не доводить. Шлях до зверхності потребує постійних вправ.\n\nПовертайся завтра й покажи свою майстерність ще раз.",
    },
    [93870] = {
        title = "Маскарад Ефемерона",
        description = "Звершення сьогодення стають оповідками сутінків!\n\nІ Шукачі, і ті, хто ховається, лишають свій слід завдяки захопливій грі та хитрому маневруванню.\n\nСонце осяює новий день, розбиваючи вчорашні ілюзії та видовжуючи сьогоднішні тіні. Ти готовий?\n\nОдягни маскування, споряди свій набір і покажи товаришам, що ніхто з тобою не зрівняється… в прямому розумінні!",
        objectives = "Поговори із ткалею полів Амоленною, щоб зіграти в «Двобій оздоб».",
        progress = "Твоє завдання досі не виконано, {NAME}.",
        completion = "О, чудова робота! Я спостерігала за тобою там, і це було вельми захопливо!",
    },
    [93877] = {
        title = "Умовні цілі — послідовні",
        description = "{name}! Радий тебе бачити. Захисникам у фортеці не завадила б твоя допомога.\n\nОдна з гномок збудувала робота, щоб допомогти боронити твердиню. Однак щоразу, коли його вмикають, він казиться.\n\nЇй потрібен хтось, хто зможе як слід зривати атаки робота, аби його можна було полагодити.\n\nЗнайдеться в тебе хвилинка, щоб допомогти?",
        objectives = "Активуй Бійцебота 11.2.7, а тоді 1 раз перервай його здібності своїм вартовим Скверни або гончаком Скверни.",
    },
    [93878] = {
        title = "Умовні цілі — кілька кроків, без послідовності",
        description = "{name}! Радий тебе бачити. Захисникам у фортеці не завадила б твоя допомога.\n\nОдна з гномок збудувала робота, щоб допомогти боронити твердиню. Однак щоразу, коли його вмикають, він казиться.\n\nЇй потрібен хтось, хто зможе як слід зривати атаки робота, аби його можна було полагодити.\n\nЗнайдеться в тебе хвилинка, щоб допомогти?",
