    [93897] = {
        title = "Додому на свята",
        description = "У твоєму районі святкові гуляння! Повертайся додому та поглянь на них.",
    },
    [93898] = {
        title = "Дім із привидами",
        description = "Я чув балачки про моторошні привиди й смачнючі ласощі, що з'являються по районах. Як випаде нагода, варто це розвідати.",
    },
    [93899] = {
        title = "Височина Вбивць",
        description = "Ми отримали повідомлення про загострення чвар між деякими доманаарами. Розслідуй битву на Височині Вбивць, а тоді доповіси Демінос Дарктранс на Сідало Володарів.",
        objectives = "Заверши бій на полі бою Височина Вбивць.",
        completion = "{NAME}, тобі вдалося пройти. Чудова робота.",
    },
    [93904] = {
        title = "Наперекір гравітації",
        description = "Тепер спускаймося. Енергія Порожнечі внизу не схожа на жодну, що мені доводилося відчувати, — немов сама гравітація кориться Порожнечі. Щойно ввійдеш до печери, її вплив охопить і тебе.\n\nКалґорґ уже повбивав тамтешніх істот і забрав їхню силу. Їхні жорстокі смерті лишили по собі якусь прокляту землю. Але ми мусимо йти далі й здобути силу, що там причаїлася. Наповни реліквіарій по вінця.\n\nНе знаю, чого чекати від мого блукача Порожнечі. Нам знадобиться вся сила, яку лише зможемо зібрати.",
        objectives = "Силу Порожнечі зібрано\nАктивуй гравітаційну аномалію, щоб піднятися вгору",
    },
    [93905] = {
        title = "Тривалий простій",
        description = "Колись Тіньова варта, може, і опиралася Ксал'атат, але тепер вони — частина її війська. Хай там що вони роблять із зібраною тут енергією, цьому треба покласти край.\n\nЗнищ їхніх солдатів, збирачів і машини. Я зроблю те саме — зустрінемося далі в глибині.",
        objectives = "Манакузню виведено з ладу\nМанатурель знищено",
    },
    [93906] = {
        title = "Звільнити обох",
        description = "Мені й на думку не спадало нападати на Ешайє. Я марнував час, силкуючись домогтися від неї розмови, не знаючи, як із нею говорити.\n\nЗробиш це для мене? Виклич Ешайє на бій і переможи її. Раптом це її розбудить? Я відчуваю, як прокидається надія.",
        objectives = "Допоможи Ешайє прийти до тями.",
        completion = "Дякую, що $p(вирвав:вирвала) мене з того кола, {NAME}. Усе, що я пам'ятала, — жага перемоги в день нашої загибелі. Я забула, за що билася: щоб повернутися до Джа'бону й життя, яке ми ділили.\n\nУперше за тисячі років я почуваюся цілісною. Хай що замкнуло нас тут, воно більше не втримає ні мене, ні Джа'бону. Тепер ми можемо рушити далі, до наступної пригоди, — разом.",
    },
    [93907] = {
        title = "Просвіта гідних",
        description = "Коли ти отримуєш новий набір Шукача, спершу він завжди досить скромний.\n\nАле під час гри ти зароблятимеш Ілюзорні монети й зможеш виміняти їх у розпорядника гри Флер'яна на розширені здібності й навіть додаткові набори!\n\nВізьми оці. Додай їх до зароблених і покажи свою торгову вправність.",
        progress = "Ті монети були одноразовим дарунком, {NAME}. Якщо вони кудись поділися або ж тебе спіткало лихо крадіжки, тоді, гадаю, доведеться взяти участь в іграх, щоб зібрати ще.",
    },
    [93909] = {
        title = "Опівніч: Глибини",
        description = "Багато хто наважувався спускатися в надра глибин, та мало хто повертався з чимось більшим, ніж пил і синці.\n\nВаліра Сангвінар виявила неабиякий інтерес до цих вилазок. Вона не лишає каменя на камені й має дивовижний хист потрапляти туди, куди іншим зась.\n\nРозшукай її та поглянь, яка удача чи небезпека чекає під поверхнею.",
        objectives = "Заверши 3 Глибини в Опівночі.",
        progress = "Пильнуй, {NAME}.",
        completion = "Виклик Глибин подолано, і сил у тебе лише додалося.\n\nВаліра мала рацію — нагода всміхається сміливим.",
    },
    [93910] = {
        title = "Опівніч: Здобич",
        description = "Сільвермун з усіх боків обступають загрози — як відомі, так і невідомі. Є ті, хто прагне вистежувати ці загрози й покласти край чварам і хаосу, які вони сіють.\n\nПоговори з магістром Асталором Кровоприсяжним у Завулку Убивць. Він спрямує тебе до найнагальніших загроз.",
        objectives = "Завершуй полювання на здобич для Асталора Кровоприсяжного в Сільвермуні.",
        completion = "Асталор служить справі Сільвермуна, хоч його шлях до мети рідко буває прямим.",
    },
    [93911] = {
        title = "Опівніч: Підземелля",
        description = "Підземелля Азероту таять у собі великі випробування й ще більші нагороди. У них лежать скарби, які можуть стати тобі в пригоді в майбутніх битвах, а також грізні вороги, яких треба здолати.\n\nУвійди в підземелля та поглянь, що тебе там чекає.",
        objectives = "Заверши будь-яке сезонне підземелля на звичайній складності або вищій.",
        progress = "Готуйся до всього. Удача часто йде пліч-о-пліч із небезпекою.",
        completion = "Твою мужність доведено ще раз. \n\nХай здобуті там перемоги зміцнять тебе перед тим, що попереду.",
    },
    [93912] = {
        title = "Опівніч: Рейд",
        description = "Збери своїх союзників — на тебе чекають великі випробування.\n\nНагороди величезні й можуть стати тобі в пригоді в прийдешніх битвах. Тобі й твоїм союзникам потрібно лише здолати невелику кількість цих жахливих ворогів.",
        objectives = "Здолай будь-яких 2 рейдових босів в Опівночі на будь-якій складності.",
        progress = "Тримайся, чемпіоне.",
        completion = "Темрява не зламала тебе — навпаки, лише загартувала.\n\nЧудова робота, {NAME}.",
    },
    [93913] = {
        title = "Опівніч: світовий бос",
        description = "Азеротом блукають могутні вороги, і їхня сила зростає з кожною новою битвою.\n\nЛише відвагою та єдністю ти здобудеш перемогу.",
        objectives = "Здолай світового боса в Опівночі.",
        progress = "Не вагайся, {NAME}.",
        completion = "Хай твої перемоги осявають шлях усім, хто йде слідом.",
    },
    [93922] = {
        title = "Вивільнене Єдине Зосередження",
        completion = "Єдине Зосередження стоїть за тобою у штурмі Шпиля Порожнечі. Ми краще за багатьох знаємо, що сьогодні тут поставлено на кін. Уся сила, яку ми можемо дарувати, — твоя; лиш візьми її.",
    },
    [93923] = {
        title = "Завзятість шул'ка",
        objectives = "Дивно, коли шул'ка просить про допомогу. Ще дивніше — цю допомогу отримати.",
