    [93924] = {
        title = "Невпинний похід",
        completion = "Ми мусимо відбити Темний Колодязь у сил Ксал'атат, поки все не поглинула Порожнеча. Ми віддамо тобі всю силу, яку зможемо, щоб підтримати тебе в прийдешній боротьбі. Не здавайся, чемпіоне!",
    },
    [93929] = {
        title = "Підсумок The War Within",
        description = "<До тебе потрапляє пергамент від невідомого відправника.>\n\n<У ньому йдеться про фоліант, який допоможе дізнатися про поточні події, і про те, як важливо зрозуміти загрозу, що насувається.>\n\n<Можливо, варто розшукати цей фоліант, коли будеш готовий дізнатися більше.>",
        objectives = "Загляни до Тому історії, щоб дізнатися про сагу «Війна Всередині».",
        completion = "<Фоліант ширяє перед тобою. Його сторінки сповнені знань про все, що відбулося.>",
    },
    [93930] = {
        title = "Світський успіх",
        description = "Ти прагнеш аудієнції в Салтеріла? І вбираєшся... отак? Даруй, хвилинку — посміюся в хустинку.\n\n<Каеріс тихенько сміється, прикрившись хустинкою.>\n\nА тепер — до справи. Тебе люб'язно запрошено на вечірку Салтеріла.\n\nНе осоромся, {name}. За тобою стежитиме весь цвіт Сільвермуна.",
        objectives = "Візьми участь у вечірці Салтеріла та наповни силою рунічні камені Лісу Вічної Пісні.",
        completion = "Мені вже ввижалося, як ти в сльозах тікаєш додому! Сподіваюся, вечір минув приголомшливо.",
    },
    [93931] = {
        title = "Удосталь багатства",
        description = "Лоа Рясності, може, й не належить до чотирьох великих, але його шанувальники — точно найвідданіші.\n\nНавідайся до нього особисто. Знайдеш його на півночі Зул'Аману, біля Храму Галаззі, та подейкують, що він улаштував місця жнив і в Лісі Вічної Пісні, і в Гарандарі, й навіть у краю Порожнечі — крізь велетенську пащу в небі.\n\nХай там як, нагороди він дарує славні... принаймні гідним.",
        objectives = "Пожни багатство для Лоа Рясності.",
        progress = "Ну шо, вдалося знайти лоа, гаш'ура?",
        completion = "Хе! То ви з Дундуном нарешті зустрілися.\n\nНавіть найменші з-поміж лоа бувають одними з найвеличніших!",
    },
    [93932] = {
        title = "Легендарне процвітання",
        description = "Гарандар ховає мудрість у кожній сторінці своєї історії, {name}. Варто самотужки розшукати його легенди. Підозрюю, ти дізнаєшся щось нове про цей світ і наше місце в ньому.",
        objectives = "Відкрий легенду гаранірів.",
        completion = "Цікаво, що ж показали тобі камені. Сподіваюся, це стало для тебе одкровенням, {NAME}. Але пам'ятай: завжди є чого вчитися ще.",
    },
    [93933] = {
        title = "Скарби під вартою",
        description = "Перебування в цьому світі подарувало рен'дорей ще глибше розуміння Порожнечі, ніж раніше. Доманаари, з якими в нас спільний ворог, діляться знаннями аж дивно щедро. Гадаю, вони хочуть, щоб ми стали такими ж грізними, як вони самі.\n\nУ цитаделі Штормаріон є Якір Сингулярності. Мені вдалося зрозуміти, як почерпнути частку його сили, щоб створити для тебе могутню річ.\n\nТа спершу слід подбати, щоб він не потрапив до рук наших ворогів.",
        objectives = "Захисти Якір Сингулярності в цитаделі Штормаріон.",
        progress = "Чи вдалося захистити якір від навали сил Порожнечі?",
        completion = "Чудова робота, {name}.",
    },
    [93934] = {
