    [93938] = {
        title = "Клятва руйнівника заклять",
        description = "Шукати приховане.\n     Знаходити невидиме.\nРозвіювати всі ілюзії\n     Й примарні мани.\n\nРуйнівники заклять розвіюють —\n     Уся правда постає.\nЖодна ілюзія не встоїть,\n     Жодна таємниця не сховається.",
    },
    [93939] = {
        title = "Клятва нищителя заклять",
        description = "Шукати приховане.\n     Знаходити невидиме.\nНищити ілюзії\n     Й примарні мани.\nНищителі заперечують —\n\n     Твої машкари зникають.\nЖодна ілюзія не лишається,\n     Жодна таємниця не вціліє.",
    },
    [93940] = {
        title = "Клятва арканного слідопита",
        description = "Шукати приховане.\n     Знаходити невидиме.\nПронизувати ілюзії\n     Й примарні мани.\n\n Слідопити розтинають і розплутують —\n     Машкари наскрізь видно.\nЖодна ілюзія тебе не сховає,\n     Жодна таємниця не встоїть.",
    },
    [93942] = {
        title = "Іскра Сяйва",
        description = "Видіння сяйва сповнює твій розум.\n\nМожливо, Елдара Доунраннер знає більше про ці Іскри Сяйва.",
        objectives = "Поговори з Елдарою Доунраннер у Сільвермуні.",
        completion = "Це Іскра Сяйва.\n\nЩотижня одна з таких іскор з'являтиметься в твоїх мандрах. У теперішньому стані вона радше марна, та зібравши більше, ти зможеш виготовляти могутні предмети. Реагенти на кшталт цих податливі, міцні й бажані для багатьох майстрів.\n\nЦе унікальний ремісничий матеріал, що допомагає предмету сягнути досконалості за межею смертних можливостей.",
    },
    [93943] = {
        title = "Стародавня дивовижа: бій",
        description = "<Ти береш дивовижу до рук і помічаєш, що від неї струмує мерехтливе сяйво. Здається, це щось важливе.>",
        objectives = "Використай бойову дивовижу та споряди нею свого супутника в Глибинах.",
    },
    [93944] = {
