    [94012] = {
        title = "Загублене пташеня яструбоступа",
        description = "Здоров, друзяко. Люди з оцієї крамнички улюбленців попросили мене помогти дати тут усьому лад. Та поки моя увага була деінде, пташеня яструбоступа, яке я доглядаю, вислизнуло за двері. Найгарніші фіолетові пера, які лиш можна уявити.\n\nЗробиш ласку — знайдеш його та приведеш назад? Час від часу я виводжу його на прогулянку в сад. Б'юся об заклад, саме там ти його й знайдеш.",
        objectives = "Злови Тіфа в Садах Спомину в Сільвермуні.",
        progress = "Ну шо, знайшлося пташеня?",
        completion = "Гарна робота. Навіть декому з тутешніх доглядачів не вдалося б вистежити ту хитрющу птаху.",
    },
    [94031] = {
        title = "Кістки моєї душі",
        description = "Маєш час, щоб зняти прокляття, {classv}?\n\nЯ — те, що лишилося від речника лоа Рала. Я тримав в'язнів у покорі на «Череві Рала». Але ми розбилися, я загинув, а в'язні повтікали.\n\nМої сили більше не діяли на живих. Зате діяли на капітана, який загинув разом зі мною.\n\nНажаханий тим, як він гнівається через мій провал, я влаштував ритуал, що ув'язнив його в кораблі, — на моїх власних кістках.\n\nЗа стільки часу моя душа всоталася в ті кістки, і тепер я не можу їх зрушити. Принесеш мені мої кістки?",
        objectives = "Позбирай кістки Іл'мула довкола уламків «Черева Рала».",
        progress = "Цей ритуал — дивна штука, якої навчив мене вчитель дуже-дуже давно.\n\nНіколи не думав, що доведеться проводити ритуали привидом, але я й уявити не міг, як розлютиться капітан.",
        completion = "Сила Рала, моя душа... усе знову тут. Дякую за повернені кістки, {NAME}.",
    },
    [94035] = {
        title = "М'ясо для кісток",
        description = "Щоб перенести душу з кісток у мене, потрібен ритуал.\n\nҐрал — лоа багато чого, але передусім моря. Він акула. І він любить м'ясо!\n\nДобудь м'ясо з морських істот у цих краях. Ритуал піде легше, коли заземлить мене щось червоне й сочисте.",
        objectives = "Збери 50 шматків м'яса морських істот біля уламків «Черева Рала».",
        progress = "Чимало речників лоа Рала використовують м'ясо у своїх ритуалах. Щоб перенести мою душу з кісток, м'яса треба багато. Але для тебе ж це дрібниці, правда, {classv}?",
        completion = "Чудово, чудово! М'яса тут вистачить на ці старі кістки.",
    },
    [94036] = {
        title = "Останній в'язень",
        description = "Не вдаватиму, що я бодай чимось кращий за капітана.\n\nМи обидва тішилися владою над в'язнями. Коли він зривався на них, я його не спиняв.\n\nАле за час, проведений тут у пастці разом, я передумав багато чого. Тієї ж миті, коли я перестав бути йому корисним, він розгнівався. І тепер я хочу покласти цьому край.\n\nЯ більше не потуратиму йому. Упокоїш його?",
        objectives = "Убий капітана Сал'чату в уламках «Черева Рала».",
        completion = "Одного з двох привидів, що живили це прокляття, розвіяно. Дякую тобі.",
    },
    [94040] = {
        title = "М'ясо, кістка й душа",
        description = "У нас є все потрібне для ритуалу.\n\nЗустрінь мене біля Зуба Сарґота. Допоможеш мені повернути душу цілою — і це прокляття нарешті скінчиться.\n\nХай Ґрал судить мене на тому боці за мої тутешні провали.",
        objectives = "Допоможи речникові лоа Іл'мулу завершити ритуал біля Зуба Сарґота.",
        completion = "Твоя поміч безцінна, {NAME}. Дякую.\n\nТепер усе це може скінчитися.",
    },
    [94052] = {
        title = "План доманаара",
        description = "Щоб здолати Зіадан, мені потрібна інформація.\n\nКарти, сувої зі стратегіями, бойові донесення — усе, що дасть мені перевагу!\n\nПрочеши Шпиль Ненависті й довколишні землі. Обшукуй кожну скриню та рубай вартових, щоб добути потрібні мені відомості.",
        objectives = "Увійди в Режим війни і збери 6 Бойових планів Зіадан зі скринь чи вбитих вартових.",
        progress = "Чи вдалося здобути бойові плани?",
