    [94408] = {
        title = "Контракт на службу",
        description = "Не честь і не слава женуть таких, як ти, на війну... а золото. І тобі, і твоїм ворогам завжди платять за кров, пролиту на полі бою.\n\nКожен ворог, якого ти вб'єш на Височині Вбивць, має при собі контракт від Зіадан. Принеси мені ці контракти, і я заплачу тобі стільки, скільки колись коштувала їй їхня вірність.",
        objectives = "Збери 10 контрактів на службу з убитих гравців у Режимі війни.",
        progress = "Ти з їхніми контрактами?",
        completion = "От бачиш — моя правда. Зрештою ціна крові завжди вимірюється золотом.",
    },
    [94409] = {
        title = "Контракт на службу",
        description = "Не честь і не слава женуть таких, як ти, на війну... а золото. І тобі, і твоїм ворогам завжди платять за кров, пролиту на полі бою.\n\nКожен ворог, якого ти вб'єш на Височині Вбивць, має при собі контракт від Відіуса. Принеси мені ці контракти, і я заплачу тобі стільки, скільки колись коштувала йому їхня вірність.",
        objectives = "Збери 10 контрактів на службу з убитих гравців у Режимі війни.",
