    [94415] = {
        title = "Сантехніка Порожнечі",
        objectives = "Ще одне завдання виконано. Трест дякує тобі за твої зусилля. Засновниця виділила фонд для заохочення такої ініціативи.",
        completion = "Ще одне завдання виконано. Трест дякує тобі за твої зусилля. Засновниця виділила фонд для заохочення такої ініціативи.",
    },
    [94416] = {
        title = "Технологія для дому",
        completion = "Ще одне завдання виконано. Трест дякує тобі за твої зусилля. Засновниця дозволила тобі, за бажання, забрати невеликий набір наших технологій до свого світу.",
    },
    [94417] = {
        title = "Герби світанку",
        description = "Наука сільвермунських майстрів пішла мені на користь: тепер ми з Кузолтом можемо наповнити твоє спорядження додатковою силою!\n\nЩоб розкрити повний потенціал могутнього спорядження, потрібні світанкові герби. Їх дають у нагороду за найрізноманітніші справи. Світанкові герби мають п'ять ступенів: що небезпечніше завдання, то вищий ступінь герба в нагороді. Світанкові герби шукача пригод — найнижчий ступінь, але й вони доволі сильні!\n\nПринеси мені тридцять світанкових гербів шукача пригод — і ми допоможемо тобі покращити спорядження ще більше.",
        objectives = "Здобудь 30 світанкових гербів шукача пригод, перемагаючи унікальних істот, виконуючи світові активності або забираючи здобич зі скриньок. Поговори з Кузолтом, щоб поліпшити предмет рівня шукача пригод за допомогою цих гербів, а тоді повернися до Васкарна в Сільвермуні.",
        progress = "Якщо світанкові герби шукача пригод трапляються тобі нечасто, пошукай приховані скарби в Лісі Вічної Пісні, Зул'Амані, Гарандарі та Войдштормі. Тих скарбів там не бракує!",
        completion = "Це чудово. Не дочекаюся, коли ти зростеш у силі!\n\nІ просуну мої дослідження, певна річ. Але так, твоя сила — мій найперший клопіт!",
    },
    [94418] = {
        title = "Трансмутація гербів",
        description = "А ти знаєш, що герби можна трансмутувати на інші рівні?\n\nЯкщо в тебе назбиралися герби, надто потужні для здобутого спорядження, я допоможу трансмутувати їх у нижчі рівні, які тобі згодяться.\n\nА коли все твоє спорядження стане достатньо потужним, я зможу перетворити зайві нижчі герби на вищі!\n\nНумо попрактикуємось у трансмутації. Ось кілька світанкових гербів ветерана. Звернися до мене — і я перетворю їх на світанкові герби шукача пригод.",
        objectives = "Принеси 10 ветеранських світанкових гербів Васкарну в Сільвермуні, потім обміняй їх на згорток світанкових гербів шукача пригод.",
        progress = "Якщо загубиш ці ветеранські світанкові герби, то здобудеш ще від могутніх істот по всьому Лісу Вічної Пісні, Зул'Амані, Гарандару та Войдшторму. Кажуть, їх там чимало різновидів!",
        completion = "Неймовірно!\n\nПам'ятай: я можу перетворювати герби на вищий ступінь лише тоді, коли ти переростеш їхню користь, і це буде недешевий процес. Дякую за всю твою допомогу, {NAME}!",
    },
    [94423] = {
        title = "Святилище під захистом",
        description = "Наш контроль тут — лише початок. Ксал'атат залишила по всьому краю й інші осередки аномалій. Захисні споруди, які ми тут розробили, можна використати, щоб убезпечити й ті місця.\n\nВирушай до Святилища Сонцевбивць та зведи п'ять додаткових захисних споруд, щоб зміцнити нашу владу над тим місцем.\n\nЯдро Штормаріону, потрібне для їхньої активації, я надам.",
        objectives = "Розгорни 3 захисні споруди біля Святилища Сонцевбивць.",
    },
    [94425] = {
        title = "Знекровити Шпиль",
        objectives = "Поговори з розвідником Адефусом\nЕлітні сили Шпиля Порожнечі знищено\nПілони призиву розтрощено\nПередні пілони завершено\nЗадні пілони завершено\nПравий пілон\nЛівий пілон",
    },
    [94430] = {
        title = "Спорядження шукача пригод",
        description = "{name}, ти саме вчасно! Я цілий день обмінююся дослідницькими нотатками з тутешніми майстрами Сільвермуна. Ти знаєш, що вони вміють насичувати зброю та обладунки силою самого світанку? Неймовірно!\n\nМені аж кортить випробувати декотрі з цих нових технік. Принеси мені предмет спорядження шукача пригод — і я скажу, що нам знадобиться, аби зробити його потужнішим.\n\nУ Сільвермуні й за його межами знайдеться чимало охочих винагородити тебе спорядженням шукача пригод в обмін на допомогу.",
        objectives = "Здобудь предмет спорядження шукача пригод, а тоді повернися до Васкарна в Сільвермуні.",
        completion = "Цей предмет спорядження підійде ідеально!\n\nЯ допоможу зробити його потужнішим, але нам знадобляться деякі реагенти.",
    },
    [94432] = {
        title = "Спорядження ветерана",
        description = "Ми лише починаємо розкривати справжній потенціал твого спорядження!\n\nПроте кожен предмет має межу покращення. Що потужніший предмет від самого початку, то потужнішим він стане після покращення. Гілка покращення предмета визначає, які герби нам для цього знадобляться.\n\nЦього разу принеси мені предмет спорядження ветерана разом із кількома світанковими гербами ветерана. Як і раніше, Кузолт допоможе тобі покращити предмет цими гербами.",
        objectives = "Здобудь предмет спорядження рівня ветерана та 20 ветеранських світанкових гербів. Поговори із Кузолтом, щоб удосконалити річ ветеранського рівня за допомогою цих гербів, а тоді повернися до Васкарна в Сільвермуні.",
        progress = "Якщо предмет спорядження ветерана ніяк не трапляється, спробуй пройти героїчне підземелля або складне тижневе випробування в Лісі Вічної Пісні, Зул'Амані, Гарандарі чи Войдштормі. Так можна знайти потужніше спорядження!",
        completion = "У тебе справжній хист! Схоже, ти вже даєш собі раду.\n\nЩоразу, коли захочеш удосконалити предмет спорядження, усе працюватиме так само. Принось нам річ і відповідні до неї герби, а Кузолт допоможе тобі її вдосконалити.",
    },
    [94444] = {
        title = "Обери шлях",
        description = "Вітаю. Я посол Чорна Варта.\n\nДля мене честь вітати тебе в Оґриммарі, {race}.\n\n<Він непереконливо усміхається.>\n\nПопереду в тебе ціле життя пригод, тож будь певен, що... е-е...\n\nЗнаєш що? Я цілий день повторюю одне й те саме привітання. З мене досить.\n\nПоговори з Хромі на вершині піщаного годинника, а тоді — зі своїм емісаром. Біжи вже.",
        objectives = "Поговори з Хромі в Оґриммарі.",
        progress = "Вітаю, {NAME}. Чи припав тобі Оґриммар до душі?",
        completion = "Неси свої традиції з гордістю, адже їхнє коріння переплелося в тобі.\n\nХай Ал'нгара благословить твій шлях.",
    },
    [94445] = {
        title = "Обери шлях",
        description = "Ласкаво просимо до Стормвінду, {race}. Запрошую тебе оглянути наше прекрасне місто. Гм, ти схожий на того, хто цінує простори природи! Елвінн чарівний цієї пори року.\n\nАх, та це може зачекати — бронзова драконка просила переговорити з тобою. Вона сидить під деревом неподалік, та ще й на піщаному годиннику!\n\nА після того тебе чекає твій емісар, щоб привітати в місті. Схоже, день у тебе буде клопіткий!\n\nПриємного перебування, {name}!",
        objectives = "Поговори з Кромі в Стормвінді.",
        completion = "Неси свої традиції з гордістю, адже їхнє коріння сплітається в тобі.\n\nНехай Ална'гара благословить твій шлях.",
    },
    [94446] = {
        title = "Кошмарне завдання",
        description = "Поки що чудова робота, {name}.\n\nАле роботи завжди не бракує.\n\nВирушай і полюй на найпотужніші цілі, які нам доступні, з усією люттю, на яку здатна наша магія.",
        objectives = "Заверши Кошмарні полювання у Здобичі.",
        completion = "Від тебе тхне стражданням.\n\nВишукано.",
    },
    [94447] = {
        title = "Офідія, Матір Виводку",
        description = "Заваді в безпеці, га? Добре. З нею не має статися нічого лихого. А нам треба розібратися з цими червами-переростками.\n\nОн там, біля берега, — одна з їхніх матерів виводку. Мерзенне створіння! Це через неї всі ці яйця довкола. Убий її. Їхнє вторгнення захлинеться, і мій народ матиме більше часу зібрати сили для удару.\n\nМені треба перев'язати рани. Я сховаюся й почекаю на тебе.",
        objectives = "Убий Офідію, матір виводку.",
        completion = "Може, Ва'кані й провалила це завдання, але вона правильно зробила, що послала тебе здолати ту несучку. Це відчутний удар по загарбницьких планах Дітей Ула'тек тут, у багні.\n\nПроте Ндаму та інші розвідники досі зниклі безвісти. Боюся, вони в лапах мурлоків.",
    },
    [94450] = {
        title = "Двадцять п'ять відсотків виконано",
        description = "Ми ще налаштовуємо систему винагород за ініціативи. Це тимчасове завдання, щоб надати тобі громадські купони.\n\nЗазвичай громадські купони здобувають, виконуючи завдання ініціатив, а не через таке завдання, як це.",
    },
