    [94622] = {
        title = "Покажи себе",
        description = "Випробування стилю дає нам нагоду показатися в найкращому вигляді, {class}.\n\nА камера подбає, щоб ми й надалі виглядали бездоганно.\n\nТож зосередься на мені та моїй камері, виконуй мої вказівки — і я зроблю так, що ти матимеш приголомшливий вигляд!",
        objectives = "Зосередься на фотографі й виконуй його вказівки.",
        progress = "Зосередься на мені й виконуй мої вказівки.\n\nЯ подбаю про твій чудовий вигляд.",
        completion = "Камера не бреше, {NAME}. \n\nТи — на диво стильний {class}.",
    },
    [94623] = {
        title = "Зведення Кузні Порожнечі",
        description = "Останнім часом я все міркую, як дати тобі більше сили, друже. Одна ідея в мене вже є, але щоб звести справжню Кузню Порожнечі, потрібна твоя допомога.\n\nЩо? О, не бійся: усі мої приховані мотиви й досі узгоджуються з твоєю справою. Поки що.\n\nДля початку мені потрібне одне Елементарне Ядро Порожнечі. Уламки знайдуться в могутніших ворогів, яких ти й так постійно зустрічаєш. Вчини своє звичне насильство, принеси уламки — і я знову сплету з них справжнє ядро Порожнечі, що стане основою кузні.",
        objectives = "Доставте уламки елементального ядра Порожнечі від босів рейду 1-го сезону Опівночі, щедрих Глибин і підземель Міфік+, щоб розпочати будівництво Кузні Порожнечі.",
        progress = "Уже назад, {NAME}? Є свіжі шрами?",
        completion = "Ах, новонароджена Кузня Порожнечі готова! О, чого тільки я... тобто ми зможемо з нею створити...",
    },
    [94625] = {
        title = "Елементарне Ядро Порожнечі",
        description = "Робота триває. Знайди досить уламків — і ми сплавимо їх назад в Елементарне Ядро Порожнечі.\n\nНаразі я маю реагентів на трансмутацію 0 ядер загалом. Новонародженій Кузні Порожнечі їх потрібно 6, щоб повністю сформуватися, а твій щедрий внесок поки що — 0.\n\nІди й дозволь собі ще трохи насильства, гаразд?",
        objectives = "Збери 3 уламки елементарного ядра Порожнечі з рейдових босів 1-го сезону Опівночі, Щедрих Глибин і міфічних+ підземель, щоб продовжити будівництво Кузні Порожнечі.\n\nКузня Порожнечі дасть доступ до туманних ядер Порожнечі, якими здобувають потужні предмети з рейдових босів, міфічних+ підземель, Щедрих Глибин і Кошмарної Здобичі.",
        progress = "Ти точно не поспішав із цим, {name}. Гадаю, брами часу не можна квапити, чи не так?",
        completion = "Чудово. Ще одне елементарне ядро Порожнечі для Кузні Порожнечі!",
    },
