    [95009] = {
        title = "На перегони",
        description = "Чув про сьогоднішні перегони?\n\nТисячі тролів збираються, щоб бігти до Сільвермуна на святкування!\n\nКалая розповіла б тобі більше. Вони саме готуються на Островах Відлуння!",
        objectives = "Поговори з Калаєю на Островах Відлуння.",
        completion = "Тобі тут раді, {class}.\n\nХоди святкувати з нами перегони. Такого не можна проґавити!",
    },
    [95012] = {
        title = "Біжи, ґноме",
        description = "Ти чув про сьогоднішні перегони?\n\nТисячі ґномів готуються пробігти від Нового Тінкертауна до Затоки Здобичі на честь свята!\n\nМіна Сміхозавіса розповість тобі більше. Ось-ось почнеться!",
    },
    [95021] = {
        title = "Здобич: Джаною Ікло (Жахіття)",
        description = "Ця істота зажила слави особливо лютими засідками. Отруєні ікла зблискують у темряві, тоді шалене борсання, а тоді... тиша. \n\nСпробуй дати їй скуштувати власної отрути.",
        objectives = "Вистеж Джаною Ікло і вбий їх.\n\nПоступ полювання зростає від виконання занять Здобичі, світових завдань, рідкісних істот і скарбів у вибраній тобою зоні.",
        completion = "А, воно билося до останнього, еге ж? Опиралося?\n\nДобре.",
    },
    [95022] = {
        title = "Здобич: Курсак Звивистий (Жахіття)",
        description = "Не підпускай цю зміїну потвору близько, {NAME}, бо з тебе видушить життя. Мої слуги нещодавно знайшли одну з її бідолашних жертв.\n\nНаче жменя розчавленого винограду...\n\nПерепрошую, я на мить забувся.",
        objectives = "Вистеж Курсака Звивистого і вбий.\n\nПоступ полювання дають заняття «Здобич», світові завдання, рідкісні вороги та скарби у вибраній тобі зоні.",
        completion = "Ти повернувся, не розчавлений!\n\nМені щось хочеться вина. А тобі?",
    },
    [95023] = {
        title = "Здобич: Батані Лускатий (Жахіття)",
        description = "Я чув, що в цієї істоти луска така товста й гостра, що нею можна філетувати рибу. Хай тебе не обманює її малий зріст, {NAME}, — її вивели з однією метою. \n\nУбивати. \n\nНа щастя, не бути вбит$p(им:ою) — це те, у чому ти добряче $p(наловчився:наловчилася).",
        objectives = "Вистеж Батані Лускатого і вбий.\n\nПоступ полювання дають заняття «Здобич», світові завдання, рідкісні вороги та скарби у вибраній тобі зоні.",
        completion = "Бачиш? Що я казав? Тебе зовсім не вбили. \n\nПринаймні... не так, щоб це мало значення.",
