    [95597] = {
        title = "Дрібничка Джан'алая",
        progress = "Як ся маєш, {NAME}?",
        completion = "Ще сонця, га? Значить, зможу попрацювати над засмагою.\n\nЖартую, жартую. Я вже й так досить засмаглий.",
    },
    [95673] = {
        title = "Підозріле полохання чайок",
        description = "Агов! Не допоможеш бідолашному тролю, якому геть не щастить?\n\nМені потрібно трохи пір'я з вашого Сусідства.\n\nДобряче налякай тутешніх птахів — вони злетять і розгублять пір'їни. Просто принеси їх сюди.",
        objectives = "Збери 25 Пташиних Пір'їн у своєму Сусідстві.",
        progress = "Ну як, є пір'я?",
        completion = "Ти просто золото, {NAME}.\n\nА то в мене вже закінчувалися запаси... панчіх. Я ж роблю... шкарпетки з... пір'я?\n\nАга, пір'яні шкарпетки. І нічого більше.",
    },
    [95768] = {
        title = "Мій товар кращий за твій",
        description = "Привіт, {NAME}.\n\nУ мене тут ятка: торгую товарами нашого Сусідства з новими друзями, і все розлітається, як гарячі пиріжки!\n\nТа не завадило б перепочити. Наглянеш за яткою замість мене? Якщо підійдуть покупці, просто запропонуй їм те, що вважаєш за найкраще.",
        objectives = "Продай ідеальний товар 6 гостям-амані у своєму Сусідстві.",
        completion = "Щиро дякую! Далі я вже впораюся. У тебе чудово вийшло!",
    },
    [95779] = {
        title = "Миті в кухлі",
        description = "Чоловік, який знається на випивці, заслуговує на найкращий трунок. Я маю дещо на думці для свого друга Флінна.\n\nСкладники, які мені потрібні, — у броварні моєї родини в Долині Чотирьох Вітрів. Я б сходив сам, але броварник має також знати, коли сісти, віддихатися і оцінити те, що в кухлі.\n\nСходиш до Броварні Штормстаутів і принесеш мені ті складники, друже?",
        objectives = "Вирушай до Долини Чотирьох Вітрів і увійди в Броварню Штормстаутів. Усередині здобудь 6 складників. За бажанням здобудь також Ліхтар Броварні Штормстаутів.",
        progress = "Ти зміг дістати складники?",
        completion = "Виглядають як дуже якісні складники. Ти, мабуть, дещо тямиш у броварстві!\n\nДякую, друже. Я зварю досить і для тебе, якщо захочеш скуштувати!",
    },
    [95804] = {
        title = "Діти Ула'тек",
        description = "Ці тортоллани що, заблукали? І давно вони тут?\n\nБіля святилища Філо є ціле їхнє поселення, але тут — не місце для них.\n\nЩе недавно я просто прогнала б їх. Але останнім часом чужинці приносять нам удачу.\n\n<Обличчям Зул'джарри пробігає тінь усмішки — уперше на твоїй пам'яті відтоді, як повернувся Малакрасс.>\n\nТреба поговорити з ними. Може, вони знають, як усе це почалося.",
        objectives = "Розпитай капітана Токку, що він бачив на Пристані Токки.",
        completion = "Зул'джан...\n\nНавіщо ти це зробив, брате?",
    },
    [95815] = {
        title = "Крижаний спуск",
        objectives = "Прокотися на крижаній брилі\nКрижану брилу докочено до цілі",
    },
    [95842] = {
        title = "Опівніч: Штурми Порожнечі",
        description = "У ці буремні часи нас тиснуть і сили Порожнечі, і давні вороги. Ми маємо лишатися пильними й не дати закріпитися жодному угрупованню.\n\nТи мусиш покласти край цим штурмам Порожнечі! Будь насторожі: наші розвідники доповідають, що деякі угруповання можуть використовувати дрібніші напади, щоб підготувати велике вторгнення.\n\nЯкщо так, я знаю, що ти допоможеш із обороною.",
        objectives = "Проходь Штурми Порожнечі та Вторгнення Порожнечі в «Опівночі».",
        completion = "Дякую, {class}: наших ворогів знову зупинено. З такими захисниками, як ти, ми не зазнаємо поразки.",
    },
    [95843] = {
        title = "Опівніч: Місця ритуалів",
        description = "Чимало ворогів прагнули за допомогою темних ритуалів насилати на нас жахіття. Далекоходи завжди були на висоті й давали їм раду.\n\nОскільки наші сили під неабияким тиском, я мушу попросити тебе взятися за це доручення. Є небезпечні місця ритуалів, які треба зірвати.\n\nНаші вороги, найпевніше, спробують знову, тож тобі доведеться бути впертим і щоразу зривати їхні наміри.",
        objectives = "Заверши Місця ритуалів в Опівночі.",
        completion = "Ці Місця ритуалів — ще одна загроза, з якою нам тепер доводиться мати справу. Твоя пильність у захисті наших земель не лишається непоміченою, і ми в боргу перед тобою.",
    },
    [95933] = {
        title = "Сліди в темряві",
        description = "$p(Чемпіоне:Чемпіонко), Клинок Розлому Маелла хоче знову з тобою поговорити.\n\nТемні частки, які ти нам приносиш, зібрані тобою відомості про наших ворогів і незліченні перемоги, здобуті тобою для Кель'Таласу, не лишилися непоміченими.\n\nСхоже, у Маелли є план. Знайди її, щойно зможеш.",
        objectives = "Поговори з Клинком Розлому Маеллою в Сільвермуні.",
        progress = "Твої зусилля проти цих загроз Порожнечі та ефіріалів знову виявилися неоціненними. Але наша робота ще не завершена.",
        completion = "Наразі продовжуй захищати Ліс Вічної Пісні та Зул'Аман.\n\nЦі загрози — чи то Порожнеча, чи ефіріали, чи щось інше — навряд чи просто здадуться й заберуться геть.\n\nГроми їх за кожної нагоди, поки я збираю союзників і готую наш наступний крок.\n\nЯ зв'яжуся з тобою свого часу.",
    },
    [95954] = {
        title = "Прадавній ворог",
        description = "Ти чудово даєш собі раду, {NAME}, та над храмом і досі лежить тінь — верховний жрець Джин'тал.\n\nЗа життя він був жерцем особливо запеклим і шанолюбним, тож мене не дивує, що він зумів утриматися й у нежитті. Я відчуваю: він і далі сповідує свою мерзенну віру в Покійницькій неподалік.\n\nПрошу, {NAME}. Покінчи з ним. Я допоможу, чим зможу.",
        objectives = "Увійди до Сховища Неспокійних Кісток і здолай верховного жерця Джин'тала.",
        completion = "Присутність верховного жерця розвіялася — принаймні наразі. Чи зможе він знову набути форми, ще невідомо.\n\nАле якщо так — ми будемо напоготові.",
    },
    [96000] = {
        title = "Прогулянка на ялику",
        objectives = "Піднімися на борт ялика\nВійська переможено з гармати\nЗнаряддя знищено з гармати",
