    [96525] = {
        title = "Здобич: Нам не до снаги",
        description = "Це вже понад мої сили. \n\nЯ відкрию портал назад до Святилища.\n\nА сам почекаю, поки ці кляті зміюки від мене втомляться, і тоді піду слідом. Замов за мене слівце, будь ласка.",
        objectives = "Повернися до Асталора Бладсворна в Сільвермун.",
        completion = "Від тебе тхне страхом і відчаєм.\n\nЗахопливо.",
    },
    [96528] = {
        title = "Здобич: Мука з потойбіччя",
        description = "{NAME}! Я спробував тихцем утекти від тих змій, але одна заповзла мені в холошу, і я на трохи знепритомнів.\n\nОтямився вже тут...\n\nЦікаво, чи є тут щось, що зацікавило б магістра Асталора. \n\nЧекай... що це? Оте світіння...\n\nСхоже, твій кристал відгукується на щось у цій гробниці!",
        objectives = "Досліди прокляту гробницю для служителя святилища Етрандила.",
        completion = "Оце так купа кісток!",
    },
    [96532] = {
        title = "Здобич: Служба служителеві",
        description = "Дехто, можливо, вважає мої методи жорстокими й химерними, але я щиро дбаю про добробут тих, хто мені служить. \n\nПереважно.\n\nСлужитель Етрандил служив нашій справі гідно. Будь ласка, перекажи йому, що він може повертатися до мене.\n\nЦя підлога останнім часом помітно забруднилася...",
        objectives = "Провідай служителя святилища Етрандила на Звивистому Острові.",
        completion = "Ти жив$p(ий:а)! Я живий! \n\nПоки що.",
    },
    [96534] = {
        title = "Готуємось до загроз",
        description = "Мій брат завжди був творчою натурою, його руки вічно зайняті якимось хитромудрим побічним проєктом чи пристроєм, над яким він працює.\n\nЙого запал стане великою підмогою цій операції, надто коли йдеться про відсіч загрозам, з якими ми стикаємось у цьому світі.\n\nПоглянь, над чим він трудиться, і випробуй один із його нових експериментів.\n\nПевен, він буде в захваті від нагоди прислужитися.",
        objectives = "Придбай бинти ефіріалів у Кіфаана.",
        progress = "Я цілком певна, що його робота дасть раду тим прикрощам, які час від часу траплятимуться тобі в цьому світі.",
        completion = "Він неабиякий маленький техномант, чи не так?\n\nВін пройшов довгий шлях від часів, коли ми блукали техноринками вдома. \n\nЙого витвори добряче допоможуть тобі в тутешніх справах.\n\nНам пощастило, що він із нами в цій експедиції. Мені пощастило, що він у мене є...\n\nМинуло дуже багато часу, відколи ми востаннє стільки бували разом.",
    },
    [96535] = {
        title = "Пережити спори",
