    [96536] = {
        title = "Витримати хуртовину",
        description = "<У цій хуртовині й справді люто холодно.\n\nМабуть, хтось у таборі підкаже, як послабити її дію.>",
    },
    [96538] = {
        title = "Здолати хуртовину",
        description = "Я певен, ми багато чим можемо зарадити твоїй біді.\n\nДесь там напевно розкидано вдосталь старих демонічних артефактів.\n\nПошукай скверножарини й принеси мені кілька жмень.",
    },
    [96539] = {
        title = "Остання надія",
        description = "Давним-давно було собі село, що потерпало від великої посухи. Врожай не родив, земля пересохла. Усе село голодувало! І прийшли селяни до однієї тролихи — Джейти — просити про послугу.\n\nУ цій оповіді Джейта — це ти. Іди ж і дізнайся, чого хочуть ті голодні селяни!",
        objectives = "Поговори з голодними селянами й дізнайся, чого вони хочуть.",
        completion = "Вона вирушила в дорогу, як її просили, аж раптом — ой! Що ж то попереду на шляху?",
    },
    [96540] = {
        title = "Сильні руки",
        description = "На стежці Джейта натрапила на лиса, якого обсіли рисі. А була вона добра, безстрашна й сильна — тож вирішила тому лисові допомогти.\n\nІди ж і скажи тим рисям забиратися геть!",
        objectives = "Прожени рисей від Хитрого лиса.",
        completion = "Оце так! Схоже, той лис — не просто собі звичайний лис, га?",
    },
    [96541] = {
        title = "Сильний розум",
        description = "Той старий хитрий лис був не абиякий лис! Він говорив, він біг — і він чекав, щоб Джейта прийшла до нього. То чого ж йому було треба від Джейти?\n\nПоговори з ним і дізнайся!",
        objectives = "Дізнайся, чого хоче Хитрий лис.",
        completion = "Ти диви — знову там, звідки все почалося, і всі живі! Джейта була настільки ж кмітлива, наскільки й сильна!",
    },
    [96543] = {
        title = "Корінь виживання",
        description = "Повернувшись туди, звідки вирушила, Джейта знала: тієї подорожі їй не подужати. Але як же голодні селяни? Як їм вижити?\n\nУ Джейти було кілька задумів... якщо тільки селяни її послухають. Іди дізнайся, що вона скаже!",
        objectives = "Назбирай усохлих коренів і м'яса звірят для села.",
        progress = "Благаємо, Джейто! Не дай нашому селу померти з голоду!",
        completion = "Це небагато, але на цьому ми напевно протримаємось. Дякуємо за твою мудрість, Джейто!",
    },
    [96544] = {
        title = "Хоробрість у вогні",
        description = "Минали роки, а того третього дару вона так і не вживала. Одного року зграя розлючених драконояструбів накинула оком — і полум'ям — на село. Її син опинився в пастці, а їхня домівка палала!\n\n«Можна б ужити мій дар, — подумала Джейта. — Та нащо здався дар, коли є моя сила?»\n\nІди покажи тим драконояструбам свою силу і врятуй хлопця!",
        objectives = "Убий 7 розлючених драконояструбів і врятуй Тего.",
        completion = "Фух! Для Джейти — буденна справа. А третій дар усе ще був при ній!",
    },
    [96545] = {
        title = "Сильний голос",
        description = "Спливали роки, а третього дару Джейта все не вживала. Одного року до села прийшла ватага наскочників, що надумали вкрасти все до нитки.\n\n«Можна б ужити той третій дар, — подумала Джейта. — Та нащо здався дар, коли є мій голос?»\n\nІди вгамуй тих наскочників словом, а як не слухатимуть — скористайся силою і зміни їхню думку!",
        objectives = "Вгамуй 10 розгніваних наскочників.",
        completion = "Джейта була мудра й мовила щиро — і її голос погамував тих наскочників там, де удари були б безсилі.",
    },
    [96546] = {
        title = "Сильне серце",
        description = "Минали роки, і Джейта відчула, що надходить її час. Вона прожила довге життя — сповнене боротьби, та все ж щасливе. Але коли Джейта дійшла до краю своїх днів, з'явився той старий хитрий лис.\n\n«Стривай! — сказав він. — Тобі ще не можна йти!»\n\nІ чого ж тому лисові треба? Піди поговори з ним і дізнайся!",
