    [96612] = {
        title = "Прадавня дивовижа: Бій",
        description = "<Ти тримаєш дивовижу і помічаєш, що від неї йде мерехтливе сяйво. Схоже, це щось важливе.>",
        objectives = "Скористайся Бойовою Дивовижею і споряди її своєму супутникові в глибинах.",
        completion = "Твоє розуміння дивовиж поглибилося.",
    },
    [96614] = {
        title = "Виковане у вогні",
        completion = "Кажуть, благословення давно забутого фенікса просочується в кожен помах молота й кожен подих полум'я цього горна.\n\nОсь чому всі, хто серйозно ставиться до свого ремесла, з'їжджаються звідусіль кувати свої творіння саме тут. А втім, можливо, уся ця сила — лише забобон. Спосіб династії Сонстрайдерів дати силу безсилим. А знов-таки — може, і ні.\n\nСпробуй і ти, гаразд?",
    },
    [96615] = {
        title = "Прадавня дивовижа: Ужиткова",
        description = "<Ти тримаєш дивовижу і помічаєш, що від неї йде мерехтливе сяйво. Схоже, це щось важливе.>",
