    [97215] = {
        title = "Другий удар",
        description = "Ми завдали ворогам відчутного удару. Та вони не припиняють своїх нападів.\n\nДецимус і мої вартові розломів взяли на приціл ще один світ, з якого вони запускають ці атаки.\n\nОсновні наші сили тимчасово відійшли до Войдшторму, щоб ми могли розпочати наступ на цей другий світ.\n\nУдарний загін чекає на нас біля Виючого Хребта.",
        objectives = "Зустрінься з Клинком Розлому Маеллою у Войдштормі.",
        completion = "Кожен із наших ворогів заклав собі твердиню на окремому світі, змушуючи нас розпорошувати увагу.\n\nЯкщо ми хочемо по-справжньому розгромити їхні сили, треба вдарити по обох твердинях і зміцнити наші точки входу.\n\nНу що, прориваємося крізь іще один розлом?",
    },
    [97256] = {
        title = "Знести верхівку (героїчний)",
        description = "Навіть найбезжальніші істоти здригаються, коли бачать, як їхні найславетніші чемпіони розсипаються на попіл.\n\nНагадай тутешнім ворогам, як швидко падають їхні ватажки!\n\nХай знають, які ж ви насправді невблаганні й люті, монстри Азероту! Принеси мені Емблеми Командира Порожнечі — і я гідно тебе винагороджу.",
        objectives = "Збери 4 Емблеми Командира Порожнечі з Капітана Нексуса Лет'іра або Імператора Пертінакса в героїчному світовому рівні Валу та Найґталю.",
        progress = "Ти вже впоралася?",
        completion = "Диявольськи, як завжди. Такі, як ти, знову й знову нагадують мені, чому мій вибір упав саме на вас. \n\nЯк винагороду я маю кілька роздобутих речей, які можуть стати тобі в пригоді в наших майбутніх справах. Твоїм союзникам про це знати не обов'язково.",
    },
    [97321] = {
        title = "Слизька здобич",
        description = "Маю добру новину й погану.\n\nПогана — усі ті дивовижі, які ми разом викопали? Розплавилися.\n\nДобра новина? Я знайшла кілька дуже цікавих нових отрут для роботи.\n\nАле дай пояснити, що сталося...",
        objectives = "Послухай історію Валіри.",
        progress = "Що думаєш?",
        completion = "Це була помилка новачка, але все було не марно.",
    },
    [97382] = {
        title = "Винагорода за відсіч прокляттю",
        description = "Кожен клаптик цього острова проклятий, {NAME}. Коли прокляття Ула'тек згущується в бій — саме тоді найважливіше дати відсіч. Нам стане в пригоді будь-яка допомога, аби тримати його на припоні.\n\nТи на вигляд $p(сильний:сильна)... але щоб вижити, тобі знадобиться краще спорядження.\n\nЗдолай ватажка одного з цих сплесків — і тоді обговоримо винагороду.",
        objectives = "Здолай сплеск прокляття.",
        completion = "Це мало б стати цим зміям наукою, та щось не віриться, що вона піде їм до серця.",
    },
    [97383] = {
        title = "Корозія духу",
        description = "Наші розвідники знайшли цю реліквію в одній із крипт. Може, Ер'іньє знає, що з нею робити?",
        objectives = "Принеси Їдку Реліквію до Ер'іньє у Сховищах Атал'Утек.",
        progress = "Що це в тебе там?",
        completion = "Ця реліквія стара й могутня. Я можу перенести корозію на твій дух.",
    },
    [97454] = {
        title = "Сезонне оновлення: Опівніч",
        description = "Відколи відкрилися Звивисті Острови, у глибинах знову стало цікаво.\n\nПодивися, чи мають наші любі господарі щось для тих із нас, хто справді ризикує шиєю, і перевір Довідник Глибинника на оновлення.\n\nШвидке освіження ще нікому не завадило.",
        objectives = "Переглянь Довідник Глибинника і купи сезонні припаси в Налейдеї Ріверґлім і телеманта Астрандіса.",
        completion = "Чудово, хоча відтоді, як ми востаннє говорили, з'явилися... новини.",
    },
    [97457] = {
        title = "Пасує як рукавичка",
        description = "<Схоже, це пара великих кистьових кісток, які хтось видовбав і оголосив рукавицями.\n\nДобре, що ти вже носиш рукавиці, інакше кортіло б їх приміряти.\n\nСлаґґс, певно, щось знає про цю річ.>",
        objectives = "Зустрінься з другою помічницею Слаґґс у Безумі Токки.",
        completion = "Я... гадаю, вони могли б помагати інтендантові тягати рибу?",
    },
    [97482] = {
        title = "Ікла на згадку",
        description = "Та зміїна почвара була люта, з отрутою, достатньо міцною, щоб пропалювати камінь.\n\nМи маємо роздобути найкраще спорядження, яке зможемо, перш ніж думати про сутичку з нею.\n\nВтім, у мене є ідеї, як обернути ту отруту на нашу користь, щоб ми могли одразу взятися до справи.",
        objectives = "Вдосконалюй спорядження, доки не зможеш стати проти Азта'река в його лігві.",
    },
    [97557] = {
        title = "Хвостом за тлгапі",
        description = "Отруйні тлгапі. Паскудна дрібна риба.\n\nУ них усе не так — від великих вирячкуватих очей до солодкого соковитого м'яса...\n\n<Ґіллс прокашлюється.>\n\nНе кажучи вже про токсичність. Морям було б значно краще без того, щоб вони їх псували.",
        objectives = "Принеси 13 Отруйних Тлгапі Розсолопивцю Ґіллсу.",
        progress = "Пхе. Треба було ще й лайм попросити.",
        completion = "О так, їм буде значно краще серед команди, ніж у відкритому океані.\n\nПідозрюю, капітан Токка буде задоволений.",
    },
    [97562] = {
        title = "Прорідити коропозубок",
        description = "Плямиста коропозубка. Гидотні дрібні створіння.\n\nЦі малі демони рояться, наче комахи, і викидаються на береги в таких жахливих кількостях, що з'їсти їх усіх — то кілька трапез.\n\n<У животі Ґіллса чутно бурчить.>\n\nТи можеш зробити свій внесок, наловивши мені трохи і позбавивши води їхньої мерзенної присутності.",
        objectives = "Принеси 13 Плямистих Коропозубок Розсолопивцю Ґіллсу.",
        progress = "Пхе. Треба було ще й свіжомеленого зандаларського перцю попросити.",
        completion = "О так, тут їх цінуватимуть значно більше, ніж якби вони плавали в морі.\n\nПідозрюю, капітан Токка буде задоволений.",
    },
    [97571] = {
        title = "Полювання на метунів",
        description = "Брудні метуни. Моторошні дрібні падлюки.\n\nТе, як вони шмигають у воді, так бентежить, так тривожить, що мимоволі уявляєш, як котрийсь шугає тобі просто в горлянку...\n\n<Ґіллз доволі гучно кашляє>\n\nДолучися до справи: назбирай їх для мене і звільни води від їхньої мерзенної присутності.",
        objectives = "Принеси 13 брудних метунів Розсолопияку Ґіллзу.",
        progress = "Гм. Треба було попросити китового масла.",
        completion = "О так, команда швидко дасть раду цим вертлявим бісенятам.\n\nПідозрюю, капітан Токка буде задоволений.",
    },
    [97616] = {
        title = "Їдкі дари: Їдка сила",
        description = "<Ти відчуваєш зміну в повітрі, коли береш цей прадавній том до рук.\n\nХоч він і коле й пече шкіру, твій розум палає думками про силу, яку він містить, і небезпеку, яку становить.\n\nТи мусиш дізнатися більше.\n\nНа острові є лише одне місце, досить нечестиве для цього тому. Внутрішнім зором ти бачиш Вівтар Корозії.>",
        objectives = "Принеси Кодекс Душезвіїв до Вівтаря Корозії у Сховищах Атал'Утек.",
        completion = "То ти, виходить, $p(знайшов:знайшла) шлях до сили корозії без старої Ер'іньє, га?\n\n<Ер'іньє пирхає.>\n\nНу-ну. Побачиш, чого це тобі коштуватиме.",
    },
    [97624] = {
        title = "Пошук легенд",
        description = "Гарандар ховає мудрість у кожному літописі своєї історії, {NAME}. Тобі варто самому шукати його легенди. Підозрюю, ти дізнаєшся дещо про цей світ і про наше місце в ньому.",
        objectives = "Відкрий легенду гаранірів.",
        completion = "Цікаво, що ж показало тобі каміння. Сподіваюся, це було повчально, {NAME}. Але пам'ятай: завжди є чого ще навчитися.",
    },
    [97625] = {
        title = "Славетна Рясність",
        description = "Лоа Рясності, може, й не належить до чотирьох великих, зате його шанувальники — безперечно найвідданіші.\n\nПошукай його $p(сам:сама). Знайдеш його на півночі Зул'Аману, біля храму Галаззі; та, кажуть, він улаштував місця збору і в Лісі Вічної Пісні, і в Гарандарі, і навіть у краю Порожнечі — туди веде велетенська небесна паща.\n\nХай там як, а дари він дає славетні... принаймні гідним.",
        objectives = "Збери багатство для лоа Рясності.",
        completion = "Хе! То ти нарешті зустрів Дундуна.\n\nНавіть найменші бувають одними з найвеличніших серед лоа!",
    },
    [97640] = {
        title = "Сховища Атал'Утек: Одна зайва монета",
        description = "Кепський у тебе вигляд, {NAME}.\n\n<Поки Абдумати похмуро оглядає тебе, твоє серце починає гупати, а в очах зеленіє. Вага монети в кишені здається нестерпною.>\n\nЩось там $p(знайшов:знайшла), еге ж? Сховища повні скарбів, і більшість із них прокляті.\n\nЯ їй не довіряю, але та відьма-дух, яку ти $p(бачив:бачила), знає всі таємниці цього моторошного місця. Якщо хтось і може зарадити, то це вона.",
        objectives = "Знайди Ер'іньє.",
        completion = "Коли їдкі монети почнуть тягнути тебе донизу — приходь до мене.",
    },
    [97661] = {
        title = "Захист Мед'джаїв",
        description = "<Цей амулет здається теплим і гладеньким у руці.\n\nПоки ти його тримаєш, відчуваєш полегшення від тягаря своєї корозії, наче амулет дає якийсь захист від прокляття Ула'тек.\n\nЕр'іньє, певно, буде цікаво його вивчити.>",
        objectives = "Принеси Амулет Мед'джаїв до Ер'іньє.",
        completion = "Це мене дивує. Ніщо в цих проклятих сховищах не дивувало мене вже давно.",
    },
    [97662] = {
        title = "Вітри Ток'джари",
        description = "<Коли твоя рука стискає це крихке перо, крізь сховища відлунює примарний вітер.\n\nІз ним ти відчуваєш, як тягар корозії твого духу спадає, наче ти міг би просто розправити крила й вилетіти з цього проклятого місця.\n\nЗвісно, не міг би. Але Ер'іньє, певно, буде цікаво його вивчити.>",
        objectives = "Принеси Перо Ток'джари до Ер'іньє.",
        completion = "Пхе. У цих сховищах криються сили, про які навіть я не знаю.",
    },
    [97668] = {
        title = "Пильний погляд Сзаріт",
        description = "<Стискаючи зміїне око, ти відчуваєш, як потилицею повзе нове усвідомлення.\n\nЯйця Ула'тек. Сотнями. Ти відчуваєш кожну їхню сіпку присутність, що чекає, аби вибухнути мерзенною отрутою і новим її бридким поріддям.\n\nТи хотів би жбурнути його в найглибшу крипту, але його сила незаперечно потужна. Ер'іньє буде цікаво його вивчити.>",
        objectives = "Принеси Око Сзаріт до Ер'іньє.",
        completion = "<Ер'іньє посміюється.>\n\nТи приніс це аж сюди, бо думав, що мені буде цікаво? Що ж, мені цікаво.",
    },
    [97669] = {
        title = "Щастя зв'язаного духа",
        description = "<Ти тримаєш просту рисячу лапу, потерту часом і тривогою, яку дух лишив як прощальний дарунок.\n\nХоч вона й не має власних магічних властивостей, вона набрякла надіями й страхами кожного зв'язаного духа, що перетнув її шлях у цьому жалюгідному місці.\n\nРезультат доволі потужний, хоч і емоційно виснажливий. Ер'іньє, певно, буде цікаво її вивчити.>",
        objectives = "Принеси Рисячу Лапу до Ер'іньє.",
        completion = "Тьху. Мені це не подобається, хоч я й не можу заперечити його сили.",
    },
    [97670] = {
        title = "Жменя мергелю світла Порожнечі",
        completion = "Зул'джарра винагороджує вірних і щирих. Дякую, гаш'ура.",
    },
    [97910] = {
        title = "Тріснутий ключ",
        description = "Коли ти торкаєшся каменя, у твоїй свідомості спалахують уривки образів героїчних діянь, але вони згасають так само швидко, як з'явилися.\n\nМожливо, якесь достатньо вражаюче звершення знову втихомирить магію каменя?",
        objectives = "Пройди будь-яке підземелля на міфічній складності 2 або вище.",
        completion = "Оповіді про твої власні звершення вплітаються в хор відлунь, що струменять із полагодженого каменя.",
    },
    [97945] = {
        title = "У Тіні Каталізатора",
        description = "А, {NAME}! Добре. Тепер, коли ти допоміг мені зібрати такий статок ресурсів, час мені взятися за інші... інтереси.\n\nЩо? Ти чекав драматичнішої зради? Нізащо!\n\nНе хвилюйся, {NAME}: хай я й буду зайнятий деінде, та ніколи не втомлюся стежити за твоїми пригодами.\n\nПригодами, які, звісно ж, і далі підживлюють мої дари. Багато хто виявляв цікавість, але я знайшов лише одного ельфа Порожнечі... досить кумедно дивного, щоб узяти в науку.\n\nЗвати його Орін Стрейлайт. Знайдеш його біля Каталізатора в Сільвермуні.",
        objectives = "Поговори з Оріном Стрейлайтом у Сільвермуні.",
        completion = "А, то ти говорив із Децимусом? Схоже, тепер ми самі по собі. Час братися до справи.",
    },
    [97978] = {
        title = "Призматичний потенціал",
        description = "Вітаю, шамане. Наш спільний друг усе нам пояснив. Не хвилюйся: ми з моєю тінню взялися до Децимусового ткання Порожнечі, як риба до води.\n\nУ нас виникла думка. Перетворювальні енергії Каталізатора величезні й охоплюють увесь спектр відомих сил стихій.\n\nЯкщо я навчуся виокремлювати з того спектра Порожнечу, то зможу ткати нею Туманні ядра Порожнечі — так само, як Децимус робив це Кузнею Порожнечі.\n\nПравда, ми не доманари. Нам потрібна практика.",
        objectives = "Збери 10 Елементарних уламків ядра Порожнечі з рейдових босів 2-го сезону Опівночі, Щедрих глибин, міфічних+ підземель і кошмарних полювань «Здобич», щоб допомогти Орінові в його дослідженні Каталізатора.\n\nКаталізатор відкриє доступ до додаткових Туманних ядер Порожнечі, якими здобувають могутні предмети з рейдових босів, міфічних+ підземель, Щедрих глибин і кошмарної «Здобичі».",
        progress = "Маєш ті Елементарні уламки ядра Порожнечі?",
        completion = "Сподіваюся, ці Елементарні уламки ядра Порожнечі дісталися тобі не надто важко. Тепер, коли вони в нас є, я можу вести далі своє дослідження потенціалу Порожнечі в силі Каталізатора. Це забере час, тож зазирни до мене згодом.",
    },
    [98172] = {
        title = "Слідами Ксал'атат",
        description = "Ми не повинні втрачати з очей нашу справжню мету тут, у Сільвермуні, {NAME}: притягнути Ксал'атат до відповідальності.\n\nМи всі бачили її армії Порожнечі біля Сонячного Колодязя. Вони линули вниз, УГЛИБ колодязя, тисячами щохвилини. А тепер — тиша.\n\nПрислухайся до їхніх шепотів, {classv}. Як пощастить, ми знову натрапимо на їхній слід, а тоді знайдемо Ксал'атат... а може, навіть тих, хто гнався за нею.",
        objectives = "Збери 100 згаслих шепотів Порожнечі.\n\nЦі рештки Порожнечі можна здобути в підземеллях, Глибинах, зі скарбів та з інших небезпечних істот.",
        progress = "Кожен затихлий шепіт — це крок ближче до нашої справжньої здобичі.",
        completion = "Наше полювання далеко не скінчене.\n\nТримай вуха й очі відкритими, {NAME}.",
    },
    [98204] = {
        title = "Проклята Пам'ятка",
        description = "<Стримувальний щит гуде, щільно огортаючи пам'ятку. Від предмета віє аурою скорботи і страждання.\n\nЗа словами Останнього Архітектора, ця пам'ятка проклята, але її можна очистити. Треба лише згорнути свою сутність усередину сутності предмета й вилучити заразу зсередини. Ну що тут може бути небезпечного?>",
        objectives = "Очисти пам'ятку, вилучивши з неї заразу.",
        progress = "Щоб вилучити заразу з проклятої пам'ятки напряму, треба увійти в неї й стати до бою з відлуннями травми, що її переслідує. Видобуту заразу можна знищити.",
        completion = "Пам'ятку очищено! Вона готова до нового дому, де творитимуться кращі спогади.",
    },
    [98218] = {
        title = "Повернення до Амані'Зару",
        description = "{NAME},\n\nтвоєї допомоги потребують у селищі Амані'Зар. Прошу, зустрінься зі мною там.\n\n--Ліадрін",
