    [98226] = {
        title = "Отруйна Безодня: Оманливість викрито",
        description = "Якщо мій брат більше не схиляється перед Малакрассом, то він у великій небезпеці. Нам треба знайти спосіб дістатися до них якнайшвидше. Шукай будь-що, що дасть нам змогу пройти храм швидше.",
        objectives = "Збери 3 Уламки Маски в Отруйній Безодні на звичайній складності.",
    },
    [98232] = {
        title = "Опівніч: Сховища Атал'Утек",
        description = "Сили Зул'джарри стоять на варті біля брам Сховищ Атал'Утек, тримаючи стрій проти тих лихих зміїв.\n\nДоля всіх Східних королівств лежить на їхніх клинках. Нам варто дати їм підкріплення. Діти Ула'тек люті, але вони не рівня досвідченому шаманові, як ти.\n\nПройди храм і прорідь їхні лави, як зможеш.",
        objectives = "Виконуй Храмові Удари, Вторгнення і здолай Прадавніх Ворогів у Сховищах Атал'Утек.",
        completion = "Це має трохи зменшити їхню кількість — принаймні на якийсь час.",
    },
    [98343] = {
        title = "Отруйна риболовля: Моя друга найкраща",
        description = "Перш ніж я пошлю тебе на лови, годиться познайомитися з тим, що лишилося від моєї команди.\n\nБільшість, звісно, загинула в кораблетрощі. Інших поглинуло болото. А декотрі зрадливі поганці... ну, до них ми ще дійдемо, еге ж?\n\nАле моя вірна друга помічниця тримає оборону трохи нижче за течією від моєї Пристані. Вона тебе споряде як слід.",
        objectives = "Зустрінься з другою помічницею Слаґґс у Безумі Токки.",
        completion = "Ой, тебе прислав капітан? Що ж, хіба не п-приємна несподіванка.",
    },
    [98388] = {
        title = "У Сховища Атал'Утек",
        description = "За цим валом немає нічого, крім змій, духів та отруйної смерті.\n\nЦього тижня ми втратили трьох лейтенантів. Сильних. Хоробрих. Може, сильніших і хоробріших за тебе.\n\n<Мок'са Камінь окидає тебе втомленим оком.>\n\nХочеш кинутися в безодню — прошу дуже. Приведи назад розвідників, якщо знайдеш їх серед кісток.\n\nАле пильнуй, куди ступаєш. Та отрута проковтне тебе цілком.",
        objectives = "Дізнайся, що сталося з Наз'арою Хороброю, Сочо Соколиним Оком і командиром Ґазбою.",
        progress = "Не змушуй мене посилати когось тобі на порятунок. У мене нема для цього бійців.",
        completion = "Що ж... двоє з трьох — непогано, як для тутешніх країв.\n\nЩоправда, ти щось $p(позеленів:позеленіла)... Точно $p(певен:певна), що отрута тебе не дістала?",
    },
    [98406] = {
        title = "Дібраний дарунок",
        completion = "Я бачу, скільки зусиль і турботи ти віддаєш іншим смертним свого Сусідства. Ця невтомна праця заради них — саме та поведінка, яку я заохочую. Зиску тобі з неї жодного, але найкращими з вашого роду рухає не це.\n\nНа знак визнання твоїх заслуг і становища пропоную тобі дарунок. У цьому невеличкому пристрої — предмет декору, який ти зможеш розмістити у своєму домі. Наступного тижня матиму для тебе ще один.",
    },
    [98414] = {
        title = "Прохання капітана",
        description = "Ой, е-е. Капітан просив, щоб ти якомога швидше $p(приєднався:приєдналася) до нього на Пристані Токки.\n\n<Друга помічниця Слаґґс тремтить у своєму панцирі.>\n\nВигляд у нього був лихий. Ступай обережно.",
        objectives = "Зустрінься з капітаном Токкою на Пристані Токки.",
        completion = "Шукаєш іще роботи? З тебе минулого разу була така поміч.",
    },
    [98415] = {
        title = "Послуга капітанові",
        description = "О! Поки ти рибалив, капітан Токка попросив побачити тебе знову. Гадаю, він починає тобі довіряти.\n\n<Другий помічник Слаґґс кривиться.>\n\nД-довіра Капітана таки має свої застереження.",
        objectives = "Зустрінься з капітаном Токкою на Пристані Токки.",
        completion = "У мене є для тебе ще одне завдання. Кожне жахливіше за попереднє, га?",
    },
    [98419] = {
        title = "Пліч-о-пліч",
        description = "Сховища — небезпечне місце. Чимало хоробрих, свавільних бійців гадає, що здолає Дітей Ула'тек наодинці. Як пощастить, ми встигаємо забрати тіла, перш ніж їх з'їдять.\n\nТи мені до вподоби, {NAME}. Було б шкода побачити, як змія згодовує тебе своєму виводкові. Тож будь розумний. Знайди тих, хто прикриє тобі спину, і прорубуйтеся крізь храм разом.",
        objectives = "Збери загін з іншими гравцями і вбивай ворогів у Сховищах Атал'Утек.",
        completion = "Пліч-о-пліч. Ось як ми виграємо цю битву.",
    },
    [98420] = {
        title = "Що там, назовні?",
        description = "Знання — найважливіша зброя на війні. Ці Сховища прадавні й величезні — наші розвідники не можуть бачити все. Що чаїться в глибинах цих опоганених залів?\n\nСаме це мені й треба знати. Іди туди й розкажи мені, що побачиш, але йти самому небезпечно. Краще візьми побратимів, якщо хочеш повернутися.",
        objectives = "Збери загін з іншими гравцями і розвідай Сховища Атал'Утек.",
        completion = "Почвари тут гадають, що можуть чаїтися й плести змови в темряві. Ми викорінимо їх і вичистимо з цих земель.",
    },
    [98428] = {
        title = "Сховища Атал'Утек: Вівтар Корозії",
        description = "Вівтар Корозії.\n\nХто скаже, коли цей проклятий камінь здійнявся з отрути? Я вивчала його цілі життя — і лише щойно розкуштувала його силу.\n\n<Ер'іньє облизує свої примарні вуста.>\n\nЛише скажи — і я перетворю корозію, яку ти носиш, на щось корисніше. Тоді зможеш поєднатися з Вівтарем і прийняти його щедрі дари.",
        objectives = "Поговори з Ер'іньє, щоб роз'їсти свій дух, а тоді поєднайся з Вівтарем Корозії.",
        completion = "Ну, як воно? Неземно? Розкішно?\n\nЯ багато чого віддала б, аби знову скуштувати це вперше.",
    },
    [98515] = {
        title = "Сховища Атал'Утек: Отруйна екскурсія",
        description = "Саме в цьому храмі всі Діти Ула'тек уперше виповзають зі слизу. І саме тут ми тримаємо оборону.\n\nЗагроза йде хвилями. Часом це короткі удари. Часом — вторгнення, що затоплює весь храм. А часом з отрути здіймається величезне чудовисько.\n\nХай що вони пришлють — відправ його назад у сльозах до великої злої матусі!\n\nА тим часом роби все можливе, щоб уберегти наші патрулі.",
        objectives = "Заверши Патруль, Удар і Вторгнення та здолай Прадавнього ворога у Сховищах Атал'Утек.",
        completion = "Ти вже вловлюєш ритм цього жахливого місця, га?\n\nЗмії виповзають з отруйної ями, а ми жбурляємо їх назад.",
    },
}
